In order to define the solution of FBSDEs we introduce the following spaces.
\begin{itemize}
	\item $\bL_{\cF}^2(\bR^d)$ is the space of all $\cF$-measurable random variables $X: \Omega \to \bR^d$ satisfying
	\begin{equation*}
	\| X \|^2:=\bE \left[ \big \vert X \big \vert^2\right]< \infty;
	\end{equation*}
	\item $\bH_{[0,T]}^2(\bR^d)$ is the space of all predictable processes $\phi:\Omega\times [0,T] \to \bR^d$ satisfying
	\begin{equation*}
		\| \phi \|^2_{\bH^2}:= \bE \left[ \int_0^T \vert \phi_t \vert^2\textnormal{d}t\right]< \infty;	
	\end{equation*}
	\item $\bH_{[0,T],N}^2(\bR)$ is the space of all predictable processes $\phi:\Omega\times [0,T]\times \bR^d \to \bR$ satisfying
	\begin{equation*}
		\| \phi \|^2_{\bH^2_N}:= \bE \left[ \int_0^T \int_{\bR^d}\vert \phi_t(z) \vert^2 \nu(\textnormal{d}z)\textnormal{d}t\right]< \infty;
	\end{equation*}
	\item $\bS_{[0,T]}^2(\bR^d)$ is the space of all $\bF$-adapted c\`{a}dl\`{a}g processes $\phi:\Omega \times [0,T] \to \bR^d$ satisfying
	\begin{equation*}
		\|\phi \|_{\bS^2}^2:=\bE \left[ \sup_{t \in [0,T]} \big \vert  \phi_t \big \vert ^2\right]< \infty.
	\end{equation*}
\end{itemize}
For $t \in [0,T]$ and $x \in \bR^d,$ we consider the following FBSDE defined by
\begin{align} \label{eq:SDE}
	X_s^{t,x}=x + \int_t^s b(X_{r-}^{t,x}) \textnormal{d}r + \int_t^s \sigma(X_{r-}^{t,x} )^{\top} \textnormal{d}W_r + \int_t^s \int_{\mathbb{R}^d} \Gamma (X_{r-}^{t,x},z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z), \quad s \in [t,T],\end{align}
and 
\begin{align} \label{eq:BSDE}
Y_{  {s}}^{t,x}&=g(X_T^{t,x})+\int_{  {s}}^T f\left(r,X_{r-}^{t,x}, Y_{r-}^{t,x}, Z_r^{t,x}, \int_{\mathbb{R}^d} U_r^{t,x}(z) \nu (\textnormal{d}z) \right)\textnormal{d}r - \int_{  {s}}^T (Z_r^{t,x})^{\top}\textnormal{d}W_r  \nonumber \\
	& \quad - \int_{  {s}}^T \int_{\mathbb{R}^d} U_r^{t,x}(z) \widetilde{N} (\textnormal{d}r,\textnormal{d}z), \quad {s \in [t,T].}
\end{align}
Throughout the paper we make us of the following assumptions.
\begin{assumption} \label{assump:ExistenceUniquenessFBSDE} The following holds:
\begin{enumerate}
\item[\textbf{(A1)}] 
\begin{enumerate}
	\item The vector fields $b: \bR^d \to \bR^d, \sigma:\bR^d \to \bR^{d \times d}$ are measurable functions which are Lipschitz continuous with Lipschitz constants $K_b$ and $K_{\sigma}$, respectively.
	\item The vector field $ \Gamma: \bR^d \times \bR^d \to \bR^d$ is measurable and satisfies for some constant $K_{\Gamma} >0$
	 \begin{align*}
	 	\int_{\vert z \vert <1} \big \vert \Gamma(x,z)-\Gamma(x',z) \big \vert^2\nu(\textnormal{d}z)& \leq K_{\Gamma}  \vert x-x'  \vert^2, \\
	 	\int_{\vert z \vert <1} \big \vert \Gamma(x,z) \big \vert^2\nu(\textnormal{d}z) &\leq K_{\Gamma} ( 1+ \vert x  \vert^2 ).
	 	\end{align*}
	 \item The function $f:[0,T] \times \bR^d \times \bR \times \bR^d \times \bR^d \to \bR$ is Lipschitz continuous with respect to the state variables, uniformly in $t$, i.e. there exists $K_f >0$ such that
	  \begin{align*}
 	 \big \vert f(t,x,y,z,u)-f(t,x',y',z',u') \big \vert \leq K_f \big(\big \vert  x-x' \big \vert + \big \vert  y-y' \big \vert +\big \vert  z-z' \big \vert + \big \vert  u-u' \big \vert\big) 
 	\end{align*}
 	for all $(t,x,y,z,u), (t,x',y',z',u') \in [0,T] \times \bR^d \times \bR \times \bR^d \times \bR^d$.
	\item The function $g: \bR^d \to \bR$ is Lipschitz continuous with Lipschitz constant $K_g$. 
\end{enumerate}
\vspace{5pt}
\item [\textbf{(A2)}]
\begin{enumerate}
 \item The function $f:[0,T] \times \bR^d \times \bR \times \bR^d \times \bR \to \bR$ is $\frac{1}{2}$-H\"{o}lder continuous with respect to $t$ and constant $K_{f,t}.$
 \item For each $z\in \mathbb{R}^d$ the mapping $x \mapsto \Gamma(x,z)$ admits a Jacobian matrix $\nabla_x \Gamma (\cdot,z)$ such that the function $a(\cdot, \cdot;z): \mathbb{R}^d \times \mathbb{R}^d \to \bR$ defined by
 \begin{equation} \label{eq:AssumpGammaErrorEstiamte1}
a(x,\xi;z):=\xi^{\top}\left( \nabla_x \Gamma(x,z)+ \textnormal{I}_{d\times d}\right)\xi
 \end{equation}
satisfies one of the following conditions uniformly in $(x,\xi) \in \bR^d \times \bR^d$
\begin{equation} \label{eq:AssumpGammaErrorEstiamte2}	
a(x,\xi;z) \geq \vert \xi \vert^2 C^{-1} \quad \textnormal{or} \quad a(x,\xi;z) \leq -\vert \xi\vert^2 C^{-1}.
\end{equation}
\end{enumerate}
\item [\textbf{(A3)}] 
	Let the function $\Gamma: \bR^d \times \bR^d \to \bR^d$ be of the form
	\begin{equation} \label{eq:Gamma}
		\Gamma(x,z):=\gamma(x)z,
	\end{equation}
	for some Lipschitz continuous function $\gamma: \bR^d \to \bR^{d \times d}$ with Lipschitz constant $K_{\gamma}$.
\end{enumerate}
\end{assumption}
