In particular, Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)} guarantees the existence of a unique solution \linebreak $(X^{t,x}, Y^{t,x}, Z^{t,x}, U^{t,x}) \in \bS_{[0,T]}^2(\bR^d) \times \bS_{[0,T]}^2(\bR) \times \bH_{[0,T]}^2(\bR^d) \times \bH_{[0,T],N}^2(\bR) $ to the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE}, see Theorem 4.1.3 in \cite{delong} and Theorem 6.2.9 in \cite{applebaum}.
\begin{theorem}
	Under Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)} there exists a unique solution \linebreak $(X^{t,x}, Y^{t,x}, Z^{t,x}, U^{t,x}) \in \bS_{[0,T]}^2(\bR^d) \times \bS_{[0,T]}^2(\bR) \times \bH_{[0,T]}^2(\bR^d) \times \bH_{[0,T],N}^2(\bR) $ to the FBSDE \eqref{eq:SDE}-\eqref{eq:BSDE}.
\end{theorem}
Moreover, it is well-known that there exists a link of the solution to the FBSDE \eqref{eq:SDE}-\eqref{eq:BSDE} to the solution $u:[0,T] \times \mathbb{R}^d \to \mathbb{R}$ of the following PIDE
\begin{align}
 -u_t(t, x)-\mathscr{L} u(t, x) -f\left(t, x, u(t, x), D_x u(t, x) \sigma(x), \mathscr{J} u(t, x)\right)&=0, \quad \quad(t, x) \in[0, T) \times \mathbb{R}^d, \label{eq:PIDE1}\\
 u(T, x)&=g(x), \quad x \in \mathbb{R}^d, \label{eq:PIDE2}
\end{align}
where 
\begin{align}
\mathscr{L} u(t, x)= & \left\langle {b}(x), D_x u(t, x)\right\rangle+\frac{1}{2}\left\langle\sigma(x) D_x^2 u(t, x), \sigma(x)\right\rangle \nonumber  \\
& +\int_{\mathbb{R}^d}\left(u(t, x+\Gamma(x, z))-u(t, x)-\left\langle\Gamma(x, z), D_x u(t, x)\right\rangle\right) \nu(d z),  \label{eq:PIDE3 }\\
\mathscr{J} u(t, x)= & \int_{\mathbb{R}^d}(u(t, x+\Gamma(x, z))-u(t, x)) \nu(d z) . \nonumber 
\end{align}
From now on, by saying that a generic constant $C\in \mathbb R$ only depends on the data of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE}, we mean that $C$ only depends on $b, \sigma, \Gamma, f, g, {t}, T, x$ and, wether finite,  on $\nu(\mathbb{R}^d)$.

By combining Proposition 4.1.1, Lemma 4.1.1 and Theorem 4.2.1 and Lemma 4.1.1 in \cite{delong} we get the following result.
\begin{theorem} \label{theorem:LinkPIDE}
Let Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)} hold and denote by $X^{t,x} \in \bS_{[0,T]}^2(\bR^d)$ the unique solution to the SDE \eqref{eq:SDE}-\eqref{eq:BSDE}. 
If $u \in C^{1,2}([0,T] \times \mathbb{R}^d, \mathbb{R})$ satisfies the PIDE \eqref{eq:PIDE1}-\eqref{eq:PIDE2} and there exists a constant $K>0$ such that  
\begin{align} \label{eq:EstimatesRegularityPIDE}
\vert u(t,x) \vert \leq K(1+ \vert x \vert), \quad \vert D_xu(t,x) \vert \leq K (1+ \vert x \vert), \quad \text{for } (t,x) \in [0,T] \times \mathbb{R}^d,
\end{align}
then $(Y^{t,x}, Z^{t,x}, U^{t,x})$ defined by
\begin{align}
    Y_s&=u\left(s,X_s^{t,x}\right), \quad  s \in [t,T], \label{eq:RelationY}  \\
Z_s^{t, x} & =\sigma(X_{s-}^{t, x})^{\top} D_x u(s, X_{s-}^{t, x}), \quad s \in [t,T], \nonumber  \\
U_s^{t, x}(z) & =u(s, X_{s-}^{t, x}+\Gamma(X_{s-}^{t, x}, z))-u(s, X_{s-}^{t, x}), \quad s \in [t,T], \, z \in \mathbb{R}^d,\label{eq:RelationU} 
\end{align}
is the unique solution to the BSDE \eqref{eq:BSDE}. 
Moreover, for some constant $C>0$ only depending on the data of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE}, $u$ satisfies
\begin{equation} \label{eq:LocallyHoelder}
\vert u(t,x)-u(t',x')\vert^2 \leq C \left( \vert x-x' \vert^2 + \left( 1+ \vert x {\vee} x' \vert^2 \right) \vert t-t' \vert \right), \quad \text{for }(t,x), (t',x') \in [0,T]\times \mathbb{R}^d.
\end{equation}
%\end{enumerate}
\end{theorem}
From now on, we assume that the PIDE in \eqref{eq:PIDE1}-\eqref{eq:PIDE2} has a solution $u\in C^{1,2}([0,T] \times \mathbb{R}^d, \mathbb{R})$ which satisfies \eqref{eq:EstimatesRegularityPIDE} and which is $\frac{1}{2}$-H\"older continuous with respect to time.
\begin{remark}
For examples of PIDEs which are relevant in financial applications and allow for a $C^{1,2}$-solution satisfying \eqref{eq:EstimatesRegularityPIDE} we refer to Proposition 2 in \cite{cont_voltchkova} and references therein.
\end{remark}
Theorem \ref{theorem:LinkPIDE} motivates the following stochastic optimal control problem 
\begin{align} \label{eq:StochastiOptimalControl}
&\begin{aligned}
& \underset{y \in \mathbb{R}, \,  Z \in \mathbb{H}_T^2\left(\mathbb{R}^d\right), \, U \in \mathbb{H}_{[0,T], N}^2(\mathbb{R})}{\operatorname{minimise}} \quad \mathbb{E}\left[\left(g\left(X_T^{t, x}\right)-Y_T^{y, Z, U}\right)^2\right] \nonumber
\end{aligned}\\
&\text { subject to: }\\
&\begin{cases}
X_s^{t, x}&=x+\int_t^s b(X_{r-}^{t, x}) \textnormal{d} r+\int_t^s \sigma(X_{r-}^{t, x})^{\top} \textnormal{d} W_r+\int_t^s \int_{\mathbb{R}^d} \Gamma(X_{r-}^{t, x}, z) \widetilde{N}(\textnormal{d} r, \textnormal{d} z) \nonumber \\
Y_s^{y, Z, U}&= y-\int_t^s f\left(r, X_{r-}^{t,x}, Y_{r-}^{y,Z,U}, Z_r, \int_{\mathbb{R}^d} U_r(z) \nu(\textnormal{d} z)\right) \textnormal{d} r+\int_t^s\left(Z_r\right)^{\top} \textnormal{d} W_r \\
& \quad +\int_t^s \int_{\mathbb{R}^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z),  \quad s \in[t, T] .
\end{cases}
\end{align}
In particular, under Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)} the minimum in problem \eqref{eq:StochastiOptimalControl} is achieved and the corresponding minimizer $(y^*,Z^*, U^*)$ is the unique solution to the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE}, see Lemma 2.6 in \cite{gnoatto_patacc_picarelli}. Then, Theorem \ref{theorem:LinkPIDE} provides the theoretical foundation for the algorithm  we present in the next subsection.
\subsection{The extension of the deep BSDE solver in \cite{ehanjen17} to the case with jumps}
{Using the stochastic optimal control problem in \eqref{eq:StochastiOptimalControl} the idea for the algorithm is to discretize the FBSDE and approximate at each time step the control processes by families of artificial neural networks. The goal is to minimize the loss function in \eqref{eq:StochastiOptimalControl} by fitting the parameters of the neural networks. While this approach is frequently used in the case without jumps, see e.g. \cite{ehanjen17}, the difficulty with jumps is to develop an algorithm which is also able to deal with a forward process $X$ with infinitely many jumps of finite or infinite variation. To overcome this problem the following procedure is used. \\
In a first step an algorithm for the finite activity case is developed. In a second step the forward process $X$ is approximated by a jump diffusion $X^{\epsilon}$ with finitely many jumps, which allows to make use of the already existing algorithm for the finite activity case. The approximation of the forward process relies here on results in \cite{asmussen_rosinski_2001}, \cite{cohen_rosinski_2007} and \cite{jum_2015}.
\\  Before presenting the algorithms for the finite and infinite activity case in details, we introduce the architecture of the underlying artificial neural networks we employ.}\\
{
We use feedforward ANNs with $\mathcal{L}+1 \in \mathbb{N} \backslash\{1,2\}$ layers, with each layer consisting of $v_{\ell}$ nodes or neurons, for $\ell=0, \ldots, \mathcal{L}$. The $0$-th layer is called the input layer, while the $\mathcal{L}$-th layer represents the output layer. The remaining $\mathcal{L}-1$ layers are termed hidden layers. For simplicity, we set $v_{\ell}=v, \ell=1, \ldots, \mathcal{L}-1$. The dimension of the input layer is equal to $d$, which equals the dimension of the forward process $X$.
A feedforward neural network is a function defined via the composition
$$
x \in \mathbb{R}^d \longmapsto \mathcal{A}_{\mathcal{L}} \circ \varrho \circ \mathcal{A}_{\mathcal{L}-1} \circ \ldots \circ \varrho \circ \mathcal{A}_1(x),
$$
where all $\mathcal{A}_{\ell}, \ell=1, \ldots, \mathcal{L}$, are linear transformations of the form $\mathcal{A}_{\ell}(x):=\mathcal{W}_{\ell} x+\beta_{\ell}, \ell=1, \ldots, \mathcal{L}$, where $\mathcal{W}_{\ell}$ and $\beta_{\ell}$ are matrices and vectors of suitable size called, respectively, weights and biases. The activation function $\varrho$ is a univariate function $\varrho: \mathbb{R} \mapsto \mathbb{R}$ that is applied componentwise to vectors. With an abuse of notation, we denote $\varrho\left(x_1, \ldots, x_v\right)=\left(\varrho\left(x_1\right), \ldots, \varrho\left(x_v\right)\right)$. The elements of $\mathcal{W}_{\ell}$ and $\beta_{\ell}$ are the parameters of the neural network. One can regroup all parameters in a vector of size $R:=\sum_{\ell=0}^{\mathcal{L}} v_{\ell}\left(1+v_{\ell}\right)$.} 

\section{A posteriori estimates}\label{sec:aPosterioriEstimates}

\subsection{A posteriori error estimate for the finite activity case} \label{sec:LiteratureSchemesFBSDEsJumps}
{The goal of this section is to present the algorithm  to approximate the solution of the  FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} for the finite activity case and provide an a posteriori error estimate. Thus,} we work under the following assumption in this section.
 \begin{assumption} \label{assump:FiniteActivity}
	The L\'evy measure satisfies $K_{\nu}:=\nu(\bR^d)< \infty$. 
\end{assumption}
Furthermore, we assume that Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A3)} holds from now on. For fixed $M \in \mathbb{N}$ we consider the uniform time discretization $0 \leq t = t_0<t_1<...<t_M=T$ with time step $\Delta t= t_{n+1}-t_n$ for $n=0,...,M-1$.
Next, we introduce a neural network $\cU_n^{\rho_n}: \mathbb{R}^d \to \mathbb{R}^d, n=0,...,M-1,$ parametrized by  $\rho=(\rho_0,...,\rho_{M-1}) \in (\mathbb{R}^R)^M$ and indexed by the time discretization $n \in \lbrace 0,...,M-1 \rbrace$. 
%Here, we set $R:=\sum_{l=0}^{\cL} v_{l} (1+v_l),$ where $v_l$ denotes the number of nodes for the layers $l =0,...,\mathcal{L}$. 
Then motivated by the stochastic optimal control problem in \eqref{eq:StochastiOptimalControl} we aim to find the family of neural networks $(\cU_n^{\rho_n})_{n=0,...,M-1}$ which minimizes the following loss function
\begin{align} \label{eq:LossFunctionAlgorithm}
\mathbb{E} \left[ \left( g(\widetilde{X}_M)-\widetilde{Y}_M^{y,\rho} \right)^2 \right],
\end{align}
where $\widetilde{X}=(\widetilde{X}_n)_{n=0,...,M-1}, \widetilde{Y}^{y, \rho}=( \widetilde{Y}^{y, \rho}_n)_{n=0,...,M-1}$ are given by 
\begin{small}
\begin{align} \label{eq:SchemeDeepSolverOneNeuralNetwork}
\begin{cases}
	\widetilde{X}_{n+1}&=\widetilde{X}_n +b(\widetilde{X}_n) \Delta t+ \sigma(\widetilde{X}_n)^{\top}\Delta W_n + \gamma(\widetilde{X}_n)\sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)}  z_i - \Delta t \int_{\mathbb{R}^d} \gamma(\widetilde{X}_n) z \nu (\textnormal{d}z), \\
	\widetilde{X}_0&=x,\\
	\widetilde{Y}_{n+1}^{y,\rho}&= \widetilde{Y}_n^{y, \rho}- f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n^{y, \rho}, \sigma(\widetilde{X}_n)^{\top} D_x \mathcal{U}_{n}^{\rho_n}(\widetilde{X}_n), \int_{\mathbb{R}^d}\left(\cU_n^{\rho_n}(\widetilde{X}_n +\gamma(\widetilde{X}_n)z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)\nu(\textnormal{d} z) \right) \Delta t \\
	& \quad +(D_x \mathcal{U}_{n}^{\rho_n}(\widetilde{X}_n))^{\top}\sigma(\widetilde{X}_n) \Delta W_n + \left( \cU_n^{\rho_n}\left(\widetilde{X}_n + \gamma(\widetilde{X}_n)\sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)} z_i \right)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)  \\
	& \quad -\Delta t \int_{\mathbb{R}^d} \left(\cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n)z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)\nu( \textnormal{d}z),  \\
	\widetilde{Y}_0^{y,\rho}&=\cU_0^{\rho_0}=:y \in \mathbb{{R}},
\end{cases}	
\end{align}
\end{small}
for $n=1,...,M-1$. Here, $N([0,t_n],\mathbb{R}^d)$ denotes the number of $\mathbb{R}^d$-valued jumps, which occur over the time interval $[0,t_n]$ and  $D_x \mathcal{U}_{n}^{\rho_n}$ is the gradient of $\cU_n^{\rho_n}$ that can be computed by means of the \texttt{Tensorflow} automatic differentiation capabilities.

\begin{remark}

\begin{enumerate}
\item 
A computationally efficient variant of the algorithm above is proposed in \cite{gnoatto_patacc_picarelli}. The presented minimization problem in \eqref{eq:LossFunctionAlgorithm} and \eqref{eq:SchemeDeepSolverOneNeuralNetwork} differs from the problem studied in \cite{gnoatto_patacc_picarelli} in the following way. While we consider one family of neural networks which approximates the stochastic integral with respect to the Brownian motion and with respect to the compensated random measure, the approach in \cite{gnoatto_patacc_picarelli} introduces a first family of ANNs  to approximate the gradient $D_x u$, a second one that approximates $\Delta u(t_n,\widetilde{X}_n, \Delta \widetilde{X}_n)$ with 
\begin{align*}
\Delta \widetilde{X}_n&= \gamma(\widetilde{X}_n)\sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)} z_i, \nonumber \\
\Delta u(t_n,\widetilde{X}_n, \Delta \widetilde{X}_n)&=u(t_n, \widetilde{X}_n + \Delta  \widetilde{X}_n)-u(t_n, \widetilde{X}_n),
\end{align*}
and a third one  that approximates
\begin{align}  \label{eq:CompensatorTerm}
\int_{\mathbb{R}^d} u(t_n, \widetilde{X}_n+\gamma(\widetilde{X}_n) z)-u(t_n, \widetilde{X}_n) \nu(\textnormal{d} z).
\end{align}

%This possibly high dimensional integral with respect to a L\'evy measure could result in a costly nested Monte Carlo simulation and the use of a second family of neural networks allows to avoid these computational difficulties. In this case the loss function in \eqref{eq:LossFunctionAlgorithm} will be penalized by another term reflecting the additional family of neural networks. For more details on the algorithm we refer directly to \cite{gnoatto_patacc_picarelli}.\\
For the purpose of deriving error estimates we consider only one family of neural networks to keep the representation of the estimates simpler, as training two further families of neural networks requires the introduction of additional penalization terms in the loss function.
