%\end{align}
%If the dimension is low one can apply for example a standard quadrature rule.

\item In \cite{ehanjen17} and \cite{gnoatto_patacc_picarelli}, instead of computing the gradient of $\mathcal{U}_n^{\rho_n}$ by using  {\fontfamily{qcr}\selectfont Tensorflow}, another family of neural networks $(\mathcal{V}_n^{\theta_n})_{n=0,...,M-1}$ is introduced to approximate this gradient $D_x u$. Under the growth condition 
$$
\big \vert  \mathcal{V}_n^{\theta_n} (x) \big \vert^2\leq C_n,
$$
for a constant $C_n\geq 0$, for $n=0,\ldots, M-1$ (see Assumption \ref{assump:NeuralNetwork} below), the error estimates derived in the following still hold true.
\end{enumerate}
\end{remark}

We assume from now on that the SDE in \eqref{eq:SDE} starts (in the fixed point $x \in \mathbb{R}^d$) at time $t=0$ and to simplify the notation we denote the solution of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} by $(X,Y,Z,U)$. Moreover, given this solution we define the process $\Psi=(\Psi_t)_{t \in [0,T]}$ by 
\begin{equation} \label{eq:Integral}
\Psi_t:=\int_{\bR^d} U_t(z)\nu(\textnormal{d}z), \quad t \in [0,T]. 
\end{equation}
With this notation we rewrite the scheme in \eqref{eq:SchemeDeepSolverOneNeuralNetwork} as follows 
\begin{align} \label{eq:SchemeDeepSolverOneNeuralNetworkRewritten1}
\begin{cases}
	\widetilde{X}_{n+1}&=\widetilde{X}_n +b(\widetilde{X}_n) \Delta t+ \sigma(\widetilde{X}_n)^{\top}\Delta W_n + \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \gamma(\widetilde{X}_n) z \widetilde{N}(\textnormal{d}r,\textnormal{d}z), \\
	\widetilde{X}_0&=x,\\
	\widetilde{Z}_n^{  {\rho}}&= \sigma(\widetilde{X}_n)^{\top} D_x \mathcal{U}_{n}^{\rho_n}(\widetilde{X}_n),\\
	\widetilde{\Psi}_n^{  {\rho}}&= \int_{\bR^d}\left(\cU_n^{\rho_n}(\widetilde{X}_n +\gamma(\widetilde{X}_n) z )- \cU_n^{\rho_n}(\widetilde{X}_n)\right) \nu(\textnormal{d}z) \\
	\widetilde{Y}_{n+1}^{y,\rho}&= \widetilde{Y}_n^{y, \rho}- f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n^{y, \rho}, \widetilde{Z}_n, \widetilde{\Psi}_n \right) \Delta t  +\widetilde{Z}_n^{\top} \Delta W_n   \\
	&\quad + \left( \cU_n^{\rho_n}\left(\widetilde{X}_n + \gamma(\widetilde{X}_n) \sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)}z_i \right)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)	 - \int_{t_n}^{t_{n+1}} \widetilde{\Psi}_n \textnormal{d}t,  \\
	\widetilde{Y}_0^{y,\rho}&=y
\end{cases}	
\end{align}
for $n=0,...,M-1$ and {by suppressing the dependence on the neural network {parameter} $\rho$ and the starting value $y$ {to ease the notation,} }we denote its solution by $(\widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n)_{n =0,...,M}$. In particular, we set here $\widetilde{Z}_M=\widetilde{\Psi}_M:=0$ to simplify the notation.

As we are interested in $L^2$-error estimates, the solution $(\widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n)_{n =0,...,M}$ of \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1} needs to be square-integrable. To guarantee this, we add assumptions for the classes of families of neural networks we consider.
\begin{assumption} \label{assump:NeuralNetwork}  
We assume that for each $n=0,...,M-1$ the function $\mathcal{U}_n^{\rho_n}: \bR^d \to \bR^d$ is measurable and satisfies the following growth condition
\begin{equation}\label{eq:AssumptionNeuralNetworkGrowth}
	\big \vert \mathcal{U}_n^{\rho_n} (x) \big \vert^2\leq A_n + B_n \vert x \vert^2
\end{equation} 
for constants $A_n,B_n {\geq 0}$. 
Moreover, for each $n=0,...,M-1$ the function $\mathcal{U}_n^{\rho_n}: \bR^d \to \bR^d$ is differentiable and the gradient $D_x \mathcal{U}_{n}^{\rho_n}(x)$ satisfies the following growth condition
\begin{equation}\label{eq:AssumptionNeuralNetworkGrowthGradient}
	\big \vert D_x \mathcal{U}_n^{\rho_n} (x) \big \vert^2\leq C_n
\end{equation} 
for a constant $C_n  {\geq 0}$.
\end{assumption}
\begin{remark}
Note that Assumption \ref{assump:NeuralNetwork} is satisfied for {families of} neural networks defined by means of the sigmoid activation function.
\end{remark}
{In the next lemma we make use of the following estimates, which we summarize briefly.}
