\begin{lemma} \label{lemma:SchemeAdaptedIntegrable}
Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}, \textbf{(A3)}, \ref{assump:FiniteActivity} and \ref{assump:NeuralNetwork} hold. Then the solution \linebreak $(\widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n)_{n =0,...,\violet{M}}$ of \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1} is $(\mathcal{F}_n)_{  {n=0,...,M}}$-adapted and square-integrable.
\end{lemma}
\begin{proof}
The adaptedness follows straightforward by induction. 
We prove the square-integrability of $(\widetilde{X}_n)_{n=0,...,M}$ by induction. It is clear that $\widetilde{X}_0:=x$ is square-integrable. Thus, for $n >0$ we have 
\begin{align} 
	\bE\left[ \big  \vert \widetilde{X}_{n+1} \big \vert ^2\right]&\leq 4 \left(  \bE\left[ \big \vert \widetilde{X}_n \big \vert ^2\right] + \bE \left[ \big \vert b(\widetilde{X}_n) \Delta t \big \vert^2 \right] + \bE \left[ \Big \vert \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \gamma(\widetilde{X}_n) z \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \Big \vert^2  \right] \right).\label{eq:SquareIntegrabilityX}
\end{align}
By Assumption \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A3)} and Assumption \ref{assump:FiniteActivity} itself and its implication $\int_{\bR^d}\big \vert  z\big \vert^2\nu(dz)<\infty$, {by Remark \ref{remark:Gamma}, the fact that  $\gamma(\widetilde{X}_n) z$ as a constant process on $[t_n, t_{n+1}]$ is an element in $\bH_{[t_n,t_{n+1}],N}^2(\bR^d)$ and {the} induction hypothesis it follows}
\allowdisplaybreaks
\begin{align}\bE \left[ \Big \vert \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \gamma(\widetilde{X}_n) z \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \Big \vert^2  \right] 
&= \bE \left[  \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \vert \gamma(\widetilde{X}_n) z\vert ^2 \nu(\textnormal{d}z)\textnormal{d}r  \right]  \nonumber \\
&= \Delta t \bE\left[\big \vert   \gamma(\widetilde{X}_n) \big \vert^2 \right] \int_{\bR^d}\big \vert    z\big \vert^2\nu(dz)\nonumber \\
&{\leq  \Delta t C_{\gamma} \left( 1+ \mathbb{E}\left[ \big \vert \widetilde{X}_n \big \vert^2\right]\right) \int_{\bR^d}\big \vert    z\big \vert^2\nu(dz)} \nonumber \\
&<\infty. \label{eq:SquareIntegrabilityX1}
\end{align}
Again by the induction assumption, Remark \ref{remark:Gamma} and \eqref{eq:SquareIntegrabilityX}, \eqref{eq:SquareIntegrabilityX1} we conclude
$$
\mathbb{E}\left[ \big \vert \widetilde{X}_{n+1} \big\vert^2 \right]< \infty.
$$
Obviously, $\mathbb{E}\left[\vert\widetilde{Z}_M \vert^2 \right]=\mathbb{E}\left[\vert\widetilde{\Psi}_M \vert^2 \right]=0$. For $n=0,...,M-1$, we get
\begin{align}
