\begin{align}
\bE \left[\widetilde{Y}_{n+1} \vert \cF_n \right]&= 	\widetilde{Y}_n- f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n \right) \Delta t + \widetilde{Z}_n^{\top}\bE \left[ \Delta W_n \vert \cF_n\right] \nonumber \\
& \quad  + \bE \left[ \left( \cU_n^{\rho_n}\left(\widetilde{X}_n + \gamma(\widetilde{X}_n)\sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)} z_i\right)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)	 - \int_{t_n}^{t_{n+1}} \widetilde{\Psi}_n \textnormal{dt}\vert \cF_n \right] \nonumber \\
&= \widetilde{Y}_n- f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n \right) \Delta t  \nonumber \\
& \quad +\bE \left[ \int_{t_n}^{t_{n+1}} \int_{\bR^d}  \left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right) \widetilde{N}(\textnormal{d}r, \textnormal{d}z) \vert \cF_n \right] \nonumber \\
& = \widetilde{Y}_n- f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n \right) \Delta t , \label{eq:YSatisfiesScheme1}
\end{align}
where we use {the fact that} $\cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n)$, as a constant process on $[t_n, t_{n+1}]$, is an element in $\bH_{[t_n,t_n+1],N}^2(\bR^d)$. %\blue{If we have a Lipschitz condition for $\mathcal{U}_n^{\rho_n}$, then we get
%\begin{align}
%	&\bE \left[ \int_{t_n}^{t_{n+1}} \int_{\bR^d}  \big \vert \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \big\vert^2 \nu(\textnormal{d}z) \textnormal{d}r  \right] \nonumber \\
%	& \leq K \Delta t \ \bE \left[  \int_{\bR^d}  \big \vert \gamma(\widetilde{X}_n) z \big\vert^2 \nu(\textnormal{d}z)   \right] <\infty
%	\end{align}
%by using the same arguments as above.
%}
By multiplying the equation for $\widetilde{Y}_{n+1}$ by $\Delta W_n$ and conditioning on $\cF_n$ we have
\begin{align}
&\bE \left[\widetilde{Y}_{n+1} \Delta W_n \vert \cF_n \right] \nonumber \\
&= \Delta t \ \widetilde{Z}_n + \bE \left[ \left(\int_{t_n}^{t_{n+1}} \int_{\bR^d}  \left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right) \widetilde{N}(\textnormal{d}r, \textnormal{d}z) \right) \left( \int_{t_n}^{t_{n+1}} dW_r\right) \vert \cF_n \right] \nonumber \\
&=\Delta t \ \widetilde{Z}_n, \nonumber
\end{align}
where we use again the regularity of $ \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n)$. This, shows that $\widetilde{Z}_n$ satisfies the corresponding equation in \eqref{eq:SchemeDelongWithoutTerminalCondition}. 
  {M}ultiplying the equation for $\widetilde{Y}_{n+1}$ by $\int_{t_n}^{t_{n+1}} \int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z)$ and considering the   {conditional} expected value, yields
\allowdisplaybreaks
\begin{align}
&\mathbb{E}\left[ \widetilde{Y}_{n+1}\int_{t_n}^{t_{n+1}} \int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\vert \mathcal{F}_n\right] \nonumber
\\
&=\mathbb{E}\left[ \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d}\left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)\widetilde{N}(\textnormal{d}r,\textnormal{d}z) \int_{t_n}^{t_{n+1}} \int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\vert \mathcal{F}_n\right] \nonumber \\
&=\mathbb{E}\left[ \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d}\left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right){N}(\textnormal{d}r,\textnormal{d}z) \vert \mathcal{F}_n\right] \nonumber \\
&=\mathbb{E}\left[ \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d}\left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right){\nu}(\textnormal{d}z)\textnormal{d}r \vert \mathcal{F}_n\right]\nonumber \\
&= \Delta t \ \int_{\mathbb{R}^d}\left( \cU_n^{\rho_n}(\widetilde{X}_n + \gamma(\widetilde{X}_n) z)- \cU_n^{\rho_n}(\widetilde{X}_n) \right){\nu}(\textnormal{d}z)\nonumber \nonumber\\
&=\Delta t \ \widetilde{\Psi}_n, 
 \end{align}
 which concludes the proof.
\end{proof}

{We prove the following auxiliary result, that we use to derive in a second step an estimate for the difference of two solutions satisfying the scheme in \eqref{eq:SchemeDelongWithoutTerminalCondition}.}
\begin{lemma} \label{lemma:FirstEstimateAuxiliary}
	Let $0 \leq s_1 < s_2 \leq T$ and $Q \in L^2(\Omega, \cF_{s_2},\bP)$. Let $(Z_t)_{t \in [s_1,s_2]}$ and $(U_t)_{t \in [s_1,s_2]}$ be $\bF$-predictable processes which are integrable with respect to $W$ and $\widetilde{N},$ respectively, and such that by the predictable representation property it holds
\begin{align}
Q = \bE \left[Q\vert \cF_{s_1} \right]+ \int_{s_1}^{s_2}( Z_r)^{\top} \textnormal{d}W_r + \int_{s_1}^{s_2}\int_{\bR^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z).
\end{align}
Then we have
\begin{align}
\bE \left[Q(W_{s_2}-W_{s_1})\vert \cF_{s_1} \right]&= \bE \left[\int_{s_1}^{s_2} Z_r\textnormal{d}r \Big \vert \cF_{s_1} \right],\label{eq:ProductDeltaBrownianMotion} \\
\bE \left[Q\left( \int_{s_1}^{s_2} \int_{\bR^d} \widetilde{N}(\textnormal{d}r,\textnormal{dz})\right)\Big \vert \cF_{s_1} \right]&= \bE \left[\int_{s_1}^{s_2} \int_{\bR^d} U_r(z) {N}(\textnormal{d}r,\textnormal{dz}) \Big \vert \cF_{s_1}\right].\label{eq:ProductDeltaJump}
\end{align}
\end{lemma}
\begin{proof}
Define the auxiliary stochastic process
\begin{equation*}
	Q_s = \left(\bE \left[Q \vert \cF_{s_1} \right]+\int_{s_1}^{s}( Z_r)^{\top} \textnormal{d}W_r + \int_{s_1}^{s}\int_{\bR^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\right) \int_{s_1}^s \textnormal{d}W_r, \quad s \in [s_1,s_2].
\end{equation*}	
By applying It\^{o}'s formula we get
\begin{align*}
\textnormal{d}Q_{s}& =(W_s - W_{s_1})(Z_s)^{\top}\textnormal{d}W_s+ \int_{\mathbb{R}^d}(W_s - W_{s_1})U_s(z)\widetilde{N}(\textnormal{d}s,\textnormal{d}z) + Z_s \textnormal{d}s  \nonumber \\
	& \quad + \left(\bE \left[Q \vert \cF_{s_1} \right]+\int_{s_1}^{s}(Z_r)^{\top} \textnormal{d}W_r + \int_{s_1}^{s}\int_{\bR^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\right) \textnormal{d}W_s .
\end{align*}
By taking the conditional expectation and using $Q_{s_1}=0$ and $Q_{s_2}=Q (W_{s_2}-W_{s_1})$, we have
\begin{align*}
	\bE \left [Q_{s_2} \vert \cF_{s_1} \right]= \bE \left[ \int_{s_1}^{s_2} Z_r \textnormal{d}r \Big \vert \cF_{s_1} \right],
\end{align*}
by using the martingale property of $\int \cdot \textnormal{d}W_r, \int \int_{\bR^d} \cdot \widetilde{N}(\textnormal{d}r,\textnormal{d}z)$ and $\left[\int \cdot \textnormal{d}W_r ,\int \int_{\bR^d} \cdot \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \right]=0.$\\
We now define another auxiliary stochastic process
\begin{equation*}
	\overline{Q}_s = \left(\bE \left[\overline{Q}\vert \cF_{s_1} \right]+\int_{s_1}^{s}( Z_r)^{\top} \textnormal{d}W_r + \int_{s_1}^{s}\int_{\bR^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\right) {\int_{s_1}^s \int_{\bR^d} \widetilde{N}(\textnormal{d}r}, \textnormal{d}z), \quad s \in [s_1,s_2].
\end{equation*}	
By It\^{o}'s formula we have
\begin{align*}
	\textnormal{d}\overline{Q}_s&= \left(\bE \left[\overline{Q}\vert \cF_{s_1} \right]+\int_{s_1}^{s}( Z_r)^{\top} \textnormal{d}W_r + \int_{s_1}^{s}\int_{\bR^d} U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\right) \int_{\bR^d}\widetilde{N}(\textnormal{d}s, \textnormal{d}z)  \nonumber\\
	& \quad + \left(\int_{s_1}^s \int_{\bR^d} \widetilde{N}(\textnormal{d}r,dz) \right)(Z_s)^{\top}\textnormal{d}W_s + \left( \int_{s_1}^s \int_{\bR^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \right)\int_{\bR^d}U_s(z) \widetilde{N}(\textnormal{d}s,\textnormal{d}z) \nonumber \\
    & \quad+ \int_{\bR^d}U_s(z) N(\textnormal{d}s,\textnormal{d}z),
\end{align*}
and by considering the conditional expectation we get
\begin{align*}
	\bE \left[Q\left( \int_{s_1}^{s_2} \int_{\bR^d} \widetilde{N}(\textnormal{d}r,\textnormal{dz})\right) \Big \vert \cF_{s_1} \right]= \bE \left[\int_{s_1}^{s_2} \int_{\bR^d} U_r(z) {N}(\textnormal{d}r,\textnormal{dz}) \Big \vert \cF_{s_1}\right].
\end{align*}


\end{proof}
{We are now in a position to state an estimate for the difference of two solutions of the scheme in \eqref{eq:SchemeDelongWithoutTerminalCondition}.}
 \begin{proposition} \label{prop:SchemeWithoutTerminalDifference}
Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}, \textbf{(A3)} and \ref{assump:FiniteActivity} hold. For $j=1,2,$ let \linebreak $(X^j_n,Y^j_n,Z^j_n,\Psi^j_n)_{n=0,...,{M}}$ be two solutions of \eqref{eq:SchemeDelongWithoutTerminalCondition} such that $X^j_n,Y_n^j \in L^2(\Omega, \cF_n, \bP)$ for $n=0,...,{M}$. 
 Then for $n=0,...,{M-1}${,}
for any $\lambda>0$ and sufficiently small $\Delta t$ such that
\begin{equation} \label{eq:LambdaConstraint1}
\lambda^2 \geq (1 \vee K_{\nu})K_f \vee \frac{1-\sqrt{1-{12} (\Delta t)^2 K_f^2}}{{6} \Delta t K_f} \quad \text{and} \quad \lambda^2 \leq \frac{1+\sqrt{1-{12}  (\Delta t)^2 K_f^2}}{{6} \Delta t K_f},
\end{equation}
 we have
\begin{align} \label{eq:DifferenceTwoSolutionsSchemeWithoutTerminal2}
	&\bE\left[ \big \vert Y_n^1-Y_n^2 \big \vert^2 \right]\leq e^{F_1(M-n) \Delta t}\bE \left[ \big \vert  Y_{M}^1-Y_M^2 \big \vert^2 \right]
\end{align}
with 
\begin{equation} \label{eq:DefinitionConstantF}
    F_1:=-\frac{\ln(1-\Delta t K_f(4 \lambda ^2 + \frac{1}{\lambda^2}))}{\Delta t } . 
\end{equation} 
 \end{proposition}
 \begin{proof}
 For $n=0,...,{M}$ we use the following notation
 \begin{align*}
 \delta X_n := X^1_n -X^2_n, \quad  \delta Y_n := Y^1_n -Y^2_n, \quad  \delta Z_n := Z^1_n -Z^2_n, \quad  \delta \Psi_n := \Psi^1_n -\Psi^2_n.
\end{align*}
{Clearly, we have 
$ \delta X_n=0,$
as $X_0^1=X_0^2=x.$}
Moreover, we set
\begin{align*}
	\delta f_n:=& f(t_n,X^1_n,Y_n^1,Z_n^1,\Psi_n^1)-f(t_n,X^2_n,Y_n^2,Z_n^2,\Psi_n^2).
\end{align*}
With this notation we have {for $n=0,...,M-1$}
\begin{align}
\delta Z_{n}&= \frac{1}{\Delta t} \bE \left[ \delta Y_{n+1} \Delta W_n \vert \cF_n\right], \label{eq:DifferenceZ} \\
\delta \Psi_{n}&= \frac{1}{\Delta t} \bE \left[ \delta Y_{n+1} \int_{t_n}^{t_{n+1}}\int_{\bR^d} \widetilde{N} (\textnormal{d}r,\textnormal{d}z) \Big \vert \cF_n \right], \label{eq:DifferencePsi} \\
\delta Y_{n}&= \bE \left[ \delta Y_{n+1} \vert \cF_n\right]+\delta f_n \Delta t. \label{eq:DifferenceY} 
\end{align}
  {Fix $n=0,...,M-1.$}
Applying the martingale representation theorem{,} there exists $\bF$-predictable processes $(\delta Z_t)_{t \in [t_{  {n}},t_{  {n}+1}]}$ and $(\delta U_t)_{t \in [t_{  {n}},t_{  {n}+1}]}$,   {which are} integrable with respect to $W$ and $\widetilde{N}$, {respectively,} such that
\begin{align} \label{eq:ProofPredictableRepresentation}
\delta Y_{n+1} = \bE \left[\delta Y_{n+1} \vert \cF_n \right]+ \int_{t_n}^{t_{n+1}}(\delta Z_r)^{\top} \textnormal{d}W_r + \int_{t_n}^{t_{n+1}}\int_{\bR^d}\delta U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z).
\end{align} 
{M}oreover, {by combining \eqref{eq:DifferenceY} and \eqref{eq:ProofPredictableRepresentation} it follows}
\begin{align}
&\bE\left[ \vert \delta Y_{n+1} \vert^2 \right]\nonumber \\
&=\bE\left[\bigg \vert  \delta Y_n {-} \delta f_n \Delta t+ \int_{t_n}^{t_{n+1}}(\delta Z_r)^{\top} \textnormal{d}W_r + \int_{t_n}^{t_{n+1}}\int_{\bR^d }\delta U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \bigg \vert^2  \right]	\nonumber \\
&=\bE \left[ \vert \delta Y_n {-} \delta f_n \Delta t\vert^2 \right]+ \bE \left[\bigg \vert \int_{t_n}^{t_{n+1}}(\delta Z_r)^{\top} \textnormal{d}W_r + \int_{t_n}^{t_{n+1}}\int_{\bR^d }\delta U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\bigg \vert^2  \right] \nonumber \\
& \quad +2 \bE \left[  \left( \delta Y_n {-} \delta f_n \Delta t\right) \left( \int_{t_n}^{t_{n+1}}(\delta Z_r)^{\top} \textnormal{d}W_r + \int_{t_n}^{t_{n+1}}\int_{\bR^d }\delta U_r(z) \widetilde{N}(\textnormal{d}r,\textnormal{d}z)\right)\right]\nonumber \\
&=\bE \left[ \vert \delta Y_n {-} \delta f_n \Delta t\vert^2 \right]+ \bE \left[\int_{t_n}^{t_{n+1}}\vert\delta Z_r\vert^2 \textnormal{d}r \right]+ \bE \left[\int_{t_n}^{t_{n+1}}\int_{\bR^d } \big \vert \delta U_r(z) \big \vert^2 \nu(\textnormal{d}z)\textnormal{d}r  \right] \nonumber \\
& \geq \bE \left[ \vert \delta Y_n \vert^2 \right]-2 \Delta t \bE \left[ \vert \delta f_n \vert \vert \delta Y_n\vert \right]  + \bE \left[\int_{t_n}^{t_{n+1}}\vert\delta Z_r\vert^2 \textnormal{d}r \right]+ \bE \left[\int_{t_n}^{t_{n+1}}\int_{\bR^d } \big \vert \delta U_r(z) \big \vert^2 \nu(\textnormal{d}z)\textnormal{d}r  \right]  \nonumber \\
& \geq \bE \left[ \vert \delta Y_n \vert^2 \right]-2 \Delta t K_f\bE \left[\vert \delta Y_n\vert (\vert \delta Y_n \vert+ \vert \delta Z_n \vert + \vert \delta \Psi_n \vert) \right]   \nonumber\\
& \quad + \bE \left[\int_{t_n}^{t_{n+1}}\vert\delta Z_r\vert^2 \textnormal{d}r \right] + \bE \left[\int_{t_n}^{t_{n+1}}\int_{\bR^d } \big \vert \delta U_r(z) \big \vert^2 \nu(\textnormal{d}z)\textnormal{d}r  \right].  \label{eq:ProofDifferencesY1}
\end{align}
By using that $-2ab \geq - a^2 - b^2$ it follows that 
\begin{align}
    &-2 \Delta t K_f\bE \left[\vert \delta Y_n\vert ( \vert \delta Y_n \vert+ \vert \delta Z_n \vert + \vert \delta \Psi_n \vert) \right] \nonumber \\
    &=-2 \Delta t K_f\bE \left[{\lambda \vert \delta Y_n\vert} \left(\frac{1}{\lambda} \vert \delta Y_n \vert+ \frac{1}{\lambda}\vert \delta Z_n \vert +\frac{1}{\lambda} \vert \delta \Psi_n \vert\right) \right] \nonumber \\
    & \geq - \Delta t K_f\left( {3}  \lambda^2 \bE \left[\vert \delta Y_n \vert^2 \right] +  \frac{1}{\lambda^2} \bE \left[\vert \delta Y_n \vert^2 \right] +   \frac{1}{\lambda^2} \bE \left[\vert \delta Z_n \vert^2 \right] + \frac{1}{\lambda^2} \bE \left[\vert \delta \Psi_n \vert^2 \right] \right). \label{eq:ImprovedApproach1}
\end{align}
By applying \eqref{eq:ProductDeltaJump} in Lemma \ref{lemma:FirstEstimateAuxiliary} to $\delta Y_{n+1}$ we get{,} with \eqref{eq:DifferencePsi} and \eqref{eq:ProofPredictableRepresentation}{,}
\begin{align*}
	\Delta t \delta {\Psi}_n &=   { \bE \left[ \delta Y_{n+1} \int_{t_n}^{t_{n+1}}\int_{\bR^d} \widetilde{N} (\textnormal{d}r,\textnormal{d}z) \Big \vert \cF_n \right]} =   \bE \left[ \int_{t_n}^{t_{n+1}} \int_{\bR^d} \delta U_r(z) N (\textnormal{d}r,\textnormal{d}z) \Big \vert \cF_n\right]\\
 &=\bE \left[ \int_{t_n}^{t_{n+1}} \int_{\bR^d} \delta U_r(z) \nu(\textnormal{d}z)\textnormal{d}r \Big \vert \cF_n\right],
\end{align*}
and thus
\begin{align}
\Delta t \bE \left[ \vert \delta \Psi_n \vert^2\right]
%&= \Delta t\bE \left[ \delta \Psi_n ^2\right]\nonumber \\
&= \frac{1}{\Delta t}  \bE \left[ \left(\bE \left[ \int_{t_n}^{t_{n+1}} \int_{\bR^d} \delta U_r(z)  \nu(\textnormal{d}z)\textnormal{d}r \vert \cF_n\right]\right)^2\right]\nonumber\\
%&  \leq \frac{1}{\Delta t}  \bE \left[ \bE \left[ \left(\int_{t_n}^{t_{n+1}} \int_{\bR^d} \delta U_r(z)  \nu(\textnormal{d}z)\textnormal{d}r \right)^2 \Big \vert \cF_n\right]\right]\nonumber\\
&\leq  \frac{1}{\Delta t} \bE \left[ \left(\int_{t_n}^{t_{n+1}} \int_{\bR^d} \delta U_r(z)  \nu(\textnormal{d}z)\textnormal{d}r \right)^2\right]\nonumber\\
%& \leq \frac{1}{\Delta t} \bE \left[ \left( \int_{t_n}^{t_{n+1}} \int_{\bR^d} \vert \delta U_r(z)\vert^2 \nu(\textnormal{d}z)\textnormal{d}r \right)\left (\int_{t_n}^{t_{n+1}} \int_{\bR^d} \nu(\textnormal{d}z) \textnormal{d}r \right)\right]\nonumber\\
& \leq K_{\nu} \bE \left[ \left( \int_{t_n}^{t_{n+1}} \int_{\bR^d} \vert \delta U_r(z))\vert^2 \nu(\textnormal{d}z)\textnormal{d}r \right)\right]{.}\label{eq:WhatWeWantToProve1}
\end{align}
Similarly, by using \eqref{eq:ProductDeltaBrownianMotion} in Lemma \ref{lemma:FirstEstimateAuxiliary} together with \eqref{eq:DifferenceZ} and \eqref{eq:ProofPredictableRepresentation} we get
\begin{equation}\label{eq:SimilarHanLong}
\Delta t \bE \left[ \big \vert \delta  Z_n \big \vert^2 \right]   {\leq} \bE \left[ \int_{t_n}^{t_{n+1}} \vert Z_r\vert^2 \textnormal{d}r \right],
\end{equation}
  {for more details we refer to the proof of Lemma 1 in \cite{Han_Long_2020}.} Combining \eqref{eq:ProofDifferencesY1}, \eqref{eq:ImprovedApproach1}, \eqref{eq:WhatWeWantToProve1} and \eqref{eq:SimilarHanLong} it follows
\begin{align}
 \bE \left[ \big \vert \delta Y_{n+1} \big \vert^2\right] & \geq \left(1- \Delta t K_f \left({3} \lambda^2 + \frac{1}{\lambda^{2}}\right)\right)\bE \left[ \big \vert \delta Y_n \big \vert^2 \right] +\Delta t\left(1- K_f \frac{1}{\lambda^2}\right) \bE \left[ \big \vert \delta  Z_n \big \vert^2 \right]\nonumber \\
 & \quad + \Delta t\left(K_{\nu}^{-1}- K_f \frac{1}{\lambda^2}\right)  \bE \left[ \big \vert \delta \Psi_n \big \vert^2 \right]. \label{eq:BetterEstimate2}
\end{align}
We now choose $\lambda>0$ and $\Delta t$ sufficiently small such that 
\begin{align} 
    &1- \Delta t K_f \left({3} \lambda^2 + \frac{1}{\lambda^{2}}\right) \in (0,1) \quad \text{and} \quad 1- K_f \frac{1}{\lambda^2}\geq 0 \quad \text{and} \quad K_{\nu}^{-1}- K_f \frac{1}{\lambda^2} \geq 0. \label{eq:ConstraintNew1}
\end{align}
Note that \eqref{eq:ConstraintNew1} can be rewritten as
\begin{align*}
\lambda^2 \geq (1 \vee K_{\nu})K_f \vee \frac{1-\sqrt{1-{12} (\Delta t)^2 K_f^2}}{{6}  \Delta t K_f} \quad \text{and} \quad \lambda^2 \leq \frac{1+\sqrt{1-{12} (\Delta t)^2 K_f^2}}{{6} \Delta t K_f}.
\end{align*}
  {Then} \eqref{eq:BetterEstimate2} and \eqref{eq:ConstraintNew1}   {yields}
\begin{align*}
    \bE \left[ \big \vert \delta Y_n \big \vert^2\right] \leq \frac{1}{1-\Delta t K_f({3} \lambda ^2 + \frac{1}{\lambda^2})} \bE \left[\big  \vert \delta Y_{n+1} \big \vert^2\right]
\end{align*}
and   {by} induction for $0 \leq n \leq M$   {it follows}
\begin{align*}
     \bE \left[ \big \vert \delta Y_{n} \big \vert^2\right] \leq e^{{F}_1(M-n)\Delta t} \bE \left[\big  \vert \delta Y_M \big \vert^2\right]
\end{align*}
with 
$$
{F}_1:=-\frac{\ln(1-\Delta t K_f({3} \lambda ^2 + \frac{1}{\lambda^2}))}{\Delta t }.
$$
\end{proof}
{Combining the results of the first and second step, we now state an a posteriori error estimate for the finite activity case.}
 \begin{theorem} \label{theorem:ErrorEstiamteFiniteActivity}
