&\max_{n=0,1,...,M-1} \mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert Y^\epsilon_t - \widetilde{Y}_n^{\epsilon} \big \vert^2 \right]\nonumber   + \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}} \big \vert Z^\epsilon_t - \widetilde{Z}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] +  \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert \Psi^\epsilon_t - \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] \nonumber 
\\
&\leq C_\epsilon  \Delta t+ \overline{C}_\epsilon(\lambda,\overline{\lambda}) \bE \left[\big \vert  \widetilde{Y}_M^{\epsilon}-g(\widetilde{X}_M^{ \epsilon})\big\vert^2 \right],  \nonumber 
\end{align}
where $C_\epsilon>0$ denotes a constant only depending on the data of the FBSDE in \eqref{eq:SDEApproximation}-\eqref{eq:BSDEApproximation} and  
\begin{align}
\overline{C}_\epsilon(\lambda,\overline{\lambda}):= {2}\left(1+\overline{\lambda}^{-1}\right)  {e^{\overline{F}_1T} } \left[ {1}+ \frac{1+T K_f ({3} \lambda^2 + \frac{1}{\lambda^{2}})}{ \left ( 1 \wedge K_{\nu^\epsilon}^{-1} \right )- K_f \frac{1}{\lambda^2}} \right],\label{def:barCeps}
\end{align}
with $\overline{F}_1= K_f \left({3} \lambda^2 + \frac{1}{\lambda^{2}}\right)+ \overline{\lambda}$.
\end{proposition} 

\begin{proof}
The result follows by applying  Theorem \ref{theorem:ErrorEstiamteFiniteActivity}  to the truncated FBSDE \eqref{eq:SDEApproximation}-\eqref{eq:BSDEApproximation}. 
\end{proof}

We can now combine the results above in order to estimate the difference between the exact solution of the FBSDE \eqref{eq:SDE}-\eqref{eq:BSDE} and its approximation given by  \eqref{eq:SchemeDeepSolverOneNeuralNetwork_eps}.

 \begin{theorem} \label{teo:InfiniteActivityEstimate}
Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}-\textbf{(A3)} and \ref{assump:NeuralNetwork} hold true. Let $(X,Y,Z,U)$ be the solution of the FBSDE \eqref{eq:SDE}-\eqref{eq:BSDE} and $\Psi$ be defined in \eqref{eq:Integral}. Let $(\widetilde{X}^{ \epsilon}_n,\widetilde{Y}^{\epsilon}_n,\widetilde{Z}^{\epsilon}_n,\widetilde{\Psi}^{\epsilon}_n)_{n=0,...,M}$  be the solution of \eqref{eq:SchemeDeepSolverOneNeuralNetwork_eps}. Let $\overline{\lambda}>0$ and choose $\lambda>0 $ and a sufficiently small $\Delta t$ such that \eqref{eq:LambdaConstraint1InfiniteActivity} holds. Then, 
 \begin{align}
     \max_{n=0,1,...,M-1} \mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert X_t - \widetilde{X}_n^{\epsilon} \big \vert^2 \right] 
     \leq C\left( 1+\vert x \vert^2 \right) \int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z)+C_\epsilon\Delta t, \nonumber
 \end{align}
 and
 \begin{align}
 &\max_{n=0,1,...,M-1} \mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert Y_t - \widetilde{Y}_n^{\epsilon} \big \vert^2 \right] + \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}} \big \vert Z_t - \widetilde{Z}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] +  \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert \Psi_t - \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] \nonumber \\
 & \leq C_\epsilon\left(\Delta t + \int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z)\right) + 2 \overline{C}_\epsilon(\lambda,\overline{\lambda}) \bE \left[\big \vert  \widetilde{Y}_M^{{\epsilon}}-g(\widetilde{X}_M^{{ \epsilon}})\big\vert^2 \right], \nonumber
 \end{align}
 where $\overline{C}_\epsilon$ is defined by \eqref{def:barCeps} and $C_\epsilon>0$ only depends on the data of the FBSDE in \eqref{eq:SDEApproximation}-\eqref{eq:BSDEApproximation}.
 \end{theorem}


\begin{proof}
  By combining Propositions \ref{prop:ErrorEstimatesApproximationAlessandroAthena} and \ref{prop:InfiniteActivityEstimate}  it easily follows
    \begin{align}
