   %& \leq 2  \mathbb{E} \left[ \sup_{t \in [0,T]} \big \vert X_t -  {X}_t^{\epsilon} \big \vert^2 \right] +   \max_{n=0,1,...,M-1} 2\mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert X_t^{\epsilon} -  \widetilde{X}_n^{\epsilon} \big \vert^2 \right] \nonumber \\
    & \leq  { C}\left( 1+\vert x \vert^2 \right) \int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z)+ C_\epsilon \Delta t.\label{eq:DistanceInfiniteActivityX}
\end{align}
We  also have
 \begin{align}
    & \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert \Psi_t - \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right]\nonumber \\
   % &= \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_n{+1}}\big \vert \Psi_t - \widetilde{\Psi}_n^{\epsilon} \pm \Psi_{t}^{\epsilon}\big \vert^2 \textnormal{d}t \right]\nonumber \\
