    & \leq 4 \mathbb{E} \left[\int_{0}^{T}\Big \vert \int_{\bR^d} \left(U_t(z)-U_t^{\epsilon}(z) \right) \nu^{\epsilon}(\textnormal{d}z)\Big \vert^2 \textnormal{d}t \right] + 4 \mathbb{E} \left[\int_{0}^{T}\Big \vert \int_{\bR^d} U_t(z)  \nu_{\epsilon}(\textnormal{d}z)\Big \vert^2 \textnormal{d}t \right]\nonumber \\
    & \quad +2 \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert  \Psi_{t}^{\epsilon}-  \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right]\nonumber \\
 & \leq 4 \mathbb{E} \left[\int_{0}^{T}\Big \vert \int_{\bR^d} \left(U_t(z)-U_t^{\epsilon}(z) \right) \nu^{\epsilon}(\textnormal{d}z)\Big \vert^2 \textnormal{d}t \right] + 4 \mathbb{E} \left[\int_{0}^{T} \int_{\bR^d} \vert U_t(z)\vert^2  \nu_{\epsilon}(\textnormal{d}z) \textnormal{d}t \right]\nonumber \\
    & \quad +2 \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert  \Psi_{t}^{\epsilon}-  \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right],\label{eq:DistanceInfiniteActivityProof2}
 \end{align}
 by using Jensen's inequality for $\sigma$-finite measures, see Corollary 23.10 in \cite{schilling_book_2005}, in the last inequality. 
 {By Theorem \ref{theorem:LinkPIDE} and \eqref{eq:EstimatesRegularityPIDE} for $t \in [0,T]$ and $z \in \bR^d,$ $U_t(z)$ has the following representation}
