    U_t(z)=u(t,X_{t-}+ \gamma(X_{t-})z)-u(t,X_{t-}),
 \end{align*}    
 where $u$ is Lipschitz continuous with $\vert u(t,x) \vert \leq C(1+\vert x \vert )$, for some constant $C>0$. \\
 Thus, we get
\begin{align} 
\mathbb{E} \left[\int_{0}^{T} \int_{\bR^d} \vert U_t(z)\vert^2  \nu_{\epsilon}(\textnormal{d}z) \textnormal{d}t \right]
& \leq C  \mathbb{E} \left[\int_{0}^{T} \int_{\bR^d} (1+ \vert X_{t-}\vert^2 ) \vert z \vert^2  \nu_{\epsilon}(\textnormal{d}z) \textnormal{d}t \right] \nonumber \\
& \leq C \int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z) \bE \left[ \int_0^T \left( 1+ \sup_{s \in [0,T]} \vert X_{s-} \vert^2  \right)\textnormal{d}t \right] \nonumber \\
& \leq C (1+ \vert x \vert^2)\int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z)  \label{eq:DistanceInfiniteActivityProof2a},
\end{align}
where we use Theorem 4.1.1 in \cite{delong}   {in the last inequality}.
