% & \quad + 4 \mathbb{E} \left[\int_{0}^{T}\int_{\bR^d} \vert U_t(z)\vert^2  \nu_{\epsilon}(\textnormal{d}z) \textnormal{d}t \right] \nonumber \\
% & \leq K_\epsilon \Delta t+ C_\epsilon(\lambda,\overline{\lambda})  \bE \left[\big \vert  \widetilde{Y}_M^{\epsilon}-g(\widetilde{X}_M^{ \epsilon})\big\vert^2 \right] + 2 \mathbb{E} \left[ \sup_{t \in 0,T]} \big \vert Y_t - {Y}_t^{ \epsilon} \big \vert^2 \right]  + 2 \bE \left[\int_0^T \vert Z_t- Z_t^{\epsilon} \vert^2 \textnormal{d}t \right] \nonumber \\
%  & \quad + 4 \mathbb{E} \left[\int_{0}^{T}\Big \vert \int_{\bR^d} \left(U_t(z)-U_t^{\epsilon}(z)  \right)\nu^{\epsilon}(\textnormal{d}z)\Big \vert^2 \textnormal{d}t \right]+ C (1+ \vert x \vert^2)\int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z) . \label{eq:DistanceInfiniteActivityProof3}
