By the Cauchy-Schwarz inequality we also have
\begin{align}
    \mathbb{E} \left[\int_{0}^{T}\Big \vert \int_{\bR^d} \left(U_t(z)-U_t^{\epsilon}(z) \right) \nu^{\epsilon}(\textnormal{d}z)\Big \vert^2 \textnormal{d}t \right]\leq T K_{\nu^\epsilon} \mathbb{E} \left[\int_{0}^{T} \int_{\bR^d}\big \vert  U_t(z)-U_t^{\epsilon}(z) \big \vert^2 \nu^{\epsilon}(\textnormal{d}z)\textnormal{d}t \right]. \label{eq:DistanceInfiniteActivityProof4}
