Thus, by   {putting together} \eqref{eq:DistanceInfiniteActivityProof2}, \eqref{eq:DistanceInfiniteActivityProof2a}, \eqref{eq:DistanceInfiniteActivityProof4},  it follows 
\begin{align}
& \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert \Psi_t - \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] \nonumber \\
& \leq 4 T K_{\nu^\epsilon} \mathbb{E} \left[\int_{0}^{T} \int_{\bR^d}\big \vert  U_t(z)-U_t^{\epsilon}(z) \big \vert^2 \nu^{\epsilon}(\textnormal{d}z)\textnormal{d}t \right] + 4 C (1+ \vert x \vert^2)\int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z) \nonumber \\
& \quad + 2 \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert  \Psi_{t}^{\epsilon}-  \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right]\nonumber 
