and then  
\begin{align}
&\max_{n=0,1,...,M-1} \mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert Y_t - \widetilde{Y}_n^{\epsilon} \big \vert^2 \right] + \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}} \big \vert Z_t - \widetilde{Z}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] + \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert \Psi_t - \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right]\nonumber \\
& \leq 2 \mathbb{E} \left[ \sup_{  {[}t \in 0,T]} \big \vert Y_t - {Y}_t^{ \epsilon} \big \vert^2 \right]  + 2 \bE \left[\int_0^T \vert Z_t- Z_t^{\epsilon} \vert^2 \textnormal{d}t \right] + 4 T K_{\nu^\epsilon} \mathbb{E} \left[\int_{0}^{T} \int_{\bR^d}\big \vert  U_t(z)-U_t^{\epsilon}(z) \big \vert^2 \nu^{\epsilon}(\textnormal{d}z)\textnormal{d}t \right]\nonumber \\
& \quad + \max_{n=0,1,...,M-1} 2 \mathbb{E} \left[ \sup_{t \in [t_n,t_{n+1}]} \big \vert Y_t^{\epsilon} - \widetilde{Y}_n^{\epsilon} \big \vert^2 \right] + 2 \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}} \big \vert Z_t^{\epsilon} - \widetilde{Z}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right]   \nonumber\\
& \quad + 2 \mathbb{E} \left[ \sum_{n=0}^{M-1}\int_{t_n}^{t_{n+1}}\big \vert  \Psi_{t}^{\epsilon}-  \widetilde{\Psi}_n^{\epsilon} \big \vert^2 \textnormal{d}t \right] + 4 C (1+ \vert x \vert^2)\int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z)\nonumber \\
& \leq C_\epsilon \Delta t+ 2 \overline{C}_\epsilon(\lambda,\overline{\lambda}) \bE \left[\big \vert  \widetilde{Y}_M^{\epsilon}-g(\widetilde{X}_M^{ \epsilon})\big\vert^2 \right] + C_\epsilon\left( 1+\vert x \vert^2 \right) \int_{\bR^d} \vert z \vert^2 \nu_{\epsilon}(\textnormal{d}z),\nonumber 
