\section{A priori estimates}\label{sec:aPrioriEstimates}
\subsection{Finite activity case}
{As for the a posteriori estimate,} we first consider the finite activity case. We now aim to find an estimate for the term $$\mathbb{E} \left[ \big \vert \widetilde{Y}_M - g(\widetilde{X}_M) \big \vert^2 \right],$$
where $\widetilde{X}_M,\widetilde{Y}_M$ are defined in  \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1}.
In particular, under Assumption \ref{assump:FiniteActivity} the following result regarding the path regularity of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} is derived in Theorem 2.1 (i) and (ii) in \cite{bouchard_elie_2008}.
\begin{theorem} \label{theorem:Bouchard_Elie_Path_regularity}
 Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}, \textbf{(A2)} and \ref{assump:FiniteActivity} hold. Let $(X,Y,Z,U) \in \bS_{[0,T]}^2(\bR^d) \times \bS_{[0,T]}^2(\bR) \times \bH_{[0,T]}^2(\bR^d) \times \bH_{[0,T],N}^2(\bR) $ be the unique solution to the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE},   {and $\Psi$ given in \eqref{eq:Integral}.} Then the following path regularity holds
 \begin{align}
    & \max_{n=0,...,M-1} \bE \left[ \sup_{t \in [t_n, t_{n+1}]} \big \vert X_t - \widetilde{\widetilde{X}}_t \big\vert^2\right]+ \max_{n=0,...,M-1} \bE \left[ \sup_{t \in [t_n, t_{n+1}]} \big\vert Y_t - \widetilde{\widetilde{Y}}_t \big\vert^2\right] \nonumber \\
     & \quad +   {\mathbb{E} \left[ \int_0^T  \big \vert {Z_t} - \widetilde{\widetilde{Z}}_t\big \vert^2 \textnormal{d}t\right]} +   {\mathbb{E} \left[ \int_0^T  \big \vert \Psi_t - \widetilde{\widetilde{\Psi}}_t\big \vert^2 \textnormal{d}t\right]} \leq C \Delta t, \label{eq:PathregularityEstimate}
 \end{align}
 where $C$ is a constant only depending on the data of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} and the processes $\widetilde{\widetilde{X}}, \widetilde{\widetilde{Y}}, \widetilde{\widetilde{Z}},\widetilde{\widetilde{\Psi}}$ are defined on $[t_n,t_{n+1})$ by
 \begin{align} \label{eq:ProcessesBouchardElie}
 \widetilde{\widetilde{X}}_t:= X_n, \quad  \widetilde{\widetilde{Y}}_t:= Y_n, \quad \widetilde{\widetilde{Z}}_t:=\frac{1}{\Delta t}   \bE \left[ \int_{t_n}^{t_{n+1}} Z_s \textnormal{d}s \Big \vert \cF_{n}\right], \quad \widetilde{\widetilde{\Psi}}_t:=\frac{1}{\Delta t} \bE \left[ \int_{t_n}^{t_{n+1}} \Psi_s \textnormal{d}s \Big \vert \cF_{n}\right]
 \end{align}
 with $X_n:=X_{t_n}$ and $Y_n:=Y_{t_n}$ for $n=0,...,  {M-1}.$
\end{theorem}

As in the previous sections, we omit the dependence on $(t,x)$ in the notation and do not keep track of constants mentioning, time by time, only the quantities they depend on. In particular, as before $C$ denotes a constant depending only on the data of the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} and $C(\cdot)$ is a constant depending on additional arguments, which are specified in the bracket.

\begin{proposition} \label{LemmaSecondEstimateAuxiliary}
Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}-\textbf{(A3)}, \ref{assump:FiniteActivity} and \ref{assump:NeuralNetwork} hold. Let $(\widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n)_{ n=0,..., M}$ be defined in \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1} and   {$ \widetilde{\widetilde{Z}}_{n}:= \widetilde{\widetilde{Z}}_{t_n}$ and $ \widetilde{\widetilde{\Psi}}_{n}:= \widetilde{\widetilde{\Psi}}_{t_n}$ defined in \eqref{eq:ProcessesBouchardElie}}. {Given $\lambda_3>0$ there exists a constant $C(\lambda_3)$ such that for sufficiently small $\Delta t$ it holds
  \begin{align*}
   \mathbb{E}\left[ \big  \vert g(\widetilde{X}_M)-\widetilde{Y}_M \big \vert^2 \right] &\leq   {\bar H} (1+\lambda_3) \Delta t \sum_{n=0}^{M-1}\left(\bE \left[ \big \vert  \widetilde{\widetilde{Z}}_{n}- \widetilde{Z}_{n} \big \vert^2 \right] + \bE \left[ \big \vert  \widetilde{\widetilde{\Psi}}_{n}- \widetilde{\Psi}_{n} \big \vert^2 \right]\right) \nonumber \\
& \quad + (1+K_g)^2C(\lambda_3) \left(\big \vert Y_0-y \big \vert^2 +  \Delta t+ \textnormal{Error}^{\rho}\right),
  \end{align*}}
where 
\begin{align}
\textnormal{Error}^{\rho}&:=\max_{n=0,...,M-1}\bigg(\bE \left[   \int_{\bR^d}\left(  u(t_n, \widetilde{X}_n + \gamma(\widetilde{X}_n)z) -\cU_n^{\rho_n}(\widetilde{X}_n+\gamma(\widetilde{X}_n)z)\right)^2\nu(\textnormal{d}z)\right] \nonumber \\
& \quad \quad + K_{\nu} \bE \left[\left(  u(t_n, \widetilde{X}_n) -\cU_n^{\rho_n}(\widetilde{X}_n)\right)^2\right]\bigg) \label{eq:DefiError}
\end{align}
and $  {\bar H} :=\min_{x \in \mathbb{R}_+} H(x)$ for 
\begin{equation} \label{eq:DefinitionFunctionH}
H(x):=(1+K_g)^2\left(1 + 5(K_f)^2 {x}^{-1} \right) e^{T\left( x+5   {\bar K} ^2 x^{-1}+  {\bar K} ^2 \max \lbrace{ x^{-1} + 1+ \int_{\bR^d} \vert z \vert^2 \nu(\textnormal{d}z ), 5 x^{-1} \rbrace} \right)}
\end{equation} 
 with   {$  {\bar K} :=\max\lbrace { K_b,K_{\sigma},K_{\gamma}, K_f, K_{\nu} \rbrace}$.} 
\end{proposition}
\begin{proof}
Let $(X,Y,Z,U) \in \bS_{[0,T]}^2(\bR^d) \times \bS_{[0,T]}^2(\bR) \times \bH_{[0,T]}^2(\bR^d) \times \bH_{[0,T],N}^2(\bR)$ be the unique solution to the FBSDE in \eqref{eq:SDE}-\eqref{eq:BSDE} and $(\widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n)_{ n=0,..., M}$ be defined in \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1}.\\
We introduce the processes $(\widetilde{X}_t)_{t \in [0,T]}, (\widetilde{Y}_t)_{t \in [0,T]}$ by 
\begin{align}
    \widetilde{X}_{t}&=\widetilde{X}_n +b(\widetilde{X}_n) (t-t_n)+ \sigma(\widetilde{X}_n)^{\top}(W_t-W_n) + \int_{t_n}^{t}\int_{\mathbb{R}^d} \gamma(\widetilde{X}_n) z \widetilde{N}(\textnormal{d}r,\textnormal{d}z), \nonumber  \\
\widetilde{Y}_t&= \widetilde{Y}_n+ f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n, \widetilde{Z}_n, \widetilde{\Psi}_n \right) (t-t_n) -\widetilde{Z}_n^{\top} (W_t-W_n)  \nonumber \\
	&\quad - \left( \cU_n^{\rho_n}\left(\widetilde{X}_n + \gamma(\widetilde{X}_n)\sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t], \mathbb{R}^d)}  z_i \right)- \cU_n^{\rho_n}(\widetilde{X}_n) \right)	 + \int_{t_n}^{t} \widetilde{\Psi}_n \textnormal{d}s,  \nonumber
\end{align}
for $t \in [t_n,t_{n+1})$, $n=0,...,M-1$ and $W_n:=W_{t_n}$, $n=0,...,M-1.$ \\
We define the following differences for $t \in [t_n,t_{n+1})$ 
\begin{align}
 \delta X_t:= X_t - \widetilde{X}_t, \quad \delta Y_t := Y_t - \widetilde{Y_t}, \quad \delta Z_t:=Z_t - \widetilde{Z}_n, \quad \delta \Psi_t := \Psi_t - \widetilde{\Psi}_n, \quad \nonumber
\end{align}
and 
\begin{align*}
\delta b_t &:=b(X_t)-b(\widetilde{X}_n), \quad 
\delta \sigma_t :=\sigma(X_t)-\sigma(\widetilde{X}_n), \quad 
\delta \gamma_t :=\gamma(X_t)-\gamma(\widetilde{X}_n), \\
