We briefly discuss the result in Proposition \ref{LemmaSecondEstimateAuxiliary}. The derived estimate for the a priori estimate depends on the following quantities
\begin{align}\label{eq:DependenceANNs}
\bE \left[ \big \vert  \widetilde{\widetilde{Z}}_{n}- \widetilde{Z}_{n} \big \vert^2 \right],  \quad \bE \left[ \big \vert  \widetilde{\widetilde{\Psi}}_{n}- \widetilde{\Psi}_{n} \big \vert^2 \right], \quad \big \vert Y_0-y \big \vert^2, \quad  \textnormal{Error}^{\rho},
\end{align}
which are all connected to the families of ANNs we use. However, note that the first two terms in \eqref{eq:DependenceANNs} depend on $\widetilde{\widetilde{Z}}_{n}, \widetilde{\widetilde{\Psi}}_{n}$ which cannot be expressed in terms of families of ANNs. Thus, we now try to simplify them and state next an auxiliary result.


\begin{lemma} \label{lemma:SecondEstimateAuxiliary3}
  Let Assumptions \ref{assump:ExistenceUniquenessFBSDE} \textbf{(A1)}, \textbf{(A2)} and \ref{assump:NeuralNetwork} hold. Let $(\widetilde{X}_n)_{n =0,...,M}$ be given by \eqref{eq:SchemeDeepSolverOneNeuralNetworkRewritten1}. For $\Delta t < (K_f)^{-1}$ there exist deterministic functions $\widetilde{U}_n: \mathbb{R}^d \to \mathbb{R}$, $\widetilde{V}_n: \mathbb{R}^d \to \mathbb{R}^d$ and $\widetilde{L}_n: \mathbb{R}^d \to \mathbb{R}^d$ for $n=0,...,M$ such that $\widetilde{Y}_n':=\widetilde{U}_n(\widetilde{X}_n)$, $\widetilde{Z}_n':=\widetilde{V}_n(\widetilde{X}_n)$ and $\widetilde{\Psi}_n':=\widetilde{L}_n(\widetilde{X}_n)$ satisfy 
    \begin{align} \label{eq:SchemeLinkFeynmanKac}
 \begin{cases}
	\widetilde{Y}_M'&=g(\widetilde{X}_M), \\
	\widetilde{Z}_n'&= \frac{1}{\Delta t} \mathbb{E} \left[\widetilde{Y}_{n+1}' \Delta W_n \vert \mathcal{F}_n \right], \\
	\widetilde{\Psi}_n'&= \frac{1}{\Delta t} \mathbb{E} \left[ \widetilde{Y}_{n+1}'\int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \vert \mathcal{F}_n \right], \\
	\widetilde{Y}_n'&= \mathbb{E}\left[\widetilde{Y}_{n+1}' \vert \mathcal{F}_n \right]+f\left( t_n, \widetilde{X}_n, \widetilde{Y}_n', \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t,
	\end{cases}
 \end{align}
 for $n=0,...,M-1$.
\end{lemma}
\begin{proof}
The proof uses similar arguments as the one in Lemma 5 in \cite{Han_Long_2020}. We proceed by backward induction.
For $n=M$ it holds $\widetilde{U}_M(x):=g(x)$ for $x \in \mathbb{R}^d$ and as before w.l.o.g. we assume $\widetilde{Z}'_M=\widetilde{\Psi}'_M:=0.$ \\
We assume that the statements hold for $n+1$. In particular, there exists a function $\widetilde{U}_{n+1}:\mathbb{R}^d \to \mathbb{R}$ such that $\widetilde{Y}_{n+1}'= \widetilde{U}_{n+1}(\widetilde{X}_{n+1}).$ As
 $$
\widetilde{X}_{n+1}=\widetilde{X}_n +b(\widetilde{X}_n) \Delta t+ \sigma(\widetilde{X}_n)^{\top}\Delta W_n + \sum_{i=N([0,t_n], \mathbb{R}^d)+1}^{N([0,t_{n+1}], \mathbb{R}^d)} \Gamma(\widetilde{X}_n, z_i) - \Delta t \int_{\mathbb{R}^d} \Gamma(\widetilde{X}_n,z) \nu (\textnormal{d}z),
$$
there exists a deterministic function $\bar{U}_{n}: \mathbb{R}^d \times \mathbb{R} \times \mathbb{R} \to \mathbb{R}$ such that 
$$
\widetilde{Y}_{n+1}'= \widetilde{U}_{n+1}(\widetilde{X}_{n+1})= \bar{U}_n(\widetilde{X}_n, \Delta W_n, \Delta \widetilde{N}_n)
$$
  { with $\Delta \widetilde{N}_n:=\int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z)$. }
  {As} $\widetilde{Z}_n'$ needs to satisfy \eqref{eq:SchemeLinkFeynmanKac},   {we have}
$$
\widetilde{Z}_n'= \frac{1}{\Delta t} \mathbb{E} \left[ \widetilde{Y}_{n+1}' \Delta W_n \vert \mathcal{F}_n \right]=\frac{1}{\Delta t} \mathbb{E} \left[ \bar{U}_n(\widetilde{X}_n, \Delta W_n, \Delta \widetilde{N}_n) \Delta W_n \vert \mathcal{F}_n \right].
$$
By the independence of $\Delta W_n$, $\Delta \widetilde{N}$ to $\mathcal{F}_n$, there exists a deterministic function $\widetilde{V}_n: \mathbb{R}^d \to \mathbb{R}^d$ with $\widetilde{Z}_n'=\widetilde{V}_{n}'(  {\widetilde{X}_n}).$
Similarly, we get for $\widetilde{\Psi}_n'$
\begin{equation*}
    \widetilde{\Psi}_n'= \frac{1}{\Delta t} \mathbb{E} \left[ \widetilde{Y}_{n+1}'\int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \Big \vert \mathcal{F}_n \right]= \frac{1}{\Delta t} \mathbb{E} \left[ \bar{U}_n(\widetilde{X}_n, \Delta W_n, \Delta \widetilde{N}_n) \int_{t_n}^{t_{n+1}}\int_{\mathbb{R}^d} \widetilde{N}(\textnormal{d}r,\textnormal{d}z) \Big \vert \mathcal{F}_n \right],
\end{equation*}
and we conclude as before that there exists a deterministic function $\widetilde{L}_n: \mathbb{R}^d \to \mathbb{R}$ such that  $\widetilde{\Psi}_n'=\widetilde{L}_n(\widetilde{X}_n)$. \\
We set $H_n:=L^2(\Omega, \sigma(\widetilde{X}_n), \mathbb{P})$, which is a Banach space and can be represented as
$$
H_n:=\left \{ Y=\phi(\widetilde{X}_n): \phi \text{ is measurable and } \mathbb{E}\left[\vert Y\vert^2\right] < \infty \right \}. 
$$
We define for $Y \in H_n$ the mapping
$$
\Phi_n(Y):= \mathbb{E}\left[\widetilde{Y}_{n+1}' \vert \mathcal{F}_n \right]+f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t.
$$
Next, we verify that $\Phi_n(Y)$ is square-integrable. It holds
\begin{align}
&\mathbb{E}\left[ \left \vert \mathbb{E}\left[\widetilde{Y}_{n+1}' \vert \mathcal{F}_n \right]+f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t\right \vert^2 \right]\nonumber \\
& \leq 2 \mathbb{E} \left[ \mathbb{E}\left[\big\vert \widetilde{Y}_{n+1}'\big \vert  \vert \mathcal{F}_n \right]^2\right]+ 2(\Delta t )^2 \mathbb{E} \left[ \left \vert f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right)\right \vert^2 \right ] \nonumber \\
& \leq 2 \mathbb{E} \left[ \mathbb{E}\left[\big\vert \widetilde{Y}_{n+1}' \big\vert^2 \vert \mathcal{F}_n \right]\right]+ 2(\Delta t )^2 \mathbb{E} \left[ \left \vert f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right)\right \vert^2 \right ]\nonumber \\
& =2 \mathbb{E} \left[\big \vert \widetilde{Y}_{n+1}' \big\vert^2 \right]+ 2(\Delta t )^2 \mathbb{E} \left[ \left \vert f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right)\right \vert^2 \right ] \nonumber \\
&= 2\mathbb{E} \left[ \big \vert \widetilde{Y}_{n+1}' \big\vert^2  \right]+ 4(\Delta t )^2 \mathbb{E} \left[ \left \vert f\left( t_n, \widetilde{X}_n, {Y}, \widetilde{Z}_n', \widetilde{\Psi}_n'\right)-f(0,0,0,0,0)\right \vert^2 \right ] + 4(\Delta t )^2 \vert f(0,0,0,0,0)\vert^2 \nonumber \\
& \leq 2\mathbb{E} \left[\big\vert \widetilde{Y}_{n+1}' \big \vert^2 \right]+ 4(\Delta t )^2 \mathbb{E} \left[   \Big\vert K_{f,t} \vert t_n\vert^{\frac{1}{2}} + K_f \left(\vert \widetilde{X}_n \vert +\vert Y\vert + \vert \widetilde{Z}_n' \vert +\vert \widetilde{\Psi}_n' \vert \right) \Big \vert^2\right ] + 4(\Delta t )^2 C \nonumber \\
&  \leq 2\mathbb{E} \left[\big\vert \widetilde{Y}_{n+1}' \big\vert^2 \right]+ 8(\Delta t )^2 \mathbb{E} \left[   (K_{f,t})^2 \vert t_n\vert + (K_f)^2 \left(\vert \widetilde{X}_n \vert^2 +\vert Y\vert^2 + \vert \widetilde{Z}_n' \vert^2 +\vert \widetilde{\Psi}_n' \vert^2 \right)\right ] + 4(\Delta t )^2 C \nonumber  \\
& < \infty,
\end{align}
as by Lemma \ref{lemma:SchemeAdaptedIntegrable} $\widetilde{X}_n$ is square-integrable. Moreover, $Y \in H_n$ implies the square-integrability of $Y$ and $ \widetilde{\Psi}'_{n}, \widetilde{Z}'_n$ are also in $L^2.$\\ 
By using the representations of $\widetilde{Z}_n'$, $\widetilde{\Psi}_n'$ and $\widetilde{Y}_{n+1}'$, we can express $\Phi_n(Y)$ as a deterministic function of $\widetilde{X}_n$, i.e. $\Phi_n(Y) \in H_n$. Next, we prove that $\Phi_n$ is a contraction. To do so, let $Y_1,Y_2 \in H_n$, then it holds
\begin{align}
&\mathbb{E} \left[\big \vert \Phi_n(Y_1)-\Phi_n(Y_2) \big \vert^2\right]\nonumber \\
&= \mathbb{E} \left[\left \vert \mathbb{E}\left[\widetilde{Y}_{n+1}' \vert \mathcal{F}_n \right]+f\left( t_n, \widetilde{X}_n, {Y}_1, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t-\mathbb{E}\left[\widetilde{Y}_{n+1}' \vert \mathcal{F}_n \right]-f\left( t_n, \widetilde{X}_n, {Y}_2, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t \right\vert^2\right] \nonumber \\
&= \mathbb{E} \left[\left \vert f\left( t_n, \widetilde{X}_n, {Y}_1, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t-f\left( t_n, \widetilde{X}_n, {Y}_2, \widetilde{Z}_n', \widetilde{\Psi}_n'\right) \Delta t \right\vert^2\right] \nonumber \\
& \leq (\Delta t)^2 (K_f)^2\mathbb{E} \left[\big \vert Y_1-Y_2\big\vert^2\right] \nonumber,
\end{align}
by using the Lipschitz continuity of $f$. This allows to conclude that for $\Delta t< (K_f)^{-1}$ the mapping $\Phi_n$ is a contraction on $H_n$ and thus by the Banach fixed-point theorem there exists a unique fixed point $Y^*=\phi_n^*(\widetilde{X}_n)\in H_n$ such that $Y^*=\Phi_n(Y^*).$ By setting $\widetilde{U}_n:=\phi_n^*$ the result is proven.
\end{proof}
We now state our main result for the a priori estimate for the finite activity case. For this let us define the following objects along the lines of \cite{delong}, based on \cite{SOLE2007165}. We consider a univariate L\'evy process with characteristic triplet $(b,\sigma,\nu)$ for $\nu$ a L\'evy measure such that $\int_{\mathbb{R}}|z|^2 \nu(d z)<\infty$, $b\in\mathbb{R}$ and $\sigma \geq 0$. For $A \in \mathscr{B}([0, T]) \otimes \mathscr{B}(\mathbb{R})$ let $A(0)=\{t \in[0, T] ;(t, 0) \in A\}$ and $A^{\prime}=A \backslash A(0)$ we define the finite measure
$$
v(A)=\int_{A(0)} \sigma^2 d t+\int_{A^{\prime}} z^2 v(d z) d t.
$$
We define the martingale-valued random measure $\Upsilon$
$$
\Upsilon(A)=\int_{A(0)} \sigma {\textnormal{d}W_t}+\int_{A^{\prime}} z \widetilde{N}(\textnormal{d} t, \textnormal{d} z), \quad A \in \mathscr{B}([0, T]) \otimes \mathscr{B}(\mathbb{R}^{  {d}}).
$$
We also define
$$
I_n\left(\varphi_n\right)=\int_{([0, T] \times \mathbb{R})^n} \varphi\left(\left(t_1, z_1\right), \ldots\left(t_n, z_n\right)\right) \Upsilon\left(\textnormal{d} t_1, \textnormal{d} z_1\right) \cdot \ldots \cdot \Upsilon\left(\textnormal{d} t_n, \textnormal{d} z_n\right),
$$
and introduce the space $\mathbb{D}^{1,2}(\mathbb{R})$ of square integrable random variables  which are measurable with respect to the natural filtration generated by a L\'evy process and have the representation $$\xi=\sum_{n=0}^{\infty} I_n\left(\varphi_n\right),$$
which is the space of random variables for which the Malliavin derivative is defined as follows: we set $D \xi: \Omega \times$ $[0, T] \times \mathbb{R} \rightarrow \mathbb{R}$ to be the stochastic process of the form
$$
D_{t, z} \xi=\sum_{n=1}^{\infty} n I_{n-1}\left(\varphi_n((t, z), \cdot)\right).
$$
In the approach of \cite{SOLE2007165}, $D_{t, 0} \xi = D_{t} \xi$ is the Malliavin derivative with respect to the (univariate) Wiener process, whereas $D_{t,z}\xi$ represents the derivative with respect to the (univariate) jump component. Notice that in our setting the underlying L\'evy process takes values on $\mathbb{R}^d$: at the cost of heavier notations the construction of \cite{SOLE2007165} has been generalized to the multivariate case, which is relevant for our purposes in order to define $D\xi : \Omega\times [0,T]\times {\mathbb R}^d \to \mathbb R $, in \cite[Section 3.11]{phdNavarro} the construction is performed by combining univariate L\'evy processes as above.

