\begin{align}
    & \mathbb{E} \left[ \big\vert \widetilde{Y}_M - g(\widetilde{X}_M)\big\vert^2 \right] \nonumber \\
& \leq   3   {\bar H} \left(1+\lambda_3\right) \left(1+\lambda_{4}\right) \left( 4C\Delta t + \sum_{n=0}^{M-1}\mathbb{E}{ \left[\Big \vert \mathbb{E}\Big[ \widetilde{\widetilde{Z}}_n \vert \widetilde{X}_n\Big] - \widetilde{Z}_n \Big \vert^2 \right]} + \sum_{n=0}^{M-1} {\mathbb{E} \left[\Big \vert \mathbb{E}\Big[ \widetilde{\widetilde{\Psi}}_n \vert \widetilde{X}_n\Big] - \widetilde{\Psi}_n \Big \vert^2 \right]}\right)\nonumber \\
& \quad +  (1+K_g)^2C(\lambda_3) \left({\big \vert Y_0-y \big \vert^2} +  \Delta t+ {\textnormal{Error}^{\rho}}\right), \nonumber
