\subsection{Hadron inelastic physics models}
\label{sec:inelamodel}
\begin{figure}[bt]
    \centering
    \includegraphics[width=0.9\linewidth]{figs/models.pdf}
	\caption{Possible combinations of intranuclear cascade and deexcitation models compatible with Geant4. The solid lines indicate the default choice of each physics list, and the dashed lines display the alternative choices.}
