\section{Scattering solutions with a contact interaction in infinite volume}\label{scatteringsolutions}  
In infinite volume,  with a incoming plane wave of $e^{i \mathbf{ k} \cdot \mathbf{ r}} $,    
 the scattering solution of two particles interaction is described by inhomogeneous  integral   Lippmann-Schwinger (LS) equation,  
\begin{align}
 & \psi^{(\infty)}_{ \epsilon}(\mathbf{ r},\mathbf{ k})  =e^{i \mathbf{ k} \cdot \mathbf{ r}}   \nonumber \\
 & + \int_{ -\infty}^\infty d \mathbf{ r}' G^{(0, \infty)} (\mathbf{ r}- \mathbf{ r}' ; \epsilon )   V_S ( \mathbf{ r'})   \psi^{(\infty)}_{ \epsilon}(\mathbf{ r}',\mathbf{ k})    , 
\end{align}  
where $k = \sqrt{2\mu \epsilon}$, and the non-interacting Green's function is given by
\begin{equation}
 G^{(0, \infty)} (\mathbf{ r}   ; \epsilon)    = \int \frac{d \mathbf{ p}}{(2\pi)^3} \frac{ e^{i \mathbf{ p} \cdot  \mathbf{ r}  }  }{\frac{q^2}{2\mu} - \frac{\mathbf{ p}^2}{2\mu}}   = - \frac{2\mu }{4\pi} i  k h_0^{(+)} (k | \mathbf{ r}   |).
\end{equation}


With a contact interaction $V_S(\mathbf{ r}) = V_0 \frac{ \delta(r)}{r^2}$,  LS equation is reduced to
\begin{equation}
  \psi^{(\infty)}_{ \epsilon}(\mathbf{ r},\mathbf{ k})  =e^{i \mathbf{ k} \cdot \mathbf{ r}}      - i   2\mu k V_0 h_0^{(+)} (k  r )     \psi^{(\infty)}_{ \epsilon}( 0,\mathbf{ k})    .
\end{equation}  
Hence only $S$-wave contribute to scattering solutions: 
\begin{equation}
  \psi^{(\infty)}_{ 0}(r; \epsilon)  =4\pi j_0 (kr)     - i   2\mu k V_0 h_0^{(+)} (k  r )     \psi^{(\infty)}_{ 0}(0; \epsilon)   ,
\end{equation}  
where the partial wave expansion is defined by
\begin{equation}
 \psi^{(\infty)}_{ \epsilon }(\mathbf{ r},\mathbf{ k})  = \sum_{l m_l}  Y^*_{lm_l} (\mathbf{ \hat{k}}) \psi^{(\infty)}_{  l}(r; \epsilon) Y_{lm_l} (\mathbf{ \hat{r}}).
\end{equation}
 The formal solution is thus given by
\begin{equation}
  \psi^{(\infty)}_{ 0}(r; \epsilon) =4\pi j_0 (kr)      +  4\pi   i  t_0^{(S)} (\epsilon )  h_0^{(+)} (k  r )       , 
\end{equation} 
where the scattering amplitude is defined by
\begin{equation}
t^{(S)}_0(\epsilon) =  - \frac{   2\mu k    }{\frac{1}{V_0} +  i   2\mu k     h_0^{(+)} (k  r ) |_{r\rightarrow 0}  } .
\end{equation}
Using asymptotic behavior of spherical Hankel function: $h_0^{(+)} (k  r ) |_{r\rightarrow 0}  \rightarrow  1 - \frac{i}{k r}$, and also introducing the renormalized coupling strength by  
\begin{equation}
    V_R = \left ( \frac{1}{V_0} +   \frac{2\mu   }{  r}|_{r\rightarrow 0} \right )^{-1},
    \label{VR}
    \end{equation} 
    the scattering amplitude now is given by
\begin{equation}
t^{(S)}_0(\epsilon) = -  \frac{  1   }{\frac{1 }{ 2\mu  V_R k} +  i        } .
\end{equation}
The scattering phase shift due to contact interaction is hence given by
\begin{equation}
\cot \delta_0^{(S)} (\epsilon)  = i + \frac{1}{t^{(S)}_0(\epsilon) } =  - \frac{1 }{ 2\mu  V_R k}.
\end{equation}


\section{Connecting eigensolutions in a trap to infinite volume scattering solutions with  Coulomb interaction}\label{traptoscattappend}
In this section, we discuss some exact solutions involving Coulomb interaction.
They are needed in the validation of the new relation in Eq.\eqref{CtpartialwavSC}.

 %%%--------------------
\subsection{Exact solution of partial-wave-projected  Green's function for pure Coulomb interaction}
In addition to the asymptotic wavefunction in Eq.\eqref{SCwavasymp} and the phase shift in Eq.\eqref{Coulombphaseshift},
the Green's function also has an analytical expression for Coulomb interaction. The Green's function for $l$-th partial wave is the solution of differential equation,
\begin{align}
& \left  [ \epsilon +  \frac{1}{2\mu r^2} \frac{d}{d r} \left ( r^2 \frac{d }{d r}  \right ) - \frac{l (l+1)}{ 2\mu r^2}  - V_C (r)    \right ]G_l^{(C,\infty)} (  r,r'; \epsilon)  \nonumber \\
& = \frac{ \delta(r-r')  }{r^2},
\end{align}
whose analytical expression is given by~\cite{messiah1999quantum,Hostler1964,Guo:2021qfu},
 \begin{equation}
G_{ l }^{(C,\infty)} (r, r' ; \epsilon)    = - i 2 \mu  k j_l^{(C)} ( \gamma, k r_<)   h_l^{(C,+)} (\gamma, k r_>)  , \label{Gcoulombinf}
\end{equation}
where $r_<$ and $r_>$ represent the lesser and greater of $(r,r')$ respectively,  and
\begin{equation}
  h_l^{(C,\pm)} (\gamma, k r) =  j_l^{(C)} (\gamma, k r)  \pm i  n_l^{(C)} (\gamma, k r)   .
\end{equation}
 The Coulomb-modified  spherical Bessel functions $j_l^{(C)}(\gamma, k r)$ and $n_l^{(C)}(\gamma, k r) $ are defined~\cite{Guo:2021qfu}  via two linearly independent Kummer functions  $M(a,b,z) $ and $U(a,b,z)$, %~\cite{NIST:DLMF}, 
\begin{align}
& j_l^{(C)}(\gamma, k r)= \mathbb{C}_l (\gamma)     (k r)^l  e^{i k r} M(l+1+ i \gamma, 2l+2, -2 i k r), \label{jLC}
\end{align}
and
\begin{align}
& n_l^{(C)}(\gamma, k r)  \nonumber \\
&=  i(-2k r)^l e^{ \frac{\pi}{2}\gamma}     e^{i k r} U(l+1+ i \gamma, 2l+2, -2 i k r) e^{ i \delta_l^{(C)}}    \nonumber \\
 &-i(-2k r)^l e^{ \frac{\pi}{2}\gamma}      e^{-i k r} U(l+1- i \gamma, 2l+2, 2 i k r) e^{- i \delta_l^{(C)}}  , \label{nLC}
\end{align}
The Sommerfeld factor  is defined by \cite{messiah1999quantum},
\begin{equation}
\mathbb{C}_l (\gamma) = 2^l \frac{|\Gamma(l+1+ i \gamma)|}{(2 l+1)!} e^{- \frac{\pi}{2} \gamma }.
\end{equation}
 The Coulomb phase shift, $\delta_l^{(C)}$, is defined in Eq.(\ref{Coulombphaseshift}).





\subsection{Coulomb-modified scattering solutions with a contact interaction in infinite volume}\label{Coulombscatteringsolutions}  
In infinite volume (no trap),    the scattering solution of two charged particles interacting via a  Coulomb potential is described by the inhomogeneous LS equation,  see e.g. Ref.~\cite{Guo:2021qfu},
\begin{align}
 & \psi^{(\infty)}_{ \epsilon}(\mathbf{ r},\mathbf{ k})  =\psi^{(C,\infty)}_{ \epsilon}(\mathbf{ r},\mathbf{ k})    \nonumber \\
 & + \int_{ -\infty}^\infty d \mathbf{ r}' G^{(C, \infty)} (\mathbf{ r}, \mathbf{ r}' ; \epsilon )   V_S ( \mathbf{ r'})   \psi^{(\infty)}_{ \epsilon}(\mathbf{ r}',\mathbf{ k})    , 
\end{align}  
where $\psi^{(C,\infty)}_{ \epsilon}(\mathbf{ r},\mathbf{ k}) $ is Coulomb wavefunction  and $  G^{(C, \infty)} (\mathbf{ r} , \mathbf{ r'}  ; \epsilon)  $ is Coulomb Green's function. 

In the case of a contact interaction $V_S(\mathbf{ r}) = V_0 \frac{\delta(r)}{r^2}$, only $S$-wave will contributes, so after partial-wave projection, we find
 \begin{equation}
  \psi^{(\infty)}_{ 0}(r; \epsilon)  =\psi^{(C,\infty)}_{ 0}(r; \epsilon)   +  V_0    G_0^{(C, \infty)} (r, 0 ; \epsilon ) \psi^{(\infty)}_{ 0}(0; \epsilon)   , 
\end{equation}  
where the analytic expression of $S$-wave Coulomb  wave function and Coulomb Green's function are given by
\begin{equation}
\psi^{(C,\infty)}_{ 0}(r; \epsilon)  = 4\pi j_0^{(C)} (\gamma, k r) e^{  i \delta_0^{(C)} (\epsilon) } , 
\end{equation}
and 
\begin{equation}
G_0^{(C, \infty)} (r, r' ; \epsilon ) = - i 2\mu k j_0^{(C)} (\gamma, k r_<)   h_0^{(C, +)} (\gamma, k r_>) .
\end{equation}



The formal scattering solution in presence of Coulomb force can thus be obtained,
 \begin{align}
  \psi^{(\infty)}_{ 0}(r; \epsilon)  &=  4\pi  j_0^{(C)} (\gamma, k r) e^{  i \delta_0^{(C)} (\epsilon) }  \nonumber \\
&  +  4\pi   i t_0^{(SC)}  (\epsilon ) h_0^{(C, +)} (\gamma, k r)  e^{ -  i \delta_0^{(C)} (\epsilon) }   , 
\end{align} 
 where 
\begin{equation}
t_0^{(SC)} (\epsilon) =    \frac{  - 2\mu k    \mathbb{C}^2_0 (\gamma) e^{  2 i \delta_0^{(C)} (\epsilon) }  }{\frac{1}{ V_0} -    Re \left [  G_0^{(C, \infty)} (r, 0 ; \epsilon )|_{r\rightarrow 0} \right ] +  i 2 \mu k  \mathbb{C}^2_0 (\gamma)}  .
\end{equation}
The $t_0^{(SC)} (\epsilon) $ is usually parameterized by
\begin{equation}
t_0^{(SC)} (\epsilon)  = \frac{1 }{\cot \delta_0^{(S) } (\epsilon) - i } e^{  2 i \delta_0^{(C)} (\epsilon) } .
\end{equation}
Hence we find a useful relation
\begin{equation}
  \frac{1}{ V_0} =  - 2\mu k    \mathbb{C}^2_0 (\gamma)  \cot \delta_0^{(S)}  (\epsilon) +Re \left [  G_0^{(C, \infty)} (r, 0 ; \epsilon )|_{r\rightarrow 0} \right ]       . \label{V0scattrelation}
\end{equation}
The total scattering amplitude is defined by
\begin{equation}
t_0(\epsilon) = t^{(C)}_0(\epsilon)  + t^{(SC)}_0(\epsilon)  = \frac{e^{2 i \delta_0 (\epsilon)} -1}{2i},
\end{equation}
where $ t^{(C)}_0(\epsilon) $ is pure Coulomb scattering amplitude
\begin{equation}
t_0^{(C)} (\epsilon)  = \frac{e^{2 i \delta^{(C)}_0 (\epsilon)} -1}{2i}  = \frac{1 }{\cot \delta_0^{(C) } (\epsilon) - i }, 
\end{equation}
and $\delta_0 (\epsilon)$ is total $S$-wave scattering amplitude,
\begin{equation}
\delta_0 (\epsilon) = \delta^{(S)}_0 (\epsilon) + \delta^{(C)}_0 (\epsilon).
\end{equation}


With Coulomb correction, the Friedel formula and Krein's theorem in Eq.(\ref{Friedelformula})   must be replaced by,
 \begin{equation} 
  Tr  \left [ G_l^{(\infty)} (  \epsilon) -G_l^{(C, \infty)} (    \epsilon )   \right ]  = - \frac{1}{\pi}  \int_{0}^{\infty} d \lambda  \frac{\delta^{(S)}_l  (\lambda)}{ (\lambda - \epsilon)^2}, \label{FriedelformulaCoulomb}
 \end{equation}
 where $G_l^{(\infty)} (  \epsilon) $ and $G_l^{(C, \infty)} (    \epsilon ) $ represent Green's function operators with short-range plus Coulomb interaction and  only Coulomb interaction respectively. The  infinite volume Green's function, $G_l^{(\infty)} (  r,r'; \epsilon) $, satisfies Dyson   equation,
 \begin{align}
 &  G_l^{(\infty)} (  r,r'; \epsilon)  =G_l^{(C,\infty)} (  r,r'; \epsilon)   \nonumber \\
 & + \int_0^\infty {r''}^2 d r'' G_l^{(C,\infty)} (  r,r''; \epsilon)  V_S(r'') G_l^{(\infty)} (  r'',r'; \epsilon).
 \end{align}





\subsection{Coulomb-modified quantization condition in spherical hard-wall trap with a contact interaction}\label{qctrapappend}
The    dynamics of particles system in a   trap    can be also described    by the homogeneous Lippmann-Schwinger equation,
\begin{equation}
\psi (\mathbf{ r}; \epsilon) = \int  d \mathbf{ r'} G^{(C, trap)} (\mathbf{ r},\mathbf{ r'}; \epsilon) V_S(\mathbf{ r'}) \psi (\mathbf{ r'} ; \epsilon) , \label{LStrap}
\end{equation}
where  $G^{(C, trap)}  (\mathbf{ r},\mathbf{ r'}; \epsilon) $ is Coulomb-modified Green's function for the trapped system, and it satisfies differential equation,
\begin{equation}
 \left  [ \epsilon +  \frac{\nabla^2}{2\mu }    -U_{trap} (r) - V_C (r)    \right ] G^{(C,trap)} (  \mathbf{ r},\mathbf{ r'}; \epsilon)    =   \delta(\mathbf{ r}-\mathbf{ r'})  .
\end{equation}
The partial wave expansion of Green's function is defined by
\begin{equation}
G^{(C,trap)} (  \mathbf{ r},\mathbf{ r'}; \epsilon)   = \sum_{ l m_l} Y_{lm_l}(\mathbf{ \hat{r}})  G_l^{(C,trap)} (  r,r'; \epsilon)Y_{lm_l}^*(\mathbf{ \hat{r'}})  .
\end{equation}
For a spherical hard-wall trap, the analytical form of  Coulomb-modified partial wave Green's function for the trapped system can be obtained, see Eq.(73) in Ref.\cite{Guo:2021qfu},
\begin{align}
G_l^{(C,trap)} (  r,r'; \epsilon) & = - 2 \mu k j_l^{(C)} (\gamma , k r_<)  j_l^{(C)} (\gamma , k r_>) \nonumber \\
&  \times \left [ \frac{ n_l^{(C)} (\gamma , k R) }{ j_l^{(C)} (\gamma , k R) } - \frac{ n_l^{(C)} (\gamma , k r_>) }{ j_l^{(C)} (\gamma , k r_>) } \right ], \label{GCLtrap}
\end{align}
where    the Coulomb-modified  $j_l^{(C)}(\gamma, k r)$ and $n_l^{(C)}(\gamma, k r) $ functions  are defined in Eq.(\ref{jLC}) and Eq.(\ref{nLC}) respectively.


With a contact interaction, $V_S(\mathbf{ r}) = V_0 \frac{\delta(r)}{r^2}$,  after the $S$-wave projection, Eq.(\ref{LStrap}) yields a quantization condition,
\begin{equation}
\frac{1}{V_0} = G_0^{(C,trap)} (  r, 0; \epsilon) |_{r\rightarrow 0} .
\end{equation} 
Using relation in Eq.(\ref{V0scattrelation}), we find
\begin{align}
&    \cot \delta_0^{(S)} (\epsilon)  \nonumber\\  
&= \frac{ Re \left [  G_0^{(C, \infty)} (r, 0 ; \epsilon )|_{r\rightarrow 0} \right ] -G_0^{(C,trap)} (  r, 0; \epsilon) |_{r\rightarrow 0}  }{2\mu k  \mathbb{C}^2_0 (\gamma)  } .
\end{align} 
The real part of Coulomb Green's function in infinite volume is given by
\begin{equation}
Re\left [G_0^{(C, \infty)} (r, r' ; \epsilon ) \right ] =   2\mu k j_0^{(C)} (\gamma, k r_<)   n_0^{(C)} (\gamma, k r_>) ,
\end{equation}
which cancel out the second term of   Coulomb Green's function in the trap in Eq.(\ref{GCLtrap}).
Also using asymptotic form
\begin{equation}
j_0^{(C)} (\gamma , k r) \stackrel{r\rightarrow 0}{\rightarrow} \mathbb{C}_0 (\gamma),
\end{equation}
the Coulomb-modified quantization condition for a contact interaction potential is found in Eq.\eqref{qchsw}.
