\noindent To facilitate calculation and analysis, let \( k_1 = \beta + \mu \), \( k_2 = \mu + \xi + \delta_1 \), \( k_3 = \gamma + \mu + \delta_2 \), and \( k_4 = \mu + \xi \). %, then model (\ref{Model_1}) is changed as follows:
Let us define $\mathbb{X}=(X_1,X_2,X_3,X_4,X_5,X_6)=(S,E,I_1,I_2,T,A)$. Then the mathematical model (\ref{Model_1}) is given in the compact form as below,
\begin{equation}\label{Model_2}
	\mathbb{X}'=G(X,t) , \  \mathbb{X}(0)=\mathbb{X}_0,
	%	\label{compact}
\end{equation}
where, the initial conditions, $\mathbb{X}_0=(S_0,E_0,I_{10},I_{20}, T_0,A_0),$  and,
\begin{align}
G(X,t)&=[\kappa - (\alpha \epsilon E + \alpha I_2)S - \mu S,(\alpha \epsilon E + \alpha I_2)S - k_1 E,p\beta E - k_2 I_1 + \gamma I_2,\nonumber \\ 
&(1 - p)\beta E - k_3 I_2,\psi I_1 - k_4 T, \delta_1 I_1 + \delta_2 I_2 + \xi T - \mu_0 A - \mu A].\nonumber
\end{align}

Note that the basic reproduction number, $\mathcal{R}_0$ of \eqref{Model_2} is
\begin{equation*}
	\displaystyle \mathcal{R}_0 = \rho(FV^{-1}) = \frac{\alpha \varepsilon S_0}{k_1} + \frac{\beta S_0 \alpha (1 - p)}{k_1 k_3}
\end{equation*}
The detailed procedure for determining $\mathcal{R}_0$ can be found in Appendix \ref{sec:mathematicalanalysis}.

 \subsection*{The Feasible Area}
 \begin{lemma}\label{Lem1}
 	Assume the initial state variables in model (\ref{Model_2}) are positive, specifically,\\ \(S(0), E(0), I_1(0), I_2(0), T(0), A(0)>0\). Then, the functions \(S(t), E(t), I_1(t), I_2(t), T(t),\) and \(A(t)\) remain non-negative for all \(t \geq 0\) in model (\ref{Model_2}), and
 	\[
 	\lim_{t \to \infty} \sup N(t) \leq \frac{\kappa}{\mu}.
 	\]
 \end{lemma}
 %\textbf{Lemma 3.1:} Assume the initial state variables in model (\ref{Model_2}) are positive, specifically, \(S(0), E(0), I_1(0), I_2(0), T(0), A(0)>0\). Then, the functions \(S(t), E(t), I_1(t), I_2(t), T(t),\) and \(A(t)\) remain non-negative for all \(t \geq 0\) in model (\ref{Model_2}), and
 %\[
 %\lim_{t \to \infty} \sup N(t) \leq \frac{\kappa}{\mu}.
 %\]
 \begin{proof}
 	Consider, \(M(t)\) as the minimum value of all state variables, i.e.,
 	\begin{align*}
 		M(t) = \min\{S(t), E(t), I_1(t), I_2(t), T(t), A(t)\}  
 	\end{align*}
 	Now, if \(t > 0\), then it is obvious that \(M(t) > 0\). We assume that there exists a minimum time \(t_1\) satisfying that \(M(t_1) = 0\). Suppose \(M(t_1) = S(t_1)\), then \(E(t)\), \(I_1(t)\), \(I_2(t)\), \(T(t)\), \(A(t) > 0\) \(\forall \) $t$ \(\in [0, t_1]\). When \(t \in [0, t_1]\), we get,
 	\begin{align*}
 		\frac{dS}{dt} &= \kappa - \lambda(t)S - \mu S \\
 		&\geq -\lambda(t)S - \mu S 	= -(\alpha \varepsilon E + \alpha I_2)S - \mu S.
 	\end{align*}
 	After integrating both sides of the equation from 0 to \(t\), the resulting expression is as follows:
 	\begin{align*}
 		S(t) &\geq S(0)e^{-\int_{0}^{t}(\alpha \varepsilon E(\tau)+\alpha I_2(\tau)+\mu)d\tau} > 0, \quad \forall \: t \in [0, t_1],
 	\end{align*}
 	which contradicts with \(M(t_1) = S(t_1) = 0\). Therefore, \(S(t)\), \(E(t)\), \(I_1(t)\), \(I_2(t)\), \(T(t)\), \(A(t)>0\) when, \(t \geq 0\).
 	Next, we determine the limits for the state variables. Given \(N(t) = S(t) + E(t) + I_1(t) + I_2(t) + T(t) + A(t)\), by summing the equations in model (\ref{Model_2}), we obtain,
 	\begin{align*}
 		\frac{dN(t)}{dt} &= \kappa - \mu(S(t) + E(t) + I_1(t) + I_2(t) + T(t)) - \mu_0 A(t) - \mu A(t).
 	\end{align*}
 	As, \(\mu_0 \geq 0\) and
 	\begin{align*}
 		\frac{dN(t)}{dt} &= \kappa - \mu N(t) - \mu_0 A(t) \leq \kappa - \mu N(t),
 	\end{align*}
 	using the Comparison Principle Theorem \cite{mukandavire2009modelling}, we get,
 	\begin{align*}
 		N(t) &\leq N(0)e^{-\mu t} + \frac{\kappa}{\mu}(1 - e^{-\mu t}),
 	\end{align*}
 	where \(N(0) = S(0) + E(0) + I_1(0) + I_2(0) + T(0) + A(0)\). Hence,
 	\[
 	\lim_{t \to \infty} \sup N(t) \leq \frac{\kappa}{\mu}.
 	\]
 \end{proof}
 \noindent So, the feasible area $\Omega$ of model (\ref{Model_2}) can be defined by,
 \begin{equation}
 	\Omega = \left\{ (S(t), E(t), I_1(t), I_2(t), T(t), A(t)) \in \mathbb{R}_+^6 : 0 \leq S, E, I_1, I_2, T, A \leq N, N(t) \leq \frac{\kappa}{\mu} \right\} \tag{5}
 	\label{lemma:3.2} 
 \end{equation}


