\section{Methods}
\label{sec:methods}

\begin{figure*}[tb]
    \centering
    \includegraphics[width=\linewidth]{figures/DevelopmentValidationFlow.pdf}
    \caption{The development and validation process of the GERQN.}
    \label{fig:timeline}
