\includegraphics[width = \columnwidth]{spectral_weight}
\caption{Spectral weight $Z_j^{(0)}$ of the three lowest energy states vs.~the coupling strength $\alpha$ for $k_c=4\pi/l_0$ and two different box sizes. For $\alpha> 1.73$ marked by the vertical dashed line
the state $|\mathrm{B}\rangle$ becomes a bound excited state.
The dotted line is the first order perturbation theory result $1-\alpha/2$ for the ground state.
}
\label{fig:spectral}
