    {In some circumstances, including the ones we will be interested in, a monoidal functor between two strict monoidal categories is always connected to a strict monoidal functor via a natural transformation. We prove this here. Although we note that this natural transformation is not monoidal.    From the point of view of classification of functors from $\Bcat$, this means that, even if we had a classification of all strict monoidal functors, it is not necessarily a straight forward exercise to find monoidal functors $G\colon \Bcat \to \Dd$ connected via a natural transformation to a given strict monoidal functor $\F\colon \Bcat\to \Dd$.  However, in the interests of reducing classification to a tractable problem, we will assume all functors are strict monoidal.}

    \medskip

Let $\Cc = (\Cc, \otimes, \One_\Cc)$ be a strict monoidal category,
with $\Ob(\Cc)$  a finitely-generated free monoid. Specifically put 
$\Ob(\Cc) = \langle X_1,\ldots, X_p \rangle$, the free monoid on $p$ generators.
A word $s = s_1 s_2\cdots s_n$ in $\{1,2,\ldots,p\}^n$ represents an object by 
$s \mapsto X_{s_1} \otimes X_{s_2} \otimes \cdots\otimes X_{s_n}$, where the empty word represents $\unit_\catC$.
\\
Given a strict monoidal category $\Dd = (\Dd,\otimes, \One_\Dd)$,
let  
$(\FF,J)$ be 
a monoidal functor  (as in \ref{def:monoidal functor}) from $\Cc$ to $\Dd$.
Define a map 
$\FF^{st} : \Ob(\Cc) \rightarrow \Ob(\Dd)  \;$
by $\; \FF^{st} (\One_\Cc) = \One_\Dd$ and 
$$
\FF^{st} ( s_1 s_2 \cdots s_n ) = \FF(s_1) \otimes \FF(s_2) \otimes \cdots\otimes \FF(s_n)
$$
that is
$$
\FF^{st} (  X_{s(1)} \otimes X_{s(2)} \otimes \cdots\otimes X_{s(n)} ) 
=  \FF(X_{s(1)}) \otimes \FF( X_{s(2)} ) \otimes \cdots\otimes \FF( X_{s(n)} )  . 
$$
Observe that $J_{s_1,s_2} \otimes \id_{\FF^{st}(s_3\cdots s_n)}$
is a morphism from  $\FF^{st}(s) $ to $ \FF(s_1 s_2) \otimes \FF^{st}(s_3 \cdots  s_n) $.
Fixing this object $s$ for a moment,  
write $J_j$ for the morphism 
$\; J_{s_1\cdots s_j,s_{j+1}}\otimes \id_{\FF^{st}(s_{j+2}\cdots s_n)}$,
which is from  $  \FF(s_1\cdots s_j) \otimes \FF^{st}(s_{j+1}\cdots s_n)$ to 
$\FF(s_1 \cdots s_{j+1}) \otimes \FF^{st}(s_{j+2}\cdots s_n)$. 
Thus  the composite morphism 
$\; \Psi_s =   J_{n-1} \circ J_{n-2} \circ \cdots \circ J_1  $
is a morphism 
\[
%J_{n-1} \circ J_{n-2} \circ \cdots \circ J_1 
\Psi_s : \FF^{st}(s) \rightarrow \FF(s).
\]
We set $\Psi_{\One_\Cc} = J_0$ where $J_0$ is as in Remark~\ref{rem:J0}. 


\newcommand{\FFF}{\FF^{st}}

\begin{example}

Consider a case in which the number of generators $p=1$ (such as $\Cc =\Bcat$ from (\ref{de:Bcat})), 
and $\Ob(\Dd) $ is $\langle 1 \rangle = (\N_0, +) \;$ (such as $\Dd = \Mat^N$ from (\ref{de:MatN})). 
Consider also $\FF(1) =1$ (essentially, note, WLOG).
Then $\FFF(0)=0$, 
$\FFF(1) = \FF(1)$,  
$\FFF(11) = \FF(1) \otimes \FF(1)\cong \FF(1\otimes 1 )= \FF(11)$ --- note that if $\Dd$ is skeletal then this is necessarily an equality.
\end{example}

\begin{proposition}\label{pr:strictifyingmonfuns}
Let $\Cc = (\Cc, \otimes, \One_\Cc)$, and $\Dd = (\Dd,\otimes, \One_\Dd)$ be strict monoidal categories.
Suppose that 
$\Ob(\catC)$ is a free monoid
on 
$\{ X_1, X_2, \ldots, X_p \}$. 
Let $(\FF,J)$ be a monoidal functor  
from $\Cc$ to $\Dd$
as in (\ref{def:monoidal functor}).
 Then\begin{enumerate}
     \item[(I)]
the object map $\FF^{st}$ and the morphism map given on each morphism 
 $f: X \rightarrow Y$ in $\Cc$ by 
 $\FF^{st}(f) =  \Psi^{-1}_{Y} \FF(f) \Psi_{X} $ yields a strict monoidal functor 
 $\FF^{st} : \Cc \rightarrow \Dd$. 
\item[(II)] The morphisms $\Psi_{X}$ assemble to a natural isomorphism from $\FF^{st}$ to $(\FF,J)$. 
\end{enumerate}
\end{proposition}

\begin{proof}
(I)
It    follows directly from the fact that $\FF$ is a functor, that $\FF^{st}$ yields a strict monoidal  functor.
 %  Thus, $\F^{st}$ is a strict monoidal functor.
   \\ (II)
    It is also straightforward to check that the $\Psi_X$ assemble to a natural  %transformation 
    isomorphism from $\FF^{st}$ to $\FF$.
\end{proof}


