\documentclass[twocolumn,floatfix]{aastex63}
\usepackage{algorithm}
\usepackage{verbatim}
\usepackage{hyperref}
\usepackage{xspace} % so we don't have to type {} after empty commands
\xspaceaddexceptions{]\}}

\begin{document}

\title{Explaining ultra-massive quiescent galaxies at $3 < z < 5$ in the context of their environments}
\correspondingauthor{Christian Kragh Jespersen}
\email{ckragh@princeton.edu}

\author[0000-0002-8896-6496]{Christian Kragh Jespersen}
\affiliation{Department of Astrophysical Sciences, Princeton University, Princeton, NJ 08544, USA}

\author[0000-0002-1482-5818]{Adam C. Carnall}
\affiliation{Institute for Astronomy, University of Edinburgh, Royal Observatory, Edinburgh, EH9 3HJ, UK}

\author[0000-0001-7964-5933]{Christopher C. Lovell}
\affiliation{Institute of Cosmology and Gravitation, University of Portsmouth, Burnaby Road, Portsmouth, PO1 3FX, UK}

\begin{abstract}

The swift assembly of the earliest galaxies poses a significant challenge to our understanding of galaxy formation. Ultra-massive quiescent galaxies at intermediate redshifts ($3 < z < 5$) currently present one of the most pressing problems for theoretical modeling, since very few mechanisms can be invoked to explain how such galaxies formed so early in the history of the Universe. Here, we exploit the fact that these galaxies all reside within significant overdensities to explain their masses. To this end, we construct and release a modified version of the Extreme Value Statistics (EVS) code which takes into account galaxy environment by incorporating clustering in the calculation. With this new version of EVS, we find that ultra-massive quiescent galaxies at $3<z<5$ do not present as serious a tension with simple models of galaxy formation when the analysis of a given galaxy is conditioned on its environment.
\end{abstract}

\keywords{Galaxies (573) --- Galaxy Formation (595) --- High-Redshift Galaxies (734) --- Astrostatistics (1882)}


\section{Introduction}
\label{sec:intro}

The James Webb Space Telescope is currently pushing the limits of galaxy formation theory. The discoveries of not only ultra-high redshift galaxies, but also extremely massive quiescent galaxies at $3 < z < 5$, imply that a surprisingly large amount of star formation took place at very early times \citep[e.g.,][]{Carnall2023_CEERS_Quiescent_Gals, Carnall2023_nature_GS9209,Valentino23_quiescentAtlas, Carniani2024_JADES-GS-z14-0, Glazebrook2024_highmass_quiescent_galaxy, deGraaf_highz_massive_quiescent}. Many possible explanations have been invoked \textit{post-hoc}, including highly bursty star formation, changes to $\Lambda$CDM, and artificially elevated star-formation efficiencies \citep{Dekel2023_bursts, Lovell2023_EVS, Endsley_2024_bursty_highz}. 

While bursty star formation seems like a promising explanation for observations of ultra-high redshift galaxies \citep{Mason2023_MUV_scatter}, it is irrelevant for inferring the masses of quiescent galaxies. Quiescent galaxies therefore present a unique opportunity for isolating other effects. This has resulted in suggestions that star formation efficiencies (SFE) must either be close to 100\%, or that modifications to the well-understood physics of halo formation would be necessary \citep{Carnall2024_EXCELS, Glazebrook2024_highmass_quiescent_galaxy}.

However, previous analyses of early ultra-massive quiescent galaxies have so far ignored the well-known fact that low redshift and simulated massive quiescent galaxies reside in overdense environments \citep{Frenk1988_halo_LCDM, Norberg2002_2CdF_clustering}, a relation which seems to continue even at high redshift, as massive quiescent galaxies observed with \textit{JWST} appear to preferentially populate overdensities \citep{Valentino23_quiescentAtlas, Jin2024_cosmic_vine, Ito2024_size_stellar_mass, Morishita2025_JWST_clusters}.

For example, the broadly used Extreme Value Statistics (EVS) approach of \cite{Lovell2023_EVS} assumes that all galaxies exist in a perfectly average field with no clustering. Another approach, presented by \cite{Jespersen2025_CV_highz}, marginalizes over the environment, since the environments of ultra-high redshift galaxies are rarely known. However, at intermediate redshifts, we may obtain strong constraints on the type of overdensity in which ultra-massive quiescent galaxies reside \citep{Overzier2016_protocluster_review}. These overdense environments require corrections to EVS \citep{davis_most_2011}. Here, we therefore explicitly include the dependence on overdensity in the EVS calculation of the probability distribution for the mass of the most massive galaxy observed in a given survey volume. We apply our model to three ultra-massive quiescent galaxies discovered with \textit{JWST} in the CANDELS UDS field.

\section{Data}
\label{sec:data}

\begin{figure*}
    \centering
    % Top figure spanning the full width
    \includegraphics[trim={18.5cm 6cm 1cm 30cm},clip, width=0.98\linewidth]{overdensity_overviews.png}
    % Row of two figures below
    \begin{minipage}{0.475\linewidth}
        \centering
        \includegraphics[trim={9.5cm 4.3cm 1cm 13.0cm},clip, width=\linewidth]{overdensity0_zoom2.png}
    \end{minipage}
    \hfill
    \begin{minipage}{0.475\linewidth}
        \centering
        \includegraphics[trim={9.5cm 4.3cm 1cm 13.0cm},clip, width=\linewidth]{overdensity1_zoom2.png}
    \end{minipage}
    \caption{\textbf{Top:} The 3D distribution of galaxies at $3 < z < 5$ with spectroscopic redshifts within the PRIMER UDS area. Strong clustering is visible, with two prominent overdensities (marked in grey). The overdensities host ultra-massive galaxies (blue stars), which have been proposed to challenge galaxy formation models. 
    \textbf{Bottom:} Further identification of possible concentrated and extended overdensities. 
    \textbf{Left:} Two possible $z\approx4.62$ volumes that could define the overdensity that PRIMER-EXCELS-109760/117560 exist in. The volumes are roughly 1.5 orders of magnitude apart.
    \textbf{Right:} Two possible $z\approx3.21$ volumes that could define the overdensity that ZF-UDS-7329 exists in. The volumes are roughly an order of magnitude apart. }
    \label{fig:EXCELS_overdensity}
\end{figure*}

In this work, we consider the objects discussed in \cite{Carnall2024_EXCELS} in the UDS field. They discuss three especially problematic galaxies: ZF-UDS-7329 at $z$=3.195 with log$_{10}(M_*/\mathrm{M_\odot})\simeq11.1$ (\citealt{Schreiber2018, Nanayakkara2024, Glazebrook2024_highmass_quiescent_galaxy}), PRIMER-EXCELS-109760 ($z=4.622$), and PRIMER-EXCELS-117560 ($z=4.621$), both with log$_{10}(M_*/\mathrm{M_\odot})\simeq11$ and newly reported by \cite{Carnall2024_EXCELS}. The relatively involved EXCELS selections are detailed in \S 3 of \cite{Carnall2024_EXCELS}, with \S 3.2.1 being of particular importance to the selection of the main galaxies of interest here.

To investigate the environments of these objects, we compile a list of available spectroscopic redshifts in the UDS field within the PRIMER survey area from $3 < z < 5$ as follows. We begin with the EXCELS spectroscopic redshift catalogue presented in \cite{Carnall2024_EXCELS}. We then supplement this with the DJA NIRSpec graded v3 compilation \citep{Heintz2024,deGraaff2025}, using only redshifts with a grade of 3. We supplement these with the compilation of pre-\textit{JWST} spectroscopic redshifts from \cite{Begley2025}.

The resulting distribution of objects with reliable spectroscopic redshifts in the PRIMER UDS field from $3 < z < 5$ is shown in Figure \ref{fig:EXCELS_overdensity}, with the three objects discussed in \cite{Carnall2024_EXCELS} highlighted in blue.

\section{Methods}
\label{sec:methods}

To calculate the mass of the most massive galaxy conditioned on density, a few steps must be taken. We quickly summarize these steps, and expand on them in the following subsections.

\begin{enumerate}
    \item The volumes of the overdensities must be identified (see \S \ref{subsec:overdensity_ID}).
    \item A mapping from the total possible number of such volumes in a given survey ($\mathrm{N_{\delta}}$) to a distribution of overdensities must be established. This is most easily done by estimating the \textit{density percentile} ($\mathrm{u_\delta}$) of a given overdensity (see \S \ref{subsec:sigma_delta_max}).
    \item Stellar mass functions dependent on density percentile, SMF($\mathrm{u_\delta}$), must be constructed (see \S \ref{subsec:model} and Figure \ref{fig:demo_fig}). 
\end{enumerate}

For each SMF($\mathrm{u_\delta}$), EVS can be used to estimate $\mathrm{P(M_{max}|u_{\delta}})$. $\mathrm{P(M_{max}|u_{\delta}})$ can then be multiplied with $P(\mathrm{u_\delta}|N_{\delta})$ to give us the final estimate of $\mathrm{P(M_{max}|N_{\delta}})$. 

\subsection{Overdensity identification}
\label{subsec:overdensity_ID}

Visual inspection of Figure \ref{fig:EXCELS_overdensity} indicates that the three galaxies of interest reside in overdensities. PRIMER-EXCELS-109760/117560 are close in mass and reside in the same overdensity. ZF-UDS-7329 is significantly more massive than other galaxies belonging to its overdensity.

We fit the size of each overdensity by fitting a spheroidal volume. The spheroidal shape is motivated by theoretical work on clusters and protoclusters in large N-body simulations \citep{Lovell2018_protocluster}. We determine the three major axes of each overdensity by considering the minimum volume enclosing ellipsoid (MVEE) for each overdensity. The volume is grown until there is a clear break in the number of galaxies included, which then defines our \textit{fiducial} overdensity regions. The measurements of the overdensities are presented in Table \ref{tab:overdensity_size}, and visually depicted in Figure \ref{fig:EXCELS_overdensity}. 

However, determining the volume of an overdensity is notoriously tricky. No matter the method, we will always need to make a subjective choice on where to draw a boundary in a continuous density field. Therefore, we also include the measured radii for an \textit{extended overdensity region} where we ignore the first ``gap'' between the central, fiducial overdensity and its surroundings, and grow the overdensity until we again encounter a sharp drop in galaxy number count. These extended overdensities are visually depicted in the bottom row of Figure \ref{fig:EXCELS_overdensity}, and their measurements are likewise included in the bottom section of Table \ref{tab:overdensity_size}. The extended volumes are typically an order of magnitude higher than the fiducial volumes, but, as will be shown in \S \ref{sec:results}, the volume uncertainty has limited influence on our results.

