\title[Chase-and-Run and Chirality in Nonlocal Models of Pattern Formation]{Chase-and-Run and Chirality in Nonlocal Models of Pattern Formation}

\author*[1]{\fnm{Thomas Jun} \sur{Jewell}}\email{jewell@maths.ox.ac.uk}

\author[2]{\fnm{Andrew L.} \sur{Krause}}\email{andrew.krause@durham.ac.uk}

\author[1]{\fnm{Philip} \sur{K. Maini}}\email{maini@maths.ox.ac.uk}

