\appendix 

\section{Dnoidal waves in V-systems}
\label{appendix:Vdnoidal}
\subsection{Two-color fields}

This appendix extends Sec.~\ref{section:twostate} to the case considered in Sec.~\ref{section:V}, namely that of two fields addressing a 3-level system in a V configuration. As usual in this context, we refer to one of these fields as the probe field and to the other as the coupling field. The former and the latter couple the ground state (state~1) to two different excited states (respectively state~2 and state~3). We neglect homogeneous broadening throughout this appendix. We therefore assume that these two excited states are stable over the time scale considered in this work.

We start by deriving the equations of motion for this particular case.
We describe each of the two fields by a real electric field vector, namely ${\bf E}_{\rm p}({\bf r},t)$ for the probe field and ${\bf E}_{\rm c}({\bf r},t)$ for the coupling field, the total electric field at position ${\bf r}$ and time $t$ being ${\bf E}({\bf r},t)$ with
\begin{equation}
    {\bf E}({\bf r},t) = 
{\bf E}_{\rm p}({\bf r},t) +
{\bf E}_{\rm c}({\bf r},t).
\label{eq:appEtot}
\end{equation}
We assume that these two fields are both linearly polarized and co-propagate in a same direction, and set
\begin{align}
{\bf E}_{\rm p}({\bf r},t) &= \frac{1}{2}\, \hat{\text{\boldmath{$\epsilon$}}}_{\rm p}\, {\cal E}_{\rm p}(z,t)
\exp[-i\omega_{\rm p}(t - z/c)] + \mbox{c.c.},\\
{\bf E}_{\rm c}({\bf r},t) &= \frac{1}{2}\, \hat{\text{\boldmath{$\epsilon$}}}_{\rm c}\, {\cal E}_{\rm c}(z,t)
\exp[-i\omega_{\rm c}(t - z/c)] + \mbox{c.c.},
\end{align}
with real unit polarization vectors $\hat{\text{\boldmath{$\epsilon$}}}_{\rm p}$ and $\hat{\text{\boldmath{$\epsilon$}}}_{\rm c}$.
Correspondingly, we make the following ansatz for the medium polarization,
\begin{align}
{\bf P}({\bf r},t) = & \frac{1}{2}\,\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \, {\cal P}_{\rm p}({z},t)
\exp[-i\omega_{\rm p}(t - z/c)] + \nonumber \\
& \frac{1}{2}\,\hat{\text{\boldmath{$\epsilon$}}}_{\rm c} \, {\cal P}_{\rm c}({z},t)
\exp[-i\omega_{\rm c}(t - z/c)]
 + \mbox{c.c.}
\end{align}
Eq.~(\ref{eq:propap}) then generalizes to a pair of wave equations,
\begin{align}
\frac{\partial {\cal E}_{\rm p}}{\partial z} + \frac{1}{c}
\frac{\partial {\cal E}_{\rm p}}{\partial t} &= \frac{i\omega_{\alpha}}{2\epsilon_0 c}\,{\cal P}_{\rm p}(z,t), \label{eq:apppropap}\\
\frac{\partial {\cal E}_{\rm c}}{\partial z} + \frac{1}{c}
\frac{\partial {\cal E}_{\rm c}}{\partial t} &= \frac{i\omega_{\alpha}}{2\epsilon_0 c}\,{\cal P}_{\rm c}(z,t).\label{eq:apppropac}
\end{align}
These two equations are coupled to each other through the dependence of ${\cal P}_{\rm p}({z},t)$ and ${\cal P}_{\rm c}({z},t)$ on both ${\cal E}_{\rm p}(z,t)$ and ${\cal E}_{\rm c}(z,t)$.

As in Sec.~\ref{section:theory}, we treat the coupling of the atoms with the fields within the electric dipole approximation, make the rotating wave approximation and pass to slowly varying variables. This results in the Hamiltonian
\begin{align}
&\hat{H}({z},t) = - \hbar \Delta_{\rm p}|2 \rangle \langle 2 | - \hbar \Delta_{\rm c} | 3 \rangle \langle 3| \nonumber \\
 &\; -(\hbar/2) \big[\Omega_{\rm p}(z,t)
|2\rangle\langle 1| + \Omega_{\rm c}(z,t) |3 \rangle\langle 1| + \mbox{h.c.}\,\big],
\label{eq:appH}
\end{align}
with
\begin{equation}
    \Omega_{\rm p}(z,t) =
{\cal E}_{\rm p}(z,t)\,\langle\, 2\, |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 1\rangle/\hbar
\label{eq:appOmegap}
\end{equation}
and
\begin{equation}
    \Omega_{\rm c}(z,t) =
{\cal E}_{\rm c}(z,t)\,\langle\, 3\, |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm c} \cdot \hat{\bf D} \,|\, 1\rangle/\hbar,
\label{eq:appOmegac}
\end{equation}
where $\hat{\bf D}$ is the dipole operator. We assume that the fields are on resonance in the absence of any Doppler shift. The detunings $\Delta_{\rm p}$ and $\Delta_{\rm c}$ may nonetheless differ from zero if Doppler broadening is included in the calculation: for atoms with a velocity $u_z$ in the $z$-direction, 
\begin{equation}
    \Delta_{\rm p} = -\omega_{\rm p}u_z/c, \qquad \Delta_{\rm c} = -\omega_{\rm c}u_z/c.
\end{equation}
In terms of the coherences $\rho_{21}(z,t)$ and  $\rho_{31}(z,t)$, which are respectively equal to
$\langle 2 | \hat{\rho}(z,t) | 1 \rangle$
and $\langle 3 | \hat{\rho}(z,t) | 1 \rangle$, where $\hat{\rho}(z,t)$ is the density operator for this 3-state system,
\begin{align}
    {\cal P}_{\rm p}(z,t) &= 2 N_{\rm d} \, 
    \langle\, 1\, |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 2\, \rangle\, \rho_{21}(z,t),
\label{eq:apppolp}\\
{\cal P}_{\rm c}(z,t) &= 2 N_{\rm d} \, 
    \langle\, 1\, |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm c} \cdot \hat{\bf D} \,|\, 3\, \rangle\, \rho_{31}(z,t).
\label{eq:apppolc}
\end{align}
As in Sec.~\ref{section:theory}, $N_d$ denotes the medium number density. 
Combining these last two equations with Eqs.~(\ref{eq:apppropap}), (\ref{eq:apppropac}), (\ref{eq:appOmegap}) and (\ref{eq:appOmegac}) gives
\begin{align}
  \frac{\partial \Omega_{\rm p}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm p}}{\partial t} &= i \mu_{\rm p} \,
    \rho_{21}(z,t) \label{eq:appOmegappropa}\\
 \frac{\partial \Omega_{\rm c}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm c}}{\partial t} &= i \mu_{\rm c} \,
    \rho_{31}(z,t), \label{eq:appOmegacpropa}
\end{align}
where $\mu_{\rm p}$ and $\mu_{\rm c}$ are the respective propagation coefficients:
\begin{align}
    \mu_{\rm p} &= \frac{\omega_{\rm p}N_{\rm d}}{\hbar \epsilon_0 c}\, |\langle 2 |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 1\, \rangle|^2, \\
 \mu_{\rm c} &= \frac{\omega_{\rm c}N_{\rm d}}{\hbar \epsilon_0 c}\, |\langle 3 |\,
\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 1\, \rangle|^2.
\end{align}

It has long been recognized that these equations can be solved analytically when $\mu_{\rm p} = \mu_{\rm c}$, in the absence of relaxation and as long as inhomogeneous broadening is negligible or can be taken to be described by a same distribution function $g(\Delta)$ for both fields. (In the case of Doppler broadening, the latter is possible only if their frequencies are sufficiently close.) The solutions relevant to this paper are derived in the rest of this appendix.


\subsection{The Maxwell-Bloch equations without homogeneous broadening}
As noted in Sec.~\ref{section:theory}, calculating the density operator $\hat{\rho}(z,t)$ involves calculating the velocity-specific density operators $\hat{\rho}_v(x,t,u_z)$ for all the relevant velocity classes. 
Since we neglect homogeneous broadening here, we set
\begin{equation}
\hat{\rho}_v(z,t,u_z) \equiv |\Psi(z,t)\rangle\langle \Psi(z,t)|
\end{equation}
with
\begin{equation}
    |\Psi(z,t)\rangle = c_1(z,t)|1\rangle + c_2(z,t) |2\rangle + c_3(z,t) |3 \rangle,
\end{equation}
where the coefficients $c_1(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ are complex functions such that
\begin{equation}
    |c_1(z,t)|^2 + |c_2(z,t)|^2 + |c_3(z,t)|^2 = 1.
\end{equation}
Like $\hat{\rho}_v({\bf r},t,u_z)$,
the state vector $|\Psi(z,t)\rangle$ and the functions $c_1(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ depend on $u_z$ as well as on $z$ and $t$.
Given Eq.~(\ref{eq:appH}), these coefficients and the two fields evolve in time according to the equations
\begin{subequations}
\label{eq:allB3}
\begin{align}
i& \frac{\partial c_1}{\partial t} = -\frac{1}{2}\, \Omega_{\rm p}^*(z,t) c_2(z,t)  -\frac{1}{2}\, \Omega_{\rm c}^*(z,t) c_3(z,t), \label{eq:B3a}\\
i& \frac{\partial c_2}{\partial t} = -\Delta_{\rm p} c_2(z,t) -\frac{1}{2}\, \Omega_{\rm p}(z,t) c_1(z,t), \label{eq:B3b}\\
i& \frac{\partial c_3}{\partial t} = -\Delta_{\rm c} c_3(z,t) -\frac{1}{2}\, \Omega_{\rm c}(z,t) c_1(z,t), \label{eq:B3c}\\
&    \frac{\partial \Omega_{\rm p}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm p}}{\partial t} = 
\nonumber \\ & \qquad \qquad
i \mu_{\rm p} \, \int_{-\infty}^{\infty} f_{}(u_z)\,
    c_2(z,t)c_1^*(z,t)\, {\rm d}u_z, \label{eq:B3d}\\
&   \frac{\partial \Omega_{\rm c}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm c}}{\partial t} =
\nonumber \\ & \qquad \qquad
i \mu_{\rm c} \, \int_{-\infty}^{\infty} f_{}(u_z)\,
    c_3(z,t)c_1^*(z,t)\, {\rm d}u_z. \label{eq:B3e}
\end{align}
\end{subequations}
%where $\mu_{\rm p}$ and $\mu_{\rm c}$ are the respective propagation coefficients:
%\begin{subequations}
%\begin{align}
%    \mu_{\rm p} &= \frac{\omega_{\rm p}N_{\rm d}}{\hbar \epsilon_0 c}\, |\langle 2 |\,
%\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 1\, \rangle|^2, \\
% \mu_{\rm c} &= \frac{\omega_{\rm c}N_{\rm d}}{\hbar \epsilon_0 c}\, |\langle 3 |\,
%\hat{\text{\boldmath{$\epsilon$}}}_{\rm p} \cdot \hat{\bf D} \,|\, 1\, \rangle|^2.
%\end{align}
%\end{subequations}
Eqs.~(\ref{eq:allB3}a)--(\ref{eq:allB3}e) do not have an analytical solution when $\Delta_{\rm p} \not= \Delta_{\rm c}$. As is commonly done, we will assume from now on that
\begin{equation}
    \Delta_{\rm p} = \Delta_{\rm c} = \Delta.
    \label{eq:Delta}
\end{equation}
This condition amounts to taking $\omega_{\rm p} = \omega_{\rm c} = \omega$ and is fulfilled only approximately for the systems for which numerical results are presented in this article. We note, however, that this condition is unnecessary if inhomogeneous broadening is neglected, in which case the equations (\ref{eq:allB3}a)--(\ref{eq:allB3}e) reduce to the following system:
\begin{subequations}
\label{eq:allB6}
\begin{align}
i& \frac{\partial c_1}{\partial t} = -\frac{1}{2}\, \Omega_{\rm p}^*(z,t) c_2(z,t)  -\frac{1}{2}\, \Omega_{\rm c}^*(z,t) c_3(z,t), \\
i& \frac{\partial c_2}{\partial t} = -\frac{1}{2}\, \Omega_{\rm p}(z,t) c_1(z,t), \\
i& \frac{\partial c_3}{\partial t} = -\frac{1}{2}\, \Omega_{\rm c}(z,t) c_1(z,t), \\
&  \frac{\partial \Omega_{\rm p}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm p}}{\partial t} = i \mu_{\rm p} \,
    c_2(z,t)c_1^*(z,t)\\
&  \frac{\partial \Omega_{\rm c}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{\rm c}}{\partial t} = i \mu_{\rm c} \,
    c_3(z,t)c_1^*(z,t).
\end{align}
\end{subequations}

It follows from Eqs.~(\ref{eq:allB3}a)--(\ref{eq:allB3}e) and (\ref{eq:Delta}) that
\begin{subequations}
\label{eq:conservation_nobr}
\begin{align}
\frac{\partial |\Omega_{\rm p}|^2}{\partial z}
+\frac{1}{c}\,
\frac{\partial |\Omega_{\rm p}|^2}{\partial t}
    &= -2 \mu_{\rm p} \int_{-\infty}^\infty \frac{\partial |c_2|^2}{\partial t}\,g(\Delta)\,{\rm d}\Delta,\\
    \frac{\partial |\Omega_{\rm c}|^2}{\partial z}
+\frac{1}{c}\,
\frac{\partial |\Omega_{\rm c}|^2}{\partial t}
    &= -2 \mu_{\rm c} \int_{-\infty}^\infty \frac{\partial |c_3|^2}{\partial t}\,g(\Delta)\,{\rm d}\Delta,
\end{align}
\end{subequations}
where we treat the coefficients $c_2(z,t)$ and $c_3(z,t)$ as functions of $\Delta$ rather than $u_z$ and, as in Sec.~\ref{section:theory},
\begin{align}
    g_{}(\Delta) & \equiv (c/\omega)f_{}(-c \Delta / \omega).
\end{align}

We consider solutions which depend on $z$ and $t$ only through the dimensionless variable $(t - z/v)/\tau$, where $v$ and $\tau$ are two constants. For such solutions,
\begin{subequations}
\label{eq:conservation_eta}
\begin{align}
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    \frac{\partial |\Omega_{\rm p}|^2}{\partial t}
    &= 2 \mu_{\rm p} \int_{-\infty}^\infty \frac{\partial |c_2|^2}{\partial t}\,g(\Delta)\,{\rm d}\Delta,\\
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    \frac{\partial |\Omega_{\rm c}|^2}{\partial t}
    &= 2 \mu_{\rm c} \int_{-\infty}^\infty \frac{\partial |c_3|^2}{\partial t}\,g(\Delta)\,{\rm d}\Delta.
\end{align}
\end{subequations}
In the case of soliton-like solutions, for which $\Omega_{\rm p}(z,t)$, $\Omega_{\rm c}(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ vanish for $t \rightarrow \pm \infty$, but not in the case of dnoidal wave solutions, these last two equations imply that
\begin{subequations}
\label{eq:conservation_integrated}
\begin{align}
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    |\Omega_{\rm p}(z,t)|^2
    &= 2 \mu_{\rm p} \int_{-\infty}^\infty |c_2(z,t)|^2\,g(\Delta)\,{\rm d}\Delta,\\
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    |\Omega_{\rm c}(z,t)|^2
    &= 2 \mu_{\rm c} \int_{-\infty}^\infty |c_3(z,t)|^2\,g(\Delta)\,{\rm d}\Delta.
\end{align}
\end{subequations}
We also note that when inhomogeneous broadening is neglected,
Eqs.~(\ref{eq:conservation_nobr}a)--(\ref{eq:conservation_nobr}b) reduce to
\begin{subequations}
\begin{align}
\frac{\partial |\Omega_{\rm p}|^2}{\partial z}
+\frac{1}{c}\,
\frac{\partial |\Omega_{\rm p}|^2}{\partial t}
    &= -2 \mu_{\rm p}  \frac{\partial |c_2|^2}{\partial t},\\
    \frac{\partial |\Omega_{\rm c}|^2}{\partial z}
+\frac{1}{c}\,
\frac{\partial |\Omega_{\rm c}|^2}{\partial t}
    &= -2 \mu_{\rm c} \frac{\partial |c_3|^2}{\partial t},
\end{align}
\end{subequations}
Eqs.~(\ref{eq:conservation_eta}a)--(\ref{eq:conservation_eta}b) reduce to
\begin{subequations}
\begin{align}
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    \frac{\partial |\Omega_{\rm p}|^2}{\partial t}
    &= 2 \mu_{\rm p} \frac{\partial |c_2|^2}{\partial t},\\
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    \frac{\partial |\Omega_{\rm c}|^2}{\partial t}
    &= 2 \mu_{\rm c} \frac{\partial |c_3|^2}{\partial t},
\end{align}
\end{subequations}
and Eqs.~(\ref{eq:conservation_integrated}a)--(\ref{eq:conservation_integrated}b) reduce to \cite{Bolshov1982b}
\begin{subequations}
\begin{align}
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    |\Omega_{\rm p}(z,t)|^2
    &= 2 \mu_{\rm p} |c_2(z,t)|^2,\\
    \left(  
    \frac{1}{v} - \frac{1}{c}\right)
    |\Omega_{\rm c}(z,t)|^2
    &= 2 \mu_{\rm c} |c_3(z,t)|^2.
\end{align}
\end{subequations}

\subsection{Equal propagation coefficients}

The above equations can be solved in closed form when the propagation coefficients $\mu_{\rm p}$ and $\mu_{\rm c}$ are equal. In particular, setting
\begin{equation}
\mu_{\rm p} = \mu_{\rm c} = \mu.
\label{eq:equal_mus}
\end{equation}
makes it possible to seek solutions of either Eqs.~(\ref{eq:allB3}a)--(\ref{eq:allB3}e) or Eqs.~(\ref{eq:allB6}a)--(\ref{eq:allB6}e) for which the two fields are in a constant ratio, i.e., solutions for which
\begin{equation}
    \Omega_{\rm p}(z,t) \equiv r \Omega_{\rm c}(z,t),
\end{equation}
where $r$ is a real constant. For instance, setting $c_2(z,t) \equiv r c_3(z,t)$ and passing to the dependent variables $a(z,t)$, $b(z,t)$ and $\Omega(z,t)$ such that $c_1(z,t) \equiv a(z,t)$, $c_3(z,t) \equiv b(z,t)/(1 + r^2)^{1/2}$ and
$\Omega_{\rm c}(z,t) \equiv \Omega(z,t)/(1 + r^2)^{1/2}$ reduces Eqs.~(\ref{eq:allB6}a)--(\ref{eq:allB6}e) to the following system, which describes the propagation of a single field in a 2-level medium \cite{Rahman}:
    \begin{subequations}
\label{eq:all2stnoinh}
\begin{align}
i& \frac{\partial a}{\partial t} = -\frac{1}{2}\, \Omega_{}^*(z,t) b(z,t),\\
i& \frac{\partial b}{\partial t} = -\frac{1}{2}\, \Omega_{}(z,t) a(z,t),\\
&    \frac{\partial \Omega_{}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{}}{\partial t} =
i \mu\,
    b(z,t)a^*(z,t).
    \end{align}
\end{subequations}
Taking $a(z,t)$, $b(z,t)$ and $\Omega(z,t)$ to correspond to the sech-soliton solution of this last system of equations yields Konopnicki and Eberly's sech-simulton solution for a V-system \cite{Rahman}. Other choices are also possible. In particular, the dnoidal solution is obtained by taking
\begin{subequations}
\label{eq:allB11}
\begin{align}
    a(z,t) &= -\mbox{sn}(\eta,k)\\
    b(z,t) &= i\,\mbox{cn}(\eta,k),\\
    \Omega(z,t) &= \Omega_0 \, \mbox{dn}(\eta,k),
\end{align}
\end{subequations}
where
\begin{equation}
    \eta = (t-z/v)/\tau
\end{equation}
with
\begin{equation}
\frac{1}{v} = \frac{1}{c} + \frac{\mu\tau^2}{2 k^2}
\end{equation}
and
\begin{equation}
\label{eq:taunew}
    \tau = 2 / \Omega_0.
\end{equation}
The corresponding Rabi frequencies for the probe and the coupling fields %$\Omega_{\rm p}(z,t)$ and $\Omega_{\rm c}(z,t)$, 
are, respectively,
$\Omega_{{\rm p}0} \, \mbox{dn}(\eta,k)$ and $\Omega_{{\rm c}0} \, \mbox{dn}(\eta,k)$ with
\begin{equation}
\sqrt{\Omega^2_{{\rm p}0} + \Omega^2_{{\rm c}0}} = \Omega_0.
\end{equation}
This solution corresponds to the twin pair of co-propagating dnoidal waves described by Eqs.~(\ref{eq:vdnoidal}), (\ref{eq:25}), (\ref{eq:26}) and (\ref{eq:tau2colour}). It is a particular case of a still more general solution found for V-systems in the absence of any broadening mechanism \cite{Hioe1994}. Taking $k \rightarrow 1$ yields
the simulton solution of
Konopniki and Eberly \cite{Kono81}, namely ${\Omega}_{\rm p}(z,t) = 
    {\Omega}_{{\rm p}0}\,\mbox{sech}(\eta)$
and ${\Omega}_{\rm c}(z,t) = 
    {\Omega}_{{\rm c}0}\,\mbox{sech}(\eta)$.
%The speed at which such simultons propagate, $v$, is related to their temporal width $\tau$ in the same way as for a single sech-soliton. This speed is the same for the two fields even though $\Omega_{{\rm p}0}$ may differ from $\Omega_{{\rm c}0}$.

Similarly, expressing Eqs.~(\ref{eq:allB3}a)--(\ref{eq:allB3}e) in terms of the coefficients $a(z,t)$ and $b(z,t)$ and of the Rabi frequency $\Omega(z,t)$ reduces these equations to the system 
\begin{subequations}
\label{eq:all2st}
\begin{align}
i& \frac{\partial a}{\partial t} = -\frac{1}{2}\, \Omega_{}^*(z,t) b(z,t),\\
i& \frac{\partial b}{\partial t} = -\Delta_{} b(z,t) -\frac{1}{2}\, \Omega_{}(z,t) a(z,t),\\
&    \frac{\partial \Omega_{}}{\partial z} + \frac{1}{c}\,\frac{\partial \Omega_{}}{\partial t} = 
\nonumber \\ & \qquad \qquad
i \mu \, \int_{-\infty}^{\infty} g{}(\Delta)
    b(z,t)a^*(z,t)\, {\rm d}\Delta.
    \end{align}
\end{subequations}
The dnoidal solution is now given by the following equations, where $X(\eta)$, $Y(\eta)$ and $Z(\eta)$ are the functions defined by Eqs.~(8b)--(8d) of Ref.~\cite{Crisp1969}:
\begin{subequations}
\label{eq:allB11withinhbr}
\begin{align}
    a(z,t) &= \sqrt{[1 - Z(\eta)]/2}\; \exp[i\alpha(\eta)],\\
    b(z,t) &= 
    \sqrt{[1+Z(\eta)]/2}\; \exp[i\beta(\eta)],\\
    \Omega(z,t) &= \Omega_0 \, \mbox{dn}(\eta,k),
\end{align}
\end{subequations}
with \cite{noteaboutCrisp1969}
\begin{align}
    \alpha(\eta) &= \pi + \int_0^\eta \frac{X(\eta')\,\mbox{dn}(\eta',k)}{1-Z(\eta')}\,{\rm d}\eta'
\end{align}
and
\begin{align}
\beta(\eta) &= \alpha(\eta) - \arctan[Y(\eta)/X(\eta)] + \pi.
\end{align}
The time parameter $\tau$ is still given by Eq.~(\ref{eq:taunew}), and $\Omega(z,t)$ is still given by Eq.~(\ref{eq:allB11}c), but $v$ is now defined by
Eq.~(\ref{eq:vdnoidalib}) of Sec.~\ref{section:theory}. 

The coefficients $c_1(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ and the electric field amplitudes ${\cal E}_{\rm p}(z,t)$ and ${\cal E}_{\rm c}(z,t)$ so defined depend on $z$ and $t$ only through the variable $\eta$. These five functions are periodic in $\eta$ with period $2K(k)$. They are thus periodic in $t$ with period $2\tau K(k)$ and in $z$ with period $2v\tau K(k)$, and the coefficients $c_1(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ oscillate in phase across all the velocity classes. The two fields also satisfy the area relation
\begin{align}
&\sqrt{
    \left[\int_{-\tau K(k)}^{\tau K(k)} \Omega_{\rm p}(z,t)\, {\rm d}t\right]^2 + 
    \left[\int_{-\tau K(k)}^{\tau K(k)} \Omega_{\rm c}(z,t)\, {\rm d}t\right]^2 
    }  = 2\pi,
\end{align}
which generalizes a similar relation applying only to single sech-simultons, i.e.,
\begin{align}
&\sqrt{
    \left[\int_{-\infty}^{\infty} \Omega_{\rm p}(z,t)\, {\rm d}t\right]^2 + 
    \left[\int_{-\infty}^{\infty} \Omega_{\rm c}(z,t)\, {\rm d}t\right]^2 
    }  = 2\pi.
\end{align}

This dnoidal wave solution does not exhaust the possibilities. For instance, a cnoidal wave solution would be obtained by setting
\begin{equation}
    \Omega(z,t) = \Omega_0\,\mbox{cn}(\eta,k)
\end{equation}
and taking the functions $X(\eta)$, $Y(\eta)$ and $Z(\eta)$ appearing in the above equations to be those defined by Eqs.~(16b)--(16d) of Ref.~\cite{Crisp1969}. In the absence of inhomogeneous broadening, V-systems also support the propagation of pairs of fields for which both $\Omega_p(z,t)$ and $\Omega_c(z,t)$ are linear combinations of a cn function and a dn function but are not in a constant ratio \cite{Hioe1994}. Solutions of this latter type have no counterpart in two-level systems and might not exist for Doppler-broadened systems.

\subsection{Unequal propagation coefficients}
\label{appendix:unequal}

Whether inhomogeneous broadening is taken into account or not, $\Omega_{\rm p}(z,t)$ and $\Omega_{\rm c}(z,t)$ cannot be obtained in closed form without further approximation if the propagation coefficients $\mu_{\rm p}$ and $\mu_{\rm c}$ are unequal.
Exact results applicable to the case where $\mu_{\rm p} \not= \mu_{\rm c}$ are scarce. To the best of our knowledge, they are limited to the following relations, which pertain to the soliton-like solutions of Eqs.~(\ref{eq:allB6}a)--(\ref{eq:allB6}e) \cite{Bolshov1982b}:
\begin{subequations}
\label{eq:Bolshov}
\begin{align}
    \Omega_{\rm c}(z,t) &= \Omega_{{\rm c}0} \exp[\xi(\eta)], \\
   \Omega_{\rm p}(z,t) &= \Omega_{{\rm p}0} \exp[\gamma\xi(\eta)],  
\end{align}
\end{subequations}
where $\xi(\eta)$ is a certain function of $\eta$ (not known in closed form) which goes to zero for $\eta \rightarrow \pm \infty$ and
\begin{equation}
\gamma = (\mu_{\rm p}/\mu_{\rm c})^{1/2}.
\label{eq:gammadefined}
\end{equation}
This system can thus support twin pulses co-propagating indefinitely even when the two propagation coefficients are different, with the probe pulse being longer (shorter) than the coupling pulse if $\gamma < 1$ ($ > 1$). Unfortunately, these results are of limited applicability here, as their derivation assumes that $\Omega_{\rm p}(z,t)$, $\Omega_{\rm c}(z,t)$ and the coefficients $c_j(z,t)$ depend on $z$ and $t$ only through the variable $\eta$ defined above, with constant values of $v$ and $\tau$, and that $\Omega_{\rm p}(z,t)$,  $\Omega_{\rm c}(z,t)$, $c_2(z,t)$ and $c_3(z,t)$ vanish for $t \rightarrow -\infty$. The first assumption excludes the transients studied in this work, for which the effective pulse velocity is not constant. The second excludes stationary dnoidal waves. Also, it seems unlikely that these results can be generalized to the inclusion of inhomogeneous broadening.

However, solving the Maxwell-Bloch equations analytically for a V-system with $\mu_{\rm p} \not= \mu_{\rm c}$ is possible for zero inhomogeneous broadening if one assumes that the probe field is too weak to affect the propagation of the coupling field. To the best of our knowledge, this was first done by Kozlov, Polynkin, and Scully, for a pair of fields co-propagating as a sech-simulton \cite{Kozlov1999}. In the following, we generalize their calculation to the case where both fields co-propagate as dnoidal waves, although working in terms of wave functions rather than populations and coherences. The approach followed here may not be applicable to cases where inhomogeneous broadening needs to be taken into account.

Besides ignoring all broadening mechanisms, the key approximation is to replace Eq.~(\ref{eq:allB6}a) by
\begin{subequations}
\label{eq:newB3a}
\begin{equation}
    i \frac{\partial c_1}{\partial t} =  -\frac{1}{2}\, \Omega_{\rm c}^*(z,t) c_3(z,t).
\end{equation}
\end{subequations}
Eqs.~(\ref{eq:allB6}c), (\ref{eq:allB6}e) and (\ref{eq:newB3a}a) can then be solved separately from Eqs.~(\ref{eq:allB6}b) and
(\ref{eq:allB6}d), to obtain the dnoidal solution
\begin{subequations}
\label{eq:couplingfield}
\begin{align}
    c_1(z,t) &= -\mbox{sn}(\eta,k)\\
    c_3(z,t) &= i\,\mbox{cn}(\eta,k),\\
    \Omega_{\rm c}(z,t) &= \Omega_{{\rm c}0} \, \mbox{dn}(\eta,k), \label{eq:Omegacappendix}
\end{align}
\end{subequations}
here with $\tau$ and $v$ defined by the equations
\begin{equation}
    \tau = 2/\Omega_{{\rm c}0}
\end{equation}
and
\begin{equation}
\frac{1}{v} = \frac{1}{c} + \frac{\mu_{\rm c}\tau^2}{2 k^2}.
\label{eq:newv}
\end{equation}
In turn, we seek a solution of Eqs.~(\ref{eq:allB6}b) and
(\ref{eq:allB6}d) which depends on $z$ and $t$ only through the variable $\eta$. Combining these two equations gives
\begin{align}
    &\left(\frac{1}{c} - \frac{1}{v}\right)\, \frac{1}{\tau}\,
    \frac{{\rm d} \Omega_{\rm p}}{{\rm d} \eta} = \nonumber \\
    &\quad- \frac{1}{2}\,\mu_{\rm p}\,c_1^*(\eta) \tau \left[ \int_{\eta_0}^\eta \Omega_{\rm p}(\eta')c_1(\eta')\,{\rm d}\eta' + C\,\right],
\end{align}
where $\eta_0$ is a constant and $C = -2i c_2(\eta_0)/\tau$.
That is, in view of Eq.(\ref{eq:newv}) and the fact that $c_1(\eta)$ is real,
\begin{equation}
\frac{{\rm d}\Omega_{\rm p}}{{\rm d}\eta} =
\gamma^2 k^2 c_1(\eta) \left[\int_{\eta_0}^\eta \Omega_{\rm p}(\eta')c_1(\eta')\,{\rm d}\eta' + C\,\right],
\end{equation}
or, after rearrangement, differentiation and division by $c_1(\eta)$,
\begin{equation}
\frac{1}{c_1(\eta)}\,\frac{{\rm d} \;}{{\rm d} \eta} \frac{1}{c_1(\eta)}
    \frac{{\rm d}\Omega_{\rm p}}{{\rm d}\eta} = \gamma^2 k^2 \Omega_{\rm p}(\eta).
    \label{eq:transformed}
\end{equation}
At this stage, we introduce a function $x(\eta)$ such that
\begin{equation}
    \frac{{\rm d}x}{{\rm d}\eta} = c_1(\eta),
\label{eq:B42}
\end{equation}
and write $\Omega_{\rm p}$ as a function of $x$ rather than a function of $\eta$. Given that $c_1(\eta) = -\mbox{sn}(\eta,k)$ here, 
\begin{equation}
    x(\eta) = \frac{1}{k}\,
    \left\{ \log \left[\frac{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)}{k'}\right]\right\} + C',
\end{equation}
where $C'$ is a constant and
\begin{equation}
k' = \sqrt{1-k^2}.    
\end{equation}
It can be shown that the function $\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)$ is positive 
for any $\eta$ when $0 \leq k < 1$ and varies monotonically on the interval $0 \leq \eta \leq 2K(k)$. We therefore
exclude the limiting case of $k=1$ from our analysis and, for the time being, restrict ourselves to seeking a solution of Eq.~(\ref{eq:transformed}) on that interval of values of $\eta$. Rewriting this equation in terms of the variable $x$ yields
\begin{equation}
    \frac{{\rm d}^2\Omega_{\rm p}}{{\rm d}^2x} = 
    \gamma^2 k^2 \Omega_{\rm p}(x).
\end{equation}
Thus
\begin{align}
    \Omega_{\rm p}(\eta) = 
    &\; C_+ \left[\frac{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)}{k'} \right]^{\gamma} + \nonumber \\ 
    &\; C_- \left[\frac{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)}{k'} \right]^{-\gamma},
\label{eq:Omegapweak1}
\end{align}
where $C_+$ and $C_-$ are two constants.
Eq.~(\ref{eq:Omegapweak1}) can also be written as
\begin{align}
    \Omega_{\rm p}(\eta) = 
    & \; C_{+} \left[\frac{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)}{k'} \right]^{\gamma} + \nonumber \\
    & \; C_{-} \left[\frac{\mbox{dn}(\eta,k)-k\,\mbox{cn}(\eta,k)}{k'} \right]^{\gamma}
\label{eq:Omegapweak2}
\end{align}
in view of the identity
\begin{equation}
    \frac{k'}{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)} =
    \frac{\mbox{dn}(\eta,k)-k\,\mbox{cn}(\eta,k)}{k'}.
\end{equation}
Since $\mbox{dn}(\eta,k)$ is periodic in $\eta$ with period $2K(k)$ whereas $\mbox{cn}[\eta+2K(k),k] = \mbox{cn}(\eta,k)$, continuing as a periodic function of $\eta$ with the same period as $\Omega_{\rm c}(\eta)$ requires that $C_+=C_-$. Thus
\begin{align}
    \Omega_{\rm p}(z,t) &= \Omega_{{\rm p}0}\left\{\left[{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)} \right]^{\gamma} \right. \nonumber \\
    &\qquad \qquad \left. + \left[{\mbox{dn}(\eta,k)-k\,\mbox{cn}(\eta,k)} \right]^{\gamma}\right\}/2^\gamma
\label{eq:Omegapweak3}
\end{align}
with $\Omega_{{\rm p}0} = (2/k')^\gamma C_+$. It then follows from Eqs.~(\ref{eq:allB6}b) and (\ref{eq:B42}) that
\begin{align}
    c_2(z,t) &= -i (\Omega_{{\rm p}0}/\Omega_{{\rm c}0})\left\{\left[{\mbox{dn}(\eta,k)+k\,\mbox{cn}(\eta,k)} \right]^{\gamma} \right. \nonumber \\
    &\qquad \left. - \left[{\mbox{dn}(\eta,k)-k\,\mbox{cn}(\eta,k)} \right]^{\gamma}\right\}/(2^\gamma \gamma k).
\end{align}
These results are consistent with those obtained above for $\gamma=1$, bearing in mind that we assume that $\Omega_{{\rm p}0} \ll \Omega_{{\rm c}0}$ here.
As illustrated by Fig.~\ref{fig:comparison}, $\Omega_{\rm p}(z,t)$ oscillates with the same period and the same phase as $\Omega_{\rm c}(z,t)$ even when $\gamma \not= 1$.
We also note that
\begin{equation}
    \Omega_{\rm p}(z,t) \rightarrow \Omega_{{\rm p}0}\,[\mbox{sech}(\eta)]^\gamma
\end{equation}
in the limit $k \rightarrow 1$, in agreement both with Eq.~(36) of Ref.~\cite{Kozlov1999} and with Eqs.~(\ref{eq:Bolshov}a) and
(\ref{eq:Bolshov}b) above.
\begin{figure}[t]
    \centering
    \includegraphics[width=0.48\textwidth]{comparison.png}
    \caption{The ratio $\Omega^2_{\rm p}/\Omega^2_{{\rm p}0}$ (solid curve) and the ratio $\Omega^2_{\rm c}/\Omega^2_{{\rm c}0}$ (dashed curve) for $k = 0.6$ and $\gamma = 0.7$ as calculated from Eqs.~(\ref{eq:Omegacappendix}) and (\ref{eq:Omegapweak3}).}
    \label{fig:comparison}
\end{figure}



