% model reduction nuclear mRNA
%---------------------------------------------

%-------------------------------------------------
% Proposition
%-------------------------------------------------

\begin{proposition}
\label{prop_pro_FF}

Let $FF^P_{s}$ denote the Fano factor of protein number fluctuations with $G$ gene states. Under the assumption that the timescale of protein species is significantly larger than the timescales of all other species, the ssLNA predicts that in the steady state,
%
\begin{equation}
\label{pro_FF}
\begin{aligned}
    FF^P_{s}=1&+\frac{\lambda_1}{2\lambda}+\frac{\lambda_1}{2\lambda}\frac{e_{G-1}(k_2^2,...,k_G^2)(k_{\rm{off}}^2+2k_{\rm{off}}(k_{\rm{on}}+k_1))+k_{\rm{on}}^2e_{G-1}(k_1^2,...,k_G^2)}{(k_{\rm{off}}e_{G-1}(k_2,...,k_G)+k_{\rm{on}}e_{G-1}(k_1,...,k_G))^2},
\end{aligned}
\end{equation}
%
where $\lambda$ is the cytoplasmic mRNA degradation rate, and $\lambda_1$ is the protein production rate. The Fano factor of protein number fluctuations is always larger than $1$ and independent of the number of mRNA processing steps in the nucleus ($S$) and the cytoplasm ($R$). Note that for the special case $G=1$, this reduces to the much simpler result
%
\begin{equation}
   FF^P_{s}|_{G=1}= 1+\frac{\lambda_1}{\lambda}+\frac{\lambda_1}{\lambda}\frac{ k_{\rm{off}}k_1}{(k_{\rm{off}}+k_{\rm{on}})^2},
\end{equation}
%
which is precisely the same as that obtained using the standard three-stage model of gene expression ($U_{0} \xrightleftharpoons[k_{\rm{off}}]{k_{\rm{on}}} U_{1}\xrightarrow{k_1} U_1 + M, M \xrightarrow{\lambda} \varnothing,  M \xrightarrow{\lambda_1} M + P,  P\xrightarrow{\lambda_2}\varnothing$), when the timescale of protein fluctuations is much larger than of mRNA and gene fluctuations~\cite{shahrezaei2008analytical}. Generally, it can be shown that $FF^P_{s}|_{G=1} \ge FF^P_{s}$, implying that the three-state model overestimates the Fano factor of protein noise.
\end{proposition}

\noindent\textit{\textbf{Sketch of the derivation of Proposition~\ref{prop_pro_FF}.}} Similar to the proof of  Proposition~\ref{prop_cmrna_cov}, using the ssLNA one can write a reduced Lyapunov equation of the form
%
\begin{equation}\label{pro_lyp}
    \mathbf{J}_s^P \mathbf{C}_s^P+\mathbf{C}_s^P[\mathbf{J}_s^P]^T+\mathbf{D}_s^P=0,    
\end{equation}
%
where $\mathbf{C}_s^P$ is the covariance of protein number fluctuations (that we need to solve for), $\mathbf{J}_s^P$ is the reduced Jacobian matrix and $\mathbf{D}_s^P$ is the reduced diffusion matrix. Note that since in this case we only have one slow variable, all matrices in the Lyapunov equation reduce to scalars. The reduced Jacobian and diffusion matrices are given by
%
\begin{equation}
\label{pro_Jacob}
\begin{aligned}
    \mathbf{J}_s^P=-\lambda_2,
\end{aligned}
\end{equation}
%
and
%
\begin{equation}\label{pro_diff}
\begin{aligned}
    \mathbf{D}_s^P=&\frac{\lambda_1}{\lambda}\times\left(\frac{e_{G-1}(k_2^2,...,k_G^2)(k_{\rm{off}}^2+2k_{\rm{off}}(k_{\rm{on}}+k_1))+k_{\rm{on}}^2e_{G-1}(k_1^2,...,k_G^2)}{(k_{\rm{off}}e_{G-1}(k_2,...,k_G)+k_{\rm{on}}e_{G-1}(k_1,...,k_G))^3}\right)\\
    &\times e_{G+1}(k_{\rm{on}},k_1,...,k_G)+\biggl(\frac{\lambda_1^2}{\lambda}+\lambda_1\biggr)[M_1^C]+\lambda_2[P].
\end{aligned}
\end{equation}
%
The substitution of Eq.~(\ref{pro_Jacob}) and Eq.~(\ref{pro_diff}) into the Lyapunov equation Eq.~(\ref{pro_lyp}) immediately leads to the solution
%
\begin{equation}
    \mathbf{C}_s^P=\frac{\mathbf{D}_s^P}{2\lambda_2}.
\end{equation}
%
The Fano factor can then be calculated using the formula $\mathbf{C}_s^P/[P]$ where $[P]$ is given by Eq.~\eqref{mean}. For details of the calculations, see Appendix~\ref{app_pro_FF}.

%-------------------------------------------------
% Corollary
%------------------------------------------------
\begin{corollary}
\label{cor_pro_thre}
%
The Fano factor of protein $FF^P_{s}$ varies with respect to $k_{\rm{off}}$ according to the following three cases. 

\begin{itemize}
   \item Case 1: When $k_1>k_1^\star$ and $k_{\rm{on}}>k_{\rm{on},2}^\star$, the Fano factor $FF^P_{s}$ decreases until it reaches the critical point $k_{\rm{off},1}$ and then increases, eventually approaching $1+\frac{\lambda_1}{\lambda}$ from below.

   \item Case 2: When $k_1\leq k_1^\star$ and $k_{\rm{on}}\geq k_{\rm{on},1}^\star$ or $k_1>k_1^\star$ and $k_{\rm{on},1}^\star\leq k_{\rm{on}}\leq k_{\rm{on},2}^\star$, the Fano factor $FF^P_{s}$ monotonically increases, eventually approaching $1+\frac{\lambda_1}{\lambda}$ from below. 

   \item Case 3: When $k_{\rm{on}}< k_{\rm{on},1}^\star$, the Fano factor $FF^P_{s}$ first increases until it reaches the critical point $k_{\rm{off},1}$ and then decreases, eventually approaching $1+\frac{\lambda_1}{\lambda}$ from above.
\end{itemize}
%
Definitions for $k_1^\star$, $k_{\rm{on},1}^\star$, $k_{\rm{on},2}^\star$ and $k_{\rm{off},1}$ have been introduced in Corollary~\ref{cor_cmrna_cases}. The proof can be found in Appendix~\ref{app_pro_cases}.
\end{corollary}

%-------------------------------------------------
% Corollary
%------------------------------------------------
\begin{corollary}
\label{cor_pro_min}

The minimum of $FF^P_s$ is obtained by taking the limit of $k_1=k_2=...=k_G=k$ and $k_{\rm{off}}=0$, and is given by
%
\begin{equation}
    \label{FFPmin}
    \lim_{\substack{k_1=...=k_G=k \\ k_{\rm{off}}= 0}}FF^P_{s}=1+\frac{\lambda_1}{2\lambda}+\frac{\lambda_1}{2\lambda}\frac{k_{\rm{on}}^2Gk^{2(G-1)}}{k_{\rm{on}}^2G^2k^{2(G-1)}}=1+\frac{\lambda_1}{2\lambda}+\frac{\lambda_1}{2\lambda G}.
\end{equation}
\end{corollary}

\noindent\textit{\textbf{Proof of Corollary~\ref{cor_pro_min}}.} It follows from Corollary~\ref{cor_pro_thre} that when varying $k_{\rm{off}}$, the minimum is achieved at $k_{\rm{off}}=0$ in cases 2 and 3. We then fix $k_{\rm{off}}=0$, and show that the Fano factor achieves the minimum at $k_1=k_2=...=k_G=k$. In that case, the Fano factor is given by
%
\begin{equation}
\begin{aligned}
    FF^P_{s}\left|_{k_{\rm{off}=0}}\right.&=1+\frac{\lambda_1}{\lambda}-\frac{\lambda_1}{\lambda}\frac{e_{G}(k_1,...,k_G)e_{G-2}(k_1,...,k_G)}{e_{G-1}(k_1,...,k_G)^2}\\
    &\geq 1+\frac{\lambda_1}{\lambda}-\frac{\lambda_1}{\lambda}\frac{G-1}{2G}\\
    &=1+\frac{\lambda_1}{2\lambda}+\frac{\lambda_1}{2\lambda G}.
\end{aligned}
\end{equation}
%
where Newton's inequality Eq.~(\ref{FFcmrna_Newton}) was used in the second row. From here, it follows that the minimum is when $k_1=k_2=...=k_G=k$.

In case 1, we do not have explicit proof that the minimum is smaller than the global minimum $1+\frac{\lambda_1}{2\lambda}+\frac{\lambda_1}{2\lambda G}$, therefore we checked this for many parameter values. We computed the Fano factor for two groups of parameters using the theoretical result. $G=3$ was fixed in group 1, $G=4$ was fixed in group 2, and each group contained $10000$ points. Other parameter values were selected from the interval $(0.1,100)$ with the constraint $k_1>k_1^\star$ and $k_{\rm{on}}>k_{\rm{on},2}^\star$ which forces case 1 (see Corollary~\ref{cor_pro_thre}). For every pair of $\lambda$ and $\lambda_1$ values, the Fano factor was found to be larger than Eq.~\eqref{FFPmin} thus suggesting that this expression provides the global minimum for all three cases.~$\square$

\section{Confirmation of analytic results using stochastic simulations}
\label{sims}

In this section, we confirm our main theoretical results using stochastic simulations with the SSA~\cite{gillespie1977exact}. In Fig.~\ref{fig2} and Fig.~\ref{fig3}, we confirm the results of queueing theory and in Fig.~\ref{fig:modred} we confirm the results obtained using model reduction. We next discuss these figures in detail. 

\subsection{Queueing theory} 

In Fig.~\ref{fig2}(a), we compare the Fano factor of the total nuclear mRNA $FF_{G,S}^{N}$ computed from Eq.~(\ref{FF-N-G-S}) using Lemma~\ref{lemma_H-function} and Proposition~\ref{prop_B-1-time} to the one computed from stochastic simulations. Each point in Fig.~\ref{fig2}(a) corresponds to one set of model parameters. The number of gene states $G$ and the number of nuclear RNA states $S$ were fixed to $2$, whereas other parameters were selected randomly to achieve variation of the timescale separation parameter $\Lambda^{G,N}$ (see Definition~\ref{def_timescales}) over four orders of magnitude between $0.01$ and $100$. The agreement between theory and simulations shows that our result for the Fano factor is valid irrespective of the timescale separation parameter. 

In Fig.~\ref{fig2}(b), we use a parallel coordinates plot to explore how the Fano factor of the total nuclear mRNA for $G=2$ and $S=2$ depends on the model parameters $k_{\text{off}}$, $k_{\text{on}}$, $k_1$, $k_2$, $\delta$ and $\delta_1$. Each vertical line in Fig.~\ref{fig2}(b) represents one model parameter ($k_{\text{off}}, k_{\text{on}}, k_1, k_2, \delta, \delta_1$), except the last vertical line, which represents the Fano factor $FF_{G,S}^{N}$. Hence, one set of connected line segments across all vertical lines represents one parameter set, ending at the value of the Fano factor for that set. The line segments in the parallel coordinates plot suggest that high values of $FF_{G,S}^{N}$ are achieved when $k_{\text{off}}\gg k_{\text{on}}$, whereas low values of $FF_{G,S}^{N}$ are achieved when $k_{\text{off}}\ll k_{\text{on}}$. 

\begin{figure}[hp]
    \centering
    \includegraphics[width=1.0\textwidth]{Fig2.pdf}
    \caption{\label{fig2} \textbf{Testing the accuracy of the queueing theory’s predictions for the  
    Fano factor of the total nuclear mRNA and its sensitivity with respect to rate parameters}. (a) Comparison of the Fano factor obtained using results in Section~\ref{qtheory} and the stochastic simulation algorithm (SSA). Each point corresponds to one combination of parameters values. $\Lambda^{G,N}$ is the time separation parameter defined in Definition (\ref{def_timescales}). (b) Parallel coordinates plot showing how different values of model parameters lead to different values of the Fano factor $FF_{G,S}^{N}$. (c)-(k) Local sensitivity analysis for three groups of randomly chosen parameter sets, as explained in the main text: (c)-(e) is for Group $1$ ($FF_{G,S}^{N}<1$), (f)-(h) is for Group $2$ ($FF_{G,S}^{N}\approx 1$), and (i)-(k) is for Group $3$ ($FF_{G,S}^{N}>1$). (e), (h) and (k) are correlation matrices of the (local) logarithmic sensitivity defined in Eq.~(\ref{correlation-matrix-delta}). In all cases in this figure, we have fixed $G=2$ and $S=2$. See main text for parameter values.}
\end{figure}

To explore this more systematically, we randomly selected $3000$ parameters that were grouped into three groups. Group 1 contained 1000 parameters sets in which the values of $k_{\text{off}}$ were selected from the interval $(0.1,10)$, whereas the values of $k_{\text{on}}, k_1$ and $k_2$ were selected from the interval $(10,100)$. Hence, in this group $k_{\text{off}}\ll k_{\text{on}},k_1,k_2$. The values of the Fano factor in this group were consistently below $1$, as shown in  Fig.~\ref{fig2}(c). Group 2 contained 1000 parameter sets with all parameters selected from the interval $(0.1,100)$, hence without \textit{a priori} restriction on the values of $k_{\text{on}}$ and $k_{\text{on}}$. Interestingly, the Fano factor in this group was sharply peaked around $1$, see Fig.~\ref{fig2}(f). Finally, Group 3 contained 1000 parameter sets in which the values of $k_{\text{off}}, k_1$ and $k_2$ were selected from the interval $(10,100)$, whereas the values of $k_{\text{on}}$ were selected from the interval $(0.1,1)$. Hence, in this group $k_{\text{off}}\gg k_{\text{on}}$, which yielded values of the Fano factor that were typically larger than $1$ (Fig.~\ref{fig2}(i)). In all three groups $\delta$ and $\delta_1$ were selected from the interval $(0.1,100)$, i.e. without further restrictions compared to other variables. These results corroborate our understanding from the parallel coordinates plot in Fig.~\ref{fig2}(b) that high values of $FF_{G,S}^{N}$ are achieved when $k_{\text{off}}\gg k_{\text{on}}$, whereas low values of $FF_{G,S}^{N}$ are achieved when $k_{\text{off}}\ll k_{\text{on}}$. 

Next, we wanted to understand how sensitive is the Fano factor $FF_{G,S}^{N}$ with respect to each of the model parameters. For each of the three aforementioned groups of parameters sets, we performed local sensitivity analysis by computing the (local) logarithmic sensitivity $\Delta(x)$~\cite{ingalls2008sensitivity} defined as,
%
\begin{equation}
    \label{Delta}
    \Delta(x)=\frac{x}{FF_{G,S}^N}\frac{\partial FF_{G,S}^N}{\partial x},
\end{equation}
%
where $x$ is any of the model parameters $k_{\text{off}}$, $k_{\text{on}}$, $k_1$, $k_2$, $\delta$ and $\delta_1$. The value of $\Delta(x)$ means that a change of $1$\% in $x$ causes a change of $\Delta(x)$\% in $FF_{G,S}^N$. Figs.~\ref{fig2} (d), (g) and (j) show box plots of $\Delta(x)$ for the three groups of parameters sets ($1$-$3$, respectively). On average, the values of $\Delta(x)$ are relatively small ($<0.1$) in all three groups, except for $\Delta(k_{\text{off}})$ and $\Delta(k_1)$ in Group 3, which are around $-0.36$ and $0.4$, respectively. 

Next, we explored how the values of $\Delta(x)$ correlate between each other for different choice of $x$. In Figs.~\ref{fig2} (e), (h) and (k), we plotted the correlation matrix
%
\begin{equation}
    \label{correlation-matrix-delta}
    \rho_{x,y}=\frac{\langle \Delta(x)\Delta(y)\rangle-\langle\Delta(x)\rangle\langle\Delta(y)}{\sqrt{\langle\Delta^2(x)\rangle-\langle\Delta(x)\rangle^2}\sqrt{\langle\Delta^2(y)\rangle-\langle\Delta(y)\rangle^2}}
\end{equation}
%
where $x$ and $y$ are any of the model parameters $k_{\text{off}}$, $k_{\text{on}}$, $k_1$, $k_2$, $\delta$ and $\delta_1$. In Group 1 ($FF_{G,S}^N<1$), there is a strong negative correlation between the pairs $\Delta(k_{\text{off}})$ and $\Delta(k_{\text{on}})$, $\Delta(k_1)$ and $\Delta(k_2)$, and $\Delta(\delta)$ and $\Delta(\delta_1)$ (Fig.~\ref{fig2}(e)). In contrast, there is almost no correlation between either $\Delta(\delta)$ or $\Delta(\delta_1)$ and the rest of $\Delta(x)$ for $x=k_{\text{off}}, k_{\text{on}}, k_1, k_2$. This means that the change in $FF_{G,S}^N$ due to a change in either $\delta$ or $\delta_1$ is practically independent of the change in $FF_{G,S}^N$ due to a change in any of the remaining parameters $k_{\text{off}}, k_{\text{on}}, k_1$ and $k_2$. Hence, the sets of parameters $\{\delta,\delta_1\}$ and $\{k_{\text{off}}, k_{\text{on}}, k_1, k_2\}$ can be considered as ``control knobs" for changing the value of the Fano factor, which may be of interest in synthetic biology. In the other two groups, the correlations in general increase and in some cases are even reversed. For example, $\Delta(k_{\text{off}})$ and $\Delta(k_{\text{on}})$ are negatively correlated in Group 1, but are positively correlated in Group 3. Similarly, $\Delta(\delta)$ and $\Delta(\delta_1)$ are negatively correlated in Group 1, but are positively correlated in Group 3. The least correlated pair of parameters in these two groups is $(k_1,k_2)$. 

