\subsection{Geometric and Dynamical Properties of Conjugate and Focal Points}\label{sec-ncp} 
The dynamics of geodesic flows are intimately connected to the behavior of Jacobi fields. For any geodesic $\gamma$ in a Riemannian manifold $M$, a Jacobi field $J$ along geodesics $\gamma$ satisfies $J'' + R(\gamma', J)\gamma' = 0$, using the horizontal and vertical decomposition. Jacobi fields encode the dynamics of the geodesic flow via $d\phi^t_\theta(\xi) = (J_\xi(t), J'_\xi(t))$, where $J_{\xi}(t)$ denotes the unique Jacobi field along $\gamma_{\theta}(t)$ such that $J_{\xi}(0) = d\pi_{\theta}(\xi)$ and $J'_{\xi}(0) = \mathcal{K}_{\theta}(\xi)$ (see \cite{Pa} for more details).
\noindent A manifold has \emph{no conjugate points} if no geodesic has non-trivial Jacobi fields vanishing at two points, and \emph{no focal points} if $\|J\|^2$ grows strictly for $t > 0$ when $J(0) = 0$, $J'(0) \neq 0$. The latter implies the former.  

For Anosov flows on compact/finite-volume manifolds, the absence of conjugate points was proven in \cite{Klin, Ma}, later extended to infinite volume cases under bounded curvature assumptions in \cite{IR3}. The \emph{Green subbundles} $G^{s/u}_\theta \subset T_\theta SM$, defined for manifolds without conjugate points, consist of vectors whose Jacobi fields remain bounded as $t \to \pm \infty$. If $\dim M = n$, then $\dim G^{s/u}_\theta = n-1$. Continuous dependence on $\theta$ holds when $M$ has no focal points (\cite{Ebe}), and the Anosov condition reduces to $G^s_\theta \cap G^u_\theta = \{0\}$ and $G^*_{\theta} = E^{*}_{\theta}$, where $ * = s, u$ (see \cite{Ebe} for more details on Green subbundles).





%\subsubsection{Jacobi fields} 

\subsubsection{Jacobi Tensors and Riccati Equation}\label{Jacobi Tensors}
Let $\gamma_\theta$ be a geodesic with parallel orthonormal frame $\{V_1(t),...,V_{n-1}(t),\gamma_\theta'(t)\}$. The Jacobi equation for orthogonal vector fields takes the matrix form:
\[
Y''(t) + R(t)Y(t) = 0,
\]
where $R(t)$ is the curvature endomorphism on $N(\phi^t(\theta)) := \gamma_\theta'(t)^\perp$.


The \emph{Riccati equation} for the geodesic flow is:
\begin{equation}\label{Riccati}
U'(t) + U^2(t) + R(t) = 0,
\end{equation}
where $U(t):N(\phi^t(\theta))\to N(\phi^t(\theta))$ is self-adjoint.


The unstable and stable solutions $U_{\theta,u}(t)$ and $U_{\theta,s}(t)$ arise from Jacobi tensors:
\[
U_{\theta,*}(t) = {Y}'_{\theta,*}(t)Y_{\theta,*}^{-1}(t),\quad *\in\{u,s\}
\]
where $Y_{\theta,*}(t)$ are the unstable/stable Jacobi tensors.\\

When the curvature is bounded below by $-c^2$, then (see \cite{Green} and \cite{Ebe})
\begin{equation}\label{EQ-Green}
\max\{\|U_{\theta, s}(t)\|, \|U_{\theta, u}(t)\|\}\leq c.
\end{equation}

When the sectional curvature is negative bounded above, that is, there is a positive constant $b$ such that $K\leq -b^2$, then (cf. \cite{Ebe} and \cite{Kn})
\begin{equation}\label{ec4.8}
\langle U_{\theta,u}(t)x,x\rangle\geq b\langle x,x\rangle
\end{equation}
and
\begin{equation*}
\langle U_{\theta,s}(t)x,x\rangle\leq -b\langle x,x\rangle,
\end{equation*}
for all $t\in \mathbb{R}$.



\subsubsection{Lyapunov Exponents}
The symmetric solutions $U_{\theta,u}(t)$ and  $U_{\theta,s}(t)$ encode all Lyapunov exponents information for the Green subbundles. Precisely, given $\theta\in SM$ and $\xi \in T_{\theta}SM$, the associated \emph{Lyapunov exponent} is defined as 
\[
\chi(\theta, \xi) := \lim_{t \to \infty} \frac{1}{t} \log \|D\phi^t_{\theta}(\xi)\|,
\]
when the limit exists.

For any invariant probability measure $\mu$, Oseledets' Theorem \cite{Osel} ensures the existence of Lyapunov exponents on a full $\mu$-measure set $\Lambda \subset SM$. In the case of Anosov geodesic flows on finite-volume / non-compact manifolds, this existence result extends via \cite{CR}.


The Lyapunov exponents \(\chi(\theta, \cdot)\) are represented as \(\chi^u(\theta, \cdot)\) and \(\chi^s(\theta, \cdot)\) for the unstable and stable Green subbundles, respectively. When \(M\) has no conjugate points, \(\chi^u(\theta, \cdot)\) is non-negative, while \(\chi^s(\theta, \cdot)\) is non-positive.







Moreover, for manifolds without conjugate points (see \cite{MF, IR2})
\begin{equation}\label{EQ-Form-Lyp-Exp}
\chi^{+}(\theta):=\lim_{t \to \infty} \frac{1}{t} \log |\det|D\phi^t_{\theta}|_{G^u_{\theta}}| = \lim_{t \to \infty} \frac{1}{t} \int_{0}^{t} \mathrm{tr}\,U_{\theta,u}(s)ds.
\end{equation}



\subsubsection{Ricci Curvature and Lyapunov Exponents}

The \emph{Ricci Curvature} in a point $(x,v)\in SM$  is defined as the following average (see \cite{doCarmo})
$$\text{Ric}(x,v)=\frac{1}{n-1}\sum_{i=1}^{n-1}R(v,v_i,v, v_i),$$
where $\{v, v_1, \dots, v_{n-1}\}$ is a orthonormal basis of $T_{x}M$.

So, using the notation of the Section \ref{Jacobi Tensors}, this becomes: 
$$\text{Ric}(\phi^t_{M}(\theta))=\frac{\text{tr}R(t)}{n-1},$$
where $\text{tr}R(t)$ denotes trace of $R(t)$.\\
From Cauchy-Schwarz inequality, the symmetry of $U_{\theta,u}(t)$,  (\ref{EQ-Green}), and (\ref{EQ-Form-Lyp-Exp}) we can take the trace and integration of the Riccati equation (\ref{Riccati}) yields the fundamental inequality   
$$\chi^{+}(\theta):=\lim_{t \to \infty} \frac{1}{t} \log |\det|D\phi^t_{\theta}|_{G^u_{\theta}}|\leq (n-1)\sqrt{-\lim_{t\to \infty}\frac{1}{t}\int_{0}^{t}\text{Ric}(\phi^s_{M}(\theta))ds}.$$
as established in \cite[Lemma 3.6]{IR2}.


\section{Estimative of Lyapunov Exponents}
For each $\theta\in SM$ we denote the asymptotic upper and lower Ricci averages:  $$\Gamma_{R}^{+}(\theta)= \displaystyle \limsup_{t\to +\infty}\frac{1}{t}\int_{0}^{t}\text{Ric}(\phi^t(\theta))ds \,\,\text{and}\,\, 
\Gamma_{R}^{-}(\theta)= \displaystyle \liminf_{t\to \infty}\frac{1}{t}\int_{0}^{t}\text{Ric}(\phi^t(\theta))ds$$
By the Birkhoff Ergodic Theorem, for any invariant measure $\mu$, these limits coincide $\mu$-almost everywhere, \emph{i.e.},  $$\Gamma_{R}^{+}(\theta)=\Gamma_{R}^{-}(\theta), \,\,\text{for}\,\, \mu\text{-a.e.} \,\, \theta\in SM.$$

\begin{lem}\label{L1NEW}
Let $M$ be a manifold without focal points and curvature bounded below by $-c^2$. For any $\theta\in SM$ where $\chi^{+}(\theta)$ exists,
\begin{equation}\label{EQ0NEW}
-(n-1)\frac{\Gamma_{R}^{+}(\theta)}{c} \leq \chi^{+}(\theta) \leq (n-1)\sqrt{-\Gamma_{R}^{-}(\theta)}.
\end{equation}
\end{lem}

\begin{proof}
Let $U_{\theta,u}(t)$ be the unstable Riccati solution associated to the unstable Jacobi tensor. Since $M$ has no focal points and curvature bounded below by $-c^2$, the symmetric operator $U_{\theta,u}(t)$ has eigenvalues satisfying $0 \leq \lambda_1(t) \leq \cdots \leq \lambda_{n-1}(t) \leq c$. This implies:
\begin{equation}\label{EQ1NEW}
\mathrm{tr}\,U_{\theta,u}^2(t) = \sum_{i=1}^{n-1} \lambda_i^2(t) \leq c\sum_{i=1}^{n-1} \lambda_i(t) = c\,\mathrm{tr}\,U_{\theta,u}(t).
\end{equation}

Taking the trace of the Riccati equation \eqref{Riccati} and integrating yields:
\begin{align*}
0 &= \frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U'_{\theta,u}(s)\,ds + \frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U^2_{\theta,u}(s)\,ds + \frac{n-1}{t}\int_{0}^{t} \mathrm{Ric}(\phi^{s}(\theta))\,ds \\
&= \frac{\mathrm{tr}\,U_{\theta,u}(t) - \mathrm{tr}\,U_{\theta,u}(0)}{t} + \frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U^2_{\theta,u}(s)\,ds + (n-1)\frac{1}{t}\int_0^t \mathrm{Ric}(\phi^s(\theta))\,ds.
\end{align*}


From \eqref{EQ-Green}, \eqref{EQ-Form-Lyp-Exp}, and (\ref{EQ1NEW}) we obtain the lower bound:
\begin{align*}
-(n-1)\Gamma_{R}^{+}(\theta) &= \liminf_{t\to +\infty} \frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U^2_{\theta,u}(s)\,ds \\
&\leq c \liminf_{t\to +\infty} \frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U_{\theta,u}(s)\,ds = c\,\chi^{+}(\theta),
\end{align*}
proving the left inequality in \eqref{EQ0NEW}.

For the upper bound, we apply the Cauchy-Schwarz inequality and the trace inequality for symmetric operators:
\begin{equation*}
(\mathrm{tr}\,U_{\theta,u}(s))^2 \leq (n-1)\,\mathrm{tr}\,U^2_{\theta,u}(s)).
\end{equation*}
This gives:
\begin{align*}
\frac{1}{t}\int_{0}^{t} \mathrm{tr}\,U_{\theta,u}(s)\,ds &\leq \sqrt{\frac{1}{t}\int_{0}^{t} (\mathrm{tr}\,U_{\theta,u}(s))^2\,ds} \\
&\leq \sqrt{\frac{n-1}{t}\int_{0}^{t} \mathrm{tr}\,U^2_{\theta,u}(s))\,ds}.
\end{align*}
Taking limits and using \eqref{EQ-Green}, \eqref{EQ-Form-Lyp-Exp} yields:
\begin{equation}\label{EQLN1}
\chi^{+}(\theta) \leq (n-1)\sqrt{-\Gamma_{R}^{-}(\theta)},
\end{equation}
completing the proof.
\end{proof}







\begin{remark}\label{RNEW1}
The conclusions of \emph{Lemma~\ref{L1NEW}} remain valid for non-compact manifolds. Furthermore, we emphasize that:
\begin{itemize}
    \item The upper bound in inequality~\eqref{EQ0NEW} requires only the absence of conjugate points and and curvature bounded below.
    \item The lower bound additionally requires no focal points and curvature bounded below.
\end{itemize}
This distinction becomes particularly relevant when studying rigidity questions in finite/infinite-volume settings.
\end{remark}



