\noindent The Ruelle inequality yields the following lemma, which extends \cite[Corollary II.1]{MF} to the non-compact case:

\begin{lem}\label{RIGI}
Let $M$ be a manifold without conjugate points where the Ruelle inequality holds. Then for any invariant measure $\mu$:
\[ h_{\mu}(\phi^t) \leq (n-1)\sqrt{-\int_{SM}\mathrm{Ric}(\theta)\,d\mu}. \]
Equality occurs if and only if $K|_{\pi(\mathrm{Supp}(\mu))}$ is constant.
\end{lem}

\begin{proof}
Combining the Ruelle inequality with \eqref{EQ0NEW}, we obtain:
\begin{align*}
h_{\mu}(\phi^t) &\leq \int_{SM} \chi^+(\theta)\,d\mu \leq (n-1)\int_{SM} \sqrt{-\widetilde{\mathrm{Ric}}(\theta)}\,d\mu \\
&\leq (n-1)\sqrt{-\int_{SM} \widetilde{\mathrm{Ric}}(\theta)\,d\mu} = (n-1)\sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\mu},
\end{align*}
where $\widetilde{\mathrm{Ric}}$ denotes the Birkhoff average of $\mathrm{Ric}$.

\noindent When equality holds, \eqref{EQLN1} implies:
\[ \int_{SM} \mathrm{tr}\,U_u\,d\mu = \int_{SM} \widetilde{\mathrm{tr}\,U_u}\,d\mu = (n-1)\sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\mu}. \]
From the Cauchy-Schwarz inequality and Riccati equation  \eqref{Riccati}
\begin{equation}\label{EQ5NEW}
\int_{SM} \mathrm{tr}\,U_u\,d\mu \leq \sqrt{n-1}\sqrt{\int_{SM} \mathrm{tr}\,U_u^2\,d\mu} = (n-1)\sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\mu}.
\end{equation}

\noindent Equality in \eqref{EQ5NEW} requires $U_u$ to be a scalar multiple of $I$, which by \eqref{Riccati} forces constant sectional curvature on $\pi(\mathrm{Supp}(\mu))$.
\end{proof}

\begin{remark}\label{R_RIGI}
The rigidity conclusion holds under the weaker assumption:
\[ \int_{SM} \mathrm{tr}\,U_u\,d\mu = (n-1)\sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\mu}. \]
In this case, $U_u = \lambda I$ $\mu$-a.e., where $\lambda = \sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\mu}$.
\end{remark}

The results of \cite{CR} establish that the Ruelle inequality holds for Anosov geodesic flows when both the curvature tensor and its derivatives are uniformly bounded, making Lemma \ref{RIGI} applicable in this setting.



