\begin{lem}\label{L2'NEW}
    Let $M$ be a manifold without focal points and $\mu$ an invariant measure satisfying $\mu(\Lambda_0) > 0$. Then:
    \[ K|_{\pi(\mathrm{Supp}(\mu) \cap \Lambda_0)} \equiv 0. \]
\end{lem}

\begin{proof}
Recall that $\Lambda_0 = \{\theta \in SM : \chi^+(\theta) = 0\}$ is invariant. Let $\tilde{\mu}$ denote the restriction of $\mu$ to $\Lambda_0 \cap \mathrm{Supp}(\mu)$. By the Birkhoff ergodic theorem, for $\tilde{\mu}$-a.e. $\theta$ there exists:
\begin{equation}\label{EQlem3.5}
    \Gamma_R^+(\theta) = \Gamma_R^-(\theta) =: \Gamma_R(\theta) = \widetilde{\mathrm{Ric}}(\theta) := \lim_{t \to +\infty} \frac{1}{t} \int_0^t \mathrm{Ric}(\phi^s(\theta))\,ds \in L^1(\tilde{\mu}) 
\end{equation}

with 
\[ \int_{\Lambda_0 \cap \mathrm{Supp}(\mu)} \widetilde{\mathrm{Ric}}(\theta)\,d\tilde{\mu} = \int_{\Lambda_0 \cap \mathrm{Supp}(\mu)} \mathrm{Ric}(\theta)\,d\mu. \]

From Lemma \ref{L1NEW}, and (\ref{EQlem3.5}) we have  $\widetilde{\mathrm{Ric}}(\theta) = 0$ holds $\tilde{\mu}$-a.e., implying:
\[ \int_{\Lambda_0 \cap \mathrm{Supp}(\mu)} \mathrm{Ric}(\theta)\,d\mu = 0. \]

\noindent Since $\chi^+(\theta) = \displaystyle\limsup_{t\to+\infty} \frac{1}{t} \int_0^t \mathrm{tr}(U_{\theta,u}(s))\,ds$ and $\mu(\Lambda_0) > 0$, we have $\widetilde{\mathrm{tr}\,U_u}(\theta) = 0$ $\mu$-a.e., where $\widetilde{\mathrm{tr}\,U_u}(\cdot)$ is the Birkhoff average of $\mathrm{tr}\,U_u(\cdot)$. 

\noindent Combining \eqref{EQ-Green} with the Birkhoff theorem and Cauchy-Schwarz yields:
$$
(n-1)\sqrt{-\int_{SM} \mathrm{Ric}(\theta)\,d\tilde{\mu}} = \int_{SM} \widetilde{\mathrm{tr}\,U_u}\,d\tilde{\mu} = \int_{SM} \mathrm{tr}\,U_u\,d\tilde{\mu} = 0.$$
\noindent Remark \ref{R_RIGI} now implies $R \equiv 0$ on $\mathrm{Supp}(\mu) \cap \Lambda_0$, as required.
\end{proof}







\noindent It is worth nothing that: In the case of dimension two and non-focal points (see (\cite{Barr-Pes}) for more details), the set $$\displaystyle\Lambda_0=\Big\{\theta: \limsup_{t\to\infty}\frac{1}{t}\int_0^tK(\gamma_{\theta}(s))ds=0\Big\},$$ 
where $K$ is the Gaussian curvature, captures directions where the average curvature along the geodesic vanishes asymptotically. In the case of non-positive curvature $$\Lambda_0=\{\theta: K(\gamma_{\theta}(t))=0, \,\, \text{for all}\,\, t\in \mathbb{R}\}.$$

%[1] Ya. B. Pesin, Lectures on Partial Hyperbolicity and Stable Ergodicity, Zürich Lectures in Advanced Mathematics, EMS, 2004.

