\section{Rigidity on Curvature Through Invariant Measures}
\begin{proof}[\textbf{\emph{Proof of Theorem \ref{Theorem_Rigidity}}}]
From \cite{Guimaraes}, since $M$ has curvature bounded from below and has no conjugate points, then the Ricci curvature is integrable for any invariant measure. 
    Assuming that $\mu$ is an invariant measure with $\mu(\Lambda_\alpha)=1$, then from (\ref{EQ-Form-Lyp-Exp})
$$\int_{SM}\text{tr}\,U_{u}\,d\mu=\int_{SM}\chi^{+}\,d\mu=\int_{\Lambda_{\alpha}}\chi^{+}\,d\mu =(n-1)\int_{\Lambda_{\alpha}}\alpha\, d\mu \geq (n-1)\sqrt{-\int_{SM}\emph{Ric}(\theta)\,d\mu}.$$

\noindent Note that for $\mu$-almost every point $\theta$, from  Birkhoff Ergodic Theorem, Remark \ref{RNEW1}, and (\ref{EQ-Form-Lyp-Exp}) both side of (\ref{EQ0NEW}) are converge to $\widetilde{\text{tr}\,U_u}(\theta)\leq (n-1)\sqrt{-\widetilde{\emph{Ric}}(\theta)}$, $\mu$ almost every $\theta$. Thus
\begin{eqnarray*}\label{EQ4NEW}
    \int_{SM}\text{tr}\,U_u \, d\mu &=& \int_{SM}\widetilde{\text{tr}\,U_u}(\theta)d\mu\leq (n-1)\int_{SM}\sqrt{-\widetilde{\emph{Ric}}(\theta)}d\mu\\
    &=&(n-1)\sqrt{-\int_{SM}\widetilde{\emph{Ric}}(\theta)\,d\mu}=(n-1)\sqrt{-\int_{SM}\emph{Ric}(\theta)\,d\mu}
\end{eqnarray*}%\label{EQ3"NEW}
The two last inequalities provide 
\begin{equation*}\label{EQN1}
\int_{SM}\text{tr}\,U_{u}\,d\mu=(n-1)\sqrt{-\int_{SM}\emph{Ric}(\theta)\,d\mu}     
\end{equation*}

\noindent It follows from (\ref{EQ5NEW}) our result. 
\end{proof}

\begin{proof}[\textbf{\emph{Proof of Corollary \ref{C_Theorem_Rigidity}}}]
Note that if $\mu$ is ergodic with full support, then the invariance of $\Lambda_{\alpha}$ implies that $\mu(\Lambda_\alpha)=1$, then from Theorem \ref{Theorem_Rigidity}, $K|_{\pi(\text{Supp}(\mu)=SM}=\sqrt{-\int_{SM}\text{Ric}(\theta)d\mu}$.
\end{proof}



\begin{proof}[\textbf{\emph{Proof of Theorem \ref{Theorem_Rigidity2}}}]
   By proof of Theorem 1.4 of \cite{Nina2}, which relies on Kalinin's result (see \cite{Kal}), the ergodicity of the  Liouville measure $\mathcal{L}$ implies that all Lyapunov exponents are equal to $\alpha$. Consequently, $\mathcal{L}(\Lambda_\alpha)>0$ and the desired result follows directly from  Theorem \ref{Theorem_Rigidity}.
\end{proof}

\begin{proof}[\textbf{\emph{Proof of Theorem \ref{Theorem_Rigidity3}}}]
From (\ref{EQ-Form-Lyp-Exp}) we know that for every $\theta\in \text{Per}(\phi^t)$
$$\chi^{+}(\theta)=\frac{1}{\tau_{\theta}}\int_0^{\tau_\theta}\text{tr}\,U_{u}(\phi^s(\theta))ds=\int_{SM}\text{tr}\,U_{u}\,d\mu_{\theta},$$
where $\tau_\theta$ is the period of $\theta$. 
From hypothesis and Remark \ref{RNEW1}, the last inequality implies that 
$$\int_{SM}\text{tr}\,U_{u}\,d\mu_{\theta}=(n-1)\sqrt{-\int_{SM}\emph{Ric}(\theta)\,d\mu_{\theta}}.$$
Remark \ref{R_RIGI} provides that the sectional curvature $K_M$ is constant along $\pi(\phi^t(\theta))=\gamma_\theta(t)$, for every $\theta\in \text{Per}(\phi^t)$ and $U_u(\cdot)=\sqrt{-\int_{SM}\emph{Ric}(\theta)\,d\mu_{\theta}}\,I$.
The idea now is to use this property to extend the constant curvature to $\overline{\text{Per}(\phi^t)}$.\\
\ \\
\textbf{Claim:} Let $\theta=(x,v)\in \overline{\text{Per}(\phi^t)}$ and $w$ and unit vector in $T_xM$ linearly independent with $v$, then for every $t\in \mathbb{R}$
$$K_{x}(v,w)=K_{\gamma_{\theta}(t)}(\gamma'_{\theta}(t),W(t)),$$
where $W(t)$ is the parallel transport of $w$ along $\gamma_{\theta}(t)$.
\begin{proof}[\textbf{\emph{Proof of Claim}}]
There is a sequence of $\{\theta_n=(x_n,v_n)\}\subset  \text{Per}(\phi^t_{M})$  and a sequence $w_n\in T_{x_n}M$ such that $\theta_n$ converges to $\theta$ and $w_n$ converges to $w$. If $W_n(t)$ represents the parallel transport of $w_n$ along $\gamma_{\theta_n}(t)$, then since the sectional curvature is constant along the closed geodesic, then for every $t\in \mathbb{R}$ 
$$K_{x_n}(v_n,w_n)=K_{\gamma_{\theta_n}(t)}(\gamma'_{\theta_n}(t), W_n(t))$$
The left hand of the last equality converges to $K_{x}(v,w)$ and from the continuity of the parallel transport to the initial conditions, the right hand of the last equation converges to $K_{\gamma_{\theta}(t)}(\gamma'_{\theta}(t),W(t))$, as $n$ goes to infinite. Thus, we have the equality desired. 
\end{proof}

Let $\theta\in \overline{\text{Per}(\phi^t)}$, $\theta=(x,v)$ and $\{v,v_1, v_2, \dots,v_{n-1}\}$ an orthonormal basis of $T_xM$, and $\{\gamma'(t), v_1(t), v_2(t),\dots, v_{n-1}(t)\}$ a parallel orthonormal basic along $\gamma_{\theta}(t)$. So, from previous Claim 

\begin{eqnarray*}
    \text{Ric}(\phi^t_{M}(\theta))&=&\frac{1}{n-1}\sum_{i=1}^{n-1}R(\gamma'_{\theta}(t), v_i(t), \gamma'_{\theta}(t), v_i(t))\\
    &=&\frac{1}{n-1}\sum_{i=1}^{n-1} K_{\gamma_{\theta}(t)}(\gamma'_{\theta}(t),v_i(t))\\
    &=&\frac{1}{n-1}\sum_{i=1}^{n-1} K_x(v,v_i)=\text{Ric}(\theta).
\end{eqnarray*}
The last equality shows that the Ricci curvature $\text{Ric}|_{\overline{\text{Per}(\phi^t)}}$ is invariant for $\phi^t$, moreover, since it is a continuous function and $\phi^t|_{\overline{\text{Per}(\phi^t)}}$ is ergodic, then $\text{Ric}(\cdot)$ is a constant function, we said equal to $-\alpha^2$. Therefore, 
$U_u(\cdot)=\alpha\, I$ for the set of periodic orbits. This mean that $U_u(\cdot)=\alpha \, I$ in $\overline{\text{Per}(\phi^t)}$. The result follows from (\ref{Riccati}).
\end{proof}



\section{Rigidity of Regular Flow Equivalences}
\subsection{Rigidity for $1$-equivalences}  





The following lemma serves a dual purpose: it is crucial for proving Theorems \ref{N-Conjugacy} and \ref{C1-Conjugacy}, while simultaneously generalizing \cite[Theorem 1.6]{Nina2} to a broader geometric setting.

\begin{lem}\label{Theorem_Not_Flat}
Let $M$ be a manifold with sectional curvature satisfying $-c^2 \leq K_M \leq -b^2 \leq 0$. If there exists a $\phi^t$-invariant measure $\mu$ with $\mu(\Lambda_\alpha) > 0$ for $\alpha \in \{b,c\}$, then:
\[ K_M|_{\pi(\mathrm{Supp}(\mu))} = -\alpha^2. \]
\end{lem}

\begin{proof}
The case $\alpha = c$ follows directly from Theorem \ref{Theorem_Rigidity}, since $\alpha = c \geq \sqrt{-\int_{SM} \mathrm{Ric}(\theta)d\mu}$. The case $\alpha = b = 0$ is handled by Lemma \ref{L2'NEW}. We thus assume $\alpha = b > 0$ with $\mu(\Lambda_b) = 1$.

For $\mu$-a.e. $\theta$, the Birkhoff ergodic theorem yields:
\[ b(n-1) = \lim_{t\to\infty} \frac{1}{t} \int_0^t \mathrm{tr}\,U_u(\phi^s(\theta))ds = \widetilde{\mathrm{tr}\,U_u}(\theta). \]

\noindent Note that $\displaystyle\int_{SM}\text{tr}\,U_{u}=\int_{SM}\widetilde{\text{tr}\,U_{u}}d\mu=b(n-1)$. Thus, since $K_M \leq -b^2$ implies $\mathrm{tr}\,U_u \geq (n-1)b$, we conclude $\mathrm{tr}\,U_u(\theta) = b(n-1)$ $\mu$-a.e. 
Finally, the Ricatti equation and symmetry of $U_{u}$ then force  
$\displaystyle \int_{SM}\text{Ric}(\theta)d\mu=-b^2$, which implies that $K_{M}|_{\pi(\text{Supp}(\mu))}=-b^2$. 
\end{proof}


\begin{proof}[\textbf{\emph{Proof of Theorem \ref{N-Conjugacy}}}]
Building on \cite{Guimaraes}, the curvature bound guarantees Ricci integrability. Let $h$ be a $1$-equivalence satisfying $h \circ \phi_M^t = \phi_N^{s(t)} \circ h$ with $s(t) \geq t$, $t\geq 0$.

For $\mu$-a.e. $\theta \in \Gamma_{M,N}$ (where $d_\theta h$ exists), there exist $C_1,C_2>0$ such that for all $t \in \mathbb{R}$ and $\eta \in G^u_\theta$:
\begin{equation}\label{EQ1}
C_1\|d_\theta\phi^t_M(\eta)\| \leq \|d_{h(\theta)}\phi^{s(t)}_N(d_\theta h(\eta))\| \leq C_2\|d_\theta\phi^t_M(\eta)\|.
\end{equation}


\noindent Note that, since $M$ has no conjugate points, then $\displaystyle\int_{SM}\text{Ric}\,d\mu\leq 0$.  Therefore,  If $\sup K_N\geq 0$, then $\displaystyle\int_{SM}\text{Ric}(\theta)\,d\mu\leq \sup K_N$. In this case, the equality only happens if both are equal to zero, however,  if $\displaystyle\int_{SM}\text{Ric}\,d\mu=0$, then $M$ is flat in $\pi(\text{Supp}(\mu))$ as we wished. (see \cite{Guimaraes}, \cite{Green}). Therefore, without loss of generality, we can assume that $\sup K_N<0$, which implies that $\phi^t_N$ is Anosov, since the curvature of $N$ is bounded from below,  therefore (\ref{EQ1}) implies 

\begin{equation}\label{EQ1*}
    \|d_{h(\theta)}\phi^{s(t)}_{N}(d_{\theta}h(\eta))\|\geq Ce^{\sqrt{-\sup K_N}s(t)}||d_{\theta}h(\eta)||.
\end{equation}
From (\ref{EQ1}) and (\ref{EQ1*}) 
\begin{equation}\label{EQ1**}
  \displaystyle \sqrt{-\sup K_N}\leq \limsup \frac{s(t)}{t}\sqrt{-\sup K_N}\leq \frac{\chi^{+}_{M}(\theta, \eta)}{n-1}. 
\end{equation}
The last inequality together with Remark \ref{RNEW1} and Birkhoff's ergodic theorem provides that, for $\mu$ almost every $\theta\in \Gamma_{M, N}$

\begin{equation}\label{EQ1***}
    \displaystyle (n-1)\sqrt{-\sup K_N}\leq \chi^{+}_{M}(\theta)\leq  (n-1)\sqrt{-\widetilde{\text{Ric}}\,(\theta)}.
\end{equation}

\noindent  Integrating with respect $\mu$ we have
\begin{eqnarray}\label{EQ2'New}
    (n-1)\sqrt{-\sup K_N}&\leq& \int_{SM}\chi^{+}(\theta)d\mu \leq (n-1)\int_{SM}\sqrt{-\tilde{Ric}\,(\theta)}d\mu \nonumber \\
    &\leq& (n-1)\sqrt{\int_{SM}-\widetilde{Ric}\,(\theta)d\mu}=(n-1)\sqrt{-\int_{SM}\text{Ric}(\theta)d\mu}.
\end{eqnarray}
Thus, we obtain that $$\sup K_N\geq \int_{SM}\text{Ric}(\theta)d\mu.$$
Note that, if we have equality in the last equation, then we have also equality in the equation (\ref{EQ2'New}), which implies that $\widetilde{\text{Ric}}\,(\theta)$ is constant $\mu$-almost everywhere, equal to $\displaystyle \int_{SM}\text{Ric}\,(\theta)d\mu$. Consequently, (\ref{EQ1***}) implies that for $\mu$-almost every $\theta$, $$\chi^{+}_{M}(\theta)=(n-1)\sqrt{-\int_{SM}\text{Ric}(\theta)d\mu}.$$
So, $\mu(\Lambda_{\alpha})=1$, for $\alpha= \sqrt{-\int_{SM}\text{Ric}(\theta)d\mu}$. Consequently, the Theorem \ref{Theorem_Rigidity} implies that $K_{M}|_{\pi(\text{Supp}(\mu))}=\displaystyle\int_{SM}\text{Ric}(\theta)d\mu=\sup K_N$.\\
To conclude the proof of the theorem we need to prove that $\displaystyle\lim_{t \to \infty}\frac{s(t)}{t}=1$. For this sake, note that the equation (\ref{EQ1**}) already imply that $\displaystyle\limsup_{t\to +\infty} \frac{s(t)}{t}=1$. Observe that, $\mu$-almost every $\theta$, from (\ref{EQ1}) and (\ref{EQ1*})
\begin{eqnarray}\label{AFTER-EQ1}
   \sqrt{-\int_{SM}\text{Ric}(\theta)d\mu}= \chi^{+}_{M}(\theta, \eta)&=&\displaystyle \lim_{t\to +\infty}\frac{1}{t}\log \|d_{\theta}\phi^{t}_{M}(\eta)\|=\displaystyle \liminf_{t\to +\infty}\frac{1}{t}\log \|d_{\theta}\phi^{t}_{M}(\eta)\| \nonumber\\
    &\geq & \liminf_{t\to +\infty}\frac{s(t)}{t}\sqrt{-\sup K_N}.
\end{eqnarray}
Thus $\displaystyle \liminf_{t\to +\infty}\frac{s(t)}{t}\leq 1$, but $s(t)\geq t$, then $\displaystyle\liminf_{t\to +\infty}\frac{s(t)}{t}=1$, as we wished.\\
Note that if $\displaystyle\liminf_{t\to +\infty}\frac{s(t)}{t}=1$, then (\ref{AFTER-EQ1}) implies that $\displaystyle\int_{SM}\text{Ric}(\theta)d\mu\leq \sup K_N $, and then $\displaystyle\int_{SM}\text{Ric}(\theta)d\mu = \sup K_N $, which completes the proof of the equivalences in the theorem. 
Assume now that $M$ and $N$ have the same dimension, our task is to prove that $K_N$ is also constant in $\pi(\text{Supp}(h_{*}\mu))$. For this sake, note that $K_M=-\alpha^2$, so (\ref{EQ1}) implies that $\chi^{+}_{N}(h(\theta))=(n-1)\alpha$, since $\sup K_N=-\alpha^2$, them using Lemma \ref{Theorem_Not_Flat} we conclude that $K_N|_{\pi(\text{Supp}(h_{*}(\mu)))}=-\alpha^2$.
\end{proof}
The techniques used in the proof of the previous theorem also work under weaker conditions. To understand these weak conditions, we introduce the following definition. 

\begin{defi}\label{E_1-measure}
    Two geodesic flows $\phi^{t}_{M}$ and $\phi^{t}_{N}$ have the property $\mathcal{E}_1$  along a measure $\mu$ if there is a map $h:U \to SN$ with $h \circ \phi^t_M = \phi^{s(t)}_{N} \circ h$ on $U$, and  $s(t)\geq t$ and satisfies \emph{(\ref{eq:bi_lipschitz})}.
\end{defi}
Using this definition on the hypotheses of Theorem \ref{N-Conjugacy}, we have the following result.
\begin{prop}\label{Prop1}
Theorem \ref{N-Conjugacy} remains valid when the global $\mathcal{E}_1$ condition is replaced by $\mathcal{E}_1$ along $\mu$.
\end{prop}



\begin{proof}[\textbf{\emph{Proof of Corolary \ref{N-Conjugacy-Liouville}}}]
It is enough apply the Theorem \ref{N-Conjugacy} for the Liouville measure $\mathcal{L}$, nothing that  $\mathcal{L}(SM\setminus \Gamma_{M,N})=1$ and $\text{Supp}(\mathcal{L})=SM$.
\end{proof}

\begin{proof}[\textbf{\emph{Proof of Theorem \ref{C1-Conjugacy}}}]
Since our equivalence is $C^1$, then $\Gamma_{N,M}=SM$. Therefore, for every $\theta\in\text{Per}(\phi^t_{M})$, $\mu_{\theta}(\Gamma_{M,N})=1$. So, similar arguments as in the proof of Theorem \ref{N-Conjugacy}, we obtain the condition $$\sup K_{N}|_{\mathcal{O}(h(\theta))}\geq  \int_{SM}\emph{Ric}(\theta)d\mathcal{\mu_{\theta}}.$$
Moreover, the equality holds if and only if $\displaystyle\lim_{t\to \infty}\frac{s(t)}{t}=1$, and 
\begin{equation}\label{EQN11}
K_{M}|_{\pi(\mathcal{O}(\theta))}= K_{M}|_{\pi(\text{Supp}(\mu_\theta))}=\int_{SM}\text{Ric}d\mu_{\theta}=\sup K_{N}|_{\mathcal{O}(h(\theta))}.  
\end{equation}
In other words, the section curvature is constant along periodic orbits. So, using the density of the periodic orbits and ergodicity of geodesic flow, a similar argument  to the proof Theorem \ref{Theorem_Rigidity3} allows us to conclude that $\text{Ric}(\cdot)$ is a constant function, we said equal to $-\alpha^2$. Therefore, from (\ref{EQN11}) we obtain that 
$$K_{M}|_{\pi(\mathcal{O}(\theta))}=-\alpha^2, \,\,\, \text{for all}\,\,\, \theta\in \text{Per}(\phi^t_{M}).$$
Consequently, from \cite{Nina} we have density of $\text{Per}(\phi^t_{M})$, therefore, the continuity of $K_M$ allows us to conclude that $K_M=-\alpha^2$ as we wished.\\
When $M$ and $N$ have the same dimension the proof follows the same lines like the end of the proof of Theorem \ref{N-Conjugacy}, from (\ref{EQ1}), $\chi^{+}_{N}(h(\theta))=(n-1)\alpha$ and $K_M=-\alpha^2$.
\end{proof}

\begin{remark}
 In the proof of the previous theorem, the Anosov condition of $\phi^t_{M}$ can be replaced by $M$ without conjugate points, $\phi^t_{M}$ ergodic, and density of periodic orbits. This condition is satisfied for a wide range of manifolds.
\end{remark}
The conditions on density of periodic orbits and ergodicity are useful to spread the constant curvature throughout the whole manifold. However, the following proposition can be obtain from the proof for Theorem \ref{C1-Conjugacy} and holds for each geodesic. 
\begin{prop}\label{Prop_2} 
 Let $M$ and $N$ be two complete Riemannian manifolds whose geodesic flows $\varphi_{M}^{t}$ and $\varphi_{N}^{t}$ satisfies the property $\mathcal{E}_1$  with $C^1$-equivalence $h$ along a periodic measure $\mu_{\theta}$. Assume that $M$ has no conjugate points along $\gamma_{\theta}(t)$, then  $$ K_{N}|_{\mathcal{O}(h(\theta))}\geq  \int_{SM}\emph{Ric}(\theta)d\mathcal{\mu_{\theta}}.$$ 
 The equality holds  if and only if, $M$ has constant negative sectional curvature along $\gamma_{\theta}(t)$ and $\displaystyle\lim_{t\to +\infty}\frac{s(t)}{t}=1$. Moreover, if $M$ and $N$ have the same dimension, then $N$ has constant negative sectional in $\gamma_{h(\theta)}(t)$.
\end{prop}



\subsection{More General Rigidity}
This section extends Theorems \ref{N-Conjugacy} and \ref{C1-Conjugacy} to equivalences where the reparametrization $s(t)$ satisfies $s(t) \geq at$ for some $a > 0$, using conformal metric deformations.
\subsubsection{No conjugate points and homotheties}
We investigate relationships between geodesic flows on the same manifold under different metrics, particularly homothetic transformations.
Let $(M,g)$ be a Riemannian manifold and consider the conformal metrics $g_r = e^{2r}g$ for $r \in \mathbb{R}$. Denote by $M_r$ the manifold $M$ with metric $g_r$. Key observations (see \cite{doCarmo} for more details):

\begin{itemize}
    \item The Levi-Civita connections satisfy $\nabla_r = \nabla$.
    \item Sectional curvatures relate by $K_r(v,w) = e^{-2r}K(v,w)$ for linearly independent $v,w \in T_xM$.
    \item Geodesics coincide as sets, but velocities scale: $\|\gamma'(t)\|_r = e^r\|\gamma'(t)\|$.
    \item Jacobi fields satisfy $\|J(t)\|_r = e^r\|J(t)\|$ .
\end{itemize}

\begin{lem}\label{Homo-NCP}
$(M,g_r)$ has no conjugate points if and only if $(M,g)$ has no conjugate points.
\end{lem}
\begin{proof}
Immediate from the norm scaling of Jacobi fields.
\end{proof}

\begin{lem}\label{lemma_Homothe}
For any complete $(M,g)$, there exists an orbit-isometric $C^1$-conjugacy $h:SM \to SM_r$ between $\phi_M^t$ and $\phi_{M_r}^t$.
\end{lem}
\begin{proof}
Define $h(x,v) = (x,e^{-r}v)$ and $s(t) = e^rt$. For $\theta = (x,v) \in SM$ and $\widetilde{\theta} = h(\theta)$, the geodesics satisfy $\gamma_{\widetilde{\theta}}(t) = \gamma_\theta(e^{-r}t)$. By definition of $h$ and the geodesic flows $\varphi^{t}_{M}$ and $\varphi^{t}_{M_{r}}$ we have that for all $t\in \mathbb{R}$
\begin{eqnarray*}
h\circ\phi^{s^{-1}(t)}_{M}(\theta)&=&h\circ\phi^{e^{-r}t}_{M}(\theta)
=h(\gamma_{\theta}(e^{-r}t),\gamma'_{\theta}(e^{-r}t))\\
&=&(\gamma_{\theta}(e^{-r}t),e^{-r}\gamma'_{\theta}(e^{-r}t))
=(\gamma_{\widetilde{\theta}}(t),\gamma'_{\widetilde{\theta}}(t))\\
&=&\phi^{t}_{M_{r}}(x,e^{-r}t)
%&=&\varphi^{t}_{M_{r}}(\widetilde{\theta})\\
=\phi^{t}_{M_{r}}\circ h(\theta).
\end{eqnarray*}

\noindent Hence $h\circ\phi^{t}_{M}=\phi^{s(t)}_{M_{r}}\circ h$, for all $t\in\mathbb{R}$.
\end{proof}


Observe that, if $r<0$, then the last lemma implies that $\phi^{t}_{M}$ and $\phi^{t}_{M_{r}}$ have the property $\mathcal{E}_1$.
\subsubsection{Generalized Equivalence Properties}
\begin{defi}
    Geodesic flows $\phi^{t}_{M}$ and $\phi^{t}_{N}$ have the property $\mathcal{E}_a$ $(a>0)$, if they are $1$-equivalent  reparametrization $s(t)$ satisfying $s(t)\geq at$, $t\geq 0$.
\end{defi}

 \begin{teo}\label{N-Conjugacy-a} Let $M$ and $N$ be two complete Riemannian manifolds whose geodesic flows  $\phi_{M}^{t}$ and $\phi_{N}^{t}$ satisfies the property $\mathcal{E}_a$ with $1$-equivalence $h$. If $M$ has no conjugate points and there exists an invariant measure $\mu$ with $\mu(\Gamma_{M,N}) = 1$, then: $$a^2\sup K_{N}\geq\int_{SM}\emph{Ric}(\theta)d\mu.$$ The equality holds if and only if  $K_{M}|_{\pi(\text{Supp}(\mu))}=a^2\sup K_N$ and $\displaystyle\lim_{t\to +\infty}\frac{s(t)}{t}=a$. \\
 Moreover, when $\dim M = \dim N$, $N$ has constant negative curvature on $\pi(\mathrm{Supp}(h_*\mu))$.
 %Moreover, if $M$ and $N$ have the same dimension, then $N$ has constant negative sectional curvature in $\pi(\text{Supp}(h^{*}(\mu)))$.
\end{teo}
\begin{proof}
Since $a>0$ there is $r_0$ such that $a=e^{-r_0}$. Consider the manifold $(N_{r_0}, g_{r_0})$, then 
$$a^2K_N= K_{N_{r_0}}.$$
From Lemma \ref{lemma_Homothe} there is an isometry $h$  such that $h\circ\phi^{t}_{N}=\phi^{u(t)}_{N_{r_0}}\circ h$, where $u(t)=e^{r_0}t$.\\
Also, by hypotheses, there is an $1$-equivalence $f$ with $f \circ \phi^t_{M}=\phi ^{s(t)}_{N}\circ f$, where $s(t)\geq at$, $t\geq 0$. % is odd and $u(t)\leq at$, $t\geq 0$. In other words, 

$$h\circ f \circ \phi^t_{M} = h \circ \phi^{s(t)}_{N}\circ f= \phi_{N_{r_0}}^{u(s(t))}\circ h\circ f.$$
Note that $u(s(t))=e^{r_0}s(t)\geq e^{r_0}at=t$. Moreover, since $h$ is an isometry, then $h\circ f$ is a $1$-equivalence. Consequently, we obtain our result from Theorem \ref{N-Conjugacy}.
\end{proof}
A similar result to Theorem \ref{Theorem_Rigidity3} is also obtained with the property $\mathcal{E}_{a}$. Its proof follows the same lines as the proof of Theorem \ref{N-Conjugacy-a} but using Theorem \ref{C1-Conjugacy} instead of Theorem \ref{N-Conjugacy}.

 \begin{teo}\label{Theorem_C^1-Conjugacy-a}

 Let $M$ and $N$ be two complete Riemannian manifolds whose geodesic flows $\phi_{M}^{t}$ and $\phi_{N}^{t}$ satisfy the property $\mathcal{E}_a$ with $C^1$-equivalence $h$. If $M$ has finite volume and $\phi^t_{M}$ is Anosov, then:  $$ a^2\,K_{N}|_{\mathcal{O}(h(\theta))}\geq  \int_{SM}\emph{Ric}(\theta)d\mathcal{\mu_{\theta}}, \, \, \, \text{for all} \, \, \, \theta \in \text{Per}(\phi^t_{M}).$$ 
  The equality holds for all geodesic if and only if, $M$ has constant negative sectional curvature and $\displaystyle\lim_{t\to +\infty}\frac{s(t)}{t}=a$. %Moreover, if $M$ and $N$ have the same dimension, then $N$ has constant negative sectional curvature.
  Moreover, when $\dim M = \dim N$, $N$ has constant negative curvature on $\pi(\mathrm{Supp}(h_*\mu))$.
\end{teo}  




\begin{remark}
The property $\mathcal{E}_a$ admits a natural measure-theoretic extension $\mathcal{E}_a(\mu)$ for invariant measures $\mu$, producing corresponding generalizations of \emph{Theorems \ref{N-Conjugacy-a} and \ref{Theorem_C^1-Conjugacy-a}} in complete analogy with \emph{Propositions \ref{Prop1} and \ref{Prop_2}}.
\end{remark}

\section{Some Applications}\label{Some Applications}

\subsection{Generalization of Some Rigidity Results}
In this section we focus on made a simple proof of some rigidity result at \cite[Theorem 1.1, Theorem 1.2 , and Theorem 1.4]{IR2}.
\begin{teo}[\cite{IR2}, Theorem 1.1]
 If $M$ is a complete manifold of finite volume with sectional curvature bounded from below by $-c^2$ and Anosov geodesic flow. If the constant of contraction of the flow $\lambda=e^{-c}$, then $K_M=-c^2$.
\end{teo}
 \begin{proof} 
The curvature condition implies (see \cite[Lemma 2.16]{Kn}) the following uniform growth estimates for unstable vectors:
\begin{equation*}\label{eq:growth_estimate}
C\lambda^{-t}\|\eta\| \leq \|d_{\theta}\varphi^{t}_{M}(\eta)\| \leq e^{ct}\|\eta\|\sqrt{1+c^2}, \quad t \geq 0, \,\, \eta \in E^u(\theta).
\end{equation*}
Taking $\lambda = e^{-c}$, we obtain $\chi^+(\theta) = (n-1)c$ for all $\theta \in SM$, which implies $\mathcal{L}(\Lambda_c) = 1$ for the Liouville measure $\mathcal{L}$. \\
Since the geodesic flow is Anosov and $M$ has finite volume, the Liouville measure is ergodic. Furthermore, the inequality 
\[
c \geq \sqrt{-\int_{SM} \text{Ric}(\theta)\,d\mathcal{L}}
\]
holds, and thus the conclusion follows directly from Corollary \ref{C_Theorem_Rigidity}.
 \end{proof}  






Our next result extends \cite[Theorem 1.2 and Theorem 1.4]{IR2} in two significant aspects: the manifolds need not be compact, nor is an Anosov geodesic flow required.

\begin{teo}\label{thm:curvature_comparison}
Let $M$ and $N$ be Riemannian manifolds whose geodesic flows are $1$-equivalent with $s(t) = t$. Assume that:
\begin{enumerate}
    \item[\emph{1}.] $M$ has finite volume;
    \item[\emph{2}.]  $M$ has curvature bounded below and no conjugate points;
    \item[\emph{3}.]  $\inf K_{M} \geq \sup K_N$.
\end{enumerate}
Then $K_M \equiv \sup K_N$ on $M$. Moreover, if $\dim M = \dim N$, then $K_M = K_N \equiv \sup K_N$.
\end{teo}

\begin{proof}
Since $\phi_M^t$ and $\phi_N^t$ satisfy property $\mathcal{E}_1$, Theorem \ref{N-Conjugacy} yields
\[ \sup K_{N} \geq \int_{SM} \text{Ric}(\theta)\, d\mathcal{L}. \]

The hypothesis $\inf K_{M} \geq \sup K_N$ implies that $\text{Ric}(\theta) \equiv \inf K_M$.% almost everywhere with respect to $\mathcal{L}$. 
Consequently,
\[ \sup K_{N} = \int_{SM} \text{Ric}(\theta)\, d\mathcal{L}. \]

\noindent The conclusion follows directly from Corollary \ref{N-Conjugacy-Liouville}.
\end{proof}

















