        \lim_{t\to0^+}\frac{\rho_{K_{f_t}}(u)-\rho_{K_f}(u)}t=\frac{h_{\dpsi}(\nu_{K_f}(\rho_{K_f}(u)u))}{\langle u,\nu_{K_f}(\rho_{K_f}(u)u)\rangle}.
