    The proof follows from \cite[Lemma 5.3]{FYZ24} verbatim and is omitted.
\end{proof}
Indeed, condition \eqref{3.11} implies that $o\in \dom \psi$, due to fact that $\psi(o)=-\inf\psi^*<\infty.$  
Note that $E_{t}(u)$ in \eqref{etu} can be written as follows:
\begin{align} 
E_{t}(u)&= \int_{0}^{+\infty}\frac{\widehat{f_{t}}(ru)-f(ru)}{t}r^{n-1}\,dr   \ \ \mathrm{for} \ \ u\notin \Omega_f, \label{def-etu-notin} \\E_{t}(u)&= \int_{0}^{\rho_{K_{f}}(u)}\frac{\widehat{f_{t}}(ru)-f(ru)}{t}r^{n-1}\,dr \!+ \!\int_{\rho_{K_{f}}(u)}^{\rho_{K_{\widehat{f_{t}}}}(u)}\frac{\widehat{f_{t}}(ru)}{t}r^{n-1}\,dr \ \ \mathrm{for} \ \ u\in \Omega_f. \label{def-etu-in} 
\end{align} For convenience, we often only use the expression of \eqref{def-etu-in} for $E_t(\cdot)$; and when $u\notin \Omega_f$, it is understood as in \eqref{def-etu-notin}. 


\begin{lemma}\label{lem7} 
Let $-\frac{1}{n}<\alpha < 0$, $\beta_{1} \geq  0$ and $\beta_{2}\in\R$  be given constants. Assume that  $f \in \CA(\Rn)$ with $o\in \mathrm{int}(K_f)$. For $t>0$ small enough, let   $\widehat{f_t}$ be given in \eqref{define-f-hat-1}.    Then, for almost every $u\in \sphere$, one has
   \begin{equation}\label{3.18}
       \lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\!\! \frac{\widehat{f_{t}}(ru)\!-\!f(ru)}{t}r^{n-1}\,dr=\!\!\int_{0}^{\rho_{K_{f}}(u)}\!\!\! \!\! \lim_{t\to 0^{+}}\frac{\widehat{f_{t}}(ru)\!-\! f(ru)}{t}r^{n-1}\,dr<+\infty.
    \end{equation} 
\end{lemma}
\begin{proof} Recall that $\widehat{f_{t}}$ is well defined if $0<t<t_0$ for some small fixed $t_{0}$. For $u\in \sphere$, $0<t<t_0$ and $r>0,$ let 
    $$\mathcal{E}_{t,u}(r):=\frac{\widehat{f_{t}}(ru)-f(ru)}{t}r^{n-1}.$$  
It can be checked from \eqref{continuity-star} that, for almost all $u\in \sphere$ and all $0<r<\rho_{K_f}(u)$, we have 
\begin{align}\label{widehat}
    \lim_{t\to0^{+}}\widehat{f_{t}}(ru)=f(ru).
    \end{align}
Note that $\widehat{f_{t}}$ in \eqref{define-f-hat-1} can be rewritten as follows:  \begin{align} \label{lemmadiff}
            \widehat{f_{t}}   = \big( 1-\alpha [(1+\beta_{1}t)\varphi^*]^*+ \alpha\beta_{2}t\big)^{\frac{1}{\alpha}} =\Big( 1-\alpha \big[\varphi^* +t (\beta_{1}\varphi^*+\beta_{2})\big]^* \Big)^{\frac{1}{\alpha}}.
        \end{align} 
When $\beta_1=0$, we have $\widehat{f_{t}} =\big( 1-\alpha \varphi +\alpha\beta_{2} t  \big)^{\frac{1}{\alpha}}$, and from \eqref{etulim} and \eqref{widehat}, we have
\begin{align*}
\int_{0}^{\rho_{K_{f}}(u)}\lim_{t\to0^{+}}\mathcal{E}_{t,u}(r)\,dr&=\int_{0}^{\rho_{K_{f}}(u)}\beta_{2}f(ru)^{1-\alpha}r^{n-1}\,dr\nonumber\\
&= \lim_{t\to 0^{+}} E_{t}(u)=\lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{E}_{t,u}(r)\,dr.
\end{align*}

Next, assume that $\beta_1$ is positive. Applying Lemma \ref{Berman's formula} to $\varphi^*$ and $\beta_{1}\varphi^*+\beta_{2}$, it follows from  \eqref{widehat} and \eqref{lemmadiff} that
    \begin{align}\label{3.13}
            \lim_{t\to 0^+}\mathcal{E}_{t,u}(r)
            &=(\beta_{1}\varphi^*+\beta_{2})(\nabla \varphi(ru))(1-\alpha \varphi(ru))^{\frac{1}{\alpha}-1}r^{n-1}\nonumber\\
            &=\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}
        \end{align} holds for almost all $u\in \sphere$ and all $0<r<\rho_{K_f}(u).$ This further implies that   \begin{align}\label{omega-f}
    \int_{0}^{\rho_{K_{f}}(u)}\lim_{t\to0^{+}}\mathcal{E}_{t,u}(r)\,dr=\int_{0}^{\rho_{K_{f}}(u)}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr.
   \end{align} 
    Let us now compute
$$\lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{E}_{t,u}(r)\,dr.$$  It can be checked that, for almost all $u\in \sphere$ and all $0<r<\rho_{K_f}(u),$
    \begin{align*}
        \frac{d}{dr}\left( f(ru)r^{n}\right)&=\frac{d}{dr}\Big( (1-\alpha\varphi(ru))^{\frac{1}{\alpha}}r^{n}\Big) \nonumber  \\& =  \Big(nf(ru)\!-\!\left\langle ru,\nabla\varphi(ru)\right\rangle f(ru)^{1-\alpha}\Big)r^{n-1}. \end{align*} 
        Together with \eqref{basicequ}, for almost every $u\in \sphere$,  formula \eqref{etulim} can be written as 
    \begin{align}  \label{detulim}
    \lim_{t\to 0^{+}}\!\! E_{t}(u) 
     &\!=  \beta_{1}n\int_{0}^{\rho_{K_{f}}(u)}f(ru)r^{n-1}\,dr-\beta_{1}\int_{0}^{\rho_{K_{f}}(u)}\left\langle ru,\nabla\varphi(ru)\right\rangle f(ru)^{1-\alpha}r^{n-1}\,dr\nonumber\\
     &\quad +\int_{0}^{\rho_{K_{f}}(u)}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr\nonumber\\
     &\!=  \beta_{1}\!\!\int_{0}^{\rho_{K_{f}}\!(u)}\!\!\frac{d}{dr}\left( f(ru)r^{n}\right)\!+\!\int_{0}^{\rho_{K_{f}}(u)}\!\!\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))\!+\!\beta_{2}\Big)f(ru)^{1\!-\!\alpha}r^{n\!-\!1}\,dr.\end{align}

         First of all, let $u\in \Omega_f$. From \eqref{detulim}, we have\begin{align} \label{finite-u}     
        \lim_{t\to 0^{+}}\!E_{t}(u)  =  \beta_{1}\rho_{K_{f}}\!(u)^{n}\!f(\rho_{K_{f}}\!(u)u)
     \!+\!\!\int_{0}^{\rho_{K_{f}}\!(u)}\!\!\! \!\!\! \big(\beta_{1}\varphi^*(\nabla \varphi(ru))\!+\!\beta_{2}\big)f(ru)^{1\!-\!\alpha}r^{n\!-\!1}\,dr. \end{align}  
It is easy to check that ${\overline {\dom (\beta_1\varphi^*)^*}}= \beta_{1}{\overline {\dom \varphi}}=\beta_1K_f$.
    Applying the mean value theorem, \eqref{widehat} and Lemma \ref{lem7.1}, for almost every $u\in\Omega_f$, we have
    \begin{align}\label{radialdiff}
        \lim_{t\to 0^{+}}\int_{\rho_{K_{f}}(u)}^{\rho_{K_{\widehat{f}_{t}}}(u)}\frac{\widehat{f_{t}}(ru)}{t}r^{n-1}\,dr
        &= \lim_{t\to 0^{+}}\widehat{f_{t}}(r(t,u)u)r(t,u)^{n-1}\frac{h_{\beta_{1}K_{f}}(\nu_{K_{f}}(\rho_{K_{f}}(u)u))}{\left\langle u,\nu_{K_{f}}(\rho_{K_{f}}(u)u))\right\rangle}\nonumber\\
        &=\beta_{1}\rho_{K_{f}}(u)^{n}f(\rho_{K_{f}}(u)u),
    \end{align}
     where $r(t,u)\in[\rho_{K_f}(u),(1+t\beta_{1})\rho_{K_f}(u)]$ satisfies  $\lim_{t\to 0^{+}}r(t,u)=\rho_{K_f}(u).$   
    Hence, for almost every $u\in \Omega_{f}$, it follows from \eqref{def-etu-in} and \eqref{finite-u} that

         \begin{align} \label{3.15}
         \lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{E}_{t,u}(r)\,dr &= \lim_{t\to 0^{+}}E_{t}(u)-\lim_{t\to 0^{+}}\int_{\rho_{K_{f}}(u)}^{\rho_{K_{\widehat{f}_{t}}}(u)}\frac{\widehat{f_{t}}(ru)}{t}r^{n-1}\,dr\nonumber\\
        &=\int_{0}^{\rho_{K_{f}}(u)}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr.
    \end{align}

       Now let $u\notin\Omega_f$ which implies $\rho_{K_f}(u)=+\infty$. 
   From \eqref{radial}, we have, for $r>r_0$ ($r_0$ is a constant), $$f(ru)\leq \Big(\frac{-\alpha ar}{2}\Big)^{\frac{1}{\alpha}}.$$
    Due to  $-\frac{1}{n}<\alpha<0$, we have
    \begin{equation}\label{0}
        \lim_{r\to+\infty}f(ru)r^n \leq \lim_{r\to+\infty}\Big(\frac{-\alpha ar}{2}\Big)^{\frac{1}{\alpha}}r^n=0.
    \end{equation}
   It follows from \eqref{detulim} and (\ref{0}) that, for almost all $u\notin \Omega_{f}$, we have
 \begin{align*} % \label{3.19-1}
    \lim_{t\to 0^{+}}E_{t}(u) &=\beta_{1}\int_{0}^{+\infty}\frac{d}{dr}\left( f(ru)r^{n}\right)+\int_{0}^{+\infty}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr\nonumber\\
     &=\int_{0}^{+\infty}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr.\end{align*}   Thanks to \eqref{def-etu-notin},  we obtain, for almost all $u\notin \Omega_{f}$,
   \begin{align}\label{3.19}
            \lim_{t\to 0^+} \int_{0}^{\rho_{K_{f}}(u)}\!\!\!\mathcal{E}_{t,u}(r)\,dr &=\! \lim_{t\to 0^+} \int_{0}^{+\infty}\mathcal{E}_{t,u}(r)\,dr=\lim_{t\to 0^+}E_t(u)\nonumber\\
            &= \int_{0}^{+\infty}\Big(\beta_{1}\varphi^*(\nabla \varphi(ru))+\beta_{2}\Big)f(ru)^{1-\alpha}r^{n-1}\,dr. 
        \end{align}   

        Combining \eqref{omega-f}, (\ref{3.15}), and (\ref{3.19}), we get, for $\beta_1>0$ and almost all $u\in \sphere$, 
    $$\lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{E}_{t,u}(r)\,dr=\int_{0}^{\rho_{K_{f}}(u)}\lim_{t\to 0^{+}}\mathcal{E}_{t,u}(r)\,dr<+\infty.$$ This completes the proof of formula \eqref{3.18}. \end{proof}

We are now in the position to prove the following result. 
\begin{theorem}\label{thm8}
  Let $-\frac{1}{n}<\alpha < 0$, and $f=(1-\alpha\varphi)^{\frac{1}{\alpha}}\in \CA(\Rn) $ with $o\in \mathrm{int}(K_f)$. Assume that $\psi\in \conv(\Rn)$ and there exist constants $\beta_{1}> 0$ and $\beta_{2}\in\R$ satisfying \eqref{3.11}. Let $f_t$ be give in \eqref{define-f-1-1} for $t>0$ small enough. Then,
    \begin{equation}\label{main-formular}
        \lim_{t\to 0^{+}}\!\int_{\Rn}\!\! \frac{{{f}_{t}}(x)\!-\!f(x)}{t}\,dx=\! \int_{\Rn}\!\! \psi^*\!\left(\nabla \varphi(x)\right)\! f(x)^{1-\alpha}\,dx +   \int_{\partial {K_f}}\!\!\!  {h_{\dpsi}\!(\nu_{K_f}\!(x))}f(x)\,d\mathcal{H}^{n-1}(x).
    \end{equation}
\end{theorem}

\begin{proof} For $t>0$ small enough, we have \begin{align*}
         \lim_{t\to0^{+}}\int_{\Rn}\frac{f_{t}(x)-f(x)}{t}\,dx
         &= \lim_{t\to0^{+}}\int_{S^{n-1}}\!\int_{0}^{+\infty}\frac{f_{t}(ru)-f(ru)}{t}r^{n-1}\,dr\,du=\lim_{t\to0^{+}} \int_{S^{n-1}}F_{t}(u)\,du,
    \end{align*}  where, for $u\in \sphere$,   $$F_{t}(u):= \int_{0}^{+\infty}\frac{f_{t}(ru)-f(ru)}{t}r^{n-1}\,dr.$$ 

   For $u\in \sphere$, let  \begin{align*}
       G_t(u): =  \int_{0}^{+\infty}\frac{\big(1-\alpha \varphi+\alpha t \inf\psi^*\big)^{\frac{1}{\alpha}}(ru)-f(ru)}{t}r^{n-1}\,dr,
\end{align*} where $\inf\psi^* >-\infty$ due to \eqref{3.11}. 
It follows from \eqref{3.11} that $$\varphi^*+t\inf\psi^*\leq \varphi^*+t\psi^*\leq(1+t\beta_1)\varphi^*+t\beta_2.$$ This implies that, for $t>0$ small enough,\begin{align} \label{compare-3-functions}
\big(1-\alpha \varphi+\alpha t \inf\psi^*\big)^{\frac{1}{\alpha}}\leq f_t\leq \widehat{f_{t}}.\end{align} Together with \eqref{widehat}, we get 
     \begin{equation}\label{double1continuity}
     \lim_{t\to0^{+}}{f_{t}}(x)=f(x).
     \end{equation} For $t>0$ small enough, the support of  $\big(1-\alpha \varphi+\alpha t \inf\psi^*\big)^{\frac{1}{\alpha}}$ is equal to $K_f$.  Moreover,  
\begin{align}
 \label{compare-F-G-E}
    G_t\leq F_t\leq E_t\ \ \mathrm{and} \ \ K_f\subset K_{f_t}\subset K_{\widehat{f_{t}}}.
\end{align}   It follows from  Lemma \ref{lem6} and the generalized dominated convergence theorem that
    $$\lim_{t\to 0^{+}}\int_{S^{n-1}}F_{t}(u)\,du = \int_{S^{n-1}}\lim_{t\to 0^{+}}F_{t}(u)\,du.$$
We can rewrite $F_t(\cdot)$ as follows: for $u\in \sphere,$
    \begin{align} F_{t}(u)= \int_{0}^{\rho_{K_{f}}(u)}\frac{f_{t}(ru)-f(ru)}{t}r^{n-1}\,dr + \int_{\rho_{K_{f}}(u)}^{\rho_{K_{f_{t}}}(u)}\frac{f_{t}(ru)}{t}r^{n-1}\,dr,\label{rewrite-F-t}\end{align} where the second integral is treated as $0$ if $u\notin \Omega_f$ (i.e., $\rho_{K_f}(u)=+\infty$)  due to \eqref{compare-F-G-E}. That is, if $u\notin \Omega_{f}$,
     \begin{equation}\label{bounddiff1}
    \int_{\rho_{K_{f}}(u)}^{\rho_{K_{f_{t}}}(u)}\frac{f_{t}(ru)}{t}r^{n-1}\,dr=0.
    \end{equation} Similar to \eqref{radialdiff},  it can be checked from \eqref{double1continuity} that, for almost every $u\in\Omega_f$,   
    \begin{align}\label{bounddiff}
        \lim_{t\to 0^{+}}\int_{\rho_{K_{f}}(u)}^{\rho_{K_{f_{t}}}(u)}\frac{f_{t}(ru)}{t}r^{n-1}\,dr&= \lim_{t\to 0^{+}} f_{t}(r(t,u)u)r(t,u)^{n-1}\lim_{t\to 0^{+}}\frac{\rho_{K_{f_{t}}}(u)-\rho_{K_{f}}(u)}{t}\nonumber\\
        &= f(\rho_{K_{f}}(u)u)\rho_{K_{f}}(u)^{n-1}\frac{h_{\dpsi}(\nu_{K_{f}}(\rho_{K_{f}}(u)u))}{\left\langle u,\nu_{K_{f}}(\rho_{K_{f}}(u)u))\right\rangle},
    \end{align}
    where $r(t,u)\in[\rho_{K_f}(u),\rho_{K_{f_{t}}}(u)]$ such that $ \lim_{t\to 0^{+}}r(t,u)=\rho_{K_f}(u)$.

    Next, we will compute, for almost all  $u\in \sphere$:  
    $$\lim_{t\to 0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\frac{f_{t}(ru)-f(ru)}{t}r^{n-1}\,dr.$$ 
    For $t>0$ small enough and $u\in \sphere$, let 
   \begin{align*} \mathcal{F}_{t,u}(r)&=\frac{f_{t}(ru)-f(ru)}{t}r^{n-1}, \\ \mathcal{G}_{t,u}(r)&=\frac{\big(1-\alpha \varphi+\alpha t \inf\psi^*\big)^{\frac{1}{\alpha}}(ru)-f(ru)}{t}r^{n-1}.\end{align*} 
    It follows from \eqref{compare-3-functions} that  
    $\mathcal{G}_{t,u}(r)\leq \mathcal{F}_{t,u}(r)\leq \mathcal{E}_{t,u}(r)$. Together with Lemma \ref{lem7} and the generalized dominated convergence theorem, we have  
     $$\lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{F}_{t,u}(r)\,dr=\int_{0}^{\rho_{K_{f}}(u)}\lim_{t\to 0^{+}}\mathcal{F}_{t,u}(r)\,dr.$$
   Similar to the proof for \eqref{3.13}, by \eqref{double1continuity} and Lemma \ref{Berman's formula} (applying to $\varphi^*$ and $\psi^*$), we have
    \begin{align*}
    \lim_{t\to 0^+}\mathcal{F}_{t,u}(r) =\lim_{t\to 0^+}\frac{f_t(ru)-f(ru)}{t}r^{n-1}  =\psi^*(\nabla \varphi(ru))f(ru)^{1-\alpha}r^{n-1}, 
    \end{align*}  holds for almost all $u\in \sphere$ such that $ru\in \dom\varphi$. Therefore,
    \begin{equation}\label{ft}
    \lim_{t\to0^{+}}\int_{0}^{\rho_{K_{f}}(u)}\mathcal{F}_{t,u}(r)\,dr=\int_{0}^{\rho_{K_{f}}(u)}\psi^*(\nabla \varphi(ru))f(ru)^{1-\alpha}r^{n-1}\,dr.
    \end{equation} 

    Combining \eqref{rewrite-F-t}, \eqref{bounddiff1},  \eqref{bounddiff}, and \eqref{ft}, we have  
 \begin{align*}
    \lim_{t\to 0^{+}}\int_{S^{n-1}}F_{t}(u)\,du &= \int_{S^{n-1}}\lim_{t\to 0^{+}}F_{t}(u)\,du\\
    &=\int_{S^{n-1}}\int_{0}^{\rho_{K_{f}}(u)}\psi^*\left(\nabla \varphi(ru)\right) f(ru)^{1-\alpha}r^{n-1}\,dr\,du\\
     &\qquad+ \int_{\Omega_f}f(\rho_{K_{f}}(u)u)\rho_{K_{f}}(u)^{n-1}\frac{h_{\dpsi}(\nu_{K_f}(\rho_{K_f}(u)u))}{\langle u,\nu_{K_f}(\rho_{K_f}(u)u)\rangle}\,du\\
    &=\int_{\Rn}\psi^*\left(\nabla \varphi(x)\right) f(x)^{1-\alpha}\,dx + \int_{\partial {K_f}}{h_{\dpsi}(\nu_{K_f}(x))}f(x)\,d\mathcal{H}^{n-1}(x).
\end{align*} This completes the proof of \eqref{main-formular}.  \end{proof}

Our next result is to relax the conditions $-\infty<\inf \psi^*<\psi^*$ in  \eqref{3.11}  (implying $o\in \dom\psi$) and $o\in \mathrm{int}(K_f)$.
Note that the last inequality in \eqref{3.11}  implies $$\overline{\dom \psi} \subset \beta_1 \overline{\dom\varphi}=\beta_1 K_f.$$ The idea is to translate $\dom\psi$ to $(\dom\psi)-x_0$ for some $x_0\in (\dom\psi)\cap\mathrm{int}(\beta_1K_f)$. Let  \begin{align}\label{def-psi-tilde-varphi} 
    \widetilde{\psi}(x)=\psi(x+x_0) \ \ \mathrm{and} \ \ \widetilde{\varphi}(x)=\varphi\Big(x+\frac{x_0}{\beta_1}\Big).
\end{align} Then, $\dom\widetilde{\psi}=\dom\psi-x_0$ and hence $o\in \dom\widetilde{\psi}.$ It can be checked that $\widetilde{\psi}^*\geq -\widetilde{\psi}(o)=-\psi(x_0)$ and hence \begin{align}\label{tildeinf}
-\infty<\inf\widetilde\psi^*\leq\widetilde\psi^*.
\end{align}
On the other hand, $x_0\in \mathrm{int}(\beta_1 K_f )$ and then $o\in \beta_1 \mathrm{int}(K_f-\frac{x_0}{\beta_1})$. That is, $$o\in \mathrm{int}\Big(K_f-\frac{x_0}{\beta_1}\Big)=\mathrm{int}(\dom\widetilde{\varphi}).$$ Moreover, if $\psi$ satisfies $\psi^*\leq \beta_1\varphi^*+\beta_2$, then, for any $y\in \Rn$, \begin{align*}
    \widetilde{\psi}^*(y)=\psi^*(y)-\langle x_0, y\rangle \nonumber \leq \beta_1\varphi^*(y)+\beta_2-\langle x_0, y\rangle \nonumber=\beta_1 \Big(\varphi^*(y)-\big\langle \frac{x_0}{\beta_1}, y\big\rangle\Big)+\beta_2\nonumber=\beta_1  \widetilde{\varphi}^*(y) +\beta_2.
\end{align*} Together with \eqref{tildeinf}, we see that $\widetilde{\varphi}$ and $\widetilde{\psi}$ satisfy the condition \eqref{3.11}, namely, 
\begin{align*}-\infty<\inf\widetilde\psi^*\leq\widetilde\psi^*\leq\beta_1  \widetilde{\varphi}^* +\beta_2. 
\end{align*} This  allows us to use the result in Theorem \ref{thm8}. 

 We shall need the following lemma.  
\begin{lemma}\label{lem9}
    Let $-\frac{1}{n}<\alpha <0$ and  $f = (1-\alpha\varphi)^{\frac{1}{\alpha}}\in \CA(\Rn)$ with $\mathrm{int}(K_f)\neq\emptyset$.
    Then, for any $u\in \sphere,$
    \begin{equation}\label{3.12}
         \int_{\Rn}\langle u,\nabla \varphi(x)\rangle f(x)^{1-\alpha}\,dx + \int_{\partial {K_f}}\langle u,\nu_{K_f}(x)\rangle f(x)\,d\mathcal{H}^{n-1}(x)=0.
    \end{equation} 
\end{lemma}

\begin{proof}
Choose $x_0\in \mathrm{int}(K_f)$. Let $\overline{\varphi}(x)=\varphi(x+x_0)$  and  $$\overline {f}(x)=(1-\alpha\overline\varphi(x))^{\frac{1}{\alpha}}=(1-\alpha\varphi(x+ x_0))^{\frac{1}{\alpha}}.$$  Then, $o\in \mathrm{int}(K_{\overline f})$ and $\overline\varphi^*(x)=\varphi^*(x)-\langle x_0,x\rangle$. From \eqref{3.1-no-beta}, we have
 \begin{align*}
 \JD(\overline f,\overline f)
 =n\Ja(\overline f) - \!\! \int_{\Rn}\overline\varphi(x)\overline f(x)^{1-\alpha}\,dx =n\Ja(f) -\!\!  \int_{\Rn}\varphi(x)f(x)^{1-\alpha}\,dx =\JD( f, f).
  \end{align*}
Applying Theorem \ref{thm8} to $\overline f$, by $K_{\overline f}= K_{ f}-x_0$ and $z=x+x_0$, it follows that 
\begin{align*}
 \JD(\overline f,\overline f)
 &=\int_{\Rn}\overline\varphi^*\left(\nabla \overline\varphi(x)\right) \overline f(x)^{1-\alpha}\,dx +\! \int_{\partial {K_{\overline f}}}{h_{K_{\overline f}}(\nu_{K_{\overline f}}(x)})\overline f(x)\,d\mathcal{H}^{n-1}(x)\\&=\int_{\Rn}\overline\varphi^*\left(\nabla  \varphi(x+x_0)\right)  f(x+x_0)^{1-\alpha}\,dx \\ & \quad +\! \int_{\partial {(K_{f}-x_0)}}{h_{(K_{ f}-x_0)}(\nu_{(K_{ f}-x_0)}(x)})  f(x+x_0)\,d\mathcal{H}^{n-1}(x)\\&=\int_{\Rn}\overline\varphi^*\left(\nabla  \varphi(z)\right)  f(z)^{1-\alpha}\,dz +\! \int_{\partial {K_{f}}}{h_{(K_{ f}-x_0)}(\nu_{K_{ f}}(z)})  f(z)\,d\mathcal{H}^{n-1}(z)\\
 &=\int_{\Rn}\varphi^*\left(\nabla \varphi(z)\right)  f(z)^{1-\alpha}\,dz + \int_{\partial {K_{ f}}}{h_{K_f}(\nu_{K_{ f}}(z)})f(z)\,d\mathcal{H}^{n-1}(z)\\ 
 &\quad -\int_{\Rn}\langle x_0,\nabla \varphi(z)\rangle f(z)^{1-\alpha}\,dz - \int_{\partial {K_f}}\langle x_0,\nu_{K_f}(z)\rangle f(z)\,d\mathcal{H}^{n-1}(z)\\
 &=\JD( f, f),  \end{align*} which is independent of $x_{0}$. This further implies that,  for any $x_0\in\mathrm{int}(K_f)$,\begin{align}\label{u}\int_{\Rn}\langle x_0,\nabla \varphi(z)\rangle f(z)^{1-\alpha}\,dz + \int_{\partial {K_f}}\langle x_0,\nu_{K_f}(z)\rangle f(z)\,d\mathcal{H}^{n-1}(z)=c, \end{align} where $c$ is a constant independent of $x_0$. Because $x_0\in \mathrm{int}(K_f)$, there exits $\epsilon>0$ such that $x_0+\epsilon B_2^n\subset \mathrm{int}(K_f)$. That is, for $u\in\sphere$, $x_0+\epsilon u\in\mathrm{int}(K_f)$ and thus, 
 \begin{align*}\int_{\Rn}\langle x_0+\epsilon u,\nabla \varphi(z)\rangle f(z)^{1-\alpha}\,dz + \int_{\partial {K_f}}\langle x_0+\epsilon u,\nu_{K_f}(z)\rangle f(z)\,d\mathcal{H}^{n-1}(z)=c. \end{align*}
 Together with \eqref{u}, we get, for any $u\in\sphere$,
\begin{align*}
 \int_{\Rn}\langle u,\nabla \varphi(z)\rangle f(z)^{1-\alpha}\,dz + \int_{\partial {K_f}}\langle u,\nu_{K_f}(z)\rangle f(z)\,d\mathcal{H}^{n-1}(z)=0.
 \end{align*} 
This completes the proof of \eqref{3.12}.
\end{proof}   
Our main result in this section is summarized in the following theorem. 
\begin{theorem}\label{thm10}
     Let $-\frac{1}{n}<\alpha < 0$, and $f=(1-\alpha\varphi)^{\frac{1}{\alpha}}\in \CA(\Rn) $. Assume that $\psi\in \conv(\Rn)$, and there exist constants $\beta_{1}> 0$ and $\beta_{2}\in\R$  satisfying
$$   (\dom \psi) \cap\mathrm{int}(\beta_1K_f)\neq\emptyset  \ \ \mathrm{and}\ \ \psi^*\leq\beta_1\varphi^*+\beta_2.$$ Let  $f_t$ be  given in \eqref{define-f-1-1} for $t>0$ small enough.
    Then,
\begin{equation}\label{3.12-1}
        \lim_{t\to 0^{+}}\!\int_{\Rn}\!\! \frac{{{f}_{t}}(x)\!-\!f(x)}{t}\,dx= \int_{\Rn}\! \psi^*\!\left(\nabla \varphi(x)\right) f(x)^{1-\alpha}\,dx + \! \int_{\partial {K_f}}\!  {h_{\dpsi}\!(\nu_{K_f}\!(x))}f(x)\,d\mathcal{H}^{n-1}(x).
    \end{equation}
\end{theorem} 

\begin{proof} Let $x_0\in\dom \psi$ and hence $\frac{x_0}{\beta_1}\in \mathrm{int}(K_f)$. Let $\widetilde{\varphi}$ and  $\widetilde{\psi}$ be given in \eqref{def-psi-tilde-varphi}. As claimed above, $\widetilde{\varphi}$ and  $\widetilde{\psi}$  satisfy the condition \eqref{3.11}. Let \begin{align*} \widetilde f(x)&=(1-\alpha\widetilde\varphi(x))^{\frac{1}{\alpha}}=\Big(1-\alpha\varphi\Big(x+\frac{x_0}{\beta_1}\Big)\Big)^{\frac{1}{\alpha}},\\ \widetilde{f}_{t, \widetilde{\psi}} &=\big( 1-\alpha (\widetilde{\varphi}^*+t\widetilde{\psi}^*)^*\big)^{\frac{1}{\alpha}}. \end{align*}  It can be easily checked that, for all $t>0$ small enough, \begin{align} \int _{\Rn} f(x)\,dx=\int _{\Rn} \widetilde{f}(x)\,dx\ \ \mathrm{and}\ \ \int _{\Rn} f_t(x)\,dx=\int _{\Rn} \widetilde{f}_{t, \widetilde{\psi}}(x)\,dx. \label{equal-two-total mass}\end{align}



 Applying Theorem \ref{thm8} with $\widetilde f$ and $\widetilde \psi$, it follows from $K_{\widetilde f}= K_{ f}-\frac{x_0}{\beta_1}$,  $ \dom\widetilde\psi= \dom\psi-x_0$ and $z=x+\frac{x_0}{\beta_1}$ that 
\begin{align*}
        \lim_{t\to 0^{+}}\! \int_{\Rn}\!\!\!\!\! \frac{\widetilde{f}_{t, \widetilde{\psi}}(x)\!-\!\widetilde f(x)}{t}dx\! &=\!\!  \int_{\Rn}\widetilde\psi^*(\nabla \widetilde\varphi(x)) \widetilde f(x)^{1-\alpha}\,dx +\! \int_{\partial {K_{\widetilde f}}}{h_{\dwpsi}(\nu_{K_{\widetilde f}}(x))}\widetilde f(x)\,d\mathcal{H}^{n-1}(x)\nonumber\\&= \!\!\int_{\Rn} \widetilde\psi^*\bigg(\!\nabla  \varphi\Big(x+\frac{x_0}{\beta_1}\Big)\!\bigg) f\bigg(x+\frac{x_0}{\beta_1}\bigg)^{1-\alpha}\,dx \nonumber \\& \quad +\! \int_{\partial (K_{ f}-\frac{x_0}{\beta_1})}{h_{(\dpsi-x_0)}(\nu_{(K_{ f}-\frac{x_0}{\beta_1})}(x))}f\bigg(x+\frac{x_0}{\beta_1}\bigg)\,d\mathcal{H}^{n-1}(x)\nonumber\\
        &= \!\!\int_{\Rn} \!\!\widetilde\psi^*\big(\nabla  \varphi (z )\big) f(z)^{1-\alpha}dz \!+\! \!\int_{\partial K_{ f}}\!\!\!\!h_{(\dpsi-x_0)}(\nu_{K_{f}}\!(z))f(z)\,d\mathcal{H}^{n-1}(z)\nonumber\\
        &=  \!\!\int_{\Rn}\psi^*\left(\nabla \varphi(z)\right)  f(z)^{1-\alpha}\,dz + \int_{\partial {K_{ f}}}{h_{\dpsi}(\nu_{K_{ f}}(z)})f(z)\,d\mathcal{H}^{n-1}(z)\nonumber\\
        &\quad \!-\!\int_{\Rn}\langle x_0,\nabla \varphi(z)\rangle f(z)^{1-\alpha}\,dz - \!\int_{\partial {K_f}}\!\langle x_0,\nu_{K_f}(z)\rangle f(z)\,d\mathcal{H}^{n-1}(z)\nonumber \\ &=\!\!  \int_{\Rn}\psi^*\left(\nabla \varphi(z)\right)  f(z)^{1-\alpha}\,dz +\! \int_{\partial {K_{ f}}}{h_{\dpsi}(\nu_{K_{ f}}(z)})f(z)\,d\mathcal{H}^{n-1}(z),
    \end{align*} where in the last equality, we have used \eqref{3.12}. Combining with \eqref{equal-two-total mass}, we get 
\begin{align*}
        \lim_{t\to 0^{+}} \int_{\Rn}\!\!  \frac{f_{t}(x)-f(x)}{t}\,dx& =\!\lim_{t\to 0^{+}} \int_{\Rn}\!\! \frac{\widetilde{f}_{t, \widetilde{\psi}}(x)\!-\!\widetilde f(x)}{t}\,dx \\  &= \! \int_{\Rn}\!\!\! \psi^*(\nabla \varphi(x))  f(x)^{1-\alpha}\,dx + \int_{\partial {K_{ f}}}\!\!\! {h_{\dpsi}(\nu_{K_{ f}}(x)})f(x)\,d\mathcal{H}^{n-1}(x).
    \end{align*} This completes the proof of \eqref{3.12-1}.\end{proof}

The following corollary follows directly from Theorem \ref{thm10} and Definition \ref{Definition-first-variation}.
%\begin{align*}
%f_t=f\oplus_{\alpha} t\bigcdot g = \Big(1-\alpha(\varphi^*+t\psi^*)^*\Big)^{\frac{1}{\alpha}}
%\end{align*} which is well-defined for all $t>0$ small enough.

\begin{theorem}\label{MainTheorem1}
   Let $-\frac{1}{n}<\alpha < 0$, and $f=(1-\alpha\varphi)^{\frac{1}{\alpha}}\in \CA(\Rn) $. Assume that $g = (1-\alpha\psi)^{\frac{1}{\alpha}}\in \mathcal{C}_{\alpha}^{+}(\mathbb{R}^{n})$, where $\psi\in \conv(\Rn)$, and there exist constants $\beta_{1}> 0$ and $\beta_{2}\in\R$  satisfying $$ (\dom \psi) \cap\mathrm{int}(\beta_1K_f)\neq\emptyset
 \ \ \mathrm{and}\ \ \psi^*\leq\beta_1\varphi^*+\beta_2.$$ Then, the following equality holds:
\begin{align*}
       \JD(f,g)= \int_{\Rn} \psi^*\!\left(\nabla \varphi(x)\right)\! f(x)^{1-\alpha}\,dx + \! \! \int_{\partial {K_f}} {h_{K_g}(\nu_{K_f}(x))}f(x)\,d\mathcal{H}^{n-1}(x).
    \end{align*}
\end{theorem} 

Theorem \ref{thm10} motivates the following definitions for two measures associated with the $\alpha$-concave function, one defined on $\Rn$ and the other   defined  on  $\sphere$.

\begin{definition}\label{}
Let $-\frac{1}{n}<\alpha < 0$ and $f=(1-\alpha\varphi)^{\frac{1}{\alpha}}\in \CA(\Rn)$. 

\vskip 2mm \noindent (i) Define the Borel measure $\mu_{\alpha}(f,\cdot)$, which is called the Euclidean surface area measure  of the  $\alpha$-concave function $f$,  as follows: for every Borel subset $\eta\subset \mathbb{R}^n$,
\begin{align}\label{euclidean-moment-measure}
\mu_{\alpha}(f,\eta)=\int_{\big\{x\in\mathbb{R}^n:\nabla\varphi(x)\in \eta\big\}} f(x)^{1-\alpha}\,dx.
\end{align}
where $\nabla\varphi$ is the gradient of $\varphi$. That is,  $\mu_{\alpha}(f, \cdot)=(\nabla\varphi)_{\sharp}(f^{1-\alpha}\,dx)$, the push-forward measure of $f^{1-\alpha}\,dx=  (1-\alpha\varphi)^{\frac{1-\alpha}{\alpha}}\,dx $ under the map $\nabla \varphi$,

\vskip 2mm \noindent (ii)  Define the Borel measure $\nu_{\alpha}(f,\cdot)$, which is called the spherical surface area measure of the  $\alpha$-concave function $f$,  as follows:  for every Borel subset $\eta\subset S^{n-1}$,
\begin{align} \label{spherical-moment-measure}
\nu_{\alpha}(f,\eta)=\int_{\big\{x\in{\partial{K_f}}:\ \nu_{K_f}(x)\in \eta\big\}}f(x)\,d\mathcal{H}^{n-1}(x).
\end{align} That is,   $\nu_{\alpha}(f, \cdot)=(\nu_{K_{f}})_{\sharp}\big(f\,d\mathcal{H}^{n-1}|_{\partial K_{f}}\big).$ 
\end{definition}   When $\varphi\geq 0$ satisfies that  $\nabla \varphi: \mathrm{int}(\dom\varphi) \rightarrow \mathrm{int}(\dom\varphi^*)$ is smooth and bijective, the measure $\mu_{\alpha}(f, \cdot)$ is absolutely continuous with respect to the Lebesgure measure and satisfies \begin{align}\label{density-eucldiean measure}
\frac{d\mu_{\alpha}(f, y)}{dy}=\det(\nabla^2\varphi^*(y)) \Big(1-\alpha \big(\langle y, \nabla \varphi^*(y)\rangle -\varphi^*(y)\big)\Big)^{\frac{1-\alpha}{\alpha}} \ \ \mathrm{for} \ \  y\in \Rn. \end{align} In fact, under the above assumptions on $\varphi,$ one has,  \begin{align}
\varphi^*(\nabla \varphi(x))= \langle x , \nabla \varphi(x) \rangle -\varphi(x). \label{def-dual-2}
\end{align} It follows from \eqref{euclidean-moment-measure} that \begin{align}\label{equivalent-f-varphi}
    \int_{\Rn} g(y)\,d\mu_{\alpha}(f, y)=\int_{\Rn}g(\nabla \varphi(x))f(x)^{1-\alpha}\,dx
\end{align} holds for every Borel function $g$ such that $g \in L ^ 1 (\mu_{\alpha} (f,\cdot))$  or $g$ is non-negative. By  letting $y=\nabla \varphi(x)$ (equivalently, $x=\nabla \varphi^*(y)$),  it follows from \eqref{def-dual-2} and \eqref{equivalent-f-varphi} that 
\begin{align*}
\int_{\Rn}g(y)\, d\mu_{\alpha} (f, y)& =\int_{\Rn}g(\nabla \varphi(x))(1-\alpha \varphi(x))^{\frac{1-\alpha}{\alpha}} \,dx\\&
=\int_{\Rn}g(y)  \det(\nabla^2\varphi^*(y)) \Big(1-\alpha \big(\langle y, \nabla \varphi^*(y)\rangle -\varphi^*(y)\big)\Big)^{\frac{1-\alpha}{\alpha}}  \,dy,
\end{align*} which further implies \eqref{density-eucldiean measure}, as desired. 




Having defined the Euclidean and spherical surface area measures of an $\alpha$-concave function (for $-\frac{1}{n}< \alpha< 0$), it is natural and interesting to study the following Minkowski problem related to $\alpha$-concave functions. 
\begin{problem}[The functional Minkowski problem for $\alpha$-concave functions]\label{Mink-double-1} Let $ -\frac{1}{n}<\alpha< 0$, and let $\mu$ and $\nu$ be two Borel measures defined on $\Rn$ and respectively, on $\sphere$. Find the necessary and/or sufficient conditions on $\mu$ and $\nu$, such that there exists an $\alpha$-concave function $f$ satisfying 
$$\mu =  \mu_{\alpha}(f,\cdot) \ \ \mathrm{and}\ \ \nu= \nu_{\alpha}(f, \cdot).$$   
\end{problem} When $\nu_{\alpha}(f, \cdot)=0$,   
Problem \ref{Mink-double-1} can be rewritten as follows. 

\begin{problem}[The Euclidean functional Minkowski problem for $\alpha$-concave functions] \label{problem-E-FMP} Let $ -\frac{1}{n}<\alpha< 0$  and $\mu$  be a Borel measure  defined on $\Rn$. Find the necessary and/or sufficient conditions on $\mu$, such that there exists an $\alpha$-concave function $f$ satisfying 
\begin{align}
    \mu =   \mu_{\alpha}(f,\cdot)\ \ \ \text{and}\ \ \ 0=\nu_{\alpha}(f,\cdot).\label{mu=mu-alpha}
\end{align}   
\end{problem}  According to \eqref{density-eucldiean measure}, if $\,d\mu(y)=h(y)\,dy$ and $\varphi\geq 0$ is smooth enough, then equation \eqref{mu=mu-alpha}  reduces to   the following Monge-Amp\'{e}re equation: 
\begin{align*}
h(\nabla\varphi(y)){\rm det}(\nabla^2\varphi(y))= \big(1-\alpha \varphi(y)\big)^{\frac{1-\alpha}{\alpha}},  
\end{align*}  with $\varphi$ being the unknown nonnegative convex function on $\Rn.$

\section{\texorpdfstring{The Minkowski problem for $\alpha$-concave functions and $\alpha$-concave measures}{The Minkowski problem for alpha-concave functions and alpha-measures}} \label{section-solution}
We will show the  necessary conditions to Problem \ref{problem-E-FMP} in Subsection \ref{necessary-1}. In Subsection \ref{section-extended}, we will solve a Minkowski problem extending Problem \ref{problem-E-FMP} to $\alpha$-concave measures instead of $\alpha$-concave functions. The main technique used in Subsection \ref{section-extended} is optimal transport, which has been successfully used in solving the Minkowski type problems for the moment measures of log-concave functions in \cite{San16} by Santambrogi and for the $q$-moment measure in \cite{HK21} by Huynh and Santambrogio.  
\subsection{\texorpdfstring{Properties of the Euclidean surface area measure $\mu_{\alpha}(f, \cdot)$}{}} \label{necessary-1}  A convex function $\phi : \mathbb{R}^n \to \mathbb{R} \cup \{+\infty\}$ is  \textit{essentially continuous} if it is lower semi-continuous and the set of its discontinuous points (on $\partial(\operatorname{dom}\phi)$) has zero   $\mathcal{H}^{n-1}$ measure. According to \cite[Lemma 3]{EK15}, if a convex function $\phi$ is essentially continuous, its restriction to almost every line must be  continuous. 

Let $\varphi$ be the base function of the $\alpha$-concave function $f$, that is, $f=(1-\alpha \varphi)^{\frac{1}{\alpha}}$. Then,  $\varphi$ is essentially continuous if and only if $f\equiv 0$ for $\mathcal{H}^{n-1}$-almost every $x\in \partial K_f$.   This is equivalent to say that the spherical moment  measure $\nu_{\alpha}(f,\cdot)$ defined in \eqref{spherical-moment-measure} is a zero measure. We call $f$ an\textit{ $\alpha$-concave function with essentially continuous base} if its base is essentially continuous.  


The following lemma proves that the measure $\mu_{\alpha}(f, \cdot)=(\nabla\varphi)_{\sharp}(f^{1-\alpha}\,dx)$, for an $\alpha$-concave function $f\in \mathcal{C}_{\alpha}^{+}(\Rn)$ with essentially continuous base must have finite first moment and its  barycenter is the origin. Note that, for each $i=1, 2,\cdots, n$, we get  
\begin{align*}%\label{barycenter=0-1}
       \int_{\Rn} x_i\,d\mu_{\alpha}(f, x)=\int_{\Rn}\frac{\partial \varphi(x)}{\partial x_{i}}(1-\alpha\varphi(x))^{\frac{1}{\alpha}-1}\,dx.
   \end{align*} If \eqref{barycenter=0} holds, then, for each $i=1, 2, \cdots, n,$  \begin{align*}
       \int_{\Rn} x_i\,d\mu_{\alpha}(f, x)=0.
   \end{align*} Hence for each $y\in \Rn,$  it holds that \begin{align*} 
       \int_{\Rn} \langle x, y\rangle\,d\mu_{\alpha}(f, x)=0.
   \end{align*} That is, the barycenter of $\mu_{\alpha}(f, \cdot)$ is at the origin. On the other hand, if \eqref{first-moment-finite} holds, then %by letting $y=\nabla \varphi(x)$,  
   \begin{align*}
       \int_{\Rn}|y| \,d\mu_{\alpha}(f, y)=\int_{\Rn}\left |\nabla \varphi(x)\right| f^{1-\alpha}(x)\,dx= \int_{\Rn}\left |\nabla f(x)\right|dx<\infty,
   \end{align*} and hence the first moment of $\mu_{\alpha}(f, \cdot)$ is finite. 

\begin{lemma}\label{Lem7}
    Let $-\frac{1}{n}<\alpha<0$ and $f\in \CA(\Rn)$ be an $\alpha$-concave function with  essentially continuous base $\varphi$. Then, 
    \begin{align}\label{first-moment-finite}
        \int_{\Rn}\left |\nabla f(x)\right|dx <+\infty,
    \end{align} 
    and, for any $i=1,\dots,n$,
   \begin{align}\label{barycenter=0}
       \int_{\Rn}\frac{\partial \varphi(x)}{\partial x_{i}}(1-\alpha\varphi(x))^{\frac{1}{\alpha}-1}\,dx=\int_{\Rn}\frac{\partial f(x)}{\partial x_{i}}\,dx =0.
   \end{align} 

\end{lemma}
\begin{proof} The proof follows essentially the approach used in 
 \cite[Lemma 4]{EK15}. For completeness, we will give the proof but with modification concentrated. 


    First of all, we verify the following claim:  for   any $i=1,\dots,n$,
    $$
    \int_{\Rn} \left| \frac{\partial f(x)}{\partial x_{i}} \right|dx < +\infty.
    $$ To this end, without  loss of generality, let $i=n$ and write $x=(x',t)$ for any $x\in \Rn$. It is easily checked that the function $t\mapsto\varphi(x',t)$ is convex and  coercive, hence it is  non-increasing in  $(-\infty,c]$ and non-decreasing in $[c, \infty)$ for some $c\in \R.$ Thus,   $t\mapsto f(x',t)$ is non-decreasing in $(-\infty,c]$ and non-increasing in $[c, \infty)$. Moreover,  $f$ is locally Lipschitz since it is the composition of the generator function $\Psi_{\alpha}$, which is convex in $[0,+\infty)$, and the convex function $\varphi$. Therefore, $ \frac{\partial f(x', t)}{\partial x_n }=\frac{\partial f(x', t)}{\partial t}$ exists almost everywhere. Applying  the Lebesgue version of the Fundamental Theorem of Calculus \cite[Theorem 3.35]{Fol99}, we get, for any $x'\in \R^{n-1},$
    \begin{align*}
        \int_{\R}\left |\frac{\partial f(x',t)}{\partial x_{n}}\right|dt &=  \int_{\R}\left |\frac{\partial f(x',t)}{\partial t}\right|dt=\int_{-\infty}^{c}\frac{\partial f(x',t)}{\partial t}\,dt-\int_{c}^{+\infty}\frac{\partial f(x',t)}{\partial t}\,dt\\
        &= 2f(x',c)=2\sup_{t\in\R}f(x',t)=2\left( 1-\alpha\inf_{t\in\R}\varphi(x',t)\right)^{\frac{1}{\alpha}}.
    \end{align*} By the Tonelli theorem, we have \begin{align}
        \label{application-T} \int_{\Rn}\left |\frac{\partial f(x)}{\partial x_{n}}\right|\,dx=\int_{\mathbb{R}^{n-1}}\int_{\R}\left |\frac{\partial f(x',t)}{\partial t}\right|\,dt\,dx'=2\int_{\mathbb{R}^{n-1}}\left( 1-\alpha\inf_{t\in\R}\varphi(x',t)\right)^{\frac{1}{\alpha}}dx'. 
    \end{align} 
Note that $ x'\mapsto \inf_{t\in\R}\varphi(x',t)$ is a function 
defined on $\R^{n-1}$ and satisfies \begin{align*}
 \inf_{t\in\R}\varphi(x',t)\geq a\inf_{t\in\R}|(x', t)|+b =a|x'|+b,  
\end{align*}  where $a>0$ and $b\in \R$ are given by  \eqref{coercive}. Thus, $x'\mapsto \inf_{t\in\R}\varphi(x',t)$ verifies the assumption which is the key ingredient in  the proof of Lemma \ref{Lem2.2} and $-\frac{1}{n-1}<-\frac{1}{n}<\alpha<0$. Therefore, the integral in \eqref{application-T} must be   finite following the proof of Lemma \ref{Lem2.2}. Consequently, \eqref{first-moment-finite} follows immediately due to the fact that $$|\nabla f|\leq \sqrt{n} \max \Big\{  \Big|\frac{\partial{f}}{\partial x_i}\Big|,\ i=1, 2, \cdots, n\Big\}.$$

We can apply  \cite[Lemma 3]{EK15} to get that   $t\mapsto f(x',t)$ is continuous for almost every $x'$. Let $[a_{1},b_{1}]$ be  the support of $t\mapsto f(x',t)$, where $a_{1}$ and $b_{1}$ may be  infinity. Then, 
    $$\int_{\R}\frac{\partial f(x',t)}{\partial x_{n}}\,dt=\int_{[a_{1},b_{1}]}\frac{\partial f(x',t)}{\partial t}\,dt = \lim_{t\to b_{1}}f(x',t) - \lim_{t\to a_{1}}f(x',t) =0.$$
    Using the Fubini’s theorem, we get 
    $$\int_{\Rn}\frac{\partial  f(x)}{\partial x_{n}}\,dx = \int_{\mathbb{R}^{n-1}}\left( \int_{\R}\frac{\partial f(x',t)}{\partial x_{n}}\,dt\right)dx'=0.$$ This completes the proof. 
\end{proof}

 Our next lemma is to prove that $\mu_{\alpha}(f,\cdot)$ is not concentrated in any  proper linear subspace of $\Rn$, and hence not concentrated in any hyperplane (due to the fact that the barycenter of $\mu_{\alpha}(f, \cdot)$ is at the origin $o$). 
\begin{lemma}\label{Lem8}
     Let $-\frac{1}{n}<\alpha<0$ and $f=(1-\alpha \varphi)^{\frac{1}{\alpha}}\in \CA(\Rn)$ be an $\alpha$-concave function with  essentially continuous base $\varphi$ such that  $0<\Ja(f)<+\infty$. Then, $\mu_{\alpha}(f, \cdot)$ is not concentrated in any proper linear subspace of $\Rn$.
\end{lemma} \begin{proof} The proof follows essentially the approach used in  \cite[Lemma 6]{EK15} . For completeness, we will give the proof but with modification concentrated. 

Assume the opposite, that is,  the support of $\mu_{\alpha}(f, \cdot)$ is contained in a proper linear subspace, say  $ e_n^{\perp}=\big \{x\in \Rn: x_n=0 \big\}$, the proper linear subspace with normal vector $e_{n}$. It follows from $\mu_{\alpha}(f, \cdot)=(\nabla\varphi)_{\sharp}(f^{1-\alpha}\,dx)$ that 
   \begin{align*}
   0 &=\int_{ \Rn\setminus e_n^{\perp} }\left |x_{n}\right|d\mu_{\alpha}(f, x)+\int_{   e_n^{\perp}}\left |x_{n}\right|d\mu_{\alpha}(f, x)\\ & =\int_{\Rn}\left |x_{n}\right|d\mu_{\alpha}(f, x) \\ &= \int_{\Rn}\left |\frac{\partial \varphi(x)}{\partial x_{n}}\right|(1-\alpha\varphi(x))^{\frac{1}{\alpha}-1}\,dx\\&=\int_{\Rn}\Big|\frac{\partial f}{\partial x_n}\Big|\,dx.    
   \end{align*} Consequently, for almost all $x=(x', t)\in \Rn,$
   we have 
   $$
    \frac{\partial f(x)}{\partial x_n}=\frac{\partial f(x',t)}{\partial t}=0.
    $$   

    By the locally Lipschitz property of $f$ in $\mathrm{int}(K_f)$ and the Lebesgue version of  the Fundamental Theorem of Calculus, for almost $x'\in \R^{n-1}$, if  $(x', t)\in \mathrm{int}(K_f)$, then $f(x', t)$ is a constant on $t$. On the other hand,  by \cite[Lemma 3]{EK15}, for almost all $x'\in \R^{n-1},$ $t\mapsto f(x',t)$  is  continuous on $t$ in $\R$, which implies $f(x' ,t)$ is a constant on $t\in \R.$  Therefore, $\int_{\R}f(x',t)\,dt\in \{0,+\infty\}$ for almost all $x'\in \R^{n-1}$. This is a contradiction to the assumption that $0<\Ja(f)<\infty$, because the  Fubini's theorem gives $$\Ja(f)=\int_{\Rn} f(x)\,dx \in \{0,+\infty\}.$$ This completes the proof. 
\end{proof}

Combining Lemmas \ref{Lem7} and \ref{Lem8}, we can get the following result. 
\begin{theorem}\label{Nec-Conditions}
    Let $-\frac{1}{n}<\alpha<0$ and $f=(1-\alpha\varphi)^\frac{1}{\alpha}\in \CA(\Rn)$ have  an essentially continuous base $\varphi$ such that  $0<\Ja(f)<+\infty.$  Then, $$\mu_{\alpha}(f, \cdot)=(\nabla\varphi)_{\sharp} (f^{1-\alpha}\,dx) $$ has a finite first moment, its barycenter is at the origin and its support is not contained in any hyperplane. 
\end{theorem}


The results in Theorem \ref{Nec-Conditions} provide the necessary conditions to the solution to Problem \ref{problem-E-FMP}, namely, $\mu$ is a finite nonzero Borel measure on $\Rn$ whose first moment is finite, barycenter is at the origin, and support is not contained in any hyperplane. 

\subsection{A  solution to an extended Minkowski problem  via optimal transport} \label{section-extended} In this section, we will show that the conditions in Theorem \ref{Nec-Conditions} are also sufficient to solve a Minkowski problem weaker than Problem \ref{problem-E-FMP}. We will prove the sufficiency using optimal transport as did in  \cite{HK21, San16}.




Recall that  $ \varrho\ll \mathcal{L}^{n}$ if $\varrho$ is absolutely continuous with respect to  $ \mathcal{L}^{n}$. It follows from the Radon-Nikodym theorem that there exists a density function $\rho$ such that $\, \,d\varrho =\rho \,dx$.  In order to state our weak Minkowski problem, we need to consider  the measure  \begin{align}\label{a-con-measure}\varrho = \rho\,dx + \varrho^{s},
\end{align}
where, for some convex function $\varphi\geq \frac{1}{\alpha}$,
$$\rho(x)=  \left( 1-\alpha\varphi(x)\right)^{\frac{1}{\alpha}};$$ and the singular part $\varrho^{s}$ is mutually singular with respect to the Lebesgue measure, denoted by $\varrho^{s}\perp \mathcal{L}^{n}$, and is concentrated on the set $\left\{\varphi =  \frac{1}{\alpha}\right\}$. 
When a finite measure  $\varrho$ is not absolutely continuous with respect to $\mathcal{L}^{n}$,   then both  $\rho\,dx$ and   $\varrho^s\neq 0$ are   finite. If $\varrho$ satisfies \eqref{a-con-measure}, then $\varrho$ is called  an \textit{$\alpha$-concave measure}. For the total mass $|\varrho|=\int_{\Rn}\,d\varrho$  to be finite, the set $\left\{\varphi =  \frac{1}{\alpha}\right\}$ must be a $\mathcal{L}^{n}$-null set. In the particular case when $\left\{\varphi =  \frac{1}{\alpha}\right\}$ is singleton, $\rho^{s}$ must be a multiple of a Dirac delta measure. 



We extend the surface area measures from $\alpha$-concave functions to $\alpha$-concave measures. 

\begin{definition}\label{def-measure-measure}
    Let $\varrho$ be a finite  $\alpha$-concave measure as given in \eqref{a-con-measure}. One says that $\mu$ is a    \textit{Euclidean surface area measure}    of $\varrho$,  if there is a measure $\pi$ on $\mathbb{R}^{n}\times \mathbb{R}^{n}$, whose marginals are $\rho^{1-\alpha}\,dx+\varrho^s$ and $\mu$:$$\pi(A\times \mathbb{R}^{n}) = \big(\rho^{1-\alpha}\,dx+\varrho^s\big)(A)\ \ \mathrm{and} \ \ \pi(\mathbb{R}^{n}\times B) = \mu(B)$$  for any $\big(\rho^{1-\alpha}\,dx+\varrho^s\big)$-measurable set $A$ and  $\mu$-measurable set $B$; and $$\mathrm{Supp}(\pi)\subset \mathrm{Graph}(\partial \varphi):=\{(x,y)\in \mathbb{R}^{n}\times \mathbb{R}^{n}:y\in \partial \varphi(x)\},$$i.e.,  $ 
y\in \partial \varphi(x) 
$  for $\pi$-almost every $(x,y)$. The spherical surface area of $\varrho$ is defined by $$(\nu_{K_{\rho}})_{\sharp}\big(\rho\,d\mathcal{H}^{n-1}|_{\partial K_{\rho}}\big).$$\end{definition}



The Minkowski problem for $\alpha$-concave functions can be extended as follows. 

\begin{problem}[The extended Minkowski problem for $\alpha$-concave measures] \label{problem-FMP-measure}
 Let $-\frac{1}{n}<\alpha<0$ and let $\mu$  be a Borel measure  on $\Rn$ and $\nu$ be a Borel measure on $S^{n-1}$. Does  there exist an $\alpha$-concave measure $\varrho$, given by \eqref{a-con-measure}, such that $\mu$ and $\nu$ are the Euclidean and the spherical surface area measures of $\varrho$, respectively?      
\end{problem} 

The extended version of Problem \ref{problem-E-FMP} can be stated as follows.

\begin{problem} \label{problem-E-FMP-measure}
    Let $-\frac{1}{n}<\alpha<0$ and $\mu$ be a Borel measure on $\mathbb{R}^{n}$. Does there exists an $\alpha$-concave measure $\varrho$ such that $\mu$ is the Euclidean surface area measure of $\varrho$ and the spherical surface area measure of $\varrho$ is the zero measure?
\end{problem}

In this paper, we only focus on Problem \ref{problem-E-FMP-measure}. In general, however, $\mu$ may not be uniquely determined. Notably, for almost every $x\in  \left\{\varphi > \frac{1}{\alpha}\right\}$, we have $y = \nabla \varphi(x)$. When $\inf \varphi=\frac{1}{\alpha}$  and $\varphi$ is differentiable at 
  $x\in \left\{\varphi=  \frac{1}{\alpha}\right\}$, we have $\partial \varphi(x) = \{o\}$,  and hence  $
\mu = (\nabla\varphi)_{\sharp}(\rho^{1-\alpha}\,dx+\varrho^s).
$  In particular, if $\varphi>\frac{1}{\alpha}$ on $\Rn,$ then $
\mu = (\nabla\varphi)_{\sharp} (\rho^{1-\alpha}\,dx)
$ is exactly the Euclidean surface area measure of the $\alpha$-concave function $\rho=(1-\alpha \varphi)^{\frac{1}{\alpha}}$ defined in \eqref{euclidean-moment-measure} and the extended Minkowski problem (i.e., Problem \ref{problem-E-FMP-measure}) reduces to the Euclidean functional Minkowski problem for $\alpha$-concave functions (i.e.,  Problem \ref{problem-E-FMP}). 





% **Example. $\varphi = \frac{1}{\alpha} + |x|^{p}$** with $p>n|\alpha|$ and $\rho(x) = (-\alpha)^{1/\alpha}|x|^{p/\alpha}\,dx$




Let $\varrho$ be a probability measure on $\mathbb{R}^{n}$.  In order to solve the extended Minkowski problem for $\alpha$-concave measures, we need to define   \begin{align*}\label{R-D-theorem} \mathcal{F}_{\alpha}(\varrho )=-\int_{\Rn}\rho^{\frac{1}{1-\alpha}}(x)\,dx \end{align*} for any finite  $\alpha$-concave measure  $\varrho=\rho\,dx+\varrho^{s}$. Recall that $\mathcal{T}(\varrho,\mu)$ is defined in \eqref{def-T-2} by:  
\begin{align*}  
\mathcal{T}(\varrho,\mu):&=\sup\left\{\int_{\mathbb{R}^{n}\times \mathbb{R}^{n}}\langle x,  y\rangle\,d\pi(x, y):\pi\in\Pi(\varrho,\mu)\right\}
\\&=\inf\left\{\int_{\Rn}\varphi \,d\varrho+\int_{\Rn}\varphi^{*} \,d\mu:\varphi\text{ is convex and lower semi-continuous}\right\},
\end{align*} where 
   $\varphi^*$ is the Legendre transform of $\varphi.$ If the measure $\mu$ has its barycenter at $o$, we can see that $\mathcal{T}(\varrho, \mu)$ is invariant regarding the translation of the measure $\varrho$, due to Proposition \ref{[San16,Prop3.1]}.   
Note that   $\mathcal{P}_1(\Rn)$ denotes the set of probability measures on $\Rn$ with finite first moment. By $\mathrm{Supp}(\mu)$ we mean the support of $\mu.$

\begin{proposition}\label{PropertyOfMinimizer}
Let $-\frac{1}{n}<\alpha<0$ and $\mu\in\mathcal{P}_1(\Rn)$. Suppose that the barycenter of $\mu$ is $o$, and $\mu$ is not supported in any hyperplane. Then, any minimizer $\varrho_0$ (assuming the existence) of following problem
\begin{equation} \label{P}
\inf\Big\{(1-\alpha)\mathcal{F}_{\alpha}(\varrho)-\alpha\mathcal{T}(\varrho,\mu):\varrho\in \mathcal{P}_{1}(\Rn)\Big\}
\end{equation}
satisfies that for some lower semi-continuous convex function $\varphi_0$,
\begin{align*}
    \varrho_0 = (1-\alpha\varphi_0)^{\frac{1}{\alpha}-1}\,dx + \varrho_{0}^{s},
\end{align*}
where $\varrho_{0}^{s}$ and $\mathcal{L}^{n}$ are mutually singular, and if $\varrho_{0}^{s}\neq 0$, then $\mathrm{Supp}(\varrho_{0}^{s})\subset\{\varphi_{0}= \frac{1}{\alpha}\}$. Furthermore, the function $\varphi_{0}$ satisfies
\begin{equation}\mathcal{T}(\varrho_{0},\mu)=\int_{\mathbb{R}^{n}}\varphi_{0}\, d\varrho_{0}+\int_{\mathbb{R}^{n}}\varphi_{0}^*\, \,d\mu. \label{T(Rho0,Mu)}\end{equation}
\end{proposition}

\begin{proof} 
Suppose that $\varrho_{0}=\rho_{0}\,dx+\varrho^{s}_{0}$ is a minimizer of \eqref{P}.  Let $\varrho_{\tau}:=\tau^{-n}\omega_{n}^{-1}\mathbf{1}_{\{|x|\leq \tau\}}\,dx\in\mathcal{P}_{1}(\Rn)$. Then
\begin{align}&(1-\alpha)\mathcal{F}_{\alpha}(\varrho_{\tau})-\alpha\mathcal{T}(\varrho_{\tau},\mu)\nonumber \\&=-(1-\alpha)\!\int_{\mathbb{R}^{n}}\!\left( \tau^{-n}\omega_{n}^{-1}\mathbf{1}_{\{|x|\leq \tau\}}\right)^{\frac{1}{1-\alpha}}\,dx-\alpha\sup\left\{\int_{\mathbb{R}^{n}\times \mathbb{R}^{n}}\langle x,  y\rangle\,d\pi(x, y):\pi\in\Pi(\varrho_{\tau},\mu)\right\}\nonumber\\&\leq -(1-\alpha)\omega_{n}^{\frac{-\alpha}{1-\alpha}}\tau^{\frac{-n\alpha}{1-\alpha}}-\alpha\tau\int_{\mathbb{R}^{n}}|y|\,d\mu(y).\label{NonzeroAbsContPart}\end{align}
Since $-\frac{1}{n}<\alpha<0$, we have $\frac{-\alpha n}{1-\alpha}<1$. Hence, if we choose $\tau$ such that 
$$0<\tau ^{1+\frac{\alpha n}{1-\alpha}}< \frac{(1-\alpha)\omega_{n}^{\frac{-\alpha}{1-\alpha}}}{-\alpha  \int_{\mathbb{R}^{n}}|y|\,d\mu(y)},$$
then, from \eqref{NonzeroAbsContPart} and the minimizing property of $\varrho_{0}$, we obtain
\begin{align}(1-\alpha)\mathcal{F}_{\alpha}(\varrho_{0})-\alpha\mathcal{T}(\varrho_{0},\mu)\leq (1-\alpha)\mathcal{F}_{\alpha}(\varrho_{\tau})-\alpha\mathcal{T}(\varrho_{\tau},\mu) < 0.\label{NegativityOfMinimum}\end{align}
% Let  $C$ be the unit cube and $\varrho_C$ be the uniform measure on $C$ with density function $\mathbf{1}_{C}$. Then
% $$
% \mathcal{F}_{\alpha}(\varrho_{C})=-\int_{C} \mathbf{1}_{C}(x)^{\frac{1}{1-\alpha}}\,dx = -1.
% $$
% We choose $k_{0}>0,$ so that 
% $$
% k_{0}(1-\alpha)\mathcal{F}_{\alpha}(\mathbf{1}_{C})-\alpha\mathcal{T}(\mathbf{1}_{C},\mu)<0.
% $$
