Let $\varphi _1 $ be a convex lower semi-continuous function that is an optimal function of $\mathcal{T}(\varrho_{0},\mu)$. Namely, $\varphi_{1}$ (and hence $\varphi_{1}+c_{0}$ for any constant $c_{0}$) must satisfy
    \begin{equation}\mathcal{T}(\varrho_{0},\mu) = \int_{\Rn}\varphi_1  \,d\varrho_{0}+\int_{\Rn}\varphi_1 ^{*}\,d\mu.\label{T(Rho0,Mu)2}\end{equation}
Without loss of generality, we assume   $\inf\varphi_1 =0$. Because $\mu$ is fixed, $\varrho_{0}=\rho_0\,dx+\varrho_0^s$ is a minimizer of the following functional defined on $\mathcal{P}_{1}(\Rn)$:
$$G:\varrho\mapsto  (1-\alpha)\mathcal{F}_{\alpha}(\varrho) -\alpha\int_{\Rn}\varphi_1  d{\varrho}.$$

We now prove   $\varrho_{0} \neq\varrho_{0}^{s}$ by contradiction.  Assume that $\varrho_{0}=\varrho_{0}^{s}$. Then,  
\begin{align}\label{G-rho>0}G(\varrho_0) = -\alpha\int_{\mathbb{R}^{n}}\varphi_1 \,d\varrho_0^{s} \geq 0 .\end{align}
On the other hand, let $x_{n}$ be a sequence such that $\varphi_1 (x_{n})\to 0$ as $n\to\infty$. Then by \eqref{NegativityOfMinimum}, one has
\begin{align*}G(\varrho_{0}) &= (1-\alpha) \mathcal{F}_\alpha(\varrho_{0})-\alpha \mathcal{T}(\varrho_{0}, \mu) +\alpha\int_{\mathbb{R}^{n}}\varphi_1^{*} \,d\mu\\
&<\alpha\int_{\mathbb{R}^{n}} \varphi_1^{*}\,d\mu\leq \alpha \int (\chi_{\{x_{n}\}} +\varphi_1(x_{n}))^{*}\,d\mu,\end{align*} where 
$\chi_E(x)=0$ if $x\in E$ and $\chi_E(x)=\infty$ if $x\notin E$. It can be checked by \eqref{legendre-tran} that $$(\chi_{\{x_{n}\}} +\varphi_1 (x_{n}))^{*}(x)=\langle x, x_n\rangle-\varphi_1 (x_n).$$ This further gives 
\begin{align*}  G(\varrho_{0})  <\alpha\int_{\mathbb{R}^{n}} \varphi_1^{*}\,d\mu  \leq \lim_{n\rightarrow \infty}   \alpha\int \left\langle x,x_{n}\right\rangle \,d\mu -\lim_{n\rightarrow \infty}  \alpha\varphi_1 (x_{n})
=0,
\end{align*} where we have used the fact that $\mu$ has its barycenter at $o$ and $\varphi_1(x_n)\rightarrow 0. $
This is a contradiction to \eqref{G-rho>0}, and hence   $\varrho_0\neq \varrho_0^s$. That is, $\rho_0\,dx$ is not a zero measure and $\rho_0$ is nonzero on a set of positive $\mathcal{L}^n $ measure. Hence, $\mathrm{Supp}(\rho_0)$ is nonempty and has positive $\mathcal{L}^n $ measure.  


Next we prove that  $\mathcal{L}^{n}(\{ \varphi_1  < \infty\}\setminus\{\rho_{0}>0\})=0$. Let $A:= \{\varphi_1 < \infty\}\setminus\{\rho_{0}>0\}$ and suppose, for the sake of contradiction, that $\mathcal{L}^{n}(A)>0$. Then there exists a point $x_{0}\in A$ such that for any ball $B$ containing $x_{0}$, we have $\mathcal{L}^{n}(B\cap A)>0$. Indeed, suppose the contrary, that for every $x\in A$, there exists a ball $B_{x}$ containing $x$ such that $\mathcal{L}^{n}(B_{x}\cap A) = 0$. Since the countable set $\mathcal{B}=\{B(q,r):q\in \mathbb{Q}^{n},r\in \mathbb{Q},r>0\}$, where $B(q,r)=q+rB^n_2$, forms a basis for the Euclidean topology on $\mathbb{R}^{n}$, there exists $B(q_{x},r_{x})\in\mathcal{B}$ such that $x\in B(q_{x},r_{x})\subset B_{x}$ for each $x\in A$. Because the collection $\{B(q_{x},r_{x}):x\in A\} \subset \mathcal{B}$ is countable, there exists a countable subcollection $\{B_{x_{i}}\}_{i=1}^{\infty}$ of $\{B_{x}:x\in A\}$ that covers $A$. Then
$$\mathcal{L}^{n}(A)\leq \mathcal{L}^{n}\Big(\bigcup_{i=1}^{\infty}(B_{x_{i}}\cap A)\Big)\leq \sum_{i=1}^{\infty}\mathcal{L}^{n}(B_{x_{i}}\cap A)=0,$$
which is a contradiction to the assumption on $A$. 

With the help of the above argument, we can now  find a contradiction to the assumption that $\mathcal{L}^{n}(A)>0$ by transporting a little mass of $\rho_{0}\,dx$ to a neighborhood of $x_{0}$. To do so, let $S_{1}\subset \{\rho_{0}>0\}$  be a set of positive $(\rho_{0}\,dx)$-measure, and hence positive $\mathcal{L}^{n}$-measure (because $\rho_{0}\,dx\ll \mathcal{L}^{n}$), such that,  $0<\inf_{S_{1}}\rho_{0} = c$. Let $\varepsilon<c$. By shrinking $S_{1}$ if necessary, we can choose $S_{2}\subset A$ containing $x_{0}$ such that $\mathcal{L}^{n}(S_{2}) = \mathcal{L}^{n}(S_{1})$. Consider $\varrho_{1}\in \mathcal{P}_{1}(\Rn)$ such that $\varrho_{1}^{s} = \varrho_{0}^{s}$ and
$$
\rho_{1}  = \left\{ \begin{array}{cl} \rho _{0}-\varepsilon, &\ \ \text{on }S_{1},\\\varepsilon,&\ \ \text{on } S_{2},\\ \rho_{0},  &\ \ \text{otherwise}.\end{array}\right.
$$
We compare $G(\varrho_{1})$ with $G(\varrho_{0})$ for small $\varepsilon$. Shrinking $S_{1}$ again, we can assume that $S_{2}$ is a subset of $\{x\in A:|\varphi_1(x)-\varphi_1(x_{0})|<\delta\}$ for some small number $\delta$. Then
\begin{equation}\int_{\Rn} \varphi_1 \,d\varrho_{1} < \int_{\Rn} \varphi _1\,d\varrho_{0}+\varepsilon\int_{S_{2}}\varphi_1\,dx \leq \int_{\Rn} \varphi _1 \,d\varrho_{0}+\varepsilon\mathcal{L}^{n}(S_{2})(\varphi_1(x_{0})+\delta).\label{BoundOfIntOfPhiRho1}\end{equation}
Moreover, from the concavity of $t^{k}$ with $0<k<1$, we obtain %(so that $x^{k}-y^{k}\leq k y^{k-1}(x-y)$), 
\begin{align}\mathcal{F}_{\alpha}(\varrho_{1})-\mathcal{F}_{\alpha}(\varrho_{0})&= \int_{\Rn}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\int _{\Rn} \rho_{1}^{\frac{1}{1-\alpha}}(x)\,dx \nonumber
\\&= \int_{S_{1}}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\int_{S_{1}}\big( \rho_{0}(x)-\varepsilon\big)^{\frac{1}{1-\alpha}}\,dx-\int_{S_{2}}  \varepsilon ^{\frac{1}{1-\alpha}}\,dx \nonumber
\\&\leq\frac{1}{1-\alpha}\int_{S_{1}}(\rho_{0}(x)-\varepsilon)^{\frac{\alpha}{1-\alpha}}\varepsilon \,dx-\mathcal{L}^{n}(S_{2})\varepsilon^{\frac{1}{1-\alpha}}\nonumber
\\&\leq \frac{1}{1-\alpha}(c-\varepsilon)^{\frac{\alpha}{1-\alpha}}\mathcal{L}^{n}(S_{1})\varepsilon-\mathcal{L}^{n}(S_{1})\varepsilon^{\frac{1}{1-\alpha}}\nonumber
\\&\leq \bigg( \frac{(c-\varepsilon_0)^{\frac{\alpha}{1-\alpha}}}{1-\alpha}\varepsilon_0^{\frac{-\alpha}{1-\alpha}}-1\bigg)\mathcal{L}^{n}(S_{1})\varepsilon^{\frac{1}{1-\alpha}}, \label{BoundOfF(Rho1)}
\end{align} for any $0<\varepsilon<\varepsilon_0$, where   $0<\varepsilon_{0}<c$ is small enough so that  
 \begin{align*}  \frac{(c-\varepsilon_0)^{\frac{\alpha}{1-\alpha}}}{1-\alpha}\varepsilon_0^{\frac{-\alpha}{1-\alpha}}-1 <0. 
\end{align*} 
Together with \eqref{BoundOfIntOfPhiRho1} and \eqref{BoundOfF(Rho1)}, we have
\begin{align*}
    G(\varrho_{1})-G(\varrho_{0}) &< (1-\alpha) \bigg( \frac{(c-\varepsilon _0)^{\frac{\alpha}{1-\alpha}}}{1-\alpha}\varepsilon_0 ^{\frac{-\alpha}{1-\alpha}}-1\bigg)\mathcal{L}^{n}(S_{1})\varepsilon ^{\frac{1}{1-\alpha}} -\alpha\mathcal{L}^{n}(S_{1})(\varphi_{1}(x_{0})+\delta)\varepsilon , 
\end{align*}  which is negative if $0<\varepsilon<\varepsilon_0$ satisfies
$$
\varepsilon^{\frac{-\alpha}{1-\alpha}}<\frac{(1-\alpha)\big(1-\frac{(c-\varepsilon_0)^{\frac{\alpha}{1-\alpha}}}{1-\alpha}\varepsilon_0 ^{\frac{-\alpha}{1-\alpha}}\big)  }{-\alpha \left(\varphi_{1}(x_0\right)+\delta)}.
$$ Hence, we obtain a contradiction to the fact that $\varrho_{0}$ minimizes $G$. Therefore, for $\mathcal{L}^{n}$-almost every $x$, if $\varphi_1(x) < \infty$, then $\rho _{0}(x)>0$. 

