We now claim that $\varrho_{0}$ is also a minimizer of a linearized functional of $G$ on a subset of $\mathcal{P}_{1}(\mathbb{R}^{n})$. To this end, using the fact that $\varrho_{0}$ is a minimizer of $G$, we have that for any $0<t<1$, there exists $0<t_{\rho}<t$ such that
\begin{align}\label{GateauxDerivative}  0&\leq \frac{G(\varrho_{0}+t(\varrho-\varrho_{0}))-G(\varrho_{0})}{t}\nonumber \\
    &=(\alpha-1)  \int_{\Rn}\frac{\left(\rho_{0}+t(\rho-\rho_{0})\right)^{\frac{1}{1-\alpha}}- \rho_{0} ^{\frac{1}{1-\alpha}}}{t}\,dx -\alpha\int_{\Rn}\varphi_{1} d(\varrho-\varrho_{0})\nonumber  \\
    &=-\int_{\Rn}(\rho_{0}+t_{\rho} (\rho-\rho_{0}))^{\frac{\alpha}{1-\alpha}}(\rho-\rho_{0})\,dx-\alpha\int_{\Rn}\varphi_{1} d(\varrho-\varrho_{0}),
    \end{align}    
where the last equality follows from the mean value theorem. Notice that 
    $$
(\rho_{0}+t_{\rho}(\rho-\rho_{0}))^{\frac{\alpha}{1-\alpha}}|\rho-\rho_{0}|\leq \big(\min\{\rho,\rho_{0}\}\big)^{\frac{\alpha}{1-\alpha}}|\rho-\rho_{0}|.
    $$
Assume that $\varrho\in \mathcal{S}$, where $\mathcal{S}$ is given by 
$$\mathcal{S}:= \left\{\varrho\in\mathcal{P}_{1}(\mathbb{R}^{n}):\big(\min\{\rho,\rho_{0}\}\big)^{\frac{\alpha}{1-\alpha}}\left |\rho-\rho_{0}\right| \in L^{1}(\mathbb{R}^{n})\right\}.$$
  The set $\mathcal{S}$ is nonempty as $\varrho_{0}\in\mathcal{S}$. Let $\phi:=\rho-\rho_{0}$. By the dominated convergence theorem,
\begin{equation}\label{DCT}
    \lim_{t\to 0^{+}}\int_{\Rn}(\rho_{0}+t\phi)^{\frac{\alpha}{1-\alpha}}\phi\,dx = \int_{\Rn}\lim_{t\to 0^{+}}(\rho_{0}+t\phi)^{\frac{\alpha}{1-\alpha}}\phi\,dx = \int_{\Rn} \rho_{0} ^{\frac{\alpha}{1-\alpha}}\phi\,dx.
    \end{equation}
    Combining (\ref{GateauxDerivative}) and (\ref{DCT}), we find that $\varrho_{0}$ is a minimizer on $\mathcal{S}$ of the functional
  \begin{align*}
     L:\varrho & \mapsto -\int_{\Rn}\rho\rho_{0}^{\frac{\alpha}{1-\alpha}}\,dx-\alpha\int_{\Rn}\varphi_{1} \,d\varrho\\ 
    &=\int_{\mathbb{R}^{n}}\rho\left( -\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1}\right)dx-\alpha\int_{\mathbb{R}^{n}}\varphi_{1} \,d\varrho^{s}.
  \end{align*} 


Next we prove that $\rho_{0}\,dx$ must be concentrated on the set $\{-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_1 =c_{0}\}$, where $c_{0} \leq 0$ is a constant. Recall that $\mathrm{ess\,sup}f = \inf\{c:f(x)\leq c\text{ for $\mathcal{L}^{n}$-a.e. }x\}$ and $\mathrm{ess\,inf}f = -\mathrm{ess\,sup}(-f)$. Suppose, for the sake of contradiction, that 
    $$
   c_{1}:=\mathrm{ess\,inf}_{\{\rho_{0}>0\}}\Big\{-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1}\Big\}<\mathrm{ess\,sup}_{\{\rho_{0}>0\}}\Big\{-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1}\Big\}:= c_{2},$$
where $c_1$ and $c_2$ could be infinite. We can choose a constant $c_3\in (c_1, c_2)$ and two sets 
    $$
    S_{3}\subset \left\{x:c_{1}\leq -\rho_{0}^{\frac{\alpha}{1-\alpha}}(x)-\alpha\varphi_{1}(x)\leq c_3 \right\} \ \ \mathrm{and} \ \
    S_{4}\subset \left\{x:c_3< -\rho_{0}^{\frac{\alpha}{1-\alpha}}(x)-\alpha\varphi_{1}(x)\leq c_{2}\right\}
    $$
    such that $\inf_{S_{4}}\rho_{0} = c'>0$, $\inf_{S_{3}} \rho_{0}>0$, and 
    $$
    0< \mathcal{L}^{n}(S_{3})=\mathcal{L}^{n}(S_{4})<+\infty.
    $$

   Consider $\varrho = \rho\,dx + \varrho^{s}\in\mathcal{P}_{1}(\mathbb{R}^{n})$ such that $\varrho^{s} = \varrho_{0}^{s}$ and
    $$
    \rho=\begin{cases}\rho_{0}+\frac{c'}{2}&\text{on }S_{3},\\\rho_{0}-\frac{c'}{2} &\text{on }S_{4},\\\rho_{0} &\text{otherwise}.\end{cases}
    $$
 It follows that 
    \begin{align*}\int_{\mathbb{R}^{n}} \min\{\rho,\rho_{0}\}^{\frac{\alpha}{1-\alpha}}\left |\rho-\rho_{0}\right|dx&=\frac{c'}{2}\int_{S_{3}}\rho_{0}^{\frac{\alpha}{1-\alpha}}dx+\frac{c'}{2}\int_{S_{4}}\left( \rho_{0}-\frac{c'}{2}\right)^{\frac{\alpha}{1-\alpha}}dx
    \\&\leq \frac{c'}{2}\Big( \inf_{S_{3}}\rho_{0}\Big)^{\frac{\alpha}{1-\alpha}}\mathcal{L}^{n}(S_{3})+\frac{c'}{2}\left( \frac{c'}{2}\right)^{\frac{\alpha}{1-\alpha}}\mathcal{L}^{n}(S_{4})
    \\&<+\infty.\end{align*}
That is $\varrho\in \mathcal{S}$. On the other hand, 
    \begin{align*}L(\varrho)&= L(\varrho_{0})+\frac{c'}{2}\int_{S_{3}}(-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1})\,dx-\frac{c'}{2}\int_{S_{4}}(-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1})\,dx<L(\varrho_{0}),\end{align*}
     which is a contradiction to the fact that $\varrho_{0}$ is a minimizer of $L$ on $\mathcal{S}$. Hence, $\rho_{0}$ must be concentrated on the set $$\{-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_1 =c_{0}\}$$ for some constant $c_{0}$. This means for $\mathcal{L}^{n}$-almost every $x\in \{\rho_{0}>0\}$, we have $-\rho_{0}(x)^{\frac{\alpha}{1-\alpha}}(x)-\alpha\varphi_{1}(x) = c_{0}$. As claimed above, $\mathcal{L}^{n}(\{\varphi_{1}<\infty\}\setminus \{\rho_{0}>0\}) = 0$, so by redefining $\rho_{0}$ on a Lebesgue null set, we may assume that, if $\varphi_{1}(x)<\infty$, then $\rho_{0}(x)>0$ and
     $$-\rho_{0}^{\frac{\alpha}{1-\alpha}}(x)-\alpha\varphi_{1}(x) = c_{0}.$$

     We now claim that  $c_{0}\leq 0$. To this end, take  the sequence $x_{n}$ such that $\varphi_{1}(x_{n})\to 0=\inf \varphi_{1}$, and then 
    $$
    c_{0}=\lim_{n\to\infty}(-\rho_{0}(x_{n})^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1}(x_{n}) ) = - \lim _{n\to\infty}\rho_0\left(x_n\right)^{\frac{\alpha}{1-\alpha}}\leq 0.
    $$     
 From the fact that $\rho_{0}\,dx$ is concentrated on the set $\{-\rho_{0}^{\frac{\alpha}{1-\alpha}}-\alpha\varphi_{1} =c_{0}\}$, on the set $\{\varphi_{1}<\infty\}$, we necessarily have
  $$
    \rho_{0} = \Bigg( 1-\alpha\bigg( \varphi_{1}+\frac{c_{0}+1}{\alpha}\bigg)\Bigg)^{\frac{1-\alpha}{\alpha}}:=  \big( 1-\alpha \varphi_0 \big)^{\frac{1-\alpha}{\alpha}}.
    $$
As $c_0\leq 0$ and $
-\frac{1}{n}<\alpha<0$, we have $$\varphi_0 =\varphi_{1}+\frac{c_{0}+1}{\alpha}\geq \frac{1}{\alpha}.$$ In the set $\{\varphi_{1}=\infty\}$, we have $\rho_{0}=0$ almost everywhere with respect to $\rho_{0}\,dx$,  as otherwise $G(\varrho_{0}) = \infty$. Clearly, $\varphi_{0}$ satisfies \eqref{T(Rho0,Mu)}, due to \eqref{T(Rho0,Mu)2}.

Finally, we prove that $\operatorname{Supp}\left(\varrho_0^s\right) \subset\left\{\varphi_0=\frac{1}{\alpha}\right\}$. Assume $\varrho_{0}^{s}\neq 0$. If $c_{0}=0$ and $\mathrm{Supp}(\varrho_{0}^s)$ is not a subset of $\{\varphi_{1}=0\}=\{\varphi_{0}=\frac{1}{\alpha}\}$, then
$$\int \varphi_{1} \,d\varrho_0^{s} > 0 = \lim_{n\to\infty}\int \varphi_{1} \,d\delta_{x_{n}},$$ where $x_n$ is such that $\varphi_1(x_n)\to0$, a contradiction to the minimality of  $\varrho_{0}$ for $G$. If $c_{0}<0$, then $$L\bigg( \frac{\rho_{0}dx}{\int \rho_{0}dx}\bigg)< L(\varrho_{0}),$$ which is a contradiction to the minimality of $\varrho_{0}$ for $L$ on $\mathcal{S}$. The conclusion follows.
\end{proof}

The next result in this section concerns the existence of minimizers to problem (\ref{P}). To establish such a result, we need the following lemma.
\begin{lemma}\label{LowerBoundOfFa}
    Let $-\frac{1}{n}<\alpha<0$. Then, there exist constants $C$, $\alpha_{1}\in (0,-\alpha n)$, and $\alpha_{2}\in (-\alpha n,1)$, such that, for any $\varrho\in \mathcal{P}_{1}(\Rn)$, one has
    \begin{equation*}
        \mathcal{F}_{\alpha}(\varrho)\geq C-\left(\int_{\mathbb{R}^n}|x| \,d \varrho(x)\right)^{\alpha_1} -\left(\int_{\mathbb{R}^n}|x| \,d \varrho(x)\right)^{\alpha_2}.
    \end{equation*}
\end{lemma}

\begin{proof}
    Let $\varrho=\rho\,dx+\varrho^s\in \mathcal{P}_{1}(\Rn)$, and $g(\tau)=-\tau^{\frac{1}{1-\alpha}}$ for $\tau\in(0,+\infty)$.  The Legendre transform of $g$ is a function $g^*: (-\infty,0)\to \R$ given by 
    $$g^{*}(t) =\sup_{\tau\in (0, \infty) }
    \big(t \cdot \tau-g(\tau)\big)=-\alpha(1-\alpha)^{\frac{1}{\alpha}-1}(-t)^{\frac{1}{\alpha}},$$ for $t\in (-\infty, 0).$ Clearly, we have Young's inequality $$g^{*}(t)+g(\tau)\geq t\tau,\ \ \ \mathrm{for} \ \tau>0,t<0.$$
    Let $\beta:=-\alpha(1-\alpha)^{\frac{1}{\alpha}-1}>0$, $\alpha_{1}\in (0,-\alpha n)$, and $\alpha_{2}\in (-\alpha n,1)$. Then, \begin{align}\label{alpha1alpha2}\int_{\{|x|\leq 1\}} |x|^{\frac{\alpha_{1}}{\alpha}}\,dx<+\infty \ \ \mathrm{and}\ \ \int_{\{|x|\geq 1\}} |x|^{\frac{\alpha_{2}}{\alpha}}\,dx<+\infty.\end{align} We can apply the above Young's inequality to $\tau=\rho(x)$, $t=-|x|^{\alpha_{i}}$, $g(\tau)$ and $g^*(t)$, to obtain the following inequality:  
    \begin{equation}-\rho(x)\left |x\right|^{\alpha_{i}}\leq -\rho(x)^{\frac{1}{1-\alpha}}+\beta \left |x\right|^{\frac{\alpha_{i}}{\alpha}}.\label{Young'sIneq}\end{equation}  As $\alpha_1\in (0, -\alpha n)\subset (0,1)$, we can  apply Jensen’s inequality to get 
    \begin{align*}-\int_{\{|x|\leq 1\}}\rho^{\frac{1}{1-\alpha}}(x)\,dx &\geq -\beta \int_{\{|x|\leq 1\}} \left |x\right|^{\frac{\alpha_{1}}{\alpha}}dx-\int_{\{|x|\leq 1\}} \rho(x)\left |x\right|^{\alpha_{1}}dx
    \\
    &\geq C_{1}- \int_{\Rn}  \left |x\right|^{\alpha_{1}}d\varrho(x)\\
    &\geq C_{1}-\left( \int_{\Rn} |x|\,d\varrho(x)\right)^{\alpha_{1}}.\end{align*}
    Similarly, as $\alpha_2\in (0, 1)$, Jensen’s inequality implies 
    \begin{align*}-\int_{\{|x|\geq 1\}}\rho^{\frac{1}{1-\alpha}}(x)\,dx&\geq -\beta \int_{\{|x|\geq 1\}} \left |x\right|^{\frac{\alpha_{2}}{\alpha}}dx-\int_{\{|x|\geq 1\}} \rho(x)\left |x\right|^{\alpha_{2}}dx
    \\
    &\geq C_{2}-\int_{\Rn}  \left |x\right|^{\alpha_2}d\varrho(x)\\
    &\geq C_{2}-\left( \int_{\Rn}  \left |x\right|d\varrho(x)\right)^{\alpha_{2}}.\end{align*}
    It then follows that
    $$\mathcal{F}_{\alpha}(\varrho)\geq C_{1}+C_{2} -\left(\int_{\mathbb{R}^n}|x| \,d \varrho(x)\right)^{\alpha_1} -\left(\int_{\mathbb{R}^n}|x| \,d \varrho(x)\right)^{\alpha_2}.$$ This completes the proof. 
\end{proof}

 We need the following proposition as well. 
\begin{proposition}\label{Existence}
     Let $-\frac{1}{n}<\alpha<0$ and $\mu\in\mathcal{P}_1(\Rn)$. Suppose that the barycenter of $\mu$ is $o$, and $\mu$ is not supported in any hyperplane. Then there exists a solution to the problem (\ref{P}). 
\end{proposition}
\begin{proof} Recall that, if  $\mu$ has its barycenter at the origin $o$, we can see that $\mathcal{T}(\varrho, \mu)$, and  hence $$
(1-\alpha)\mathcal{F}_{\alpha}(\varrho)-\alpha\mathcal{T}(\varrho,\mu)$$ are invariant regarding the translation of the measure $\varrho$.  Without loss of generality, we can take  a  minimizing sequence $\varrho_{k}$ of (\ref{P}), such that, their  barycenters are at $o$. By Lemma \ref{LowerBoundOfFa}, each $\varrho_{k}$  satisfies that, for some fixed $\alpha_{1} \in (0, -\alpha n)$ and $\alpha_{2}\in (-\alpha n,1)$,  
    \begin{equation}\label{LowerBoundOfFAlongRk}
        \mathcal{F}_{\alpha}(\varrho_k)\geq C-\left(\int_{\mathbb{R}^n}|x| \,d \varrho_k(x)\right)^{\alpha_1} -\left(\int_{\mathbb{R}^n}|x| \,d \varrho_k(x)\right)^{\alpha_2}.
    \end{equation}
Due to Proposition \ref{[San16,Prop3.2]}, there exists a constant $\tau\geq 0$ such that $\mathcal{T}(\varrho,\mu)\geq \tau\int_{\Rn}\left |x\right|d\varrho(x)$ for any $\varrho\in \mathcal{P}_{1}(\mathbb{R}^{n})$ whose barycenter is at $o$.  Hence 
    \begin{align*}(1-\alpha )\left(C-\left( \int_{\Rn}\left |x\right|d\varrho_{k}(x)\right)^{\alpha_{1}}-\left( \int_{\Rn}\left |x\right|d\varrho_{k}(x)\right)^{\alpha_{2}} \right)-\alpha\tau\int_{\Rn}\left |x\right|d\varrho_{k}(x) \\ \leq (1-\alpha)\mathcal{F}_{\alpha}(\varrho_{k})-\alpha\mathcal{T}(\varrho_{k},\mu).\end{align*} Note that the sequence $(1-\alpha)\mathcal{F}_{\alpha}(\varrho_{k})-\alpha\mathcal{T}(\varrho_{k},\mu)$ is bounded from above (as $\varrho_k$ is a minimizing sequence to problem (\ref{P})). Hence we see that the sequence $$\int_{\Rn} |x|\,d\varrho_k(x)$$ must be bounded from above as well.  This gives the tightness of the sequence $\varrho_{k}$. Indeed, let $M := \sup_{k}\int_{\Rn} |x|\,d\varrho_{k}(x)<+\infty$. Then, for any  $\lambda >0$, we have
    $$\int_{\{|x|\geq \lambda\}}\,d\varrho_{k}(x)\leq \int_{\{|x|\geq \lambda\}} \frac{|x|}{\lambda}\,d\varrho_{k}(x) \leq  \frac{M}{\lambda}.$$
The tightness of the sequence $\varrho_{k}$ follows by letting $\lambda\to +\infty$. By Prokhorov's theorem (see \cite[Theorem 2.1.11]{FG21}), the sequence $\varrho_{k}$ admits a subsequence,   still denoted by $\varrho_k$ for convenience, that converges weakly to some $\varrho_{0}$, i.e.,
    $$\int_{\Rn}\phi \,d\varrho_{k}\to\int_{\Rn}\phi \,d\varrho_{0},$$  for any bounded continuous function $\phi$. 

We prove that $\varrho_{0}$ has finite first moment. By \eqref{LowerBoundOfFAlongRk} and the boundedness of $\int_{\mathbb{R}^n}|x| d \varrho_k(x)$, the sequence $\mathcal{F}_\alpha(\varrho_k)$ is bounded from below. Hence the sequence $\mathcal{T}(\varrho_k, \mu)$ is bounded from above. It follows from  Proposition \ref{[San16,Prop3.1]} that
\begin{equation}\mathcal{T}(\varrho_{0},\mu)\leq \liminf_{k\to\infty}\mathcal{T}(\varrho_{k},\mu)<\infty.\label{LSC-Of-T}\end{equation}
By Theorem \ref{[Vil08, Theorem 5.10]}, there exists a function $\varphi_{1}$ such that
$$\mathcal{T}(\varrho_{0},\mu)=\int_{\mathbb{R}^{n}}\varphi_{1}(x)\,d\varrho_{0}(x)+\int_{\mathbb{R}^{n}}\varphi_{1}^{*}(x)\,d\mu(x)<\infty.$$
Consequently, $\int_{\mathbb{R}^{n}}\varphi_{1}\,d\varrho_{0}<\infty$  and $\varphi_{1}$ is coercive, as otherwise $\varphi_{1}^{*}=\infty$ in a half space. Therefore, there exist positive numbers $R$ and $c_{1}$ such that $\varphi_{1}(x)\geq c_{1}|x|$ whenever $|x|>R$. Thus
\begin{align*}\int_{\mathbb{R}^{n}}|x|\,d\varrho_{0}(x) &= \int_{\{|x|\leq R\}}|x|\,d\varrho_{0}(x)+\int_{\{|x|>R\}}|x|\,d\varrho_{0}(x)\\&\leq \int_{\{|x|\leq R\}}|x|\,d\varrho_{0}(x)+\frac{1}{c_{1}}\int_{\{|x|> R\}}\varphi_{1}(x)\,d\varrho_{0}(x)<\infty.\end{align*}


By \eqref{LSC-Of-T}, to conclude the existence of a minimizer for problem (\ref{P}), it suffices to prove that
    \begin{equation}\label{LimInfOfF(RhoK)}
        \liminf _{k\to\infty}\mathcal{F}_{\alpha}(\varrho_{k})\geq \mathcal{F}_{\alpha}(\varrho_{0}).
    \end{equation}
Let $g(x):=\mathbf{1}_{\{|x|\leq 1\}} |x|^{ \alpha_1 } +\mathbf{1}_{\{ |x|> 1\}} |x|^{ \alpha_2}  $, and  $\beta:=-\alpha(1-\alpha)^{\frac{1}{\alpha}-1}>0$. Note that
    \begin{align}\label{SplitF}
        \mathcal{F}_\alpha(\varrho)&=\int_{\mathbb{R}^n}\left(-\rho(x)^{\frac{1}{1-\alpha}}+\beta g^{\frac{1}{\alpha}}(x) +g(x) \rho(x)\right) d x +\int_{\mathbb{R}^{n}}g(x)\,d\varrho^{s}(x)\nonumber
        \\ & \quad -\beta \int_{\mathbb{R}^n} g^{\frac{1}{\alpha}}(x)\,d x-\int_{\mathbb{R}^n} g(x)\,d\varrho(x).
    \end{align}  By \eqref{alpha1alpha2}, the term $\int_{\mathbb{R}^{\mathrm{n}}} g^{\frac{1}{\alpha}}(x)\,d x$ is finite and independent of $\varrho$. We now prove that 
\begin{align}
   \lim_{k\to \infty}\int_{\mathbb{R}^{n}}g(x)\,d\varrho_{k}(x) = \int_{\mathbb{R}^{n}}g(x)\,d\varrho_{0}(x). \label{limit-g-rho-k} 
\end{align} 
For any $M_1>1$, 
    \begin{align}\label{Continuity-Of-Int-g}&\left |\int_{\mathbb{R}^{n}}g(x) \,d\varrho_{k}(x) - \int_{\mathbb{R}^{n}}g(x)\,d\varrho_{0}(x)\right| \nonumber 
\\ & \leq \  \left |\int_{\mathbb{R}^{n}}\min\{g,M_1 \}\,d(\varrho_{k}-\varrho_0)\right|+\int_{\{|x|^{\alpha_{2}}>M_1 \}}|x|^{\alpha_{2}}\,d(\varrho_{k}+\varrho_0)\nonumber
\\ & \leq\  \left |\int_{\mathbb{R}^{n}}\min\{g,M_1 \}\,d(\varrho_{k}-\varrho_0)\right|+\int_{\{|x|^{\alpha_{2}}>M_1 \}}\frac{|x|}{M_1 ^{(1-\alpha_{2})/\alpha_{2}}}\,d(\varrho_{k}+\varrho_0)\nonumber
\\& \leq\  \left |\int_{\mathbb{R}^{n}}\min\{g,M_1\}\,d(\varrho_{k}-\varrho_0)\right|+\frac{1}{M_1^{(1-\alpha_{2})/\alpha_{2}}}\left( \int_{\mathbb{R}^{n}}|x| \,d\varrho_{k}(x)+\int_{\mathbb{R}^{n}}|x| \,d\varrho_0(x) \right)\end{align}
    Note that the sequence $\int_{\mathbb{R}^n}|x| \,d \varrho_k$ is bounded above by $M$. For each fixed $M_1>1$, after taking the upper limit as $k\rightarrow \infty$ in \eqref{Continuity-Of-Int-g},  we get $$
\limsup_{k\to\infty}\left|\int_{\mathbb{R}^n} g(x) \,d \varrho_k(x)-\int_{\mathbb{R}^n} g(x) \,d \varrho_0(x)\right| \leq \frac{1}{M_1^{(1-\alpha_{2})/\alpha_{2}}}\left( M+\int_{\mathbb{R}^{n}}|x|\,d\varrho_0(x) \right), 
$$  where  we have used the weak convergence of $\varrho_k$ to $\varrho_0.$ Now let $M_1 \to \infty$, we arrive at $$
\lim_{k\to\infty}\left|\int_{\mathbb{R}^n} g(x) \,d \varrho_k(x)-\int_{\mathbb{R}^n} g(x) \,d \varrho_0(x)\right| =0.
$$ That is, \eqref{limit-g-rho-k} holds. 


    Finally, we prove that 
$$
\mathcal{G}_{\alpha}(\varrho):=\int_{\mathbb{R}^n}\left(-\rho(x)^{\frac{1}{1-\alpha}}+\beta g^{\frac{1}{\alpha}}(x)+g(x) \rho(x)\right) d x +\int_{\mathbb{R}^{n}}g(x)\,d\varrho^{s}(x)
$$
is lower semi-continuous. For any compact set $K$, let
$$
\mathcal{G}_{\alpha,K}(\varrho):= \int_{K}\left(-\rho(x)^{\frac{1}{1-\alpha}}+\beta g^{\frac{1}{\alpha}}(x)+g(x) \rho(x)\right) d x +\int_{K}g(x)\,d\varrho^{s}(x).
$$
By \eqref{Young'sIneq}, the function $-\rho(x)^{\frac{1}{1-\alpha}}+\beta g^{\frac{1}{\alpha}}(x)+g(x) \rho(x)$ is nonnegative. By the monotone convergence theorem, we have
    $$
\mathcal{G}_{\alpha}(\varrho) = \sup_{K\subset \mathbb{R}^{n},K \text{ is compact}} \mathcal{G}_{\alpha,K}(\varrho).
$$
% Note that  $F(x,t):= -t^{\frac{1}{1-\alpha}}+\beta g^{\frac{1}{\alpha}}(x)+g(x)t$ is  continuous on $\Rn \times [0, \infty)$, and for a fixed $t_{0}>0$, 
% $$
% F_{\infty}(x,t):= \lim_{r\to \infty}\frac{F(x,t_{0}+rt)}{r}=g(x)t. $$
It follows from \cite[Remark 3 on Page 413]{BV88} that   $\mathcal{G}_{\alpha,K}$ is lower semi-continuous in $\mathcal{P}_{1}(\mathbb{R}^{n})$. Therefore, $\mathcal{G}_{\alpha}$ is also lower semi-continuous in $\mathcal{P}_{1}(\mathbb{R}^{n})$ and thus, 
\begin{align*}
        \liminf _{k\to\infty}\mathcal{G}_{\alpha}(\varrho_{k})\geq \mathcal{G}_{\alpha}(\varrho_{0}).
    \end{align*} Together with \eqref{SplitF} and \eqref{limit-g-rho-k},   \eqref{LimInfOfF(RhoK)} is proved. As the sequence $\varrho_k$ is the limiting sequence of problem (\ref{P}) and $\varrho_0\in \mathcal{P}_1(\R^n)$, $\varrho_0$ is a solution to   problem (\ref{P}).   \end{proof}



    Now we prove that the solutions to our Minkowski problems, if exist, must have essentially continuous base functions. The idea of the proof originates from \cite[Theorem 4.3]{San16}.


\begin{proposition}\label{EssentialContinuity}
    Let $-\frac{1}{n}<\alpha<0$ and $\mu\in\mathcal{P}_1(\Rn)$ be such that  the barycenter of $\mu$ is $o$ and $\mu$ is not supported in any hyperplane. Suppose that $$\varrho_0 =\rho_{0}\,dx+\varrho_{0}^{s}= (1-\alpha\varphi_0)^{\frac{1}{\alpha}-1}\,dx + \varrho_{0}^{s},$$ with $\varphi_{0}\geq \frac{1}{\alpha}$, is the solution to (\ref{P}). Then, $\varphi_{0}$ is essentially continuous. In particular, the spherical surface area measure of $\varrho_{0}$ is identically $0$.
\end{proposition}


\begin{proof}
    Let $\Omega=\dom\varphi_{0}$. To prove that $\varphi_{0}$ is essentially continuous, i.e., continuous $\mathcal{H}^{n-1}$-a.e. on $\partial \Omega$, it is sufficient to show that $\rho_{0}=0$ $\mathcal{H}^{n-1}$-a.e. on $\partial \Omega$. Indeed, let $x_{0}\in \partial \Omega$. By virtue of lower semi-continuity of $\varphi_{0}$, we have
    $$\limsup_{x\to x_{0}}\rho_{0}(x) \leq \rho_{0}(x_{0}).$$
If $\rho_{0}(x_{0}) = 0$, then obviously $$\liminf_{x\to x_{0}}\rho_{0}(x)\geq 0 = \rho_{0}(x_{0}).$$ Hence $\rho_{0}$ and $\varphi$ are continuous at $x_{0}$.

For any $t\in \R$, define the sublevel set of $\varphi_0$ by $$[\varphi_0 ]_t=\{x\in \Rn: \varphi_0 (x)\leq   t\}.$$ 
Suppose that, for any $t\in \R$, the interior of $[\varphi_0]_t$ is empty. As $\varphi_0$ is lower semi-continuous, $[\varphi_0]_t$ is closed and  $\Omega=\cup_{t\in \mathbb{Z}}  [\varphi_0]_t$. Thus, $\Omega$ must have an empty interior by Baire category theorem.  Because $\Omega$ is convex, it should be contained in some hyperplane. Hence $\{\rho > 0\}$ is contained in some hyperplane, i.e. $\rho(x)=0$ for $\mathcal{L}^{n}$-a.e. $x$, which is a contradiction to the fact that $\varrho_{0}\neq \varrho_{0}^{s}$.

Without loss of generality, we can then assume that there exists $t_0$ such that $[\varphi_0]_{t_0}$ has a nonempty interior. Hence, for any $t>t_0$,  $\{\varphi<t\} $  must have non-empty interiors as well. Moreover, $\{\varphi<t\}$ must be  a convex open  set. 

Assume the opposite to our claim, namely,  there exist a constant $a>0$ and a set $S\subset \partial \Omega$ of positive $\mathcal{H}^{n-1}$- measure, such that, $\rho_{0}\geq a>0$   on $S$. Shrinking  $S$, if necessary, and  using the convexity of $\Omega,$ we see that, locally around some point $x_0\in S,$ the set $S$ can be  represented as the graph of a convex function. Without loss of generality, we can assume $x_0=o$ and  
 $$S = \{(x',h(x')):x'\in U\}, $$ for a convex function $h:\R^{n-1}\rightarrow [0,\infty)$, where $U$ is a neighborhood of $o\in \R^{n-1}$ and   $h(o)=0$.  
 Let $S_{\varepsilon}:=\{(x',h(x')+\delta):x'\in U,0< \delta\leq\varepsilon\}$. Shrinking $U$ if necessary, we can assume $S_{\varepsilon_{0}}\subset \text{int }\Omega$ for some small $\varepsilon_{0}$. There is   $S'\subset S+\varepsilon_{0}e_{n}$, which takes  the form $$S'=\{(x',h(x')+\varepsilon_{0}):x'\in V\}$$ with $V$  a relative open subset of $U$ such that $\overline{V}\subset U$. Hence,  $\varphi_0$ is bounded from above on $S'$.  Because $\{\varphi_{0}<t\}$ is open for $t$ large and $\varphi_{0}$ is finite on $S$, there exists $t'$ such that $\{\varphi_0 <t'\}\cap (S+\varepsilon_{0}e_{n})$ is a relative open subset of $S+\varepsilon_{0}e_{n}$. 

 By shrinking $S$ again, if necessary, we may assume that $U=V$ and $$S'=S+\varepsilon_{0}e_{n}\subset \{\varphi_{0}<t'\}.$$ Then, $\varphi_0$ is bounded from above on $S+\varepsilon_{0}e_{n}$. Due to the convexity of $\varphi_{0}$, the boundedness of $\varphi_{0}$ on $S$ and $S+\varepsilon_{0}e_{n}$ yield the boundedness of $\varphi_{0}$ on $S_{\varepsilon_{0}}$. Thus, there exists a constant $c_{0}>0$ such that  $\rho_{0} \geq c_{0}$ on $S_{\varepsilon}$ for any $0<\varepsilon<\varepsilon_{0}$.
  Therefore,
    \begin{equation} \int_{S_{\varepsilon}}\rho_{0}^{\frac{1}{1-\alpha}}\,dx\geq c_{0}^{\frac{1}{1-\alpha}} \int_{S_{\varepsilon}}\,dx = c_{0}^{\frac{1}{1-\alpha}} \int_{U}\int_{h(x')}^{h(x')+\varepsilon}\,dx_{n}\,dx' = c_{0}^{\frac{1}{1-\alpha}} \mathcal{L}^{n-1}(U)\varepsilon:=c_{1}\varepsilon.\label{LocalBoundOfRho}\end{equation} To find a contradiction, let $T^{\varepsilon}(x):=(x',x_{n}-\varepsilon)$ for $x=(x', x_n)$ and 
    $$
    \varrho_{\varepsilon}:= \varrho_{0}\mres{S_{\varepsilon}^{c}} + \frac{1}{2}\Big(\rho_{0}\,dx\mres{S_{\varepsilon}}\Big)+\frac{1}{2}\Big(T^{\varepsilon}_{\sharp}(\rho_{0}\,dx\mres{S_{\varepsilon}})\Big) +\varrho^s_{0}\mres{S_{\varepsilon}},
    $$ where $ S_{\varepsilon}^{c} =\Rn\setminus  S_{\varepsilon}$. Note that the measure $T^{\varepsilon}_{\sharp}(\rho_{0}\,dx\mres{S_{\varepsilon}})$ has its density function again equal to $\rho_0\big((T^{\varepsilon})^{-1}(\cdot)\big)$ on the set $T^{\varepsilon}(S_{\varepsilon})$, where $(T^{\varepsilon})^{-1}$ denotes the preimage of the map $T^{\varepsilon}$. Therefore, put $c'= \big( 2^{\frac{-\alpha}{1-\alpha}}-1\big),$ we have\begin{align*}\mathcal{F_{\alpha}}(\varrho_{\varepsilon})&= -\int_{S_{\varepsilon}^{c}}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\! \int_{S_{\varepsilon}}\! 2^{-\frac{1}{1-\alpha}}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\! \int_{T^{\varepsilon}(S_{\varepsilon})} \!\!  2^{-\frac{1}{1-\alpha}}\rho_0\big((T^{\varepsilon})^{-1}(x)\big)^{\frac{1}{1-\alpha}}\,dx\\
    &=-\int_{S_{\varepsilon}^{c}}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\int_{S_{\varepsilon}}2^{\frac{-\alpha}{1-\alpha}}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx\\
    &=-\int_{\Omega}\rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx-\big( 2^{\frac{-\alpha}{1-\alpha}}-1\big) \int_{S_{\varepsilon}} \rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx \\ 
    &=\mathcal{F_{\alpha}}(\varrho_{0})-c'\int_{S_{\varepsilon}} \rho_{0}^{\frac{1}{1-\alpha}}(x)\,dx \numberthis\label{EstimateF}.\end{align*}

     Next, we find an upper bound for $\mathcal{T}\left(\varrho_{\varepsilon}, \mu\right)$. Let $\psi$ be a fixed convex, positive function, such that $\int_{\Rn}\psi\,d\mu<\infty$ and $\psi^{*}$ is finite on $\Rn$. Such a function $\psi$ exists due to the fact that $\mu\in \mathcal{P}_{1}(\mathbb{R}^{n})$. Let $\delta>0$ be a positive number, and  $\varphi_{ \delta}:=(\varphi_{ 0}^{*}+\delta\psi)^{*}$. For $x\in S_{\varepsilon}$, it follows from \eqref{legendre-tran} that 
    \begin{align*}\varphi_{ \delta}\big(T^{\varepsilon}(x)\big) &=\sup_{z\in\Rn} \Big\{\langle z, T^{\varepsilon}(x)\rangle -\varphi_{ \delta}^*(z)\Big\} \\&=\sup_{z\in\Rn} \Big\{\langle z, x-\varepsilon e_n \rangle -\varphi_{ 0}^*(z)-\delta \psi(z)\Big\}\\&\leq \sup_{z\in\Rn} \Big\{\langle z, x \rangle -\varphi_{ 0}^*(z) \Big\} +\delta  \sup_{z\in\Rn} \Big\{\Big\langle z,  \frac{-\varepsilon e_n}{\delta} \Big\rangle  -\psi(z)\Big\}  \\
    &= \varphi_{ 0}(x)+\delta\psi^{*}\Big( \frac{-\varepsilon e_{n}}{\delta}\Big),\end{align*}
    where $\{e_{i}\}_{1\leq i\leq n}$ is the standard basis of $\mathbb{R}^{n}$. As the Legendre transform is order reversing, we have
     $\varphi_{ \delta}\leq \varphi_{ 0}$ in  $\Rn.$ This further implies  
    \begin{align*}\mathcal{T}(\varrho_{\varepsilon},\mu)&\leq \int_{\Rn}\varphi_{ \delta}\,d\varrho_{\varepsilon}+\int_{\Rn}(\varphi_{ 0} ^{*}+\delta\psi)\,d\mu\\
    &\leq\int_{S_{\varepsilon}^{c}}\!\varphi_{ 0} \,d\varrho_{0}+\frac{1}{2}\! \int_{S_{\varepsilon}}\!\varphi_{ 0} \rho_0\,dx +\frac{1}{2}\!\int_{T^{\varepsilon}(S_{\varepsilon})}\varphi_{ \delta} \rho_0\big((T^{\varepsilon})^{-1}(x)\big) \,dx \\ &\ \  +\int_{S_{\varepsilon}}\!\,d\varrho^s_{0}+  \int_{\Rn}\!\varphi^{*}_{0} \,d\mu+\delta\int_{\Rn}\! \psi \,d\mu\\
    &=\!\int_{\Rn}\! \varphi_{ 0} \,d\varrho_{0}\!+\!\int_{\Rn}\!\varphi_{ 0} ^{*}\,d\mu \!-\! \frac{1}{2}\!\int_{S^{\varepsilon}}\! \varphi_0 \,d\rho_{0}\!+\!\frac{1}{2}\!\int_{S_{\varepsilon}}\!\Big(\!\varphi_{\delta}\circ T^{\varepsilon}\!\Big)(x)\rho_{0}(x)\,dx \!+\!\delta\!\int_{\Rn}\! \psi \,d\mu\\
    &= \mathcal{T}(\rho_{0},\mu) +\delta\!\int_{\Rn}\! \psi \,d\mu - \frac{1}{2}\!\int_{S^{\varepsilon}}\! \varphi_0 \,d\rho_{0}+\frac{1}{2}\!\int_{S_{\varepsilon}}\!\Big(\!\varphi_{\delta}\circ T^{\varepsilon}\!\Big)(x)\rho_{0}(x)\,dx \\
    &\leq \mathcal{T}(\rho_{0},\mu)+\delta\int_{\Rn}\psi \,d\mu+\frac{\delta}{2} \psi^{*}\left( \frac{-\varepsilon e_{n}}{\delta}\right)\int_{S_{\varepsilon}}\rho_{0}(x)\,dx .\numberthis\label{EstimateT} 
    \end{align*} Combining (\ref{LocalBoundOfRho}), (\ref{EstimateF}), and (\ref{EstimateT})   with  the fact that $\varrho_{0}$ solves \eqref{P},   we get
    \begin{align*}
         (1\!-\!\alpha)\mathcal{F}_{\alpha}(\varrho_{0})\!-\! \alpha\mathcal{T}(\varrho_{0},\mu) 
        &\leq  (1\!-\!\alpha)\mathcal{F}_{\alpha}(\varrho_{\varepsilon})\!-\! \alpha\mathcal{T}(\varrho_{\varepsilon},\mu)\\
        & \leq\  (1\!-\!\alpha)\mathcal{F}_{\alpha}(\varrho_{0})-c' (1-\alpha)\int_{S_{\varepsilon}} \rho_0^{\frac{1}{1-\alpha}}(x) d x\\&\ \ -\alpha\bigg(\!\mathcal{T}(\rho_{0},\mu)\!+\!\delta\!\int_{\Rn}\! \psi \,d\mu \!+\! \frac{\delta}{2} \psi^{*}\Big(\! \frac{-\varepsilon e_{n}}{\delta}\!\Big)\!\int_{S_{\varepsilon}}\! \rho_{0}(x)\,dx\bigg)\\
        &  \leq\  (1-\alpha)\mathcal{F}_{\alpha}(\varrho_{0})-c'c_{1} (1-\alpha)\varepsilon\\&\ \ -\alpha\bigg(\!\mathcal{T}(\rho_{0},\mu)\!+\!\delta\!\int_{\Rn}\! \psi \,d\mu \!+\! \frac{\delta}{2} \psi^{*}\Big(\! \frac{-\varepsilon e_{n}}{\delta}\!\Big)\!\int_{S_{\varepsilon}}\! \rho_{0}(x)\,dx\bigg). 
    \end{align*}
    This estimate entails
    \begin{align}c'c_{1}  (1-\alpha)&\leq -\frac{\alpha\delta}{\varepsilon}\int_{\Rn}\psi \,d\mu-\frac{\alpha \delta}{2\varepsilon} \psi^{*}\Big( \frac{-\varepsilon e_{n}}{\delta}\Big)\int_{S_{\varepsilon}}\rho_{0}(x)\,dx \nonumber \\ &=- \alpha\beta \int_{\Rn}\psi \,d\mu-\frac{\alpha \beta}{2 } \psi^{*}\Big( \frac{- e_{n}}{\beta}\Big)\int_{S_{\varepsilon}}\rho_{0}(x)\,dx  \label{LastEstimate},\end{align} where $\delta$ is chosen to be $\delta=\beta\varepsilon$ for some positive constant $\beta$ so that  $$-\alpha \beta \int_{\Rn}\psi \,d\mu< c'c_1 (1-\alpha).$$  Let $\varepsilon\to 0$ in \eqref{LastEstimate}, then by monotone convergence theorem, 
    $$\int_{S_\varepsilon} \rho_0 (x) d x\to 0,$$
and we arrives at a contradiction. Thus, $\varphi_{0}$ is essentially continuous.
\end{proof}
 Our main result in this section is summarized in the following theorem. 
\begin{theorem}\label{sol-measure-measure}
Let $-\frac{1}{n}<\alpha<0$ and $\mu\in \mathcal{P}_{1}(\mathbb{R}^{n})$. Assume that  the barycenter of $\mu$ is $o$ and $\mu$ is not supported in any hyperplane. Then, there exists an $\alpha$-concave measure $$\bar\varrho = (1-\alpha\varphi_{0})^{\frac{1}{\alpha}}\,dx + \varrho^{s}_{0},$$ such that $\mu$ is the Euclidean surface area measure of $\bar{\varrho}$ and the spherical surface area measure of $\bar\varrho$ is the zero measure.
\end{theorem}

    \begin{proof} By Propositions \ref{PropertyOfMinimizer} and   \ref{Existence}, there exists a solution $$\varrho_{0} = \big(1-\alpha\varphi_{0}\big)^{\frac{1}{\alpha}-1}+\varrho_{0}^{s}$$ to the minimization problem \eqref{P} such that, $\varphi_{0}\geq \frac{1}{\alpha}$,   $\mathrm{Supp}(\varrho_{0}^{s})\subset \left\{\varphi_{0}=\frac{1}{\alpha}\right\}$, and 
        $$\mathcal{T}(\varrho_{0},\mu)=\int_{\mathbb{R}^{n}}\varphi_{0}\, \,d\varrho_{0}+\int_{\mathbb{R}^{n}}\varphi_{0}^*\, \,d\mu.$$
Due to Theorem \ref{[Vil08, Theorem 5.10]}, there exists a measure $\pi$ on $\mathbb{R}^{n}\times \mathbb{R}^{n}$, whose marginals are $\varrho_{0}$ and $\mu$, respectively, such that 
$$\mathrm{Supp}(\pi)\subset \mathrm{Graph}(\partial \varphi). $$
Therefore, $\mu$ is the Euclidean surface area measure of $\bar{\varrho}$. On the other hand, Proposition \ref{EssentialContinuity} asserts that the spherical surface area measure of $\bar\varrho$ vanishes. This completes the proof.
\end{proof}


Note that, if $\inf\varphi>\frac{1}{\alpha},$ Theorem \ref{sol-measure-measure} provides a solution to Problem \ref{problem-E-FMP}. However, it is not clear when the solution $\varphi$ given in Theorem \ref{sol-measure-measure} does  satisfy $\inf \varphi >\frac{1}{\alpha}$, and we leave this investigation for future studies. 


