\subsection{(1+1+2)-covariant equations for LRS space-times in signature (+\ -\ -\ -)} \label{Subsection2.2}
The $(1+1+2)$-splitting relies on the introduction of an additional space-like vector field $n^{i}$, orthogonal to $u^i$, with $n^iu_i=0$ and $n^{i}n_{i}=-1$. At every point $x$ of space-time $M$, the $3$-space contained in $T_xM\/$ and orthogonal to $u^i$ is further decomposed into the direct sum of a $1$-dimensional subspace parallel to $n_{i}$ and a $2$-dimensional subspace orthogonal to both $u^i$ and $n^i$. As a consequence, the  metric tensor can be expressed as
\bea\label{mertric_1_1_2}
 g_{ij}=u_{i}u_{j}-n_{i}n_{j}+N_{ij} \ \ \ \ {\rm with} \ \ \ \ h_{ij}=-n_{i}n_{j}+N_{ij}
\eea
where $N_{ij}$ denotes the restriction of the metric tensor to the $2$-space orthogonal to $u^i$ and $n^i$. The tensor
\bea\label{projection_1_1_2}
N^i\hspace{0.1mm}_{j} =g^i\hspace{0.1mm}_{j} - u^{i}u_{j} + n^{i}n_{j}, \ \ \ {\rm with}  \ \ \ N^i\hspace{0.1mm}_{j}u^j=N^i\hspace{0.1mm}_{j}n^j =0,  \ \ \ N^i\hspace{0.1mm}_{j} N^j\hspace{0.1mm}_{h}=N^i\hspace{0.1mm}_{h}  \ \ \ {\rm and}  \ \ \ N^i\hspace{0.1mm}_{i}=2
\eea
plays the role of projection operator into the $2$-space orthogonal to $u^i$ and $n^i$. Therefore, every $3$-vector $V^{i}$ ($V^iu_i=0$) can be decomposed as
\bea\label{vector_decomposition_1_1_2} 
V^{i}=-Vn^{i}+\mathcal{V}^{i}
\eea
where $V=V^{i}n_{i}$ and $\mathcal{V}^{i}=N^{i}\hspace{0.1mm}_{j}V^{j}$. In an analogous way, every PSFT $3$-tensor $W_{ab}=W_{\langle ab\rangle}$ can be expressed as
\bea\label{tensor_decomposition_1_1_2} 
W_{ab}=W\left(n_{a}n_{b} + \frac{1}{2}N_{ab}\right) - 2\mathcal{W}_{(a}n_{b)} + \mathcal{W}_{ab} 
\eea
where $W=W^{ab}n_{a}n_{b}=W^{ab}N_{ab}$, $\mathcal{W}_{a}=N_{a}\hspace{0.1mm}^{b}n^{c}W_{bc}$ and $\mathcal{W}_{ab}=\left(N_{(a}\hspace{0.1mm}^{c}N_{b)}\hspace{0.1mm}^{d}-\frac{1}{2}N_{ab} N^{cd}\right)W_{cd}$. We also introduce the alternating tensor
\bea\label{2_alternating}
\varepsilon_{ab}:=\varepsilon_{jab}n^j=\varepsilon_{ijab}u^in^j \ \ \ \ {\rm with} \ \ \ \ \varepsilon_{ab}\varepsilon^{cd}= 
N_{a}\hspace{0.1mm}^{c}N_{b}\hspace{0.1mm}^{d} - N_{a}\hspace{0.1mm}^{d}N_{b}\hspace{0.1mm}^{c}
\eea
After that, making use of the fully orthogonally projected covariant derivative \eqref{space_cov_der}, we define two new derivatives given by
\bea\label{hat_derivative}
\hat{A}^a\hspace{0.1mm}_{...b}:=n^c\bar{\nabla}_c\/A^a\hspace{0.1mm}_{...b}
\eea
and
\bea\label{delta_derivative}
\delta_c\/A^a\hspace{0.1mm}_{...b}:= N_c\hspace{0.1mm}^{d}N^a\hspace{0.1mm}_{e}...N^f\hspace{0.1mm}_{b}\bar{\nabla}_d\/A^e\hspace{0.1mm}_{...f}
\eea
holding for every tensor $A^a\hspace{0.1mm}_{...b}$. The covariant derivatives of the $1$-forms $u_{a}$ and $s_{a}$ are expressed respectively as
\begin{subequations}\label{cdun0}
\begin{align}\label{cdu0}
\non \nabla_a\/u_b=& -u_a\left(A n_b-\mathcal{A}_b\right)+n_a n_b\left(\Sigma-\frac{1}{3} \Theta\right)  - n_{a}\left(\Sigma_{b}-\varepsilon_{b c}\Omega^c\right)-n_{b}\left(\Sigma_{a}+\varepsilon_{ac}\Omega^c\right) + \\
 & +  N_{a b}\left(\frac{1}{3} \Theta+\frac{1}{2} \Sigma\right)+\Omega \varepsilon_{ab}+\Sigma_{ab}
\end{align}
\be\label{cdn0}
\nabla_a\/n_b=  -Au_a\/u_b + u_a\alpha_b+\left(\Sigma-\frac{1}{3} \Theta\right)\/n_a u_b  -\left(\Sigma_a+\varepsilon_{ac} \Omega^c\right) u_b-n_a\/a_b+\frac{1}{2}\phi\/N_{ab}  +\xi\varepsilon_{ab}+\zeta_{ab}
\ee
\end{subequations}
where the scalar, vector, and tensor components appearing in eqs. \eqref{cdun0} are given by
\begin{subequations}\label{kinematical_quantities} 
\be
A:=\dot{u}_{i}n^i, \quad \Sigma:=\sigma_{ab}n^{a}n^{b}, \quad  \Omega:=\omega_{i}n^{i}, \quad \phi:=N^{ab}\delta_{a}n_{b}, \quad \xi:=\frac{1}{2}\varepsilon^{ab}\delta_{a}n_{b} 
\ee
\be
\mathcal{A}^a:=N^a{}_b\dot{u}^b, \quad  \alpha^a:= N^{a}{}_{b}{\dot{n}}^{b}, \quad a^c:=N^{a}{}_{b}\hat{n}^b, \quad \Sigma^a:=N^{ab}\sigma_{bc}n^c, \quad  \Omega^a:=N^a{}_b\omega^b
\ee
\be
\Sigma_{ab}:=\left(N_{(a}{}^{c}N_{b)}{}^{d}\!-\!\frac{1}{2}N_{ab}N^{cd}\right)\sigma_{cd},\quad \zeta_{ab}:=\left(N_{(a}{}^{c}N_{b)}{}^{d}\!-\!\frac{1}{2}N_{ab}N^{cd}\right)\delta_c\/n_d
\ee
\end{subequations}
In Locally Rotationally Symmetric (LRS) geometries, at each point of space-time the unit vector $n^i$ indicates a preferred spatial direction, coinciding with a local axis of symmetry. All observations are identical under rotations about $n^i$, that is, observations are the same in all spatial directions perpendicular to $n^i$. In particular, this implies that all tensors having physical meaning must have null projections into the $2$-space orthogonal to both $u^i$ and $n^i$. As a consequence, in a LRS space-time, the covariant derivatives of $u_{i}$ and $n_{i}$ reduce to
\bea \label{cdubis} 
&& \nabla_{i}u_{j}=\Sigma\left(n_{i}n_{j}+\frac{1}{2}N_{ij}\right)+\frac{1}{3}\Theta\left(N_{ij}-n_{i}n_{j}\right)-Au_{i}n_{j}+\Omega\varepsilon_{ij} \\
\label{cdn} && \nabla_{i}n_{j}=\frac{1}{2}\phi N_{ij}+\xi\varepsilon_{ij}-Au_{i}u_{j}+\left(\Sigma-\frac{1}{3}\Theta \right)n_{i}u_{j} 
\eea
Moreover, denoting by
\bea\label{E_H}
&& E:=E_{ab}n^{a}n^{b} \ \ \ \ {\rm and} \ \ \ \ H:=H_{ab}n^{a}n^{b} 
\eea 
the following identities necessarily hold
\begin{subequations}\label{decompositions}
\begin{align}
\dot{u}^{a}&=-An^{a}\\
\omega^{a}&=-\Omega n^{a}\\
\sigma_{ab}&=\Sigma\left(n_{i}n_{j}+\frac{1}{2}N_{ij}\right)\\
E_{ab}&=E\left(n_{i}n_{j}+\frac{1}{2}N_{ij}\right)\\
H_{ab}&=H\left(n_{i}n_{j}+\frac{1}{2}N_{ij}\right)
\end{align}
\end{subequations}
Similarly, denoting by
\bea\label{Q_PI}
Q:=q^in_i \ \ \ \ {\rm and} \ \ \ \ \Pi:=\Pi_{ij}n^in^j
\eea
we have the following representations
\bea\label{Q_PI_bis}
q_i=-Qn_i \ \ \ \ {\rm and} \ \ \ \ \Pi_{ij}=\Pi\left(n_{i}n_{j}+\frac{1}{2}N_{ij}\right)
\eea
for the momentum density vector and the anisotropic pressure tensor, respectively. In the variables above, the energy conditions take the form 
\bea\label{energy_conditions_bis} 
\mu\geq 0 \ , \ \ \ \ \ \mu+p+\Pi\geq 0 \ , \ \ \ \ \ \  \mu+3p\geq 0 
\eea 
Summing it all up, the variables that covariantly describe LRS space-times are the scalar quantities
\bea\label{scalar_quantities}
\{A,\Theta,\Sigma,\Omega,\phi,\xi,E,H,\mu,p,Q,\Pi\}
\eea
For these variables, corresponding equations are then needed. Such equations, usually distinguished in evolution, propagation, evolution--propagation and constraint equations, are partly derived by the $(1+3)$-equations obtained in Subsection 2.1, and partly by working out the Ricci identities for the vector field $n^i$.
\\
\\
{\it Evolution equations}:
\begin{itemize}
\item By saturating eq. \eqref{dotvortic} with $n_a$, we get
\bea\label{dotomega} 
\dot{\Omega} = -A\xi-\frac{2}{3}\Theta\Omega-\Omega\Sigma
\eea
\item By saturating eq. \eqref{doth13} with $n_in_j$, we obtain
\bea\label{dot_H} 
\dot{H} = 3E\xi+\frac{3}{2}\Pi\xi-\Theta H -\frac{3}{2}H\Sigma -\Omega Q 
\eea
\item From the identity $\left[\left(\nabla_{c}\nabla_{d}-\nabla_{d}\nabla_{c}\right)n_a - R_{abcd}n^b\right]u^cN^{ad}=0$, we have
\bea\label{dot_phi}
\dot{\phi} = - \left(\Sigma+\frac{2}{3}\Theta\right)\left(A+\frac{1}{2}\phi\right) + 2\Omega\xi - Q 
\eea
\item From the identity $\left[\left(\nabla_{c}\nabla_{d}-\nabla_{d}\nabla_{c}\right)n_a - R_{abcd}n^b\right]u^{c}\varepsilon^{ad}=0$, we deduce
\bea\label{dot_xi}
\dot{\xi} = -\left(\frac{1}{2}\Sigma+\frac{1}{3}\Theta\right)\xi - \Omega\left(\frac{1}{2}\phi+A\right) + \frac{1}{2}H 
\eea
\end{itemize}

\noindent
{\it Propagation equations}:
\begin{itemize}
\item eq. \eqref{vortdiver} amounts to
\bea\label{hat_Omega}
\hat{\Omega} = - \Omega\left(A+\phi\right)
\eea
\item The identity $\left[\left(\nabla_{c}\nabla_{d}-\nabla_{d}\nabla_{c}\right)n_a - R_{abcd}n^b\right]n^{c}N^{ad}=0$ yields directly
\bea\label{hat_phi} 
\hat{\phi} = -\frac{1}{2}\phi^{2} + 2\xi^{2} - \left(\Sigma-\frac{1}{3}\Theta\right)\left(\Sigma+\frac{2}{3}\Theta\right) - \frac{2}{3}\mu -\frac{1}{2}\Pi + E 
\eea
\item The identity $\left[\left(\nabla_{c}\nabla_{d}-\nabla_{d}\nabla_{c}\right)n_a - R_{abcd}n^b\right]n^{c}\varepsilon^{ad}=0$ gives rise to 
\bea\label{hatxi} 
\hat{\xi} = - \left(\Sigma-\frac{1}{3}\Theta\right)\Omega - \phi\xi 
\eea
\item By saturating eq. \eqref{130alpha} with $n^d$, we get 
\bea\label{hat_Theta_Sigma} 
\frac{2}{3}\hat{\Theta} + \hat{\Sigma}= -\frac{3}{2}\Sigma\phi + 2\Omega\xi - Q
\eea
\item By saturating \eqref{econstr13} with $n^i$, we have
\bea\label{hat_E} 
\hat{E}-\frac{1}{2}\hat{\Pi}+\frac{1}{3}\hat{\mu} = - \frac{3}{2}\phi\left(E-\frac{1}{2}\Pi\right) - 3\Omega H - Q\left(\frac{1}{3}\Theta+\frac{1}{2}\Sigma\right)
\eea
\item By saturating \eqref{hconstr13} with $n_i$, we obtain
\bea\label{hat_H} 
\hat{H} = - \frac{3}{2}\phi H - \Omega\left(-3E+\mu+p-\frac{1}{2}\Pi\right) + Q\xi
\eea
\end{itemize}

\noindent
{\it Evolution--Propagation equations}:
\begin{itemize}
\item By working out the Raychaudhuri equation \eqref{Raychaudhuri1+3}, we get
\bea\label{Raychaudhuri1+1+2}  
\dot{\Theta} + \hat{A} = - A\phi + A^{2} - \frac{1}{3}\Theta^{2} - \frac{3}{2}\Sigma^{2} + 2\Omega^{2} - \frac{1}{2}\left(\mu+3p\right) 
\eea
\item From eq. \eqref{eneconserv}, we obtain
\bea\label{dot_mu} 
\dot{\mu} - \hat{Q}= - \left(\mu + p\right)\Theta + Q\phi - 2AQ +\frac{3}{2}\Sigma\Pi 
\eea 
\item By saturating eq. \eqref{momconserv} with $n_a$, we have 
\bea\label{dot_Q} 
\dot{Q}-\hat{\Pi} -\hat{p} = + \frac{3}{2}\Pi\phi - A\left(\mu + p + \Pi\right) - \frac{4}{3}Q\Theta + Q\Sigma
\eea
\item By saturating eq. \eqref{shearprop} with $n^an^d$, we get
\bea\label{dot_Sigma} 
\dot{\Sigma}-\frac{2}{3}\hat{A} = - \frac{1}{3}A\phi + \frac{1}{2}\Sigma^{2} + \frac{2}{3}\Omega^{2} - \frac{2}{3}A^{2} - \frac{2}{3}\Theta\Sigma - E - \frac{1}{2}\Pi 
\eea
\item By saturating eq. \eqref{dote13} with $n_in_j$, we deduce 
\bea\label{dot_E} 
\dot{E} - \frac{1}{2}\dot{\Pi} + \frac{1}{3}\hat{Q} = -E\Theta - \frac{3}{2}E\Sigma - 3H\xi + \frac{2}{3}AQ + \frac{1}{6}Q\phi - \frac{1}{2}\left(\mu+p\right)\Sigma + \frac{1}{6}\Theta\Pi - \frac{1}{4}\Pi\Sigma 
\eea
\item The identity $\left[\left(\nabla_{c}\nabla_{d}-\nabla_{d}\nabla_{c}\right)n_a - R_{abcd}n^b\right]u^{c}n^{d}u^{a}=0$ provides
\bea\label{equazione_indipendente} 
\hat{A} - \dot{\Sigma} + \frac{1}{3}\dot{\Theta} = - \left(\Sigma-\frac{1}{3}\Theta\right)^{2} + A^{2} - \frac{1}{6}\left(\mu+3p\right) + \frac{1}{2}\Pi + E 
\eea
Eq. \eqref{equazione_indipendente} is dependent on the previous ones. Indeed, it is given by the linear combination $\frac{1}{3}\eqref{Raychaudhuri1+1+2} - \eqref{dot_Sigma}$. 
\end{itemize}

\noindent
{\it Constraint equation}:
\begin{itemize}
\item Saturating eq. \eqref{hequation} with $n_cn_a$, we get
\bea\label{constraint_H} 
H=2A\Omega+\Omega\phi-3\xi\Sigma
\eea
which expresses the magnetic part of the Weyl tensor in terms of other kinematical variables.
\end{itemize}
