\subsection{Hitting Time and Hitting Probability} 
Given the Markov chain $(X^{[t]})_{t \ge 0}$  and a fitness level partition $(S_0, \cdots, S_K)$, we introduce the concepts of hitting time and hitting probability of reaching $S_\ell$ (where $0\le\ell\le K$) based on the textbook \cite{norris1998markov}. 

\begin{definition} Assume that the Markov chain $(X^{[t]})_{t \ge 0}$ starts from $X_k \in S_k$, the first \emph{hitting time} from $X_k$ to $S_\ell$ is %the minimum number of generations for the chain to reach $H$:
\[
    \tau(X_k,S_\ell)=\inf \{ t\ge 0,  X^{[t]} \in S_\ell \}.\]
    The \emph{mean hitting time} $m(X_k,S_\ell)$  denotes the expected value  of $\tau(X_k,S_\ell)$. The \emph{hitting probability} from $X_k$ to $S_\ell$ is 
\[
h(X_k,S_\ell)= \Pr(  \tau(X_k,S_\ell) <\infty).
\]
The \emph{hitting probability} from $X_k$ to $Y_\ell \in S_\ell$ is  
\[
h(X_k,Y_\ell)= \Pr(  X^{[\tau(X_k,S_\ell)]} =Y_\ell, \tau(X,S_\ell)<+\infty).
\]
\end{definition}

The following proposition adapts \cite[Theorem 1.3.2]{norris1998markov} for the hitting probability $h(X_k,S_\ell)$. This hitting probability from $X_k$ to $S_\ell$ is composed of two parts: (i) the probability of transitioning from $X_k$ to an intermediate state $Y_i$ and (ii) the hitting probability from the intermediate state $Y_i$ to $S_\ell$. 

\begin{proposition}
\label{pro:HittingProbability} For any $0 \le \ell \le k \le K$,
the hitting probability $h(X_k,S_\ell)$ satisfies
\begin{align*} 
 \left\{   
 \begin{array}{ll}
  h(X_k,S_k) =1.   \\
 h(X_k,S_\ell)=\sum^{k}_{i=\ell}\sum_{Y_i \in S_i} p(X_k,Y_i) h(Y_i,S_\ell).
 \end{array}\right.
\end{align*}
\end{proposition}


The following proposition modifies \cite[Theorem 1.3.5]{norris1998markov} for the mean hitting time $m(X_k,\overline{S}_k)$.   This mean time from $X_k$ to leaving $S_k$ is composed of two parts: (i) the probability of transitioning from $X_k$ to any intermediate state $Y_k$ within $S_k$, and (ii) the mean hitting time from the intermediate state $Y_k$ to leaving $S_k$, plus 1 for the initial step. 
\begin{proposition}
\label{pro:HittingTime} For any $0 < k \le K$,
the mean hitting time $m(X_k,\overline{S}_k)$ satisfies
\begin{equation*} 
         m(X_k,\overline{S_k}) 
         = 1+ \sum_{Y_k \in S_k} p(X_k,Y_k) m(Y_k,\overline{S_{k}}).   
\end{equation*}  
\end{proposition}  
 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Lower and Upper Bounds on Hitting Time}
Assuming that the Markov chain $(X^{[t]})_{t \ge 0}$ starts from $X$, the mean hitting time $m(X, S_0)$ from $X$ to the optimal set $S_0$ is always abbreviated as $m(X)$.
If $d(X) \le m(X)$, then $d(X)$ is called a lower bound of $m(X)$. Conversely, if $d(X) \ge m(X)$, then $d(X)$ is called an upper bound of $m(X)$.

Asymptotic notations such as $O$, $\Omega$, and $o$ are used to differentiate between tight and loose bounds, as described in the textbook \cite{cormen2022introduction}. Let $n$ represent the dimension of the search space. The mean hitting time $m(X)$ is a function of $n$. A tight bound $d(X)$ differs from the actual mean hitting time $m(X)$ by only a constant factor, meaning $d(X) = O(m(X))$ for an upper bound and $d(X) = \Omega(m(X))$ for a lower bound. 

 \subsection{Drift Analysis Using Linear Drift Functions}
\label{secDrift} 
The main results of drift analysis using linear drift functions \cite{he2023drift} are summarized in Proposition \ref{pro:LinearBound}. A drift function $d(X)$ is used to approximate the mean hitting time $m(X)$ to the optimal set. 

\begin{proposition}  
\label{pro:LinearBound}   Given a fitness level partition $(S_0, \ldots, S_K)$,

(1) Let a drift function $d(X)$ satisfy that for any $X_0 \in S_0$,  $d(X_0) = 0$ and for any $1\le k \le K$ and any $X_k \in S_k$, 
\begin{equation*}   
d(X_k)=\frac{1}{p_{{\scriptscriptstyle\max}}(X_{k},S_{[0,k-1]})} +\sum^{k-1}_{\ell=1} \frac{c_{k,\ell} }{ p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})},
\end{equation*} 
where coefficients $c_{k,\ell} \in [0,1]$ satisfy 
\begin{equation}
\label{equCoefficientLower}
    c_{k,\ell} \le \min_{X_k \in S_k} \left\{ r(X_k, S_\ell) + \sum^{k-1}_{j=\ell+1}  {r}(X_k, S_j) c_{j,\ell} \right\}.
\end{equation}
 Then for any $k\ge 1$ and $X_k \in S_k$, the drift
 \[
\Delta d(X_k)= \sum^{K}_{i=0} \sum_{Y_i \in S_i} p(X_k, Y_i)[d(X_k)- d(Y_i)] \le 1, 
 \]
 and %for any $k\ge 1$ and $X_k \in S_k$, 
 the mean hitting time
 $ 
m(X_k) \ge d(X_k).$ 

(2) Let a drift function $d(X)$ satisfy that for any $X_0 \in S_0$,  $d(X_0) = 0$ and for any $1\le k \le K$ and any $X_k \in S_k$, 
\begin{equation*} %\label{equ:Linear-lower-lound-ckl}   %\textstyle  
d(X_k)=\frac{1}{p_{{\scriptscriptstyle\min}}(X_{k},S_{[0,k-1]})} +\sum^{k-1}_{\ell=1} \frac{c_{k,\ell} }{ p_{{\scriptscriptstyle\min}}(X_{\ell},S_{[0,\ell-1]})},
\end{equation*} 
where coefficients $c_{k,\ell} \in [0,1]$ satisfy 
\begin{equation}
\label{equCoefficientUpper}
    c_{k,\ell} \ge \max_{X_k \in S_k} \left\{ r(X_k, S_\ell) + \sum^{k-1}_{j=\ell+1}  {r}(X_k, S_j) c_{j,\ell} \right\}.
\end{equation}
 Then for any $k\ge 1$ and $X_k \in S_k$, the drift
 \[
\Delta d(X_k)=\sum^{K}_{i=0} \sum_{Y_i \in S_i} p(X_k, Y_i)[d(X_k)- d(Y_i)] \ge 1, 
 \]
 and
 %for any $k\ge 1$ and $X_k \in S_k$, 
 the mean hitting time
 $ 
m(X_k) \ge d(X_k).$ 
\end{proposition} 

The drift analysis above reformulates the task of determining a drift function into the problem of identifying coefficients \( c_{k,\ell} \). In this paper, we interpret \( c_{k,\ell} \) as the hitting probability from \( X_k \) to \( S_\ell \) and introduce another drift analysis to estimate this hitting probability. 



\subsection{Previous Results in the Fitness Level Method}
The Type-$c$ linear bound is a special cases of the Type-$c_{k,\ell}$ bound by setting $c_{k,\ell}=c$ \cite{he2023drift}. 
Sudholt \cite{sudholt2012new} investigated Type-$c$ time bounds. For example, he gave the lower time bound as follows:
    \begin{align*} 
       &m(X^{[0]})  \ge  \sum^K_{k=1} \Pr(X^{[0]} \in S_k) \\
       &\left[\frac{1}{p_{{\scriptscriptstyle\max}}(X_{k},S_{[0,k-1]})} +\sum^{k-1}_{\ell= 1} \frac{c}{p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}\right].
    \end{align*} 
    where the coefficient $c$ is calculated as follows: 
    \begin{equation} 
\label{equLowerCoeff-c} 
c \le \min_{k:1 < k\le K} \min_{\ell:1\le \ell<k} \; \min_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
\end{equation}  
Sudholt \cite{sudholt2012new} used a different expression, but it is equivalent to \eqref{equLowerCoeff-c}.
He called $c$ the viscosity, which is a lower bound on the probability of visiting $S_\ell$ conditional on visiting $S_{[0,\ell]}$. 

The Type-$c_\ell$ linear bound is a special cases of the Type-$c_{k,\ell}$ bound by setting $c_{k,\ell}=c_\ell$ \cite{he2023drift}. Doerr and K\"otzing \cite{doerr2024lower} investigated Type-$c_\ell$ time bounds. For example,  they gave the lower time bound as follows:  
\begin{equation*} 
    m(X^{[0]})  \ge   
 \sum^{K}_{\ell=1}\frac{c_{ \ell}  }{ p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}.
\end{equation*} 
The coefficient $c_\ell$ is a lower bound on the probability of visiting $S_\ell$ at least once, which can be calculated as follows, 
\begin{align*}\left\{\begin{array}{ll}
    c_{\ell} \le \min_{k:\ell < k\le K}  \;   \min_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}. 
  %\label{equDKCondition1}
  \\  c_\ell \le \frac{\Pr(X^{[0]} \in S_{\ell})}{\Pr(X^{[0]} \in S_{[0,\ell]})}. %\label{equDKCondition2}
\end{array}
\right.
\end{align*}  



