\section{Estimate Hitting time by Hitting Probability}
\label{sec:Theory}
This section explains the linear coefficient of a linear bound as a bound on the hitting probability.

\subsection{Exact Hitting Time} 
Given a fitness level partition $(S_0,\ldots,S_K)$, the hitting time can be intuitively derived as follows.  Assume that the Markov chain $(X^{[t]})_{t \ge 0}$ starts from $X_k \in S_k$.  Intuitively, the hitting time from $X_k$ to $S_0$ is equal to the time that the chain stays at all non-optimal levels $S_1, \ldots, S_k$. The staying time at level $S_\ell$ is equal to the hitting time from $S_\ell$ to leaving  $S_\ell$, multiplied by the hitting probability from $S_k$ to entering $S_\ell$. This observation is formalized in the following theorem.


\begin{theorem}
\label{the:MeanHittingTime}
Given  a fitness level partition $(S_0, \ldots, S_K)$, the mean hitting time from $X_k$ to the optimal set $S_0$ (where $1\le k \le K$) is equal to
    \begin{equation*}     
        m(X_k) = \sum^{k}_{\ell=1} \sum_{X_\ell \in S_\ell}  h(X_k,X_\ell) \, m(X_\ell, \overline{S}_\ell) .  
    \end{equation*}
\end{theorem}

\begin{IEEEproof}
Let $\tau$ be the time that the chain spends at level $S_1 \cup \cdots \cup S_k$ and $\tau_\ell$ be the time period between when the chain entering $S_\ell$ and leaving $S_\ell$. Then
$
\tau =  \tau_1+\cdots +\tau_k,
$
and
\begin{equation}   
\label{equ:time-1a} 
        m(X_k) = \mathrm{E}[\tau_1]+\mathrm{E}[\tau_2]+ \cdots +\mathrm{E}[\tau_k].   
    \end{equation} 

%Let $\mathrm{Hit}_\ell$ be the event that the chain starts from $X_k$ to first enter $S_\ell$. 
Once the    chain enters the level $S_\ell$, it  will not return to a level lower than $S_\ell$.  The mean hitting time 
\begin{equation} \label{equ:time-1b}\begin{split}
 \mathrm{E}[\tau_\ell] 
    = \sum_{X_\ell \in S_\ell} h(X_k,X_\ell) m(X_\ell, \overline{S}_\ell) ,
\end{split}
\end{equation}
where $h(X_k,X_\ell)$ is the hitting probability from  $X_k$ to $X_\ell$ and $m(X_\ell,\overline{S}_\ell )$ is the mean hitting time from $X_\ell$ to leaving $S_\ell$.
Inserting \eqref{equ:time-1b} into \eqref{equ:time-1a}, we obtain  the desired conclusion.
\end{IEEEproof}




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Lower and Upper Bounds on Hitting Time}
Theorem \ref{the:MeanHittingTime} gives the exact hitting time. % of the elitist EA based on a fitness level partition. 
But in most cases, it is impossible to calculate the exact hitting time. Therefore, it is necessary to estimate their lower and upper bounds. The following theorem gives lower and upper linear bounds on hitting time based on the hitting probability. 


\begin{theorem}
\label{the:TimeBounds}
Given a fitness level partition $(S_0, \ldots, S_K)$ and a fitness level $k: 0<k \le K$, 

(1) The mean hitting time from $X_k$ to the optimal set $S_0$ (where $1\le k \le K$) is lower-bounded by 
    \begin{equation}   
    \label{equ:LinearLowerBound2}  m(X_k)  \ge
 \sum^{k}_{\ell=1}\frac{ h_{{\scriptscriptstyle\min}}(X_{k},S_\ell) }{ p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})} .  
    \end{equation}

(2)  The mean hitting time from $X_k$ to the optimal set $S_0$ (where $1\le k \le K$) is upper-bounded by
    \begin{equation}   
    \label{equ:LinearUpperBound2}   
    m(X_k)   \le
 \sum^{k}_{\ell=1}\frac{ h_{{\scriptscriptstyle\max}}(X_{k},S_\ell) }{ p_{{\scriptscriptstyle\min}}(X_{\ell},S_{[0,\ell-1]})}.  
    \end{equation}
\end{theorem}

\begin{IEEEproof}  1) First, we estimate a lower bound on $m(X_\ell,\overline{S_\ell})$.  Let $X^\sharp_\ell \in S_\ell$ such that $m(X^\sharp_\ell,\overline{S_\ell})=m_{\scriptscriptstyle\min}(X_\ell,\overline{S_\ell})$. According to  Proposition~\ref{pro:HittingTime}, we have  
 \begin{align*}
 %\begin{array}{rll} 
m_{\scriptscriptstyle\min}(X_\ell,\overline{S_\ell})=  &m(X^\sharp_\ell,\overline{S_\ell})\\  
       =& 1+\sum_{Y_\ell \in S_\ell} p(X^\sharp_\ell,Y_\ell) m(Y_\ell,\overline{S_{\ell}}) \\
       \ge &1+ p(X^\sharp_\ell,S_\ell) m_{\scriptscriptstyle\min}(X_\ell,\overline{S_\ell}). 
 %\end{array}  
 \end{align*}  
Then we get
  \begin{align} 
 % \begin{array}{rl}
       &   m_{\scriptscriptstyle\min}(X_\ell,\overline{S_\ell})
      \ge \frac{1}{1 - p(X^\sharp_\ell,S_\ell)} \nonumber \\   
       = &  \frac{1}{  p(X^\sharp_\ell,S_{[0,\ell-1]})}  
       \ge  \frac{1}{p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}. \label{equ:MeanTimeLowerBound}
 % \end{array}
 \end{align} 

Second, we estimate a lower bound on the mean hitting time $m(X_k)$ to the optimal set. 
According to Theorem~\ref{the:MeanHittingTime}, 
\begin{align*}    
  %\begin{array}{rl}
          m(X_k) 
         = &\sum^{k}_{\ell=1} \sum_{Y_\ell \in S_\ell}  h(X_k,Y_\ell) m(Y_\ell, \overline{S}_\ell)\\%[1mm]
        \ge &   \sum^{k}_{\ell=1}   h_{{\scriptscriptstyle\min}}(X_k,S_\ell)m_{\scriptscriptstyle\min}(X_\ell,\overline{S_\ell})  \\%[1mm]
        \ge &\sum^{k}_{\ell=1}\frac{    h_{{\scriptscriptstyle\min}}(X_k,S_\ell) }{ p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})} \quad \mbox{(by \eqref{equ:MeanTimeLowerBound})} .  
        %\end{array}
\end{align*}
Then we get Inequality \eqref{equ:LinearLowerBound2}. 


2) The proof is similar to the first part.
\end{IEEEproof}





The above theorems provide an explanation of the linear bound coefficients.  The hitting probability  $ h_{{\scriptscriptstyle\min}}(X_{k},S_\ell) $ is a  lower bound coefficient, and  $ h_{{\scriptscriptstyle\max}}(X_{k},S_\ell) $ is an upper bound coefficient. Any $ c_{k,\ell} \le  h_{{\scriptscriptstyle\min}}(X_{k},S_\ell)$ is a lower bound coefficient, while any $   c_{k,\ell}  \ge h_{{\scriptscriptstyle\max}}(X_{k},S_\ell)$  an upper bound coefficient. Since $ h(X_{k},S_k) =1$, the coefficient $c_{k,k}$ is always assigned to $1$. 


 The terms viscosity \cite{sudholt2012new}, visit probability \cite{doerr2024lower}, and coefficient \cite{he2023drift}  fundamentally study the same subject: the probability of visiting fitness levels.  Their distinctions  can be characterized as viscosity for Type-\(c\) time bounds, visit probability for Type-\(c_{\ell}\) bounds, and coefficient for Type-\(c_{k,\ell}\) bounds. Hitting probability is adopted in the paper because it is a standard term used in Markov chains \cite{norris1998markov}. 
