\section{Drift Analysis of Hitting Probability}
 \label{sec:Method}
This section develops drift analysis of hitting probability to compute the coefficients in a linear drift function.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Drift Function} 
Computing exact values of  hitting probabilities is challenging. Instead, a new drift analysis method is proposed to estimate their bounds. Given a level $S_\ell$ (where $1 \le \ell \le K$), a drift function $c(X, S_\ell)$ is used to approximate the hitting probability $h(X, S_\ell)$. It is designed specifically for elitist EAs based on fitness level partitioning.

\begin{definition}
    Given a fitness level partition $(S_0,\ldots,S_K)$, and a level  $ S_\ell$ (where $1 \le \ell \le K$),  a \emph{drift function} $c(X, S_\ell)$ is a function  $S \to [0,1]$ such that for any $X_k \in S_k$,
\begin{equation}
\label{equ:DriftFunction}
    c(X_k, S_\ell):=c_{k,\ell} =\left\{
    \begin{array}{ll}
         0 & \mbox{if }    \ell>k,\\
          1    &  \mbox{if }   \ell=k,\\
           \in [0,1]&  \mbox{if }   \ell < k,
    \end{array}
    \right.
\end{equation} 
where $c_{k,\ell}$ is called coefficient in the paper.
\end{definition}


The above drift function makes use of two observations that (i) the hitting probability from a lower level  to a higher level  is equal to $0$, and (ii) the hitting probability to the same level  is equal to $1$. Note that there is no need to approximate the probability of hitting the optimal set, because in a converged EA, this probability is equal to \(1\). Hence, we assign $c_{k, 0}=1$. 



\begin{definition}
 Based on the transition probability, the standard \emph{drift} from $X_k$ to $S_\ell$  (where $1 \le \ell <k \le K$) is 
\begin{align}
{\Delta} c(X_k, S_\ell):= &\sum^{K}_{i=0} \sum_{Y_i \in S_i} p(X_k, Y_i) \left(c_{k,\ell} -   c_{i, \ell}\right)\nonumber,\\
=&c_{k,\ell} -\sum^{k}_{i=\ell} p(X_k, S_i) \, c_{i, \ell}\label{equ:Drift}.
\end{align} 
Based on the conditional transition probability, the \emph{conditional drift} from $X_k$ to $S_\ell$  is 
\begin{align}
\tilde{\Delta} c(X_k, S_\ell):= &\sum^{K}_{i=0} \sum_{Y_i \in S_i}  r(X_k, Y_i) \left(c_{k,\ell} -   c_{i, \ell}\right)\nonumber
\\
=&c_{k,\ell} -\sum^{k-1}_{i=\ell} r(X_k, S_i) \, c_{i, \ell}\label{equ:ConditionalDrift},
\end{align}  
\end{definition} 
The above definitions makes use of the facts: $p(X_k, S_i)=0$ for $i > k$,  $r(X_k, S_i)=0$ for $i \ge k$, and   $c_{i, \ell}=0$ for $i< \ell$. 

%{\color{blue} The drift conditions from the two drifts are equivalent.}  
%\begin{align*}
%{\color{blue}  {\Delta} c(X_j, S_\ell)  \le 0  \Leftrightarrow \tilde{\Delta} c(X_j, S_\ell)  \le 0,} \\ 
%{\color{blue}    {\Delta} c(X_j, S_\ell)  \ge 0  \Leftrightarrow \tilde{\Delta} c(X_j, S_\ell)  \ge 0.}
%\end{align*}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Drift Conditions} 
The following theorem provides drift conditions to determine that a drift function is a lower or upper bound on the hitting probability. 

\begin{theorem} 
\label{the:DriftTheorem} Given a fitness level partition $(S_0,\ldots,S_K)$, a drift function \eqref{equ:DriftFunction} and two levels $\ell, k: 1 \le \ell <k \le K$,  

(1) If for any $\ell< j \le  k$ and any $X_j \in S_j$, the conditional drift 
$\tilde{\Delta} c(X_j, S_\ell)  \le 0$, equivalently, the coefficient  
\begin{align}\label{equ:LowerCoefficient}
    c_{j,\ell} \le \min_{X_j \in S_j} \left\{r (X_j, S_\ell)+ \sum^{j-1}_{i=\ell+1}r (X_j, S_i)    c_{i, \ell} \right\},
\end{align} 
then for any $\ell< j \le  k$, the coefficient  $c_{j,\ell}\le h_{{\scriptscriptstyle\min}}(X_j,S_\ell)$. 

(2) If for any $\ell<j \le k$ and any $X_j \in S_j$, the conditional drift 
$\tilde{\Delta} c(X_j, S_\ell)  \ge 0$, equivalently, the coefficient 
\begin{align}\label{equ:UpperCoefficient}
    c_{j,\ell} \ge  \max_{X_j \in S_j} \left\{r (X_j, S_\ell)+ \sum^{j-1}_{i=\ell+1} r (X_j, S_i)    c_{i, \ell} \right\},
\end{align} 
then for any $\ell< j \le  k$, the coefficient  $c_{j,\ell}\ge h_{{\scriptscriptstyle\max}}(X_j,S_\ell)$.  
\end{theorem}




\begin{IEEEproof}  1) For $j: \ell <j \le k$, let $X^\sharp_j  \in S_j$  such that $h(X^\sharp_j, S_\ell) = h_{\scriptscriptstyle\min}(X_j,S_\ell)$.
By Proposition~\ref{pro:HittingProbability},  %the hitting probability 
\begin{align*}
h_{\scriptscriptstyle\min}(X_j,S_\ell)= &h(X^\sharp_j,S_\ell) 
\\=& \sum^j_{i=\ell}\sum_{Y_i \in S_i} p(X^\sharp_j,Y_i) h (Y_i,S_\ell)\\
\ge & \sum^j_{i=\ell}  p(X^\sharp_j,S_i) h_{{\scriptscriptstyle\min}}(X_i,S_\ell).
\end{align*} 

Moving the term $i=j$ from the right-hand sum to the left, we obtain
\begin{align} h_{{\scriptscriptstyle\min}} (X_j,S_\ell)  \ge &\sum^{j-1}_{i=\ell} \frac{p(X^\sharp_j,S_i)}{1-p(X^\sharp_j,S_j) } h_{{\scriptscriptstyle\min}} (X_i,S_\ell) \nonumber \\
= &\sum^{j-1}_{i=\ell} r(X^\sharp_j,S_i) h_{{\scriptscriptstyle\min}} (X_i,S_\ell) \label{equ:DriftCondition-hmin}.
\end{align}


We prove that for any $\ell< j \le  k$,   $c_{j,\ell}\le h_{{\scriptscriptstyle\min}}(X_j,S_\ell)$ by induction. For $j=\ell+1$, by \eqref{equ:LowerCoefficient} and then \eqref{equ:DriftCondition-hmin} (note that $c_{\ell,\ell}=h_{{\scriptscriptstyle\min}}(X_\ell, S_\ell)=1$), we get  
\begin{align*} 
    c_{\ell+1,\ell} \le & r(X^\sharp_{\ell+1}, S_\ell)  
    \le  h_{{\scriptscriptstyle\min}} (X_{\ell+1},S_\ell). 
\end{align*} 

We make an inductive assumption that for $j \ge \ell+1$,
\begin{equation}
    \label{equ:suppose-a}
    c_{j,\ell}\le h_{{\scriptscriptstyle\min}} (X_j,S_\ell).
\end{equation} 

By the condition \eqref{equ:LowerCoefficient}, the assumption \eqref{equ:suppose-a} and \eqref{equ:DriftCondition-hmin}, we get
\begin{align*}
c_{j+1,\ell} &\le \sum^{j}_{i=\ell} r(X^\sharp_{j+1},S_i) c_{i,\ell}  \\
 &\le \sum^{j}_{i=\ell} r(X^\sharp_{j+1},S_i)  h_{{\scriptscriptstyle\min}} (X_i,S_\ell) \\
 &\le  h_{\scriptscriptstyle\min}(X_{j+1},S_\ell).
\end{align*}
We prove that $c_{j+1,\ell}\le h_{{\scriptscriptstyle\min}}(X_{j+1},S_\ell)$ for $j+1$. Thus, by induction, we complete the proof. 


2) The proof is similar to the first part.
\end{IEEEproof}

Interestingly, the recursive formulas \eqref{equ:LowerCoefficient} and \eqref{equ:UpperCoefficient} in the above theorem are identical to that in Proposition~\ref{pro:LinearBound}, despite being derived through entirely different proofs. But Theorem \ref{the:DriftTheorem} makes a new contribution: drift analysis of hitting probability. A lower bound coefficient is a lower bound on the hitting probability, while an upper bound coefficient is an upper bound on the hitting probability. A drift function is used to bound the hitting probability, and the drift condition determines whether the drift function serves as a lower or upper bound.

Type-$c$ and Type-$c_\ell$ bounds \cite{he2023drift} can be rewritten in terms of {necessary and sufficient} drift conditions. A detailed analysis is given in the supplementary material. The drift conditions in Theorem \ref{the:DriftTheorem} are based on pointwise drift. Average drift \cite{he2017average} can be used to handle random initialization. 
