\subsection{Direct Calculation and Alternative Calculation}
 The coefficients in Theorem \ref{the:DriftTheorem} are determined recursively. He and Zhou~\cite{he2023drift} gave explicit expressions for calculating the coefficients as follows.

\begin{corollary} Given  a fitness level partition $(S_0, \ldots, S_K)$ and two levels $\ell, k: 1 \le \ell <k \le K$,

(1) Let a drift function \eqref{equ:DriftFunction} (denoted by $c^{\min}(X, S_\ell)$)  satisfies that for $X \in S_j$, $c^{\min}_{\ell, \ell}=1$ and for any $\ell<j \le k$,   
\begin{align*} 
    c^{\min}_{j,\ell}   
   =& \ 
        r_{{\scriptscriptstyle\min}}(X_j, S_{\ell})   \\
         & + \sum_{ \ell<j_1<j} r_{{\scriptscriptstyle\min}}(X_j, S_{j_1})\, r_{{\scriptscriptstyle\min}}(X_{j_1}, S_{\ell})  +\cdots\\ 
&+\sum_{ \ell<\ell+1<\cdots<j-1<j} \, r_{{\scriptscriptstyle\min}}(X_j, S_{j-1}) \cdots  r_{{\scriptscriptstyle\min}}(X_{\ell+1}, S_{\ell}).  
\end{align*}  
Then $
c^{\min}_{j,\ell} \leq h_{\scriptscriptstyle \min}(X_j, S_\ell).
$

(2) Let a drift function \eqref{equ:DriftFunction} (denoted by $c^{\max}(X, S_\ell)$)  satisfies that for $X \in S_j$, $c^{\max}_{\ell, \ell}=1$ and for any $\ell<j \le k$,   
\begin{align*} 
    c^{\max}_{j,\ell}   
   =& \ 
        r_{{\scriptscriptstyle\max}}(X_j, S_{\ell})   \\
         & + \sum_{ \ell<j_1<j} r_{{\scriptscriptstyle\max}}(X_j, S_{j_1})\, r_{{\scriptscriptstyle\max}}(X_{j_1}, S_{\ell})  +\cdots\\ 
&+\sum_{ \ell<\ell+1<\cdots<j-1<j} \, r_{{\scriptscriptstyle\max}}(X_j, S_{j-1}) \cdots  r_{{\scriptscriptstyle\max}}(X_{\ell+1}, S_{\ell}).  
\end{align*}  
Then $
c^{\max}_{j,\ell} \geq h_{\scriptscriptstyle \max}(X_j, S_\ell).
$
\end{corollary}

\begin{IEEEproof}
(1)    By applying induction, it is straightforward to confirm that for any \( \ell < j \leq k \), the coefficient \( c^{\min}_{j,\ell} \) satisfies 
\[
c^{\min}_{j,\ell} = \sum^{j-1}_{i=\ell} r_{\scriptscriptstyle\min}(X_j, S_i) c^{\min}_{i, \ell} \leq \sum^{j-1}_{i=\ell} r(X_j, S_i) c^{\min}_{i, \ell}.
\]
Consequently, according to Theorem \ref{the:DriftTheorem}.(1), for any \( \ell < j \leq k \),  we have
$
c^{\min}_{j,\ell} \leq h_{\scriptscriptstyle \min}(X_j, S_\ell).
$


 (2) The proof is similar to the first part.
\end{IEEEproof}

Each term in \(c^{\min}_{j,\ell}\) or \(c^{\max}_{j,\ell}\) denotes the conditional probability of reaching \(S_\ell\) along a path originating from \(S_j\). The hitting probability is obtained by summing these conditional probabilities over all possible paths connecting \(S_j\) to \(S_\ell\).  

In Theorem \ref{the:DriftTheorem}, coefficients are computed recursively in the direction from $\ell+1$ to $k$: $c_{\ell+1, \ell}, c_{\ell+2, \ell}, \ldots, c_{k, \ell}$. They can also be computed recursively in the opposite direction from $k-1$ to $\ell$: $c_{k, k-1}, c_{k, k-2}, \ldots, c_{k, \ell}$, as shown below.

\begin{theorem} 
\label{the:DriftTheorem-alt}  
Given a fitness level partition $(S_0,\ldots,S_K)$ and two levels $\ell, k: 1 \le \ell <k \le K$,  

(1) Let a drift function \eqref{equ:DriftFunction} satisfy that for any  $\ell<j \le k$,  
\begin{align} 
\label{equ:LowerCoefficient-alt}
{c}_{j,\ell} \le \sum^{K}_{i=0} {c}_{j,i}  \,  r_{\scriptscriptstyle\min}(X_i, S_\ell) = \sum^{j}_{i=\ell+1} {c}_{j,i}  \,  r_{\scriptscriptstyle\min}(X_i, S_\ell),
\end{align}  
then  for any  $\ell<j \le k$, the coefficient $c_{j,\ell}\le h_{{\scriptscriptstyle\min}}(X_j,S_\ell)$.

(2) Let a drift function \eqref{equ:DriftFunction} satisfy that for any  $\ell<j \le k$, 
\begin{align}  
\label{equ:UpperCoefficient-alt}
 {c}_{j,\ell} \ge \sum^{K}_{i=0}c_{j,i}  \,  r_{\scriptscriptstyle\max}(X_i, S_\ell)  = \sum^{j}_{i=\ell+1}c_{j,i}  \,  r_{\scriptscriptstyle\max}(X_i, S_\ell),
\end{align} 
then for any  $\ell<j \le k$, the coefficient $c_{j,\ell}\ge h_{{\scriptscriptstyle\max}}(X_j,S_\ell)$. 
\end{theorem}



\begin{IEEEproof} 
(1) 
By applying induction to \eqref{equ:LowerCoefficient-alt}, we can establish that \( c_{j,\ell} \leq c^{\min}_{j,\ell} \). By the above corollary, we arrive at the desired conclusion.



(2) The proof is similar to the first part.
\end{IEEEproof} 

Note: The sums in \eqref{equ:LowerCoefficient-alt} and \eqref{equ:UpperCoefficient-alt} do not contain the terms $i \le \ell$ and $i>k$, since for $i \le \ell$, $r_{{\scriptscriptstyle\min}}(X_i, S_{\ell})=0$, and for $i>k$, $c_{i, \ell}=0$.  


