\subsection{Lower Bound Coefficients Using Paths}  
For multimodal fitness landscapes, there are multiple paths from one fitness level to another.  For example, in Fig.~\ref{fig:Jump}, there are $11!$ paths from $S_{12}$ to $S_1$. To calculate coefficient $c_{k,\ell}$, it is sufficient to use one path $P[\ell,k]$ from $S_k$ to $S_\ell$, rather than using all paths from $S_k$ to $S_\ell$.   For example, in Fig.~\ref{fig:Jump}, coefficient $c_{12,1}$ can be estimated using a longer path $S_{12} \to \cdots \to S_2 \to S_1$, or a shorter path $S_{12} \to \cdots  \to S_8 \to S_1$.  In this case, two $c_{12,1}$ values can be generated, however, it suffices to utilize any one of them.  


The following theorem uses a path to obtain the lower bound coefficient $c_{k,\ell}$. If vertex $j \in (\ell, k]$ is not on the path $P(\ell,k]$, then we directly assign the coefficient $c_{j,\ell }=0$.

\begin{theorem}
\label{the:LowerBoundPaths} Given  a fitness level partition $(S_0, \ldots, S_K)$ and two levels $\ell, k: 1 \le \ell <k \le K$,  let $P{[\ell,k]}$ be a path from $k$ to $\ell$.   Let a drift function \eqref{equ:DriftFunction} satisfy that  for any $j \in (\ell,k] \setminus P{(\ell,k]}$,  $c_{j, \ell}=0$, and for any $j \in P(\ell ,k]$,  
\begin{equation} 
\label{equ:LowerCoefficient3} 
 c_{j,\ell} \le \min_{X_j \in S_j} \left\{ r (X_j, S_\ell)+  \sum_{i \in P{( \ell,j)}} r(X_j, S_i)    \, c_{i, \ell}\right\}. 
\end{equation} 
Then  for any $\ell <j \le k$, coefficient $c_{j,\ell}\le h_{{\scriptscriptstyle\min}}(X_j,S_\ell)$.  
\end{theorem} 



\begin{IEEEproof}  For any  $j\in (\ell, k] \setminus P{(\ell,k]}$, since $c_{j,\ell}=0$, the conditional drift $\tilde{\Delta} c(X_j, S_\ell)  \le 0$. For any  $j \in P{(\ell,k]}$, the conditional drift $\tilde{\Delta} c(X_j, S_\ell)  \le 0$ by \eqref{equ:LowerCoefficient3}.   According to Theorem~\ref{the:DriftTheorem}.(1), we get the conclusion.   
\end{IEEEproof}



 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The coefficient computation in Theorem~\ref{the:LowerBoundPaths} is recursive. 
The following corollary provides a non-recursive way to compute the coefficients.

\begin{corollary} 
\label{cor:LowerExplicitExpression}  Given  a fitness level partition $(S_0, \ldots, S_K)$ and two levels $\ell, k: 1 \le \ell <k \le K$,    
let $P{[\ell,k]}$ be a path from $k$ to $\ell$.   
Let a drift function \eqref{equ:DriftFunction} satisfy that for any $j \in (\ell,k] \setminus P{(\ell,k]}$,   $c_{j, \ell}=0$, and for any $j \in P(\ell ,k]$, 
\begin{align}
\label{equ:LowerExplicitExpression}   
 c_{j,\ell} = & \prod_{i\in P(\ell, j]}     r_{\scriptscriptstyle\min}(X_i,S_{P[\ell,i)}), 
 \end{align}  
 then for any $\ell <j \le k$, coefficient $c_{j,\ell}\le h_{{\scriptscriptstyle\min}}(X_j,S_\ell)$. 
\end{corollary} 
\begin{IEEEproof}
 From \eqref{equ:LowerExplicitExpression},  we get
\begin{align}
 \min_{i \in P{(\ell,j)}}  c_{i, \ell} &=  \prod_{i\in P(\ell, j)}     r_{\scriptscriptstyle\min}(X_i,S_{P[\ell,i)}) , \nonumber\\
\label{equ:Cor1Condition}
    c_{j,\ell} &= r_{\scriptscriptstyle\min}(X_{j}, S_{P[\ell,j)})  \min_{i \in P{(\ell,j)}}   c_{i, \ell}. 
\end{align}
%\begin{align}
%& \min_{i \in P{(\ell,j)}}  c_{i, \ell} =  \prod_{i\in P(\ell, j)}  %   r_{\scriptscriptstyle\min}(X_i,S_{P[\ell,i)}) , \nonumber\\
%\label{equ:Cor1Condition}
%  &  c_{j,\ell}= r_{\scriptscriptstyle\min}(X_{j}, S_{P[\ell,j)})  %\min_{i \in P{(\ell,j)}}   c_{i, \ell}. 
%\end{align}

For any $j \in P{(\ell,k]}$,    
\begin{align*} 
&\min_{X_j \in S_j} \left\{ \sum_{i \in P{[\ell,j)}} r(X_j, S_i)    \, c_{i, \ell}\right\} \\
\ge &\ \sum_{i\in {[\ell,j)}}  r_{\scriptscriptstyle\min}(X_j, S_i)    c_{i, \ell}\\ 
\ge &\  r_{\scriptscriptstyle\min}(X_j, S_{P{[\ell,j)}})  \min_{i \in P{(\ell,j)}}   c_{i, \ell} =   c_{j,\ell} \quad \mbox{(by \eqref{equ:Cor1Condition})}.
\end{align*}   

According to Theorem~\ref{the:LowerBoundPaths}, we get the conclusion.   
\end{IEEEproof}
In \eqref{equ:LowerExplicitExpression}, the transition probability $r(X_j,S_{P[\ell,j)})$ represents the transition from $X_j$ to the path $P[\ell,j)$.  

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Upper Bound Coefficients Using Paths} 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Intuitively, it seems impossible to obtain an upper bound on the hitting probability using a path, since the transition probability of going from $S_k$ to $S_\ell$ is  not less than that of going from $S_k$ to $S_\ell$ via a path $P{[\ell,k]}$. Counterintuitively, the following theorem surprisingly establishes an upper bound on the hitting probability using a path. If vertex $i \in (\ell, k]$ is not on the path $P(\ell,k]$, we simply assign the coefficient $c_{i,\ell }=1$.

\begin{theorem}
\label{the:UpperBoundPaths}Given  a fitness level partition $(S_0, \ldots, S_K)$  and two levels $\ell, k: 1 \le \ell <k \le K$,    let $P{[\ell,k]}$ be a path from $k$ to $\ell$.
 Let a drift function \eqref{equ:DriftFunction} satisfy that for any $j \in (\ell,k] \setminus P{(\ell,k]}$, $c_{j, \ell}=0$, and for any $j \in P(\ell ,k]$,  
\begin{align}\label{equ:UpperCoefficient3}
     c_{j,\ell} \ge   \max_{X_j \in S_j} \left\{ r(X_j, S_{[\ell, j)\setminus P{(\ell,j)}} )
   + \sum_{i\in P{(\ell,j)}} r(X_j, S_i)   c_{i, \ell}\right\}, 
    \end{align}  
 then for any $\ell <j \le k$, the coefficient $c_{j,\ell}\ge h_{{\scriptscriptstyle\max}}(X_j,S_\ell)$.  
\end{theorem}  



\begin{IEEEproof} For any  $j \in  (\ell,k] \setminus P{(\ell,k]}$, since $c_{j,\ell}=1$, the conditional drift  $\tilde{\Delta} c(X_j, S_\ell)  \ge 0$. For any  $ j \in P{(\ell,k]}$, the conditional drift $\tilde{\Delta} c(X_j, S_\ell)  \ge 0$ by \eqref{equ:UpperCoefficient3}.    
According to Theorem~\ref{the:DriftTheorem}.(2), we get the conclusion.  
\end{IEEEproof} 

 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The coefficient computation in Theorem~\ref{the:UpperBoundPaths} is recursive. 
The following corollary provides a non-recursive way to compute the coefficients.

\begin{corollary} 
\label{cor:UpperExplicitExpression2} Given  a fitness level partition $(S_0, \ldots, S_K)$  and two levels $\ell, k: 1 \le \ell <k \le K$,    let $P{[\ell,k]}$ be a path from $k$ to $\ell$.  Let a drift function \eqref{equ:DriftFunction} satisfy that for any $j \in (\ell,k] \setminus P{(\ell,k]}$, $c_{j, \ell}=0$, and for any $j \in P(\ell ,k]$, 
\begin{align}
\label{equ:UpperExplicitExpression2}   
 c_{j,\ell}  =   \sum_{i\in P(\ell, j]}   r_{\scriptscriptstyle\max}(X_i,S_{[\ell, i)\setminus P(\ell,i)}), 
 \end{align}
then for any $\ell <j \le k$, the coefficient $c_{j,\ell}\ge h_{{\scriptscriptstyle\max}}(X_j,S_\ell)$. 
\end{corollary} 
\begin{IEEEproof}  From \eqref{equ:UpperExplicitExpression2}, we get 
\begin{align} 
\max_{i \in P{(\ell,j)}}  c_{i, \ell} &= \sum_{i\in P(\ell, j)}   r_{\scriptscriptstyle\max}(X_i,S_{[\ell, i)\setminus P(\ell,i)}),\nonumber\\
\label{equ:Cor2Condition}
  c_{j,\ell}  &= r_{\scriptscriptstyle\max}(X_j, S_{[\ell, j)\setminus P{(\ell,j)}}) +  \max_{i \in P{(\ell,j)}}  c_{i, \ell}.
\end{align}
%\begin{align} 
%&\max_{i \in P{(\ell,j)}}  c_{i, \ell} = \sum_{i\in P(\ell, j)}   %r_{\scriptscriptstyle\max}(X_i,S_{[\ell, i)\setminus %P(\ell,i)}),\nonumber\\
%\label{equ:Cor2Condition}
% & c_{j,\ell}  =\ r_{\scriptscriptstyle\max}(X_j, S_{[\ell, %j)\setminus P{(\ell,j)}}) +  \max_{i \in P{(\ell,j)}}  c_{i, \ell}. 
% \end{align}

For any $j \in P{(\ell,k]}$ and $X_j \in S_j$,  
\begin{align*} 
&  \max_{X_j \in S_j} \left\{ r(X_j, S_{[\ell, j)\setminus P{(\ell,j)}} )
   + \sum_{i\in P{(\ell,j)}} r(X_j, S_i)   c_{i, \ell}\right\} \\  
 \le  & \  r_{\scriptscriptstyle\max}(X_j, S_{[\ell, j)\setminus P(\ell,j)}) +     r_{\scriptscriptstyle\max}(X_j, S_{P(\ell,j)}) \max_{i \in P{(\ell,j)}} c_{i, \ell}    \\
 \le &\    r_{\scriptscriptstyle\max}(X_j, S_{[\ell, j)\setminus P(\ell,j)})  +     \max_{i \in P{(\ell,j)}}  c_{i, \ell}  = c_{j,\ell} \quad \mbox{(by \eqref{equ:Cor2Condition})}.
\end{align*}      
According to Theorem~\ref{the:UpperBoundPaths}, we get the conclusion. 
\end{IEEEproof}

In \eqref{equ:UpperExplicitExpression2}, the conditional probability $r(X_j,S_{[\ell,j)\setminus P(\ell,j)})$ represents the transitions from $X_j$ to those vertices in $[\ell,j)$ but not on the path $P(\ell,j)$. %In many cases, it is not necessary to compute the upper coefficient. When the hitting probability $h_{\scriptscriptstyle\max}(X_k,S_\ell)=O(1)$, using $1$ is sufficient as a good upper bound coefficient. %\deleted{However, if the hitting probability $h_{\scriptscriptstyle\min}(X_k,S_\ell)=\Omega(1)$,  using $0$ is not a good lower bound coefficient. This explains why estimating a tight lower bound is more difficult than estimating a tight upper bound.}

