%\FOR{$t=1,2,\ldots$}
%\STATE  Flip  each bit of $x$ independently with  probability $ {1}/{n}$ to generate a solution $y$.
%\STATE If $y$ is infeasible, select the item with the lowest value and remove it from the knapsack. Repeat this process until the weight is within the capacity.  
%\STATE  If $f(y) \ge f(x)$, then  $X^{[t+1]}=y$; else $X^{[t+1]}=x$.
%\ENDFOR
%\end{algorithmic}
