\subsubsection{The (1+1) EA Using Feasibility Rules} 

It is sufficient to consider feasible solutions because infeasible solutions are worse than the empty knapsack.  
According to the lower bound \eqref{equ:LinearLowerBound2} in Theorem \ref{the:TimeBounds}, the mean hitting time from the empty knapsack to the global optimum is
\begin{align}
    m(0,0;0) \ge  \frac{h_{(0,0;0), (0,1;1)}}{p_ {(0,1;1), (0,1;1)^+}}.
\label{instance1-a1} 
\end{align}

Since $
   L^+_{(0,1;1)} =L_{(1,0;0)} \cup L_{(0,0;[n/2+2,n-2])},$
the transition probabilities
\begin{align*} 
 p_{(0,1;1), (1,0;0)} \le & \left(\frac{1}{n}\right)^3,\\
  p_{(0,1;1), (0,0;[n/2+2,n-2])} \le & \frac{1}{n} \binom{n-3}{n/2+2}\left(\frac{1}{n}\right)^{n/2+2}, 
\end{align*}
and then the transition probability 
\begin{align*}%\label{instance1-a2}
 p_{(0,1;1), (0,1;1)^+}& \le \left(\frac{1}{n}\right)^3 +\frac{1}{n} \binom{n-3}{n/2+2}\left(\frac{1}{n}\right)^{n/2+2}  \\
 &=O(n^{-3}).
\end{align*}

Thus, the mean hitting time 
\begin{align} 
 m(0,0,0) \ge \Omega(n^3)\;  h_{(0,0;0), (0,1;1)}. 
      \label{instance1-a3}
\end{align}


We compute the hitting probability $h_{(0,0;0), (0,1;1)}$ using the path $L_{(0, 0;0)} \to  L_{(0,1; 1)}$  (see Fig. \ref{fig:Knapsack}.(a)).  An intuitive observation is that the probability of hitting $L_{(0,1; 1)}$ is $\Omega(\frac{1}{n})$ because of flipping bit $b_2$ and flipping one of bits in $[b_3, b_n]$. We rigorously analyze it with Corollary \ref{cor:LowerExplicitExpression}.

By Corollary \ref{cor:LowerExplicitExpression}, the hitting probability  
\begin{align*}  
     h_{(0,0;0),(0,1;1)}  \ge r_{(0,0;0),(0,1;1)} \ge p_{(0,0;0),(0,1;1)}.  
\end{align*} 

The transition probabilities
\begin{align*}
p_{(0,0;0), (0,1;1] }  \ge \frac{1}{n} \binom{n-3}{1} \frac{1}{n} \left(1-\frac{1}{n}\right)^{n-2}.  
\end{align*} 

Then, the hitting probability
\begin{align} 
    h_{(0,0;0), (0,1;0)}  \ge \frac{1}{n}    \frac{n-3}{n} e^{-2} =  \Omega\left(\frac{1}{n}\right).
    \label{instance1-b2}
\end{align}

Thus, the mean hitting time 
\begin{align}  \label{instance1-b3}
m(0,0;0)=    \Omega(n^3)   \Omega(n^{-1})     =\Omega(n^2). 
\end{align}  

