According to the upper bound \eqref{equ:LinearUpperBound2} in Theorem \ref{the:TimeBounds}, the mean hitting time from the empty knapsack to the global optimum 
\begin{align}
    m(0,0;0) \le   \sum^{n-4}_{\ell=0} \frac{1}{p_{(0,0;\ell), (0,0;\ell)^+}}+
  \frac{h_{(0,0;0), (0,1;0)}}{p_{(0,1;0), (0,1;0)^+}}
\label{instance2-a1} . 
\end{align} 

The transition probabilities in \eqref{instance2-a1} are estimated as follows. For $\ell=0, \ldots, n-4$, since $L^+_{(0,0;\ell)} \supset L_{(0,0;\ell+1)}$ (see Fig. \ref{fig:Knapsack}.(b)), the transition probability  
\begin{align*}
%\label{instance2-a2}
p_{(0,0;\ell), (0,0;\ell)^+} \ge p_{(0,0;\ell),  (0,0;\ell+1)} \ge  \frac{n-2-\ell}{n} \left(1-\frac{1}{n}\right)^{n-1}. 
\end{align*}

Since $L^+_{(0,1;0)} = L_{(0,0;[n/2,n-3])}$ (see Fig. \ref{fig:Knapsack}.(b)), the transition probability $p_{(0,1;0), (0,0;[n/2,n-3]}$ is %equal to 
%\begin{align}\label{instance2-a3} 
%   \left(1-\frac{1}{n}\right)\frac{1}{n}   \sum^{n-3}_{i=n/2}\binom{n-2}{i} \left(\frac{1}{n}\right)^{i} \left(1-\frac{1}{n}\right)^{n-2-i}.
%\end{align}
no less than
\begin{align}\label{instance2-a3} 
   \left(1-\frac{1}{n}\right)\frac{1}{n}   \binom{n-2}{n/2}  \left(\frac{1}{n}\right)^{n/2} \left(1-\frac{1}{n}\right)^{n-2-n/2}.
\end{align}
Thus, the mean hitting time  $m(0,0,0)$ is upper-bounded by
\begin{align} 
           O(n \ln n)+ e \frac{h_{(0,0;0), (0,1;0)}}{\binom{n-2}{n/2}\left(\frac{1}{n}\right)^{n/2+1}} .%{\sum^{n-3}_{i=n/2}\binom{n-2}{i} \left(\frac{1}{n}\right)^{i+1} \left(1-\frac{1}{n}\right)^{n-1-i}}.
      \label{instance2-a4}
\end{align}

%\subsubsection{Hitting probability} 
Intuitively, the hitting probability $h_{(0,0;0), (0,1;0)}$ will not be greater than the sum of the conditional transition probabilities $r_{(0,0;\ell),(0,1;0)}$ over $\ell =0,\ldots, n/2-1$ (see Fig. \ref{fig:Knapsack}.(b)). Since the conditional probability $r_{(0,0;\ell),(0,1;0)}$ decreases exponentially fast as $\ell$ increases from $0$ to $n/2$, the hitting probability $h_{(0,0;0), (0,1;1)}=O(\frac{1}{n})$. We rigorously prove this observation.

By Corollary \ref{cor:UpperExplicitExpression2}, the hitting probability  
\begin{align*}  
     h_{(0,0;0),(0,1;0)} \le  \sum^{n/2-1}_{\ell=0}  r_{(0,0;\ell), (0,1;0)} = \sum^{n/2-1}_{\ell=0}  \frac{p_{(0,0;\ell), (0,1;0)}}{p_{(0,0;\ell), (0,0;\ell)^+}}.  
\end{align*} 



The transition probability
\begin{align}
    p_{(0,0;\ell), (0,1;0)} \le & \left(\frac{1}{n}\right)^{\ell+1}.  
\end{align}

Since $L^+_{(0,0;\ell)}\supset L_{(0,0;\ell+1)}$ (see Fig. \ref{fig:Knapsack}.(b)) and $\ell \le n/2$, the transition probability  
\begin{align*} 
p_{(0,0;\ell), (0,0;\ell)^+} &\ge p_{(0,0;\ell), (0,0;\ell+1)} \\
 &\ge \frac{n-3-\ell}{n} \left(1-\frac{1}{n}\right)^{n-1} \\
 &\ge \frac{1}{2e} - o(1).
\end{align*}

%\begin{align*} 
%\begin{array}{rl}
%&p_{(0,0;\ell), (0,0;\ell)^+}\\
%\ge &   p_{(0,0;\ell), (0,0;\ell+1)} \\
%\ge &  \frac{n-3-\ell}{n} \left(1-\frac{1}{n}\right)^{n-1} \nonumber\\
%    \ge &\frac{1}{2e} - o(1).
%\end{array}
%\end{align*}

Then the hitting probability  
\begin{align} h_{(0,0;0),(0,1;0)} \le \sum^{n/2-1}_{\ell=0} \frac{ (\frac{1}{n})^{\ell+1}  }{\frac{1}{2e} - o(1)} 
     = O\left(\frac{1}{n}\right).
\end{align} 

Thus, the mean hitting time  $m(0,0;0)$ is upper-bounded by
\begin{align}    
      \label{instance2-a5}  
      O(n \ln n)+   \frac{e}{\binom{n-2}{n/2}\left(\frac{1}{n}\right)^{n/2}}=   \frac{O(1)}{\binom{n-2}{n/2}\left(\frac{1}{n}\right)^{n/2}}.
      %\\         = & O(n \ln n) + O((n/2)!/n).\nonumber
\end{align} 
