\subsubsection{The (1+1) EA Using Greedy Repair}  
According to the lower bound \eqref{equ:LinearLowerBound2} in Theorem \ref{the:TimeBounds}, the mean hitting time from the empty knapsack to the global optimum 
\begin{align}
     m(0,0;0) \ge    \frac{h_{(0,0;0), (0,1;0)}}{p_{(0,1;0), (0,1;0)^+}}.
\label{instance2-b1} 
\end{align}

Since $L^+_{(0,1;0)} = L_{(0,0;[n/2,n-3])}$ (see Fig. \ref{fig:Knapsack}.(b)), 
 the transition probability $p_{(0,1;0), (0,0;[n/2,n-3])}$ is no more than
 \begin{align}  \label{instance2-b2}
   \left(1-\frac{1}{n}\right)\frac{1}{n}   \binom{n-2}{n/2}  \left(\frac{1}{n}\right)^{n/2} .
\end{align}%equal to 
%\begin{align*}%
%  \left(1-\frac{1}{n}\right)\frac{1}{n}   \sum^{n-3}_{i=n/2}\binom{n-2}{i} \left(\frac{1}{n}\right)^{i} \left(1-\frac{1}{n}\right)^{n-2-i}.
%\end{align*}
%It is the same as \eqref{instance2-a3}.
Then, the mean hitting time 
\begin{align} 
    m(0,0;0)\ge        \frac{h_{(0,0;0), (0,1;0)}}{\binom{n-2}{n/2}\left(\frac{1}{n}\right)^{n/2+1}}%\frac{h_{(0,0;0), (0,1;0)}}{\sum^{n-3}_{i=n/2}\binom{n-2}{i} \left(\frac{1}{n}\right)^{i+1} \left(1-\frac{1}{n}\right)^{n-1-i}}.
      \label{instance2-b3}
\end{align}

%\subsubsection{Hitting probability}
Intuitively, the Markov chain follows the path $(0,0;0) \to (0,0;1) \to \cdots \to (0,0;n/2-1)$ with probability $\Omega(1)$ (see Fig. \ref{fig:Knapsack}.(b)). For each vertex on the path, the mutation probability from $(0,0;\ell)$ (where $\ell=0, \ldots, n/2-1$) to $ (0,1;*)$ is $\frac{1}{n}$. After greedy repair, the solution becomes $(0,1;0)$. Thus, the hitting probability $h_{(0,0;0), (0,1;0)}$ is no less than the sum of $\Omega(\frac{1}{n})$ over $\ell=0, \ldots, n/2-1$. Then the hitting probability $h_{(0,0;0), (0,1;0)}=\Omega(1)$. We rigorously prove this observation.

 The hitting probability $ h_{(0,0;0), (0,1;0)}$ is estimated by Theorem \ref{the:DriftTheorem-alt}. By \eqref{equ:LowerCoefficient-alt}, the lower bound coefficient is assigned to 
\begin{align}
%\begin{array}{rl}
&
    c_{(0,0;0), (0,1;0)}\nonumber\\
    &=  r_{(0,0;0), (0,1;0)} +\sum^{n/2-1}_{\ell=1} c_{(0,0;0), (0,0;\ell)} \, r_{(0,0;\ell), (0,1;0)}.
%\end{array}
    \label{instance2-b4}
\end{align} 

The conditional probability $r_{(0,0;\ell), (0,1;0)}$ (where $0\le \ell <n/2$) is calculated as follows. The mutation probability from $(0,0;\ell)$ to $(0,1;*)$ is $(1-\frac{1}{n})\frac{1}{n}$ (where $*$ represents an arbitrary value). After greedy repair, %by removing items with lower values, 
only item 1 remains and the solution becomes $(0,1;0)$. The conditional probability 
$$r_{(0,0;\ell), (0,1;0)} \ge p_{(0,0;\ell), (0,1;0)} =\Omega\left(\frac{1}{n}\right).$$ 

Then the lower bound coefficient
\begin{align}
    c_{(0,0;0), (0,1;0)} =  \Omega\left(\frac{1}{n}\right) +  \Omega\left(\frac{1}{n}\right)\sum^{n/2-1}_{\ell=1} c_{(0,0;0), (0,0;\ell)} .
    \label{instance2-b5}
\end{align} 

The lower bound coefficient $c_{(0,0;0), (0,0;\ell)}$ is calculated using Corollary \ref{cor:LowerExplicitExpression}. By \eqref{equ:LowerExplicitExpression}, it is assigned to 
\begin{align}
%\begin{array}{rl}
    & c_{(0,0;0), (0,0;\ell)} \nonumber\\%[1mm]
    &= \prod^{\ell-1}_{j=0} {r_{(0,0;j) ,  (0,0;(j, \ell])}} \nonumber\\%[1mm]
   &= \prod^{\ell-1}_{j=0} \frac{1}{1+\frac{p_{(0,0;j), (0,0;[\ell+1,n-3])} + p_{(0,0;j), (0,1;0)}}{p_{(0,0;j), (0,0;(j, \ell])}}}.
%\end{array}
\label{instance2-b6}
\end{align}  
The transition probabilities  
\begin{align*}%\label{instance2-b7}
    p_{(0,0;j), (0, 0; [\ell+1,n-3])} &\le \binom{n-2-j}{\ell+1-j} \left(\frac{1}{n}\right)^{\ell+1-j},\\
     p_{(0, 0;j), (0, 1; 0)}  & \le 
     \frac{1}{n} ,%\label{instance2-b8}
     \\
         p_{(0, 0;j), (0,0;(j,\ell])} &\ge  \binom{n-2-j}{1} \frac{1}{n} \left(1-\frac{1}{n}\right)^{n-1}   . 
%\label{instance2-b9}
\end{align*}
Substituting them into \eqref{instance2-b6}, we get
\begin{align*} 
c_{(0,0;0), (0,0;\ell)} &\ge \prod^{\ell}_{j=1} \frac{1}{1+ \frac{e}{(\ell+1-j)!} + \frac{2e}{n-2-j} } =\Omega(1).
%\label{instance2-a7}
\end{align*}
We omit the proof of $\Omega(1)$ in the product, which one can refer to \cite{he2023fast} for details.  
%Substituting \eqref{instance2-a7} to \eqref{instance2-b5}, 
Then we get
\begin{align*}
    c_{(0,0;0), (0,1;0)} =  \Omega\left(\frac{1}{n}\right) + \Omega\left(\frac{1}{n}\right)\sum^{n/2-1}_{\ell=1} \Omega(1) =\Omega(1).
    %\label{instance2-b10}
\end{align*} 


Thus, the mean hitting time 
\begin{align} 
         m(0,0;0) \ge  \frac{\Omega(1) }{\binom{n-2}{n/2}\left(\frac{1}{n}\right)^{n/2+1}}.
      \label{instance2-b11}
\end{align}

By comparing \eqref{instance2-a5} and \eqref{instance2-b11}, we observe that the mean hitting time of the (1+1) EA using greedy repair is $\Omega({n})$ of that of the (1+1) EA using feasibility rules. For Instance KP2, greedy repair is worse than feasibility rules.





