\subsection{Instance KP3}
\subsubsection{The (1+1) EA Using Feasibility Rules}   
According to the lower bound \eqref{equ:LinearLowerBound2} in Theorem \ref{the:TimeBounds}, the mean hitting time from the empty knapsack to the global optimum 
\begin{align}
    m(0,0;0) \ge   \sum^{n-2}_{\ell=0} \frac{h_{(0,0;0), (0,0;\ell)}}{p_{(0,0;\ell), (0,0;\ell)^+}}
\label{instance3-a1} . 
\end{align} 

The transition probabilities in \eqref{instance3-a1} are estimated as follows. For $\ell=0, \ldots, n-3$, since $L^+_{(0,0;\ell)} \supset L_{(0,0;\ell+1)}$ (see Fig. \ref{fig:Knapsack}.(c)), the transition probability  
\begin{align*}
%\label{instance2-a2}
p_{(0,0;\ell), (0,0;\ell)^+} \ge p_{(0,0;\ell),  (0,0;\ell+1)} \ge  \frac{n-2-\ell}{n} \left(1-\frac{1}{n}\right)^{n-1}. 
\end{align*}

Since $L^+_{(0,0;n-2)} = L_{(1,0;0)}$,
 the transition probability  
\begin{align*}%\label{instance2-a3} 
   p_{(0,0;n-2), (1,0;0)}= \left(1-\frac{1}{n}\right)   \left(\frac{1}{n}\right)^{n-1}.
\end{align*}

Thus, the mean hitting time  $m(0,0;0)$ is lower-bounded by
\begin{align} 
\sum^{n-3}_{\ell=0} h_{(0,0;0), (0,0;\ell)}  \frac{e n}{n-2-\ell}  +  h_{(0,0;0), (0,0;n-2)} \Omega(n^{n-1}).
      \label{instance3-a4}
\end{align}

%\subsubsection{Hitting probability} 

We prove that the hitting probability $h_{(0,0;0), (0,0;\ell)}$ is a positive constant using Corollary \ref{cor:LowerExplicitExpression}. By \eqref{equ:LowerExplicitExpression},   we get
\begin{align*}
%\begin{array}{rl}
    & h_{(0,0;0), (0,0;\ell)} \nonumber\\%[1mm]
    &\ge \prod^{\ell-1}_{j=0} {r_{(0,0;j) ,  (0,0;(j, \ell])}} \nonumber\\%[1mm]
   &\ge  \prod^{\ell-1}_{j=0} \frac{1}{1+\frac{p_{(0,0;j), (0,0;[\ell+1,n-2])} + p_{(0,0;j), (0,1;[0,1])}+p_{(0,0,j),(1,0;0)}}{p_{(0,0;j), (0,0;(j, \ell])}}}.
%\end{array}
%\label{instance3-b6}
\end{align*}  
The transition probabilities 
\begin{align*}%\label{instance2-b7}
    p_{(0,0;j), (0, 0; [\ell+1,n-3])} &\le \binom{n-2-j}{\ell+1-j} \left(\frac{1}{n}\right)^{\ell+1-j},\\
    p_{(0,0;j), (0,1;[0,1])}&\le \frac{1}{n}\binom{j}{j-1} \left(\frac{1}{n}\right)^{j-1}+  \left(\frac{1}{n}\right)^{j+1},\\
     p_{(0, 0;j), (1, 0; 0)} &\le  
     \left(\frac{1}{n}\right)^{1+j},%\label{instance2-b8}
     \\
         p_{(0, 0;j), (0,0;(j,\ell])} &\ge  \binom{n-2-j}{1} \frac{1}{n} \left(1-\frac{1}{n}\right)^{n-1}   . 
%\label{instance2-b9}
\end{align*}
%Substituting them into \eqref{instance2-b6}, 
Then we get
\begin{align*}
&h_{(0,0;0), (0,0;\ell)} \\
&\ge \prod^{\ell}_{j=1} \frac{1}{1+ \frac{e}{(\ell+1-j)!}+\frac{ej}{n^j(n-2-j)} + \frac{2e}{n^j(n-2-j)}} \\
&=\Omega(1).
%\label{instance2-a7}
\end{align*}
We omit the proof of $\Omega(1)$ in the product, which one can refer to \cite{he2023fast} for details.    
By substituting the above estimation into \eqref{instance3-a4}, we get the mean hitting time as follows:
\begin{align}
m(0,0;0) = \Omega(n \ln n) + \Omega(n^{n-1})
\label{instance3-a5}.
\end{align}
