\section{Supplementary Material}
\subsection{Necessary and Sufficient Drift Conditions for Type-$c$ and Type-$c_\ell$ Time Bounds}  
In this section, we demonstrate that Type-\(c\) and Type-\(c_\ell\) time bounds can be reformulated in terms of necessary and sufficient drift conditions.

Given a fitness level partition $(S_0,\ldots,S_K)$, and a level  $ S_\ell$ (where $1 \le \ell \le K$),  we use a {drift function} $c(X_k, S_\ell)$ to approximate the hitting probability $c(X_k, S_\ell)$ from $X_k \in S_k$ to $S_\ell$. It is given as follows.  
\begin{equation}
\label{equ:DriftFunction}
    c(X_k, S_\ell) =\left\{
    \begin{array}{ll}
         0 & \mbox{if }    \ell>k,\\
          1    &  \mbox{if }   \ell=k,\\
           1&  \mbox{if }   \ell < k,
    \end{array}
    \right.
\end{equation}   When the coefficient $c_{k,\ell}=c$, the Type-$c_{k,\ell}$ bound  degenerates into the Type-$c$ bound. 



\begin{corollary}[Type-$c$ lower bound] 
\label{cor:LowerBound-c} 
Let the coefficient $c_{k,\ell}=c$ in the drift function (\ref{equ:DriftFunction}).  Then  for any $\ell< k $ and $X_k \in S_k$, the drift 
$    {\Delta} c(X_k, S_\ell)  \le 0$   is equivalent to 
\begin{equation} 
\label{equ:LowerCoeff-c} 
c \le \min_{k >\ell} \min_{\ell \ge 1} \; \min_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
\end{equation}   
\end{corollary} 

\begin{IEEEproof} It is sufficient to analyze the case $ p(X_k, S_{[0,\ell]})>0$.  
From the drift condition, we have
\begin{align*}
    \begin{array}{rl}
         & {\Delta} c(X_k, S_\ell)  \le 0. \\
         \Leftrightarrow & c \le  r(X_k, S_\ell) + \sum^{k-1}_{j=\ell+1}r(X_{k}, S_j)    c.\\
        \Leftrightarrow &c   \le \frac{r(X_k, S_\ell)}{r(X_k, S_{[0,\ell]}} = \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
    \end{array}
\end{align*} 
Then we obtained the desired conclusion. 
\end{IEEEproof}

Using a similar proof, we can prove the following three corollaries.

\begin{corollary}[Type-$c$ upper bound] 
\label{cor:UpperBound-c} 
Let the coefficient $c_{k,\ell}=c$ in the drift function (\ref{equ:DriftFunction}). Then  for any $k >\ell$ and $X_k \in S_k$, the drift 
$    {\Delta} c(X_k, S_\ell)  \ge 0$  is equivalent to 
\begin{equation} 
\label{equ:UpperCoeff-c} 
c \ge \max_{k>\ell}\; \max_{\ell \ge 1} \; \max_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
\end{equation}   
\end{corollary}   


As shown in \cite{he2023drift}, the above linear bound coefficient $c$ is the same as  Sudholt's the viscosity in \cite{sudholt2012new}, but is expressed differently.  The above analysis means that $c$ is a lower bound on the hitting probability.

%In Corollary \ref{cor:LowerExplicitExpression2},  let the path $P{[\ell,k]}= {[\ell, k]}$ and the coefficient $c_{k,\ell}=c_\ell$ for all $k >\ell$.  Then Corollary \ref{cor:LowerExplicitExpression2} degenerates to the Type-$c_{ \ell}$ lower bound. 
When the coefficient $c_{k,\ell}=c_\ell$, the Type-$c_{k,\ell}$ bound   degenerates into the Type-$c_\ell$ bound. 

\begin{corollary}  [Type-$c_{ \ell}$ lower bound] 
\label{cor:LowerBound-cl} 
Let the coefficient $c_{k,\ell}=c_\ell$ in the drift function (\ref{equ:DriftFunction}). Then  for any $k >\ell$ and $X_k \in S_k$, the drift 
$    {\Delta} c(X_k, S_\ell)  \le 0$  is equivalent to  
\begin{equation} 
\label{equ:LowerCoeff-cl} 
    c_{\ell} \le \min_{k >\ell}  \;   \min_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
\end{equation}    
\end{corollary}    

\begin{corollary}  [Type-$c_{ \ell}$ upper bound] 
\label{cor:UpperBound-cl} 
Let the coefficient $c_{k,\ell}=c_\ell$ in the drift function (\ref{equ:DriftFunction}). Then  for any $k >\ell$ and $X_k \in S_k$, the drift 
${\Delta} c(X_k, S_\ell)  \ge 0$  is equivalent to 
\begin{equation} 
\label{equ:UpperCoeff-cl} 
    c_{\ell} \ge \max_{k >\ell}  \;   \max_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})}.
\end{equation}    
\end{corollary}   


Doerr and K\"otzing~\cite{doerr2024lower} considered random initialization subject to a particular probability distribution \eqref{equ:DK-Condition2}. Adding this condition to Corollary~\ref{cor:LowerBound-cl}, it yields the Type-$c_{ \ell}$ lower bound under random initialization that is identical to \cite[Lemma 10]{doerr2024lower}.

\begin{corollary} 
\label{cor:LowerBound-cl-random} 
If for $\ell \ge 1$, the linear coefficient  $c_{\ell}$ satisfies the two conditions  
\begin{align}
\label{equ:DK-Condition1}
c_\ell &  \le \min_{k >\ell }  \;   \min_{X_k: p(X_k, S_{[0,\ell]})>0} \frac{p(X_k, S_{\ell})}{p(X_k, S_{[0,\ell]})},\\
    \label{equ:DK-Condition2}
c_\ell &\le \frac{\Pr(X^{[0]} \in S_{\ell})}{\Pr(X^{[0]} \in S_{[0,\ell]})}, 
\end{align}  
then the hitting time $$ 
   m(X^{[0]})  \ge \sum^{K}_{\ell=1} \frac{c_{\ell}}{p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}.$$     
\end{corollary}

\begin{IEEEproof}
For any random initialization,  the hitting time  
\begin{align}
\label{equ:Rand1}
    m(X^{[0]}) =& \sum^K_{\ell=1}  \Pr(X^{[0]} \in S_\ell) \times m(X_\ell).
\end{align}

By Condition \eqref{equ:DK-Condition1} and Corollary \ref{cor:LowerBound-cl}, the hitting time
\begin{align}
\label{equ:Rand2}
   m(X_\ell) \ge   \frac{1 }{p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}  +  \sum^{\ell-1}_{j=1} \frac{  c_j}{p_{{\scriptscriptstyle\max}}(X_{j},S_{[0,j-1]})}. 
\end{align}
Inserting \eqref{equ:Rand2} to \eqref{equ:Rand1} and reindexing the sum, we get
\begin{align*}
m(X^{[0]}) & \ge \sum^K_{\ell=1} \frac{\Pr(X^{[0]} \in S_\ell)+ c_\ell \sum^{K}_{j=\ell+1}\Pr(X^{[0]} \in S_\ell)}{p_{{\scriptscriptstyle\max}}(X_{\ell},S_{[0,\ell-1]})}.
\end{align*}

Condition \eqref{equ:DK-Condition2} can be rewritten as 
\begin{align}
\label{equ:DK-Condition2-plus}
    c_\ell \le \Pr(X^{[0]} \in S_\ell)+ c_\ell \sum^{K}_{j=\ell+1}\Pr(X^{[0]} \in S_\ell). 
\end{align}

Using \eqref{equ:DK-Condition2-plus}, we get
\begin{align*}
m(X^{[0]}) & \ge   \sum^K_{\ell=1} \frac{ c_\ell}{p_{{\scriptscriptstyle\max}}(X_\ell,S_{[0,\ell-1]})},
\end{align*}
This is the desired result.
\end{IEEEproof}


\paragraph*{Examples (LeadingOnes, OneMax, and Long $k$-path)} 
Consider the (1+1) EA to maximize OneMax, LeadingOnes, and Long $k$-path \cite{sudholt2012new}. The results by Sudholt \cite{sudholt2012new} can be derived by Corollary \ref{cor:LowerBound-c}. The results by Doerr and K\"otzing~\cite{doerr2024lower} can be derived by Corollary \ref{cor:LowerBound-cl-random}.





%Therefore, the Type-$c_{k,\ell}$ upper bound can be used to derive the same results as before. 

The above analysis shows that the drift analysis of hitting probability can be used to derive previous results \cite{sudholt2012new,doerr2024lower}. Therefore, its applicability is at least as broad as previous linear bounds.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Advantage of the Type-$c_{k,\ell}$ Bound Over the Type-$c_\ell$ Bound}
In most cases, the Type-$c_{k,\ell}$ bound is tighter than the Type-$c$ and Type-$c_{\ell}$ bounds. Let us prove this claim. 
 Since a linear bound is determined by a set of coefficients, the comparison of two linear bounds is based on Pareto dominance.

\begin{definition} Given a fitness level partition $(S_0, \cdots, S_k)$ and an EA, a linear lower bound with coefficients $\{c_{k,\ell} \}$ (where $1 \le \ell < k\le K$)  is considered tighter than another bound with coefficients $\{c'_{k,\ell} \}$  if $c_{k,\ell}  \ge c'_{k,\ell} $ for all $({k,\ell})$, and $c_{k,\ell} > c'_{k,\ell}$ for some $({k,\ell})$. Similarly, a linear upper bound with coefficients $\{c_{k,\ell} \}$  is considered tighter than another bound with coefficients $\{c'_{k,\ell} \}$ if $c_{k,\ell}  \le c'_{k,\ell} $ for all $({k,\ell})$, and $c_{k,\ell} < c'_{k,\ell}$ for some $({k,\ell})$.    
\end{definition} 


The theorem below states that the Type-$c_{k,\ell}$ lower bound is tighter than the Type-$c_{\ell}$ lower bound.  


\begin{theorem}
\label{the:BestLowerBoundCoeff-cl} Given an elitist and convergent and EA, and  a fitness level partition $(S_0, \cdots, S_K)$, 
For any $1 \le \ell < k$, let $c^*_\ell$ denote the best coefficient $c_{\ell}$ in the Type-$c_\ell$ lower bound such that 
\begin{equation}
\label{equ:BestLowerCoeff-cl}
    c^*_{\ell} = \min_{\ell < i \le k} \; \min_{X_i: p(X_i, S_{[0,\ell]}) > 0} \frac{p(X_i, S_{\ell})}{p(X_i, S_{[0,\ell]})}.
\end{equation}
Let $c^*_{k,\ell}$ denote the coefficient  in the Type-$c_{k,\ell}$ lower bound such that
\begin{align}
\label{equ:BestLowerCoefficient}
    c^*_{k,\ell} = \min_{X_k \in S_k} \left(r(X_{k}, S_\ell) + \sum_{j=\ell+1}^{k-1} r(X_{k}, S_j) \, c^*_{j, \ell}\right).
\end{align}
Then the coefficients $c^*_{k,\ell}$ Pareto dominate $c^*_\ell$, meaning:
\begin{enumerate}
    \item For any $i = \ell + 1, \ldots, k$, $c^*_{i,\ell} \ge c^*_{\ell}$.
    \item If for some $i$,
    \begin{align}
    \label{equ:LowerCoefficient31}
       \min_{X_i: p(X_i, S_{[0,\ell]}) > 0} \frac{p(X_i, S_{\ell})}{p(X_i, S_{[0,\ell]})} > c^*_\ell,
    \end{align}
    then $c^*_{i,\ell} > c^*_{\ell}$.
\end{enumerate} 
\end{theorem}


\begin{IEEEproof}
According to the definition of conditional probability $r(X_k, S_{\ell})$, we get
    \begin{align}\label{equ:LowerCoefficient32}
       \frac{p(X_i, S_{\ell})}{p(X_i, S_{[0,\ell]})} =  \frac{r(X_i, S_{\ell})}{r(X_i, S_{[0,\ell]})}.
    \end{align}
Inserting the above equality to \eqref{equ:BestLowerCoeff-cl}, we get
\begin{align*} 
 c^*_{\ell} = \min_{\ell < i \le k}  \;   \min_{X_i: p(X_i, S_{[0,\ell]})>0}   \frac{r(X_i, S_{\ell})}{r(X_i, S_{[0,\ell]})},  
\end{align*}  
and then for an $i$, 
\begin{align}
\label{equ:LowerCoefficient33}
  r(X_i, S_{\ell}) \ge    r(X_k, S_{[0,\ell]})\; c^*_{\ell}.
\end{align}
Inequality \eqref{equ:LowerCoefficient33} is strict if \eqref{equ:LowerCoefficient31} is true. 
Utilizing Inequality \eqref{equ:LowerCoefficient33}, we can employ induction to demonstrate that $c^*_{k,\ell}$ Pareto dominates $c^*_\ell$. 

Since the conditional probability $r(X_{\ell+1}, S_{[0,\ell]})  =1$, it is trivial to get for $j=\ell+1$,
\begin{align} 
    c^*_{\ell+1,\ell} = r(X_{\ell+1}, S_\ell)=\frac{r(X_{\ell+1}, S_{\ell})}{r(X_{\ell+1}, S_{[0,\ell]})} \ge c^*_{\ell}. 
\end{align} 
The inequality is strict if \eqref{equ:LowerCoefficient31} is true.

Assume that for $j =\ell+1, \cdots, i-1$, $    c^*_{j,\ell}   \ge c^*_{\ell}$. 
Inserting this to \eqref{equ:BestLowerCoefficient}, we have
\begin{align} 
\label{equ:LowerCoefficient34}
    c^*_{i,\ell} \ge  r(X_i, S_\ell)+   \sum^{i-1}_{j=\ell+1} r(X_{i}, S_j)    c^*_{ \ell} .
\end{align}  
Combining \eqref{equ:LowerCoefficient33} with the above inequality, we get
\begin{align} 
\label{equ:LowerCoefficient35}
    c^*_{i,\ell} \ge  r(X_i, S_{[0,\ell]}) \; c^*_{\ell}  +  r(X_i, S_{[\ell+1,i-1]})    c^*_{ \ell} = c^*_\ell.
\end{align}
Inequality \eqref{equ:LowerCoefficient34} is strict if \eqref{equ:LowerCoefficient31} is true. By induction, we complete the proof.  
\end{IEEEproof}


\paragraph*{Examples (OneMax)} 
Even for the (1+1) EA on OneMax, the Type-$c_{k,\ell}$ lower bound is tighter than the Type-$c_{\ell}$ lower bound because the transition probability from level $S_k$ to $S_\ell$ is not equal to the transition probability from $S_i$ to $S_\ell$ if $k \neq i$. 

\paragraph*{Examples (TwoMax1)} 
As proved in \cite{he2023drift}, for the (1+1) EA on TwoMax1, the Type-$c_{k,\ell}$ lower bound is $\Omega(n \ln n)$, but the Type-$c_{\ell}$ is only $O(1)$.  Due to the existence of shortcuts on the multimodal fitness landscapes, Type-$c$ and Type-$c_\ell$ lower bounds are not tight \cite{he2023drift}.  


Similarly, the theorem below states that the Type-$c_{k,\ell}$ upper bound is tighter than the Type-$c_{\ell}$ upper bound.


\begin{theorem}
\label{the:BestUpperBoundCoeff-cl} Given an elitist and convergent and EA, and  a fitness level partition $(S_0, \cdots, S_K)$, 
For any $1 \le \ell < k$, let $c^*_\ell$ denote the best coefficient $c_{\ell}$ in the Type-$c_\ell$ upper bound such that 
\begin{equation}
\label{equ:BestUpperCoeff-cl}
    c^*_{\ell} = \max_{\ell < i \le k} \; \max_{X_i: p(X_i, S_{[0,\ell]}) > 0} \frac{p(X_i, S_{\ell})}{p(X_i, S_{[0,\ell]})}.
\end{equation}
Let $c^*_{k,\ell}$ denote the coefficient  in the Type-$c_{k,\ell}$ upper bound such that
\begin{align}
\label{equ:BestupperCoefficient}
    c^*_{k,\ell} = \max_{X_k \in S_k} \left(r(X_{k}, S_\ell) + \sum_{j=\ell+1}^{k-1} r(X_{k}, S_j) \, c^*_{j, \ell}\right).
\end{align}
Then the coefficients $c^*_{k,\ell}$ Pareto dominate $c^*_\ell$, meaning:
\begin{enumerate}
    \item For any $i = \ell + 1, \ldots, k$, $c^*_{i,\ell} \le c^*_{\ell}$.
    \item If for some $i$,
    \begin{align}
    \label{equ:upperrCoefficient31}
       \max_{X_i: p(X_i, S_{[0,\ell]}) > 0} \frac{p(X_i, S_{\ell})}{p(X_i, S_{[0,\ell]})} < c^*_\ell,
    \end{align}
    then $c^*_{i,\ell} <c^*_{\ell}$.
\end{enumerate} 
\end{theorem}


