%	\begin{equation}
%		\begin{aligned}
%			\ln P(\hat{\mathbf{z}}|\mathbf{x}) &= \ln\left( \frac{1}{(2\pi)^{\frac{3L}{2}} |\mathbf{\Sigma}_e|^{\frac{1}{2}}} \exp\left(-\frac{1}{2} (\hat{\mathbf{z}} - f(\mathbf{x}, E))^T \mathbf{\Sigma}_e^{-1} (\hat{\mathbf{z}} - f(\mathbf{x}, E))\right)\right) \\
%			&= -\frac{3L}{2}\ln(2\pi) - \frac{1}{2} \ln|\mathbf{\Sigma}_e| - \frac{1}{2} (\hat{\mathbf{z}} - f(\mathbf{x}, E))^T \mathbf{\Sigma}_e^{-1} (\hat{\mathbf{z}} - f(\mathbf{x}, E)).
