			\begin{aligned}
				\ln P(\hat{\mathbf{z}}|\mathbf{x})=&\sum_{l=1}^{L} \ln P(\mathbf{z}_l|\mathbf{x})=\sum_{l=1}^{L} \ln P(\phi_l, \theta_l, \tau_l|\mathbf{x})\\
				=&\sum_{l=1}^{L}\ln \left(\int\int P(\theta_{l_T}, \tau_{l_T}|\mathbf{q}=\mathbf{x}) P(\theta_{l_R},\tau_{l_R}|\mathbf{q}=\mathbf{x})\delta(\tau_l-(\tau_{l_T}+\tau_{l_R})) d\tau_{l_T}d\tau_{l_R}\right)\\
				=&\sum_{l=1}^{L}\ln \left(\int\int\mathcal{N}(\theta_{l_T}; \mu_{\theta,{l_T}}(\mathbf{x}), \sigma_{\theta,{l_T}}^2(\mathbf{x}))\mathcal{N}(\tau_{l_T}; \mu_{\tau,{l_T}}(\mathbf{x}), \sigma_{\tau,{l_T}}^2(\mathbf{x}))
				\mathcal{N}(\theta_{l_R}; \mu_{\theta,{l_R}}(\mathbf{x}), \sigma_{\theta,{l_R}}^2(\mathbf{x}))\right.\\
				&\times\mathcal{N}(\tau_{l_R}; \mu_{\tau,{l_R}}(\mathbf{x}), \sigma_{\tau,{l_R}}^2(\mathbf{x}))\delta(\tau_l-(\tau_{l_T}+\tau_{l_R})) d\tau_{l_T}d\tau_{l_R}\Big)\\
				=&\sum_{l=1}^{L}\ln \left(\mathcal{N}(\phi_{l}; \mu_{\theta,{l_T}}(\mathbf{x}), \sigma_{\theta,{l_T}}^2(\mathbf{x}))
				\mathcal{N}(\theta_{l}; \mu_{\theta,{l_R}}(\mathbf{x}), \sigma_{\theta,{l_R}}^2(\mathbf{x}))\mathcal{N}(\tau_{l}; \mu_{\tau,{l_T}}(\mathbf{x})+\mu_{\tau,{l_R}}(\mathbf{x}), \sigma_{\tau,{l_T}}^2(\mathbf{x})+\sigma_{\tau,{l_R}}^2(\mathbf{x}))\right).
			\end{aligned}
