\section{Convergence Analysis  and Main Results}
In this section, we analyze the total variation error between the target distribution $\varrho_{t}$ and the distribution $\dvarrho_{t}$ of the numerical solution $\dY_t$, produced by aforementioned standard Runge–Kutta schemes in \eqref{eq:RK-update}. The goal is to illustrate the core analysis ideas. Extension to exponential Runge-Kutta schemes and to forward processes with general variance schedules is present in \cref{s:GeneralProcess}. Although the overall analysis strategy remains similar, the extension requires additional estimates involving the variance schedules.
%
We begin by stating our assumptions, followed by the main result. 

\begin{assumption}\label{assumption:secon-moment}
	The data distribution $\muast$ is a probability distribution that is positive and compactly supported on a compact set $K_{\ast}$ in $\bR^d$, and we also define $D \coloneq 1+\max_{x \in K_{\ast}} \|x\|_{\infty} $.
\end{assumption}


\begin{assumption}\label{a:score-estimate}
Recall the discrete-time sequence $\bT$ defined in \eqref{e:defbT} and consider the integration domain $[0, T - \tau]$ for a small $\tau > 0$.
For the backward process, the time domain is discretized into $M$ steps:
\[
0 = t_0 < t_1 < \dots < t_M = T - \tau.
\]
with step sizes $H_i = t_{i+1} - t_i$ for every $0 \leq i \leq  M - 1$. We assume  
there exists a small parameter $\varepsilon_{\mathrm{score}} > 0$ such that the weighted $L^2$ score matching error satisfies
 \begin{align*}
		 \sum_{i=0} ^{M-1}H_i\cdot \sum_{t\in [t_i,t_{i+1}]\cap \bT}  \sigma_{T-t}^2 \int_{\bR^d}   \left\| s_{{t}}(x) -  \nabla \log\varrho_{{t}}(x)\right\|_2^2 \varrho_{{t}}(x) \rd x\leq \varepsilon_{\rm score} ^2 .
	\end{align*}
\end{assumption}
\begin{remark}
We remark that if each time step contains a bounded number of points from $\bT$, especially if $\max_{0\leq i\leq M-1}H_i/\Delta t=\cO(1)$. Then our \Cref{a:score-estimate} is equivalent (up to a constant factor) to bounding the average $L^2$ score matching error
\begin{align*}
		 \sum_{t\in [0,T-\tau]\cap \bT} \Delta t\cdot \sigma_{T-t}^2 \int_{\bR^d}   \left\| s_{{t}}(x) -  \nabla \log\varrho_{{t}}(x)\right\|_2^2 \varrho_{{t}}(x) \rd x\leq \varepsilon_{\rm score} ^2 .
	\end{align*}
\end{remark}

Although for standard Runge-Kutta schemes \eqref{eq:RK-update} and \eqref{eq:RK-update-k} (as in \Cref{tab:butcher-specific}), the coefficients $[a_{jk}]$ and $[b_j]$ do not depend on the step size $H_i$, in the general case they may vary with $H_i$. This is particularly true for exponential Runge-Kutta schemes; see \Cref{s:GeneralProcess} for details.
We therefore allow the coefficients $[a_{jk}(H_i)]$ and $[b_j(H_i)]$ to depend on the step size $H_i$. The following assumption ensures that these coefficient functions, along with their derivatives, are appropriately bounded.

\begin{assumption}\label{a:bounds on RK}
For the Runge-Kutta schemes \eqref{eq:RK-update} and \eqref{eq:RK-update-k}, we assume there exist constants $A_p, B_p \geq 1$ such that the coefficient functions $a_{jk}(h)$ and $b_j(h)$, along with their derivatives up to order $p+1$, satisfy the following bounds for all time steps $t_i$ and for all $h \in [0,H_i]$:
\begin{align}\label{e:RKbound}
    \max_{1 \leq j,k \leq s} \max_{0 \leq l \leq p+1} \tau^l \left| \partial_h^l a_{jk}(h) \right| \leq A_p, \quad 
    \max_{1 \leq j \leq s} \max_{0 \leq l \leq p+1} \tau^l \left| \partial_h^l b_j(h) \right| \leq B_p.
\end{align}
For commonly used Runge-Kutta schemes listed in \Cref{tab:butcher-specific}, \eqref{e:RKbound} holds trivially because the coefficients $[a_{jk}]$ and $[b_j]$ are constants.
Moreover, when applying the Runge-Kutta scheme, the time domain is discretized into $M$ steps. We assume that all time nodes $t_i$, as well as all intermediate evaluation points $t_i +c_jH_i$ (as in \eqref{eq:RK-update-k}), lie within the discrete time sequence $\bT$.
\end{assumption}





\begin{assumption}\label{a:score-derivative}
We assume that the approximate score $s_t(x)$ is $C^2$ with respect to $x$. More precisely, there is a positive constant $\widetilde K$, such that for any $t \in [0,T-\tau]\cap \bT$, 
    \begin{align*}
        \sup_{x \in \mathbb{R}^d} \max_{1\leq l, j \leq d} |\partial_{l} s_t ^{(j)}(x)| \leq \widetilde K \tau ^{-2}, \quad \sup_{x \in \mathbb{R}^d} \max_{1\leq l,k, j \leq d} |\partial^2 _{lk} s_t ^{(j)}(x)| \leq \widetilde K  \tau ^{-3} .
    \end{align*}
Here, we write $s_t(x) = (s_t ^{(1)}(x),s_t ^{(2)}(x),\ldots,s_t ^{(d)}(x))$, and we denote $\partial_l \coloneq \partial_{x_l}, \partial^2 _{lk} \coloneq \partial^2 _{x_l x_k}$.
We also assume that for any $t \in [0,T-\tau]\cap \bT$, there is a constant $\widetilde W$ such that  $\|s_t(x)\|_2 \leq \tau^{-1}\widetilde W(\sqrt{d}   +\|x\|_2) $.
\end{assumption}


\begin{remark}
    We remark that the assumption on $\| s_t(x)\|_2$ is of correct order, as we prove that, according to \Cref{p:ABCD}, $\|\nabla \log\varrho_{{t}}(x)\|_2 \leq 2 \tau^{-1} (\sqrt{d} D + \|x\|_2)$. Also, similar to~\cite{huang2024convergence}, we can replace the point-wise second derivative assumption on $s_t$ with the following:
        \begin{align*}
            \max_{1\leq l, k, j \leq d} \int_{\mathbb{R}^d}|\partial^2 _{lk} s_t ^{(j)}(x)| \varrho_t(x) \de x \leq \widetilde K \tau ^{-3}.
        \end{align*}
\end{remark}

Our main result is stated below, with the detailed proof deferred to \cref{Section: Discrete ODE}.
\begin{theorem}\label{theorem: main L^1 theorem}
    Let $\dvarrho_{t}$ be the distribution of the numerical solution $\dY_t$, produced by the standard Runge–Kutta schemes in \eqref{eq:RK-update} and \eqref{eq:RK-update-k}.
    Adopt \Cref{assumption:secon-moment}, \Cref{a:score-estimate},  \Cref{a:bounds on RK}, and \Cref{a:score-derivative}. There exist constants $C_{\rm score} >0$, $C_{\rm RK}>0$, $\Delta_{\rm disc} \in (0,1)$, depending on $A_p, B_p, s, p, D,\widetilde K, \widetilde W$,  and $\gamma_1,\gamma_2$ depending on $p$, such that if we let $H_{\rm max} \coloneq \max_{0\leq i \leq M -1} (t_{i+1}-t_i) $ and take $H_{\rm max}\leq (d \log (2d))^{-1} \cdot \tau^{3} \cdot \Delta_{\rm disc}$, then
    \begin{align}\label{e: main L^1 error}
        \begin{split}
        \TV(\varrho_{T-\tau}, \dvarrho_{T-\tau}) &\leq \TV(\varrho_{0}, \dvarrho_{0}) + C_{\rm score}  \tau^{-2}     T^{\frac{3}{4}}      d^{\frac{7}{4}}   \cdot \varepsilon_{\rm score} ^{\frac{1}{2}}   
         +  C_{\rm RK}  T H_{\mathrm{max}} ^p d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}.
        \end{split}
    \end{align}
If we take the initialization to be the standard normal distribution $ \dvarrho_0=\cN(0, \id_d)$, then $\TV(\varrho_0, \dvarrho_0)\leq C_u e^{-T} \sqrt d D$, which is exponentially small in $T$.
\end{theorem}

\begin{remark}
The total variation bound in \cref{theorem: main L^1 theorem} simplifies to $\mathcal{O}( d^{7/4}\varepsilon_{\rm score}^{1/2} + d\cdot(dH_{\max})^p)$, where we treat quantities such as the total time $T$, the target distribution diameter  parameter $D$, and the stopping time parameter $\tau$ as constants. In the absence of score error ($\varepsilon_{\rm score}$), this bound further simplifies as $\mathcal{O}(d\cdot(dH_{\max})^p)$, which implies an iteration complexity of $\cO(d^{1+1/p} \varepsilon^{-1/p})$ to achieve a total variation accuracy of $\varepsilon$.



\end{remark}



\begin{remark}
  Although our bound in \eqref{e: main L^1 error} is established between the numerical solution $\dvarrho_{T-\tau}$ and reference density $\varrho_{T-\tau}$ at an earlier time, the Wasserstein 2-distance between $\varrho_{T-\tau}$ and the target distribution $\muast$, $W_2(\muast,\varrho_{T-\tau})$, tends to $0$ of order $\tau d$ as $\tau \to 0^+$ (see Remark 3.7 in \cite{huang2024convergence}). It is also standard that $W_2(\varrho_{T-\tau}, \dvarrho_{T-\tau})$ can be quantitatively estimated by $\TV(\varrho_{T-\tau}, \dvarrho_{T-\tau})$. We can use, for example, Proposition 7.10 in \cite{MR1964483} together with the facts like \Cref{lemma: qt close to Gaussian} and \Cref{lemma: moments of L^2 and infinity norms} to quantitatively estimate $W_2(\varrho_{T-\tau}, \dvarrho_{T-\tau})$ by $\TV(\varrho_{T-\tau}, \dvarrho_{T-\tau})$. Hence, we can also obtain a quantitative estimate for $W_2(\muast, \dvarrho_{T-\tau})$ by \Cref{theorem: main L^1 theorem}.
\end{remark}



\begin{remark}\label{rem:score_error}
The total variation error bound in \eqref{e: main L^1 error} consists of three components: the error from the initial condition, the score matching error, and the temporal discretization error. For the score matching error term, as discussed in Remark 3.6 in our previous work in \cite{huang2024convergence}, if we make assumptions on higher order derivatives of $s_t(x)$ like \Cref{a:score-derivative}, i.e., $s_t(x)$ is $C^k$ with controlled norms for its derivatives of order $\leq k$ for some $k \geq 2$, we can replace the exponent $\frac{1}{2}$ of $\varepsilon_{\rm score}$ with $1-\frac{1}{k}$ in \eqref{e: main L^1 error}. 
In our numerical experiments exploring the sharpness of this bound, we find that the total variation error scales linearly with $\varepsilon_{\rm score}$ (See \Cref{sec:num}), with a potentially more  favorable dependence on the dimension $d$ for the Gaussian mixture target density.
\end{remark}


\begin{remark}
    The technical assumption $H_{\rm max}\leq (d \log 2d)^{-1} \cdot \tau^{3} \cdot \Delta_{\rm disc}$ in the statement of \Cref{theorem: main L^1 theorem} is to ensure that the maps in the Runge-Kutta schemes \eqref{eq:RK-update}, when viewed as pushforward maps, are invertible. This invertibility is essential for estimating the distribution of $\dY_{t_{i+1}}$ from the distribution of $\dY_{t_i}$ via the map \eqref{eq:RK-update} reformulated as \eqref{e:phi_h_define}. 
\end{remark}



\begin{remark}
Compared to several previous studies on probability flow ODEs \cite{li2023towards, li2024unified, li2024sharp, li2024accelerating}, which require control over the difference between the derivatives of the true and estimated scores, our result in \Cref{a:score-derivative} only requires the boundedness of the first two derivatives of the estimated score. In \Cref{sec:num}, we numerically validate \Cref{a:score-derivative}, showing that both quantities remain well-bounded in practice, which supports our theoretical assumptions.
\end{remark}



In \Cref{s:GeneralProcess}, we extend \Cref{theorem: main L^1 theorem} to (exponential) Runge–Kutta schemes applied to arbitrary forward processes with general variance schedules. The technical analysis remains similar. For the general case, we can rewrite the (exponential) Runge-Kutta schemes as in \eqref{eq:RK-update-beta-rf} and \eqref{eq:Exp-RK-update-beta-rf}, which mirror the standard Runge–Kutta formulations in \eqref{eq:RK-update}, except that stage evaluations now involve $s_t$ instead of $\sV_t(x) = x + s_t(x)$. Since both $s_t(x)$ and $\sV_t(x) = x + s_t(x)$ satisfy the same technical assumptions required for \Cref{theorem: main L^1 theorem}, this allows us to generalize the result to \Cref{theorem: main L^1 theorem general}.






\section{Results for General Forward Process}
\label{s:GeneralProcess}
\subsection{General Forward Process}
In practical settings \cite{ho2020denoising,song2020score}, the following variance preserving stochastic process is commonly used: 
\begin{align}
\label{eq:OU-time}
	\de X_t = -\frac{1}{2}\beta_t X_t \de t + \sqrt{\beta_t} \de B_t, \qquad X_0 \sim \muast, \qquad 0 \leq t \leq T, 
\end{align}
where $\beta_t:\bR\rightarrow\bR$ is the variance schedule that controls the level of noise injected at each time step.
Similar to the OU process, this process \eqref{eq:OU-time} admits an analytical solution:
\begin{align*}
	X_t \overset{d}{=} \lambda_t X_0 + \sigma_t W, \qquad W \sim \cN(0, \id_d), 
\end{align*}
where  $\lambda_t$ and $\sigma_t$ satisfy
\begin{align*}
\frac{\dd \log \lambda_t}{\dd t} = -\frac{1}{2}\beta_t \qquad \textrm{and} \qquad \frac{\dd \sigma_t^2}{\dd t} - 2\frac{\dd \log \lambda_t}{\dd t } \sigma_t^2 = \beta_t.
\end{align*}
These yield the explicit expressions:
\begin{align}\label{e:general_sigma_t}
\lambda_t = e^{-\frac{1}{2} \int_0^t \beta_s \de s} \qquad \textrm{and} \qquad  \sigma_t  = \sqrt{1 - \lambda_t^2}.
\end{align}
The parameters play a key role in the score matching procedure described in~\cref{s:score_matching}.
A widely adopted choice for $\beta_t$ is the linear variance schedule: $\beta_t = \beta_{\rm min} + \frac{t}{T} (\beta_{\rm max} - \beta_{\rm min})$, where $\beta_{\rm min}$ and $\beta_{\rm max}$ represent the minimum and maximum noise levels. Under this schedule, the decay factor becomes $\lambda_t = e^{-\frac{1}{2}\Bigl(t \beta_{\rm min} + \frac{t^2}{2T}(\beta_{\rm max} - \beta_{\rm min})\Bigr)}$. The OU process \eqref{eq:OU} is a special case with $\beta_t = 2$.




The density $q_t$ of $X_t$ as in \eqref{eq:OU-time} satisfies
\begin{align*}
    \del_t q_t =\frac{\beta_t}{2} \nabla \cdot \left((x+\nabla \log q_t)q_t\right)=\frac{\beta_t}{2}  \nabla \cdot (\qU_t q_t), \quad 0 <  t\leq T,
\end{align*}
with $\qU_t(x) \coloneq x +  \nabla \log q_t(x)$. 
By denoting $\varrho_t  = q_{T - t}$, the time reversal process from time $0$ to $T$, satisfies the following partial differential equation (PDE):
\begin{align}\begin{split}
\label{e:reversep_general}
    \del_t \varrho_t =-\frac{\beta_{T-t}}{2}\nabla \cdot \bigl((x + \nabla \log q_{T - t}) \varrho_t\bigr) = -\frac{\beta_{T-t}}{2} \nabla \cdot (V_t \varrho_t), \quad 0 \leq t < T,
\end{split}\end{align}
with $V_t(x) \coloneq x +  \nabla \log q_{T - t}(x)$.


Then we can reformulate the reverse  PDE \eqref{e:reversep_general} into 
a deterministic dynamics in terms of an ordinary differential equation with velocity field $V_t$:
\begin{align}\label{eq:reverse-ode_general}
	\del_t Y_t = \frac{\beta_{T-t}}{2}\left( Y_t +  \nabla \log q_{T - t} (Y_t) \right) = \frac{\beta_{T-t}}{2} V_t(Y_t), \qquad Y_0 \sim q_T, \qquad 0 \leq t < T.
\end{align}
%known as the probability flow ODE. 
When $\nabla \log q_{T - t} (x)$, is approximated by the learned score function $s_t(x)$, the probability flow ODE \eqref{eq:reverse-ode_general} becomes 
\begin{align}\label{eq:reverse-ode-score_general}
	\del_t \sY_t = \frac{\beta_{T-t}}{2}\left( \sY_t +  s_t(\sY_t)\right) = \frac{\beta_{T-t}}{2} \sV_t(\sY_t), \qquad \sY_0 \sim \svarrho_0, 
\end{align}
where the velocity field becomes $\sV_t(x) \coloneq x + s_t(x)$. 



\subsection{ODE Solver for General Forward Process}\label{s:general}
To solve the differential equation \eqref{eq:reverse-ode-score_general}, one can again apply the standard Runge-Kutta schemes introduced in \cref{s:time_integrator}.
\begin{align}
\label{eq:RK-update-beta}
\dY_{t_{i+1}} = \dY_{t_i} +  H_i \sum_{j=1}^s  b_j  \wt k_j(\dY_{t_i}),
\end{align}
where $ H_i=t_{i+1}-t_i$, and
\begin{equation}
\label{eq:RK-update-beta-k}
\begin{split}
    & \wt k_1(x) =\frac{\beta_{T-t_i - c_1  H_i}}{2} \sV_{t_i +  c_1  H_i}(x),\\
    & \wt k_2(x) = \frac{\beta_{T-t_i -  c_2  H_i}}{2}\sV_{t_i +  c_2  H_i}\bigl(x + ( a_{21} \wt k_1(x)) H_i\bigr),\\
    & \wt k_3(x) = \frac{\beta_{T-t_i - c_3  H_i}}{2}\sV_{t_i + c_3 H_i}\bigl(x + ( a_{31} \wt k_1(x) +  a_{32} \wt k_2(x))  H_i\bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
   & \wt k_s(x) = \frac{\beta_{T-t_i -  c_s  H_i}}{2}\sV_{t_i +  c_s H_i}\bigl(x + ( a_{s1}\wt k_1(x) +  a_{s2} \wt k_2(x) + \cdots +  a_{s,s-1} \wt k_{s-1}(x))  H_i\bigr).
\end{split}
\end{equation}

However, standard Runge-Kutta schemes do not leverage the natural separation between the linear and nonlinear terms in the probability flow ODE~\eqref{eq:reverse-ode-score_general}. Exploiting this structure by integrating the linear term analytically is the central idea behind exponential Runge–Kutta schemes~\cite{cox2002exponential,hochbruck2005explicit,hochbruck2010exponential}, which yields more robust time integrators. This approach has been adopted in recent works~\cite{zhang2022fast, lu2022dpm} for solving probability flow ODEs and has demonstrated improved performance.  In practice, applying exponential Runge–Kutta schemes in this setting requires several important modifications.
First, classical exponential Runge–Kutta schemes~\cite{cox2002exponential,hochbruck2005explicit,hochbruck2010exponential} are typically designed for time-independent linear terms. In our case~\eqref{eq:reverse-ode-score_general}, the linear term is time-dependent due to the variance schedule, necessitating additional adjustments to handle this dependency. 
Second, to mitigate the potential singularity of the score function as $t\to T$, the reparameterization $\rscore_t(x) \coloneq s_t(x)\,\sigma_{T - t}$, used in score matching, is adopted.
The rescaled quantity $\rscore_t$ is typically smoother than $s_t$, especially near the terminal time, making it a more robust target for deriving order conditions.
Finally, all time steps, including intermediate stages,  should lie within the discrete time sequence $\bT$ used in score matching. 

To derive the enhanced exponential Runge-Kutta schemes for solving \eqref{eq:reverse-ode-score_general}, we begin by introducing a time change variable
\begin{align}\label{eq:t-zeta change of variable2}
\zeta(t)= \frac{1}{2}\int_{T-t}^{T} \beta_s \, \rd s ,
\end{align}
and we rewrite \eqref{eq:reverse-ode-score_general} as $
 \del_t \bigl(e^{-\zeta(t)}\sY_t\bigr) = e^{-\zeta(t)} \frac{\beta_{T-t}}{2} s_t(\sY_t).$ 
 This leads to the corresponding integral form for $\sY_{t}$:
\begin{align} 
\label{eq:exp-rk-intg}
     \sY_{t_{i+1}} &= e^{\zeta(t_{i+1}) - \zeta(t_i)}\sY_{t_{i}} + \int_{t_i}^{t_{i+1}} \frac{\beta_{T-t}}{2} e^{\zeta(t_{i+1})-\zeta(t)} s_t(\sY_t) \rd t \nonumber \\
     &= e^{\zeta(t_{i+1}) - \zeta(t_i)}\sY_{t_{i}} - \sigma_{T - t_{i+1}}e^{\alpha_{t_{i+1}}}\int_{t_i}^{t_{i+1}} \frac{\rd}{\rd t} e^{-\alpha_{t}} \rscore_t(\sY_t) \rd t,
\end{align}
where, in the last equation, we introduce the reparameterized score $\rscore_t(x) \coloneq \sigma_{T-t} s_{t}(x)$ and apply the change of variables from \cite{lu2022dpm}, defined by
\begin{equation}
\label{eq:t-alpha change of variable}
    \alpha_{t} = \zeta(t) - \log\sigma_{T-t}, \quad \textrm{satisfying} \quad \frac{\rd \alpha_t}{\rd t} = -\frac{\beta_{T-t}}{2\sigma_{T - t}^2}, 
    \quad \frac{\rd}{\rd t} e^{-\alpha_{t} } = -\frac{\beta_{T-t}}{2\sigma_{T - t}} e^{-\zeta(t)}.
\end{equation} 
The enhanced exponential Runge-Kutta schemes updates from $t_i$ to $t_{i+1}$ with step size $H_i=t_{i+1}-t_i$ according to (see detailed derivations in \cref{section:rk scheme})
\begin{align}
\label{eq:Exp-RK-update-beta}
\dY_{t_{i+1}} = e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_i} + H_i \sum_{j=1}^s b_j(H_i) k_j(\dY_{t_i}),
\end{align}
where the stage evaluations are defined using the rescaled score $\rscore_t(x) = s_t(x)\,\sigma_{T - t}$ as follows:
\begin{equation}
\label{eq:Exp-RK-update-beta-k}
\begin{split}
    &k_1(x) = \rscore_{t_i + c_1 H_i}(e^{\zeta(t_{i} + c_1H_i) - \zeta(t_i)}x),\\
    &k_2(x) = \rscore_{t_i + c_2 H_i}\bigl(e^{\zeta(t_{i} + c_2H_i) - \zeta(t_i)}x + (a_{21}(H_i) k_1(x)) H_i\bigr),\\
    &k_3(x) = \rscore_{t_i + c_3 H_i}\bigl(e^{\zeta(t_{i} + c_3H_i) - \zeta(t_i)}x + (a_{31}(H_i) k_1(x) + a_{32} (H_i)k_2(x)) H_i\bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
    &k_s(x) = \rscore_{t_i + c_s H_i}\bigl(e^{\zeta(t_{i} + c_sH_i) - \zeta(t_i)}x + (a_{s1}(H_i) k_1(x) + a_{s2}(H_i) k_2(x) + \cdots + a_{s,s-1}(H_i)k_{s-1}(x)) H_i\bigr).
\end{split}
\end{equation}
As in standard Runge-Kutta schemes, the lower triangular matrix $[a_{jk}]$, along with the coefficients $[b_j]$ and $[c_j]$, represent the Runge-Kutta matrix, weights and nodes. Typically, the nodes $c_j$ are constants, but the coefficients $a_{jk}(H_i)$ and $b_j(H_i)$ are functions of the step size $H_i$. The detailed coefficients for schemes up to third order are provided in \cref{tab:exp-butcher-specific}. Note that a fourth-order scheme requires at least five stages \cite{hochbruck2010exponential}, which we do not include here.
Exponential-type Runge-Kutta schemes of up to third order are widely used for solving the probability flow ODE, forming the backbone of the DPM solver~\cite{lu2022dpm}. However, in \cite{lu2022dpm}, the evaluation time points do not necessarily lie within the discrete time sequence $\bT$. In contrast, our construction~\cref{tab:exp-butcher-specific} allows the nodes $c_i$ to be chosen arbitrarily, in particular, uniformly over the interval $[0,1]$. By setting the step size $H_i$ to be a multiple of $\Delta t$, all evaluation times $t_i+c_jH_i$ are guaranteed to lie within $\bT$.


