\section{Discrete ODE Flow and Proofs of \Cref{theorem: main L^1 theorem} and \Cref{theorem: main L^1 theorem general}}\label{Section: Discrete ODE}



In this section, we first outline the proof of \Cref{theorem: main L^1 theorem} for the $p$-th order standard Runge-Kutta schemes introduced in \eqref{eq:RK-update} and \eqref{eq:RK-update-k}. At the end of this section, we sketch the proof of \Cref{theorem: main L^1 theorem general} for the (exponential) Runge-Kutta schemes introduced in \eqref{eq:RK-update-beta} and \eqref{eq:Exp-RK-update-beta} for the general forward process.



We start with the proof of \Cref{theorem: main L^1 theorem}. We analyze these Runge-Kutta schemes over a single time step. Recall that in \Cref{s:time_integrator}, we introduced the discretization of the time interval $[0,\,T-\tau]$: $0 = t_0 < t_1< \cdots < t_M  = T-\tau$, and we introduced $H_i=t_{i+1}-t_i$. We remark that we do not require each $H_i$ to be the same in the proof for \Cref{theorem: main L^1 theorem}. A key step in the proof (see \Cref{t:RK_1step}) is to establish a bound on the total variation distance between $\widetilde{Y}_{t_{i+1}}$ and $Y_{t_{i+1}}$. This bound is derived in terms of the total variation distance between $\widetilde{Y}_{t_i}$ and $Y_{t_i}$, with two contributing error terms: 
\begin{itemize}
    \item A discretization error of order $\mathcal{O}(H_i^{p+1})$ arising from the Runge-Kutta method.
    \item An additional error due to the score approximation.
\end{itemize}
We remark that the proof for \Cref{t:RK_1step} does not require those $t_i + c_j H_i$'s to be uniform in $[t_i , t_{i+1}]$ as in \eqref{e:defbT}. 

\begin{theorem}\label{t:RK_1step}
     Adopt \Cref{assumption:secon-moment}, \Cref{a:bounds on RK} and \Cref{a:score-derivative}. We fix $t=t_i$ and $H=t_{i+1}-t_i$. We denote the 
 $L^2$ score matching error at times $\{t+c_1H, t+c_2 H, t+c_3 H,\cdots, t+c_s H\}$ as
\begin{align}\label{e:score_bound}
		 \varepsilon_{\rm score} ^2(t) \coloneq \sum_{j=1}^s \sigma_{T-(t+c_j H)}^2 \int_{\bR^d}   \left\| s_{{t+c_j H}}(x) -  \nabla \log\varrho_{{t+c_j H}}(x)\right\|_2^2 \varrho_{{t+c_j H}}(x) \rd x.
\end{align}
Then, there is a constant $\Delta_{\rm disc} \in (0,1)$ depending on $A_p, B_p, s, p, D,\widetilde K, \widetilde W$, such that if we further assume that $H \leq (d\log (2d))^{-1} \cdot \tau^{3} \cdot \Delta_{\rm disc}$,
we can obtain that the total variation distance between the law of $\widetilde Y_{t+H}$ and $Y_{t+H}$ can be estimated by
 \begin{align}\label{eq:main local time estimate}
        \begin{split}
        &\int_{\mathbb{R}^d} |\dvarrho_{t+H}(x)-\varrho_{t+H}(x)| \de x
        \leq\int_{\mathbb{R}^d} |\dvarrho_{t}(x)-\varrho_{t}(x)| \de x+ \cE_{\rm score}+\cE_{\rm RK} ,
        \end{split}
    \end{align}
where $\cE_{\rm score}$ is related to the score error from \eqref{e:score_bound}, and $\cE_{\rm RK}$ is produced by $p$-th Runge-Kutta on the interval, which is of order $\cO(H^{p+1})$. More precisely, according to \Cref{Prop: Conclusion second error term} and \Cref{Prop: Conclusion third error term},
    \begin{align}\label{e:two_error}
        \begin{split}
            &\cE_{\rm score} = C_{\rm score}  \tau^{-2}  H  d^{\frac{7}{4}}   \cdot (\varepsilon_{\rm score}(t)) ^{\frac{1}{2}}, \quad \cE_{\rm RK} = C_{\rm RK}  H^{p+1} d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}, 
        \end{split}
    \end{align}
with $C_{\rm score}>0, C_{\rm RK} >0$ depending on $A_p, B_p, s, p, D,\widetilde K, \widetilde W$, and $\gamma_1,\gamma_2$ depending on $p$.
\end{theorem}


