\subsection{Preliminaries: p-th Order Runge-Kutta}\label{s:p-th-RK}
In the remaining subsections, we adopt notations from \Cref{t:RK_1step}, namely $t=t_i$ and $H=t_{i+1}-t_i$. 
For one step of the $p$-th order Runge-Kutta scheme introduced in \eqref{eq:RK-update} and \eqref{eq:RK-update-k}, we can write it in the form
\begin{align}\label{e:deftMt}
    \dY_{t+H}=\dY_t +H \dM_t(\widetilde Y_t;H),\quad \dM_t(x;H)=\sum_{j=1}^s b_j  \widetilde k_j(x).
\end{align}
where $\{b_j, \widetilde k_j(x)\}_{1\leq j\leq s}$ are as defined in \eqref{eq:RK-update-k}, and $\dM_t(x;H)$ in \eqref{eq:RK-update} depends on the approximate score at times $\{t+c_1 H, t+c_1 H,\cdots, t+c_s H\}$ and coefficients $a_{jk}$ from $p$-th order Runge-Kutta method. We remark that in the definition of $\dM_t(x;H)$ by \eqref{eq:RK-update} and \eqref{eq:RK-update-k}, because $H=t_{i+1}-t_i$ is fixed in \Cref{t:RK_1step}, we can view the coefficients $b_j = b_j(H)$ and $a_{jk} = a_{jk}(H)$ as constants. 

We further introduce the notations: for $0\leq h\leq H$ 
\begin{align}\label{e:phi_h_define}
  \dphi_h(x) \coloneq x + h \dM_t(x;H).
\end{align}
Let us first assume that for all $0\leq h\leq H$, $\dphi_h$ is invertible, which will be verified later in \Cref{lemma: phi_h invertible}. With the above notations \eqref{e:phi_h_define}, we can rewrite \eqref{e:deftMt} as $\dY_{t+H}=\dphi_H(\dY_t)$.
Given the law $\dvarrho_{t}$ of $\dY_t$,  we then define $\dvarrho_{t+h}$ as the pushforward law by the map $\dphi_h$:
    \begin{align}\label{e:trhoth}
        \dvarrho_{t+h} (x)\coloneq \dvarrho_{t} (\dphi_h ^{-1}(x)) \cdot | \det[ \nabla (\dphi_h ^{-1}(x))]|.
    \end{align}
Then the law of $\dY_{t+H}=\dphi_H(\dY_t)$ is $ \dvarrho_{t+H} (x)$. 





We use the notation $\phi_h(x)$ to denote the solution of the continuous flow \eqref{eq:reverse-ode} 
\begin{align*}
    \del_h \phi_h(x)=V_{t+h}(\phi_h(x)),
\end{align*} 
with $\phi_{0}(x) = x$ for $x \in \mathbb{R}^d$. 
Given the law $\varrho_t$ of $Y_t$,  the law $\varrho_{t+h}$ of $Y_{t+h}$ is the pushforward law by the map $\phi_h$:
    \begin{align}\label{e:rhoth}
    \varrho_{t+h} (x)\coloneq \varrho_{t} (\phi_h ^{-1}(x)) \cdot|  \det[ \nabla (\phi_h ^{-1}(x))]|.
    \end{align}
In particular, the law of $Y_{t+H}$ is given by $\varrho_{t+H} (x) = \varrho_{t} (\phi_H ^{-1}(x)) \cdot  |\det[ \nabla (\phi_H ^{-1}(x))]|$. Then we can formally define $M_t (Y_t;H)$, so that the solution $Y_{t+H}$ of the continuous flow \eqref{eq:reverse-ode} can also be written in the form of \eqref{e:deftMt}
\begin{align*}
    Y_{t+H}=Y_t+H M_t (Y_t;H),\quad M_t(x;H)=\frac{\phi_H(x)-x}{H}.
\end{align*}



Analogues to \eqref{e:deftMt}, we introduce  $\baM_t(x;H)$, which is defined in the same way as $\dM_t(x;H)$, but using  $V_t(x)=x+\nabla \log \varrho_t(x)$ from the true score instead of  $\sV_t(x)$. We let 
\begin{align}\label{e: score error p RK method}
\baM_{t}(x;H) \coloneq \sum_{j=1}^s b_j \overline k_j(x) ,
\end{align}
with 
\begin{equation}\label{e: p RK interpolation terms}
\begin{split}
    &\overline k_1(x) = V_{t + c_1 H}\bigl(x\bigr),\\
    & \overline k_2(x)  = V_{t + c_2 H}\bigl(x + (a_{21 } \overline k_1(x) ) H\bigr),\\
    & \overline k_3 (x) = V_{t + c_3 H}\bigl(x + (a_{31} \overline k_1(x)  + a_{32} \overline k_2(x) ) H\bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
    &\overline k_s(x)  = V_{t + c_s H}\bigl(x + (a_{s1} \overline k_1(x)  + a_{s2} \overline k_2(x)  + \cdots + a_{s,s-1} \overline k_{s-1}(x) ) H\bigr).
\end{split}
\end{equation}
In the above \eqref{e: score error p RK method} and \eqref{e: p RK interpolation terms}, the coefficients $b_j = b_j(H)$ and $a_{jk} = a_{jk}(H)$ are the same as those we used to define $\dM_t(x;H)$ in \eqref{e:deftMt}.
We can similarly define 
    \begin{align*}
        \baphi_h(x) \coloneq x + h \baM_t(x;H).
    \end{align*}
By \Cref{lemma: phi_h invertible}, let us also assume that for all $0\leq h\leq H$, $\baphi_h$ is invertible. Similar to \eqref{e:rhoth}, given the law $\varrho_t$ of $Y_t$,  we then define $\overline \varrho_{t+H}$ as the pushforward law by the map $\baphi_H$:
    \begin{align}\label{e:brhoth}
      \overline \varrho_{t+H} (x)\coloneq \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]|.
    \end{align}



For \eqref{eq:main local time estimate} in \Cref{t:RK_1step}, we need to estimate the total variation distance of $\dvarrho_{t+H},  \varrho_{t+H}$. Using \eqref{e:trhoth} and \eqref{e:rhoth}, we can rewrite it as
    \begin{align}\label{e: score error split 01}
        \begin{split}
        &\phantom{{}={}}\int_{\mathbb{R}^d} \left|\dvarrho_{t+H}(x)-\varrho_{t+H}(x)\right| \de x
        \\ &= \int_{\mathbb{R}^d} \left|\dvarrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\phi_H ^{-1}(x)) \cdot | \det[ \nabla (\phi_H ^{-1}(x))]| \right| \de x.
        \end{split}
    \end{align}

By triangle inequality, we can further bound \eqref{e: score error split 01} as
\begin{align}\label{e: score error split 0}
    \eqref{e: score error split 01}\leq I_1+I_2+I_3.
\end{align}
Here 
\begin{align}\begin{split}\label{e:defI1}
    I_1 &\coloneq \int_{\mathbb{R}^d} \left|\dvarrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| \right| \de x\\
    &=\int_{\mathbb{R}^d} |\dvarrho_{t}(x)-\varrho_{t}(x)|\de x,
\end{split}\end{align}
where the last line follows from change of variables, and is the total variation distance of $\dvarrho_t, \varrho_t$. The other two terms $I_2,I_3$ are 
\begin{align}\label{e:defI2}
    I_2 \coloneq \int_{\mathbb{R}^d} \left| \varrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| \right| \de x,
\end{align}
and 
\begin{align}\begin{split}\label{e:defI3}
    I_3
    & \coloneq \int_{\mathbb{R}^d} \left| \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| -  \varrho_{t} (\phi_H ^{-1}(x)) \cdot | \det[ \nabla (\phi_H ^{-1}(x))]| \right| \de x\\
    &=\int_{\bR^d} |\overline\varrho_{t+H}(x)-\varrho_{t+H}(x)|\rd x,
\end{split}\end{align}
where the last line follows from \eqref{e:brhoth} and \eqref{e:rhoth}, and it is the total variation distance between  $\overline\varrho_{t+H}$ and $\varrho_{t+H}$.
Intuitively, $I_1$ captures the initial distribution error; $I_2$ reflects the score matching error, since $\dphi_H$ and $\baphi_H$ correspond to the Runge-Kutta updates with and without score error; and $I_3$ represents the numerical discretization error of the Runge-Kutta scheme. 


In the rest of the paper, for simplicity of notations, if the context is clear, we simply write $ M_t(x;H), \dM_t(x;H), \baM_t(x;H)$ as $M_t(x), \dM_t(x), \baM_t(x)$.




