\subsection{Proof Outline of \Cref{t:RK_1step}}
\label{s:proof_RK_1step}
In this section, we outline the proof of \Cref{t:RK_1step}. By the decomposition \eqref{e: score error split 0}, the claim \eqref{eq:main local time estimate} boils down to  estimate $I_2, I_3$ as in \eqref{e:defI2} and \eqref{e:defI3}. In \Cref{Prop: Conclusion second error term} we show that $I_2\leq \cE_{\rm score}$ and in \Cref{Prop: Conclusion third error term} we show that $I_3\leq \cE_{\rm RK}$ as given in \eqref{e:two_error}. 

Before presenting the estimates for $I_2$ and $I_3$, we first state a proposition that gathers several useful estimates for the Runge-Kutta map functions $V_{t+h}(x)$, $\sV_{t+h}(x)$, $\widetilde{M}_t(x)$, and $\overline{M}_t(x)$, 
and ensures that for all $0\leq h\leq H$, $\dphi_h$ and $\baphi_h$ are invertible.
These estimates will be repeatedly applied throughout the remaining proofs.
The proof of \Cref{p:ABCD} is deferred to \Cref{Section: Constant Convention}.




\begin{proposition}\label{p:ABCD}
Adopt \Cref{assumption:secon-moment}, \Cref{a:bounds on RK} and \Cref{a:score-derivative}, the following holds
\begin{enumerate}
    \item 
\label{i:Vbound}
We recall $D$ from \Cref{assumption:secon-moment} and $\widetilde W, \widetilde K$ from \Cref{a:score-derivative}, and introduce
\begin{align}\label{e:tbound1}
 \widetilde W ^{(0)} 
  = \sqrt{d} \widetilde W \tau^{-1},  
  \widetilde W ^{(1)} 
  =  1+\widetilde W \tau^{-1},
   \widetilde K ^{(1)}  = 1+\widetilde K \tau^{-2},  \widetilde K ^{(2)}  = \widetilde K \tau^{-3}, \widetilde L^{(1)}=1+d\widetilde K \tau^{-2},
\end{align}
and
\begin{align}\label{e:tbound2}
            \overline W ^{(0)} = 2\tau^{-1} \sqrt{d}D, \overline W ^{(1)} = 2\tau^{-1}, \overline K ^{(1)}= 2D^2 \tau^{-2}, \overline K ^{(2)} = 24 D^3 \tau^{-3},\overline L ^{(1)} = 2dD^2 \tau^{-2}.
        \end{align}
%There exist constants $ \overline W ^{(0)}$,$  \overline W ^{(1)}$, $\overline  L^{(1)}$, $ \overline K ^{(1)}$, $ \overline K ^{(2)}$,  $\widetilde  W ^{(0)}$,$  \widetilde W ^{(1)}$,$ \widetilde L^{(1)}$, $ \widetilde K ^{(1)}$ and $ \widetilde K ^{(2)}$, which depend on the constants in \Cref{assumption:secon-moment}, \Cref{a:score-derivative} and $\tau$,
Then for any $x \in \mathbb{R}^d$ and any $h\in [0,H]$ such that $0\leq t+h\leq T-\tau$, the following holds: $\|V_{t+h}(x)\|_2 \leq \overline W ^{(0)} + \overline W ^{(1)} \|x\|_2$, $\|\nabla V_{t+h}(x)\|_{op} \leq \overline L ^{(1)}$, $\|\nabla V_{t+h} (x)\|_{\infty} \leq \overline K ^{(1)}$, and $\|\nabla ^2 V_{t+h} (x)\|_{\infty} \leq \overline K ^{(2)}$. Similarly, we have that $\|\sV_{t+h}(x)\|_2 \leq \widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_2$, $\|\nabla \sV_{t+h}(x)\|_{op} \leq \widetilde L ^{(1)}$, $\|\nabla \sV_{t+h} (x)\|_{\infty} \leq \widetilde K ^{(1)}$, and $\|\nabla ^2 \sV_{t+h} (x)\|_{\infty} \leq \widetilde K ^{(2)}$.% according to \Cref{a:score-derivative}.



\item There exist $\widetilde A, \widetilde B, \widetilde C,  \widetilde D, \overline A, \overline B, \overline C, \overline D$, which depend on $\tau$, the constants $A_p,B_p$ in \Cref{a:bounds on RK}, and constants in the above \Cref{i:Vbound}, such that for any $x \in \mathbb{R}^d$ and $0\leq t\leq T-\tau$, the following holds: 
 $\|\dM_t(x)\|_2  \leq \widetilde A + \widetilde B \|x\|_2$, $\|\nabla \dM_t(x) \|_{op} \leq  \widetilde C $, $\|\nabla \dM_t(x) \|_{\infty} \leq  \widetilde D$; similarly, $\|\baM_t(x)\|_2 \leq \overline A + \overline B \|x\|_2$, $\|\nabla \baM_t(x) \|_{op} \leq \overline C $, $\|\nabla \baM_t(x) \|_{\infty} \leq \overline D$.

\noindent We notice that the above statements on $\widetilde M_t$ and $\overline M_t$  can imply that $\|\dphi_H(x) - x\|_2 \leq H(\widetilde A + \widetilde B \|x\|_2)$, $\|\nabla \dphi_H(x) - \mathbb{I}_d \|_{op} \leq H \widetilde C $, $\|\nabla \dphi_H (x) - \mathbb{I}_d\|_{\infty} \leq H \widetilde D$; similarly, $\|\baphi_H(x) - x\|_2 \leq H(\overline A + \overline B \|x\|_2)$, $\|\nabla \baphi_H(x) - \mathbb{I}_d \|_{op} \leq H \overline C $, $\|\nabla \baphi_H (x) - \mathbb{I}_d\|_{\infty} \leq H \overline D$.

\end{enumerate}
\end{proposition}

We emphasize that the constant $D$ is the diameter defined in \Cref{assumption:secon-moment} and is different from $\widetilde D, \overline D$ defined in \Cref{p:ABCD}. \Cref{p:ABCD} follows from a careful analysis of the true score $\nabla \log \varrho_t$ and its derivatives, and we postpone its proof to \Cref{Section: Constant Convention}. 

Our main result, \Cref{t:RK_1step}, follows as a consequence of the following two propositions, which provide estimates for $I_2$  and $I_3$ on the right-hand side of \eqref{e: score error split 0}. The proof of \Cref{Prop: Conclusion second error term} is presented in \Cref{Section: second term conclusion}, and the proof of \Cref{Prop: Conclusion third error term} is given in \Cref{Section: third term conclusion}.


\begin{proposition}\label{Prop: Conclusion second error term} Adopt \Cref{a:bounds on RK}, the assumption \eqref{e:score_bound} in \Cref{t:RK_1step}, and assume the statements in \Cref{p:ABCD}. Denote $B:=1+A_p+B_p$. 
Assume that $H >0$ is small enough, such that $t+H\leq T-\tau$, and the following holds
\begin{align}
    \begin{split}\label{e:Hcondition}
        &\big[ (\widetilde L ^{(1)} +\overline L ^{(1)}) +  \sqrt{d}D(\widetilde W ^{(0)} + \overline W ^{(0)})+ (\widetilde W ^{(0)} + \overline W ^{(0)})^2+ dD^2(\widetilde W ^{(1)} + \overline W ^{(1)})  + 2d(\log 2d)(\widetilde W ^{(1)} + \overline W ^{(1)})^2
        \\&+ d (\widetilde K ^{(1)}+\overline K ^{(1)})   \big]\times  10^6  B^2  s^2 {4}^{s} \times  H\leq \sigma_{T-t} ^2 .
    \end{split}
\end{align}
Then, $I_2$ in \eqref{e: score error split 0} can be estimated by
     \begin{align*}
        \begin{split}
        I_2\leq C_{\rm disc}  \tau^{-2}  H\bigg[  d^{\frac{7}{4}}   \cdot (\varepsilon_{\rm score}(t)) ^{\frac{1}{2}} +     \tau^{-3}  {\pi}^{-\frac{d}{10}} e^{-\frac{1}{\xi H} }   \bigg] ,
        \end{split}
    \end{align*}
where $C_{\rm disc} $ is a constant depending on $B,  s, p, D,\widetilde K, \widetilde W$, and $\xi \coloneq 2\cdot 10^6 B^2s^2 4^s (\widetilde W ^{(1)} + \overline W ^{(1)})^2$.

\end{proposition}


\begin{proposition}\label{Prop: Conclusion third error term}
Adopt \Cref{a:bounds on RK}, and assume the statements in \Cref{p:ABCD}.
    Denote $B:=1+A_p+B_p$. There exists a large constant $C(p,s, B)>0$ depending on $p,s, B$,  and  positive constants $\gamma_1, \gamma_2 $ depending on $p$, such that if $t+H\leq T-\tau$ and $20 s 2^sBd D^2 \tau^{-2} H\leq 1$, then $I_3$ in \eqref{e: score error split 0} can be estimated by
        \begin{align}
            \begin{split}\label{e:third_term}
                I_3\leq C(p,s,B) H^{p+1} d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2} .
            \end{split}
        \end{align}

\end{proposition}


\begin{proof}[Proof of \Cref{t:RK_1step}]
    Plug the estimates in \Cref{Prop: Conclusion second error term} and \Cref{Prop: Conclusion third error term} into the decomposition \eqref{e: score error split 0}, we obtain that
         \begin{align}\label{e:simplify RK_1step}
        \begin{split}
        \int_{\mathbb{R}^d} |\dvarrho_{t+H}(x)-\varrho_{t+H}(x)| \de x
        \leq& 
         \int_{\mathbb{R}^d} |\dvarrho_{t}(x)-\varrho_{t}(x)| \de x 
         \\ &+ C_{\rm disc}  \tau^{-2}  H d^{\frac{7}{4}}   \cdot (\varepsilon_{\rm score}(t)) ^{\frac{1}{2}} 
        +   C_{\rm disc}  \tau^{-5} H   {\pi}^{-\frac{d}{10}} e^{-\frac{1}{\xi H} }    
        \\&+C(p,s,B) H^{p+1} d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}.
        \end{split}
    \end{align}
    Then, we further simplify the exponentially small term. Using the inequality that $e^\zeta \geq \frac{\zeta^{p}}{p!}$ when $\zeta \geq 0$, we have that $e^{-\frac{1}{\xi H} } = (e^{\frac{1}{\xi H} } )^{-1} \leq p! \times (\xi H)^{p}$. By \Cref{p:ABCD}, we know that $\xi \leq C(B,s,\widetilde W) \tau^{-2} $ for a constant $C(B,s,\widetilde W)$ depending on $B,s, \widetilde W$. Hence, we can combine the last two terms in \eqref{e:simplify RK_1step} to get a new term of the form $C(p,s,B,\widetilde W) H^{p+1} d^{p+1}  \tau^{-\gamma_1 ' } {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}$, where we take $\gamma_1 ' = \max \{\gamma_1, 2p+5\}$, and $C(p, B,s,\widetilde W)$ is a new constant depending on $p, B,s, \widetilde W$. This completes the proof of \Cref{t:RK_1step}.
\end{proof}




To conclude this subsection, we state \cref{lemma: phi_h invertible}, which implies that $\dphi_h(y)$ and $\baphi_h(y)$ are diffeomorphisms on $\mathbb{R}^d$, and hence invertible. The proof relies on a matrix estimate provided in the following lemma, whose proof is deferred to \Cref{app:proofs}.

\begin{lemma}\label{lemma: Growth of inverse matrix}
    Let $\gamma, \xi, H $ be positive 
  constants such that $\gamma H < 1/2$ and $2\xi H \leq 1/d$. Let $Q$ be a $d \times d $ matrix such that $\|Q - \mathbb{I}_d\|_{op} \leq \gamma H$ and $\|Q - \mathbb{I}_d\|_{\infty} \leq \xi H$, then 
        \begin{align*}
       \|Q^{-1} - \mathbb{I}_d \|_{op} \leq 2\gamma H, \quad \|Q^{-1} - \mathbb{I}_d \|_{\infty} \leq 2\xi H, 
       \quad \textrm{and} \quad
            e^{-4\xi H d} \leq  \det Q \leq e^{2\xi H d}.
    \end{align*}
\end{lemma}

\begin{lemma}\label{lemma: phi_h invertible}
  Assume the statements in \Cref{p:ABCD}. For $H>0$ is small enough, such that $t+H<T-\tau$ and 
  \begin{align}\label{e:Hsmall}
      H (\widetilde 
    A + \widetilde 
    B + \widetilde C+\overline A + \overline B +\overline C) <1/10,
  \end{align}
  then for $0\leq h\leq H$, $\dphi_h(y)$ and $\baphi_h(y)$ are diffeomorphisms on $\mathbb{R}^d$.
\end{lemma}
\begin{proof}
    We notice that $\nabla \dphi_h (x) = {\mathbb I}_d + h \nabla \dM_t(x)$, and $\|\nabla \dM_t(x)\|_{op} \leq \widetilde C$ by \Cref{p:ABCD} for any $x \in \mathbb{R}^d$.
    Then, for any $h\leq H$, \Cref{lemma: Growth of inverse matrix}, by taking $Q=\nabla \wt \phi_h(x)$, implies $\|(\nabla \dphi_h (x) ) ^{-1}\|_{op} \leq 2$. 
    Again, by \eqref{e:Hsmall}, for $h\leq H$, we have that $\|\dphi_h(x)\| \geq \|x\|_2 - \|\dphi_h(x) - x\|_2 \geq \|x\|_2 - h(\widetilde A + \widetilde B \|x\|_2) \geq (\|x\|_2-1)/2$. We see that $\|\dphi_h(x)\|_2 \to + \infty$ if $\|x\|_2 \to + \infty$. Hence, by Hadamard-Cacciopoli theorem,  $\dphi_h$'s are global diffeomorphisms on $\mathbb{R}^d$.

    By the same argument, the same statement holds for $\baphi_h (x)$.
\end{proof}





