\subsection{Proof of \Cref{theorem: main L^1 theorem}}
\label{s:proof_main}


Recall that in \Cref{Section: Preliminaries}, we introduced the discretization of the time interval $[0,\,T-\tau]$: $0 = t_0 < t_1< \cdots < t_M  = T-\tau$, and we introduced $H_i=t_{i+1}-t_i$. We basically apply the single step estimate \eqref{eq:main local time estimate} on each of these intervals $[t_i, t_{i+1}] = [t_i , t_i + H_i]$, and collect the errors on all intervals.

According to~\Cref{t:RK_1step} and \Cref{p:ABCD}, there is a constant $\Delta_{\rm disc}$ depending on numbers $A_p, B_p,s,D,\widetilde K, \widetilde W$, such that if we define $H_{\mathrm{max}} \coloneq \max_{0\leq i \leq M -1} H_i$ and $H_{\mathrm{max}}  \leq (d\log (2d))^{-1} \cdot \tau^{3} \cdot \Delta_{\rm disc}$, 
then it holds that
    \begin{align*}
        \begin{split}
            \sum_{i=0} ^{M-1} \int_{\mathbb{R}^d} |\dvarrho_{t_{i+1}}(x)-\varrho_{t_{i+1}}(x)| \de x
        \leq \sum_{i=0} ^{M-1} \Bigl(\int_{\mathbb{R}^d} |\dvarrho_{t_{i}}(x)-\varrho_{t_{i}}(x)| \de x+ \cE^i _{\rm score}+\cE^i _{\rm RK} \Bigr),
        \end{split}
    \end{align*}
where $\cE^i _{\rm score} = C_{\rm score}  \tau^{-2}  H_i  d^{\frac{7}{4}}   \cdot (\varepsilon_{\rm score}(t_i)) ^{\frac{1}{2}}$, $\cE^i _{\rm RK} = C_{\rm RK}  H_i ^{p+1} d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}$,
and $\varepsilon_{\rm score}(t)$ is as defined in \eqref{e:score_bound}.
Hence,
    \begin{align}\label{e:trho_diff}
        \int_{\mathbb{R}^d} |\dvarrho_{t_{M}}(x)-\varrho_{t_{M}}(x)| \de x
        \leq  \int_{\mathbb{R}^d} |\dvarrho_{t_{0}}(x)-\varrho_{t_{0}}(x)| \de x+ \sum_{i=0} ^{M-1}\Bigl(\cE^i _{\rm score}+\cE^i _{\rm RK} \Bigr).
    \end{align}
For those error terms on the right hand side, we first estimate $\sum_{i=0} ^{M-1}\cE^i _{\rm score}$. Observe that, by H{\"o}lder's inequality, 
    \begin{align*}\begin{split}
        \sum_{i=0} ^{M-1} H_i  (\varepsilon_{\rm score}(t_i)) ^{\frac{1}{2}} 
        &\leq \left( \sum_{i=0} ^{M-1}  H_i \varepsilon_{\rm score} ^{2} (t_i) \right)^{\frac{1}{4}} \left( \sum_{i=0} ^{M-1} H_i \right)^{\frac{3}{4}} 
        \leq  \varepsilon_{\rm score} ^{\frac{1}{2}}  T^{\frac{3}{4}},
   \end{split} \end{align*}
where $\varepsilon^2_{\rm score}\geq  \sum_{i=0}^{M-1} H_i \varepsilon^2_{\rm score}(t_i)$ and $\sum_{i=0} ^{M-1} H_i = T$ from \Cref{a:score-estimate} the definition of $\varepsilon^2_{\rm score}(t_i)$ in \eqref{e:score_bound}. Therefore, we obtain the following bound:
    \begin{align}\label{e:E_score_bound}
        \sum_{i=0} ^{M-1}\cE^i _{\rm score} \leq C_{\rm score}  T^{\frac{3}{4}} \tau^{-2}    d^{\frac{7}{4}}   \cdot \varepsilon_{\rm score} ^{\frac{1}{2}}.
    \end{align}
We next estimate $\sum_{i=0} ^{M-1} \cE^i _{\rm RK}$. Note that $
        \sum_{i=1} ^M H_i ^{p+1} \leq  H_{\mathrm{max}}^{p}T$, we have
    \begin{align}\label{e:ERK_bound}
        \sum_{i=0} ^{M-1} \cE^i _{\rm RK} \leq C_{\rm RK}  T H_{\mathrm{max}} ^p  d^{p+1}  \tau^{-\gamma_1} {\big(D+\sqrt{ \log d}\big)}^{\gamma_2}.
    \end{align}
Combine the bounds from \eqref{e:E_score_bound} and  \eqref{e:ERK_bound}, we substitute them into \eqref{e:trho_diff} and complete the proof of
\Cref{theorem: main L^1 theorem}. 


 \subsection{Proof of \Cref{theorem: main L^1 theorem general}}
\label{s:proof_general}
 In this section we sketch the proof of \Cref{theorem: main L^1 theorem general}.




For the standard Runge-Kutta schemes \eqref{eq:RK-update-beta}, we introduce the modified coefficients
\begin{align*}
   \check b_j(H_i):=\frac{\beta_{T-t_i-c_j H_i}b_j}{2},\quad \check a_{jk}(H_i)= \frac{\beta_{T-t_i-c_kH_i} a_{jk}}{2},\quad 1\leq k<j\leq s.
\end{align*}
Although \eqref{eq:RK-update-beta} and \eqref{eq:RK-update-beta-k} depend on $\beta_t$, we can rewrite them in the following form:
\begin{align}
\label{eq:RK-update-beta-rf}
\dY_{t_{i+1}} = \dY_{t_i} + H_i \sum_{j=1}^s  \check b_j \check k_j(\dY_{t_i}),
\end{align}
with 
\begin{equation}\label{eq:RK-update-beta-k-rf}
\begin{split}
    &\check k_1(x) = \widehat V_{t_i + c_1 H_i}(x),\\
    &\check k_2(x) = {\widehat V}_{t_i + c_2 H_i}\bigl(x + (\check a_{21}(H_i)\check k_1(x)) H_i\bigr),\\
    &\check k_3(x) = {\widehat V}_{t_i + c_3 H_i}\bigl(x + (\check a_{31}(H_i)\check k_1(x) + \check a_{32}(H_i) \check k_2(x)) H_i\bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
    &\check k_s(x) = {\widehat V}_{t_i + c_s H_i}\bigl(x + (\check a_{s1}(H_i) \check k_1(x) + \check a_{s2}(H_i)\check k_2(x) + \cdots + \check a_{s,s-1}(H_i)\check k_{s-1}(x)) H_i\bigr).
\end{split}
\end{equation}
In this reformulated version, the above scheme has the same structure as the standard Runge-Kutta schemes \eqref{eq:RK-update}.

Similarly, for the enhanced exponential Runge-Kutta scheme \eqref{eq:Exp-RK-update-beta} and \eqref{eq:Exp-RK-update-beta-k}, we introduce
\begin{align*}
\begin{split}
    &\check k_0(x)=x, \quad \check b_0(H_i)=\frac{e^{\zeta(t_{i}+H_i) - \zeta(t_i)}-1}{H_i},\quad 
      \check a_{j0}(H_i)=\frac{e^{\zeta(t_{i} + c_jH_i) - \zeta(t_i)}-1}{H_i},\\
      &\check b_{j}(H_i)=\sigma_{T-t_i-c_j H_i} b_j(H_i), \quad \check a_{jk}(H_i)=\sigma_{T-t_i-c_k H_i} a_{jk}(H_i), \quad 1\leq k<j\leq s.
\end{split}\end{align*}
With these definitions, the enhanced exponential Runge-Kutta scheme can be written as: 
\begin{align}
\label{eq:Exp-RK-update-beta-rf}
\dY_{t_{i+1}} = \dY_{t_i} + H_i \sum_{j=0}^s \check b_j (H_i)\check k_j(\dY_{t_i}),
\end{align}
and 
\begin{equation}\label{eq:Exp-RK-update-beta-k-rf}
\begin{split}
    &\check k_1(x) = s_{t_i+c_1H_i}(x+\check a_{10}(H_i) \check k_0(x) H_i),\\
    &\check k_2(x) = s_{t_i + c_2 H_i}\bigl(x + (\check a_{20}(H_i) \check k_0(x)+\check a_{21}(H_i) \check k_1(x)) H_i\bigr),\\
    &\check k_3(x) = s_{t_i + c_3 H_i}\bigl(x + (\check a_{30}(H_i) \check k_0(x)+\check a_{31}(H_i) \check k_1(x) + \check a_{32}(H_i) \check k_2(x)) H_i\bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
    &\check k_s(x) = s_{t_i + c_s H_i}\bigl(x + (\check a_{s0}(H_i) \check k_0(x)+\check a_{s1}(H_i) \check k_1(x) + \check a_{s2}(H_i) \check k_2(x) + \cdots + \check a_{s,s-1}(H_i)\check k_{s-1}(x)) H_i\bigr).
\end{split}
\end{equation}
Again, in this new form, the enhanced exponential Runge-Kutta schemes have the same structure as the standard schemes \eqref{eq:RK-update-k} with $\sV_t$ replaced by $s_t$. Importantly, both  \( s_t(x) \) and \( \widehat V_t(x) = x + s_t(x) \) satisfy the same regularity assumptions (see \Cref{a:score-derivative}). Therefore, \Cref{p:ABCD} also holds for $s_t(x)$. Moreover, using the explicit formula \eqref{e:general_sigma_t} of $\sigma_t$, it is straightforward to check that all statements in \Cref{s:prel-estim-q} hold for the forward density of the process \eqref{eq:OU-time}. 

The following lemma states that the coefficients of both schemes \eqref{eq:RK-update-beta-rf} and \eqref{eq:Exp-RK-update-beta-rf} satisfy the regularity condition in \Cref{a:bounds on RK}.  
\begin{lemma}
\label{lem:coefficients}
We consider the $i$-th time step for the Runge-Kutta schemes over the time interval $[t_i, t_{i}+H_i]\subset[0, T-\tau]$, such that $H_{i} \leq \tau$. Under \cref{a:bounds on beta_t} for the variance schedule $\beta_t$, the Runge-Kutta coefficients, rewritten in the forms \eqref{eq:RK-update-beta-rf} and \eqref{eq:Exp-RK-update-beta-rf} and treated as  functions of the time step $h$, satisfy the following derivative bounds.
\begin{align}
\label{e:derbound}
    \max_{1\leq j,k\leq s}\max_{0\leq l\leq p+1} \tau^{l} |\del_{h}^l \check{a}_{jk}(h)|\leq A_p,\quad \max_{1\leq j\leq s} \max_{0\leq l\leq p+1} \tau^{l} |\del_{h}^l \check{b}_j(h)|\leq B_p.
\end{align}
\end{lemma}
The proof of \cref{lem:coefficients} is technical and depends on the explicit forms of \( b_j(H_i) \) and \( a_{jk}(H_i) \). We defer this proof to \Cref{s:coefficient_est}.
Using the bounds in \eqref{e:derbound}, we can directly extend the proof of \Cref{theorem: main L^1 theorem} to both schemes \eqref{eq:RK-update-beta-rf} and \eqref{eq:Exp-RK-update-beta-rf}, which establishes \Cref{theorem: main L^1 theorem general}. 

% For \eqref{e:defba1}, the bound \eqref{e:derbound} follows directly from the fact that \( b_j \) and \( a_{jk} \) are constants, together with \Cref{a:bounds on beta_t}, which asserts that the derivatives of \( \beta_t \) are uniformly bounded.

%
%as After the change of time variable using~\eqref{eq:t-zeta change of variable}, the reverse process~\eqref{e:copy_hatYcirc} becomes essentially equivalent to~\eqref{eq:reverse-ode-score}. Similarly, the (exponential) Runge–Kutta methods~\eqref{eq:RK-update-general} and~\eqref{eq:Exp-RK-update-general} align with those in~\eqref{eq:RK-update} and~\eqref{eq:Exp-RK-update}, respectively, when the time sequence $\bT$ is taken to be $\{\zeta(j\Delta) : 0 \leq j \leq N\}$, and $t_j$ is set as $\zeta_j$ for $1 \leq j \leq M$.

