\section{Enhanced Exponential Runge-Kutta Schemes}\label{section:rk scheme}

In this section, we present the derivation of the enhanced exponential Runge–Kutta schemes introduced in \cref{s:general} for solving the probability flow ODE with a general variance schedule $\beta_t$:
\begin{align} 
\label{e:ODE_flow0}
	\del_t \sY_t = \frac{\beta_{T-t}}{2}\left( \sY_t +  s_t(\sY_t)\right) = \frac{\beta_{T-t}}{2} \sV_t(\sY_t), \qquad \sY_0 \sim \svarrho_0, \qquad 0 \leq t \leq T.
\end{align}
The schemes are constructed to ensure that all primary and intermediate time steps align with the discrete time sequence used during score matching: $\bT=\{j\Delta t : 0 \leq j \leq N,\,  \Delta t = \frac{T}{N}\}$. This alignment is necessary to achieve high-order convergence to the target distribution in \Cref{theorem: main L^1 theorem} and \Cref{theorem: main L^1 theorem general}.  We also provide estimates for the corresponding Runge–Kutta scheme coefficients.




\subsection{Coefficient Derivation}
The derivation follows the approaches in \cite{lu2022dpm,hochbruck2005explicit}.
Starting from the integral equation \eqref{eq:exp-rk-intg}, 
\begin{align*} 
     \sY_{t_{i+1}} = e^{\zeta(t_{i+1}) - \zeta(t_i)}\sY_{t_{i}} - \sigma_{T - t_{i+1}}e^{\alpha_{t_{i+1}}}\int_{t_i}^{t_{i+1}} \frac{\rd}{\rd t} e^{-\alpha_{t}} \rscore_t(\sY_t) \rd t.
\end{align*}
Recall the time change variable $\alpha_t$ defined in \eqref{eq:t-alpha change of variable}, which is monotonically decreasing in $t$.
We treat $\rscore_t(\sY_t)$ as a function of $\alpha_t$ and  apply a Taylor expansion of 
$\rscore_t(\sY_t)$ with respect to the changed time variable $\alpha_t$, yielding the following approximation:
\begin{align} 
     \sY_{t_{i+1}} &= e^{\zeta(t_{i+1}) - \zeta(t_i)}\sY_{t_{i}} -  \sigma_{T - t_{i+1}}e^{\alpha_{t_{i+1}}}\sum_{k=0}^{q-1}\int_{t_i}^{t_{i+1}} \frac{\bigl(\alpha_{t} - \alpha_{t_i}\bigr)^k}{k!}\frac{\rd}{\rd t} e^{-\alpha_{t}} \rd t \frac{\de^{(k)}\rscore_{t_i}(\sY_{t_i})}{\de{\alpha}^{(k)}}  + \mathcal{O}(H^{q+1}) \nonumber\\
     &= e^{\zeta(t_{i+1}) - \zeta(t_i)}\sY_{t_{i}} + \sigma_{T - t_{i+1}}\sum_{k=1}^{q}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^{k}\varphi_k(\alpha_{t_{i+1}} - \alpha_{t_i}) \frac{\de^{(k-1)}\rscore_{t_i}(\sY_{t_i})}{\de \alpha^{(k-1)}}  + \mathcal{O}(H^{q+1}) \label{eq:app-integral}.
\end{align}
where $\varphi_k(h) = \int_0^1 \frac{x^{k-1}}{(k-1)!}e^{h(1-x)}dx$. In particular,
\begin{equation}
\label{eq:varphi}
\varphi_1(h) = \frac{e^{h}-1}{h}\quad \textrm{and} \quad \varphi_2(h) = \frac{e^{h}-h-1}{h^2}.
\end{equation}


The first order scheme ($q=1$) with $c_1 = 0$ is given by 
\begin{equation}\label{eq:exp-RK-stiff1}\begin{split}
       k_1(x) &= \rscore_{t_i}(x), \\
     \dY_{t_{i+1}} &= e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_{i}} 
     + \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)\varphi_1\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr) k_1(\dY_{t_i}). 
\end{split}
\end{equation} 
Assume that $\dY_{t_i} = \sY_{t_i}$ is exact at time $t_i$, and subtract the above equation from \eqref{eq:app-integral}, the local truncation error 
is given by $\dY_{t_{i+1}} - \sY_{t_{i+1}} = \mathcal{O}(H_i^2)$.  


The second order scheme ($q=2$), with $c_1 = 0$ and any $0 < c_2 \leq 1$, is given by 
\begin{equation}
\label{eq:exp-RK-stiff2}
    \begin{split}
k_1(x) =& \rscore_{t_i}(x), \\
k_2(x) =& \rscore_{t_i + c_2H_i}\bigl(e^{\zeta(t_{i}+c_2H_i) - \zeta(t_i)}x + \sigma_{T - t_{i} - c_2H_i}\bigl(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_i}\bigr)\varphi_1(\alpha_{t_{i} + c_2H_{i}} - \alpha_{t_i}) k_1(x)\bigr), \\
\dY_{t_{i+1}} =& e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_{i}} 
     + b_1 k_1(\dY_{t_i}) H_i + b_2 k_2(\dY_{t_i}) H_i, 
\\
     b_2 = & \sigma_{T - t_{i+1}}\frac{(\alpha_{t_{i+1}} - \alpha_{t_i})^2}{(\alpha_{t_{i}+c_2H_i} - \alpha_{t_i})H_i} \varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i})
     \quad 
     b_1 =  \sigma_{T - t_{i+1}}\frac{\alpha_{t_{i+1}} - \alpha_{t_i}}{H_i}\varphi_1(\alpha_{t_{i+1}} - \alpha_{t_i}) - b_2.
\end{split}
\end{equation}
To analyze the local truncation error, we assume that  $\dY_{t_i} = \sY_{t_i}$ is exact at time $t_i$. Then, the slope evaluations satisfy the following approximations:
\begin{align*} 
k_1(\dY_{t_i}) =& \rscore_{t_i}(\dY_{t_i}), 
\\
k_2(\dY_{t_i}) =& \rscore_{t_i + c_2H_i}\bigl(\sY_{t_i + c_2H_i}\bigr) + \mathcal{O}(H_i^2)
= \rscore_{t_i}(\sY_{t_i}) + \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} + \mathcal{O}(H_i^2).
\end{align*}
The resulting update satisfies
$$\dY_{t_{i+1}} = e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_{i}} 
     + b_1 k_1(\dY_{t_i})H_i 
     + b_2 k_2(\dY_{t_i})H_i 
     = \sY_{t_{i+1}} + \mathcal{O}(H_i^3).$$ 
This third order local accuracy is achieved by matching coefficients of $\rscore_{t_i}(\sY_{t_i})$ and $\frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha}$ in the update rules \eqref{eq:exp-RK-stiff2} and \eqref{eq:app-integral} to order $3$, using  the identities:
\begin{align*}
    &\Bigl(b_1  + b_2\Bigr)H_i = \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)\varphi_1(\alpha_{t_{i+1}} - \alpha_{t_i}), 
    \\
    &b_2 \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) H_i = \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i}). 
\end{align*}







The third order scheme ($q=3$), with $c_1 = 0$, any $0 < c_2  < c_3 \leq 1$, and $\gamma = \frac{3c_3^2 - 2c_3}{3c_2^2-2c_2}$, is given by 
{\small
\begin{equation}
\label{eq:exp-RK-stiff3}
    \begin{split}
        k_1(x) =& \rscore_{t_i}(x), 
\\
k_2(x) =& \rscore_{t_i + c_2H_i}\Bigl(e^{\zeta(t_{i}+c_2H_i) - \zeta(t_i)}x + \sigma_{T - t_{i} - c_2H_i}\bigl(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_i}\bigr)\varphi_1\bigl(\alpha_{t_{i} + c_2H_{i}} - \alpha_{t_i}\bigr) k_1(x)\Bigr), 
\\
k_3(x) =& \rscore_{t_i + c_3H_i}\Bigl(e^{\zeta(t_{i}+c_3H_i) - \zeta(t_i)}x 
+ \sigma_{T - t_{i} - c_3H_i}\bigl(\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_i}\bigr)\varphi_1\bigl(\alpha_{t_{i} + c_3H_{i}} - \alpha_{t_i}\bigr) k_1(x) + a_{32} \bigl(k_2(x) - k_1(x)\bigr)H_i
\Bigr), 
\\
a_{32} =& \frac{\gamma\sigma_{T - t_{i} - c_2H_i}(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i} + c_2H_{i}} - \alpha_{t_i}\bigr) + \sigma_{T - t_{i} - c_3H_i}\bigl(\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i} + c_3H_{i}} - \alpha_{t_i}\bigr)}{(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_{i}})H_i},
\\
\dY_{t_{i+1}} =& e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_{i}} 
     + b_1 k_1(\dY_{t_i})H_i 
     + \gamma b_3 k_2(\dY_{t_i})H_i 
     + b_3 k_3(\dY_{t_i})H_i, 
\\
b_{3}  =&  \frac{\sigma_{T - t_{i+1}}
     \bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i})
      }{\bigl(\gamma(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_{i}}) + (\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_{i}})\bigr)H_i}\quad
b_1 = \frac{\sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)\varphi_1\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)}{H_i}  - (1+\gamma)b_3.
    \end{split}
\end{equation}}The local truncation error analysis assumes that $\dY_{t_i} = \sY_{t_i}$ is exact at time $t_i$. Denote $J_{t_i} = \frac{\partial \rscore_{t_i}(x)}{\partial x}\Bigl|_{x=\sY_{t_i}}$,  then the slope evaluations satisfy the following approximations:
{\small
\begin{align*} 
k_1(\dY_{t_i}) =& \rscore_{t_i}(\dY_{t_i}) ,
\\
k_2(\dY_{t_i}) =& \rscore_{t_i + c_2H_i}(\sY_{t_i + c_2H_i}) 
- \Bigl(\rscore_{t_i + c_2H_i}(\sY_{t_i + c_2H_i}) -  k_2(\dY_{t_i})\Bigr)  \quad  \textrm{(Taylor expansions at $\rscore_{t_i(\alpha_{t_i})}(\sY_{t_i(\alpha_{t_i})})$ and $\rscore_{t_i}(\sY_{t_i})$)}
\\
=& \rscore_{t_i}(\sY_{t_i}) + \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} + \frac{1}{2}\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2 \frac{\de^{(2)}\rscore_{t_i}(\sY_{t_i})}{\de\alpha^{(2)}}\\
&- J_{t_i}\Bigl(\sigma_{T - t_i - c_2H_i}\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_i+c_2H_i} - \alpha_{t_i})\Bigr)\frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} + \mathcal{O}(H_i^3) , 
\\
k_3(\dY_{t_i}) =& \rscore_{t_i + c_3H_i}(\sY_{t_i + c_3H_i}) 
- \Bigl(\rscore_{t_i + c_3H_i}(\sY_{t_i + c_3H_i}) -  k_3(\dY_{t_i})\Bigr)  \quad  \textrm{(Taylor expansions at $\rscore_{t_i(\alpha_{t_i})}(\sY_{t_i(\alpha_{t_i})})$ and $\rscore_{t_i}(\sY_{t_i})$)}
\\
=& \rscore_{t_i}(\sY_{t_i}) + \bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} + \frac{1}{2}\bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr)^2  \frac{\de^{(2)}\rscore_{t_i}(\sY_{t_i})}{\de\alpha^{(2)}} \\
&- J_{t_i}\Bigl(\sigma_{T - t_{i} - c_3H_i}\bigl(\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i} + c_3H_{i}} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} - a_{32} \bigl(k_2(\dY_{t_i}) - k_1(\dY_{t_i})\bigr)H_i\Bigr) + \mathcal{O}(H_i^3) .
\end{align*}}
The resulting update satisfies
$$\dY_{t_{i+1}} = e^{\zeta(t_{i+1}) - \zeta(t_i)}\dY_{t_{i}} 
     + b_1 k_1(\dY_{t_i})H_i 
     + \gamma b_3 k_2(\dY_{t_i})H_i 
     + b_3 k_3(\dY_{t_i})H_i = \sY_{t_{i+1}} + \mathcal{O}(H_i^4).$$ 
This accuracy is achieved by matching the coefficients $\rscore_{t_i}(\sY_{t_i})$, $\frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha}$, $\frac{\de^{(2)}\rscore_{t_i}(\sY_{t_i})}{\de\alpha^{(2)}}$,  and $J_{t_i}$ in the update rules \eqref{eq:exp-RK-stiff3} and \eqref{eq:app-integral} to order 4, using the following approximations:
{\small
\begin{equation}
\label{eq:rk3-exp-order-conditions}
    \begin{split}
        &\Bigl(b_1  + \gamma b_3 + b_3\Bigr)H_i = \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)\varphi_1\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr) 
    \\
    &\Bigl(\gamma b_3 \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) + b_3 \bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr) \Bigr)H_i = \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr) 
    \\
    &\Bigl(\frac{\gamma b_3}{2}\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2 + \frac{b_3}{2}\bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr)^2 \Bigr)H_i = \sigma_{T - t_{i+1}}\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^2\varphi_3\bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr) + \mathcal{O}(H_i^4) \\
    &\gamma b_3 \Bigl(\sigma_{T - t_i - c_2H_i}\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_i+c_2H_i} - \alpha_{t_i}) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha}\Bigr) H_i 
    \\&+ b_3 \Bigl(\sigma_{T - t_{i} - c_3H_i}\bigl(\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i} + c_3H_{i}} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} - a_{32} \bigl(k_2(\dY_{t_i}) - k_1(\dY_{t_i})\bigr)H_i\Bigr)H_i = \mathcal{O}(H_i^4) .
    \end{split}
\end{equation}}The first two equations in \eqref{eq:rk3-exp-order-conditions} follow directly from the definitions of $b_1$ and $b_3$. The third equation holds up to fourth order, due to the definition of $\gamma$ and the approximations: 
\begin{align*}
%\label{eq:rk3-exp-order-conditions-3}
    \Bigl(\frac{\gamma b_3}{2}&\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2 +  \frac{b_3}{2}\bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr)^2 \Bigr)H_i 
     \\&= \frac{1}{2}\frac{\gamma \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2 + \bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr)^2
      }{\gamma(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_{i}}) + (\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_{i}})} \sigma_{T - t_{i+1}}
     \bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i})
     \\&= \frac{1}{2}\frac{\gamma c_2^2 + c_3^2}{\gamma c_2  + c_3} \sigma_{T - t_{i+1}}
     \bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^3\varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i}) + O(H_i^4) 
     \\&= \sigma_{T - t_{i+1}}
     \bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)^3\varphi_3(\alpha_{t_{i+1}} - \alpha_{t_i}) + O(H_i^4),
\end{align*}
where the second equation uses $\frac{\gamma \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2 + \bigl(\alpha_{t_i+c_3H_i} - \alpha_{t_i}\bigr)^2
      }{\gamma(\alpha_{t_{i}+ c_2H_{i}} - \alpha_{t_{i}}) + (\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_{i}})} = \frac{\gamma c_2^2 + c_3^2}{\gamma c_2  + c_3} 
     \bigl(\alpha_{t_{i+1}} - \alpha_{t_i}\bigr)+ \mathcal{O}(H_i^2)$, and the final step applies the definition of $\gamma$ and  the identity $\varphi_2(\alpha_{t_{i+1}} - \alpha_{t_i})  = 3\varphi_3(\alpha_{t_{i+1}} - \alpha_{t_i}) + \mathcal{O}(H_i)$.
The last equation in \eqref{eq:rk3-exp-order-conditions} is obtained by first expressing
\begin{align*}
    k_2(\dY_{t_i})  - k_1(\dY_{t_i}) = \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) \frac{\de\rscore_{t_i}(\sY_{t_i})}{\de\alpha} + \mathcal{O}(H_i^2),
\end{align*}
and then enforcing
{\small
\begin{align*}
    &\gamma  \Bigl(\sigma_{T - t_i - c_2H_i}\bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr)^2\varphi_2(\alpha_{t_i+c_2H_i} - \alpha_{t_i}) \Bigr) H_i 
    \\&+  \Bigl(\sigma_{T - t_{i} - c_3H_i}\bigl(\alpha_{t_{i}+ c_3H_{i}} - \alpha_{t_i}\bigr)^2\varphi_2\bigl(\alpha_{t_{i} + c_3H_{i}} - \alpha_{t_i}\bigr) - a_{32} \bigl(\alpha_{t_i+c_2H_i} - \alpha_{t_i}\bigr) H_i\Bigr)H_i = \mathcal{O}(H_i^4) ,
\end{align*}}which leads to our definition of $a_{32}$. We note that $a_{32}$ can be further simplified to retain only the dominant $\mathcal{O}(1)$ term.  



To construct $c_j$ such that all relevant time points, including $t_i$, $t_{i+1}$, and $\{t_i + c_j H_i\}$, lie within the discrete time sequence $\bT$.  For the 1-stage first-order scheme and the 2-stage second-order scheme with $c_2 = 1$, detailed in \eqref{eq:exp-RK-stiff1} and \eqref{eq:exp-RK-stiff2}, no intermediate time evaluations are required. In these cases, it suffices that $t_i \in \bT$, which implies that $H_i$ is an integer multiple of the base step size $\Delta t$. For the 3-stage third-order detailed in \eqref{eq:exp-RK-stiff3}, we can choose $c_2 = \frac{1}{3}$ and $c_3 = \frac{2}{3}$. To ensure these points align with $\bT$, we require that each $H_i$ is a multiple of $3\Delta t$.


\subsection{Coefficient Estimations}
\label{s:coefficient_est}
Finally, we present the proof of \cref{lem:coefficients},  which establishes bounds for the modified Runge-Kutta coefficients introduced in \eqref{eq:RK-update-beta-rf} and \eqref{eq:Exp-RK-update-beta-rf}.
\begin{proof}
For the standard Runge-Kutta schemes, the coefficients are constant. After being rewritten as \eqref{eq:RK-update-beta-rf}, the coefficients are scaled by $\beta_t$, and the resulting bounds follow from the regularity \Cref{a:bounds on beta_t} on $\beta_t$. 
For the enhanced exponential Runge-Kutta schemes up to third order discussed above, we  begin by  recalling the relevant time change variables
    \begin{align*}
    \lambda_t = e^{-\frac{1}{2} \int_0^t \beta_s \de s} \quad  \sigma_t  = \sqrt{1 - \lambda_t^2} \quad
\zeta(t) = \frac{1}{2} \int_{T-t}^T \beta_s \de s \quad \textrm{and} \quad 
\alpha_t = \zeta(t) - \log \sigma_{T-t},
    \end{align*}
and their  derivatives
    \begin{align}
    \label{eq:derivatives}
    \frac{\rd \sigma_t^2}{\rd t}  = \beta_t\bigl( 1 - \sigma_t^2 \bigr)
    \quad
        \frac{\rd \zeta(t)}{\rd t} = \beta_{T-t} 
        \quad \textrm{and} \quad 
        \frac{\rd \alpha_t}{\rd t} = -\frac{\beta_{T-t}}{2\sigma_{T-t}^2}. 
    \end{align}
The Runge-Kutta coefficients in \cref{eq:exp-RK-stiff1,eq:exp-RK-stiff2,eq:exp-RK-stiff3} are modified through \eqref{eq:Exp-RK-update-beta-rf}, these modified coefficients are linear combinations of the following functions: 
\begin{align}
\begin{split}
\label{eq:RK-f}
f_0(h; t, \fc) &=  \frac{
e^{\zeta(t + \fc h) - \zeta(t)}-1}{\fc h} ,
\\
    f_1(h; t, \fc , \fc _1) &= \sigma_{T - t - \fc_1h}\sigma_{T - t - \fc h}\frac{\alpha_{t + \fc h} - \alpha_{t}}{\fc h}\varphi_1(\alpha_{t  + \fc h} - \alpha_{t})  ,
    \\
    f_2(h; t, \fc , \fc_1, \fc_2, \fc_3, \gamma) &= \sigma_{T - t - \fc_1h}\sigma_{T - t - \fc h}\frac {(\alpha_{t + \fc h} - \alpha_{t})^2}{\bigl(\gamma (\alpha_{t + \fc_2h} - \alpha_{t}) + (\alpha_{t + \fc_3h} - \alpha_{t})\bigr)h}\varphi_2(\alpha_{t  + \fc h} - \alpha_{t}),
\end{split}
\end{align}
where these constants $0\leq\gamma$, $0 < \fc_i \leq \fc \leq 1$ are related to, but may differ in index from, $c_i$ and $\gamma$ constants in the Runge-Kutta schemes~\cref{eq:exp-RK-stiff1,eq:exp-RK-stiff2,eq:exp-RK-stiff3}.

Next, we show that these functions $f_i$  and their derivatives are bounded. These functions can be further decomposed into the following terms
\begin{align}
\begin{split}
\label{eq:RK-coeff}
&\frac{\zeta(t  + \fc h) - \zeta(t)}{\fc h} =   \int_0^1 \beta_{T - t - \fc h s}\de s \in [C_\beta^{-1}, C_{\beta}],
\\
%&\frac{\alpha_{t  + \fc h} - \alpha_{t}}{\fc h} =   \int_0^1 \frac{\beta_{T-t-\fc h s}}{2\sigma_{T-t-\fc hs}^2}\de s \geq \frac{C_\beta^{-1}}{2}\\
&\sigma_{T-t-\fc_1h}\sigma_{T-t-\fc_2h}\frac{\alpha_{t  + \fc h} - \alpha_{t}}{\fc h} =  \sigma_{T-t-\fc_1h}\sigma_{T-t-\fc_2h} \int_0^1 \frac{\beta_{T-t-\fc h s}}{2\sigma_{T-t-\fc hs}^2}\de s \leq \frac{C_\beta}{2} \Bigl(\frac{\sigma_{T - t}}{\sigma_{T-t-\fc h}}\Bigr)^2 ,
\\
&\frac{ \alpha_{t + \fc h} - \alpha_{t} }{ \gamma (\alpha_{t + \fc_2h} - \alpha_{t}) + (\alpha_{t + \fc_3h} - \alpha_{t}) } = 
\frac{\int_0^1 \frac{\beta_{T-t-\fc h s}}{\sigma_{T-t-\fc hs}^2}\de s}{\gamma\int_0^1 \frac{\beta_{T-t-\fc_2h s}}{\sigma_{T-t-\fc_2hs}^2}\de s + \int_0^1 \frac{\beta_{T-t-\fc_3h s}}{\sigma_{T-t-\fc_3hs}^2}\de s} \leq \frac{C_\beta^2}{\gamma+1} \Bigl(\frac{\sigma_{T - t}}{\sigma_{T-t-\fc h}}\Bigr)^2,
\\
&\varphi_k(\alpha_{t  + \fc h} - \alpha_{t}) \leq   e^{\alpha_{t  + \fc h} - \alpha_{t}}  =   e^{\zeta(t  + \fc h) - \zeta(t)} \frac{\sigma_{T - t}}{\sigma_{T-t-\fc h}} .
\end{split}
\end{align}
The first three equations are due to the fact 
that $C_\beta^{-1} \leq \beta_t \leq C_\beta$, the fact that $\sigma_t \in [0,1]$ is increasing,  and the definition of $\frac{\de \zeta(t)}{\de t}$ and $\frac{\de \alpha_t}{\de t}$ in \eqref{eq:derivatives}. The last inequality follows from $\varphi_k(h) = \int_0^1 \frac{x^{k-1}}{(k-1)!}e^{h(1-x)}dx \leq e^h$. The boundedness of the functions $f_i$ in \eqref{eq:RK-f} can be obtained by substituting the following estimate into \eqref{eq:RK-coeff}:
\begin{align*}
     \Bigl(\frac{\sigma_{T - t}}{\sigma_{T - t - \fc h}}\Bigr)^2 
     = 
     \frac{1 - e^{-\int_0^{T-t-\fc h}\beta_s \de s - \int_{T-t-\fc h}^{T-t}\beta_s \de s}}{1 - e^{-\int_0^{T-t-\fc h}\beta_s \de s}}
     \leq 
    \frac{\int_0^{T-t-\fc h}\beta_s \de s + \int_{T-t-\fc h}^{T-t}\beta_s \de s}{\int_0^{T-t-\fc h}\beta_s \de s}
     \leq 
      1 + \fc C_\beta^2 \frac{h}{\tau}.
\end{align*}
Here, we used the inequality $\frac{1 - e^{-x-y}}{1-e^{-x}} \leq \frac{x+y}{x}$ for $x,y >0$, the time domain $t+\fc h \leq T - \tau$, and $h \leq H_{\rm max} \leq \tau$. The estimates for the derivatives of these $f_i$ functions can be obtained by the fact that these terms in \eqref{eq:RK-coeff} are smooth with bounded derivatives. Except that $\sigma_{t}$ has a singularity as $t$ approaches $0$, its behavior is like $\sqrt{t}$. For $t\in[\tau,T]$, we have 
\begin{align*}
      1\geq \sigma_{t} = \sqrt{1 - e^{-\int_0^{t}\beta_s \de s}}
      \geq \sqrt{1 - e^{-\frac{\tau}{C_\beta}}}
      \geq \sqrt{\min\Bigl\{\frac{\tau}{2C_\beta},\frac{1}{2}\Bigr\}} .
\end{align*}
Its derivative satisfies
\begin{equation*}
      |\partial_t \sigma_{t}| = \Bigl|\sigma_t \frac{\beta_t}{2} \Bigl(\frac{1}{\sigma_t^2} - 1\Bigr)\Bigr| \leq \sigma_t 
      C_\beta \max\{\frac{2C_\beta}{\tau}, 1\} .
\end{equation*}
Similarly, for any integer $\ell\in \mathbb Z$
\begin{equation*}
      |\partial_t \sigma^\ell_{t}| = \Bigl|\ell \sigma^{\ell}_t \frac{\beta_t}{2} \Bigl(\frac{1}{\sigma_t^2} - 1\Bigr)\Bigr| \leq \ell\sigma_t ^{\ell}
      C_\beta \max\{\frac{2C_\beta}{\tau}, 1\} .
\end{equation*}
For higher derivatives we treat $\beta_t$ and its derivatives as coefficients, and only track the change of $\sigma_t$. The $\ell$-th derivative of $\sigma_t$ is a Laurent polynomial of $\sigma_t$ with degree between $1-2\ell$ and $1$, and the coefficients of this polynomial involve $\beta_t$ and its derivatives. As a consequence
\begin{align}\label{e:high-der}
    |\partial^\ell_t \sigma_{t}| \leq C\max_{1-2\ell\leq r\leq 1}\{\sigma^r_t\}\leq \frac{2\ell C}{\tau^\ell} \sigma_t, 
\end{align}
where the constant $C$ depends on $C_\beta$. In a word, each derivative gives an extra factor $1/\tau$. 

Back to \eqref{eq:RK-coeff}. By \eqref{e:high-der}, when a term $\sigma_{T-t-\fc h}$ in \eqref{eq:RK-coeff} is differentiated with respect to $h$, it might introduce a factor proportional to $\frac{1}{\tau}$ in front, thereby explaining the $\tau$-scaling in the estimates of \eqref{e:derbound}. This completes the proof.
\end{proof}





