\section{Proof of \Cref{p:ABCD}}\label{Section: Constant Convention}


The first part of \Cref{p:ABCD} follows from the following lemma, which is an easy consequence of our \Cref{a:score-derivative} and the estimates on derivatives of $\log q_t(y)$ provided in \Cref{Lemma: Hessian estimates}. 
\begin{lemma}\label{lemma: Constant Convention1}
Adopt the assumptions in \Cref{p:ABCD}.  For $t+H \leq T- \tau$, \Cref{i:Vbound} of \Cref{p:ABCD} holds with the following choice of parameters 
\begin{align}\label{e:tbound3}
 \widetilde W ^{(0)} 
  = \sqrt{d} \widetilde W \tau^{-1},  \quad 
  \widetilde W ^{(1)} 
  =  1+\widetilde W \tau^{-1},\quad
   \widetilde K ^{(1)}  = 1+\widetilde K \tau^{-2}, \quad  \widetilde K ^{(2)}  = \widetilde K \tau^{-3}, \quad \widetilde L^{(1)}=1+d\widetilde K \tau^{-2},
\end{align}
and
\begin{align}\label{e:tbound4}
            \overline W ^{(0)} = 2\tau^{-1} \sqrt{d}D, \quad \overline W ^{(1)} = 2\tau^{-1}, \quad \overline K ^{(1)}= 2D^2 \tau^{-2}, \quad \overline K ^{(2)} = 24 D^3 \tau^{-3},\quad \overline L ^{(1)} = 2dD^2 \tau^{-2}.
        \end{align}
\end{lemma}
\begin{proof}
    The first claim \eqref{e:tbound3} is a consequence of \Cref{a:score-derivative}. For example $\|\nabla \widehat V_{t+h}(x)\|_{op}\leq 1+\|\nabla \widehat s_{t+h}(x)\|_{op}\leq 1+d \max_{1\leq l,j\leq d}|\partial_{x_l} s_t^{(j)}(x)|\leq 1+d\widetilde K/\tau^2$. 
    The claim \eqref{e:tbound4} follows from the estimates on derivatives of $\log q_t(y)$ in Lemma~\ref{Lemma: Hessian estimates}. 
    For example, we see that $|V^{(i)}_{t+h} (x)| \leq \tau^{-1} (|x_i| + D)$, so $\|V_{t+h} (x)\|_2 \leq 2\tau^{-1} (\sqrt{d}D+\|x\|_2)$, which gives that we can take $\overline W ^{(0)} = 2\tau^{-1} \sqrt{d}D$ and $\overline W ^{(1)} =2\tau^{-1}$. Similarly, $\overline K ^{(1)}= 2D^2 \tau^{-2}$, $\overline K ^{(2)} = 24D^3 \tau^{-3}$, and $\overline L ^{(1)}= 2dD^2 \tau^{-2}$.
\end{proof}


In the rest of this section we prove the second part of \Cref{p:ABCD}. We recall  $\dM_t(x)$ and $\baM_t(x)$ from \eqref{e:deftMt} and \eqref{e: score error p RK method} 
\begin{align}\label{e: score error p RK method copy}
\dM_{t}(x)= \sum_{j=1}^s b_j \widetilde k_j(x), \quad \dphi_H(x)=x+H \dM_{t}(x),\quad \baM_{t} \coloneq \sum_{j=1}^s b_j \overline k_j(x) , \quad \baphi_H(x)=x+H \baM_{t}(x),
