    &\widetilde k_3 = \sV_{t + c_3 H}\bigl(x + (a_{31} \widetilde k_1 + a_{32} \widetilde k_2) H\bigr), \quad \overline k_3 = V_{t + c_3 H}\bigl(x + (a_{31} \overline k_1 + a_{32} \overline k_2) H\bigr),\\
