\subsection{Proofs of \Cref{lemma: infinity norm pth order growth in RK}, \Cref{lemma: pth order growth in RK} and \Cref{lemma: infinity norm for k_i(x)}}
\begin{proof}[Proof of \Cref{lemma: infinity norm pth order growth in RK}]\label{s:prove_k}
    We only prove the statement for $\widetilde k_i(x)$'s and the proof for $\overline k_i(x)$'s are similar. 
    By the relation that $\widetilde k_i = \sV_{t + c_i H}\bigl(x + (a_{i1} \widetilde k_1 + a_{i2} \widetilde k_2 + \cdots + a_{i,i-1} \widetilde k_{i-1}) H\bigr)$, we obtain that
        \begin{align*}
    \partial_{l_1} \widetilde k_i ^{(q)} = \sum_{l_2 = 1} ^{d} (\partial_{l_2}\sV_{t + c_i H} ^{(q)})[\delta_{l_1 l_2} + H(a_{i1} \partial_{l_1}\widetilde k_1 ^{(l_2)} + a_{i2} \partial_{l_1} \widetilde k_2 ^{(l_2)} + \cdots + a_{i,i-1} \partial_{l_1} \widetilde k_{i-1} ^{(l_2)}) ],
        \end{align*}
and 
    \begin{align*}
        \begin{split}
            \partial_{l_1 l_3} ^2 \widetilde k_i ^{(q)} &= \bigg( \sum_{l_2  = 1} ^{d} \sum_{l_4  = 1} ^{d} (\partial_{l_2 l_4} ^2 \sV_{t + c_i H} ^{(q)})[\delta_{l_1 l_2} + H(a_{i1} \partial_{l_1}\widetilde k_1 ^{(l_2)} + \cdots + a_{i,i-1} \partial_{l_1} \widetilde k_{i-1} ^{(l_2)}) ]
            \\ &\quad \cdot [\delta_{l_3 l_4} + H(a_{i1} \partial_{l_3}\widetilde k_1 ^{(l_4)} + \cdots + a_{i,i-1} \partial_{l_3} \widetilde k_{i-1} ^{(l_4)}) ] \bigg)
           \\   &\quad  + \sum_{l_2 = 1} ^{d} (\partial_{l_2}\sV_{t + c_i H} ^{(q)})[ H(a_{i1} \partial_{l_1 l_3} ^2\widetilde k_1 ^{(l_2)} \cdots + a_{i,i-1} \partial_{l_1 l_3} ^2 \widetilde k_{i-1} ^{(l_2)})].
        \end{split}
    \end{align*}
Hence,
    \begin{align}\label{e:iteration growth}
        \|\nabla \widetilde k_i(x)\|_{\infty} \leq \widetilde K ^{(1)} [1+ A_p H d (\|\nabla \widetilde k_1(x)\|_{\infty} +\|\nabla \widetilde k_2(x)\|_{\infty} +\cdots+ \|\nabla \widetilde k_{i-1}(x)\|_{\infty}) ].
    \end{align}
If we define $T_j \coloneq \sum_{i=1} ^{j} \|\nabla \widetilde k_i(x)\|_{\infty}$, we see that 
    \begin{align*}
        T_j \leq \widetilde K ^{(1)} + (1+ \widetilde K ^{(1)} A_p H d) T_{j-1}.
    \end{align*}
Also, $\|\nabla \widetilde k_1(x)\|_{\infty} \leq \widetilde K ^{(1)}$.
So, 
    \begin{align}\label{e:iteration result}
        T_s \leq s \widetilde K ^{(1)} {(1+ \widetilde K ^{(1)} A_p H d)}^{s-1}.
    \end{align}
If $\widetilde K ^{(1)} A_p H d s 2^s \leq 1$, then the right hand side of \eqref{e:iteration result} is bounded by $s2^s \widetilde K^{(1)}$. We then put this term on the right hand side of \eqref{e:iteration growth}, we we obtain that for each $i \in \llbracket 1 , s \rrbracket$, $ \|\nabla  \widetilde  k_i(x) \|_{\infty} \leq 2 \widetilde K ^{(1)}$.

Similarly,
    \begin{align*}
        \|\nabla^2 \widetilde k_i(x)\|_{\infty} \leq \widetilde K ^{(2)} {(1+ A_p H d T_{i-1})}^{2} + \widetilde K ^{(1)}A_p H d (\|\nabla ^2 \widetilde k_1(x)\|_{\infty} +\cdots+ \|\nabla  ^2 \widetilde k_{i-1}(x)\|_{\infty}),
    \end{align*}
and then we define $T_j ' \coloneq \sum_{i=1} ^{j} \|\nabla ^2 \widetilde k_i(x)\|_{\infty}$. We see that
    \begin{align*}
        T_j ' \leq \widetilde K ^{(2)} {(1+ A_p H d T_{j-1})}^{2} + (1+ \widetilde K ^{(1)}A_p H d) {T_{j-1} '}.
    \end{align*}
Also, $\|\nabla ^2 \widetilde k_1(x)\|_{\infty} \leq \widetilde K ^{(2)}$. So,
    \begin{align*}
        T_s ' \leq \widetilde K ^{(2)} \sum_{i=1} ^{s} {(1+ A_p H d T_{i-1})}^{2} {(1+ \widetilde K ^{(1)}A_p H d)}^{s-i} \leq 2 \widetilde K ^{(2)} s^3 {(1+ \widetilde K ^{(1)}A_p H d)}^{2s}.
    \end{align*}
For the last inequality, we regard $\xi \coloneq \widetilde K ^{(1)}A_p H d$. Then, 
    \begin{align*}
        \begin{split}
            &\sum_{i=1} ^s {(1+(i-1)\xi(1+\xi)^{i-1})}^2 {(1+\xi)}^{s-i} \leq 2 \sum_{i=1} ^s \big[{(1+\xi)}^{s-i} + {(i-1)}^2 \xi^2 {(1+\xi)}^{s+i-2}\big]
            \\  &\leq 2s\big[{(1+\xi)}^{s-1} + {(s-1)}^2 \xi^2 {(1+\xi)}^{2s-2}\big] \leq 2s {(1+\xi)}^{2s-2} (1+s^2 \xi^2) \leq 2 s^3 {(1+\xi)}^{2s} .
        \end{split}
    \end{align*}


\end{proof}

\begin{proof}[Proof of \Cref{lemma: pth order growth in RK}]
    We only prove the statement for $\widetilde k_i(x)$'s and the proof for $\overline k_i(x)$'s is similar. We first notice that, according to \Cref{i:Vbound} of \Cref{p:ABCD}, for any $x\in \bR^d$ and $0\leq h\leq H$, $\|\widetilde V_{t+h}(x)\|_2 \leq \widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_2 $, and 
 $\| \nabla \widetilde V_{t+h}(x) \|_{op} \leq \widetilde L ^{(1)}$. Hence, $\|\widetilde k_1(x)\|_2 \leq \widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_2$, $\|\nabla \widetilde k_1(x)\|_{op} \leq \widetilde L ^{(1)}$ according to \eqref{eq:RK-update-k}. By the relation that $\widetilde k_i = \sV_{t + c_i H}\bigl(x + (a_{i1} \widetilde k_1 + a_{i2} \widetilde k_2 + \cdots + a_{i,i-1} \widetilde k_{i-1}) H\bigr)$, we obtain that
        \begin{align*}
            \begin{split}
                &\|\widetilde k_i (x)\|_{2} \leq \widetilde W ^{(0)} + \widetilde W ^{(1)}\|x\|_{2}+ \widetilde W ^{(1)} A_p H (\|\widetilde k_1(x)\|_{2} + \|\widetilde k_2(x)\|_{2} + \cdots + \|\widetilde k_{i-1}(x)\|_{2}),
                \\  & \| \nabla \widetilde k_i (x)\|_{op} \leq \widetilde L ^{(1)} (1+ A_p H (\|\widetilde \nabla k_1(x)\|_{op} + \|\widetilde \nabla k_2(x)\|_{op} + \cdots + \|\widetilde \nabla k_{i-1}(x)\|_{op})).
            \end{split}
        \end{align*}
    If we define $T_j \coloneq \sum_{i=1} ^j \|\widetilde k_i(x) \|_{2}$, $T_j ' \coloneq \sum_{i=1} ^j \|\nabla \widetilde k_i(x) \|_{op}$, we see that
    \begin{align*}
        \begin{split}
            &T_j \leq (\widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_{2}) + (1+ \widetilde W ^{(1)} A_p  H) T_{j-1}, \\ & T_j ' \leq \widetilde L ^{(1)}  + (1+ \widetilde L ^{(1)} A_p  H) T_{j-1} ' .
        \end{split}
    \end{align*} 
    Hence,
    \begin{align*}
        \begin{split}
            &T_s \leq {(1+ \widetilde W ^{(1)}A_p H)}^{s-1} \big[(s-1) {(\widetilde W ^{(0)} + \widetilde W ^{(1)}\|x\|_{2})} +  (\widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_2) \big] ,
            \\  & T_s ' \leq {(1+ \widetilde L ^{(1)}A_p H)}^{s-1} \big[(s-1) {\widetilde L ^{(1)}} +  {\widetilde L ^{(1)}} \big].
        \end{split}
    \end{align*}
Also, if $\widetilde W ^{(1)} A_p H s 2^s \leq 1$, we see that for each $i \in \llbracket 1, s \rrbracket$,
    \begin{align*}
        \begin{split}
            \|\widetilde k_i (x)\|_{2} &\leq \widetilde W ^{(0)} + \widetilde W ^{(1)}\|x\|_{2}+ \widetilde  W ^{(1)} A_p H (\|\widetilde  k_1(x)\|_{2} + \|\widetilde  k_2(x)\|_{2} + \cdots + \|\widetilde  k_{i-1}(x)\|_{2})
            \\  &\leq \widetilde W ^{(0)} + \widetilde W ^{(1)}\|x\|_{2}+ \widetilde  W^{(1)} A_p H s2^s \big[\widetilde W ^{(0)} + \widetilde W ^{(1)} \|x\|_2 \big] \leq 2(\widetilde W ^{(0)} + \widetilde W ^{(1)}\|x\|_{2}),
        \end{split}
    \end{align*}
and similarly, if $\widetilde L ^{(1)} A_p H s 2^s \leq 1$, 
    \begin{align*}
    \|\nabla \widetilde k_i(x) \|_{op} \leq 2\widetilde L ^{(1)}.
    \end{align*}

\end{proof}



\begin{proof}[Proof of \Cref{lemma: infinity norm for k_i(x)}]
    According to \Cref{Lemma: Hessian estimates}, we see that for any $t$ such that $T-t \geq \tau$, 
        \begin{align*}
            \|V_t(x)\|_{\infty} \leq (1+\sigma_{T-t} ^{-2})\|x\|_{\infty} + D\sigma_{T-t} ^{-2} \leq 2\tau ^{-1}\|x\|_{\infty} + D\tau ^{-1}.
        \end{align*}
    So, for any $i \in \llbracket 1, s \rrbracket$, by the relation that $\overline k_i = V_{t + c_i H}\bigl(x + (a_{i1} \overline k_1 + a_{i2} \overline k_2 + \cdots + a_{i,i-1} \overline k_{i-1}) H\bigr)$, we obtain that
        \begin{align*}
            \|\overline k_i (x)\|_{\infty} \leq \tau^{-1}(D + 2\|x\|_{\infty}) + 2\tau ^{-1}A_p H(\|\overline k_1 (x)\|_{\infty}+ \|\overline k_2 (x)\|_{\infty} + 
 \cdots + \|\overline k_{i-1} (x)\|_{\infty}).
        \end{align*}
By a similar strategy we used in \Cref{lemma: pth order growth in RK}, we see that
    \begin{align*}
        \sum_{i=1} ^s \|\overline k_i (x)\|_{\infty} \leq s\tau^{-1}{(1+2\tau ^{-1}A_p H)}^{s-1} \big[D + 2\|x\|_{\infty} \big].
    \end{align*}

Similarly, by \Cref{Lemma: Hessian estimates}, for any $t$ such that $T-t \geq \tau$, we see that
\begin{align*}
            \|V_t(x)\|_{2}  \leq 2\tau ^{-1}(\|x\|_{2} + \sqrt{d} D),
        \end{align*}
and then
    \begin{align*}
        \sum_{i=1} ^s \|\overline k_i (x)\|_{2} \leq 2s\tau^{-1}{(1+2\tau ^{-1}A_p H)}^{s-1} \big[\sqrt{d}D + \|x\|_{2} \big].
    \end{align*}
\end{proof}



\section{Proof of \Cref{Prop: Conclusion second error term}}\label{Section: second term conclusion}
In this section, we prove \Cref{Prop: Conclusion second error term}. Recall that both $t$ and $H$ are fixed. 
In our proofs, $H$ will also be chosen small such that for any $|h|<H$ and any $x \in \mathbb{R}^d$, as matrices, $\|(\nabla \baphi_h (x) ) ^{-1}\|_{op} \leq 2$ and $\|(\nabla \dphi_h (x) ) ^{-1}\|_{op} \leq 2$. We already illustrated how to choose suitably small $H$ in \Cref{lemma: phi_h invertible}. Similarly, we can assume that when $|h|<H$, as matrices, $\|(\nabla \baphi_h ^{-1})(y)\|_{op} \leq 2$ and $\|(\nabla \dphi_h ^{-1})(y)\|_{op} \leq 2$. This is because, for example, $\|(\nabla \dphi_h ^{-1})(y)\|_{op} = \|(\nabla \dphi_{h}  (\dphi_h ^{-1}(y) ) )^{-1}\|_{op} \leq 2$ for any $y \in \mathbb{R}^d$. Also, $\det[ \nabla (\baphi_h ^{-1}(x))]>0$ and $\det[ \nabla (\dphi_h ^{-1}(x))]>0$ for any $x \in \mathbb{R}^d$ when $|h| <H$.










We recall $I_2$ from \eqref{e:defI2}
    \begin{align}\label{e:defI2copy}
        I_2=\int_{\mathbb{R}^d} | \varrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| | \de x.
    \end{align}
We consider the interpolation map, which interpolates $\dphi_H ^{-1}(x)$ and $\baphi_H ^{-1}(x)$
\begin{align*}
    \varphi_s(x) \coloneq s\dphi_H ^{-1}(x) + (1-s)\baphi_H ^{-1}(x), \quad s\in [0,1].
\end{align*} 
So, $\varphi_0(x) = \baphi_H ^{-1}(x)$ and $\varphi_1(x)=\dphi_H ^{-1}(x)$. We first need to collect some growth estimates for $\varphi_s(x)$ similar to the second part of  \Cref{p:ABCD}.
\begin{lemma}\label{lemma: Growth of interpolation maps}
    Adopt the assumptions and notations in \Cref{p:ABCD}. Take $H$ small enough such that
        \begin{align*}
            H  (\widetilde B + \overline B + \widetilde C + \overline C + d(\widetilde D + \overline D)) <1/4.
        \end{align*}
   Let $\bm\al = 2 (\widetilde A + \overline A)$, $\bm\beta=2(\widetilde B + \overline B)$, $\bm \gamma=2(\widetilde C + \overline C)$, and $\bm\xi = 2 (\widetilde D + \overline D)$.
    Then, for any $s\in [0,1]$, $\varphi_s(x)$ is a diffeomorphism on $\mathbb{R}^d$, and the following holds $ \| \varphi_s(x) -x\|_2 \leq   H (\bm\alpha+ \bm\beta\|x\|_2)$, $\|\nabla \varphi_s(x) -\mathbb{I}_d \|_{\op} \leq \bm\gamma H$, $\|\nabla \varphi_s(x) -\mathbb{I}_d \|_{\infty} \leq \bm\xi H$. 
\end{lemma} 
\begin{proof}
    We only need to find out suitable estimates for $\varphi_0$ and $\varphi_1$, because $\varphi_s = s\varphi_1 + (1-s)\varphi_0$. We do this for $\varphi_1(x) = \dphi_H ^{-1}(x)$ first and the computations for $\varphi_0(x) = \baphi_H ^{-1}(x)$ are similar.

     By \Cref{p:ABCD}, $\|\dphi_H(x) - x\|_2 \leq H(\widetilde A + \widetilde B \|x\|_2)$. So, $\| x - \dphi_H ^{-1}(x) \|_2 \leq H(\widetilde A + \widetilde B \|\dphi_H ^{-1}(x)\|_2) \leq H(\widetilde A + \widetilde B \|\dphi_H ^{-1}(x) - x\|_2 + \widetilde B \|x \|_2)$. If we choose $H \widetilde B < 1/2$ at the beginning, then $\| x - \dphi_H ^{-1}(x) \|_2 \leq 2H (\widetilde A + \widetilde B \|x\|_2)\leq H(\bm\alpha+\bm\beta\|x\|_2)$, for $\bm\alpha\geq 2 (\widetilde A + \overline A)$ and $\bm\beta\geq2(\widetilde B + \overline B)$. 

     By \Cref{lemma: Growth of inverse matrix}, we also notice the following estimates $\|\nabla \dphi_H ^{-1}(x) -\mathbb{I}_d \|_{\op} = \big\|{[(\nabla \dphi_H) (\dphi_H ^{-1}(x))]}^{-1} -\mathbb{I}_d \big\|_{\op} \leq 2 \big\|{[(\nabla \dphi_H) (\dphi_H ^{-1}(x))]} -\mathbb{I}_d \big\|_{\op}  \leq 2H \widetilde C\leq 2\bm\gamma H$, for $\bm\gamma \geq 2 (\widetilde C + \overline C) $. Similarly, $\|\nabla \dphi_H ^{-1}(x) -\mathbb{I}_d \|_{\infty} \leq 2H \widetilde D\leq \bm\xi H$ provided  $\bm\xi= 2 (\widetilde D + \overline D) $ and $2\bm\xi< 1/d$.

\end{proof}

Because we can choose $H$ small at the beginning such that all $\varphi_s$'s are diffeomorphisms and $\det[ \nabla (\varphi_s(x))] >0$ for $s \in [0,1]$. So, $I_2$ (recall from \eqref{e:defI2copy}) becomes
    \begin{align}\label{e: interpolation error in second term}
        \begin{split}
            &\int_{\mathbb{R}^d} | \varrho_t(\varphi_0(x)) \cdot  \det[ \nabla (\varphi_0(x))] - \varrho_t(\varphi_1(x)) \cdot  \det[ \nabla (\varphi_1(x))]| \de x
            \\  &\leq \int_0 ^1 \int_{\mathbb{R}^d} \bigg| \frac{d}{ds}  \bigg(\varrho_t(\varphi_s(x)) \cdot  \det[ \nabla (\varphi_s(x))] \bigg)\bigg| \de x \de s
           \leq J_1+J_2.
        \end{split}
    \end{align}
where 
\begin{align}\begin{split}\label{e:defJ1J2}
    &J_1:=\int_0 ^1 \int_{\mathbb{R}^d} \bigg| (\nabla \varrho_t) (\varphi_s(x)) \cdot (\varphi_1(x) - \varphi_0(x)) \det[ \nabla (\varphi_s(x))]\bigg| \de x \de s. \\
    &J_2:=\int_0 ^1 \int_{\mathbb{R}^d}\bigg| \varrho_t(\varphi_s(x)) \cdot \trace \bigg( \bigg( \nabla [\varphi_1(x) - \varphi_0(x)] \bigg) \cdot {(\nabla \varphi_s(x) )}^{-1} \bigg) \det[ \nabla \varphi_s(x)] \bigg| \de x \de s .
\end{split}\end{align}





\subsection{Estimates of $J_1$}
To proceed, we need the following argument to compare two expectations with respect to $\varrho_t$. We postpone the  proofs of \Cref{lemma: score error cut-off general scheme} and \Cref{lemma: exponential error term in cut-off} to \Cref{app:proofs}.
\begin{lemma}\label{lemma: score error cut-off general scheme}
    Assume that $\psi_1,\psi_2$ are two diffeomorphisms on $\mathbb{R}^d$, such that $ \| \psi_1(x) -x\|_2 \leq  H (\bm\al_1 + \bm\beta_1\|x\|_2)$, $\|\nabla\psi_1(x)-x\|_\infty\leq \bm\xi_1 H$,   $ \| \psi_2(x) -x\|_2 \leq  H (\bm\al_2+  \bm\beta_2\|x\|_2)$ and  $\|\nabla\psi_2(x)-x\|_\infty\leq \bm\xi_2 H$ with positive constants $\bm\al_1, \bm\al_2, \bm\beta_1, \bm\beta_2, \bm\xi_1,\bm\xi_2$. We also assume that $Z(x)$ is a map from $\mathbb{R}^d \to \mathbb{R}^d$ such that $\|Z(x)\|_2 \leq A + B\|x\|_2 ^m$, where $m \in \mathbb{Z}_+$. Let $\eta >1$ be a constant. Then, if $H$ satisfies that
        \begin{align}\label{e: H in cut-off scheme}
            100 H \big[(\bm\al_1+\bm\al_2)(\sqrt{d}D + \eta \sigma_{T-t})+(\bm\beta_1+\bm\beta_2)(\sqrt{d}D + \eta \sigma_{T-t})^2+d(\bm\xi_1+\bm\xi_2) \big]  \leq \sigma_{T-t} ^2,
        \end{align}
we have that
        \begin{align*}
            \int_{\mathbb{R}^d}    \varrho_{t}(\psi_1(x)) \big\| Z(x)\big\|_2  \de x
    &\leq   3\int_{\mathbb{R}^d}    \varrho_{t}(\psi_2(x)) \big\| Z(x) \big\|_2 \de x  + 8^m E(m,A,B,\eta),
        \end{align*}
    where $E(m,A,B,\eta)$ is an exponentially small term defined as
        \begin{align*}
            E(m,A,B,\eta) \coloneq \int_{\|z\|_2\geq 2\eta} \frac{1}{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|^2}{2}} [(A+2B{(\sqrt{d}D)}^m) + B {(\|z\|_2)} ^m] \de z.
        \end{align*}
\end{lemma}



We need the following lemma for the  $E(m,A,B,\eta)$ term in \Cref{lemma: score error cut-off general scheme}.


\begin{lemma}\label{lemma: exponential error term in cut-off}
    Let $a$ be a positive constant and $b$ be a positive integer. Assume that $a^2 >  (b-1)$. Then, there is a universal constant $C_u$ such that
    \begin{align}\label{e:exponential tail of Gaussian}
        \int_{r \geq a} e^{-r ^2} r^b \de r \leq a^{b-1} e^{-a^2}.
    \end{align}
    As a corollary, in \Cref{lemma: score error cut-off general scheme}, we take $\eta = 10^{-2} (\bm\beta_1+\bm\beta_2)^{-1} H^{-1/2}$ and assume that 
    \begin{align}\label{e: H in cut-off scheme 1}
            H \leq (2d \log (2d))^{-1} 10^{-6} (\bm\beta_1+\bm\beta_2)^{-2}
        \end{align}
    and 
        \begin{align}\label{e: H in cut-off scheme 2}
            10^3 H \big[(\bm\al_1+\bm\al_2)\sqrt{d}D+(\bm\beta_1+\bm\beta_2)dD^2+d(\bm\xi_1+\bm\xi_2) \big] + H^{\frac{1}{2}} \frac{\bm\al_1+\bm\al_2}{\bm\beta_1+\bm\beta_2} \sigma_{T-t} \leq \sigma_{T-t} ^2.
        \end{align}
    Then, \eqref{e: H in cut-off scheme 1} and \eqref{e: H in cut-off scheme 2} imply \eqref{e: H in cut-off scheme} in \Cref{lemma: score error cut-off general scheme}. Also, under the assumption \eqref{e: H in cut-off scheme 1} only, we can deduce that for $m=1,2,3$, the error term $E(m,A,B,\eta)$ satisfies that 
    \begin{align*}
        E(m,A,B, \eta) \leq {4^m(A+B \sqrt{d}D)}^m \pi^{-\frac{d}{2}} e^{- 10^{-4} (\bm\beta_1+\bm\beta_2)^{-2} H^{-1}}.
    \end{align*}
\end{lemma}







In Lemma~\ref{lemma: score error cut-off general scheme}, we particularly want to let $\psi_2(x)$ be some $\phi_h ^{-1}(x)$'s, for $0<h < H $, because $\del_h \phi_h(y)=V_{t+h}(\phi_h(y))$ with $\phi_{0}(y) = y$ for $y \in \mathbb{R}^d$, and $\varrho_{t+h} (x)= \varrho_{t} (\phi_h ^{-1}(x)) \cdot  \det[ \nabla (\phi_h ^{-1}(x))] $. So, we need to collect some growth estimates for $\phi_h (x)$ and $\phi_h ^{-1}(x)$ like \Cref{lemma: Growth of interpolation maps}.

\begin{lemma}\label{lemma: Growth of the original phi_h map}
   Adopt the assumptions and notations in \Cref{p:ABCD}. Take $H$ small enough such that $H  \cdot (\overline W ^{(1)} + \overline L ^{(1)} + d \overline K ^{(1)}) < 1/100$. Then, for $h < H$,
        \begin{align*}
            \begin{split}
                &\|x - \phi_h(x)\|_2 \leq 4 h {( \overline W ^{(0)} +  \overline W ^{(1)} \|x\|_2)}, \quad \|x - \phi_h ^{-1} (x)\|_2 \leq 8 h {( \overline W ^{(0)} +  \overline W ^{(1)} \|x\|_2)},
                \\  & \| \nabla \phi_{h} (x) -\mathbb{I}_d \|_{\op} \leq 4 \overline L ^{(1)} h, \quad \|(\nabla \phi_{h} ^{-1})(x) -\mathbb{I}_d \|_{\op} \leq 8 \overline L ^{(1)} h,
                \\  & \|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty} \leq 2 \overline K ^{(1)}h, \quad \|(\nabla \phi_{h} ^{-1})(x) -\mathbb{I}_d \|_{\infty} \leq 4 \overline K ^{(1)}h,
                \\  & 0<e^{-8  \overline K ^{(1)} hd} \leq  \det [\nabla \phi_{h}  (x)]  \leq e^{4  \overline K ^{(1)} hd} ,\quad 0< e^{-4  \overline K ^{(1)} hd} \leq  \det [\nabla \phi_{h} ^{-1} (x)] \leq e^{8  \overline K^{(1)} hd},
            \end{split}
        \end{align*}
    for any $x \in \mathbb{R}^d$.
\end{lemma}
\begin{proof}
    By definition, $\del_h \phi_h(y)=V_{t+h}(\phi_h(y))$ with $\phi_{0}(y) = y$ for $y \in \mathbb{R}^d$. For $h < H$,
    \begin{align*}
            \bigg | \frac{d}{dh} \|x - \phi_h(x)\|_2 ^2 \bigg | = \bigg | 2 V_{t+h}(\phi_h(x)) \cdot (\phi_h(x) - x) \bigg | \leq 2 ( \overline W ^{(0)} + \overline W ^{(1)} \|\phi_h(x)\|_2) \|x - \phi_h(x)\|_2.
    \end{align*}
    So, 
    \begin{align*}
            \bigg | \frac{d}{dh} \|x - \phi_h(x)\|_2 \bigg | \leq 2 (\overline W ^{(0)} +  \overline W ^{(1)} \|\phi_h(x)\|_2) \leq 2 \overline W ^{(1)} \|\phi_h(x)- x\|_2 + 2 ( \overline W ^{(0)} +  \overline W ^{(1)} \|x\|_2).
    \end{align*}
    Hence, for $h<H$,
        \begin{align*}
            \|x - \phi_h(x)\|_2 \leq \frac{e^{(2  \overline W ^{(1)} )h} - 1}{  \overline W ^{(1)} } {( \overline W ^{(0)} +  \overline W ^{(1)} \|x\|_2)} \leq e^{(2 \overline W^{(1)} )h} (2h  ){( \overline W ^{(0)} +  \overline W ^{(1)} \|x\|_2)}.
        \end{align*}
    Because $H  \cdot  \overline W ^{(1)} < 1/100$, we can obtain that $\|x - \phi_h(x)\|_2 \leq 4h {( \overline W ^{(0)} + \overline W ^{(1)} \|x\|_2)}$ for any $x \in \mathbb{R}^d$. Hence,  $\|x - \phi_h ^{-1}(x)\|_2 \leq 4 h {( \overline W ^{(0)} + \overline W ^{(1)} \|\phi_h ^{-1}(x)\|_2)} \leq 4 h {( \overline W ^{(0)} + \overline W ^{(1)}\|x\|_2 +  \overline W ^{(1)} \|\phi_h ^{-1}(x)-x\|_2)}$.  
    Because $H  \cdot \overline W ^{(1)} < 1/100$, we can obtain that $\|x - \phi_h ^{-1} (x)\|_2 \leq 8 h {( \overline W ^{(0)} + \overline W ^{(1)} \|x\|_2)}$ for any $x \in \mathbb{R}^d$.

    Next, we need to find a suitable bound for $\|\nabla \phi_h(x) -\mathbb{I}_d \|_{\op}$. Again, by definition, $\del_h \phi_h(y)=V_{t+h}(\phi_h(y))$ with $\phi_{0}(y) = y$ for $y \in \mathbb{R}^d$. For any fixed vector $v \in \mathbb{R}^d$ with $\|v\|_2 =1$, we see that
    \begin{align*}
        \begin{split}
            &\partial_h (\nabla \phi_h(y) \cdot v - v) = (\nabla V_{t+h})(\phi_h(y)) \cdot \nabla \phi_h(y) \cdot v \\ &= (\nabla V_{t+h})(\phi_h(y)) \cdot (\nabla \phi_h(y) \cdot v - v) + (\nabla V_{t+h})(\phi_h(y)) \cdot v.
        \end{split}
    \end{align*}
By considering the derivative of $\|\nabla \phi_h(y) \cdot v - v\|_2 ^2$, and the fact that $\|\nabla V_{t+h}(x) \|_{op} \leq \overline L ^{(1)} $ for any $x \in \mathbb{R}^d$, one can obtain that
    \begin{align*}
        \del_h \|\nabla \phi_h(y) \cdot v - v\|_2 \leq 2\overline L ^{(1)}  (\|\nabla \phi_h(y) \cdot v - v\|_2 + 1).
    \end{align*}
Hence, since $H \cdot \overline L ^{(1)} < 1/100$, we obtain that for any $h<H$,
    \begin{align*}
        \|\nabla \phi_h(y) \cdot v - v\|_2 \leq 4 \overline L ^{(1)}  \cdot h.
    \end{align*}
Hence, $\|\nabla \phi_{h}(y) -\mathbb{I}_d \|_{op} \leq 4 \overline L ^{(1)} h$ for any $y \in \mathbb{R}^d$. By Lemma~\ref{lemma: Growth of inverse matrix}, because $H  \cdot \overline L ^{(1)} < 1/100$, we see that $\|\nabla (\phi_{h} ^{-1}(y)) -\mathbb{I}_d \|_{op} = \|{(\nabla \phi_{h} (\phi_{h} ^{-1}(y)))}^{-1} -\mathbb{I}_d \|_{op} \leq 8 \overline L ^{(1)} h$ for any $y \in \mathbb{R}^d$.

For $\|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty}$, we consider the evolution of $\partial_i \phi_h ^{(j)} (x) - \delta_{ij}$ for arbitrary $i,j \in \llbracket 1 , d \rrbracket$. We see that
    \begin{align*}
        \begin{split}
            &\del_h |\partial_i \phi_h ^{(j)}(x) - \delta_{ij}| \leq |\del_h (\partial_i \phi_h ^{(j)}(x) - \delta_{ij})| = \bigg | \sum_{k=1} ^d \partial_i \phi_h ^{(k)} (x) \partial_k V_{t+h} ^{(j)}(\phi_h(x)) \bigg| 
            \\  &= \bigg| \partial_i V_{t+h} ^{(j)}(\phi_h(x))+ \sum_{k=1} ^d (\partial_i \phi_h ^{(k)} (x) - \delta_{ik}) \partial_k V_{t+h} ^{(j)}(\phi_h(x)) \bigg|
            \\  &\leq \overline K ^{(1)} \bigg(1+ \sum_{k=1} ^d |\partial_i \phi_h ^{(k)} (x) - \delta_{ik}|\bigg)\leq \overline K ^{(1)} (1+ d\|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty}).
        \end{split}
    \end{align*}
Hence,
    \begin{align*}
        \del_h  \|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty} \leq \overline K ^{(1)} d\|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty} + \overline K ^{(1)}.
    \end{align*}
Hence, for $h <H$, we have that 
    \begin{align*}
        \|\nabla \phi_{h}(x) -\mathbb{I}_d \|_{\infty} \leq \frac{e^{(\overline K ^{(1)} d)h} - 1}{  d}   \leq e^{(\overline K ^{(1)} d)h} (\overline K ^{(1)}h  ) \leq 2 \overline K ^{(1)}h ,
    \end{align*}
where the last inequality is because $H  \cdot d \overline K ^{(1)} < 1/100$.
\end{proof}

Now, we are able to estimate $J_1$ from \eqref{e:defJ1J2}. 

\begin{lemma}\label{lemma: interpolation error term 1}
Adopt the assumptions and notations in \Cref{lemma: Growth of interpolation maps}. If $H >0$ is small such that 
\begin{align*}
            400 H \big[\bm\al (\sqrt{d}D + \eta \sigma_{T-t})  + \bm\beta (\sqrt{d}D + \eta \sigma_{T-t})^2 + \bm\xi d\big]   \leq \sigma_{T-t} ^2,
    \end{align*}
then,
        \begin{align*}
            \begin{split}
            &J_1=\int_0 ^1 \int_{\mathbb{R}^d} \bigg| (\nabla \varrho_t) (\varphi_s(x)) \cdot (\varphi_1(x) - \varphi_0(x)) \det[ \nabla (\varphi_s(x))] \bigg| \de x \de s
        \\          
                & \leq\frac{10^3 }{({\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (x) \cdot \big(   \sqrt{d} D+  \|x\|_2 \big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x \\   & \quad +\frac{10^4 }{({\sigma_{T-t})}^2} E(1,H\sqrt{d} D(\widetilde A + \overline A),H(\widetilde A + \overline A) + H\sqrt{d} D (\widetilde B + \overline B),\eta)
                \\  & \quad +\frac{10^5 }{({\sigma_{T-t})}^2} E(2,0, H(\widetilde B + \overline B), \eta) .
            \end{split}
        \end{align*}   
\end{lemma}
\begin{proof}
    According to Lemma~\ref{Lemma: Hessian estimates}, we see that $\|\nabla \log \varrho_t (y)\|_2 \leq \frac{2}{{\sigma_{T-t}}^2}(\|y\|_2 + \sqrt{d}D)$ for any $y \in \mathbb{R}^d$. $\big\| {(\dphi_H ^{-1})}(x) - {(\baphi_H ^{-1})}(x)\big\|_{2} \leq 2 \big\| {(\baphi_H \circ \dphi_H ^{-1})}(x) - x\big\|_{2}$ because $\| \nabla \baphi_H ^{-1} (y)\|_{op} = \| {(\nabla \baphi_H(\baphi_H ^{-1}(y)))}^{-1} \|_{op}  \leq 2$ for any $y \in \mathbb{R}^d$. Hence, for any $s \in [0,1]$,
        \begin{align}\label{e: interpolation error step 1}
            \begin{split}
                &\int_{\mathbb{R}^d} \bigg| (\nabla \varrho_t) (\varphi_s(x)) \cdot (\varphi_1(x) - \varphi_0(x)) \det[ \nabla (\varphi_s(x))] \bigg| \de x
                \\  &\leq \frac{4}{{(\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (\varphi_s(x)) \cdot \big( \|\varphi_s(x)\|_2 + \sqrt{d} D\big) \cdot \big\| {(\baphi_H \circ \dphi_H ^{-1})}(x) - x\big\|_{2}  \big| \det[ \nabla (\varphi_s(x))] \big| \de x 
                \\  &\leq \frac{4}{{(\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (\varphi_s(\dphi_H(x))) \cdot \big( \|\varphi_s(\dphi_H(x))\|_2 + \sqrt{d} D\big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2  \big| \det[ \nabla (\varphi_s(\dphi_H(x)))] \big| \de x .
            \end{split}
        \end{align}
    Notice that, by Lemma~\ref{lemma: Growth of interpolation maps}, $\|\varphi_s(\dphi_H(x)) - x\|_2 \leq \|\varphi_s(\dphi_H(x)) - \dphi_H(x)\|_2 + \|\dphi_H(x) - x\|_2 \leq  H(\bm\alpha+ \bm\beta\|\dphi_H(x)\|_2) + \|\dphi_H(x) - x\|_2 \leq  H(\bm\alpha + \bm\beta\|x\|_2) + (1+ \bm\beta H)\|\dphi_H(x) - x\|_2 \leq  H(\bm\alpha +\bm\beta \|x\|_2) + H(1+ \bm\beta H)(\widetilde A + \widetilde B \|x\|_2) = H[\bm\alpha + (1+ \bm\beta H)\widetilde A + (\bm\beta + (1+ \bm\beta H)  \widetilde B) \|x\|_2] \leq 4 H[\bm\alpha +   \bm\beta\|x\|_2]$, where we used the choice of $H$ in Lemma~\ref{lemma: Growth of interpolation maps} to get $(1+ \bm\beta H) \leq 2$. By Lemma~\ref{lemma: Growth of interpolation maps} again, $\|\nabla \varphi_s(\dphi_H(x)) \cdot \nabla \dphi_H(x) -\mathbb{I}_d \|_{\infty} \leq \bm\xi H \|\nabla \dphi_H(x)\|_{\infty} + \|\nabla \dphi_H(x) - \mathbb{I}_d \|_{\infty} \leq \bm\xi H + (1+ \bm\xi H) \|\nabla \dphi_H(x) - \mathbb{I}_d \|_{\infty} \leq (\bm\xi+ (1+ \bm\xi H)  \widetilde D)H \leq 3 \bm\xi H $,  where by the assumption of $H$, we have that $(1+ \bm\xi H) \leq 2$. According to the proof of Lemma~\ref{lemma: Growth of inverse matrix}, we see that $\big| \det[ \nabla (\varphi_s(\dphi_H(x)))] \big| \leq e ^ {6 \bm\xi Hd} \leq 5$ by the assumption on $H$.

    So, \eqref{e: interpolation error step 1} can be bounded by
        \begin{align*}
            \frac{80}{({\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (\varphi_s(\dphi_H(x))) \cdot \big( (H\bm\alpha  + \sqrt{d} D)+ (1+\bm\beta H) \|x\|_2 \big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x .
        \end{align*}
        If we choose $H$ such that
            \begin{align*}
            200 H \big[\bm\alpha  + \bm\beta(\sqrt{d}D + \eta \sigma_{T-t}) \big] \leq \sigma_{T-t},
        \end{align*}
        where $\eta >1$ is a constant, then the above equation can be further bounded by
            \begin{align*}
            \frac{200}{({\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (\varphi_s(\dphi_H(x))) \cdot \big(   \sqrt{d} D+  \|x\|_2 \big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x .
        \end{align*}
    We also see that $\|\baphi_H(x) - \dphi_H(x)\|_2 \leq \|\baphi_H(x) - x\|_2+ \|\dphi_H(x) - x\|_2 \leq H((\widetilde A + \overline A) + (\widetilde B + \overline B) \|x\|_2 )$. Hence, by Lemma~\ref{lemma: score error cut-off general scheme} and the growth of $\varphi_s(\dphi_H(x))$, i.e., $\|\varphi_s(\dphi_H(x)) - x\|_2 \leq 4 H[\bm\alpha +   \bm\beta\|x\|_2]$ we obtained above, the above equation can be further bounded by
        \begin{align*}
            \begin{split}
                &\frac{10^3 }{({\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (x) \cdot \big(   \sqrt{d} D+  \|x\|_2 \big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x \\   &+\frac{10^4 }{({\sigma_{T-t})}^2} E(1,H\sqrt{d} D(\widetilde A + \overline A),H(\widetilde A + \overline A) + H\sqrt{d} D (\widetilde B + \overline B),\eta)
                \\  &+\frac{10^5 }{({\sigma_{T-t})}^2} E(2,0, H(\widetilde B + \overline B), \eta) .
            \end{split}
        \end{align*}
\end{proof}

\subsection{Estimates of $J_2$}
For the other term $J_2$ in \eqref{e:defJ1J2}, we have the following lemmas.
\begin{lemma}\label{lemma: trace term in interpolation maps}
Adopt the assumptions and notations in \Cref{lemma: Growth of interpolation maps}.
    For any $x\in \mathbb{R}^d$ and any $s \in [0,1]$,
    \begin{align*}
        \begin{split}
            &\bigg| \trace \big[ \big( \nabla [\varphi_1(x) - \varphi_0(x)] \big) \cdot {(\nabla \varphi_s(x) )}^{-1} \big] \bigg|
        \\  & \leq 20d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty}\big\| {(\baphi_H \circ \dphi_H ^{-1})}(x) - x\big\|_{2} + 20\sum_{i=1} ^d \sum_{j=1} ^d \big| \partial_i \dphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) \big|. 
        \end{split}
    \end{align*}
\end{lemma}
\begin{proof}
    Notice that $\nabla \varphi_1(x) = \nabla \dphi_H ^{-1}(x) = {(\nabla \dphi_H(\dphi_H ^{-1}(x)))}^{-1}$, which we can denote as $Q_1 ^{-1}$. Similarly, we denote $\nabla \varphi_0(x)$ as $Q_0 ^{-1}$ and denote ${(\nabla \varphi_s(x) )}^{-1}$ as $Q_s$.
        \begin{align*}
            \trace [(Q_1 ^{-1} - Q_0 ^{-1}  ) Q_s] = \trace [Q_1 ^{-1} (Q_0  - Q_1  ) Q_0 ^{-1} Q_s] = \trace [(Q_0  - Q_1  ) Q_0 ^{-1} Q_s Q_1 ^{-1} ].
        \end{align*}
By our assumption, $\|{(\nabla \dphi_H(y))}^{-1}\|_{op} \leq 2$ and $\|{(\nabla \baphi_H(y))}^{-1}\|_{op} \leq 2$ for any $y \in \mathbb{R}^d$. By the choice of $H$ in Lemma~\ref{lemma: Growth of interpolation maps}, $\bm\gamma H < 1/2$. It follows from Lemma~\ref{lemma: Growth of inverse matrix} that $\|{(\nabla \varphi_s(x) )}^{-1}\|_{op} \leq 2$. If we denote the matrix $Q_0 ^{-1} Q_s Q_1 ^{-1}$ as $P$, we see that $\|P\|_{op} \leq 8$, and then each of its element, say $P_{ij}$, satisfies $|P_{ij}| \leq 8$. Hence, $\big|\trace [(Q_0  - Q_1  )P ] \big| \leq 8 \sum_{i=1} \sum_{j=1} |{(Q_0  - Q_1  )}_{ij}|$. We also notice that, since $\| \nabla \baphi_H ^{-1} (y)\|_{op} = \| {(\nabla \baphi_H(\baphi_H ^{-1}(y)))}^{-1} \|_{op}  \leq 2$ for any $y \in \mathbb{R}^d$, 
    \begin{align*}
        \begin{split}
            &|{(Q_0  - Q_1  )}_{ij}| \leq \big| \partial_i \dphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) \big| + \big| \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\baphi_H ^{-1}(x)) \big|
            \\  & \leq \big| \partial_i \dphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) \big| + \|\nabla^2 \baphi_H \|_{\infty}\sum_{k=1} ^d \big| {(\dphi_H ^{-1})}^{(k)}(x) - {(\baphi_H ^{-1})}^{(k)}(x)\big|
            \\  & \leq \big| \partial_i \dphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) \big| + \sqrt{d}\|\nabla^2 \baphi_H \|_{\infty}\big\| {(\dphi_H ^{-1})}(x) - {(\baphi_H ^{-1})}(x)\big\|_{2}
            \\  & \leq \big| \partial_i \dphi_H ^{(j)} (\dphi_H ^{-1}(x)) - \partial_i \baphi_H ^{(j)} (\dphi_H ^{-1}(x)) \big| + 2\sqrt{d}\|\nabla^2 \baphi_H \|_{\infty}\big\| {(\baphi_H \circ \dphi_H ^{-1})}(x) - x\big\|_{2}.
        \end{split}
    \end{align*}


\end{proof}




\begin{lemma}\label{lemma: interpolation error term 2}
Adopt the assumptions and notations in \Cref{lemma: Growth of interpolation maps}. If $H >0$ is small such that
\begin{align*}
            4000 H \big[\bm\alpha (\sqrt{d}D + \eta \sigma_{T-t}) + \bm\beta(\sqrt{d}D + \eta \sigma_{T-t})^2 + \bm\xi d \big] \leq \sigma_{T-t}^2,
    \end{align*}
then,
    \begin{align*}
        \begin{split}
            &J_2= \int_0 ^1 \int_{\mathbb{R}^d} \varrho_t(\varphi_s(x)) \bigg| \trace \bigg( \bigg( \nabla [\varphi_1(x) - \varphi_0(x)] \bigg) \cdot {(\nabla \varphi_s(x) )}^{-1} \bigg) \det[ \nabla \varphi_s(x)] \bigg| \de x \de s
            \\  &\leq 600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty} \int_{\mathbb{R}^d} \varrho_t(x)   \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x 
            + 600\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \\    & + 1600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty}E(1,H (\widetilde A + \overline A),H (\widetilde B + \overline B), \eta) + 1600 d^2 E(1,H (\widetilde D + \overline D),0, \eta).
        \end{split}
    \end{align*}
\end{lemma}

\begin{proof}

By change of variables, we see that $J_2$ equals to
    \begin{align*}
        \begin{split}
            &\int_0 ^1 \int_{\mathbb{R}^d} \varrho_t(\varphi_s(\dphi_H(x))) \bigg| \trace \bigg( \bigg( [(\nabla \varphi_1)( \dphi_H(x)) - (\nabla \varphi_0)(\dphi_H(x))] \bigg) \cdot {[(\nabla \varphi_s)(\dphi_H(x) )]}^{-1} \bigg) 
            \\  & \quad \cdot \det[ \nabla (\varphi_s  (\dphi_H (x)))] \bigg| \de x \de s.
        \end{split}
    \end{align*}
By the proof of Lemma~\ref{lemma: interpolation error term 1}, 
$\big| \det[ \nabla (\varphi_s(\dphi_H(x)))] \big| \leq e ^ {6\bm\xi Hd} \leq 10$ according to the assumption on $H$. Together with Lemma~\ref{lemma: trace term in interpolation maps}, the above equation is bounded by
    \begin{align*}
        \begin{split}
            &200 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty} \int_0 ^1 \int_{\mathbb{R}^d} \varrho_t(\varphi_s(\dphi_H(x)))   \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x \de s
            \\  &+ 200\sum_{i=1} ^d \sum_{j=1} ^d \int_0 ^1 \int_{\mathbb{R}^d} \varrho_t(\varphi_s(\dphi_H(x))) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \de s. 
        \end{split}
    \end{align*}
We have seen that $\|\baphi_H(x) - \dphi_H(x)\|_2 \leq \|\baphi_H(x) - x\|_2+ \|\dphi_H(x) - x\|_2 \leq H((\widetilde A + \overline A) + (\widetilde B + \overline B) \|x\|_2 )$. Also, $\big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \leq H (\widetilde D + \overline D)$. In the proof of Lemma~\ref{lemma: interpolation error term 1}, we showed that $\|\varphi_s(\dphi_H(x)) - x\|_2 \leq 4 H[\bm\alpha+  \bm\beta\|x\|_2]$. Hence, by Lemma~\ref{lemma: score error cut-off general scheme}, the above term can be bounded by
    \begin{align*}
        \begin{split}
            &600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty} \int_{\mathbb{R}^d} \varrho_t(x)   \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x 
            + 600\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \\    & + 1600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty}E(1,H (\widetilde A + \overline A),H (\widetilde B + \overline B), \eta) + 1600d^2 E(1,H (\widetilde D + \overline D),0, \eta),
        \end{split}
    \end{align*}
    provided that 
    \begin{align*}
            4000 H \big[\bm\alpha (\sqrt{d}D + \eta \sigma_{T-t}) + \bm\beta(\sqrt{d}D + \eta \sigma_{T-t})^2 \big] \leq \sigma_{T-t} ^2,
    \end{align*}
    according to Lemma~\ref{lemma: score error cut-off general scheme}.


\end{proof}


\subsection{Estimates of $I_2$}
Combine \eqref{e: interpolation error in second term}, Lemma~\ref{lemma: interpolation error term 1}, and Lemma~\ref{lemma: interpolation error term 2}, we see that $I_2$ from  \eqref{e:defI2}
can be bounded by 
\begin{align}\begin{split}\label{e:I2bb}
&I_2 \leq J_1+J_2      
                 \leq\frac{10^3 }{({\sigma_{T-t})}^2} \int_{\mathbb{R}^d} \varrho_t (x) \cdot \big(   \sqrt{d} D+  \|x\|_2 \big) \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x \\  
                &+600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty} \int_{\mathbb{R}^d} \varrho_t(x)   \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x+ 600\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \\
                &  +\frac{10^4 }{({\sigma_{T-t})}^2} E(1,H\sqrt{d} D(\widetilde A + \overline A),H(\widetilde A + \overline A) + H\sqrt{d} D (\widetilde B + \overline B),\eta)
                +\frac{10^5 }{({\sigma_{T-t})}^2} E(2,0, H(\widetilde B + \overline B), \eta) \\
                &+ 1600 d^{\frac{5}{2}}\|\nabla^2 \baphi_H \|_{\infty}E(1,H (\widetilde A + \overline A),H (\widetilde B + \overline B), \eta) + 1600 d^2 E(1,H (\widetilde D + \overline D),0, \eta).
\end{split}\end{align}
which involves terms in the following forms
    \begin{align}\begin{split}\label{e:three_term}
        &\int_{\mathbb{R}^d} \varrho_t(x)   \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x, \\
    & \int_{\mathbb{R}^d} \varrho_t(x)  \|x\|_2 \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x ,  \\ &\int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x,
   \end{split} \end{align}
and exponentially small terms $E$'s. For these exponentially small terms $E$'s, we use the fact that $\sigma_{T-t}^2 \geq C_u (T-t) \geq C_u \tau$, the bound of $\|\nabla^2 \baphi_H \|_{\infty} \leq 48 H B_p s^3 4^s D^3/\tau^3$ from \Cref{lemma: Constant Convention} and \Cref{lemma: Constant Convention1},  and use \Cref{lemma: exponential error term in cut-off}, we can bound the exponentially small terms in \eqref{e:I2bb} as
\begin{align}\label{e:I2bb2}
    C(s,A_p, B_p ,\widetilde K, \widetilde W) \cdot \frac{d^2 H D^4}{\tau^4}\cdot \pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 (4\bm\beta)^{2} H} },
\end{align}
provided the assumption \eqref{e:Hcondition} for $H$ holds. Here,  $\bm\beta$ is defined in \Cref{lemma: Growth of interpolation maps}. This is because we choose $\eta = 10^{-2} (4\bm\beta)^{-1} H^{-1/2}$ in \Cref{lemma: exponential error term in cut-off}, and \eqref{e:Hcondition} implies that $H \leq (2d \log (2d))^{-1} 10^{-6} (4\bm\beta)^{-2}$.

In the rest of the subsection, we estimate these three terms in \eqref{e:three_term}. Since $\dphi_h(y) = y + h \dM_t(y)$ and $\baphi_h(y) = y + h \baM_t(y)$, the term $\|  \baphi_H (x) - \dphi_H(x) \|_{2}$ reduces to estimates on $\|\dM_t (x) - \baM_t(x)\|_2$. For the term $\int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x$, notice that
    \begin{align*}
        \begin{split}
            \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x &\leq \int_{\mathbb{R}^d} \big|\partial_i\varrho_t(x) \big| \cdot \big|  \dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x) \big| \de x 
            \\  & \quad + \int_{\mathbb{R}^d}  \big| \partial_i \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x,
        \end{split}
    \end{align*}
where we can estimate $|\partial_i\varrho_t(x)|$ by $|\varrho_t(x)| \sigma_{T-t} ^{-2} (|x_i| + \lambda_{T-t} D)$ according to Lemma~\ref{Lemma: Hessian estimates}, and we can estimate the term $\int_{\mathbb{R}^d}  \big| \partial_i \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x$ by $\int_{\mathbb{R}^d}  \big|  \varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x)) \big| \de x$ multiplying $\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x$, according to the Gagliardo-Nirenberg inequality Lemma~\ref{lemma: Gagliardo-Nirenberg}.

\begin{lemma}\label{lemma: Second derivative bound on errors}
   Adopt the assumptions and notations in \Cref{p:ABCD}. Take $H$ small enough such that
    \begin{align*}
        H \cdot d A_p(\overline K ^{(1)} + \widetilde K ^{(1)}) \leq 1/10.  
    \end{align*}
Then, there is a universal constant $C_u >0$, such that
        \begin{align*}
            \begin{split}
                &\quad \sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \\   &\leq \frac{C_u  d}{\sigma_{T-t} ^2} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \int_{\mathbb{R}^d}   \varrho_t(x) (\|x\|_2 ^2 + dD^2) \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x \bigg)}^{\frac{1}{2}} 
            \\ &+   \frac{C_u {H}^{\frac{1}{2}} d^{\frac{7}{4}} {B_p}^{\frac{1}{2}}}{\sigma_{T-t}} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}} {\big[  D   (\widetilde K ^{(1)} +\overline K ^{(1)} )   + \sigma_{T-t} ^2(\widetilde K ^{(2)} +\overline K ^{(2)} )\big]}^{\frac{1}{2}} 
            \\  &+ \frac{d}{\sigma_{T-t} ^2}  \int_{\mathbb{R}^d} \varrho_t(x)  (\|x\|_2 + \sqrt{d} D) \cdot \|  \dphi_H  (x) -  \baphi_H (x) \|_2 \de x .
            \end{split}
        \end{align*}
\end{lemma}
\begin{proof}
    Notice that
    \begin{align}\label{e:ht1}
        \begin{split}
            &\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x \\ &\leq \sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \big|\partial_i\varrho_t(x) \big| \cdot \big|  \dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x) \big| \de x 
             + \sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_i \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x.
        \end{split}
    \end{align}

We estimate the second part first. According to the Gagliardo-Nirenberg inequality Lemma~\ref{lemma: Gagliardo-Nirenberg}, we see that
    \begin{align*}
        \begin{split}
            &\sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_i \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x 
            \\  &\leq C_u  \sum_{i=1} ^d \sum_{j=1} ^d {\bigg (  \int_{\mathbb{R}^d}  \big|  \varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x)) \big| \de x \bigg)}^{\frac{1}{2}}{\bigg (\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \bigg)}^{\frac{1}{2}}
            \\  &\leq C_u  \sum_{i=1} ^d {\bigg (  \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big|  \varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x)) \big| \de x \bigg)}^{\frac{1}{2}}{\bigg ( \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \bigg)}^{\frac{1}{2}}
            \\  &\leq C_u  \sum_{i=1} ^d {\bigg (  \sqrt{d}\int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \bigg)}^{\frac{1}{2}}
            \\  &\leq C_u  d^{\frac{3}{4}} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \bigg)}^{\frac{1}{2}},
        \end{split}
    \end{align*}
where we also used H{\" o}lder inequality. 
We notice that 
    \begin{align*}
        \begin{split}
            & \sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \leq \sum_{i=1} ^d \int_{\mathbb{R}^d}  |\partial_{ii} ^2 \varrho_t(x) |\sqrt{d}\|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x
            \\  &+ 2d \sum_{i=1} ^d \int_{\mathbb{R}^d}  |\partial_{i} \varrho_t(x) | \|\nabla \dphi_H  (x) -  \nabla \baphi_H (x) \|_{\infty} \de x + d^2 \int_{\mathbb{R}^d}  | \varrho_t(x) | \|\nabla^2 \dphi_H  (x) -  \nabla ^2\baphi_H (x) \|_{\infty} \de x.
        \end{split}
    \end{align*}
We then need to use Lemma~\ref{lemma: infinity norm pth order growth in RK}. We see that by the assumption on $H$,
    \begin{align*}
       & \|\nabla \dphi_H  (x) -  \nabla \baphi_H (x) \|_{\infty} \leq HB_p s 2^s (\widetilde K ^{(1)} +\overline K ^{(1)} ),
   \\
        &\|\nabla ^2 \dphi_H  (x) -  \nabla ^2 \baphi_H (x) \|_{\infty} \leq 2HB_p s^3 4^s (\widetilde K ^{(2)} +\overline K ^{(2)} ).
    \end{align*}
According to Lemma~\ref{Lemma: Hessian estimates}, we know that 
    \begin{align}\label{e:ratio density bounds}
        \sum_{i=1} ^d \bigg| \frac{\partial _{i} \varrho_t(x)}{\varrho_t(x)} \bigg| \leq \frac{(\sqrt{d}\|x\|_2 + d D) }{\sigma_{T-t} ^2}, \quad  \sum_{i=1} ^d \bigg| \frac{\partial^2 _{ii} \varrho_t(x)}{\varrho_t(x)} \bigg| \leq \frac{3(\|x\|_2 ^2 + dD^2) }{\sigma_{T-t} ^4}.
    \end{align}
   By~\Cref{lemma: moments of L^2 and infinity norms}, we know that
    \begin{align*}
        \int_{\mathbb{R}^d} \|x\|_2 ^m \varrho_t(x) \ \de x \leq C(m) {(\sqrt{d}D)}^m.
    \end{align*}
Also,
    \begin{align*}
        \begin{split}
            &\sum_{i=1} ^d \int_{\mathbb{R}^d}  |\partial_{ii} ^2 \varrho_t(x) |\sqrt{d}\|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x \leq \frac{3\sqrt{d}}{\sigma_{T-t} ^4}\int_{\mathbb{R}^d}   \varrho_t(x) (\|x\|_2 ^2 + dD^2) \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x.  
        \end{split}
    \end{align*}
Hence, there is a universal constant $C_u >0$ such that
    \begin{align*}
        \begin{split}
            &\sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_{ii} ^2 \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x \leq \frac{3\sqrt{d}}{\sigma_{T-t} ^4}\int_{\mathbb{R}^d}   \varrho_t(x) (\|x\|_2 ^2 + dD^2) \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x
            \\  &+C_u \frac{HB_p d^2}{\sigma_{T-t} ^2}\big[  D   (\widetilde K ^{(1)} +\overline K ^{(1)} )   + \sigma_{T-t} ^2(\widetilde K ^{(2)} +\overline K ^{(2)} )\big].
        \end{split}
    \end{align*}
So,
    \begin{align}
        \begin{split}\label{e:ht2}
            & \quad \sum_{i=1} ^d \sum_{j=1} ^d\int_{\mathbb{R}^d}  \big| \partial_i \big(\varrho_t(x) (\dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x))\big) \big| \de x  
            \\  & \leq \frac{C_u  d}{\sigma_{T-t} ^2} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \int_{\mathbb{R}^d}   \varrho_t(x) (\|x\|_2 ^2 + dD^2) \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x \bigg)}^{\frac{1}{2}} 
            \\ &+   \frac{C_u {H}^{\frac{1}{2}} d^{\frac{7}{4}} {B_p}^{\frac{1}{2}}}{\sigma_{T-t}} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}} {\big[  D   (\widetilde K ^{(1)} +\overline K ^{(1)} )   + \sigma_{T-t} ^2(\widetilde K ^{(2)} +\overline K ^{(2)} )\big]}^{\frac{1}{2}} .
        \end{split}
    \end{align}
    Finally, by \eqref{e:ratio density bounds} again, we notice that
        \begin{align}
            \begin{split}\label{e:ht3}
                &\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \big|\partial_i\varrho_t(x) \big| \cdot \big|  \dphi_H ^{(j)} (x) -  \baphi_H ^{(j)} (x) \big| \de x \leq \frac{d}{\sigma_{T-t} ^2}  \int_{\mathbb{R}^d} \varrho_t(x)  (\|x\|_2 + \sqrt{d} D) \cdot \|  \dphi_H  (x) -  \baphi_H (x) \|_2 \de x .
            \end{split}
        \end{align}
The claim of \Cref{lemma: Second derivative bound on errors} follows from combining \eqref{e:ht1}, \eqref{e:ht2} and \eqref{e:ht3}.
\end{proof}

Next, we need to use the explicit formula \eqref{e:deftMt} and \eqref{e: score error p RK method} to explicitly estimate $\|\dM_t (x) - \baM_t(x) \|_{2}$ and $\|\dM_t (x) - \baM_t(x) \|_{\infty}$. We have the following lemma.

\begin{lemma}\label{lemma: pth order score error}
  Adopt the assumptions and notations in \Cref{p:ABCD}. Take $H$ small enough such that $t+H \leq T-\tau$, and
    \begin{align*}
        H \cdot  A_p s 2 ^s (\widetilde L ^{(1)} +\overline L ^{(1)} + d \overline K ^{(1)} + \overline W ^{(1)}) \leq 1/10.
    \end{align*}
    For $\dM_t, \baM_t$ as in \eqref{e:deftMt} and \eqref{e: score error p RK method}, we have that 
        \begin{align*}
            \begin{split}
                \| \dM_t (x) - \baM_t(x) \|_2 &\leq 2 B_p \bigg[ \| \sV_{t + c_s H}(\psi_{s,H}(x)) - V_{t + c_s H}(\psi_{s,H}(x)) \|_2 \\ & \quad +  \| \sV_{t + c_{s-1} H}(\psi_{s-1,H}(x)) - V_{t + c_{s-1} H}(\psi_{s-1,H}(x)) \|_2
                \\  &\quad +  \| \sV_{t + c_{s-2} H}(\psi_{s-2,H}(x)) - V_{t + c_{s-2} H}(\psi_{s-2,H}(x)) \|_2
                \\  &\quad + \cdots +   \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2\bigg],
            \end{split}
        \end{align*}
    where each $\psi_{j,H}$ for $j\in\llbracket 1,s\rrbracket$ is a diffeomorphism on $\mathbb{R}^d$, and satisfies that
            \begin{align*}
            \begin{split}
                & \|\psi_{j,H} ^{-1} (x) -x\|_2 \leq 2A_p H s{2}^{s} \big[   \overline W ^{(0)}+\overline W ^{(1)} \|x\|_{2}  \big] ,
                \\  & \big \|(\nabla \psi_{j,H} ^{-1})(x) -\mathbb{I}_d\big \|_{op} \leq 2 A_p H s 2^s  \overline L ^{(1)} \leq 1/10,
                \\  &\big \|(\nabla \psi_{j,H} ^{-1})(x) -\mathbb{I}_d\big \|_{\infty}  \leq 2 A_p H s 2^s  \overline K ^{(1)} ,
                \\  &e^{-8 A_p  s 2^s  \overline K ^{(1)} H d} \leq | \det[(\nabla \psi_{j,H} ^{-1})(x)]| \leq e^{4 A_p  s 2^s  \overline K ^{(1)} H d}.
            \end{split}
        \end{align*}
Also, if we further assume that $H>0$ is small such that 
    \begin{align*}
        H \cdot  A_p d s 2 ^s (\overline K ^{(1)} +\widetilde K ^{(1)} ) \leq 1/10,
    \end{align*}
then
    \begin{align*}
            \begin{split}
                \| \dM_t (x) - \baM_t(x) \|_{\infty} &\leq 2 B_p \bigg[ \| \sV_{t + c_s H}(\psi_{s,H}(x)) - V_{t + c_s H}(\psi_{s,H}(x)) \|_{\infty} \\ & \quad +  \| \sV_{t + c_{s-1} H}(\psi_{s-1,H}(x)) - V_{t + c_{s-1} H}(\psi_{s-1,H}(x)) \|_{\infty}
                \\  &\quad +  \| \sV_{t + c_{s-2} H}(\psi_{s-2,H}(x)) - V_{t + c_{s-2} H}(\psi_{s-2,H}(x)) \|_{\infty}
                \\  &\quad + \cdots +   \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_{\infty}\bigg].
            \end{split}
        \end{align*}
\end{lemma}

\begin{proof}
    First, $\| \dM_t (x) - \baM_t(x) \|_2\leq B_p \sum_{i=1} ^s \| \widetilde k_i - \overline k_i\|_2$. For each $\| \widetilde k_i - \overline k_i\|_2$, denoted as $\epsilon_i$, according to \eqref{e: p RK interpolation terms}, we see that 
        \begin{align*}
            \begin{split}
                \epsilon_i &\leq \| \sV_{t + c_i H}\bigl(x + (a_{i1} \widetilde k_1 + a_{i2} \widetilde k_2 + \cdots + a_{i,i-1} \widetilde k_{i-1}) H\bigr) \\ & \quad - \sV_{t + c_i H}\bigl(x + (a_{i1} \overline k_1 + a_{i2} \overline k_2 + \cdots + a_{i,i-1} \overline k_{i-1}) H\bigr)\|_{2}
                \\  &+ \| \sV_{t + c_i H}\bigl(x + (a_{i1} \overline k_1 + a_{i2} \overline k_2 + \cdots + a_{i,i-1} \overline k_{i-1}) H\bigr) \\ & \quad - V_{t + c_i H}\bigl(x + (a_{i1} \overline k_1 + a_{i2} \overline k_2 + \cdots + a_{i,i-1} \overline k_{i-1}) H\bigr)\|_{2}
                \\  &\leq \widetilde L ^{(1)} A_p H (\epsilon_1 + \epsilon_2 + \cdots + \epsilon_{i-1}) + \| \sV_{t + c_i H}(\psi_{i,H}(x)) - V_{t + c_i H}(\psi_{i,H}(x)) \|_2,
            \end{split}
        \end{align*}
    where we used the notation $\psi_{i,H} (x) \coloneq x + (a_{i1} \overline k_1 + a_{i2} \overline k_2 + \cdots + a_{i,i-1} \overline k_{i-1}) H$. If we define $\mathbf{T}_j \coloneq \sum_{i=1} ^j \epsilon_i$, we see that $\mathbf{T}_j \leq (1+\widetilde L ^{(1)} A_p H)\mathbf{T}_{j-1} +  \| \sV_{t + c_j H}(\psi_{j,H}(x)) - V_{t + c_j H}(\psi_{j,H}(x)) \|_2$. Hence,
        \begin{align*}
            \begin{split}
                \mathbf{T}_s &\leq \| \sV_{t + c_s H}(\psi_{s,H}(x)) - V_{t + c_i H}(\psi_{i,H}(x)) \|_2 \\ & \quad +(1+\widetilde L ^{(1)} A_p H) \| \sV_{t + c_{s-1} H}(\psi_{s-1,H}(x)) - V_{t + c_{s-1} H}(\psi_{s-1,H}(x)) \|_2
                \\  &\quad + {(1+\widetilde L ^{(1)} A_p H)}^2 \| \sV_{t + c_{s-2} H}(\psi_{s-2,H}(x)) - V_{t + c_{s-2} H}(\psi_{s-2,H}(x)) \|_2
                \\  &\quad + \cdots + {(1+\widetilde L ^{(1)} A_p H)}^{s-1}  \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2.
            \end{split}
        \end{align*}
    According to \Cref{lemma: pth order growth in RK}, \Cref{lemma: infinity norm pth order growth in RK}, and the assumption on $H$, for every $j \in \llbracket 1, s \rrbracket$,
        \begin{align*}
            \begin{split}
                & \|\psi_{j,H}(x) -x\|_2 \leq  A_p H \sum_{i=1} ^{j-1} \|\overline k_i(x) \|_{2} \leq A_p H s{2}^{s} \big[   \overline W ^{(0)}+\overline W ^{(1)} \|x\|_{2}  \big],
                \\  & \big \|\nabla \psi_{j,H}(x) -\mathbb{I}_d\big \|_{op} \leq A_p H \sum_{i=1} ^{j-1} \|\nabla \overline k_i(x) \|_{op} \leq A_p H s 2^s  \overline L ^{(1)},
                \\  & \|\nabla \psi_{j,H}(x) -\mathbb{I}_d\big \|_{\infty} \leq A_p H \sum_{i=1} ^{j-1} \|\nabla \overline k_i(x) \|_{\infty} \leq A_p H s 2^s \overline K ^{(1)} .
            \end{split}
        \end{align*}
    By the assumption on $H$, all these $\psi_{j,H}$'s are diffeomorphisms on $\mathbb{R}^d$. Similar to the proof of \Cref{lemma: Growth of inverse matrix} and \Cref{lemma: Growth of the original phi_h map}, we have that 
        \begin{align*}
            \begin{split}
                & \|\psi_{j,H} ^{-1} (x) -x\|_2 \leq 2\|\psi_{j,H}(x) -x\|_2 \leq 2 A_p H s{2}^{s} \big[   \overline W ^{(0)}+\overline W ^{(1)} \|x\|_{2}  \big] ,
                \\  & \big \|(\nabla \psi_{j,H} ^{-1})(x) -\mathbb{I}_d\big \|_{op} \leq 2 \big \|(\nabla \psi_{j,H} )(x) -\mathbb{I}_d\big \|_{op} \leq 2 A_p H s 2^s  \overline L ^{(1)},
                \\  & \big \|(\nabla \psi_{j,H} ^{-1})(x) -\mathbb{I}_d\big \|_{\infty} \leq 2 \big \|(\nabla \psi_{j,H} )(x) -\mathbb{I}_d\big \|_{\infty} \leq 2 A_p H s 2^s  \overline K ^{(1)}.
            \end{split}
        \end{align*}

One can similarly obtain the estimate for $\| \dM_t (x) - \baM_t(x) \|_{\infty}$. Indeed, similar proof holds true when one replaces $\| \dM_t (x) - \baM_t(x) \|_{\infty}$ with the $j$-th coordinate $|\dM_t ^{(j)} (x) - \baM_t ^{(j)} (x)|$ and replaces those $\| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_{\infty}$ with $|\sV_{t + c_{1} H} ^{(j)} (\psi_{1,H}(x)) - V_{t + c_{1} H} ^{(j)} (\psi_{1,H}(x)) |$.

\end{proof}


\begin{lemma}\label{lemma: errors of phi_H}
    Use the notation $\mathbb{B} \coloneq \frac{A_p+B_p+1}{B_p+1} \cdot (4\bm \beta+1)$, and take $\eta = 10^{-2} \mathbb{B}^{-1} H^{-1/2}$ for $\bm\beta$ obtained in \Cref{lemma: Growth of interpolation maps}.
      Adopt the assumptions and notations in \Cref{p:ABCD}. Take $H$ small enough such that 
    \begin{align}\label{e:H small logd 1}
        H \leq (2d \log (2d))^{-1} 10^{-6} \mathbb{B}^{-2}
    \end{align}
    and
    \begin{align}\label{e:H small logd 2}
        4000 H \cdot (A_p+B_p + 1)  s{2}^{s} \big[ \widetilde L ^{(1)} +\overline L ^{(1)} +  \overline W ^{(0)} \sqrt{d}D  + (\overline W ^{(0)})^2+ \overline W ^{(1)} d D^2 + d \overline K ^{(1)}   \big] \leq \sigma_{T-t} ^2.
    \end{align}
    Then, we have that
    \begin{align}
        \begin{split}\label{e:goal0}
            &\int_{\mathbb{R}^d} \varrho_t(x)  \big\|    \dphi_H(x) -\baphi_H (x)\big\|_{2}  \de x \\   &\leq C_u H B_p \bigg( \sum_{r=1} ^s \int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2  \de x 
        \\  & \quad +s\pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 \mathbb{B}^{2} H} }\big[(\widetilde W ^{(0)} + \overline W ^{(0)}) + \sqrt{d}D (\widetilde W ^{(1)} + \overline W ^{(1)})\big] \bigg).
        \end{split}
    \end{align}
    Similarly, for $m=1,2$, there is a universal constant $C_u >0$ such that
    \begin{align}
        \begin{split}\label{e:goal1}
            &\int_{\mathbb{R}^d} \varrho_t(x) \|x\|^m_2 \big\|    \dphi_H(x) -\baphi_H (x)\big\|_{2}  \de x \\   &\leq C_u H B_p \bigg( \sum_{r=1} ^s \int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \|x\|^m_2 \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2  \de x 
        \\  & \quad +s\pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 \mathbb{B}^{2} H} }(\sqrt d D)^m \big[(\widetilde W ^{(0)} + \overline W ^{(0)})^m + \sqrt{d}D (\widetilde W ^{(1)} + \overline W ^{(1)})^{m+1}\big] \bigg)
        \\   &\leq C_u H B_p (\sqrt{d}D)^m\bigg( \sum_{r=1} ^s {\bigg(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x)  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2 ^2  \de x \bigg)}^{\frac{1}{2}}
        \\  & \quad +s\pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 \mathbb{B}^{2} H} } \big[(\widetilde W ^{(0)} + \overline W ^{(0)})^m + \sqrt{d}D (\widetilde W ^{(1)} + \overline W ^{(1)})^{m+1} \big]\bigg).
        \end{split}
    \end{align}
\end{lemma}
\begin{proof}
First, the assumptions \eqref{e:H small logd 1} and \eqref{e:H small logd 2} enable us to use \Cref{lemma: pth order score error}, \Cref{lemma: score error cut-off general scheme}, and \Cref{lemma: exponential error term in cut-off}.

Then, by \Cref{lemma: pth order score error}, we have
\begin{align}         
\begin{split}\label{e:start}
&\int_{\mathbb{R}^d} \varrho_t(x) \|x\|_2^m  \big\|    \dphi_H(x) -\baphi_H (x)\big\|_{2}  \de x \\ 
 &\leq      
 2 H B_p\int_{\mathbb{R}^d} \varrho_t(x) \|x\|_2^m  \bigg[ \| \sV_{t + c_s H}(\psi_{s,H}(x)) - V_{t + c_s H}(\psi_{s,H}(x)) \|_2 \\ & \quad +  \| \sV_{t + c_{s-1} H}(\psi_{s-1,H}(x)) - V_{t + c_{s-1} H}(\psi_{s-1,H}(x)) \|_2
                \\  &\quad +  \| \sV_{t + c_{s-2} H}(\psi_{s-2,H}(x)) - V_{t + c_{s-2} H}(\psi_{s-2,H}(x)) \|_2
                \\  &\quad + \cdots +   \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2\bigg] \de x.
            \end{split}
        \end{align}
The right-hand side of \eqref{e:start} is a sum of $s$ terms, and they can be analyzed in the same way. So, we only study the term corresponding to $\| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2$. We notice that $\varrho_{t+c_1 H} (x) = \varrho_{t} (\phi_{c_1 H} ^{-1}(x)) \cdot  \det[ \nabla (\phi_{c_1 H} ^{-1}(x))] $. The estimates for $\phi_{c_1 H} ^{-1}(x)$ are in \Cref{lemma: Growth of the original phi_h map}. Those determinants term can be bounded by universal constants according to our assumption on $H$.  By change of variables,  Lemma~\ref{lemma: Growth of the original phi_h map},  Lemma~\ref{lemma: Growth of inverse matrix} and Lemma~\ref{lemma: pth order score error}, we see that for $m\geq 1$
\begin{align}
    \begin{split}\label{e:start1}
        &\int_{\mathbb{R}^d} \varrho_t(x)  \|x\|^m_2 \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2  \de x
        \\  &\leq 4\int_{\mathbb{R}^d} \varrho_t(\psi_{1,H} ^{-1}(x)) \|x\|^m_2 \| \sV_{t + c_{1} H}(x) - V_{t + c_{1} H}(x) \|_2  \de x 
        \\  &\leq 24\int_{\mathbb{R}^d} \varrho_t(\phi_{c_1 H} ^{-1}(x))  \cdot  \det[ \nabla (\phi_{c_1 H} ^{-1}(x))] \cdot \|x\|^m_2 \| \sV_{t + c_{1} H}(x) - V_{t + c_{1} H}(x) \|_2  \de x 
        \\  & \quad 
        + 32 E(m,0,(\widetilde W ^{(0)} + \overline W ^{(0)}),\eta) + 200 E(m+1,0,(\widetilde W ^{(1)} + \overline W ^{(1)}),\eta) 
        \\  &=24\int_{\mathbb{R}^d} \varrho_{t+c_1 H} (x) \|x\|^m_2 \| \sV_{t + c_{1} H}(x) - V_{t + c_{1} H}(x) \|_2  \de x 
        \\  & \quad +  32 E(m,0,(\widetilde W ^{(0)} + \overline W ^{(0)}),\eta) + 200 E(m+1,0,(\widetilde W ^{(1)} + \overline W ^{(1)}),\eta) .
    \end{split}
\end{align}
where the first inequality is by change of variables and the growth estimate on $\psi_{1,H} ^{-1}(x)$ in Lemma~\ref{lemma: pth order score error}, and the second inequality is by Lemma~\ref{lemma: score error cut-off general scheme} because $\| \sV_{t + c_{1} H}(x) - V_{t + c_{1} H}(x) \|_2 \leq (\widetilde W ^{(0)} + \overline W ^{(0)}) + (\widetilde W ^{(1)} + \overline W ^{(1)})\|x\|_2$, and we use the growth estimates for  $\psi_{1,H} ^{-1}(x)$ and $\phi_{c_1 H} ^{-1}(x)$ in Lemma~\ref{lemma: pth order score error} and \Cref{lemma: Growth of the original phi_h map}.
Similarly, for $m=0$, we have
\begin{align}\label{e:start2}
    \begin{split}
        &\int_{\mathbb{R}^d} \varrho_t(x)   \| \sV_{t + c_{1} H}(\psi_{1,H}(x)) - V_{t + c_{1} H}(\psi_{1,H}(x)) \|_2  \de x
       \\  &\leq 24\int_{\mathbb{R}^d} \varrho_{t+c_1 H} (x) \| \sV_{t + c_{1} H}(x) - V_{t + c_{1} H}(x) \|_2  \de x 
        + 32 E(1,(\widetilde W ^{(0)} + \overline W ^{(0)}),(\widetilde W ^{(1)} + \overline W ^{(1)}),\eta)  .
   \end{split}
\end{align}
Hence, by our choice of $\eta$ in the assumption (as in Lemma~\ref{lemma: exponential error term in cut-off}), after plugging \eqref{e:start1} and \eqref{e:start2} into \eqref{e:start}, we conclude that there is a universal constant $C_u >0$ such that for $m=0$
   \begin{align}
        \begin{split}\label{e:start3}
            &\int_{\mathbb{R}^d} \varrho_t(x) \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x \leq C_u H B_p \bigg( \sum_{r=1} ^s \int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2  \de x 
        \\  & \quad +s \pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 \mathbb{B}^{2} H} }  \big[(\widetilde W ^{(0)} + \overline W ^{(0)}) + \sqrt{d}D{(\widetilde W ^{(1)} + \overline W ^{(1)})} \big]\bigg).
        \end{split}
    \end{align}
The claim \eqref{e:goal0} follows.   
Similarly, for $m\geq 1$, we have 
    \begin{align}
        \begin{split}\label{e:start4}
            &\int_{\mathbb{R}^d} \varrho_t(x) \|x\|_2^m \big\|  \baphi_H (x) - \dphi_H(x) \big\|_{2}  \de x \leq C_u H B_p \bigg( \sum_{r=1} ^s \int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \|x\|_2^m  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2  \de x 
        \\  & \quad +s\pi^{-\frac{d}{2}} e^{-\frac{1}{10^4 \mathbb{B}^{2} H} }(\sqrt d D)^m \big[(\widetilde W ^{(0)} + \overline W ^{(0)})^m + \sqrt{d}D (\widetilde W ^{(1)} + \overline W ^{(1)})^{m+1}\big] \bigg).
        \end{split}
    \end{align}
    Moreover, H{\"o}lder inequality  and \Cref{lemma: moments of L^2 and infinity norms} imply
\begin{align}\begin{split}\label{e:start5}
    &\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \|x\|_2^m  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2  \de x\\
    &\leq \left(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \|x\|_2^{2m}  \de x  \right)^{1/2}\left(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x)  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|^2_2  \de x \right)^{1/2}\\
    &\leq C_u (\sqrt d D)^m\left(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x) \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|^2_2  \de x \right)^{1/2}.
\end{split}\end{align}  
    The statement \eqref{e:goal1} follows from combining \eqref{e:start4} and \eqref{e:start5}. 



\end{proof}




\subsection{Proof of \Cref{Prop: Conclusion second error term}}

\begin{proof}[Proof of \Cref{Prop: Conclusion second error term}]
    The proof is basically by combining the estimates in this section and use the fact that $\sigma_{T-t}^2 \geq C_u (T-t) \geq C_u \tau$. We recall from \Cref{lemma: Second derivative bound on errors}, 
     \begin{align}\label{e:I2bb3}
            \begin{split}
                &\sum_{i=1} ^d \sum_{j=1} ^d \int_{\mathbb{R}^d} \varrho_t(x) \big| \partial_i \dphi_H ^{(j)} (x) - \partial_i \baphi_H ^{(j)} (x) \big| \de x  
            \\  &\leq \frac{C_u d}{\tau}  \int_{\mathbb{R}^d} \varrho_t(x)  \|x\|_2  \cdot \|  \dphi_H  (x) -  \baphi_H (x) \|_2 \de x + \frac{C_u d^{3/2}D}{\tau}  \int_{\mathbb{R}^d} \varrho_t(x)   \cdot \|  \dphi_H  (x) -  \baphi_H (x) \|_2 \de x \\
            &+\frac{C_u  d}{\tau} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \int_{\mathbb{R}^d}   \varrho_t(x) \|x\|_2 ^2 \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x \bigg)}^{\frac{1}{2}} \\
            &+\frac{C(\widetilde K) {H}^{\frac{1}{2}} d^{\frac{7}{4}} {B_p}^{\frac{1}{2}}D^{3/2}}{\tau^{3/2}} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}, 
            \end{split}
        \end{align}
    where we used H{\"o}lder's inequality and \Cref{lemma: Constant Convention1} to simplify the expression. 

    We recall the bound $\|\nabla^2 \baphi_H \|_{\infty} \leq 48 H B_p s^3 4^s D^3/\tau^3$ from \Cref{lemma: Constant Convention} and \Cref{lemma: Constant Convention1}. By our assumption \eqref{e:Hcondition}, and $\overline{K}^{(1)}=2D^2\tau^{-2}$ from \eqref{e:tbound2}, we have $B_p dH\overline{K}^{(1)}=2B_pdHD^2\tau^{-2}\leq 1$.
    Using \eqref{e:I2bb3}, we can estimate the first three terms in \eqref{e:I2bb} as
    \begin{align}\begin{split}
        &C(s, B_p, \widetilde K)\Bigg[\frac{d^{3/2} D}{\tau}
        \int_{\mathbb{R}^d} \varrho_t (x) \cdot  \| \baphi_H(x) - \dphi_H(x) \|_2   \de x +    \frac{ d}{\tau}
        \int_{\mathbb{R}^d} \varrho_t (x) \cdot \|x\|_2  \cdot \| \baphi_H(x) - \dphi_H(x) \|_2   \de x\\
        &+\frac{  d}{\tau} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}{\bigg ( \int_{\mathbb{R}^d}   \varrho_t(x) \|x\|_2 ^2 \|\dphi_H  (x) -  \baphi_H (x) \|_2 \de x \bigg)}^{\frac{1}{2}} \\
            &+\frac{{H}^{\frac{1}{2}} d^{\frac{7}{4}} D^{3/2}}{\tau^{3/2}} {\bigg (  \int_{\mathbb{R}^d}  \varrho_t(x) \| (\dphi_H (x) -  \baphi_H  (x)) \|_{2} \de x \bigg)}^{\frac{1}{2}}\Bigg], 
    \end{split}\end{align}
where $C(s, B_p, \widetilde K)$ is a constant depending only on $s, B_p, \widetilde K$. Also, the exponential term  $e^{-\frac{1}{10^4 (4\bm\beta)^{2} H} }$ in \eqref{e:I2bb2} can be replaced by $e^{-\frac{1}{10^4 (\mathbb{B})^{2} H} }$ because $\mathbb{B} \geq 4\bm\beta$. Putting together \eqref{e:I2bb}, \eqref{e:I2bb2}, \Cref{lemma: errors of phi_H} and \eqref{e:I2bb3}, we conclude:
        \begin{align}\label{e:final1}
        \begin{split}
        &\int_{\mathbb{R}^d} | \varrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| | \de x
            \\  & \leq  C(s, B_p, \widetilde K, \widetilde W) H  d^{\frac{3}{2}} \tau^{-1} D\bigg[   \bigg( \sum_{r=1} ^s {\bigg(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x)  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2 ^2  \de x \bigg)}^{\frac{1}{2}}\bigg)   
        \\  &\quad + d^{\frac{1}{4}} D^{\frac{1}{2}} \tau^{-\frac{1}{2}}    \bigg( \sum_{r=1} ^s {\bigg(\int_{\mathbb{R}^d} \varrho_{t+c_r H} (x)  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2 ^2  \de x \bigg)}^{\frac{1}{4}} \bigg)
      +  \tau^{-4} d^2 D^6    {\pi}^{-d/4} e^{-\frac{1}{2\cdot 10^4 (\mathbb{B})^{2} H} }  \bigg],
        \end{split}
    \end{align}
where $C(s, B_p, \widetilde K, \widetilde W)$ is a constant depending only on $s, B_p, \widetilde K, \widetilde W$.


To further adopt the second assumption \eqref{e:score_bound} in \Cref{t:RK_1step} and to simplify our notations, we denote 
    \begin{align*}
        \epsilon_{r} \coloneq \int_{\mathbb{R}^d} \varrho_{t + c_{r} H} (x)  \| \sV_{t + c_{r} H}(x) - V_{t + c_{r} H}(x) \|_2 ^2  \de x , \quad \eta_{r} \coloneq \sigma_{T-(t +c_r H)} ^2.
    \end{align*}
According to the above inequality \eqref{e:final1}, we see that
    \begin{align*}
        \begin{split}
             &\sum_{r=1} ^s \epsilon_{r} ^{\frac{1}{2}} =  \sum_{r=1} ^s \left(\eta_{r} \epsilon_{r} \right) ^{\frac{1}{2}} \eta_{r} ^{-\frac{1}{2}} \leq \left(\sum_{r=1} ^s \eta_{r} \epsilon_{r} \right) ^{\frac{1}{2}} \left(\sum_{r=1} ^s \eta_{r} ^{-1} \right) ^{\frac{1}{2}}  \leq \varepsilon_{\rm score}(t) s ^{\frac{1}{2}} \tau ^{-\frac{1}{2}},
        \end{split}
    \end{align*}
where in the last inequality, we used the second assumption in \Cref{t:RK_1step} and the fact that $\sigma_t ^2 \geq \tau$ for any $t \in [\tau,T]$.
Similarly, 
    \begin{align*}
        \sum_{r=1} ^s \epsilon_{r} ^{\frac{1}{4}}
        \leq (\varepsilon_{\rm score} (t)) ^{\frac{1}{2}} s^{\frac{3}{4}} \tau ^{-\frac{1}{4}}.
    \end{align*}
Hence, there is a $C_{\rm disc} $ depending on $A_p, B_p,  s, p, D,\widetilde K, \widetilde W$, such that 
    \begin{align*}
        \begin{split}
        &\int_{\mathbb{R}^d} | \varrho_{t} (\dphi_H ^{-1}(x)) \cdot | \det[ \nabla (\dphi_H ^{-1}(x))]| -  \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| | \de x
            \\  & \leq C_{\rm disc}  \tau^{-2}  H\bigg[  d^{\frac{7}{4}}   \cdot (\varepsilon_{\rm score}(t)) ^{\frac{1}{2}} +  \tau^{-3}  {\pi}^{-\frac{d}{10}} e^{-\frac{1}{2\cdot 10^4 (\mathbb{B})^{2} H} }   \bigg] .
        \end{split}
    \end{align*}
Finally, because $\mathbb{B} = \frac{A_p+B_p+1}{B_p+1} \cdot (4\bm \beta+1)$ and $\bm \beta \leq 2B_p s 2^s (\widetilde W ^{(1)} + \overline W ^{(1)})$ according to \Cref{lemma: Growth of interpolation maps} and \Cref{lemma: Constant Convention}, we see that $2\cdot 10^4 (\mathbb{B})^{2} \leq \xi$.
This finishes  the proof of \Cref{Prop: Conclusion second error term}.
\end{proof}


