\section{Proof of \Cref{Prop: Conclusion third error term}}\label{Section: third term conclusion}

In this section, we prove \Cref{Prop: Conclusion third error term}. Notice that we already assumed that $t+H \leq T- \tau$ and $t,H$ are fixed. We will also use the estimates for $\overline K ^{(1)}$ and $\overline L ^{(1)}$ as shown in~\Cref{p:ABCD}.

We recall $I_3$ from \eqref{e:defI3} that
    \begin{align}\label{e:I3_copy}
       I_3 = \int_{\mathbb{R}^d} |\overline \varrho_{t+H}(x)-\varrho_{t+H}(x)| \de x,
    \end{align}
where $\overline \varrho_{t+H}(x)$ is as defined in \eqref{e:brhoth}.

For any $0\leq h\leq H$, we introduce the following function $F_h(x)$
    \begin{align}\label{e:Phitmap0}
        F_h(x) \coloneq x + h \sum_{j=1}^s b_j(h)  k_j(x),
    \end{align}
with
    \begin{align}\begin{split}\label{e:RK2}
    &k_1(x) = V_{t + h c_1 }(x),\\
    & k_2(x) =  V_{t + h c_2 }\bigl(x + h(a_{21}(h) k_1(x)) \bigr),\\
    & k_3(x) = V_{t + h c_3 }\bigl(x + h (a_{31}(h) k_1 + a_{32}(h) k_2(x)) \bigr),\\
    &\qquad\qquad\qquad\vdots
    \\
    & k_s(x) =  V_{t + h c_s }\bigl(x + h (a_{s1}(h) k_1(x) + a_{s2}(h) k_2 + \cdots + a_{s,s-1}(h) k_{s-1}(x)) \bigr).
\end{split}\end{align}
We remark that these $k_i(x)$'s depend on $h$, and they are different from the $\overline k_i(x)$'s we defined in \eqref{e: p RK interpolation terms}, because now we use a varying $h$ instead of a fixed $H$. But we see that $\baphi_H(x) = F_H(x)$, and $\overline{\varrho}_{t+H}$ is also the pushforward of the law $\varrho_t$ by $F_H(x)$. Denote
\begin{align}\label{e:defbaY}
    \overline{Y}_{t+h}=F_h(Y_t), \quad 0\leq h\leq H, \quad \overline{Y}_{t}=Y_t,
\end{align}
then $\overline{\varrho}_{t+H}$ is the law of $\overline{Y}_{t+H}$. Moreover, $k_i(x)$ enjoys the same estimates as $\bar k_i(x)$ as in \Cref{lemma: infinity norm pth order growth in RK}, \Cref{lemma: pth order growth in RK} and \Cref{lemma: infinity norm for k_i(x)} with $H$ replaced by $h$.
    % \begin{align*}
    %    \int_{\mathbb{R}^d}(\varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| -  \varrho_{t} (\phi_H ^{-1}(x)) \cdot | \det[ \nabla (\phi_H ^{-1}(x))]| )  \de x = \int_{\mathbb{R}^d}( \overline \varrho_{t+H}(x)-\varrho_{t+H}(x)) \de x.
   % \end{align*}

   Because $V_{t+h}(\cdot)$ is differentiable in $h$ on $[0,H]$, one can see from the above construction \eqref{e:RK2}, that $F_h(\cdot)$ is also differentiable in $h$. By taking $h$ derivative on both sides of \eqref{e:defbaY}
\begin{align}\label{e:dttY}
    \del_h \overline Y_{t+h} =\del_h F_h(\overline Y_{t}),\quad 0\leq h\leq H.
\end{align}

Let us first assume that for all $0\leq h\leq H$, $F_h$ is invertible, which will be verified later in \Cref{lemma: high_order_error}. Let 
\begin{align}\label{e:discreteODE}
    \overline V_{t+h}(x)=(\partial_h F_h)(F_h ^{-1}(x)),
\end{align}
then we can rewrite \eqref{e:dttY} as the following ODE flow
\begin{align}\label{e:dttY2}
     \del_h \overline Y_{t+h} = \overline V_{t+h}(\overline Y_{t+h}),\quad 0\leq h\leq H.
\end{align}
We also recall the ODE flow for $Y_{t+h}$ from \eqref{eq:reverse-ode}
\begin{align}\label{e:Ytflow}
     \del_h  Y_{t+h} =V_{t+h}( Y_{t+h}),\quad 0\leq h\leq H.
\end{align}
Then, according to \Cref{theorem: L^1 error}, using \eqref{e:dttY2} and \eqref{e:Ytflow} we can bound the total variation distance in \eqref{e:I3_copy}, as 
    \begin{align}\label{e:I3_copy2}
        I_3\leq \int_{0} ^H \int_{\mathbb{R}^d}  \bigg|  \nabla \cdot( (\varrho_{t+h}(x)(V_{t+h}(x) - \overline V_{t+h}(x) )) \bigg|\de x \de h.
    \end{align}



The following lemma states that for $H$ small enough, for any $0\leq h\leq H$, $F_h$ is invertible, and $\overline V_{t+h}(\cdot)$ is close to $V_{t+h}(\cdot)$ up to an error of size $\cO(H^p)$.

\begin{lemma}\label{lemma: high_order_error}
Adopt the assumptions in \Cref{Prop: Conclusion third error term}.
Denote $B:=1+A_p+B_p$. There exists a large constant $C=C(p,s, B)$, such that if $20 s 2^sBHd D^2 \tau^{-2}\leq 1$, then the following holds. For any $0\leq h\leq H$, $F_h$
    is a global diffeomorphism from $\bR^d$ to $\bR^d$. We denote its functional inverse as $F^{-1}_{h}(x)$, and
    \begin{align}\label{e:def_wtV}
      \overline V_{t+h}(x)=  (\del_h F_h)(F_h ^{-1} (x)).
    \end{align}
Then, for any $0\leq h\leq H$
    \begin{align}\label{e:stdiff}
        \begin{split}\|\overline V_{t+h}(x)- V_{t+h}(x)\|_{\infty} &\leq C\Big[  {(H\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!}\\
        &+ {(H\sqrt{d}(\|x \|_{2} + \sqrt{d} D))}^{p+1} {(\tau^{-1})}^{2^{p+2} (p+1)! + 2(p+1)} {(\|x\|_{\infty} +D)}^{3^{p+2} (p+1)!}\Big],
   \end{split} \end{align}
   and the same estimate holds for $ \|\nabla (\overline V_{t+h}(x)- V_{t+h}(x))\|_{\infty}$.
\end{lemma}

Before we give the proof for \Cref{lemma: high_order_error}, we need another lemma.

\begin{lemma}\label{lemma:V derivative bound}Adopt the assumptions in \Cref{Prop: Conclusion third error term}.
Denote $B:=1+A_p+B_p$. There exists a large constant $C=C(p,s, B)$, such that if $20 s 2^sBHd D^2 \tau^{-2}\leq 1$, then the following holds for any $0 \leq h \leq H$.
    \begin{align}\begin{split}\label{e:dtVbound}
        \|\del_h^p \baV_{t+h}(F_h(x))\|_\infty, \ 
         \|\del_h^p\nabla \baV_{t+h}(F_h(x))\|_\infty&\leq \frac{C  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^p  {(\|x\|_{\infty} +D)}^{3^{p+1} p!}}{\tau^{2^{p+1} p! + 2p}}\\
         &+Ch \frac{  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^{p+1}  {(\|x\|_{\infty} +D)}^{3^{p+2} (p+1)!}}{\tau^{2^{p+2} (p+1)! + 2(p+1)}},
    \end{split}\end{align}
and 
\begin{align}\begin{split}\label{e:dhVbound}
        \|\del_h^p V_{t+h}(F_h(x))\|_\infty , \ 
         \|\del_h^p\nabla V_{t+h}(F_h(x))\|_\infty
         &\leq \frac{C  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^p  {(\|x\|_{\infty} +D)}^{3^{p+1} p!}}{\tau^{2^{p+1} p! + 2p}}\\
         &+Ch \frac{  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^{p+1}  {(\|x\|_{\infty} +D)}^{3^{p+2} (p+1)!}}{\tau^{2^{p+2} (p+1)! + 2(p+1)}}.
    \end{split}\end{align}
\end{lemma}


Now, we can estimate the third term in \eqref{e: score error split 0}.

\begin{proof}[Proof of \Cref{Prop: Conclusion third error term}]

 By~\Cref{lemma: high_order_error}, we let $\gamma(p) \coloneq 3^{p+1} p!$ and see that there is a constant $C(p,s,B)>0$, such that
    \begin{align}\label{e:int1}
        \begin{split}
            &\int_{0} ^H \int_{\mathbb{R}^d}  \bigg|  \nabla \cdot ((\varrho_{t+h}(x)(V_{t+h}(x) - \overline V_{t+h}(x) )) \bigg|\de x \de h
    \\  &   \leq
        C   {[Hd^{\frac{1}{2}}  ]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} \int_{0} ^H \int_{\mathbb{R}^d} \varrho_{t+h}(x) (d+ \frac{\|x\|_1 +d D}{\tau}){(\|x\|_{\infty} +D)}^{\gamma(p)} {(\sqrt{d}D+ \|x\|_{2})}^p \de x \de h\\
      &  +C   {[Hd^{\frac{1}{2}}  ]}^{p+1} {(\tau^{-1})}^{2^{p+2} (p+1)! + 2p+2} \int_{0} ^H \int_{\mathbb{R}^d} \varrho_{t+h}(x) (d+ \frac{\|x\|_1 +d D}{\tau}){(\|x\|_{\infty} +D)}^{\gamma(p+1)} {(\sqrt{d}D+ \|x\|_{2})}^{p+1} \de x \de h,
        \end{split}
    \end{align}
where we also used \Cref{Lemma: Hessian estimates} to replace $\nabla \varrho_{t+h}(x)$ terms with $\varrho_{t+h}(x)$.
By~\Cref{lemma: moments of L^2 and infinity norms}, we know that there is a positive constant $C(m)$, such that
    \begin{align*}
        \int_{\mathbb{R}^d} \|x\|_2 ^m \varrho_{t+h}(x) \ \de x \leq C(m) {(\sqrt{d}D)}^m, \quad \int_{\mathbb{R}^d}  \|x\|_{\infty} ^m \varrho_{t+h}(x) \de y \leq C(m) {\big(D+\sqrt{ \log d}\big)}^m .
    \end{align*}
Hence, by H{\"older} inequality,
    \begin{align}\label{e:int2}
        \begin{split}
        &\phantom{{}={}}\int_{0} ^H \int_{\mathbb{R}^d} \varrho_{t+h}(x) (d+ \frac{\|x\|_1 +d D}{\tau}){(\|x\|_{\infty} +D)}^{\gamma(p)} {(\sqrt{d}D+ \|x\|_{2})}^p \de x \de h\\
            &\leq\frac{\sqrt{d}}{\tau}\int_{0} ^H \int_{\mathbb{R}^d} \varrho_{t+h}(x){(\|x\|_{\infty} +D)}^{\gamma(p)} {(\sqrt{d} D+ \|x\|_{2})}^{p+1} \de x \de h \\  &\leq C(p) \frac{\sqrt{d} H}{\tau} {(\sqrt{d}D)}^{p+1} {\big(D+\sqrt{ \log d}\big)}^{\gamma(p)} .
        \end{split}
    \end{align}
The same argument implies
\begin{align}\begin{split}\label{e:int3}
 &\phantom{{}={}}\int_{0} ^H \int_{\mathbb{R}^d} \varrho_{t+h}(x) (d+ \frac{\|x\|_1 +d D}{\tau}){(\|x\|_{\infty} +D)}^{\gamma(p+1)} {(\sqrt{d}D+ \|x\|_{2})}^{p+1} \de x \de h
 \\  &\leq C(p+1) \frac{\sqrt{d} H}{\tau} {(\sqrt{d}D)}^{p+2} {\big(D+\sqrt{ \log d}\big)}^{\gamma(p+1)} .
\end{split}\end{align}


We can then conclude from \eqref{e:I3_copy2}, \eqref{e:int1}, \eqref{e:int2} and \eqref{e:int3} that
    \begin{align*}
    \begin{split}
    %&\int_{\mathbb{R}^d} \big| \varrho_{t} (\baphi_H ^{-1}(x)) \cdot | \det[ \nabla (\baphi_H ^{-1}(x))]| -  \varrho_{t} (\phi_H ^{-1}(x)) \cdot | \det[ \nabla (\phi_H ^{-1}(x))]|  \big| \de x
           I_3 &\leq \int_{0} ^H \int_{\mathbb{R}^d}  \bigg|  \nabla \cdot ((\varrho_{t+h}(x)(V_{t+h}(x) - \overline V_{t+h}(x) )) \bigg|\de x \de h 
            \\    &\leq  C(p,s,B) H^{p+1} d^{p+1}D^{p+1}  {(\tau^{-1})}^{2^{p+2} (p+1)! + 2p+3} {\big(D+\sqrt{ \log d}\big)}^{\gamma(p+1)},
        \end{split}
    \end{align*}
where we used that $dHD<1$.


\end{proof}





\subsection{Proofs of \Cref{lemma: high_order_error} and \Cref{lemma:V derivative bound}}

In this section, we first prove \Cref{lemma: high_order_error} assuming \Cref{lemma:V derivative bound}. Then, we give the proof of \Cref{lemma:V derivative bound}.
\begin{proof}[Proof of \Cref{lemma: high_order_error}]
We first show that for any $0\leq h\leq H$, $F_h$ is a global diffeomorphism from $\bR^d$ to $\bR^d$.
Recall $F_h(x)=x+h\sum_{j=1}^s b_j(h) k_j$ from \eqref{e:Phitmap0}. It follows from \Cref{lemma: pth order growth in RK} that 
\begin{align}\begin{split}\label{e:Fr_bound}
    \|F_h(x)-x\|_2&\leq h B \sum_{i=1}^s \|k_i(x)\|_2\leq hs {(1+ \overline W ^{(1)}A_p H)}^{s-1} \big[   \overline W^{(0)} + \overline W ^{(1)} \|x\|_2 \big]\leq \frac{1}{2}(1+\|x\|_2),
\end{split}\end{align}
where we used~\Cref{p:ABCD} and our assumption that $20 s 2^sBHd D^2 \tau^{-2}\leq 1$. It follows that 
\begin{align}\label{e:change}
    1+\|F_h(x)\|_2\geq 1+\|x\|_2-\|F_h(x)-x\|_2\geq \frac{1}{2}(1+\|x\|_2).
\end{align}
Also, by~\Cref{lemma: infinity norm for k_i(x)}, we notice that 
    \begin{align*}
        \|F_h(x)-x\|_{\infty}&\leq 2h B s\tau^{-1}{(1+2\tau ^{-1}A_p H)}^{s-1} \big[D + 2\|x\|_{\infty} \big] \leq \frac{1}{2}(1+\|x\|_{\infty}).
    \end{align*}
Next, we show the $F_h(x)$ is a local diffeomorphism by checking its Jacobian matrix 
    \begin{align}\label{e:Jacobian}
        \nabla F_h(x)={\mathbb I}_d +A,\quad A:=h \sum_{j=1}^s b_j(h) \nabla k_j(x).
    \end{align}
   By \Cref{lemma: infinity norm pth order growth in RK}, the $(i,j)$-th entry of $A$ is bounded by
    \begin{align}\label{e:Aijbound}
        |A_{ij}|\leq h B \sum_{i=1}^s \|\nabla k_i(x)\|_\infty\leq hB s \overline K ^{(1)} {(1+ \overline K ^{(1)} A_p H d)}^{s-1} ,\quad 1\leq i,j\leq d.
    \end{align}
    The operator norm $\|A\|_{op}$ of the matrix $A$ is bounded by its  Frobenius norm as
    \begin{align*}
        \|A\|_{op}\leq \|A\|_{\rm F}\leq \sqrt{\sum_{ij}A_{ij}^2}\leq d hB s \overline K ^{(1)} {(1+ \overline K ^{(1)} A_p H d)}^{s-1}\leq 1/2.
    \end{align*}
    where again we used our assumption that $20 s 2^sBHd D^2 \tau^{-2}\leq 1$. It follows that $\nabla F_h(x)=\mathbb I_d+A$ is invertible, and $F_h$ is a local diffeomorphism. Then, Hadamard-Cacciopoli theorem implies that $F_h$ is also a bijection from $\bR^d$ to itself because $\|F_h(x)\|_2 \to + \infty$ if $\|x\|_2 \to + \infty$ by \eqref{e:change}. Therefore, $F_h$ is a diffeomorphism from $\bR^d$ to itself. Moreover, by \eqref{e:Aijbound}, we have the following entrywise bound for the inverse matrix $(\nabla F_h(x))^{-1}$:
\begin{align}\begin{split}\label{e:DFr_inverse}
       |((\nabla F_h(x))^{-1}-\mathbb I_d)_{ij}|
       &= |(\mathbb I_d +A)_{ij}^{-1}-\delta_{ij}|\leq |(\mathbb I_d
       -A+A^2-A^3+\cdots)_{ij}-\delta_{ij}|\\
       &\leq \sum_{k\geq 1}(hB s \overline K ^{(1)} {(1+ \overline K ^{(1)} A_p H d)}^{s-1})^k d^{k-1}
       \\   &\leq 2hB s \overline K ^{(1)} {(1+ \overline K ^{(1)} A_p H d)}^{s-1},\quad 1\leq i,j\leq d,
    \end{split}\end{align}
   where we used that $8sBhd\tau^{-1}\leq 1$.
  We denote the functional inverse of $F_h$ as $F^{-1}_{h}(x)$, then \eqref{e:def_wtV} follows from \eqref{e:dttY}. 


 Next, we show that the claim \eqref{e:stdiff} follows from the following statements: for $0\leq h\leq H$,
\begin{align}\begin{split}\label{e:tV-V}
     &\|\overline V_{t+h}(F_h(x))-V_{t+h}(F_h(x))\|_{\infty}\leq C(p,s, B)   {[h\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!},\\
     &\|\nabla(\overline V_{t+h}(F_h(x))-V_{t+h}(F_h(x)))\|_{\infty}\leq C(p,s, B)   {[h\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!}.
 \end{split}\end{align}
In fact, if we denote $y=F_h(x)$, then
\begin{align*}
    \|\overline V_{t+h}(y)-V_{t+h}(y)\|_{\infty}
    &\leq C(p,s, B)   {[h\sqrt{d}(\|F_h ^{-1} (x) \|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|F_h ^{-1} (x)\|_{\infty} +D)}^{3^{p+1} p!}\\
    &\leq C(p,s, B) 2^p 2^{3^{p+1} p!}   {[h\sqrt{d}(\|x \|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!},
\end{align*}
where in the last inequality we used \eqref{e:change} to bound $\|F_h ^{-1} (x) \|_{2} + \sqrt{d} D$ by $2(\|x \|_{2} + \sqrt{d} D)$, and bound $\|F_h ^{-1} (x)\|_{\infty} +D$ by $2(\|x\|_{\infty} +D)$. For the gradient part in \eqref{e:stdiff}, by the chain rule, we have
\begin{align}\label{e:DeltaV}
    (\nabla \overline V_{t+h})(y)-(\nabla  V_{t+h})(y)=\nabla(\overline V_{t+h}(F_h(x))-  V_{t+h}(F_h(x)))(\nabla F_h(x))^{-1}.
\end{align}
By plugging \eqref{e:DFr_inverse} into \eqref{e:DeltaV}, we conclude that
    \begin{align}\begin{split}\label{e:VFdiff}
        &\phantom{{}={}}\|(\nabla \overline V_{t+h})(y)-(\nabla  V_{t+h})(y)\|_\infty \\
        &\leq (1+2dhB s \overline K ^{(1)} {(1+ \overline K ^{(1)} A_p H d)}^{s-1})\|\nabla(\overline V_{t+h}(F_h(x))- V_{t+h}(F_h(x)))\|_{\infty}\\
    &\leq 2\|\nabla(\overline V_{t+h}(F_h(x))- V_{t+h}(F_h(x)))\|_{\infty}\\
    &\leq 2C(p,s, B)   {[h\sqrt{d}(\|x \|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!},
    \end{split}\end{align}
  where in the last inequality we used the gradient part in \eqref{e:tV-V}.

In the rest, we prove \eqref{e:tV-V}. 
We denote the characteristic flow corresponding to $V_{t+h}$ as $\Phi_h(x)$, i.e. $\Phi_0(x)=x$ and $\del_h\Phi_h(x)= V_{t+h}(\Phi_h(x))$. 
The  Runge-Kutta matrix $[a_{jk}]$, weights $b_j$ and nodes $c_j$ are carefully chosen such $\Phi_h(x)$ and $F_h(x)$ matches for the first $p$-th derivative at $h=0$. It follows that for any $0\leq m\leq p$,
\begin{align*}
    \left.\frac{\rd^m \Phi_h(x)}{\rd^m h}\right|_{h=0}=\left.\frac{\rd^m F_h(x)}{\rd^m h}\right|_{h=0},\quad 
    \left.\frac{\rd^m \nabla \Phi_h(x)}{\rd^m h}\right|_{h=0}=\left.\frac{\rd^m \nabla F_h(x)}{\rd^m h}\right|_{h=0}.
\end{align*}
Thus, by the chain rule, we have for $0\leq m\leq p-1$,
\begin{align*}
    &\left.\frac{\rd^m  V_{t+h}(F_h(x))}{\rd^m h}\right|_{h=0} = \left.\frac{\rd^m  V_{t+h}(\Phi_h(x))}{\rd^m h}\right|_{h=0}= \left.\frac{\rd^{m+1} \Phi_h(x)}{\rd^{m+1} h}\right|_{h=0} = \left.\frac{\rd^{m+1} F_h(x)}{\rd^{m+1} h}\right|_{h=0} = \left.\frac{\rd^m  \overline V_{t+h}(F_h(x))}{\rd^m h}\right|_{h=0},\\
    &\left.\frac{\rd^m \nabla  V_{t+h}(F_h(x))}{\rd^m h}\right|_{h=0}=\left.\frac{\rd^m \nabla   \overline V_{t+h}(F_h(x))}{\rd^m h}\right|_{h=0}.
\end{align*}
Then, by Taylor expansion we conclude that
\begin{align}\begin{split}\label{e:Taylor}
    & V_{t+h }(F_h(x))-\overline V_{t+h }(F_h(x))
    =R_1(h,x)-R_2(h,x),\\
    &\nabla ( V_{t+h }(F_h(x))  )-\nabla ( \overline V_{t+h }(F_h(x)) )
    =\nabla R_1(h,x)-\nabla R_2(h,x).
\end{split}\end{align}
where the two remainder terms are given by 
\begin{align*}
    &R_1(h,x)=\frac{1}{p!}\int_0^{h}(h-\tau)^{p-1}\frac{\rd^p V_{t_i+\tau }(F_\tau(x))}{\rd \tau^p} \de \tau,\\
    &R_2(h,x)=\frac{1}{p!}\int_0^{h}(h-\tau)^{p-1}\frac{\rd^p \overline V_{t+\tau }(F_\tau(x))}{\rd \tau^p} \de \tau .
\end{align*}
We conclude from  \Cref{lemma:V derivative bound} that 
\begin{align}\begin{split}\label{e:gradinfite_bound}
&\phantom{{}={}}\| R_1(h,x)\|_{\infty},\| R_2(h,x)\|_{\infty}
    \|\nabla R_1(h,x)\|_{\infty},\|\nabla  R_2(h,x)\|_{\infty}
    \\  &\leq  C(p,s, B)   {[h\sqrt{d}(\|x \|_{2} + \sqrt{d} D)]}^p {(\tau^{-1})}^{2^{p+1} p! + 2p} {(\|x\|_{\infty} +D)}^{3^{p+1} p!}\\
    &+C(p,s, B)   {[h\sqrt{d}(\|x \|_{2} + \sqrt{d} D)]}^{p+1} {(\tau^{-1})}^{2^{p+2} (p+1)! + 2(p+1)} {(\|x\|_{\infty} +D)}^{3^{p+2} (p+1)!}.
\end{split}\end{align}
The estimates \eqref{e:Taylor} and \eqref{e:gradinfite_bound} together give \eqref{e:tV-V}.
This finishes the proof of \Cref{lemma: high_order_error}. 
\end{proof}


\begin{proof}[Proof of~\Cref{lemma:V derivative bound}]
    We prove \eqref{e:dtVbound} first. We use the notation $X\lesssim Y$ if there exists a constant $C$ depending only on $p,s,B$ such that $|X|\leq C Y$. Given a symmetric tensor $T=(T_{j_1 j_2 \cdots j_{\al+1}})\in \bR^{d^{\al+1}}$, and vectors $u_1, u_2, \cdots, u_\al\in \bR^d$, we denote the vector $T[u_1, u_2, \cdots, u_\al]\in \bR^d$ as
\begin{align*}
    (T[u_1, u_2, \cdots, u_\al])_j
    =\sum_{1\leq j_1,j_2,\cdots, j_\al\leq d}T_{j j_1 j_2 \cdots j_\al}u_1^{(j_1)}u_2^{(j_2)}\cdots u_\al^{(j_\al)}.
\end{align*}
For any matrix $A=(A_{j_1j_2})\in \bR^{d\times d}$, we denote the matrix $T[u_1, u_2, \cdots, u_{\al-1}, A]\in \bR^{d\times d}$ as
\begin{align*}
    (T[u_1, u_2, \cdots, u_{\al-1},A])_{jj'}
    =\sum_{1\leq j_1,j_2,\cdots, j_\al\leq d}T_{j j_1 j_2 \cdots j_\al}u_1^{(j_1)}u_2^{(j_2)}\cdots u_{\al-1}^{(j_{\al-1})}A_{j_\al j'}.
\end{align*}

    Recall that $F_h(x)=x+h\sum_{j=1}^s b_j(h) k_j(x)$. So, by \eqref{e:discreteODE}, we have
    \begin{align}\label{e:tV=dF}
        \overline V_{t+h}(F_h(x))=\del_h F_h(x)=\sum_{j=1}^s \del_h (h b_j(h) k_j(x)).
    \end{align}

   In the following, we prove by induction on $j \in \llbracket 1 , s \rrbracket$ that for any $1\leq m\leq p+1$,
   \begin{align}\label{e:kjbound}
      \|\del_h^m k_j\|_\infty, \|\del_h^m\nabla  k_j\|_\infty\lesssim  {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)}/{ \tau}^{2^{m+1} m! + 2m}.
   \end{align}
We recall from \Cref{a:bounds on RK}, that $|\del^l_h b_j(h)|\leq B_p{/}\tau^l$ for $0\leq l\leq p+1$. Then claim \eqref{e:dtVbound} follows from plugging \eqref{e:kjbound} to \eqref{e:tV=dF}:
\begin{align*}\begin{split}
    \|\del_h^p \baV_{t+h}(F_h(x))\|_\infty
   =\|\del_h^{p+1} F_h(x)\|_\infty 
   &\leq C\frac{  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^{p}  {(\|x\|_{\infty} +D)}^{3^{p+1} p!}}{\tau^{2^{p+1} p! + 2p}},\\
   &+Ch \frac{  {[\sqrt{d}(\|x\|_{2} + \sqrt{d} D)]}^{p+1}  {(\|x\|_{\infty} +D)}^{3^{p+2} (p+1)!}}{\tau^{2^{p+2} (p+1)! + 2(p+1)}}.
\end{split}\end{align*}
   Since $k_1(x)= V_{t+h c_1}(x)$, by \Cref{lemma: time-space derivatives log qt}, \eqref{e:kjbound} holds for $j=1$ and any $1\leq m\leq p+1$. In the following we assume statement \eqref{e:kjbound} holds for $j-1$, we prove it for $j$ by induction on $m \in \llbracket 1 , p+1 \rrbracket$.


   We define the following set of vectors $\cD_0, \cD_1,\cD_2, \cdots$. Let $\cD_0=\{k_1, k_2, \cdots, k_j\}$. Then, by \Cref{lemma: pth order growth in RK} and \Cref{p:ABCD}, for any $v\in \cD_0$,
   \begin{align*}
       \|v\|_2\leq 2(\overline W ^{(0)} + \overline W ^{(1)}\|x\|_{2}) \leq 6dD^2 \tau^{-2} (1+ \|x\|_{2}).
   \end{align*}


   For $m\geq 1$, $\cD_m$ is defined as the set of vectors in the following form: for  $\beta\geq 1, \zeta \geq 0, \theta\geq 0, \al\leq \beta\leq m$,
    \begin{align}\label{e:defcDm}
        {\mathcal P}_\theta \cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al} V_{t+h c_j}(x+h(a_{j1}(h)k_1+a_{j2}(h)k_2+\cdots+a_{jj-1}(h)k_{j-1}))[u_1, u_2, \cdots, u_\al],
    \end{align}
    where $\del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}\in \bR^{d^{\al+1}}$ is a tensor, for each $1\leq \gamma\leq \al$, \begin{align*}
        u_\gamma\in \{\del_h^{\ell_\gamma} k_1, \del_h^{\ell_\gamma} k_2, \cdots, \del_h^{\ell_\gamma} k_{j-1} \},
    \end{align*}
    for some $\ell_\gamma\geq 0$, and ${\mathcal P}_\theta$ is of the form
    \begin{align*}
        \prod_{1\leq i<j\leq s}\del_h^{\ell_{ji}}a_{ji}(h),\quad \ell_{ji}\geq 0, \quad \theta=\sum_{1\leq i<j\leq s} \ell_{ji}.
    \end{align*}
Moreover, there exist nonnegative integers $m_0+m_1+m_2+\cdots+m_6+m_7=m$ such that
    \begin{align}\label{e:parameter}
    \begin{split}
        &\zeta=-m_1+m_4+m_7,\quad  \al=m_3+m_4+m_7,\quad \beta = m_2 + m_3 + m_4+m_7\\ &\theta=m_0+m_7,\quad
    \sum_{\gamma}\ell_\gamma=m_4+m_5+m_6,
        \quad 
        \sum_{\gamma:\ell_\gamma\geq 1}1=m_4+m_5.
    \end{split}
    \end{align}

    Next, we show that for each $v\in \cD_m$, $\del_h v$ is a linear combination of at most $C(s,p)$ terms in $\cD_{m+1}$, with coefficients bounded by $\max\{p,B\}$. Say $v$ is given in \eqref{e:defcDm}, satisfying \eqref{e:parameter}. By the chain rule, there are several cases:
    \begin{enumerate}
     \setcounter{enumi}{-1}
    \item If $\del_h$ hits $\mathcal P_\theta$ then we get
    \begin{align*}
        (\mathcal \del_h\mathcal P_\theta)\cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}[ u_1, u_2, \cdots, u_\al],
    \end{align*}
      which is a sum of terms in $\cD_{m+1}$, with new parameters \eqref{e:parameter} as $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0+1,m_1, m_2,m_3, m_4, m_5,m_6, m_7)$.
    \item If $\del_h$ hits $h^\zeta$, we get
    \begin{align*}
        \mathcal P_\theta\cdot h^{\zeta-1}\cdot \del_h^{\beta-\al}\nabla^{\al} V_{t+h c_j}[u_1, u_2, \cdots, u_\al]\in \cD_{m+1},
    \end{align*}
    which is in $\cD_{m+1}$, with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0,m_1+1, m_2,m_3, m_4, m_5,m_6,m_7)$.
    \item If $\del_h$ hits $t+hc_j$ in $V_{t+h c_j}$, we get
    \begin{align*}
        \mathcal P_\theta\cdot h^\zeta\cdot \del_h^{(\beta+1)-\al}\nabla^{\al}  V_{t+h c_j}[u_1, u_2, \cdots, u_\al]\in \cD_{m+1},
    \end{align*}
    which is in $\cD_{m+1}$, with the parameters \eqref{e:parameter} given by  $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0,m_1, m_2+1,m_3, m_4, m_5,m_6, m_7)$.

    \item If $\del_h$ hits $h$  in $(x+h(a_{j1}(h)k_1+a_{j2}(h)k_2+\cdots+a_{jj-1}(h)k_{j-1})$, we get
    \begin{align*}
        \sum_{1\leq i<j}(a_{ji}(h)\mathcal P_\theta)\cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al+1} V_{t+h c_j}[k_i, u_1, u_2, \cdots, u_\al],
    \end{align*}
    which is in $\cD_{m+1}$, with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0,m_1, m_2,m_3+1, m_4, m_5,m_6,m_7)$. 
    \item If $\del_h$ hits $k_i$ in $(x+h(a_{j1}k_1+a_{j2}k_2+\cdots+a_{jj-1}k_{j-1})$ for some $1\leq i\leq j-1$, we get
    \begin{align*}
        {\mathcal P}_{\theta} \cdot h^{\zeta+1} \cdot \del_h^{\beta-\al}\nabla^{\al+1} V_{t+h c_j}[\del_h k_i, u_1, u_2, \cdots, u_\al]\in \cD_{m+1},
    \end{align*}
    which is in $\cD_{m+1}$ with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0, m_1, m_2,m_3, m_4+1, m_5,m_6,m_7)$.

    \item If $\del_h$ hits $u_\gamma$ and $u_\gamma=k_i$ we get
    \begin{align*}
        {\mathcal P}_{\theta} \cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}[ u_1, u_2, \cdots, u_{\gamma-1}, \del_h k_i, u_{\gamma+1},\cdots, u_\al]\in \cD_{m+1},
    \end{align*}
    which is in $\cD_{m+1}$, with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0,m_1, m_2,m_3, m_4, m_5+1,m_6,m_7)$.
    \item If $\del_h$ hits $u_\gamma$ and $u_\gamma=\del_h^{\ell_\gamma}k_i$ with $\ell_\gamma\geq 1$ we get
    \begin{align*}
       {\mathcal P}_{\theta} \cdot h^{\zeta}\cdot\del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}[ u_1, u_2, \cdots, u_{\gamma-1}, \del_h^{\ell_\gamma+1}k_i, u_{\gamma+1},\cdots, u_\al]\in \cD_{m+1},
    \end{align*}
      which is in $\cD_{m+1}$ with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0,m_1, m_2,m_3, m_4, m_5,m_6+1,m_7)$.
      \item If $\del_h$ hits $a_{ji}(h)$ in $(x+h(a_{j1}(h)k_1+a_{j2}(h)k_2+\cdots+a_{jj-1}(h)k_{j-1})$, we get
    \begin{align*}
       \sum_{1\leq i<j}(\mathcal P_\theta \cdot \del_h a_{ji}(h) )\cdot h^{\zeta+1}\cdot \del_h^{\beta-\al}\nabla^{\al+1} V_{t+h c_j}[k_i, u_1, u_2, \cdots, u_\al],
    \end{align*}
    where each summand is in $\cD_{m+1}$, with parameters \eqref{e:parameter} as $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_0, m_1, m_2,m_3, m_4, m_5,m_6, m_7+1)$. 
%\item If $\del_h$ hits $\mathcal P_\theta$ then we get
%    \begin{align*}
 %     {\mathcal P}_{\theta}  %(\del_h\mathcal P_\theta)\del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}[ u_1, u_2, \cdots, u_\al],
%    \end{align*}
  %    is a sum of terms in $\cD_{m+1}$, %with the parameters \eqref{e:parameter} given by $(m_0',m_1', m_2',m_3', m_4', m_5',m_6',m_7')=(m_1, m_2,m_3, m_4, m_5,m_6, m_7+1)$.
\end{enumerate}
We conclude that for $v\in \cD_m$, $\del_h v$ is a linear combination of finite terms in $\cD_{m+1}$. In particularly, $\del_h^m k_j$ is a linear combination of at most $C(s,p)^m$ terms in $\cD_m$, with coefficients bounded by $\max\{p,B\}^m$

 In the following, we show the following bound for vectors in $v\in \cD_m$
    \begin{align}\label{e:Dkbound}
        \|v\|_\infty\lesssim
            {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)}, \quad  m\geq 1. 
    \end{align}
Then it follows 
\begin{align*}
    \|\del_h^m k_j\|_{\infty} \lesssim {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)},
\end{align*}
and the first statement in \eqref{e:kjbound} holds.

 We prove \eqref{e:Dkbound} by induction. From \Cref{lemma: infinity norm for k_i(x)}, when $H A_p 2^s s \tau^{-1} \leq 1$, we have that $\|k_i\|_2\leq 4\tau ^{-1}(\|x\|_{2} + \sqrt{d} D)$. It follows that $\|k_i\|_1\leq 4\sqrt{d}\tau ^{-1}(\|x\|_{2} + \sqrt{d} D)$.
    We assume \eqref{e:Dkbound} holds for $ 1,2,\cdots, m-1$, and next we prove it for $m$. Notice that when we write $\del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}$, this tensor is evaluated at $F_h(x)$. According to \Cref{lemma: time-space derivatives log qt}, we see that 
    \begin{align*}
        \|  \del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j} (F_h(x))\|_\infty \leq C(p) d^{\beta-\alpha} \tau^{\alpha - 2\beta}{(\|F_h(x)\|_{\infty}+D)} ^{3\beta - 2\alpha+1  }.
    \end{align*}
We can further estimate $\|F_h(x)\|_{\infty}$ by $4\|x\|_{\infty}+4D$ according to~\Cref{lemma: infinity norm for k_i(x)}. We also notice that $\beta = m_2 + m_3 + m_4+m_7$ and $\alpha = m_3+m_4+m_7$. So, we see that 
    \begin{align}\begin{split}\label{e:ubb}
        &\phantom{{}={}}\| \mathcal P_\theta \cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al} V_{t+h c_j}[u_1, u_2, \cdots, u_\al]\|_\infty
        \lesssim \tau^{-\theta} h^{\zeta} \|  \del_h^{\beta-\al}\nabla^{\al} V_{t+h c_j}\|_\infty\|u_1\|_1\|u_2\|_1\cdots\|u_\al\|_1\\
        &\lesssim  h^{-m_1+m_4+m_7}d^{m_2} {(\tau^{-1})}^{m_0+ 2m_2 + m_3 + m_4+2m_7}{(\|x\|_{\infty}+D)} ^{3m_2+m_3+m_4+m_7+1  }  
        \\  & \quad \times \prod_{\gamma:\ell_\gamma=0}(\sqrt{d}\tau ^{-1}(\|x\|_{2} + \sqrt{d} D))\prod_{\gamma:\ell_\gamma\geq 1} d (\sqrt{d}(\|x\|_{2} + \sqrt{d} D))^{\ell_\gamma} {(\tau^{-1})}^{2^{\ell_\gamma+1} \ell_\gamma! + 2\ell_\gamma} {(\|x\|_{\infty} +D)}^{3^{\ell_\gamma+1} \ell_\gamma!}
        \\  &=  h^{-m_1+m_4+m_7}d^{m_2} {(\tau^{-1})}^{m_0+ 2m_2 + m_3 + m_4+2m_7}{(\|x\|_{\infty}+D)} ^{3m_2+m_3+m_4+m_7+1  } {(\sqrt{d}\tau ^{-1}(\|x\|_{2} + \sqrt{d} D))}^{m_3+m_4}
        \\  & \quad \times \prod_{\gamma:\ell_\gamma\geq 1} d (\sqrt{d}(\|x\|_{2} + \sqrt{d} D))^{\ell_\gamma-1} {(\tau^{-1})}^{2^{\ell_\gamma+1} \ell_\gamma! + 2(\ell_\gamma-1)} {(\|x\|_{\infty} +D)}^{3^{\ell_\gamma+1} \ell_\gamma!}
        \\  &\lesssim  h^{-m_1+m_4+m_7}d^{m_2} {(\tau^{-1})}^{m_0+ 2m_2 + m_3 + m_4+2m_7}{(\|x\|_{\infty}+D)} ^{3m_2+m_3+m_4+m_7+1  } {(\sqrt{d}\tau ^{-1}(\|x\|_{2} + \sqrt{d} D))}^{m_3+m_4}
        \\  & \quad \times d^{m_4+m_5} (\sqrt{d}(\|x\|_{2} + \sqrt{d} D))^{m_6} {(\tau^{-1})}^{m(2^{m} (m-1)! + 2(m-2))} {(\|x\|_{\infty} +D)}^{m(3^{m} (m-1)!)}
        \\  &\lesssim h^{m_7}{(hd)}^{m_4-m_1} d^{m_1+m_2+m_5} {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m_3+m_4+m_6}{( \tau^{-1})}^{2^{m} (m)! + 2m^2-2m} {(\|x\|_{\infty} +D)}^{(3^{m} (m)! + 3m+1)}
        \\ & 
        \lesssim {(hd)}^{m_7+m_4-m_1} d^{m_1+m_2+m_5} {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m_3+m_4+m_6}{( \tau^{-1})}^{2^{m} (m)! + 2m^2-2m} {(\|x\|_{\infty} +D)}^{(3^{m} (m)! + 3m+1)}
        \\ & \lesssim {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)},
    \end{split}\end{align}
    where in the first inequality we used \Cref{a:bounds on RK}, in the last line we used \eqref{e:parameter} and $m= m_0+m_1 + m_2 +m_3+m_4+m_5+m_6+m_7$, and by our assumption, $hd \leq 1$, $m_7\geq 0$ and $m_7+m_4- m_1 = \zeta \geq 0$. This finishes the proof of \eqref{e:Dkbound}.



  In the following we prove the second statement in \eqref{e:kjbound}. We define the following set of $d\times d$ matrices $\widetilde\cD_0, \widetilde\cD_1,\widetilde\cD_2, \cdots$. Let $\widetilde\cD_0=\{\nabla k_1, \nabla  k_2, \cdots, \nabla 
 k_j\}$. Then by \Cref{lemma: infinity norm pth order growth in RK}, for any $v\in \widetilde\cD_0$,
   \begin{align*}
       \|v\|_\infty\leq 2 \overline K ^{(1)} \leq 8 D^2 \tau^{-2}.
   \end{align*}
We denote $\widetilde \cD_m$ the set of matrices obtained from taking gradient of \eqref{e:defcDm}, with respect to $x$ 
   \begin{align}\begin{split}\label{e:defcDm2}
        &\mathcal P_\theta \cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al+1}  V_{t+h c_j}[(\mathbb{I}_d+h(a_{j1}\nabla k_1+a_{j2}\nabla k_2+\cdots+a_{jj-1}\nabla k_{j-1})), u_1, u_2, \cdots, u_\al]\\
        &\mathcal P_\theta \cdot h^{\zeta}\cdot \del_h^{\beta-\al}\nabla^{\al}  V_{t+h c_j}[u_1, u_2, \cdots, u_{\gamma-1},\nabla u_{\gamma}, u_{\gamma+1},\cdots, u_\al], \quad 1\leq \gamma\leq \al.
    \end{split}\end{align}
  Then  $\del_h^m \nabla k_j$ is a finite linear combination of terms in $\widetilde \cD_m$. 

  Next we show by induction that $v\in \widetilde \cD_m$, 
   \begin{align}\label{e:wDkbound}
        \|v\|_\infty\lesssim
            {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)}, \quad  m\geq 1. 
    \end{align}
    Then it follows 
\begin{align*}
    \|\del_h^m \nabla k_j\|_{\infty}\lesssim {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)},
\end{align*}
and the second statement in \eqref{e:kjbound} holds.

  Similar to \eqref{e:ubb}, 
  we can bound the $L^\infty$-norm of $v$ as
  \begin{align*}
       & \phantom{{}={}}|\mathcal P_\theta| h^\zeta \|  \del_h^{\beta-\al}\nabla^{\al + 1} V_{t+h c_j}\|_\infty (1+8D^2 \tau^{-2}sBr) \|u_1\|_1\|u_2\|_1\cdots\|u_\al\|_1
       \\   &\lesssim 2\tau^{-\theta} h^\zeta \|  \del_h^{\beta-\al}\nabla^{\al+1} V_{t+h c_j}\|_\infty\|u_1\|_1\|u_2\|_1\cdots\|u_\al\|_1\\
       &\lesssim {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)}.
    \end{align*}
    Also, for any $q \in \{1, 2,\dots,d\}$, we can similarly obtain that
    \begin{align*}
       &\phantom{{}={}} |\mathcal P_\theta|  h^\zeta \|  \del_h^{\beta-\al}\nabla^{\al} V_{t+h c_j}\|_\infty \|\partial_q u_\gamma\|_1 \prod_{\gamma'\neq \gamma}\|u_{\gamma'}\|_1 \\  &\lesssim   \tau^{-\theta }h^\zeta \|  \del_h^{\beta-\al}\nabla^{\al+1} V_{t+h c_j}\|_\infty d
       {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{\ell_\gamma}{( \tau^{-1})}^{2^{\ell_\gamma+1} \ell_\gamma! + 2\ell_\gamma} {(\|x\|_{\infty} +D)}^{(3^{\ell_\gamma+1} \ell_\gamma!)}\prod_{\gamma'\neq \gamma}\|u_{\gamma'}\|_1\\ &\lesssim  {(\sqrt{d}(\|x\|_{2} + \sqrt{d} D))}^{m}{( \tau^{-1})}^{2^{m+1} m! + 2m} {(\|x\|_{\infty} +D)}^{(3^{m+1} m!)},
  \end{align*}
as we did in \eqref{e:ubb}.
This gives \eqref{e:wDkbound}.

Finally, for \eqref{e:dhVbound}, we notice that 
    \begin{align*}
        V_{t+h}(F_h)= V_{t+h}(x+h\sum_{j=1}^s b_j(h) k_j),
    \end{align*}
    which is of the same form as $k_j$. Thus the same argument as for \eqref{e:kjbound} gives \eqref{e:dhVbound}
\end{proof}




