\section{Proofs of \Cref{lemma: Growth of inverse matrix}, \Cref{lemma: score error cut-off general scheme}, and \Cref{lemma: exponential error term in cut-off} }
\label{app:proofs}

In this section, we present the proofs of \Cref{lemma: Growth of inverse matrix}, \Cref{lemma: score error cut-off general scheme}, and \Cref{lemma: exponential error term in cut-off}. 
\begin{proof}[Proof of \Cref{lemma: Growth of inverse matrix}]
    We denote $P = \mathbb{I}_d -Q$.
    It is easy to see that $Q^{-1} = \mathbb{I}_d + \sum_{j=1} ^{+\infty} P^j$. Hence, $\|Q^{-1} - \mathbb{I}_d \|_{op} \leq  \sum_{j=1} ^{+\infty} {(\gamma H)}^j \leq 2\gamma H$. Also, because $\xi H \leq 1/d$, we see that $\|P^2\|_{\infty} \leq d (\xi H)^2 \leq \xi H/2$, and similarly $\|P^j\|_{\infty} \leq \xi H/2^{j-1}$. It follows that $\|Q^{-1} - \mathbb{I}_d \|_{\infty} \leq 2\xi H$. 

    For the determinant, we see that $Q^t Q = (\mathbb{I}_d - P)^t (\mathbb{I}_d - P) = \mathbb{I}_d - (P^t + P - P^t P)$. Because $P^t + P - P^t P$ is a symmetric matrix, we assume that its eigenvalues are real numbers $\lambda_1,\lambda_2,\dots,\lambda_d$. Then,
    \begin{align*}
        \begin{split}
             | \det Q| ^2&=| \det[Q^tQ ]| = \prod_{i=1} ^d (1-\lambda_i) \\ &\leq e^{-\sum_{i=1} ^d \lambda_i} = e^{-\trace (P^t + P - P^t P)} \leq e^{2\xi d H + d^2 \xi^2 H^2} \leq e^{4\xi d H},
        \end{split}
    \end{align*}
    because $d\xi H <1$. So, $| \det Q| \leq e^{2\xi d H}$.
    Similarly, we see that $| \det[Q ^{-1}]| \leq e^{4\xi d H}$. Finally, because one can consider a continuous family of $Q_s \coloneq (1-s)\mathbb{I}_d + sQ$ for $s \in [0,1]$, and one can see that for any $s \in [0,1]$, $\|Q_s - \mathbb{I}_d\|_{\infty} \leq \xi H$. Hence, $| \det[Q_s]| \geq e^{-4\xi d H}$ for any $s \in [0,1]$. Because when $s =0$, $\det[Q_0] = 1 >0$, by continuity, we see that $\det[Q_s] >0$ for any $s \in [0,1]$. In particular, $\det Q >0$.
\end{proof}


\begin{proof}[Proof of \Cref{lemma: score error cut-off general scheme}]
By our assumption $\psi_1(x)$ is a diffeomorphism, and 
$\|\psi_1^{-1}(x)-x\|_2\leq  H(\bm\al_1+\bm\beta_1\|\psi_1^{-1}(x)\|_2)$. By rearranging it, we get $\|\psi_1^{-1}(x)-x\|_2\leq 2 H(\bm\alpha_1+\bm\beta_1\|x\|_2)$, provided $\bm\beta_1 H<1/4$.

   Next we notice that for any $x\in K_{\ast}$, $\|x\|_2 \leq \sqrt{d} D$ by the Assumption~\ref{assumption:secon-moment}.
    Consider the domain $\cD_{4R} \coloneq \{x\in \bR^d: \|x- \lambda_{T-t} K_{\ast}\|_2\leq 4R\}$, with $R \coloneq \eta \sigma_{T-t}$. 
    Outside the $\cD_{4R}$, we have that
    \begin{align}
        \begin{split}
            & \int_{\mathbb{R}^d \setminus \cD_{4R}}    \varrho_{t}(\psi_1(x)) \big\| Z(x)\big\|_2  \de x \leq \int_{\mathbb{R}^d \setminus \cD_{4R}}    \varrho_{t}(\psi_1(x)) (A + B\|x\|_2 ^m)  \de x
            \\ &\leq \int_{\mathbb{R}^d \setminus \psi_1 (\cD_{4R})}    \varrho_{t}(x) (A+ B \|\psi^{-1}_1(x)\|_2 ^m) | | \det[ \nabla (\psi_1 ^{-1}(x))]| \de x
            \\  & \leq e^{4\bm\xi_1 H d}\int_{\mathbb{R}^d \setminus (\cD_{2R})}    \varrho_{t}(x) (A + B {(\|x\|_2+2H (\bm\al_1 +  \bm\beta_1 \|x\|_2))}^m)  \de x
            \\  & \leq  2 \int_{\mathbb{R}^d \setminus (\cD_{2R})}    \varrho_{t}(x) 2^m ((A+B{2(H\bm\alpha_1)}^m) + B{(1+2H\bm\beta_1)}^m \|x\|_2 ^m)  \de x.
        \end{split}
    \end{align}
where we used the fact that $\nabla (\psi_1 ^{-1}(x)) = {[(\nabla \psi_1)(\psi_1 ^{-1}(x))]}^{-1}$ and \Cref{lemma: Growth of inverse matrix}, and we chose $H$ small such that, $\cD_{2R} \subset \psi_1 (\cD_{4R})$. This can be done if we require that $ H(\bm\alpha_1 + \bm\beta_1\sqrt{d} D) \leq \min\{R,1\}/10$. This is because if $x \in \cD_{2R}$, then there is a $y \in K_{\ast} $, such that $\|x- \lambda_{T-t} y\|_2\leq 2R$. Then, 
    \begin{align}\label{e: psi_1 in D4R}
        \begin{split}
            &\|\psi_1 ^{-1}(x) - \lambda_{T-t} y \|_2 \leq 2R + \|\psi_1 ^{-1}(x) - x \|_{2} \leq 2R +  H(\bm\al_1 + \bm\beta_1\|\psi_1 ^{-1}(x) \|_2)
            \\  &\leq 2R +  H(\bm\al_1 + \bm\beta_1 \|\psi_1 ^{-1}(x) -\lambda_{T-t} y\|_2 + \bm\beta_1 \sqrt{d}D).
        \end{split}
    \end{align}
Because $\bm\beta_1 H  \leq \bm\beta_1 H  \sqrt{d} D \leq 1/10$ as $D \geq 1$, we obtain that $\|\psi_1 ^{-1}(x) - \lambda_{T-t} y \|_2 \leq 3R + 2 H(\bm\al_1+ \bm\beta_1\sqrt{d} D) < 4R$. Hence, $\psi_1 ^{-1} (\cD_{2R}) \subset \cD_{4R}$. Now, according to the definition of $q_t$ as in \eqref{e: definition of q_t}, 
\begin{align*}
            \varrho_t(y) = q_{T-t} (y) =\int_{\mathbb{R}^d} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{-\frac{\|y-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} \ d\muast(x),
\end{align*}
    with $\int_{\mathbb{R}^d} d\muast(x) = 1$ and $\mathrm{supp}(\muast) = K_{\ast}$, we see that
        \begin{align*}
            \begin{split}
                &\int_{\mathbb{R}^d \setminus (\cD_{2R})}    \varrho_{t}(y) 2^m ((A+B{(2H\bm\al_1)}^m) + B{(1+2H\bm\beta_1)}^m \|y\|_2 ^m)  \de y \\
                &\leq 4^m \int_{\mathbb{R}^d \setminus (\cD_{2R})}\varrho_t(y) ((A+B) + B\|y\|_2 ^m) \de y 
                \\  &= 4^m\int_{\mathbb{R}^d \setminus (\cD_{2R})}\int_{\mathbb{R}^d} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{-\frac{\|y-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} ((A+B) + B\|y\|_2 ^m) \ d\muast(x)  \de y
                \\  &\leq 8^m \int_{\mathbb{R}^d} 
                \int_{\mathbb{R}^d \setminus (\cD_{2R})} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{-\frac{\|y-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} [(A+2B{(\sqrt{d}D)}^m) + B{\|y-\lambda_{T-t} x\|_2 }^m] \de y\ d\muast(x)  \\  &\leq 8^m \int_{\mathbb{R}^d} 
                \int_{\|y-\lambda_{T-t} x\|_2\geq 2R} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{-\frac{\|y-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} [(A+2B{(\sqrt{d}D)}^m) + B{\|y-\lambda_{T-t} x\|_2}^m] \de y\ d\muast(x)
                \\  & =8^m \int_{\|z\|_2\geq (2R)/\sigma_{T-t}} \frac{1}{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}} [(A+2B{(\sqrt{d}D)}^m) + B {(\sigma_{T-t}\|z\|_2)}^m] \de z,
            \end{split}
        \end{align*}
which is a exponentially small term if we choose $(2R)/\sigma_{T-t}$ large.

Inside the $\cD_{4R}$, we need to estimate
    \begin{align*}
        \int_{\cD_{4R}}    \varrho_{t}(\psi_1(x)) \big\| Z(x)\big\|_2  \de x.
    \end{align*}
We estimate the ratio $\varrho_{t}(\psi_1(y)) / \varrho_{t}(\psi_2(y))$ for $y \in \cD_{4R}$. Again, by the definition of $q_t$ as in \eqref{e: definition of q_t},
\begin{align*}
            \begin{split}
                &\varrho_t(\psi_1(y)) =\int_{\mathbb{R}^d} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{-\frac{\|\psi_1(y)-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} \ d\muast(x)
                \\  & \leq \int_{\mathbb{R}^d} \frac{1}{{(\sqrt{2\pi} \sigma_{T-t})}^{d}} \cdot e^{\frac{2\|\psi_1(y)-\psi_2 (y)\|_2 \cdot \|\psi_2(y)-\lambda_{T-t} x\|_2 }{2{(\sigma_{T-t})}^2}}    \cdot e^{-\frac{\|\psi_2(y)-\lambda_{T-t} x\|_2 ^2}{2{(\sigma_{T-t})}^2}} \ d\muast(x)
                \\ &\leq e^{\frac{\|\psi_1(y)-\psi_2 (y)\|_2 \cdot (8R+2\sqrt{d}D)}{{(\sigma_{T-t})}^2}} \varrho_{t}(\psi_2(y)),
            \end{split}
\end{align*}
where the last inequality is because when $y \in \cD_{4R}$ and $x \in K_{\ast}$, similar arguments like \eqref{e: psi_1 in D4R} can deduce that $\psi_2(y) \in \cD_{8R}$, and then $\|\psi_2(y)-\lambda_{T-t} x\|_2 \leq \|\psi_2(y)-\lambda_{T-t} K_{\ast}\|_2+ 2\sqrt{d}D \leq 8R+2\sqrt{d}D$. For this error term, $\|\psi_1(y)-\psi_2 (y)\|_2$, we see that 
    \begin{align*}
        \begin{split}
            &\|\psi_1(y)-\psi_2 (y)\|_2 \leq \|\psi_1(y) - y\|_2 + \|\psi_2(y) - y \|_2 \leq H \big[(\bm\al_1+\bm\al_2)+(\bm\beta_1+\bm\beta_2)\|y\|_2 \big]
            \\  &\leq  H \big[(\bm\al_1+\bm\al_2)+(\bm\beta_1+\bm\beta_2) (\sqrt{d}D + 4R) \big].
        \end{split}
    \end{align*}
Hence, we need to choose $H$ small so that $100 H \big[(\bm\al_1+\bm\al_2)+(\bm\beta_1+\bm\beta_2) (\sqrt{d}D + R) \big] \cdot (\sqrt{d}D + R)\leq \sigma_{T-t} ^2$, and then $\frac{\|\psi_1(y)-\psi_2 (y)\|_2 \cdot (8R+2\sqrt{d}D)}{{(\sigma_{T-t})}^2} \leq 1$. So, the claim of \Cref{lemma: score error cut-off general scheme} follows.





\end{proof}

\begin{proof}[Proof of \Cref{lemma: exponential error term in cut-off}]
    \begin{align*}
        \begin{split}
            \int_{r \geq a} e^{-r ^2} r^b \de r &= \bigg(-\frac{1}{2} r^{b-1} e^{-r^2} \bigg) \bigg|_{r=a} ^{+\infty} + \frac{b-1}{2} \int_{r \geq a} e^{-r ^2} r^{b-2} \de r
            \\  &\leq \frac{1}{2} a^{b-1} e^{-a^2} + \frac{1}{2} \int_{r \geq a} e^{-r ^2} r^b \de r.
        \end{split}
    \end{align*}
This proves \eqref{e:exponential tail of Gaussian}. When we take $\eta = 10^{-2} (\bm\beta_1+\bm\beta_2)^{-1} H^{-1/2}$ and assume \eqref{e: H in cut-off scheme 1} and \eqref{e: H in cut-off scheme 2} in \Cref{lemma: score error cut-off general scheme}, we first see that \eqref{e: H in cut-off scheme 1} and \eqref{e: H in cut-off scheme 2} imply \eqref{e: H in cut-off scheme} by directly plugging this $\eta$ into \eqref{e: H in cut-off scheme}. Then, by \eqref{e: H in cut-off scheme 1}, $\eta \geq 10 (2d \log (2d))^{1/2} \geq 10$. Using \eqref{e:exponential tail of Gaussian}, we see that for $m=1,2,3$,
    \begin{align*}
        E(m,A,B,\eta) \leq {4^m(A+B \sqrt{d}D)}^m \pi^{-\frac{d}{2}} e^{(d+2)\log(2\eta)-4\eta^2}.
    \end{align*}
Because $\eta \geq 10$ and $d \geq 1$, $(d+2)\log(2\eta) \leq 3d \log (\eta ^2) = 6d \log (\eta)$. We can also show that the function $G(\eta) = \eta^2 / \log (\eta)$ is increasing when $\eta \geq 10$, because $G'(\eta) = (2\eta \log (\eta) - \eta)/ (\log(\eta))^2 >0$. So, 
        \begin{align*}
            \eta^2 / \log (\eta) = G(\eta) \geq G(10 (2d \log (2d))^{1/2}) = \frac{200 d \log (2d) }{\frac{1}{2} \log( 200 d \log (2d) ) } = 4d \cdot \frac{\log((2d)^{100})}{\log(200 d \log (2d)) } \geq 4d,
        \end{align*}
    because $d \geq 1$. This shows that  $(d+2)\log(2\eta) \leq 2\eta^2$. Hence, 
    \begin{align*}
        E(m,A,B,\eta) \leq {4^m(A+B \sqrt{d}D)}^m \pi^{-\frac{d}{2}} e^{-2\eta^2}.
    \end{align*}
    We complete the proof of \Cref{lemma: exponential error term in cut-off} because $\eta = 10^{-2} (\bm\beta_1+\bm\beta_2)^{-1} H^{-1/2}$. 
\end{proof}




