\section{Derivatives and Moments Estimates on Forward and Reverse Densities}
\label{s:prel-estim-q}

Under \Cref{assumption:secon-moment}, we take $\lambda_t = e^{-t}$ and $\sigma_t = \sqrt{1- \lambda_t ^2}$ ($t>0$), and we have that
    \begin{align}\label{e: definition of q_t}
        q_t (y) \coloneq \int_{\mathbb{R}^d} \frac{1}{{(\sqrt{2\pi} \sigma_t)}^{d}} \cdot e^{-\frac{\|y-\lambda_t x\|^2}{2{\sigma_t}^2}} \cdot \de \muast(x).
    \end{align}


We recall the following estimates on derivatives of $\log q_t (y)$ proved in Appendix B of~\cite{huang2024convergence}.
\begin{lemma}\label{Lemma: Hessian estimates}
   For any $p \geq 3$, any $y\in\mathbb{R}^d$ and any $t >0$, 
        \begin{align}\label{e: all derivatives log qt}
            \|\nabla^p \log q_t (y)\|_{\infty} \leq (4 p!) \frac{ {\lambda_t} ^p D^p}{ {\sigma_t} ^{2p}} .
        \end{align}
    Also, for any $i,j$,
        \begin{align*}
            |\partial_{y_i} \log q_t (y)| \leq \frac{|y_i| +\lambda_t D}{\sigma_t ^2}, \text{ and } |\partial^2 _{y_i y_j} \log q_t (y)| \leq \frac{\delta_{ij}}{\sigma_t ^2} +  2\frac{\lambda_t ^2 D^2}{\sigma_t ^4}.
        \end{align*}
\end{lemma}   

Next, we estimate the time direction derivatives of $\log q_t(y)$.
\begin{lemma}\label{lemma: time-space derivatives log qt}
 For any $p \geq m \geq 1$, and any multi-index $\gamma$ with $m+ |\gamma| = p$, there exists a computable positive constants $C(m,p)$, such that
    \begin{align*}
        |\partial_t ^m \partial_y^{\gamma} \log q_t(y)| \leq C(m,p) \cdot d^m \cdot {(\|y\|_{\infty}+1)} ^m \cdot {\bigg(\frac{\|y\|_{\infty }+\lambda_t D}{\sigma_t ^2}\bigg)}^{p+m}.
    \end{align*}
\end{lemma}
\begin{proof}
    Let $h_t (y)\coloneq \log q_t(y) + \frac{\|y\|^2}{2}$. A direct computation shows that 
        \begin{align}\label{e: time derivatives of q_t}
            \partial_t h_t (y)= \sum_{i=1} ^d \partial^2 _{ii} h_t(y) + \sum_{i=1} ^d \partial_i h_t (y)\partial_i h_t (y)- \sum_{i=1} ^d \partial_i h_t (y)y_i.
        \end{align}
    Now, we assume that for an $m \in \mathbb{Z}_+$, $\partial_t ^m h_t(u)$ has the following form:
    \begin{align}\label{e: expansion of m time derivative}
        \partial_t ^m h_t(y) = \sum_{\alpha,\beta} y^{\alpha} \partial_y ^{\beta_1} h_t(y) \partial_y ^{\beta_2} h_t(y) \ldots \partial_y ^{\beta_{2m}} h_t(y),
    \end{align}
    where $\alpha$ and $\beta_i$'s are multi-indices and they satisfy that $|\alpha| + |\beta_1| + \ldots +|\beta_{2m}| \leq 2m$, $|\alpha| \leq m$, and there are at most $a_m$ terms in the summation. When some $\beta_i = 0$, we mean that $\partial_y ^{0} h_t(y) = 1$. Then, by induction,
        \begin{align}\label{e: expansion of m+1 time derivative}
            \partial_t ^{m+1} h_t(y) = \sum_{\alpha,\beta} \sum_{j=1} ^{2m} y^{\alpha} \partial_y ^{\beta_1} h_t(y) \ldots \partial_y ^{\beta_j} \partial_t h_t(y) \ldots \partial_y ^{\beta_{2m}} h_t(y). 
        \end{align}
    By \eqref{e: time derivatives of q_t}, we know that
        \begin{align*}
            \partial_y ^{\beta_j} \partial_t h_t(y) = \sum_{i=1} ^d \partial_y ^{\beta_j} \partial^2 _{ii} h_t(y) + \sum_{i=1} ^d \sum_{\gamma_{j} + \gamma' _{j} } (\partial_{y} ^{\gamma_j}\partial_i h_t (y) )(\partial_{y} ^{\gamma' _j}\partial_i h_t (y))- \sum_{i=1} ^d \sum_{\gamma_{j} + \gamma' _{j} } (\partial_{y} ^{\gamma_j}\partial_i h_t (y) )(\partial_{y} ^{\gamma' _j}y_i),
        \end{align*}
    where $\beta_j = \gamma_j + \gamma' _j$, and there are at most $d(1+ 2^{|\beta_j|} + 2^{|\beta_j|}) \leq 3d \cdot 4^m $ terms. Hence, there are at most $a_m  \cdot 6md \cdot 4^m$ terms on the right hand side of \eqref{e: expansion of m+1 time derivative}. Hence, $a_1 = 3d$ and $a_{m+1} = a_m  \cdot 6md \cdot 4^m$, we see that $a_m \leq (6d)^m \cdot m! \cdot 2^{m(m-1)}$ for any $m \in \mathbb{Z}_+$.

    Now, for a derivative $\partial_t ^m \partial_y^{\gamma} h_t(y)$ with $|\gamma| = p-m$ and $m \geq 1$, according to \eqref{e: expansion of m time derivative},
    \begin{align*}
        \partial_t ^m \partial_y ^{\gamma} h_t(y) = \sum_{\alpha',\beta'} y^{\alpha'} \partial_y ^{\beta_1 '} h_t(y) \partial_y ^{\beta_2 ' } h_t(y) \ldots \partial_y ^{\beta_{2m} '} h_t(y),
    \end{align*}
    with $|\alpha '| + |\beta_1 '| + \ldots +|\beta_{2m} '| \leq 2m + |\gamma| = p+m$, $|\alpha '| \leq m$, and there are at most $a_m (2m+1)^{|\gamma|} \leq (6d)^m \cdot m! \cdot 2^{m(m-1)} \cdot (2m+1)^{p-m}$ on the right hand side. For each term of it, according to Lemma~\ref{Lemma: Hessian estimates}, we know that each term on the right hand side has an upper bound
        \begin{align*}
            C(m,p)  \cdot {(\|y\|_{\infty}+1)} ^m \cdot {\bigg(\frac{\|y\|_{\infty }+\lambda_t D}{\sigma_t ^2}\bigg)}^{p+m},
        \end{align*}
    which can also be the upper bound of $|\partial_t ^m \partial_y ^{\gamma} h_t(y)|$ after replacing $C(m,p)$ with another much larger positive constant $C(m,p)$ multiplying $d^m$. 

\end{proof}


The following is the Lemma 2 in Appendix B of \cite{huang2024convergence}, which describes the situation when $t >0$ is very large. We remark that one can also use Lemma 9 in \cite{chen2023improved} to obtain a similar result as \Cref{lemma: qt close to Gaussian}.
\begin{lemma}\label{lemma: qt close to Gaussian}
    Let $q_t(y)$ be defined in \eqref{e: definition of q_t}, and let
        \begin{align*}
            g(y) \coloneq \frac{1}{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|y\|^2}{2}}.
        \end{align*}
    Then, we have that for $t >0$,
        \begin{align}\label{e:qt-q_bound}
            \int_{\mathbb{R}^d} | q_t(y)  - g(y)| \de y \leq \frac{2d(1-\sigma_t)}{{\sigma_t}^{d+3}} + \lambda_t \sqrt{d}D \frac{4+ \lambda_t \sqrt{d}D}{\sigma_t ^2} \cdot e^{\frac{ \lambda_t ^2 d D^2}{2{\sigma_t}^2}}.
        \end{align}
    %In particular, this difference goes to $0$ exponentially as $t \to +\infty$.
 In particular, there exists a universal constant $C_u>0$, such that
\begin{align}\label{e:simplified_bound}
         \int_{\mathbb{R}^d} | q_t(y)  - g(y)| \de y \leq C_u e^{-t}\sqrt d D,
    \end{align}
    which goes to $0$ exponentially as $t\rightarrow +\infty$.

\end{lemma}



Finally, we estimate the moments of $\|x\|_2$ and $\|x\|_{\infty}$.
\begin{lemma}\label{lemma: moments of L^2 and infinity norms}
    For any $t >0$, any $m \in \mathbb{Z}_+$, there is a positive constant $C(m)>0$, such that
        \begin{align*}
        \int_{\mathbb{R}^d} q_{t}(y) \|y\|_{2} ^{m} \de y \leq C(m){d}^{\frac{m}{2}} D^m .
        \end{align*}
and
        \begin{align*}
        \int_{\mathbb{R}^d} q_{t}(y) \|y\|_{\infty} ^{m} \de y \leq C(m) {\big(D+\sqrt{ \log d}\big)}^m.
        \end{align*}
\end{lemma}
\begin{proof}
    Notice that $\muast$ has a compact support $K_{\ast}$ and $D =  1+\max_{x \in K_{\ast}} \|x\|_{\infty} $.
        \begin{align*}
        \begin{split}
            \int_{\mathbb{R}^d} q_t(y) \|y\|_{2} ^m \ \de y &= \int_{\mathbb{R}^d} \int_{\mathbb{R}^d} \frac{\|y\|_{2} ^m }{{(\sqrt{2\pi} \sigma_t)}^{d}} \cdot e^{-\frac{\|y-\lambda_t x\|_2 ^2}{2{\sigma_t}^2}} \cdot \muast(x)  \de x \de y
            \\  &\leq 2^{m-1}\int_{\mathbb{R}^d} \int_{\mathbb{R}^d} \frac{\|y-\lambda_t x\|_{2} ^m + \|\lambda_t x\|_{2} ^m}{{(\sqrt{2\pi} \sigma_t)}^{d}} \cdot e^{-\frac{\|y-\lambda_t x\|_2 ^2}{2{\sigma_t}^2}} \cdot  \muast(x)  \de x \de y
            \\  &\leq 2^{m}\int_{\mathbb{R}^d} \int_{\mathbb{R}^d} \frac{\sigma_t ^m \|z\|_{2} ^m + (\sqrt{d}D)^m}{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}} \cdot  \muast(x)  \de x \de z
            \\  &= 2^{m} \bigg( (\sqrt{d}D)^m + \sigma_t ^m \int_{\mathbb{R}^d} \frac{ \|z\|_{2} ^m }{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}}  \de z \bigg).
        \end{split}
    \end{align*}
Also, 
    \begin{align*}
        \int_{\mathbb{R}^d} \frac{ \|z\|_{2} ^m }{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}}  \de z \leq d^{\frac{m}{2}-1} \sum_{i=1} ^d \int_{\mathbb{R}^d} \frac{ {|z_i|} ^m }{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}}  \de z = C(m)d^{\frac{m}{2}},
    \end{align*}
where $C(m) = \mathbb{E}(|X| ^m)$ for $X$ being a $1$-dimensional unit normal distribution.

Similarly,
    \begin{align*}
        \begin{split}
            \int_{\mathbb{R}^d} q_t(y) \|y\|_{\infty} ^m \ \de y \leq 2^{m} \bigg( D^m + \sigma_t ^m \int_{\mathbb{R}^d} \frac{ \|z\|_{\infty} ^m }{{(\sqrt{2\pi} )}^{d}} \cdot e^{-\frac{\|z\|_2 ^2}{2}}  \de z \bigg).
        \end{split}
    \end{align*}
Now we need to estimate the above integral. Assume that $X_1, X_2,\cdots,X_d$ are i.i.d.~unit normal distributions and we define $M \coloneq \max \{|X_1|, |X_2|,\cdots,|X_d|\}$. We see that for any $r>0$,
    \begin{align*}
        \mathbb{P}(M>r) \leq d \mathbb{P}(|X_1|>r) < 2d \cdot f(r) r^{-1},
    \end{align*}
where $f(r)$ is the density function of a unit normal distribution. Hence,
    \begin{align*}
        \begin{split}
            \mathbb{E}(M^m) &= \int_{0} ^{+\infty} m r^{m-1} \mathbb{P}(M>r) \de r \leq \int_{0} ^{\sqrt{2 \log d}} m r^{m-1}  \de r + 2md\int_{\sqrt{2 \log d}} ^{+\infty}  r^{m-2}f(r) \de r
            \\  &= (2 \log d)^{\frac{m}{2}} + \frac{2^{\frac{m}{2}}md}{\sqrt{\pi}}  \int_{\sqrt{\log d}} ^{+\infty}  r^{m-2}e^{-r^2} \de r
            \\  &\leq {(2 \log d)}^{\frac{m}{2}} + \frac{2^{\frac{m}{2}}m}{\sqrt{\pi}} {(\log{d})}^{\frac{m-3}{2}} \leq (m+1){(2 \log d)}^{\frac{m}{2}},
        \end{split}
    \end{align*}
where we used~\Cref{lemma: exponential error term in cut-off} in the second inequality.
Hence,
    \begin{align*}
        \int_{\mathbb{R}^d} q_t(y) \|y\|_{\infty} ^m \ \de y \leq 2^{m} ( D^m + (m+1){(2 \log d)}^{\frac{m}{2}}) \leq (m+1) 2^{m} {\big(D+\sqrt{2 \log d}\big)}^m .
    \end{align*}

\end{proof}

