\section{Total Variation Estimates along Probability Flow}
\label{section: L^1 error of transport equation}


In this section, we collect some general theorems for continuity equations proved in Appendix A of~\cite{huang2024convergence}.
\begin{theorem}\label{theorem: L^1 error}
    Fix any $0 < \mft < T$. Let $\widehat q_t(x), q_t(x) \in C^1([\mft, T] \times \mathbb{R}^d) \cap L^1 ([\mft, T] \times \mathbb{R}^d) $ solve the following two continuity equations on $\mathbb{R}^d$ respectively,
    \begin{align*}
    \del_t q_t =\nabla \cdot (Z_t
    q_t),\quad
    \del_t \widehat q_t =\nabla \cdot (\widehat Z_t
    \widehat q_t).
    \end{align*}
    We also assume that for $t \in [\mft, T]$, $Z_t, \widehat Z_t$ are locally Lipschitz on $\mathbb{R}^d$. Then, if we denote
    $\delta_t(x) \coloneq  \widehat Z_t(x) - Z_t(x)$, $\widehat\varepsilon_t(x) \coloneq \widehat q_t(x) - q_t(x)$, we have that, 
    \begin{align*}
        \bigg| \int_{\mathbb{R}^d}  | \widehat\varepsilon_{\mft}(x)  | \ \de x  - \int_{\mathbb{R}^d}  | \widehat\varepsilon_{T}(x)  | \ \de x \bigg | \leq \int_{\mft} ^T E(t) \ \de t, \quad \text{with } E(t) \coloneq \int_{\mathbb{R}^d}  \bigg|  (\nabla \cdot (q_{t}\delta_{t} ))(x) \bigg| \ \de x.
    \end{align*}
\end{theorem}

\begin{theorem}\label{theorem: general L^1 error}
    Fix any $0 < \mft < T$. Let $p_t(x) \in C^1([\mft, T] \times \mathbb{R}^d) \cap L^1 ([\mft, T] \times \mathbb{R}^d) $ solve the following continuity equation on $\mathbb{R}^d$ with $h_t(x) \in L^1 ([\mft, T] \times \mathbb{R}^d)$,
    \begin{align*}
    \del_t p_t(x) =(\nabla \cdot (Z_t
    p_t))(x) + h_t(x).
    \end{align*}
    We also assume that for $t \in [\mft, T]$, $Z_t$ is locally Lipschitz on $\mathbb{R}^d$. Then, for almost all $t \in [\mft,T]$, we have that, 
    \begin{align*}
        \bigg| \frac{\de}{\de t} \int_{\mathbb{R}^d}  | p_{t}(x)  | \ \de x  \bigg | \leq \int_{\mathbb{R}^d}  |h_t(x)| \ \de x.
    \end{align*}
Hence,
    \begin{align*}
        \bigg| \int_{\mathbb{R}^d}  | p_{\mft}(x)  | \de x - \int_{\mathbb{R}^d}  | p_{T}(x)  | \de x \bigg | \leq \int_{\mft} ^T \int_{\mathbb{R}^d}  |h_t(x)| \ \de x.
    \end{align*}

\end{theorem}







