\section{Gagliardo-Nirenberg Interpolation Inequality}\label{section:score estimation error}

Finally, we recall the following Gagliardo-Nirenberg interpolation inequality proved in Appendix C of~\cite{huang2024convergence}.
\begin{lemma}[Gagliardo-Nirenberg]\label{lemma: Gagliardo-Nirenberg}
    There is a positive universal constant $C_u$, such that for any $d \in \mathbb{Z}_{+}$, any $w \in L^1(\bR^d)$, any $i \in \llbracket 1,d\rrbracket$, if $\partial^2 _{ii} w \in L^1(\bR^d)$, then
        \begin{align}\label{e: Gagliardo k=2}
        {\bigg(\int_{\mathbb{R}^d}|\partial_i w(x)| \ \de x\bigg)}^{2} \leq C_u \bigg(\int_{\mathbb{R}^d}|\partial^2 _{ii} w(x)| \ \de x\bigg)\bigg(\int_{\mathbb{R}^d}|w(x)| \ \de x\bigg).
        \end{align}
In general, if $\partial^k _{i} w \in L^1 (\bR^d)$ with $k \geq 2$, then
        \begin{align}\label{e: Gagliardo general k}
        \int_{\mathbb{R}^d}|\partial_i w(x)| \ \de x \leq C_u ^{\frac{k-1}{2}}{\bigg(\int_{\mathbb{R}^d}|\partial^k _{i} w(x)| \ \de x\bigg)}^{\frac{1}{k}} {\bigg(\int_{\mathbb{R}^d}|w(x)| \ \de x\bigg)}^{\frac{k-1}{k}}.
        \end{align}
\end{lemma}




