\section{Structure of the Exact Gibbs Sampler from KMS Detailed Balance}
\label{app:DBderivation}
In this section, we provide a detailed derivation of the constraints imposed on the detailed balance Lindbladian by detailed balance, following Ref.~\onlinecite{CKG23}. Our starting point is the Bohr-frequency representation \autoref{eq:TRGdefs}. We will assume (as in the main text) that $\mathcal{L}$ consists either of Hermitian jump operators, or else is `paired' such that  $A^{\pdag}_a$ appears in the set of jump operators $\mathcal{A}$  if and only if $A_a^\dagger$ also appears in $\mathcal{A}$. The reason for this will become apparent below.

Before proceeding, recall that we have already introduced  the ``weighting'' operator $\Gamma_\rho$ involving conjugation with powers of any full-rank state $\rho$:
\begin{equation}
\Gamma_{\rho}[\bigcdot] := \rho^{1/2}(\bigcdot)\rho^{1/2},
\end{equation}
It is convenient to also define a second such operator,
\begin{equation}
\Lambda_{\rho}[\bigcdot] :=\rho^{-1/2} (\bigcdot) \rho^{1/2},
\end{equation}
such that for a Hermitian operator $X$ we have $\Gamma_{\rho}[X]^\dagger =\Gamma_{\rho}[X]$ and $\Lambda_\rho[X]^\dagger = \Lambda_\rho^{-1}[X]$.  

First, we consider the detailed balance condition on the transition part $\mathcal{T}$; a short calculation gives us that
\begin{align}
 (\Gamma_{\rho_\beta}^{-1}\circ \mathcal{T } \circ \Gamma_{\rho_\beta})[\bigcdot] &= \sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{\nu_1, \nu_2} {\rho_\beta}^{-1/2} A^a_{\nu_1}{\rho_\beta}^{1/2}(\bigcdot) {\rho_\beta}^{1/2}(A^a_{\nu_2})^\dagger{\rho_\beta}^{-1/2} \nonumber\\
 &= \sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{\nu_1, \nu_2} e^{\frac{\beta(\nu_1+\nu_2)}2}  A^a_{\nu_1}(\bigcdot)(A^a_{\nu_2})^\dagger.\label{eq:Tconjugated}
\end{align}
where we used the fact that $\rho^{-s} A_\nu \rho^{s} = e^{\beta s \nu } A_\nu$ and hence $\rho^{s} (A_\nu)^\dagger \rho^{-s} = e^{\beta s \nu } (A_\nu)^\dagger$, which follow from  the Bohr frequency representation \autoref{eq:Bohrdef}.

On the other hand, by using $\text{tr}\{\mathcal{O} \mathcal{T}[\rho]\} = \text{tr}\{\rho \mathcal{T}^\dagger[\mathcal{O}]\}$ to determine $\mathcal{T}^\dagger$, we have
\begin{align}
\mathcal{T}^\dagger[\bigcdot] &= \sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{\nu_1, \nu_2} (A^a_{\nu_2})^\dagger (\bigcdot) A^a_{\nu_1} \nonumber\\
&= \sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{\nu_2, \nu_1} (A^a_{\nu_1})^\dagger (\bigcdot) A^a_{\nu_2} &\text{(Relabeling $\nu_1\leftrightarrow \nu_2$)} \nonumber\\
&=\sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{-\nu_2, -\nu_1} (A^a_{-\nu_1})^\dagger (\bigcdot) A^a_{-\nu_2} & \text{(Since if $\nu\in \bohr$ then $-\nu \in \bohr$)}\nonumber\\
&=\sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{-\nu_2, -\nu_1} ((A^{a\dagger})_{-\nu_1})^\dagger (\bigcdot) (A^{a\dagger})_{-\nu_2} & \text{(Since if $A^a\in \mathcal{A}$ then $A^{a\dagger}\in\mathcal{A}$)}\nonumber\\
&=\sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2\in\bohr} \alpha_{-\nu_2, -\nu_1} A^a_{\nu_1}(\bigcdot)(A^a_{\nu_2})^\dagger & \text{(Since $(A_\nu)^\dagger=(A^\dagger)_{-\nu}$)}\label{eq:Tdagger}
\end{align}
Comparing \autoref{eq:Tconjugated} and \autoref{eq:Tdagger}, we see that in order for $\mathcal{T}$ to satisfy the detailed balance condition $\mathcal{T}^\dagger =  \Gamma_\rho^{-1}\circ \mathcal{T} \circ \Gamma_\rho$, we require that the kernel $\alpha_{\nu_1, \nu_2}$ satisfies the condition
\begin{equation}
\alpha_{-\nu_2, -\nu_1} = \alpha_{\nu_1, \nu_2}e^{\frac{\beta(\nu_1+\nu_2)}{2}}.\label{eq:alphaDB}
\end{equation}
We highlight the crucial role played  by the requirement that every jump operator in $\mathcal{T}$ is `paired' with its Hermitian conjugate. Without this, since the left/right action of $A$ and $A^\dagger$ are exchanged under the transformation from $\mathcal{T}$ to $\mathcal{T}^\dagger$, it would not be possible to relate $\mathcal{T}$ and $\mathcal{T}^\dagger$. Physically, the detailed balance parametrized by \autoref{eq:rhoDB} (or \autoref{eq:alphaDB}) relates `downhill' transitions driven by $A_\nu$ with `uphill' transitions driven by $(A^\dagger)_{\nu}$. Note that this is related to the observation (Appendix B of Ref.~\onlinecite{lloyd2024quasiparticle})
 that the rate equation for `quasiparticle cooling' is detailed-balanced only if the jump operators are chosen to be Hermitian. 


We now define $K = G -i\frac{R}{2}$, so that $(\mathcal{G}+\mathcal{R})[\bigcdot] = -i K(\bigcdot) + i(\bigcdot)K^\dagger$, and $(\mathcal{G}+\mathcal{R})^\dagger[\bigcdot]  =
i K^\dagger(\bigcdot)  -i(\bigcdot)K$. 
We can then write
\begin{align}
(\mathcal{G}+\mathcal{R})^\dagger[\bigcdot] - [\Gamma_{\rho_\beta}^{-1} \circ (\mathcal{G}+\mathcal{R}) \circ \Gamma_{\rho_\beta}][\bigcdot] &= i\left(K^\dagger(\bigcdot)  -(\bigcdot)K \right) + i\left( \Lambda_{\rho_\beta}[K](\bigcdot) - (\bigcdot) \Lambda_{\rho_\beta}^{-1}[K]\right)\nonumber
\\&= i(K^\dagger +\Lambda_{\rho_\beta}[K])(\bigcdot) - i(\bigcdot) (K+ \Lambda_{\rho_\beta}[K]^\dagger),\label{eq:GRdb}
\end{align}
where we have used the fact that if $\mathcal{Q}[\bigcdot] = Q_1(\bigcdot) \pm (\bigcdot)Q_2$, then
\begin{equation}
\Gamma_{\rho}^{-1}\circ \mathcal{Q} \circ \Gamma_{\rho}[\bigcdot] = \rho^{-1/2}\left(Q_1 \left(\rho^{1/2}(\bigcdot)\rho^{1/2}\right) \pm \left(\rho^{1/2}(\bigcdot)\rho^{1/2}\right) Q_2 \right)\rho^{-1/2}
 =\Lambda_\rho[Q_1](\bigcdot) \pm (\bigcdot) \Lambda_\rho^{-1}[Q_2],
 \end{equation}
and that $\Lambda_\rho^{-1}[K^\dagger] = \Lambda_\rho^{-1}[G] + \frac{i}{2}\Lambda_\rho^{-1}[R] = \Lambda_\rho[G]^\dagger + \frac{i}{2}\Lambda_\rho[R]^\dagger =\left(\Lambda_\rho[G] -\frac{i}{2}\Lambda_\rho[R]\right)^\dagger = \Lambda_\rho[K]^\dagger$.

Since $\mathcal{G}+\mathcal{R}$ must satisfy detailed balance \autoref{eq:rhoDB} independently of $\mathcal{T}$, we require that the RHS of  \autoref{eq:GRdb} vanishes. This in term requires that
\begin{equation}
    K^\dagger + \Lambda_{\rho_\beta}[K] = 0 + \lambda I
\end{equation}
where $\lambda \in \mathbb{R}$. For simplicity, we will set $\lambda=0$. Now, since $B, R$ are Hermitian, we can write
\begin{align}
K^\dagger + \Lambda_{\rho_\beta}[K] = B  + \frac{i}{2} R +\Lambda_{\rho_\beta}[B] -\frac{i}{2}\Lambda_{\rho_\beta}[R].
\end{align}
Using the explicit forms of $B$ and $R$ in \autoref{eq:TRGdefs} and 
\begin{align}
    \Lambda_{\rho_\beta}[(A^a_{\nu_2})^\dagger A^a_{\nu_1}]  &= \rho_\beta^{-1/2}(A^a_{\nu_2})^\dagger A^a_{\nu_1} \rho_\beta^{1/2}\nonumber\\&= e^{\frac{\beta(\nu_1-\nu_2)}{2}}(A^a_{\nu_2})^\dagger A^a_{\nu_1},
\end{align}
we find that 
\begin{equation}
    K^\dagger + \Lambda_{\rho_\beta}[K] =\sum_{a\in \mathcal{A}}\sum_{\nu_1, \nu_2} \left[ \left( 1 +e^{\frac{\beta(\nu_1-\nu_2)}{2}} \right)g_{\nu_1, \nu_2} +\frac{i}{2}\left( 1 -e^{\frac{\beta(\nu_1-\nu_2)}{2}} \right)\alpha_{\nu_1, \nu_2} \right](A^a_{\nu_2})^\dagger A^a_{\nu_1} 
\end{equation}
Setting this to zero gives us a condition on kernels of the decay and coherent parts such that they together satisfy detailed balance:
\begin{align}
 g_{\nu_1, \nu_2} = \frac{i}{2} \frac{1 -e^{\frac{\beta(\nu_1-\nu_2)}{2}}}{1 +e^{\frac{\beta(\nu_1-\nu_2)}{2}}} \alpha_{\nu_1, \nu_2}= -\frac{1}{2i} \tanh\frac{\beta(\nu_1-\nu_2)}{4}\alpha_{\nu_1, \nu_2}.\label{eq:gexact}. 
\end{align}




\section{Detailed Derivation of Error Bounds I: Lindbladian Evolution and Magnus Expansion\label{app:bound_magnus}}
 In this section, we provide a detailed derivation of the first of the two error bounds used in the main text to derive the upper bound on the total Hamiltonian evolution time needed to prepare a thermal state up so some error $\nB \epsilon$ in trace distance. 



Here, we bound the errors incurred by the Lindbladian evolution and the Magnus expansion: we show that that given $\mathcal K$ as in \autoref{eq:channelev}, and with $\mathcal L_T$ given in \autoref{eq:LDS}, that
\begin{equation}
    \norm{e^{J^2 \mathcal L_{T}}[\rho] - \mathcal K[\rho]}_1 = O \left(\nB J^4 \right).
\end{equation}

\subsection{Bounding the Magnus Approximation Error}

Recall that in the interaction picture, we implement the Hamiltonian
\begin{equation}
		\tilde{H}_{\rm SB}(t) = \sum_a J \{f(t) B_a^\dagger(t) \otimes A_a(t) + f^*(t) B_a(t)\otimes A_a^\dagger(t)\}.\label{eq:Hint2}
	\end{equation}
	Here $B= \tfrac{1}{2}(X_B  - i Y_B)$, and $B^\dagger = \tfrac{1}{2}(X_B + i Y_B)$ are lowering and raising operators for the ancilla, and $f(t)$ is given by \autoref{eq:chosenfilterfunction}.


Using the Magnus expansion, we may express the exact time evolution operator $\tilde{V}$ (see \autoref{eq:Vexact}, reproduced here) for convenience
\begin{equation}
\tilde{V} = \mathcal{T}\exp\left(-i J \int_{-T/2}^{T/2} dt \tilde{H}_{\rm SB}(t) \right)
\end{equation}
up to third order as
	\begin{align}\label{eq:Vmagnus2}
			\tilde{V} = e^{-i \sum_{n=1}^3\tilde{H}_M^{(n)}}  + O(\nB J^4) 
	\end{align}
	with
	\begin{align}
		\tilde{H}_M^{(1)} &= \int_{-{T}/{2}}^{T/{2}}d t_1\, \tilde{H}_{\rm SB}(t_1), \\\nonumber
		\tilde{H}_M^{(2)} &= \frac{1}{2i}\int_{-{T}/{2}}^{T/{2}}d t_1\int_{-{T}/{2}}^{t}d t_2\ [\tilde{H}_{\rm SB}(t_1), \tilde{H}_{\rm SB}(t_2)]\nonumber\\
		\tilde{H}_M^{(3)} &= -\frac{i}{6} \int_{-T/2}^{T/2} dt_1 \int_{-T/2}^{t_1} dt_2 \int_{-T/2}^{t_2} dt_3\,
		\Big( 
		[\tilde{H}_{\rm SB}(t_1), [\tilde{H}_{\rm SB}(t_2), \tilde{H}_{\rm SB}(t_3)]] 
		+ [\tilde{H}_{\rm SB}(t_3), [\tilde{H}_{\rm SB}(t_2), \tilde{H}_{\rm SB}(t_1)]]
		\Big)\label{eq:magnusterms}.
	\end{align}
	Note that the higher-order terms includes commutators between different jump operators (and hence, given our construction, different ancillas $a$, $a'$).

    The error incurred can be bounded by using (a mild generalization of) Theorem 1 of Ref.~\onlinecite{sharma2024simulation}. Adapting their notation to the present setting,  Ref.~\onlinecite{sharma2024simulation}  considers the question of approximating the time evolution operator
    corresponding to evolution under a (potentially time-dependent) $k$-local Hamiltonian  $H_{\rm SB}$, each term of which is supported on a subset $X$ of at most $k$ qubits, in the interaction picture of a geometrically local Hamiltonian $H$. We then have 
    \begin{equation}
        \norm{\tilde{V} - \exp\left(-i\sum_{n=1}^q \tilde{H}_{M}^{(n)} \right) } \leq O(\nB (J d T)^{q+1})\label{eq:magnusboundrephrased}
    \end{equation}
where
    $d = \max_{i} \sum_{X: i\in X} \norm{H_{\rm SB}}$ is the {\it interaction degree} (where the maximum is taken over all sites in the system and bath) of $B_X$, and $\tilde{H}_{\rm SB}(t) = e^{i Ht} {H}_{\rm SB}e^{-i Ht}$ is the time-evolved interaction-picture operator. In our case, $X$ consists of a single site and its ancilla, and  $H_{\rm SB}(t) =\sum_a f(t) A^\dagger_a(t)\otimes B_a(t) +\rm{h.c.}$ is explicitly time-dependent. Note that Ref. ~\onlinecite{sharma2024simulation} explicitly considers time-independent $B_X$, but observe that the generalization to time-dependent $B_X$ is immediate given the nature of their proof as long as $d$ can be bounded at all times. A second comment is in order regarding the scaling with $\nB$ in \eqref{eq:magnusboundrephrased}; Ref.~\onlinecite{sharma2024simulation} do not have a separation of system and bath and so the operator that plays the role $\tilde{H}_{\rm SB}$ simply scales with the system size. Analysing the derivation of their bound (or equivalently, by applying it to each term in the sum within $\tilde{H}_{\rm SB}$ separately) it is clear that the appropriate scaling in our case is with $\nB$ rather than the total size of system and bath together, $\nS +\nB$. In practice of course for effective cooling, $\nB\propto \nS$ so the distinction is not fundamental, but may be relevant for practical considerations where prefactors matter.

    We see that given the choice of filter function, since $\norm{A^\dagger_a(t)\otimes B_a(t)}=1$, we have 
    \begin{equation}
    d =  \max_t |f(t)|=\sqrt{\frac{2}{\pi\sigma^2}}e^{\frac{\beta^2}{8 \sigma^2}}.
\end{equation}
    Elsewhere in the proof, we have that $\beta\lesssim\sigma$, so that we see that we can always take $\max_t |f(t)|=O\left(\frac{1}{\sigma}\right)$. Now, the drive is applied for duration $T=\Tilde O(\sigma)$, characterized by the width of the filter function, so in other words $d = O\left(\frac{1}{T}\right)$. Combining this with \autoref{eq:magnusboundrephrased}, we arrive at \autoref{eq:Vmagnus}.

\subsection{Bounding the Error of the Reset Protocol}

It remains to bound the error of the reset protocol, i.e. the fact that we implement a Lindbladian by effectively ``Trotterizing": the drive followed by reset results in a quantum channel that approximates evolution with the Lindbladian for a short time.

Recall that each time step of our evolution implements the quantum channel
\begin{equation}
\mathcal{K}[\rho] = \tr_B \left[ \tilde{V} \left(\rho^0_B\otimes \rho\right)\tilde{V}^\dagger  \right],
\end{equation}
with
$\rho^0_B =\bigotimes_{a=1}^{\nB} \ket{0_a}\bra{0_a}_B$. Consider $\mathcal{L}_T$ as defined in \autoref{eq:LDScombined}. We argue that if we take $J = \sqrt{\Delta \tau}$, then 
\begin{align}
			\norm{e^{\Delta\tau \mathcal{L}_{T}}[\rho]-\mathcal{K}[\rho]}_1\leq \mathcal{O}(\nB J^4).            
\end{align}
Note that the scaling is one order in $J$ better than naively expected; this is due to the trace over the bath degrees of freedom. We now derive this in detail.

We begin by defining the Magnus-approximated channel
		\begin{align}
			{\mathcal{K}}_M[\rho] = \tr_B \left[  \exp\left(-i\sum_{n=1}^q \tilde{H}_{M}^{(n)} \right) \left(\rho^0_B\otimes \rho\right) \exp\left(i\sum_{n=1}^q \tilde{H}_{M}^{(n)} \right) \right]
		\end{align}
Using the triangle inequality,
\begin{align}
				\norm{e^{\Delta\tau \mathcal{L}_{T}}[\rho]-\mathcal{K}[\rho]}_1\leq 	\norm{e^{\Delta\tau \mathcal{L}_{T}}\rho-{\mathcal{K}}_M[\rho]}_1+	\norm{{\mathcal{K}}_M[\rho]-\mathcal{K}[\rho]}_1
		\end{align}
		The second term has the scaling 
		\begin{align}
			\norm{{\mathcal{K}}_M[\rho]-\mathcal{K}[\rho] } \leq \mathcal{O}\left( \nB J^{4} \right),
		\end{align}
		due to the Magnus expansion error bound \autoref{eq:Vmagnus2} combined with the fact that the partial trace  (over the ancillas) is a contractive operation.

It remains to bound the first term. To do so, we show that $e^{\Delta\tau \mathcal{L}_{T}}\rho$ and ${\mathcal{K}}_M[\rho]$ agree up to $O(\nB J^4)$.
		On the one hand, the identification $J^2=\tau$ gives  
		\begin{align}\label{eq:tLindblad}
			e^{\Delta\tau \mathcal{L}_{T}}[\rho]=\Delta\tau \mathcal{L}_{T}[\rho] +\mathcal{O}(\nB J^4) 
		\end{align}

On the other hand, we consider the expansion of ${\mathcal{K}}_M[\rho]$.
	Due to the trace over ancilla qubits at the end of the protocol and the structure of the system-bath interactions, all odd orders in $J$ cancel. It follows that
	\begin{align}\label{eq:defKrho}
	\begin{split}
		{\mathcal{K}}_M[\rho] &=  \tr_B \left[\tilde{H}_M^{(1)} \left(\rho^0_B\otimes \rho\right) \tilde{H}_M^{(1)} \right]-\frac{1}{2}\tr_B \left[\left(\tilde{H}_M^{(1)}\right)^2 \left(\rho^0_B\otimes \rho\right)+ \left(\rho^0_B\otimes \rho\right)\left(\tilde{H}_M^{(1)}\right)^2 \right]\\&
		-i \tr_B \left[\tilde{H}_M^{(2)} \left(\rho^0_B\otimes \rho\right)- \left(\rho^0_B\otimes \rho\right)\tilde{H}_M^{(2)} \right]
		+\mathcal{O}(\nB J^4).
	\end{split}
	\end{align}
	We consider the first term in detail; the treatment of the other terms proceeds analogously. 	We have  
	\begin{align}
	\begin{split}
		&\tr_B \left[\tilde{H}_M^{(1)} \left(\rho^0_B\otimes \rho\right) \tilde{H}_M^{(1)} \right]\\&=J^2 \sum_{a,a'} \int_{-{T}/{2}}^{T/{2}}d t_1 \int_{-{T}/{2}}^{T/2}d t_2
		 \tr_B\left[\left(f(t_1) B_a^\dagger(t_1) \otimes A_a(t_1) + f^*(t_1) B_a(t_1)\otimes A_a^\dagger(t_1)\right)
		 \left(\rho^0_B\otimes \rho\right)\right.
		 \\&\phantom{\sum_{a,a'} \int_{-{T}/{2}}^{T/{2}}d t_1 \int_{-{T}/{2}}^{T/2}d t_2} 
		 \left.\left(f(t_2) B_{a'}^\dagger(t_2) \otimes A_{a'}(t_2) + f^*(t_2) B_{a'}(t_2)\otimes A_{a'}^\dagger(t_2)\right)
		 \right]\\
	\end{split}
	\end{align}
	Tracing out the bath degrees of freedom forces $a=a'$. Meanwhile, placing the the bath degree of freedom in the $\ket{0}$ state (the reset step) forces the application of $B_a(t_1)$ on the left and $B^\dagger_a(t_2)$ on the right.
Together, these give
	\begin{align}
			\tr_B \left[\tilde{H}_M^{(1)} \left(\rho^0_B\otimes \rho\right) \tilde{H}_M^{(1)} \right]	 = J^2 \sum_a \int_{-{T}/{2}}^{T/{2}}d t_1 \int_{-{T}/{2}}^{T/2}d t_2
		\,f(t_1) f^*(t_2) A_a(t_1) (\cdot) A_a^\dagger(t_2).
	\end{align} 
	Identifying $\Delta\tau=J^2$, this gives the transition part in \autoref{eq:LDScombined}. Similarly, the remaining terms in the expansion \autoref{eq:defKrho} of ${\mathcal{K}}_M[\rho]$ can be respectively identified with the decay and coherent parts of $\mathcal{L}_T$, completing the proof.

\section{Detailed Derivation of Error Bounds II: Fixed-Point Error\label{app:boundfpe}}



In this section, we consider the second of the two error bounds used in the main text. Namely, we obtain an upper bound on the  overall fixed point error, i.e. the difference between the fixed point of the local driving sampler $\mathcal L_{T}$ in \autoref{eq:LDS}, (that we denote $\rho_T$), and the thermal state $\rho_{\beta}$.

We split the total error into two parts using the triangle inequality, viz.
\begin{equation}
    \norm{\rho_T  - \rho_\beta}_1 \leq \norm{\rho_T - \rho_{\infty}}_1 + \norm{\rho_{\infty} - \rho_{\beta}}_1
\end{equation}
where $\rho_\infty$ is the fixed point of  
is the fixed point of  $\mathcal{L}\equiv\lim_{T\to\infty}\mathcal{L}_T$, the infinite time evolution limit of the local driving sampler, i.e.  $\mathcal{L}[\rho_\infty]=0$. 
The two terms on the RHS of the above equation capture different pieces of physics. The first is the error incurred by the fact that the exact sampler involves an infinite-time smoothing, while the local driving sampler is truncated at time $T$. The the second essentially comes from the fact that even as $T\to \infty$, the local driving sampler has the ``wrong'' coherent part, given by the Lamb shift, which we tackle via the so-called ``secular approximation''. We address these in turn.

Note that throughout this section to streamline notation we consider a single jump operator $A$; the generalization to multiple jump operators $A_a$ is straightforward and simply involves a sum over $a$, and all the errors simply pick up  an overall factor of $\nB = |\mathcal{A}|$.

\subsection{Error from finite-time evolution\label{app:bound_finite_time}}
Here, we prove that
\begin{align}
    \norm{\rho_T - \rho_{\infty}}_1 
    \leq 4\,\tmix\, \norm{\mathcal L_{T} - \mathcal L_{\infty}}_{1-1}
    \leq \frac{24}{\pi} \nB \left(\frac{\sigma}{T}\right) e^{-\left(\frac{T}{\sigma}\right)^2} \tmix(\mathcal L_{T})
\end{align}
We can use Lemma II.1 of \cite{CKBG23} to write 
	\begin{align}
		\norm{\rho_T-\rho}_1\leq 4 \,t_{\text{mix}}(\mathcal{L}_T) \norm{\mathcal{L}_{T}-	\mathcal{L}_\infty}_{1-1}.
	\end{align}
Recall that
\begin{equation}
		 \mathcal{L}_{T}[\cdot] = \int_{-{T}/{2}}^{T/{2}}d t_1 \int_{-{T}/{2}}^{T/2}d t_2\,f(t_1) f^*(t_2)\left( -i \left[-\frac{\text{sgn}(t_1-t_2)}{2i}A^\dagger(t_2) A(t_1), \cdot \right]  + A(t_1) (\cdot) A^\dagger(t_2) -\frac{1}{2} \left\{A^\dagger(t_2) A(t_1), \cdot\right\} \right).
	\end{equation}
Since $\mathcal{L}_\infty =\lim_{T\to\infty} \mathcal{L}_T$, using $\|A(t)\|\leq 1$ and  $|\frac{\text{sgn}(t_1-t_2)}{2}|<\frac{1}{2}$, $\left|\Gamma(t_2-t_1)\right|=1$ and the H\"older inequality, we obtain
	\begin{align}
		\norm{\mathcal{L}_T-	\mathcal{L}_\infty}_{1-1}\leq  3\int_{\mathbb{R}_{[T]}}\rd t_1 \int_{\mathbb{R}_{[T]}}\rd t_2\,|f(t_1) f^*(t_2)|=3 \left[\int_{\mathbb{R}_{[T]}}\rd t_1 |f(t_1)|\right]^2
	\end{align}
    where we have defined $\mathbb{R}_{[T]}= \mathbb{R}\backslash[-T/2,T/2]$. For our specific choice of filter function 
	\begin{align}
		f(t)=\sqrt{\frac{2}{\pi \sigma^2}}\e^{-\frac{2}{\sigma^2}\left(t-\frac{\I \beta}{4}\right)^2},
	\end{align}
    we obtain 
	\begin{align}
		\int_{\mathbb{R}_{[T]}}\rd t_1 |f(t_1)|=\mathrm{erfc}\left( \frac{T}{\sigma \sqrt{2}} \right)\leq \frac{\sqrt{2}\sigma}{\sqrt{\pi}T}e^{-\frac{T^2}{2\sigma^2}},
	\end{align}
	where the last bound holds for $\frac{T^2}{2\sigma^2}>1$, which is guaranteed by the choice in \autoref{eq:LDS_params} as $\epsilon\to 0$.
	This leads to the final bound
		\begin{align}
        \norm{\rho_T -\rho}_1 \leq  \frac{24 }{\pi } 
       \left(\frac{\sigma}{T}\right)^2 \e^{-\left(\frac{T}{\sigma}\right)^2} t_{\text{mix}}(\mathcal{L}_T). 
	\end{align}



\subsection{Secular Approximation for the Lamb Shift\label{app:bound_secular}}
We next derive the inequality
\begin{equation}\label{eq:app:bound_secular_final}
    \norm{\rho_{\infty} - \rho_{\beta}}_1 = \Tilde O\left(
        \nB\, \frac{\beta}{\sigma}\, \max(\tmix(\mathcal L_{\infty}), \tmix(\mathcal L_{\rm diss})
    \right)
\end{equation}
The derivation ultimately proceeds by means of implementing the so-called ``secular approximation'', but first we need to perform  some preliminary manipulations involving eigenvector perturbation theory. Much of our treatment is agnostic to specific choices of the filter function, except the very last portions of the proof which impose some requirements of the time-domain asymptotics of $f(t)$. Accordingly we will only specific our choice of $f(t)$ where necessary.

\subsubsection{Preliminaries.} 
We first establish some notation. We denote by $\mathcal{L}_\infty, \mathcal{L}_{\rm sec}$, and $\mathcal{L}_\beta$ the Lindbladians that respectively correspond to the $T\to \infty$ limit of the local-driving sampler $\mathcal{L}_T$, its {\it secular approximation} (to be explained below), and the exact sampler.  These all have identical dissipative parts, but differ in their coherent parts:
\begin{align}\label{eq:Ldefs}
\mathcal{L}_\beta[\bigcdot] &= -i[G, \bigcdot ] + \mathcal{L}_{\rm diss}[\bigcdot]\nonumber\\
\mathcal{L}_\infty[\bigcdot] &= -i[H_{\rm LS}, \bigcdot ] + \mathcal{L}_{\rm diss}[\bigcdot]= -i [B, \bigcdot] + \mathcal{L}_\beta[\bigcdot]  \nonumber\\
\mathcal{L}_{\rm sec}[\bigcdot] &= -i[B_{\rm sec}, \bigcdot] + \mathcal{L}_\beta[\bigcdot] =  -i[B_{\rm sec} +G, \bigcdot] + \mathcal{L}_{\rm diss}[\bigcdot]
\end{align}
where we have defined $B =  H_{\rm LS} - G$, the difference between the coherent parts of the local-driving and exact samplers, and its secular approximation $B_{\rm sec}$ (to be specified below). Note that in contrast to Ref. \onlinecite{CKBG23} (Appendix D), we {\it do not} make a secular approximation for the dissipative part of the sampler. This is because we are bounding the difference between the local-driving sampler and the {\it exact} Gibbs sampler, whereas Ref. \onlinecite{CKBG23} were bounding the difference between a physical system-bath problem and a suitably smoothed approximation of a Davies Lindbladian {\it without} the coherent part necessary to make the latter an exact Gibbs sampler. This difference considerably streamlines our proof relative to that of Ref. \onlinecite{CKBG23}. 

The Lindbladians introduced above satisfy the following fixed-point relations:
\begin{equation}
    \mathcal{L}_\beta[\rho_\beta] = 0; \quad\quad\mathcal{L}_\infty[\rho_\infty] =0; \quad\quad \mathcal{L}_{\rm sec}[\rho_{\rm sec}] =0,
\end{equation}
where the final equation can be viewed as a {\it definition} of $\rho_{\rm sec}$.

We now have by the triangle inequality that
\begin{equation}\label{eq:normtriangle}
    \norm{\rho_\infty-\rho_\beta}_{1} \leq \norm{\rho_\infty-\rho_{\rm sec}}_{1} + \norm{\rho_{\rm sec} -\rho_\beta}_{1}
\end{equation}


Of the remaining two expressions in \autoref{eq:normtriangle}, $\norm{\rho_\infty-\rho_{\rm sec}}_{1}$ can be bounded using Lemma II.1 of Ref. \onlinecite{CKBG23}, yielding
\begin{equation}
    \norm{\rho_\infty-\rho_{\rm sec}}_{1}  \leq 4\norm{\mathcal{L}_\infty - \mathcal{L}_{\rm sec}}_{1-1}\cdot t_{\rm mix}(\mathcal{L}_\infty).
\end{equation}
As we will frequently do, we can use H\"older's inequality to relate $p-p$ norms of superoperators $\mathcal{Q}[\cdot] = -i[Q, \cdot]_{\pm} $ whose sole action is commutation ($-$) or anticommutation ($+$) with some operator $\mathcal{Q}$ to the operator norm of $\mathcal{Q}$, yielding \footnote{This follows since $\norm{\mathcal{Q}}_{p-p} \equiv \sup_{X\neq 0} \frac{\norm{\mathcal{Q}[X]}_{p}}{\norm{X}_p} = \frac{\norm{-i[{Q},X]_{\pm}}_{p}}{\norm{X}_p} \leq \sup_{X\neq 0} \frac{2\norm{\mathcal{Q}}_\infty\norm{X}_p}{\norm{X}_p} = \norm{Q}_\infty$  where we used the triangle inequality to rewrite the commutator in terms of a product and then applied H\"older's inequality to rewrite the numerator.}
\begin{equation}\label{eq:normrhorhosecBBsec}
    \norm{\rho_\infty-\rho_{\rm sec}}_{1}  \leq 8\norm{B - B_{\rm sec}}_\infty\cdot t_{\rm mix}(\mathcal{L}_\infty).
\end{equation}

The second piece is trickier to bound, and requires a use of eigenvector perturbation theory. Specifically, we use the following identity from Ref. \onlinecite{CKBG23}, Appendix E: given two linear [super]operators\footnote{The original argument in Ref.~\onlinecite{CKBG23} is in terms of matrices, but we can view these as superoperators written in the doubled space where density matrices are vectorized, so we give the argument in terms of superoperators here for brevity.} $\mathcal{M}$, $\mathcal{M}'$ (such that $\mathcal{M}'$ is a `small' perturbation of $\mathcal{M}$), with eigenvectors $\ket{v}$, $\ket{v'}$ corresponding to eigenvalues $\lambda, \lambda'$, we have
\begin{equation}\label{eq:eigenvectorPT}
 \norm{\ket{v} - \ket{v'}}_1 \leq \frac{2\sqrt{2} \norm{\mathcal{M}' -\mathcal{M}}_{1-1} + |\lambda-\lambda'|}{\zeta_{-2}(\mathcal{M} - \lambda I)},
\end{equation}
where $\zeta_{-2}(\mathcal{Q})$ is the second smallest singular value of $\mathcal{Q}$.

Although in general eigenvector perturbation theory is poorly behaved for generic non-Hermitian operators (such as $\mathcal{M}, \mathcal{M}'$),  it is possible to choose both to share a common eigenvalue $\lambda=\lambda'=0$: simply choose superoperators $\mathcal{M}, \mathcal{M}'$ which have $\rho_{\rm sec}$ and $\rho_{\beta}$ as fixed points (eigenstates with eigenvalue 0). We can then  relate the $1$-norm distance between the two density matrices to the difference of the superoperators. There is a natural choice for $\mathcal{M} =\mathcal{L}_{\rm sec}$. However, there is a wide range of possible superoperators that can be chosen to have $\rho_\beta$ as a fixed point, due to the latter's central role in defining detailed balance. The nontrivial idea introduced in Ref. \onlinecite{CKBG23} is that this flexibility can be leveraged to obtain a tight bound. An elegant choice is
\begin{equation}
    \mathcal{M}'[\bigcdot]= \rho_\beta^{1/2}\mathcal{L}_2^\dagger[\rho_\beta^{-1/2}\bigcdot \rho_\beta^{-1/2}]\rho_\beta^{1/2},
\end{equation}
with  $\mathcal{L}_2^\dagger[\bigcdot] = -i[B_{\rm sec},\bigcdot] + \mathcal{L}_\beta^\dagger[\bigcdot]$. Observe that $\mathcal{M}'[\rho_\beta]  = \rho_\beta^{1/2}\mathcal{L}_2^\dagger[\mathds{1}]\rho_\beta^{1/2} =0$, by using the fact that 
$\mathcal{L}_2^\dagger[\mathds{1}] = 0$ as long as $\mathcal{L}_2$ is a valid Lindbladian. 

We then have, using the definition \autoref{eq:Ldefs} of $\mathcal{L}_{\rm sec}$ and by rewriting the detailed balance condition as
$ \mathcal{L}_\beta[\bigcdot] - \rho_\beta^{1/2}\mathcal{L}_\beta^\dagger[\rho_\beta^{-1/2}(\bigcdot) \rho_\beta^{-1/2}]\rho_\beta^{1/2}=0$  
that
\begin{align}
(\mathcal{M}' -\mathcal{M})[\bigcdot] &= \rho_\beta^{1/2}\mathcal{L}_2^\dagger[\rho_\beta^{-1/2}(\bigcdot) \rho_\beta^{-1/2}]\rho_\beta^{1/2} -\mathcal{L}_{\rm sec}[\bigcdot]\nonumber\\
& = -i\rho_\beta^{1/2}[B_{\rm sec},\rho_\beta^{-1/2} (\bigcdot) \rho_\beta^{-1/2}]\rho_\beta^{1/2} + \rho_\beta^{1/2}\mathcal{L}_\beta^\dagger[\rho_\beta^{-1/2}(\bigcdot) \rho_\beta^{-1/2}]\rho_\beta^{1/2} + i[B_{\rm sec}, \bigcdot]  -\mathcal{L}_\beta[\bigcdot]\nonumber\\
& = i \left[\left(B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}\right) (\bigcdot) - (\bigcdot)\left(B_{\rm sec} -  \rho_\beta^{-1/2}B_{\rm sec} \rho_\beta^{1/2}\right)  \right]
\end{align}
Using the triangle and H\"older inequalities again, we then have
\begin{equation}\label{eq:MMpnorm}
\norm{\mathcal{M}' -\mathcal{M}}_{1-1} \leq \norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty + \norm{B_{\rm sec} -  \rho_\beta^{-1/2}B_{\rm sec} \rho_\beta^{1/2}}_\infty = 2 \norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty,
\end{equation}
where in the second line we have used $\norm{Q}_* = \norm{Q^\dagger}_*$, with ${Q}=B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}$.

Using the Fan-Hoffmann inequality \cite[Proposition III.5.1]{Bhatia1997book} on the second-smallest singular value\footnote{Note that for any $n\times n$ matrix $A$, $\zeta_j(A) = \zeta_j(-A) \geq \lambda_j\left(-\tfrac{1}{2}(A + A^\dagger)\right) = -\lambda_{n-j+1}\left(\tfrac{1}{2}(A + A^\dagger)\right)$, which yields the identity in \autoref{eq:FanHoffmann} if indexing is understood to be modulo $n$.} of $\mathcal{M}$ (not necessarily Hermitian) we have
\begin{equation}\label{eq:FanHoffmann}
\zeta_{-2}(\mathcal{M}  - \lambda I) \geq -\lambda_2\left(\frac{\mathcal{M}+\mathcal{M}^\dagger}{2} - {\rm Re}(\lambda) I\right)
= -\lambda_2\left({\mathcal{L}_{\rm diss}} - {\rm Re}(\lambda) I\right)
\end{equation}
where $\lambda_2(\mathcal{Q})$ denotes the second largest eigenvalue of $\mathcal{Q}$. Note that in the final step we have simply used  \autoref{eq:Ldefs} with $\mathcal{M} = \mathcal{L}_{\rm sec}$ and recognized that the coherent parts of any Lindbladian $\mathcal{L}$ cancels in $\mathcal{L}+\mathcal{L}^\dagger$.

Finally, we use the results of Ref. \onlinecite{CKBG23}, Appendix E, to relate $\lambda_2(\mathcal{L}_{\rm sec})$ to the Lindbladian gap $\Delta(\mathcal{L}_{\rm diss})$, and therefore the mixing time, via
\begin{equation}\label{eq:l2mixingtimelink}
-\lambda_2(\mathcal{L}_{\rm diss}) \geq \frac{4\sqrt{2}}{4\sqrt{2}+1}\Delta(\mathcal{L}_{\rm diss})  \geq \frac{4\sqrt{2} } {4\sqrt{2}+1}\frac{\ln(2)}{t_{\rm mix}(\mathcal{L}_{\rm diss})}.
\end{equation}


We can now assemble a bound on the second term in \autoref{eq:normtriangle}, by using
\autoref{eq:eigenvectorPT} with $\lambda=\lambda'=0$ and the results in \autoref{eq:MMpnorm}, \autoref{eq:FanHoffmann}, and \autoref{eq:l2mixingtimelink}:
\begin{equation}\label{eq:normrhosecrhobeta}
\norm{\rho_{\rm sec} -\rho_\beta}_{1} \leq \frac{4\sqrt{2}+1 }{\ln 2}\norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty\cdot t_{\rm mix}(\mathcal{L}_{\rm diss}). 
\end{equation}



Putting together \autoref{eq:normrhorhosecBBsec} and \autoref{eq:normrhosecrhobeta}, we finally arrive at a bound on the error of the fixed point of local-driving sampler in terms of secular-approximable quantities and mixing times
\begin{align}\label{eq:errorintermsofsecnorms}
 \norm{\rho_{\infty} - \rho_\beta}_1 &\leq   8\norm{B - B_{\rm sec}}_\infty\cdot t_{\rm mix}(\mathcal{L}_\infty) + \frac{4\sqrt{2}+1 }{\ln 2}\norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty \cdot t_{\rm mix}(\mathcal{L}_{\rm diss})\nonumber\\
  &\leq 10\left(\norm{B - B_{\rm sec} }_\infty+ \norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty\right)\cdot \max(t_{\rm mix}(\mathcal{L}_\infty), t_{\rm mix}(\mathcal{L}_{\rm diss})).
\end{align}
We now turn to computing these norms using the secular approximation, which will allow us to bound the terms in the  RHS of \autoref{eq:errorintermsofsecnorms}. 


\subsubsection{Implementing the Secular Approximation.} 
The secular approximation is most transparently phrased in frequency space (although bounding various contributions is often easier in the time domain). Consider a generic  operator of the form  $B = \sum_{\nu_1,\nu_2\in \bohr} b_{\nu_1, \nu_2} (A_{\nu_2})^\dagger A_{\nu_1}$. The secular approximation of $B$ is obtained by restricting the sum to the ``almost diagonal'' pieces, such that $|\nu_1-\nu_2|\lesssim \mu$, where $\mu$ is some suitably chosen cutoff. Formally, we do this by multiplying the kernel $b_{\nu_1, \nu_2}$ by a suitably chosen ``bump function'',

\begin{equation}
B = \sum_{\nu_1,\nu_2\in \bohr} b_{\nu_1, \nu_2} (A_{\nu_2})^\dagger A_{\nu_1} \implies  B_{{\rm sec}} = \sum_{\nu_1,\nu_2\in \bohr} b_{\nu_1, \nu_2}w\left(\frac{\nu_-}{\mu}\right) (A_{\nu_2})^\dagger A_{\nu_1}
\end{equation}
where $\nu_- \equiv \nu_1 -\nu_2$ and $w(x)$ is a smooth (i.e., infinitely differentiable) function with
\begin{align}
	w(x)=\begin{cases}
		1,\qquad x=0\\
		0,\qquad|x|>1\\
		<1,\qquad \text{else}
		\end{cases}.
\end{align}
For our purposes, it is convenient to choose a bump function such that it remains close to $1$ except in some finite interval near the boundaries at $\pm1$. While a specific choice will not be essential to our argument (modulo this requirement) a concrete  choice is
\begin{equation}
	w(x)=w_1\left(\frac{x+1}{1-\lambda}\right)w_1\left(\frac{1-x}{1-\lambda}\right).
\end{equation}
where we define $w_1(x)$ in terms of another auxiliary function
\begin{equation}
		w_1(x)=\frac{w_2(x)}{w_2(x)+w_2(1-x)}, \quad \quad
		w_2(x)=\begin{cases}
			\exp\left(-\frac{1}{x}\right),\qquad &x>0\\
			0,\qquad  &\text{else}.
			\end{cases}
\end{equation}  
Note that $w$ is zero outside of $[-1,1]$ and one in the interval $[-\lambda,\lambda]$. By choosing $\lambda$ close to one, we can make the function arbitrarily sharp.

The  reason to implement the secular approximation  is that in the limit where we take $\mu\to 0$,  the secular piece is purely diagonal in Bohr frequencies and hence commutes with $\rho_\beta$. An important point is that, depending on the specific function we wish to approximate, a sharp cutoff in frequencies may prove difficult to bound; implementing the secular approximation then requires a judicious use of bump functions (smooth functions that are strictly vanishing outside a compact domain) in order to remove high-frequency terms. This will be the case for our coherent parts.

Evidently, in order to use the secular approximation we must bound  the two separate terms in \autoref{eq:errorintermsofsecnorms}: the  ``almost-commuting'' piece  $B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}$ and the  non-secular piece $B- B_{\rm sec}$. The strategy of proving these bounds is distinct, so we tackle them in turn. 

\subsubsection{Bounding the Almost-Commuting Part.} First, we consider the `almost commuting' piece $\norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty$

Note that we can always choose to write any operator in terms of its Bohr frequency expansion as $B = \sum_{\nu\in \bohr} B_\nu$.  Using the secular approximation, it then follows that
    \begin{align}
    	\norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty=\norm{\sum_{\nu\in\bohr} w\left(\frac{\nu}{\mu}\right) \left(1-e^{-\frac{\beta \nu}{2}}\right) B_\nu}_\infty.
    \end{align}
	We now exploit the fact that $w\left(\frac{\nu}{\mu}\right) \left(1-e^{-\frac{\beta \nu}{2}}\right)<\beta \mu$ for $\beta \mu\leq1$, which places a restriction on the choice of $\mu$. From this, it follows that
	    \begin{align}
		\norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty\leq O\left(\norm{\sum_{\nu\in\bohr} B_\nu}_\infty \beta \mu\right) =O\left(\norm{B}_\infty \beta \mu\right).
	\end{align}
Since $B = H_{\rm LS}-G$, the final step in bounding the almost-commuting piece is therefore to bound the norms of the operators that appear
in the coherent evolution of the exact sampler and the local driving sampler (the latter being the Lamb shift), which we may reduce to bounding the norm of each individually. For both cases, we can show that this is $O(1)$,  by writing the relevant operator as a  time domain integral of an expression quadratic in the jump operators multiplied by some weight function that depends quadratically on the smoothing functions. Since the jump operators can always be fixed to have unit norm by a suitable choice of normalization, we can use triangle inequalities to simplify the bound to one in terms of time domain integrals over the weight functions. For the  Lamb shift the time domain representation is shown in \autoref{eq:HLStimedomain}; the weight functions are just a product of filter functions and so resulting bound on the norm is clearly $O(1)$ due to the normalization of the filter functions. For the exact coherent part, the introduction of the $\tanh\frac{\beta\nu_-}{4}$ complicates the weight functions. It is straightforward but tedious to show 
[cf. Ref.~\onlinecite{CKG23}, Appendix A]  that
		\begin{align}\label{eq:coherenttime}
			G=
			\int_{-\infty}^{\infty}\!\tilde{g}_-(t_-)\e^{-\I H t_-} \left(\int_{-\infty}^{\infty}\tilde{g}_+(t_+)A(t_+)A(-t_+)\rd t_+ \right)\e^{\I H t_-}\rd t_-
		\end{align}
        	with
	\begin{align}
		\tilde{g}_-(t)=\frac{1}{2i} \int_{-\infty}^{\infty}d\nu_-\, e^{i\nu_-t_-}g_-(\nu_-)=\left[\frac{2\sqrt{2\pi}}{\beta \cosh\left(\frac{2\pi t_-}{\beta}\right)}\right]*_{t_-}\left[\frac{\sqrt{2}}{\sigma}e^{\frac{\beta^2-16t_-^2}{4\sigma^2}}\sin\left(\frac{2  \beta t_- }{\sigma^2}\right)\right]
	\end{align}
	and
	\begin{align}
		\tilde{g}_+(t)=\int_{-\infty}^{\infty}d \nu_+\,e^{i\nu_+t_+}g_+(\nu_+)=\frac{4 \sqrt{\pi} e^{-\frac{2}{\sigma^2}\left(t_+ - \frac{i\beta}{4}   \right)^2}}{\sigma}.
	\end{align}
With this in hand, we can use triangle inequalities to write
    	\begin{align}
		\norm{G}_\infty \leq \left(\int_{-\infty}^\infty {d}t_+ |\tilde{g}_+(t_+)|\right) \left(\int_{-\infty}^\infty {d}t_- |\tilde{g}_-(t_-)|\right).
	\end{align}
Since $g_+(t_+)$ is a shifted Gaussian, its integral is bounded. Now, $g_-(t_-)$ is the convolution of two bounded functions, and we can use Young's convolution inequality for the $L_1$ norm to bound the  norm of this convolution terms of the product of the norms. In each case due to the choice of overall normalization the bound is $O(1)$.  Combining the result above, we find that for a single jump operator, 
\begin{equation}
    \norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty = O(\beta\mu)
\end{equation}
Finally, for multiple jump operators $\nB = |\mathcal{A}|$ the errors add independently, so that we finally have
\begin{equation}\label{eq:bound_almost_commuting}
    \norm{B_{\rm sec} -  \rho_\beta^{1/2}B_{\rm sec} \rho_\beta^{-1/2}}_\infty = O(\nB\beta\mu).
\end{equation}

\subsubsection{Bounding the Non-Secular Part.}
The operator $B$ that appears in the error bounds involves the difference between the coherent parts of the local driving sampler (the Lamb shift) and the exact sampler. A sufficient bound obtains by simply using the triangle inequality to bound these pieces separately. Therefore will proceed initially being agnostic to the form of $B$, making general arguments as to the form of the kernel such that the non-secular part $B - B_{\rm sec}$ is bounded, before we specialize to the form dictated by our choice of filter functions.

Consider the non-secular piece
\begin{equation}
B - B_{\rm sec} =  \sum_{\nu_1,\nu_2\in \bohr} b_{\nu_1, \nu_2}\left (1 -w\left(\frac{\nu_-}{\mu}\right)\right) (A_{\nu_2})^\dagger A_{\nu_1}
\end{equation}
Now, let us {\it define} a time-domain kernel $\mathcal{W}(t_1, t_2)$ implicitly via
\begin{equation} \label{eq:nonsecularkerneldef}
b_{\nu_1, \nu_2}\left (1 -w\left(\frac{\nu_-}{\mu}\right)\right) \equiv \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W}(t_1, t_2) e^{i\nu_1 t_1 -i \nu_2 t_2}.
\end{equation}
Using \autoref{eq:nonsecularkerneldef} in our expression for the non-secular part, we have 
\begin{align}
B - B_{\rm sec} &= \sum_{\nu_1,\nu_2\in \bohr} \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W}(t_1, t_2) e^{i\nu_1 t_1 -i \nu_2 t_2} (A_{\nu_2})^\dagger A_{\nu_1}\nonumber\\ &= \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W}(t_1, t_2) A^\dagger(t_2) A(t_1)\label{eq:timedomainBnonsec}
\end{align}
where we have simply used the representation of time evolution in terms of Bohr frequencies. The reason for this step is that the  $A(t)$ are obtained by time-evolving bounded local operators, and therefore their norm has some $O(1)$ bound (which can be set to be $1$ by a suitable choice of normalization, which we henceforth assume). We then find, using \autoref{eq:timedomainBnonsec} and the triangle inequality, that the non-secular part can be bounded by a certain two-dimensional time domain integral:
\begin{equation}\label{eq:nonsecasTDnorm}
\norm{B - B_{\rm sec}}_\infty \leq \left| \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W} (t_1, t_2) \right|.
\end{equation}
Now, we can invert \autoref{eq:nonsecularkerneldef} by recognizing that it is just a Fourier transformation, so that
\begin{equation}\label{eq:BasFT}
\mathcal{W}(t_1, t_2) = \int_{-\infty}^\infty \frac{d\nu_1}{2\pi}  \int_{-\infty}^\infty \frac{d\nu_2}{2\pi} b_{\nu_1, \nu_2}\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{-i\nu_1 t_1 + i\nu_2 t_2}
\end{equation}

To proceed, we need to consider the form of $b_{\nu_1, \nu_2}$. For now, we will simply assume that this has the form $b_{\nu_1, \nu_2} = b_+({\nu_1 + \nu_2}) b_-({\nu_1 -\nu_2})$; this will be the form of the kernel for both $H_{{\rm LS}, f}$ and $G$. We then see, by combining \autoref{eq:nonsecasTDnorm} (with a judicious sign change) with  \autoref{eq:BasFT}, and defining $t_\pm = \frac{t_1\pm t_2}{2}$, $\nu_\pm = \nu_1\pm \nu_2$, that
\begin{align}
\norm{B - B_{\rm sec}}_\infty &\leq  \left| \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W} (t_1, t_2) \right| 
\nonumber\\ &=\left| \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2\, \mathcal{W} (-t_1, t_2) \right|
\nonumber\\ &= \left| \int_{-\infty}^\infty dt_1 \int_{-\infty}^\infty dt_2 \int_{-\infty}^\infty \frac{d\nu_1}{2\pi}  \int_{-\infty}^\infty \frac{d\nu_2}{2\pi} b_+({\nu_+}) b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_1 t_1 + i\nu_2 t_2}\right|
\nonumber\\&\leq  \int_{-\infty}^\infty dt_+ \left| \int_{-\infty}^\infty \frac{d\nu_+}{2\pi} b_+(\nu_+) e^{i \nu_+ t_+}\right|\times
\int_{-\infty}^\infty dt_- \left| \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_-t_-}\right|
\nonumber\\&\leq \int_{-\infty}^\infty dt_+ |\widehat{b_+}(t_+)| \times \int_{-\infty}^\infty dt_- \left| \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_-t_-}\right|\label{eq:workingsecular}
\end{align}
where $\widehat{b_+}(t_+)$ is the inverse Fourier transform of $b_+(\nu_+)$. 

We find that in the two cases of interest to us, $|\widehat{b_+}(t_+)|$ takes the simple form
\begin{equation}\label{eq:app:gplus_explicit}
|\widehat{b_+}(t_+)| = |\widehat{h_+}(t_+)| = |\widehat{g_+}(t_+)| =  \frac{1}{\sqrt{\pi}\sigma}  e^{\beta^2/4\sigma^2} e^{-4t_+^2/\sigma^2}
\end{equation}
Therefore, we can express the first term in the product on the RHS of the final inequality \autoref{eq:workingsecular} above as
\begin{equation}
\int_{-\infty}^\infty dt_+ |\widehat{b_+}(t_+)|  = \frac{e^{\beta^2/4\sigma^2}}{2}\label{eq:nuplusbound}
\end{equation}
in both the coherent and exact cases, which will only give an overall constant prefactor.

Perhaps unsurprisingly, the nontrivial bound involves the integration over $t_-$ in \autoref{eq:workingsecular}. It is useful to split this into a short-time contribution $\mathcal{I}_1$ with $t\in [-t_0, t_0]$ and a long-time contribution $\mathcal{I}_2$ with  $|t|>t_0$, with $t_0$ to be specified below. The short-time piece is given by 
\begin{align}
     \mathcal{I}_1 \equiv \int_{-t_0}^{t_0} dt_- \left| \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_-t_-}\right| &\leq 2t_0  \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} \left| b_-({\nu_-})\right|\left| 1- w\left(\frac{\nu_-}{\mu}\right)\right|.\label{eq:shorttime1}
\end{align}
Given our choice of bump function, $1- w\left(\frac{\nu_-}{\mu}\right)$ is only nonzero for $\nu_-\gtrsim \mu$, where it is close to $1$, so that the integral is dominated by the tails, and we have
\begin{equation}
\int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} \left| b_-({\nu_-})\right|\left| 1- w\left(\frac{\nu_-}{\mu}\right)\right|  = O\left(2 \int_{\mu}^\infty \frac{d\nu_-}{2\pi} \left| b_-({\nu_-})\right|\right) = O\left(\frac{e^{-\frac{\sigma^2\mu^2}{16}}}{\sigma^2 \mu} \right)\label{eq:shorttime2}
\end{equation}
where in the second step  we have used the fact that both $|b_-|\leq e^{-(\sigma \nu_-)^2/16}$ for either choice $b_- = g_-, h_-$. Combining \autoref{eq:shorttime1} and \autoref{eq:shorttime2}, we have
\begin{equation}
    \mathcal{I}_1 = O\left(\frac{t_0 e^{-\frac{\sigma^2\mu^2}{16}}}{\sigma^2 \mu} \right)\label{eq:I1bound}
\end{equation}

We turn next to the long-time contributions. By integrating by parts twice, we observe that
\begin{align}
\int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_-t_-} = -\frac{1}{t_-^2}\int_{-\infty}^\infty  \frac{d\nu_-}{2\pi}\, \frac{d^2}{d\nu_-^2} \left[b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right)\right] e^{i\nu_-t_-}.
\end{align}
We can then use this result to obtain a useful bound on the long-time contributions,
\begin{align}
    \mathcal{I}_2 &\equiv \int_{\mathbb{R}\backslash[-t_0,t_0]}dt_-\left|\int_{-\infty}^\infty  \frac{d\nu_-}{2\pi} b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right) e^{i\nu_-t_-}\right| \nonumber\\
    &\leq \frac{2}{t_0} \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi}\, \left|\frac{d^2}{d\nu_-^2} \left[b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right)\right] \right|.\nonumber\\ \label{eq:intermediateboundlongtime}
\end{align}
Using the product rule, we have that
\begin{equation}
\frac{d^2}{d\nu_-^2} \left[b_-({\nu_-})\left( 1- w\left(\frac{\nu_-}{\mu}\right)\right)\right] =\left( 1- w\left(\frac{\nu_-}{\mu}\right) \right) b_-''(\nu_-) + \frac{1}{\mu} b'_-(\nu_-) w'\left(\frac{\nu_-}{\mu}\right) + \frac{1}{\mu^2} b_-(\nu_-) w''\left(\frac{\nu_-}{\mu}\right), \label{eq:productrule}
\end{equation}
so that on inserting \autoref{eq:productrule} into \autoref{eq:intermediateboundlongtime} and using the triangle inequality that
\begin{align}
 \mathcal{I}_2 &\leq \frac{2}{t_0} \int_{-\infty}^\infty  \frac{d\nu_-}{2\pi}\,\left( \left| \left( 1- w\left(\frac{\nu_-}{\mu}\right) \right) b_-''(\nu_-) \right|
 + \left|\frac{1}{\mu} b'_-(\nu_-) w'\left(\frac{\nu_-}{\mu}\right)  \right| +  \left|\frac{1}{\mu} b_-(\nu_-) w''\left(\frac{\nu_-}{\mu}\right)  \right|\right)\label{eq:productrulesplitbound}
\end{align}

Let us now consider the two choices $b_- =h_-, g_-$ corresponding to the local driving and exact samplers. We have that $h_-(\nu_-) \propto e^{-(\sigma\nu_-)^2/16}$, whereas $h_-(\nu_-) \propto \tanh\left(\frac{\beta\nu_-}4\right) e^{-(\sigma\nu_-)^2/16}$. Crucially, the $\tanh$ that appears in the 
latter case has a bounded derivative everywhere, and so is relatively innocuous when inserted into \autoref{eq:productrulesplitbound}. Therefore,  after a  scaling analysis (that we do not reproduce here as it is straightforward but tedious) we can show that each term in \autoref{eq:productrulesplitbound} takes the form ${\rm Lpoly}(\beta\nu, \sigma\nu) \times e^{-(\sigma\nu_-)^2/16}$, where ${\rm Lpoly}$ represents some Laurent polynomial of bounded negative and positive degrees. Meanwhile, for our choice of bump function, $w'(\nu_-/\mu)$ and $w''(\nu_-/\mu)$ are both O(1) around $\nu_-/\mu\sim 1$ or vanish otherwise, whereas as stated before $1-w(\nu_-/\mu)$ is only nonzero outside the bounded domain $[-\mu, \mu]$.  
Combining these results, it is evident that we can bound the various terms in \autoref{eq:productrulesplitbound} as
\begin{equation}
\mathcal{I}_2 = O\left(\frac{\sigma}{t_0} {\rm Lpoly}(\beta\mu, \sigma\mu)e^{-(\sigma\mu)^2/16}\right) \label{eq:I2bound}
\end{equation}
which results from considering that the integrals only receive contributions either near $\pm \mu$ or $(\pm \mu, \infty)$, rescaling the integrand, and estimating the weight due to the Gaussian factors, and the $\beta$-dependence will only appear for the exact sampler.  Combining the bound \autoref{eq:nuplusbound} on the $\nu_+$ integral  with the bounds \autoref{eq:I1bound} and \autoref{eq:I2bound} respectively and setting $\sigma = t_0$ 
\begin{equation}
    \norm{B - B_{\rm sec}}_\infty = O\left( {\rm Lpoly}(\beta\mu, \sigma\mu)e^{-(\sigma\mu)^2/16}\right)
\end{equation}

Again, for the case of multiple jump operators $\nB = |\mathcal{A}|$ the errors add independently, so that we have
\begin{equation}\label{eq:bound_non_sec}
    \norm{B - B_{\rm sec}}_\infty = O\left( \nB\,{\rm Lpoly}(\beta\mu, \sigma\mu)e^{-(\sigma\mu)^2/16}\right)
\end{equation}

Now, substituting \autoref{eq:bound_non_sec} and \autoref{eq:bound_almost_commuting} into \autoref{eq:errorintermsofsecnorms} we obtain
\begin{equation}
    \norm{\rho_{\infty} - \rho_{\beta}}_1 = O \left( 
    \nB\, \left[
        \beta \mu + {\rm Lpoly}(\beta\mu, \sigma\mu)e^{-(\sigma\mu)^2/16}
    \right] \max(t_{\rm mix}(\mathcal{L}_\infty), t_{\rm mix}(\mathcal{L}_{\rm diss})
    \right)
\end{equation}
which for some choice of $\mu = \Tilde O(\sigma^{-1})$ (the $\Tilde O$ now hiding extra-log factors necessary to suppress the second term above) yields the desired result in \autoref{eq:app:bound_secular_final}.


\subsubsection{Choice of Filter Functions and Kernels.} 

To complete the proof, we must obtain the relevant functions $b_+, b_-$ for the two samplers in question, for a specific filter function, and confirm that they satisfy the properties assumed in the proof above. While this can be done for arbitrary sufficiently quickly decaying $f(t)$, for concreteness here we present results for the specific choice \autoref{eq:chosenfilterfunction} in the main text.

With this choice, we see that the Lamb shift kernel in \autoref{eq:LSkernel} is given by (taking $T\to\infty$ as we have throughout the secular approximation, and dropping the superscript $T$)
\begin{align}
-2i h_{\nu_1, \nu_2} &= \int_{-{\infty}}^{\infty}d t_1 \int_{-{\infty}}^{\infty}d t_2\, \text{sgn}(t_1-t_2) f(t_1) f^*(t_2)  e^{i\nu_1 t_1 - i \nu_2 t_2} \nonumber\\
&= \int_{-\infty}^\infty \mathrm{d}t_1\,\int_{-\infty}^\infty \mathrm{d}t_2\, {\rm sgn}(t_1+t_2)f(t_1)f^*(-t_2)e^{i \nu_1 t_1} e^{i \nu_2 t_2}\nonumber\\
	&= 2 \int_{-\infty}^\infty \mathrm{d}t_+\,\int_{-\infty}^\infty \mathrm{d}t_-\, {\rm sgn}(t_+)f(t_++t_-)f^*(-t_++t_-) e^{i \nu_+ t_+} e^{i \nu_- t_-}
\end{align}
We can further simplify the integrand as follows:
\begin{align}
	f(t_++t_-)f^*(-t_++t_-)&=\frac{2}{\pi \sigma^2}\exp\left\{-\frac{2}{\sigma^2}\left[\left(\left(t_+-\frac{i\beta}{4}\right)+t_-\right)^2+\left(\left(t_+ - \frac{i\beta}{4}\right)-t_-\right)^2\right]\right\}\nonumber\\
    &
	=\frac{2}{\pi \sigma^2}\exp\left[-\frac{4}{\sigma^2}\left(t_+-\frac{i\beta}{4}\right)^2\right]
\exp\left[-\frac{4}{\sigma^2}t_-^2\right].
\end{align}
From this, we obtain
\begin{align}
\begin{split}
	h_{\nu_1,\nu_2}=
	h_+(\nu_+)h_-(\nu_-).
\end{split}
\end{align}
Here,
\begin{align}
	h_+(\nu_+)=-\frac{1}{2 i}\int_{-\infty}^\infty \mathrm{d}t_+ \frac{2}{\sqrt{\pi}  \sigma}{\rm sgn}(t_+)\exp\left[-\frac{4}{\sigma^2}\left(t_+ -\frac{i \beta}{4}\right)^2\right]
	e^{-i\nu_+t_+}
\end{align}
which gives us that 
\begin{equation}
|\widehat{b_+}(t_+)| = \left|\frac{i}{\sqrt{\pi} \sigma}{\rm sgn}(t_+)\exp\left[-\frac{4}{\sigma^2}\left(t_+ - \frac{i \beta}{4}\right)^2\right]\right| =\frac{1}{\sqrt{\pi}\sigma}  e^{\beta^2/4\sigma^2} e^{-4t_+^2/\sigma^2}
\end{equation}
and hence satisfies the assumption of Gaussian decay at large $t_+$. Meanwhile,  we have
\begin{align}
h_-(\nu_-)=\int_{-\infty}^\infty \frac{\mathrm{d}t_-}{\sqrt{\pi} \sigma} e^{-\frac{4}{\sigma^2}t_-^2} e^{-i\nu_-t_-}=\frac{1}{2} e^{-\frac{1}{16}\sigma^2\nu_-^2}.
\end{align}
which has the form of a bounded function (in this case a constant) multiplied by a Gaussian.

For the exact sampler, instead, we have that $\alpha_{\nu_1, \nu_2} = \exp[ -(\sigma\nu_1)^2/8 -(\sigma\nu_2)^2/8 -\beta\nu_1/4-\beta\nu_2/4]$, which yields
\begin{equation}
g_{\nu_1,\nu_2} =  -\frac{1}{2i} \tanh\frac{\beta(\nu_1-\nu_2)}{4}\alpha_{\nu_2, \nu_2} = g_+(\nu_+) g_-(\nu_-)
\end{equation}
with
\begin{equation}
g_+(\nu_+) = \frac{i}{2} e^{-\beta\nu_+/4} e^{-\frac{(\sigma \nu_+)^2}{16}}\quad \text{and} \quad g_-(\nu_-) = \tanh \frac{\beta\nu_-}{4} e^{- \frac{(\sigma\nu_-)^2}{16}}
\end{equation}
Evidently, $g_-$ once again has the form of a bounded function multiplying a Gaussian. Turning finally to the Fourier transform fo $g_+$, we have
\begin{align}
|\widehat{g_+}(t_+)| &= \left| \frac{i}{2}\int_{-\infty}^\infty \frac{d\nu_+}{2\pi}e^{-\beta\nu_+/4} e^{-\frac{(\sigma \nu_+)^2}{16}} e^{i\nu_+t_+}\right| \nonumber\\&= \left| \frac{i}{\sqrt{\pi}\sigma}\exp\left[-\frac{4}{\sigma^2}\left(t_+ - \frac{i \beta}{4}\right)^2\right] \right| \nonumber\\&= \frac{1}{\sqrt{\pi} \sigma} e^{\beta^2/4\sigma^2} e^{-4t_+^2/\sigma^2}
\end{align}
which is identical to $|\widehat{h_+}(t_+)|$ and in particular of exactly the form assumed in \autoref{eq:app:gplus_explicit}.

\section{Bounding the error in dropping the ``rewinding''\label{app:rewindingerror}}

In this appendix, we show that dropping the rewinding procedure in our protocol adds to the total error bound in a controllable way, namely that the error bound for the original protocol increases by a factor of $2\tmix$ [cf. \autoref{eq:rewindingerror} in the main text].

Concretely, we consider a channel $\mathcal K'$ defined as
$\mathcal K'[\sigma] \equiv V \mathcal K[\sigma] V^{\dagger}$ for some unitary $V$, and a state $\rho_{\beta}$ that invariant under conjugation with $V$: $V \rho_{\beta} V^{\dagger} = \rho$. We assume that fixed point of $\mathcal K$, $\rho$, ($\mathcal K[\rho] = \rho$) is close to $\rho_{\beta}$: $\norm{\rho - \rho_{\beta}}_1 \leq \delta$ for some $\delta > 0$.  We then show that
\begin{equation}\label{eq:app:rewinding_final}
    \norm{\rho' - \rho_{\beta}}_1 \leq 4\delta \tmix
\end{equation}
where $\rho'$ is the fixed-point of $\mathcal K'$ and $\tmix$ the mixing time of $\mathcal K$, respectively.

As preliminaries, observe that since the channel $\mathcal K$ is contracting w.r.t. to the Schatten 1-norm,
\begin{equation} 
    \norm{\mathcal K[\rho_{\beta}] - \rho}_1 
    = \norm{\mathcal K[\rho_{\beta}] - \mathcal K[\rho]}_1
    \leq \norm{\rho_{\beta} - \rho}_1 
    \leq \delta.
\end{equation}
Furthermore, because the Schatten 1-norm is preserved under unitary conjugation,
\begin{equation}
    \norm{\mathcal K'[\rho_{\beta}] - \rho_{\beta}}_1
    = \norm{V \mathcal K[\rho_{\beta}] V^\dagger - \rho_{\beta}}_1 
    \leq \norm{V \left(\mathcal K[\rho_\beta] - \rho \right) V^\dagger}_1
        + \norm{V \left(\mathcal \rho - \rho_{\beta} \right) V^\dagger}_1
    \leq 2\delta.
\end{equation}

Now, for the fixed point $\rho'$ of $\mathcal K'$, we have
\begin{equation}\label{eq:app:rewinding_intermediate1}
    \norm{\rho' - \rho_{\beta}}_1 
    = \norm{\mathcal K'[\rho'] - \rho_{\beta}}_1
    \leq \norm{\mathcal K'[\rho'] - \mathcal K'[\rho_{\beta}]}_1
        + \norm{\mathcal K'[\rho_{\beta}] - \rho_{\beta}}_1
    \leq \eta \norm{\rho' - \rho_{\beta}}_1  + 2 \delta
\end{equation}
where $\eta \in [0, 1)$ is the \emph{contraction} factor
\begin{equation}
    \eta' \equiv 
    \sup_{\omega\neq \zeta} \frac{\norm{\mathcal K'[\omega] - \mathcal K'[\zeta]}_1}{\norm{\omega - \zeta}_1} 
    = \sup_{\omega\neq \zeta} \frac{\norm{\mathcal K[\omega] - \mathcal K[\zeta]}_1}{\norm{\omega - \zeta}_1} = \eta
\end{equation}
where the second inequality follows from the definition of $\mathcal K$.
Note that $\eta < 1$ under the assumption that $\mathcal K$ is primitive (that is irreducible and aperiodic), i.e. that any initial state converges to a unique fixed point.
Rearranging \autoref{eq:app:rewinding_intermediate1} then gives
\begin{equation}
    \norm{\rho' - \rho_{\beta}}_1 \leq \frac{2\delta}{1-\eta}.
\end{equation}

What is left to show to obtain \autoref{eq:app:rewinding_final} is then to relate the contraction factor $\eta$ to the mixing time $\tmix$. 
To this end, note that  the contraction factor lower bounds the second-largest absolute value in the spectrum of $\mathcal K$, which in turn lower bounds the mixing time (see e.g. Lemma 30 of Ref. \onlinecite{kastoryano2012quantum_sobolev}):
\begin{equation}
\frac{1}{1-\eta} \leq \frac{1}{1-\abs{\lambda_1}} \leq 2 \tmix
\end{equation}
Substituting this above then yields the final result
\begin{equation}
    \norm{\rho' - \rho_{\beta}}_1 
    \leq \frac{2\delta}{1-\eta}
    \leq 4 \delta \tmix
\end{equation}





