\section{Theory}

\subsection{Notation and Definitions}

We let $\mathcal{V}^{K}$ denote the set of tree-structured step functions on $\mathcal{X}\times (0,1)\to \mathbb{R}$ with $K$ terminal nodes. We use the notation $\lesssim$ and $\gtrsim$ to denote inequality up to a universal constant. Given a function $g:A\times B\to C$ and any fixed $b\in B$, we use $g(\cdot,b)$ to denote the partial application from $A$ to $C$ given by $a\mapsto g(a,b)$.

\begin{defn}

  We define the \emph{single quantile loss} $\ell(\bm{X},Y;\tau)$ as the usual check-loss in estimation of the single conditional quantile $\tau$ by the $\tau$-conditional quantile candidate $h:\mathcal{X}\to\mathbb{R}$ given by
  \[
    \ell(\bm{X},Y,h;\tau)=\rho_{\tau}(h(\bm{X})-Y)\,.
  \]
  We also define the \emph{expected quantile loss} $\ell(\bm{X},Y,\mu)$ as the average check-loss incurred by a uniformly sampled quantile value for the single datapoint $\bm{X},Y$. This is expressed as
  \begin{equation}
    \ell(\bm{X}, Y, \mu) := \int_{0}^{1} \rho_{\tau}(\mu(\bm{X},\tau) - Y)\,\mathrm{d}\tau.
    \label{eq:single-expected-quantile-loss}
  \end{equation}
  Similarly, the \emph{expected quantile risk} $R(\mu)$ of a conditional quantile function estimator $\mu: \mathcal{X}\times (0,1)\to \mathbb{R}$ is given by the expectation
  \begin{equation}
    \ell(\mu) := \mathbb{E}_{\bm{X},Y\sim P_{\bm{X},\bm{Y}}}\left[\int_{0}^{1} \rho_{\tau}(\mu(\bm{X},\tau) - Y)\,\mathrm{d}\tau\right].
    \label{eq:empirical-expected-quantile-risk}
  \end{equation}
  Finaly, we also define its empirical version given $n$ datapoints $\bm{X},\bm{Y}$ as
  \begin{equation}
    \ell_{n}(\mu;\bm{X}, \bm{Y}) := \frac{1}{n}\sum_{i=1}^{n}\int_{0}^{1} \rho_{\tau}(\mu(X_{i},\tau) - Y_{i})\,\mathrm{d}\tau.
    \label{eq:empirical-expected-quantile-risk}
  \end{equation}

  We define the $\bm{r}$\emph{-Monte Carlo quantile loss} as a Monte Carlo approximation of the above by $r$ samples
  \begin{equation}
    \ell^{(r)}(\bm{X}, Y, \mu; \bm{\tau}) := \frac{1}{r}\sum_{j=1}^{r} \rho_{\tau_{j}}(\mu(\bm{X},\tau_{j}) - Y)
    \label{eq:single-mc-emp-quantile-loss}
  \end{equation}
  Similarly, we define the $\bm{r}$\emph{-Monte Carlo quantile risk} via the expectation
  \begin{equation}
    \ell^{(r)}(\mu; \bm{\tau}) := \frac{1}{r}\sum_{j=1}^{r}\mathbb{E}_{\bm{X},\bm{Y}}\left[ \rho_{\tau_{j}}(\mu(\bm{X},\tau_{j}) - Y)\right]
    \label{eq:mc-emp-quantile-risk}
  \end{equation}
  and, its empirical version given $n$ data points as
  \begin{equation}
    \ell_{n}^{(r)}(\mu;\bm{X}, \bm{Y}, \bm{\tau}) := \frac{1}{nr}\sum_{i=1}^{n}\sum_{j=1}^{r} \rho_{\tau_{j}}(\mu(X_{i},\tau_{j}) - Y_{i})
    \label{eq:mc-emp-quantile-risk}
  \end{equation}
  where $\tau_{1},\ldots,\tau_{r}\overset{\mathrm{iid}}{\sim} \mathcal{U}(0,1)$.
  %Note that the $r$-Monte Carlo quantile risk and its empirical version are random quantities due to their dependence on $\bm{\tau}$.
\end{defn}


\begin{lemma}\label{lem:approximation}

  Under Assumption~\ref{assn:main}, there exists a tree-structured step function $\mu_{\widehat{\mathcal{T}},\widehat{\beta}}\in\mathcal{V}^{K}$ for some $K=2^{s\,(d+1)}$ with $s\in\mathbb{N}\setminus\{0\}$ such that
  \[
\|\mu_{0}-\mu_{\widehat{\mathcal{T}},\widehat{\beta}}\|_{\infty}\leq \|\mu_{0}\|_{\mathcal{H}^{\alpha}} C M^{\alpha} (d+1)/K^{\alpha/(d+1)}
  \]
\end{lemma}

\begin{proof}
  Following the proof of Lemma 3.2 in~\citet{rockova2020posterior}, for any valid tree partition $\mathcal{T}=\{\Omega_{k}:k\in[K]\}$, there exists a step function $\mu_{\mathcal{T}, \widehat{\beta}}$ such that for any $k\in [K]$, for any $\bm{x}\in \Omega_{k}\cap \left(\mathcal{X}\times [0,1]\right)$, we have
  \[
    \lvert \mu(\bm{x}) - \mu_{\mathcal{T}, \widehat{\beta}}(\bm{x})\rvert \leq \|\mu\|_{\mathcal{H}^{\alpha}}\mathrm{diam}^{\alpha}(\Omega_{k}; \mathcal{S})\,.
  \]
  Taking $\widehat{\mathcal{T}}$ to be a $k$-$d$ tree partition $\{\widehat{\Omega}_{k}:k\in [K]\}$ (refer to \citep{rockova2020posterior}), and taking the supremum over $\bm{x}\in \mathcal{X}$ yields
  \[
    \|\mu-\mu_{\widehat{\mathcal{T}}, \widehat{\beta}}\|_{\infty} < C_{\mathrm{max}}\|\mu\|_{\mathcal{H}^{\alpha}} \max_{1\leq k\leq K}\mathrm{diam}^{\alpha}(\widehat{\Omega}_{k}; \mathcal{S})
  \]
  for some absolute constant $C_{\mathrm{max}}>1$. The same technique used in the proof of Theorem 3.2 of~\citet{rockova2020posterior} then yields the desired conclusion.
\end{proof}

\subsection{Proof of Theorem~\ref{thm:concentration}}\label{sec:concentration-thm-proof}

\begin{proof}

  We employ Theorem 4.1 of \citet{syring20_gibbs_poster_concen_rates_under}. The authors provide a set of sufficient conditions on our prior distribution and loss function to achieve concentration of the Gibbs posterior around $\mu_{0}$ at a particular rate. We verify these sufficient conditions given the setting in Assumption~\ref{assn:main}.


  \paragraph{Condition 2.} Observe that the loss function $\ell^{(r)}$ (defined in~\eqref{eq:single-mc-emp-quantile-loss}) is of the form
  \[
    \ell^{(r)} = \sum_{j=1}^{r}\ell(\cdot\,;\tau_{j})\,.
  \]
  From the proof of Proposition 8 in~\citep{syring20_gibbs_poster_concen_rates_under}, there exists $K>0$ such that for $\mu \in \mathcal{F}_{n}$, the loss $\ell(\cdot\,;\tau): \mathcal{F} \to \mathbb{R}$ satisfies
  \[
    \mathbb{E}_{\bm{X},Y\sim P}\left[\exp\left(-\omega_{n} \left( \ell(\bm{X},Y,\mu;\tau) - \ell(\bm{X},Y,\mu_{0}(\cdot,\tau);\tau) \right)\right) \right] \leq \exp \left( -K_{n} \omega_{n} \varepsilon_{n}^{2} \right)
  \]
  with $K_{n}=(K/2)\log(n)^{-2p}$. We note that this requires Assumption~\ref{assn:main}.3. Therefore, we have for $\mathcal{F}_{n}=\{\mu:\|\mu\|_{\infty}\leq \log^{p}(n)\}$,
  \begin{align*}
   &\mathbb{E}_{\bm{X},Y\sim P}\left[\exp\left(-\omega_{n} \left( \ell^{(r)}(\bm{X},Y,\mu) - \ell^{(r)}(\bm{X},Y,\mu_{0}) \right)\right)\right] \\ =\,\,& \mathbb{E}_{\bm{X},Y\sim P}\left[\exp\left(-\frac{1}{r}\sum_{j=1}^{r} \omega_{n} \left( \ell(\bm{X},Y,\mu(\cdot,\tau_{j});\tau_{j}) - \ell(\bm{X},Y,\mu_{0}(\cdot,\tau_{j});\tau_{j}) \right)\right)\right]
    \\\leq \,\,& \frac{1}{r}\sum_{j=1}^{r} \mathbb{E}_{\bm{X},Y\sim P}\left[ \exp\left(- \omega_{n} \left( \ell(\bm{X},Y,\mu(\cdot,\tau_{j});\tau_{j}) - \ell(\bm{X},Y,\mu_{0}(\cdot,\tau_{j});\tau_{j}) \right)\right)\right] \\
  \leq \,\,& \exp \left( -K_{n} \omega_{n} \varepsilon_{n}^{2} \right)
  \end{align*}
  which verifies Condition 2 of~\citep{syring20_gibbs_poster_concen_rates_under} with $\omega_{n}=c\log^{-2p}(n)$ for some $0<c<1/2$.

  \paragraph{Prior mass condition.} Now, we verify the prior mass condition in Theorem 4.1 of~\citep{syring20_gibbs_poster_concen_rates_under}.
  As in~\citep{syring20_gibbs_poster_concen_rates_under}, we define $m(\mu,\mu_{0}):=\mathbb{E}_{\bm{X},Y\sim P}\left[\ell^{(r)}(\bm{X},Y,\mu)-\ell^{(r)}(\bm{X},Y,\mu_{0})\right]$ and $v(\mu,\mu_{0}):= \mathbb{E}_{\bm{X},Y\sim P} \left[ \left(\ell^{(r)}(\bm{X},Y,\mu) - \ell^{(r)}(\bm{X},Y,\mu_{0})\right)^{2} \right]-m(\mu,\mu_{0})^{2}$ to denote the mean and variance of the excess loss. Similarly, define the mean and variance of the excess $\tau$-check loss specifically as $m_{\tau}(\mu,\mu_{0}):=\mathbb{E}_{\bm{X},Y\sim P}\left[\ell(\bm{X},Y,\mu(\cdot,\tau);\tau)-\ell(\bm{X},Y,\mu_{0}(\cdot,\tau);\tau)\right]$ and $v_{\tau}(\mu,\mu_{0}):= \mathbb{E}_{\bm{X},Y\sim P} \left[ \left(\ell(\bm{X},Y,\mu(\cdot,\tau);\tau) - \ell(\bm{X},Y,\mu_{0}(\cdot,\tau);\tau)\right)^{2} \right]-m_{\tau}(\mu,\mu_{0})^{2}$.

  We note that
  \begin{align*}
    m(\mu,\mu_{0}) &= \frac{1}{r}\sum_{j=1}^{r}m_{\tau_{j}}(\mu,\mu_{0}) \\ &\lesssim \frac{1}{r}\sum_{j=1}^{r}\left(\frac{1}{\tau_{j}(1-\tau_{j})}\right)\|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot, \tau_{j})\|_{L_{1}} \\
    &\lesssim \left(\frac{1}{r}\sum_{j=1}^{r}\frac{1}{\tau_{j}(1-\tau_{j})}\right) \max_{j\in[r]}\|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot, \tau_{j})\|_{L_{1}}\,.
  \end{align*}
  and similarly
  \begin{align*}
    v(\mu,\mu_{0}) &\leq \frac{1}{r}\sum_{j=1}^{r}\left(v_{\tau_{j}}(\mu,\mu_{0}) + m_{\tau_{j}}(\mu,\mu_{0})^{2}\right) \\ &\lesssim \frac{1}{r}\sum_{j=1}^{r}\left(\left(\frac{1}{\tau_{j}^{2}(1-\tau_{j})^{2}}\right)\left(\|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot, \tau_{j})\|^{2}_{L_{2}} + \|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot,\tau_{j})\|_{L_{1}}^{2}\right)\right)\\
    &\lesssim \left(\frac{1}{r}\sum_{j=1}^{r}\frac{1}{\tau_{j}^{2}(1-\tau_{j})^{2}}\right) \left(\max_{j\in[r]}\|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot, \tau_{j})\|^{2}_{L_{2}} + \max_{j\in[r]}\|\mu(\cdot,\tau_{j})-\mu_{0}(\cdot, \tau_{j})\|^{2}_{L_{1}}\right)\,.
  \end{align*}

  We now proceed as in~\citet{rockova2020posterior}. Lemma~\ref{lem:approximation} guarantees that there exists a tree-supported step-function $\mu_{\widehat{\mathcal{T}},\widehat{\beta}}$ on a partition $\widehat{\mathcal{T}}$ that approximates $\mu_{0}$ with error
  \[
    \|\mu_{0}-\mu\|_{\infty} \leq \|\mu_{0}\|_{\mathcal{H}^{\nu}} C_{1} (d+1) / K^{-\nu/(d+1)}\,.
  \]
  We choose $K=J_{n}$ such that the approximation error is bounded above by $\epsilon_{n}/2$. The reverse triangle ineqality and this choice of $J_{n}$ then yield the conclusion that $\|\beta-\widehat{\beta}\|_{\infty}<\epsilon_{n}/2$ implies that $\|\mu_{0}-\mu_{\widehat{\mathcal{T}},\beta}\|_{\infty}<\epsilon_{n}$.

  We can proceed using the argument in the proof of Proposition 8 of~\citet{syring20_gibbs_poster_concen_rates_under}. Define $J_{n}=n^{-1/(2\nu+d+1)}$. We now consider tree-supported step functions $\mu_{\wh{\mathcal{T}},\beta}$ on a partition $\wh{\mathcal{T}}$ and a coefficient vector $\beta\in \mathbb{R}^{J_{n}}$.
  %We consider the ball $B_{n}:=\{\beta\in\mathbb{R}^{J}:\|\mu_{0}-\mu_{\wh{\mathcal{T}},\beta}\|_{\infty}\leq C J_{n}^{-\nu}\}$ which contains the coefficients of all tree-supported step functions on $\wh{\mathcal{T}}$ with coefficient $\beta$ that are sufficiently close to $\mu_{0}$ in sup-norm.
  The above bounds on $m(\mu,\mu_{0})$ and $v(\mu,\mu_{0})$ allow us to conclude that for any $\mu_{\wh{\mathcal{T}},\beta}$ satisfying $\|\mu_{\wh{\mathcal{T}},\beta}-\mu_{0}\|_{\infty}\leq CJ_{n}^{-\nu}$, we have
  \[
    m(\mu_{\wh{\mathcal{T}},\beta},\mu_{0})\vee v(\mu_{\wh{\mathcal{T}},\beta},\mu_{0}) \lesssim J_{n}^{-2\nu}\,.
  \]
  This implies that
  \begin{align*}
    \Pi\left\{\mu\in \mathcal{F}_{\mathcal{T}} : m(\mu,\mu_{0})\vee v(\mu,\mu_{0}) \leq J_{n}^{-2\nu}\right\} &\geq  \Pi\left\{\mu\in \mathcal{F}({\wh{\mathcal{T}}}) : m(\mu,\mu_{0})\vee v(\mu,\mu_{0}) \lesssim J_{n}^{-2\nu}\right\}\pi(\widehat{\mathcal{T}}) \\                                                  &\geq  \Pi\left\{\mu\in \mathcal{F}({\wh{\mathcal{T}}}) : \|\mu_{0}-\mu\|_{\infty} \lesssim J_{n}^{-\nu}\right\}\pi(\widehat{\mathcal{T}}) \\
     &\geq  \Pi\left\{\widehat{\beta}\in\mathbb{R}^{J_{n}} : \|\beta_{0}-\widehat{\beta}\|_{\infty} \lesssim J_{n}^{-\nu}\right\}\pi(\widehat{\mathcal{T}}) \\
    &\gtrsim \exp(-C_{2}J_{n}\log n)
  \end{align*}
  for some constant $C_{2}>0$, where the last inequality bounds the (log of the) first factor exactly as in the proof of Theorem 1 of~\citet{ shen2015adaptive}. The (log of the) second factor is bounded as in the proof of Theorem 4.1 in~\citet{rockova2020posterior}. This verifies that the step-function prior on the conditional quantile function $\mu$ assigns sufficient mass around the truth.

  Thus, the two sufficient conditions for Theorem 4.1 of~\citet{syring20_gibbs_poster_concen_rates_under} hold, yielding the desired result. Note that the condition on the sequence of prior supports is true by Assumption~\ref{assn:main}, where we restrict the support of the prior to $\mathcal{F}_{n}$, but that this may not be necessary (see \citet{kleijn2006misspecification}).

\end{proof}

\subsection{Proof of Lemma~\ref{lem:flat-pm}}\label{sec:pf-lem-1}

\begin{proof}

Recall that $q^{\mathrm{PM}}_{\tau,\lambda}$ takes the form~\eqref{eq:quantile-post-mean}. The numerator can be evaluated as
\begin{align*}
   &\sum_{k=0}^{n} \int_{Y_{(k)}}^{Y_{(k+1)}} \mu \exp\left(-\lambda^{-1}(\tau-1) \sum_{i=1}^{k}Y_{(i)}-\lambda^{-1}\tau\sum_{i=k+1}^{n}Y_{(i)}\right)\exp\left(-\lambda^{-1}(k-n\tau)\mu\right)\,\mathrm{d}\mu \\ =&
    \sum_{k=0}^{n} \int_{Y_{(k)}}^{Y_{(k+1)}} w_{k}\exp\left(-c_{k}\mu\right)\mu\,\mathrm{d}\mu \\
=& \sum_{k=0}^{n} w_{k} \begin{cases}\frac{1}{c_{k}^{2}}\left[(c_{k}Y_{(k)}+1)\exp(-c_{k}Y_{(k)})-(c_{k}Y_{(k+1)}+1)\exp(-c_{k}Y_{(k+1)})\right] & k/n \neq \tau \\ \frac{1}{2}\left[Y_{(k+1)}^{2}-Y_{(k)}^{2}\right] & k/n = \tau\end{cases}
\end{align*}
where $w_{k}:=\exp\left(-\lambda^{-1}(\tau-1) \sum_{i=1}^{k}Y_{(i)}-\lambda^{-1}\tau\sum_{i=k+1}^{n}Y_{(i)}\right)$ and $c_{k}:= \lambda^{-1}(k-n\tau)$. We also have $Y_{(0)}:=-\infty$ and $Y_{(n+1)}:=\infty$.

The denominator can be evaluated in a similar way
\begin{align*}
   &\sum_{k=0}^{n} \int_{Y_{(k)}}^{Y_{(k+1)}} \exp\left(-\lambda^{-1}(\tau-1) \sum_{i=1}^{k}Y_{(i)}-\lambda^{-1}\tau\sum_{i=k+1}^{n}Y_{(i)}\right)\exp\left(-\lambda^{-1}(k-n\tau)\mu\right)\,\mathrm{d}\mu \\ =&
    \sum_{k=0}^{n} \int_{Y_{(k)}}^{Y_{(k+1)}} w_{k}\exp\left(-c_{k}\mu\right)\,\mathrm{d}\mu \\
=& \sum_{k=0}^{n} w_{k} \begin{cases}\frac{1}{c_{k}}\left[\exp(-c_{k}Y_{(k)})-\exp(-c_{k}(Y_{(k+1)})\right] & k/n \neq \tau \\ \left[Y_{(k+1)}-Y_{(k)}\right] & k/n = \tau\end{cases}
\end{align*}

The form~\eqref{eq:pm-form} allows for numerically stable computation of the estimator in log-space and allows the practitioner to avoid approximate inference via numerical integration or MCMC methods.

\end{proof}

\subsection{Proof of Lemma~\ref{lem:posterior_mean_convergence}}\label{subsec:asymp-pf}

\begin{proof}
We refer to \citet{chernozhukov2003classical} and \citet{ruppert2015statistics} which characterize the asymptotic behavior of Gibbs posteriors and of the sample quantile respectively.
\end{proof}


\subsection{Proof of Lemma~\ref{lem:asymp-lam}}\label{subsec:asymp-pf-lam}

\begin{proof}
  As discussed in Sec. 3.1 of \citet{bissiri2016general}, the limiting behavior as the learning rate grows large and as the learning rate converges to zero for proper priors is well known.

In the case of the improper prior, as $\lambda \to \infty$, the exponent approaches zero, and thus $\lim_{\lambda \to \infty} w_k = 1$ for all $k=0, \ldots, n$. We use the change of variables $\nu=\mu-\bar{Y}$ to write \begin{align}\label{eq:mean-and-remainder}
  \hat{q}^{\mathrm{PM}}_{\tau,\lambda}&=\frac{\int (\nu + \bar{Y})\exp\left(-\lambda^{-1}\sum_{i=1}^{n}(Y_{i}-\bar{Y}-\nu)(\tau-\mathbb{I}\{Y_{i}-\bar{Y}<\nu\})\right)\mathrm{d}\nu}{\int \exp\left(-\lambda^{-1}\sum_{i=1}^{n}(Y_{i}-\bar{Y}-\nu)(\tau-\mathbb{I}\{Y_{i}-\bar{Y}<\nu\})\right)\mathrm{d}\nu} \notag \\
  &=\bar{Y}+ \frac{\int \nu\exp\left(-\lambda^{-1}\sum_{i=1}^{n}(Z_{i}-\nu)(\tau-\mathbb{I}\{Z_{i}<\nu\})\right)\mathrm{d}\nu}{\int \exp\left(-\lambda^{-1}\sum_{i=1}^{n}(Z_{i}-\nu)(\tau-\mathbb{I}\{Z_{i}<\nu\})\right)\mathrm{d}\nu}
\end{align}
where $Z_{i}=Y_{i}-\bar{Y}$ for $i=1,\ldots,n$ are the centered data points. We turn out attention to the second term and expand the numberator as
\begin{align*}
\sum_{k=1}^{n-1} w_{k}\int_{Z_{(k)}}^{Z_{(k+1)}}\nu \exp\left(-c_{k}\nu\right)\,\mathrm{d}\nu &+ w_{0}\int_{-\infty}^{-M}\nu \exp\left(-c_{0}\nu\right)\,\mathrm{d}\nu \\ &+ w_{0}\int_{-M}^{-Z_{1}}\nu \exp\left(-c_{0}\nu\right)\,\mathrm{d}\nu \\ &+ w_{n}\int_{Z_{(n)}}^{M}\nu \exp\left(-c_{n}\nu\right)\,\mathrm{d}\nu \\&+ w_{0}\int_{M}^{\infty}\nu \exp\left(-c_{n}\nu\right)\,\mathrm{d}\nu
\end{align*}
where $M>0$ is a constant such that $M>Z_{(n)}$ and $-M < Z_{(1)}$. The integrands on all interior terms between $-M$ and $M$ converge uniformly on finite intervals, and so the dominated convergence theorem allows the limits to be evaluated inside the integrals, causing the sum of all of these terms to converge to a finite constant. We recall that $w_{k}\to 1$ as $\lambda\to\infty$ for all $k=0,1,\ldots,n$, and so the asymptotic behavior is controlled by the outer terms. These evaluate to
\[
\int_{M}^{\infty}\nu\exp(-c_{n}\nu)\,\mathrm{d}\nu=\frac{\lambda}{n(1-\tau)}M\exp\left(-\frac{n(1-\tau)\,M}{\lambda}\right)+\frac{\lambda^{2}}{n^{2}(1-\tau)^{2}\exp\left(-\frac{n(1-\tau)\,M}{\lambda}\right)}
\]
and
\[
\int_{-\infty}^{-M}\nu\exp(-c_{0}\nu)\,\mathrm{d}\nu=-\frac{\lambda}{n\tau}M\exp\left(-\frac{n\tau M}{\lambda}\right)-\frac{\lambda^{2}}{n^{2}\tau^{2}}\exp\left(-\frac{n\tau M}{\lambda}\right)
\]
As $\lambda\to\infty$, the numerator therefore becomes asymptotically becomes of order $\lambda^{2}$ for $\tau\neq 0.5$, and for $\tau=0.5$ becomes of constant order with respect to $\lambda$. Similar analysis of the denominator shows that it is always of order $\lambda$ for all $\tau\in(0,1)$. This implies that the remainder term in~\eqref{eq:mean-and-remainder} is of order $\lambda$ for $\tau\neq 0.5$ and of order $\lambda^{-1}$ for $\tau=0.5$.

\end{proof}


