We propose an algorithm (Algorithm \ref{alg:main_algorithm_intro}) that randomly outputs a set of generators $F=(f_1,\ldots,f_m)$ of $\langle G \rangle$ for a given set of polynomials $G=(g_1,\ldots,g_n)$.

\begin{algorithm}
    \DontPrintSemicolon
	\SetKwInOut{Input}{input}\SetKwInOut{Output}{output}
     \caption{Algorithm to compute random generators of $\langle G \rangle$ (See Algorithm \ref{alg:main_algorithm} for a detailed version).}
    \label{alg:main_algorithm_intro}
    \Input{$G = (g_1,\ldots, g_n)^{T} \in R^{n \times 1}$, $m \geq n$.}
    \Output{$F = (f_1,\ldots,f_m)^{T} \in R^{m \times 1}$ such that $\langle F \rangle = \langle G \rangle$.}
    \BlankLine
    Pick a finite product $U$ of random elementary matrices; \;
	\Return $F = AG$ where
	\[ A = U\left(\begin{array}{c} E_n \\ \hline O_{(m-n) \times n} \end{array}\right). \] \;
\end{algorithm}

Here we denote by $E_n$ the identity matrix of size $n$, and by $O_{(m-n)\times n}$ the $(m-n) \times n$ zero matrix.
Let us recall
\begin{align*}
    \mathcal{F}& := \{ F \in R^m \mid \text{$\langle G \rangle$ is generated by $F$} \}, \\
    \mathcal{F}_0 &:= \{ F \in \mathcal{F} \mid \text{$F$ is an output of Algorithm \ref{alg:main_algorithm_intro}} \} \\
     &= \left\{ \left. U\left(\begin{array}{c} E_n \\ \hline O_{(m-n) \times n} \end{array}\right)G \right| \begin{aligned}
   \text{$U$ is a finite product of}\\
   \text{elementary matrices}
     \end{aligned}\right\}.
\end{align*}
Our heuristic assumption concerns the irreducibility of an algebraic set.

\begin{heuristic}\label{heu:chi_is_irr_intro}
Let us consider a block representation of $B \in R^{n \times m}$ and $A \in R^{m \times n}$:
\[ B = (B_1 | B_2),\ A = \left(\begin{array}{c} A_1 \\ \hline A_2 \end{array} \right),\]
where $B_1, A_1 \in R^{n \times n}$, $B_2 \in R^{n \times (m-n)}$ and $A_2 \in R^{(m-n) \times n}$. For given $D \geq 0$ and $G = (g_1,\ldots, g_n)$, the algebraic set
\[ \mathcal{X_{\leq D}} = \left\{ (B,A) \in R_{\leq D}^{n \times m} \times R_{\leq D}^{m \times n} \left| \begin{aligned} &(BA - E_n)G = O_{n \times 1},\\ &B_1 A_1 \in R_{\leq D}^{n \times n} \end{aligned} \right. \right\} \]
in the affine space $R_{\leq D}^{n \times m} \times R_{\leq D}^{m \times n}$ is irreducible.
\end{heuristic}

Here, our main theorem asserts the density in $\mathcal{F}$ of 
\[ \tilde{\mathcal{F}}_{\leq D} := \{ F \in R^{m \times 1} \mid \langle F \rangle = \langle G \rangle,\ \exists\, (B,A) \in \mathcal{X}_{\leq D},\ F = AG \}. \]


\begin{theorem}[{Corollary \ref{cor:m2n}}]
\label{thm:main}
Using the same notation as Problem \ref{prob:taking_generators}, assume that the base field $K$ is a Hilbertian field and $m \geq 2n \geq 3$. 
Then, under Heuristic \ref{heu:chi_is_irr_intro} for $D$ and $G$, the set $\mathcal{F}_0 \cap \tilde{\mathcal{F}}_{\leq D}$ is dense for the relative Zariski topology of $\tilde{\mathcal{F}}_{\leq D}.$
\end{theorem}

Here we say a field $K$ is a \textit{Hilbertian field} if Hilbert's irreducibility theorem (Theorem \ref{thm.Hilbert's irreducibility theorem}, \cite[Theorem 14.4.2]{FieldArithmetic2023}) holds for $K$. For example, number fields are Hilbertian.

% \textcolor{red}{Note that we do not have any guarantee of Heuristic \ref{heu:chi_is_irr_intro} yet. However,
% \textcolor{green}{Since a generic algebraic set in an affine space is irreducible, one may hope that Hueristic \ref{heu:chi_is_irr_intro} is true for enough huge integers $D$ and generic \gr\ basis $G$.}
% \Yota{Make remark later and refer it?}
% It would be sufficient for the purpose of machine learning that find the statistical patterns on generic polynomials and generic \gr\ basis.
%\Yota{I will reconsider this paragraph.}

\begin{corollary}
Assume that the same hypothesis in Theorem \ref{thm:main} holds. If Heuristic \ref{heu:chi_is_irr_intro} is true for sufficiently large integers $D \geq 0$ and a given $G$, then $\mathcal{F}_0$ is Zariski dense in $\mathcal{F}$.    
\end{corollary}

\begin{proof}
By Prop. \ref{prop:gene_iff} and the definition of $\mathcal{X}_{\leq D}$,  there exists an ascending chain of subsets
\[ \tilde{\mathcal{F}}_{\leq D} \subset \tilde{\mathcal{F}}_{\leq (D+1)} \subset \cdots \subset \mathcal{F} = \bigcup_{D' \geq D} \tilde{\mathcal{F}}_{\leq D'}. \]
Let $V$ be the Zariski closure of $\mathcal{F}_0$ in $\mathcal{F}$. It follows that $V \cap \tilde{\mathcal{F}}_{\leq D} = \tilde{\mathcal{F}}_{\leq D}$ for all sufficiently large $D \geq 0$ from the hypothesis and Theorem \ref{thm:main}. Therefore, we have
\[ V =V \cap \mathcal{F} =  V \cap \bigcup_{D' \geq D} \tilde{\mathcal{F}}_{\leq D'} =  \bigcup_{D' \geq D} V \cap \tilde{\mathcal{F}}_{\leq D'} =  \bigcup_{D' \geq D} \tilde{\mathcal{F}}_{\leq D'} = \mathcal{F}. \]
\end{proof}



