\section{Density of the outputs}\label{sec:Density}

The goal of this section is to show that 
\[ \mathcal{F}_0 = \left\{ \left. U \left(\begin{array}{c} E_n \\ \hline O_{(m-n) \times n} \end{array}\right)G \right| U \in \mathbb{E}(m) \right\} \]
is dense in
\[ \mathcal{F} =\{ F \in R^m \mid \langle F \rangle = \langle G \rangle \}.\]


\subsection{Algebraic aspects of \texorpdfstring{$\mathcal{F}$}{F} and  \texorpdfstring{$\mathcal{F}_0$}{F0}}

First, we show Proposition \ref{prop:set_of_outputs}, asserting that $\mathcal{F}_0$ is the same as the set of generators $F = AG$ whose $A$ is a left regular matrix over $R$.

\begin{theorem}[Quillen-Suslin theorem, also known as Serre's conjecture]\label{thm:Serre_conj}
A finitely generated projective $R$-module is free.
\end{theorem}
\begin{proof}
    See \cite[XXI Theo. 3.7]{Lang:Algebra}
\end{proof}

\begin{proposition}\label{prop:set_of_outputs}
For any left regular matrix $A \in R^{m \times n}$ with $m \geq n \geq 3$, there exists an element $U \in \mathbb{E}(m)$ such that
\[ A = U \left(\begin{array}{c} E_n \\ \hline O_{(m-n) \times n} \end{array}\right). \]
\end{proposition}

\begin{proof}
Let $B \in R^{n \times m}$ be a matrix such that $BA = E_n$. Let $\varphi_A : R^n \rightarrow R^m$ and $\varphi_B : R^m \rightarrow R^n$ be the $R$-module morphisms defined by  $\varphi_A(C) = AC$ and $\varphi_B(C) = BC.$ The assumption on $B$ implies that the sequence
\begin{equation}\label{eq:sequence}
    0 \rightarrow \mathrm{Ker}(\varphi_B) \rightarrow R^m \overset{\varphi_B}{\rightarrow} R^n \rightarrow 0
\end{equation}
is a split exact sequence. The kernel $\mathrm{Ker}(\varphi_B)$ is projective. Indeed, this is a direct summand of the free module $R^m$. Then, by Theorem \ref{thm:Serre_conj}, $\mathrm{Ker}(\mathrm{\varphi_B})$ is free. Moreover, since $R^n$ is projective over $R$, we have
\[ \mathrm{Ext}^1_R(R^n, \mathrm{Ker}(\varphi_B))=0.\]
It follows that $\mathrm{Ker}(\varphi_B)$ is isomorphic to the free module $R^{(m-n)}$ and the sequence \eqref{eq:sequence} corresponds to the zero of the module $\mathrm{Ext}^1_R(R^n, R^{(m-n)})$, which forces that 
\[ 0 \rightarrow R^{(m-n)} \rightarrow R^n \stackrel{\pr_n}{\to} R^m \rightarrow 0, \]
where $\pr_n$ is the projection to the first $n$ coordinates. Hence there exist isomorphisms $\rho : R^m \rightarrow R^m$ and $\tau : R^n \rightarrow R^n$ of $R$-modules making the diagram
\[
\xymatrix{
R^m \ar[r]^{\varphi_B} \ar[d]_{\rho} & R^n \ar[d]_{\tau} \\
R^m \ar[r]^{\pr_n} & R^n
}
\]
commutative. Let $U$, $V$, $U'$, $V'$ be matrices that represent $\rho$, $\tau$, $\rho^{-1}$, $\tau^{-1}$ respectively. These are matrices with entries in $R$ since $\rho^{-1}$ and $\tau^{-1}$ are still $R$-module morphisms. Then we have $\det(U), \det(V) \in R^{\times} = K \setminus \{0\}$ from Proposition \ref{prop:regular_det}. Therefore we obtain
\[ B = V^{-1} (E_n|O_{n \times (m-n)}) U\quad (V \in \mathbb{E}(n),\ U \in \mathbb{E}(m)) \]
from Theorem \ref{thm:Suslin's_stability_theorem}. Taking a block matrix representation
\[ UA = \left(\begin{array}{c} A_1 \\ \hline A_2 \end{array} \right) \]
for $A_1 \in R^{n \times n}$ and $A_2 \in R^{(m-n) \times n}$, we have
\[ E_n = BA = BU^{-1} UA = V^{-1}A_1. \]
It implies that
\[ A = U^{-1} \left( \begin{array}{c} V \\ \hline A_2 \end{array} \right) = U^{-1} \left( \begin{array}{c|c} V & O_{n \times (m-n)} \\ \hline A_2 & E_{(m-n)\times (m-n)}\end{array} \right)\left( \begin{array}{c} E_n \\ \hline O_{(m-n) \times n } \end{array} \right).\]
By the row reduction, we can show that the matrix 
\[U^{-1} \left( \begin{array}{c|c} V & O_{n \times (m-n)} \\ \hline A_2 & E_{(m-n)\times (m-n)}\end{array} \right)\]
is an element in $\mathbb{E}(m)$.
\end{proof}

