Next, we analyze $\mathcal{F} = \{ F \in R^{m \times 1}\mid \langle F \rangle = \langle G \rangle \}$.

\begin{proposition}\label{prop:gene_iff}
Let $F = AG$ for $A \in R^{m \times n}$. The tuple of polynomials $F$ is a generator of $\langle G \rangle$ if and only if there exists a matrix $B \in R^{n \times m}$ such that $(BA-E_n)G = O_{n \times 1}$.
\end{proposition}

\begin{proof}
 The polynomials $F=AG$ is a set of generators of $\langle G\rangle$ if and only if 
 %\sout{\textcolor{red}{$A$ is left regular.}} \textcolor{red}{(It is not True. Indeed, if $F = AG$ are generators, then for any element $W \in \Syz(G)^m$, $F = (A+W)G$ are also generators and $(A+W)$ is not regular in general.)} 
 there exists a matrix $B \in R^{n \times m}$ such that $G = BF= BAG$. The latter is rephrased as  $(BA-E_n)G = O_{n \times 1}$.
\end{proof}

\begin{definition}
    We call a polynomial row vector $H = (h_1,\ldots,h_n) \in R^{1 \times n}$ a \textit{syzygy} of $G$ if $HG = h_1g_1 + \cdots + h_n g_n = 0$. The set of all syzygies of $G$ is denoted by $\Syz(G) \subset R^{1 \times n}$. We also denote by $\Syz(G)^m \subset R^{m \times n}$ the set consisting of matrices that all rows are a syzygy of $G$.
\end{definition}
 Namely,
\[ \Syz(G)^m = \{ C \in R^{m \times n} \mid CG = O_{n \times 1} \}. \]
Using Proposition \ref{prop:gene_iff} and the syzygies of $G$, we will find enough condition for $F \in \mathcal{F}$ to be in $F \in \mathcal{F}_0$.

\begin{proposition}\label{prop:irreducible_determinant}
Assume that $m \geq n \geq 3$. Let us denote by 
\[ B = (B_1 | B_2), A = \left(\begin{array}{c} A_1 \\ \hline A_2 \end{array} \right)\quad (B_1, A_1 \in R^{n \times n}, B_2 \in R^{n \times (m-n)}, A_2 \in R^{(m-n) \times n}) \]
a block representations of $B \in R^{n \times m}$ and $A \in R^{m \times n}$. Let $F = AG \in \mathcal{F}$ be a set of generators of $\langle G \rangle$ and $B$ a matrix such that $W := BA - E_n \in \Syz(G)^n$. If the determinant of $E_n + W - B_2A_2$ is a non-zero irreducible polynomial in $R$, then $F \in \mathcal{F}_0$.
\end{proposition}

\begin{proof}
We note that
\[ E_n + W -B_2 A_2 = B_1A_1. \]
The assumption on the determinant of $E_n + W - B_2A_2$ implies that  $\det B_1 \in K \setminus \{0\}$ or $\det A_1 \in K \setminus \{0\}.$

First suppose that $\det B_1 \in K \setminus \{0\}$. In this case, we have
\[ A_1 = B_1^{-1}(E_n + W - B_2A_2).\]
Let us consider a matrix
\[ A' := \left( \begin{array}{c} B_1^{-1}(E_n - B_2 A_2) \\ \hline A_2 \end{array} \right) \in R^{m \times n}. \]
Then we have
\[ BA' = B_1 (B_1^{-1}(E_n - B_2A_2)) + B_2 A_2 = E_n\]
and
\[ AG = \left( \begin{array}{c} B_1^{-1}(E_n+W-B_2 A_2)G \\ \hline A_2G \end{array} \right) = \left( \begin{array}{c} B_1^{-1}(E_n - B_2 A_2)G \\ \hline A_2G \end{array} \right) = A'G\]
since $W \in \Syz(G)^n$. Hence the set of generators $F = AG = A'G$ is an element of $\mathcal{F}_0$ by Proposition \ref{prop:set_of_outputs}.

For the case of $\det A_1 \in K \setminus \{0\}$. putting 
\[ B' := (A_1^{-1} \mid O_{n\times (m-n)}) \in R^{n \times m}, \]
 we have
\[ B' A = (A_1^{-1} \mid O_{n\times (m-n)} )\left(\begin{array}{c} A_1 \\ \hline A_2 \end{array} \right) =  E_n. \]
Proposition \ref{prop:set_of_outputs} again concludes the claim.
\end{proof}

\subsection{Geometric aspects of \texorpdfstring{$\mathcal{F}$}{F} and \texorpdfstring{$\mathcal{F}_0$}{F0}}

Let us denote by
\[ \mathcal{X} := \{ (B,A) \mid B \in R^{n \times m}, A \in R^{m \times n}, (BA-E_n)G = O_{n \times 1} \} \]
an algebraic set in the affine space $R^{n\times m} \times R^{m \times n}$. Proposition \ref{prop:gene_iff} claims that there exists a surjective continuous map
\[ \varphi : \mathcal{X} \rightarrow \mathcal{F} \]
\[ (B,A) \mapsto AG. \]

The goal of this subsection is to find a dense subset $\mathcal{X}_0$ of $\mathcal{X}$ such that $\varphi(\mathcal{X}_0) \subset \mathcal{F}_0.$ 
The existence of such a subset implies that $\mathcal{F}_0$ is dense in $\mathcal{F}$ from the following basic topological fact that the image of a dense subset of a topological space is also dense under a continuous subjective map.

