Let us consider a block representation of $B \in R^{n \times m}$ and $A \in R^{m \times n}$:
\[ B = (B_1 | B_2),\ A = \left(\begin{array}{c} A_1 \\ \hline A_2 \end{array} \right),\]
where $B_1, A_1 \in R^{n \times n}$, $B_2 \in R^{n \times (m-n)}$ and $A_2 \in R^{(m-n) \times n}$. 
According to these, we shall define
\[ p: \mathcal{X} \rightarrow R^{n \times n} \]
\[ (B,A) \mapsto B_1 A_1\]
and
\[ \delta : R^{n \times n} \rightarrow R\]
\[ C \mapsto \det(C). \]

The following proposition is another version of Proposition \ref{prop:irreducible_determinant} in the geometrical context.
Put
\[ \mathcal{U} := \{ f \in R \setminus \{0\} \mid \text{$f$ is irreducible} \}.\]

\begin{proposition}\label{prop:enough_condition_of_output}
Assume that $m \geq n \geq 3$. 
Then the following inclusion of subsets in $\mathcal{X}$ is true:
\[ (\delta \circ p)^{-1}(\mathcal{U}) \subset \varphi^{-1}(\mathcal{F}_0). \]
\end{proposition}

\begin{proof}
Pick an element $(B,A) \in (\delta \circ p)^{-1}(\mathcal{U}) \subset \mathcal{X}$. The image is
\[ (\delta \circ p)(B,A) = \det(B_1A_1).\]
Then similar to the proof of Proposition \ref{prop:irreducible_determinant}, $(\delta \circ p)(B,A) \in \mathcal{U}$ implies that $AG = \varphi(B,A) \in \mathcal{F}_0$.
\end{proof}

From a well-known fact, which is so-called Hilbert's irreducibility theorem, the inverse image
\[ \delta^{-1}(\mathcal{U}) \cap R_{\leq D}^{n \times n} = \{ C \in R_{\leq D}^{n \times n} \mid \text{$\det (C)$ is non-zero irreducible} \} \]
is Zariski dense in $R_{\leq D}^{n \times n} = (\mathbb{A}_K^{N_D})^{n \times n}$ over $K$.
%\YotaToDo{Hilbert's irreducibility theorem vs the Hilbert irreducibility theorem}

\begin{theorem}[Hilbert's irreducibility theorem]\label{thm.Hilbert's irreducibility theorem}
Let $f(X_1,\ldots,X_r,Y_1,\ldots,Y_s)$ be an irreducible element in $\mathbb{Q}(X_1,\ldots,X_r)[Y_1,\ldots,Y_s]$. Then the set
\[ \{ (a_1,\ldots,a_r) \in \mathbb{Q}^r \mid f(a_1,\ldots,a_r)(Y_1,\ldots,Y_s)\ \text{is irreducible} \}\]
is Zariski dense in $\mathbb{A}^r_{\mathbb{Q}}$.
\end{theorem}
\begin{proof}
    See \cite[Theorem 14.4.2]{FieldArithmetic2023}.
\end{proof}

As written in section \ref{sec:introduction}, we say a field $K$ is Hilbertian if Hilbert's irreducibility theorem holds when replacing $\mathbb{Q}$ to $K$. 
To apply Hilbert's irreducibility theorem to our situation, let us prove the following lemma on the irreducibility of the determinant of a generic polynomial matrix.

\begin{lemma}\label{lem:irreducibility_of_determinant}
The polynomial
\[ \mathrm{DET}(\{c_{\alpha,i,j}\},\{x_k\}) \in K[c_{\alpha,i,j} \mid x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n][x_1,\ldots,x_n]\]
corresponding to the map
\begin{align*}
    \delta: R_{\leq D}^{n \times n} &\rightarrow R \\
    C = \left(\sum_{|\alpha|\leq D} c_{\alpha,i,j}x^{\alpha} \right) &\mapsto \det C = \mathrm{DET}(\{c_{\alpha,i,j}\},\{x_k\})
\end{align*}
is irreducible in $K(c_{\alpha,i,j} \mid x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)[x_1,\ldots,x_n]$.
\end{lemma}
\begin{proof}
    Let 
    \[\Gamma := \mathrm{DET}(\{c_{\alpha,i,j}\},\{x_k\}) \in K[c_{\alpha,i,j} \mid x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n][x_1,\ldots,x_n].\]
    We first prove that $\Gamma$ is irreducible in \[K(x_1,\ldots,x_n)[c_{\alpha,i,j}\  (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)].\]

    %Let $\gamma = \Gamma_{ \mid c_{\alpha,i,j}=0 \text{ for } \vert \alpha \vert \geq 1, \: x_1=\dots=x_n=0}.$
    %Then \[\gamma = \det \left( \begin{bmatrix} c_{0,1,1} & \dots & c_{0,1,n} \\
    %\vdots & & \vdots \\
    %c_{0,n,1} & \dots & c_{0,n,n}\end{bmatrix} \right) \in K[ \left\lbrace c_{0,i,j}, \:  1 \leq i,j \leq n \right\rbrace ]. \]
    %The polynomial $\gamma$ is well-known to be irreducible in $K[ \left\lbrace c_{0,i,j}, \:  1 \leq i,j \leq n \right\rbrace ]$
    %(see \textit{e.g.} \cite[p.176]{Bocher:HigherAlgebra}).
    %Consequently, $\Gamma$ is irreducible in $K[c_{\alpha,i,j}  (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n),x_1,\ldots,x_n]$.
    %\Tristan{I need an additional argument here. Actually I have a better idea that I should develop tomorrow, hopefully.}

%    In addition, as a polynomial in $K[c_{\alpha,i,j}  (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)][x_1,\ldots,x_n],$
%    the content of $\Gamma$ is one.
%    Indeed, its coefficient of degree $0$  and its
%    coefficient in $x_1^{nD}$ have no variable in common.

The proof can be understood as an extension of the classical proof of irreducibility
of the determinant of a matrix of generic entries, see \textit{e.g.} \cite[p.176]{Bocher:HigherAlgebra}.

We recall
Leibniz's formula for determinants:
\begin{equation}
    \Gamma = \sum_{\sigma \in \mathfrak{S}_n} \textrm{sign}(\sigma) \prod_{l=1}^n \left(\sum_{|\alpha|\leq D} c_{\alpha,l,\sigma(l)}x^{\alpha} \right). \label{eqn:Leibniz_formula}
\end{equation} 
Suppose $\Gamma = fg$ for some polynomials
\[f,g \in K[c_{\alpha,i,j} \: (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n), \: x_1,\ldots,x_n].\]
By \eqref{eqn:Leibniz_formula}, $\Gamma$ has degree at
most 1 with respect to any of the $c_{\alpha,i,j}.$
For any $\alpha,i,j$, adequate substitutions of $0$'s or $1$'s
prove that $\Gamma$ can be evaluated to 
\[\det \left( 
\begin{bmatrix} 1 & 0      &  &   & & \cdots & & & & & 0\\
                0 & \ddots &        &   & & & & & & & \\
                 &    & 1 & & & & & 0& & & \\
                        &   &   &0 & & & 0& 1&0 & & \\
                        &   &   &  & 1 & & &0 & & & \\
                \vdots        &   &   &   &   & \ddots & & & & & \vdots \\
                        &   &   & 0  &   &       & 1 & & & & \\
                        &   & 0  &c_{\alpha,i,j}   & 0  &       &  & 0 & & & \\
                        &   &   & 0  &   &       &  &  & 1& & \\
                        &   &   &   &   &       &  &  & & \ddots &0 \\
               0         &   &   &   &   &   \cdots    &  &  & & 0 & 1 \\ 
                        \end{bmatrix} \right) = \pm c_{\alpha,i,j}.\]
Consequently, all the variables $c_{\alpha,i,j}$ must appear in $\Gamma$.

Suppose that for some $\alpha$, $c_{\alpha,1,1}$
appears in $f.$
By consideration of degrees in $c_{\alpha,1,1}$, it then can not appear in $g.$
Leibniz's formula \eqref{eqn:Leibniz_formula} proves that there is no term where
$c_{\alpha,1,1}c_{\alpha,1,j}$ can appear in $\Gamma$ with $j \neq 1.$
It follows from the equality 
\[(u_1c_{\alpha,1,1}+u_2)(u_3c_{\alpha,1,j}+u_3)=u_1u_2c_{\alpha,1,1}c_{\alpha,1,j}+u_1u_3c_{\alpha,1,1}+u_2u_3c_{\alpha,1,j}+u_2u_3,\]
 that $c_{\alpha,1,j}$ can not appear in $g$
and must appear in $f$.
Similarly, all the $c_{\alpha,i,1}$ must appear in $f$ and not in $g$.
With the same argument applied for $c_{\alpha,i,1}$,  we can prove that all $c_{\alpha,i,j}$'s must appear in $f$ and not in $g$.

If we take some $\beta \neq \alpha$ with $\vert \beta \vert \leq D,$
\eqref{eqn:Leibniz_formula} proves that there is no term in 
$c_{\alpha,1,1} c_{\beta,1,1}$ in $\Gamma.$
Thus, $c_{\beta,1,1}$ must appear in $f$ and not in $g$.
Using the previous argument, we gets that all the
$c_{\beta,i,j}$ must appear in $f$ and not in $g.$
Therefore, $g$ can not contain any $c_{\alpha,i,j}$
for $\vert \alpha \vert \leq D, 1\leq i,j \leq n.$
Thus, $g$ can only be a pure polynomial in $K[x_1,\dots,x_n]$
and $\Gamma$ is then irreducible in 
$K(x_1,\ldots,x_n)[c_{\alpha,i,j} \: (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)]$.

As a polynomial in $K[x_1,\ldots,x_n][c_{\alpha,i,j} \: (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)]$, its content
has to be $1.$ Indeed, from \eqref{eqn:Leibniz_formula}, the coefficient of the monomial 
$c_{0,1,1}\cdots c_{0,n,n}$ in $\Gamma$ is $1$. 
By Gauss's lemma, it implies that $\Gamma$ is irreducible in
$K[x_1,\ldots,x_n][c_{\alpha,i,j} \: (x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)]$, and then, again by Gauss's lemma, $\Gamma$ is irreducible in 
    $K(c_{\alpha,i,j} \mid x^{\alpha} \in R_{\leq D}, 1 \leq i,j \leq n)[x_1,\ldots,x_n]$.    
\end{proof}


