\begin{lemma}\label{lem:U_is_dense}
%Assume Heuristic \ref{heu:irreducibility_of_determinant}. 
The set $\delta^{-1}(\mathcal{U}) \cap R_{\leq D}^{n \times n}$ is Zariski dense in the affine space $R_{\leq D}^{n \times n}$.
\end{lemma}

\begin{proof}
From Hilbert's irreducibility theorem (Theorem \ref{thm.Hilbert's irreducibility theorem}), the set
\[ \{ (c_{\alpha,i,j}) \in (K^{N_D})^{n \times n} \mid \text{$\mathrm{DET}(\{c_{\alpha,i,j}\},\{x_k\})$ is non-zero irreducible} \}, \]
which is equal to $\delta^{-1}(\mathcal{U}) \cap R_{\leq D}^{n \times n}$,
is Zariski dense in the affine space $R_{\leq D}^{n \times n}$.
\end{proof}

Let us summarize our situation in the following commutative diagram:

\[ \xymatrix{
\tilde{\mathcal{F}}_{\leq D}  & \mathcal{X}_{\leq D} \ar[l]_{\varphi} \ar[r]^{p} & R_{\leq D}^{n \times n} \\
\mathcal{F}_0 \cap \tilde{\mathcal{F}}_{\leq D} \ar@{^{(}-_>}[u]& (\delta \circ p)^{-1}(\mathcal{U}) \cap \mathcal{X}_{\leq D} \ar[l] \ar@{^{(}-_>}[u] \ar[r] & \delta^{-1}(\mathcal{U}) \cap R_{\leq D}^{n \times n}. \ar@{^{(}-_>}[u]_{\text{dense}}
}
\]
Here we denote by
\begin{align*}
    \mathcal{X_{\leq D}} &:= \left\{ (B,A) \in R_{\leq D}^{n \times m} \times R_{\leq D}^{m \times n} \left| \begin{aligned} &(BA - E_n)G = O_{n \times 1},\\ &B_1A_1 \in R_{\leq D}^{n \times n} \end{aligned} \right. \right\},\\
\tilde{\mathcal{F}}_{\leq D} &:= \{ F \in R^{m \times 1} \mid \langle F \rangle = \langle G \rangle,\ \exists\, (B,A) \in \mathcal{X}_{\leq D}^{m \times n}\ F = AG \}.    
\end{align*}


Thus, if the set $(\delta \circ p)^{-1}(\mathcal{U}) \cap \mathcal{X}_{\leq D}$ is dense in $\mathcal{X}_{\leq D}$, then the set $\mathcal{F}_0 \cap \tilde{\mathcal{F}}_{\leq D}$ is dense in $\tilde{\mathcal{F}}_{\leq D}$. We use the following lemma that states that the preimage of a dense subset under a flat morphism is still dense.

\begin{lemma}\label{lem:density_of_preimage}
Let $f:Y \rightarrow Z$ be a flat morphism of finite type between Noetherian schemes. Let $\mathcal{V}$ be a dense subset in $Z$. Then the preimage $f^{-1}(\mathcal{V})$ is dense in $Y$.
\end{lemma}

\begin{proof}
It is enough to show that for any non-empty open subset $U$ in $Y$, the intersection $U \cap f^{-1}(\mathcal{V})$ is not empty. In fact, a flat morphism of finite type between Noetherian schemes is open \cite[Exercise III.9.1]{Har77}. Since $f$ is open, the image $f(U)$ is a non-empty open subset in $Z$ for any non-empty open subset $U$ in $Y$. Then we have $f(U) \cap \mathcal{V} \neq \emptyset$, which forces $U \cap f^{-1}(\mathcal{V})\neq \emptyset$.
\end{proof}

