\section{Limit of polynomial rings}
\label{sec:app}

Let $\Lambda$ be a set. Let
\[ \mathbb{E}(\Lambda) = \mathop{\bigoplus}_{\lambda \in \Lambda} \mathbb{Z}_{\geq 0} = \{ \varepsilon = (e_{\lambda}) \mid e_{\lambda} = 0\ \text{for all but finitely many $\lambda \in \Lambda$}\}.\]
We denote the polynomial ring in symbolic variables $\{x_{\lambda}\mid \lambda \in \Lambda\}$ corresponding to elements in $\Lambda$ by
\[ K[\Lambda] = \left\{ \left. \mathop{\sum}_{\varepsilon \in\mathbb{E}(\Lambda)} c_{\varepsilon} x^{\varepsilon} \right| \begin{aligned} &c_{\varepsilon} \in K \ \text{for all $\varepsilon \in\mathbb{E}(\Lambda)$,}\\ & c_{\varepsilon} = 0\ \text{for all but finitely many $\varepsilon \in \mathbb{E}(\Lambda)$} \end{aligned} \right\}. \]
Also, we denote the formal power series ring in symbolic variables $\{x_{\lambda} \mid \lambda \in \Lambda\}$ corresponding to an element in $\Lambda$ by
\[ K[[\Lambda]] = \left\{ \left. \mathop{\sum}_{\varepsilon \in\mathbb{E}(\Lambda)} c_{\varepsilon} x^{\varepsilon} \right| c_{\varepsilon} \in K \ \text{for all $\varepsilon \in\mathbb{E}(\Lambda)$} \right\}. \]
For any two finite subsets $A,B \subset \Lambda$ such that $A \supset B$, we have a canonical $K$-algebra morphism
\[ f_{A \supset B} : K[A] \rightarrow K[B] \]
such that $f_{A \supset B}(x_{\lambda}) = x_{\lambda}$ if $\lambda \in A \setminus B$ and $f_{A \supset B}(x_{\lambda}) = 0$ otherwise. Then, for any set $\mathcal{P}$ of finite subsets in $\Lambda$, we can consider the limit
\[  \lim_{\substack{\to \\ A\in \mathcal{P}}} K[A] \]
of the system $(\{K[A]\mid A \in \mathcal{P} \},\{f_{A\supset B} \mid A,B \in \mathcal{P}, A \supset B\})$ in the category of $K$-algebras (See \cite{mac2013categories} for the elements of limits in categories.). 

\begin{proposition}\label{prop:limit_of_polynomial_rings}
For any set $\mathcal{P}$ of finite subsets in a set $\Lambda$, the limit $\displaystyle \lim_{\substack{\to \\ A\in\mathcal{P}}} K[A]$ exists in the category of $K$-algebras.
\end{proposition}

\begin{proof}
For any $A \in \mathcal{P}$, let
\[ \pi_A : K[[\Lambda]] \rightarrow K[[\Lambda]] \]
be a $K$-algebra morphism such that $\pi_A(x_{\lambda})= x_{\lambda}$ if $\lambda \in A$ and $\pi_A(x_{\lambda}) = 0$ otherwise. Namely, this morphism $\pi_A$ kills terms including variables not corresponding to elements in $A$. In particular, we have $\pi_A(K[[\Lambda]]) = K[[A]]$. Note that the polynomial ring $K[A]$ is a subring of $K[[A]]$. Let $R$ be the subring of $K[[\Lambda]]$ defined by
\[ R = \mathop{\bigcap}_{A \in \mathcal{P}} \pi_A^{-1}(K[A]).\]
We show that the ring $R$ and the morphisms $ \{(\pi_A)_{\mid R} : R \rightarrow K[A]\}_{A \in \mathcal{P}}$ is the limit of the system $(\{K[A]\mid A \in \mathcal{P} \},\{f_{A\supset B} \mid A,B \in \mathcal{P}, A \supset B\})$. Clearly, we have $f_{A \supset B} \circ (\pi_{A})_{\mid R} = (\pi_{B})_{\mid R}$ for any two finite subsets $A,B \in \mathcal{P}$ such that $A \supset B$. Let $S$ be an arbitrary $K$-algebra and $\{\rho_A : S \rightarrow K[A]\}_{A \in \mathcal{P}}$ be arbitrary $K$-algebra morphisms such that $f_{A \supset B} \circ \rho_{A} = \rho_{B}$ for any two finite subsets $A,B \in \mathcal{P}$. It is enough to show that there exists a unique $K$-algebra morphism $\varphi : S \rightarrow R$ such that $\pi_A \circ \varphi = \rho_A$ for any $A \in \mathcal{P}$. To construct a $K$-algebra morphism $\varphi$, let us assume that
\[ \rho_A(s) = \mathop{\sum}_{\varepsilon \in \mathbb{E}(A)} d_{\varepsilon}(A,s) x^{\varepsilon} \in K[A]\]
for any $A \in \mathcal{P}$ and $s \in S$. Then we define an element $\varphi(s) \in K[[\Lambda]]$ as 
\[ \varphi(s) = \mathop{\sum}_{\varepsilon \in \mathbb{E}(\Lambda)} d_{\varepsilon}(\supp(\varepsilon),s) x^{\varepsilon} \in K[[\Lambda]],\]
where $\supp(\varepsilon) = \{ \lambda \in \Lambda \mid e_{\lambda} \neq 0\}$. First we show that $\pi_A \circ \varphi = \rho_A$ for any $A \in \mathcal{P}$. For any $\varepsilon \in \mathbb{E}(A)$ and $s \in S$, from the commutativity $f_{A \supset \supp(\varepsilon)} \circ \rho_{A} = \rho_{\supp(\varepsilon)}$, the coefficient of $\rho_{\supp(\varepsilon)}(s)$ at $\varepsilon$, which is $d_{\varepsilon}(\supp(\varepsilon),s)$, is just the coefficient of $\rho_{A}(s)$ at $\varepsilon$, which is $d_{\varepsilon}(A,s)$. Therefore we have $d_{\varepsilon}(\supp(\varepsilon),s) = d_{\varepsilon}(A,s)$. Then for any $\varepsilon \in \mathbb{E}(A)$, the coefficient of $\varphi(s)$ and the coefficient of $\rho_A(s)$ are the same at $\varepsilon$. Since $\pi_A$ kills terms including variables not corresponding to elements in $A$, this implies that $\pi_A \circ \varphi = \rho_A$. In particular, for any $A \in \mathcal{P}$, we have
\[ \pi_A(\varphi(S)) \subset \rho_A(S) \subset K[A],\]
and then the image of $\varphi$ is in $R = \bigcap_{A \in \mathcal{P}} \pi_A^{-1}(K[A])$. Next we show that $\varphi$ is a $K$-algebra mophism. It is clear that $\varphi(0) = 0$, $\varphi(1) = 1$, and $\varphi(s+t) = \varphi(s)+\varphi(t)$ for any $s,t \in S$. For any $s,t \in S$, and $\varepsilon \in \mathbb{E}(\Lambda)$, the coefficient of $\varphi(st)$ at $\varepsilon$ is $d_{\varepsilon}(\supp(\varepsilon),st)$, which is the coefficients of $\rho_{\supp(\varepsilon)}(st) =\rho_{\supp(\varepsilon)}(s)\rho_{\supp(\varepsilon)}(t)$ at $\varepsilon$. Putting $B = \supp(\varepsilon)$, let us compute the multiplication $\rho_{B}(s)\rho_{B}(t)$:
\[ \begin{aligned} \rho_{B}(s)\rho_{B}(t) &= \left(\mathop{\sum}_{\alpha \in \mathbb{E}(B)} d_{\alpha}(B,s) x^{\alpha}\right) \left( \mathop{\sum}_{\beta \in \mathbb{E}(B)} d_{\beta}(B,s) x^{\beta} \right)\\
&= \mathop{\sum}_{\gamma \in \mathbb{E}(B)} \left(\mathop{\sum_{\alpha+\beta = \gamma}}_{\alpha,\beta \in \mathbb{E}(B)} d_{\alpha}(B,s)d_{\beta}(B,t) \right) x^{\gamma}
\end{aligned}
\]
Then we have
\[d_{\varepsilon}(\supp(\varepsilon),st) = \mathop{\sum_{\alpha+\beta = \varepsilon}}_{\alpha,\beta \in \mathbb{E}(\supp(\varepsilon))} d_{\alpha}(\supp(\varepsilon),s)d_{\beta}(\supp(\varepsilon),t). \]
On the other hand, let us compute the multiplication $\varphi(s)\varphi(t)$:
\[ \begin{aligned} \varphi(s)\varphi(t) &= \left(\mathop{\sum}_{\alpha \in \mathbb{E}(\Lambda)} d_{\alpha}(\supp(\alpha),s) x^{\alpha}\right) \left( \mathop{\sum}_{\beta \in \mathbb{E}(\Lambda)} d_{\beta}(B,s) x^{\beta} \right)\\
&= \mathop{\sum}_{\gamma \in \mathbb{E}(\Lambda)} \left(\mathop{\sum_{\alpha+\beta = \gamma}}_{\alpha,\beta \in \mathbb{E}(\Lambda)} d_{\alpha}(\supp(\alpha),s)d_{\beta}(\supp(\beta),t) \right) x^{\gamma}
\end{aligned}
\]
Then the coefficient of $\varphi(s)\varphi(t)$ at $\varepsilon$ is
\[ \mathop{\sum_{\alpha+\beta = \varepsilon}}_{\alpha,\beta \in \mathbb{E}(\Lambda)} d_{\alpha}(\supp(\alpha),s)d_{\beta}(\supp(\beta),t).\]
For any pair $\alpha,\beta \in \mathbb{E}(\Lambda)$ such that $\alpha + \beta = \varepsilon$, it holds that
\[ \supp(\alpha), \supp(\beta) \subset \supp(\varepsilon).\]
Then these elements $\alpha,\beta$ are canonically in $\mathbb{E}(\supp(\varepsilon))$. Moreover, from the commutativity $f_{\supp(\varepsilon) \supset \supp(\alpha)} \circ \rho_{\supp(\varepsilon)} = \rho_{\supp(\alpha)}$, we have
\[ d_{\alpha}(\supp(\alpha),s) = d_{\alpha}(\supp(\varepsilon),s)).\]
This also holds for $\beta$ and $t$. Then the coefficient of $\varphi(st)$ and the coefficient of $\varphi(s)\varphi(t)$ are the same at $\varepsilon$. Therefore we have $\varphi(st) = \varphi(s)\varphi(t)$. Finally, we show the uniqueness of $\varphi$. Assume that there exists a $K$-algebra morphism $\psi : S \rightarrow R$ such that $\pi_A \circ \psi = \rho_A$ for any $A \in \mathcal{P}$. For any $\varepsilon \in \mathbb{E}(\Lambda)$ and $s \in S$, we have
\[ \pi_{\supp(\varepsilon)}(\psi(s)) = \rho_{\supp(\varepsilon)}(s) = \sum_{\alpha \in \mathbb{E}(\supp(\varepsilon))} d_{\alpha}(\supp(\varepsilon),s) x^{\alpha}.\]
In particular, the coefficient of $\psi(s)$ at $\varepsilon$ is $d_{\varepsilon}(\supp(\varepsilon),s)$, which is the coefficient of $\varphi(s)$ at $\varepsilon$. Therefore we obtain $\varphi = \psi$.
\end{proof}

\fi

























































