\section{Error bounds for $U$-statistics computed on synthetic data}
\label{appendix:error_bounds}
Since $U_{\Tilde{n}}$ is a $U$-statistics with mean $\Tilde{\theta}_n$, we can safely write, by following Property~(\ref{eq:berry_esseen}),
\begin{align*}
          \left|\mathbb{P}\left( \frac{\sqrt{\Tilde{n}}(U_{\Tilde{n}} - \Tilde{\theta}_n)}{r\hat{\sigma}_1} \leq x \right) - \Phi(x) \right| \leq \frac{\hat{c}}{(1+|x|)^\beta\sqrt{\Tilde{n}-r+1}}.
\end{align*}    
Let $b=\frac{xr\hat{\sigma}_1}{\sqrt{\Tilde{n}}}+a_n>0$ where $a_n=\Tilde{\theta}_n - \theta$. The above expression becomes 
\begin{align*}
 \left|\mathbb{P}\left( U_{\Tilde{n}} - \theta \leq b \right) - \Phi\left(\frac{(b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right) \right| \leq \frac{\hat{c}}{\left(1+\left|\frac{(b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right|\right)^\beta\sqrt{\Tilde{n}-r+1}}=\Tilde{c}(a_n,b,\Tilde{n})
\end{align*}
where $\Tilde{c}(x,y,z) = \frac{\hat{c}}{\left(1+\left|\frac{(y-x)\sqrt{z}}{r\hat{\sigma}_1}\right|\right)^\beta\sqrt{z-r+1}}$.

\medskip

It implies that

\begin{align}
\label{ineq:first}
-\Tilde{c}(a_n,b,\Tilde{n}) + \Phi\left(\frac{(b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right) \leq \mathbb{P}\left( U_{\Tilde{n}} - \theta \leq b \right) \leq \Tilde{c}(a_n,b,\Tilde{n}) + \Phi\left(\frac{(b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right).
\end{align}

However, we are interested in the absolute distance $b$ from $\theta$. To address this, we first present the following analogous inequality.

\begin{align}
\label{ineq:second}
-\Tilde{c}(a_n,-b,\Tilde{n}) - \Phi\left(\frac{(-b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right) \leq -\mathbb{P}\left( U_{\Tilde{n}} - \theta \leq -b \right) \leq \Tilde{c}(a_n,-b,\Tilde{n}) - \Phi\left(\frac{(-b-a_n)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right).
\end{align}

Note that, $$\mathbb{P}\left( U_{\Tilde{n}} - \theta \leq b \right) - \mathbb{P}\left( U_{\Tilde{n}} - \theta \leq -b \right) = \mathbb{P}\left(|U_{\Tilde{n}} - \theta| \leq b \right)$$ where $b>0$ and also
$$\Phi(-x) = 1 - \Phi(x).$$

Therefore, the following bound can be obtained by combining Inequality~(\ref{ineq:first}) and (\ref{ineq:second}),

\begin{equation*}
\left| \mathbb{P}\left(|U_{\Tilde{n}} - \theta| \leq b \right) - \left[ \Phi\left(\frac{(a_n+b)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right) - \Phi\left(\frac{(a_n-b)\sqrt{\Tilde{n}}}{r\hat{\sigma}_1}\right)\right] \right| \leq \Tilde{c}(a_n,b,\Tilde{n}) + \Tilde{c}(a_n,-b,\Tilde{n}).
\end{equation*}


