\section{Error propagation due to eigenvector perturbation}
\label{appendix:perturb}
Using Equation~(\ref{eq:MPO:simple}), for any arbitrary vector $\mathbf{z}$, 

$$\bm{\Tilde{\Sigma}}_{(k)}^{-1} \mathbf{z} = \frac{1}{\lambda_1}\,\langle \mathbf{z},\mathbf{\Tilde{P}}_{:,1} \rangle\,\mathbf{\Tilde{P}}_{:,1}+ \sum_{\substack{1<i\leq m \\ i\neq k}} \frac{1}{\lambda_i}\,\langle \mathbf{z},\mathbf{P}_{:,i} \rangle\,\mathbf{P}_{:,i} +\frac{1}{\lambda_k}\,\langle \mathbf{z},\mathbf{\Tilde{P}}_{:,k} \rangle\,\mathbf{\Tilde{P}}_{:,k}+ \frac{1}{\lambda_c}\sum_{i\leq d-m}\langle \mathbf{z},\mathbf{Q}_{:,i} \rangle\,\mathbf{Q}_{:,i}$$

where $\bm{\Tilde{\Sigma}}_{(k)}$ is given by (\ref{new_cov}).

\medskip

Recall that for $k>1$, 
 $$
 \mathbf{\Tilde{P}}_{:,1} = -\sin \epsilon \cdot \mathbf{P}_{:,k} + \cos \epsilon \cdot \mathbf{P}_{:,1}
     \quad
\text{and}  \quad \mathbf{\Tilde{P}}_{:,k} = \cos \epsilon \cdot \mathbf{P}_{:,k} + \sin \epsilon \cdot \mathbf{P}_{:,1}.$$  

We are actually interested in, 
$$\bm{\Tilde{\Sigma}}_{(k)}^{-1} \mathbf{z} - \bm{\Sigma}^{-1} \mathbf{z} = \frac{1}{\lambda_1}(\underbrace{\langle \mathbf{z},\mathbf{\Tilde{P}}_{:,1} \rangle\,\mathbf{\Tilde{P}}_{:,1}-\langle \mathbf{z},\mathbf{P}_{:,1} \rangle\,\mathbf{P}_{:,1}}_{a_k}) + \frac{1}{\lambda_k}(\underbrace{\langle \mathbf{z},\mathbf{\Tilde{P}}_{:,k} \rangle\,\mathbf{\Tilde{P}}_{:,k}-\langle \mathbf{z},\mathbf{P}_{:,k} \rangle\,\mathbf{P}_{:,k}}_{b_k})$$
where
$$a_k = \left(\sin^2\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle - \sin\epsilon\cos\epsilon \,\langle \mathbf{z},\mathbf{\mathbf{P}_{:,1}} \rangle\right)\, \mathbf{P}_{:,k} + \left(-\sin\epsilon\cos\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle -\sin^2\epsilon \,\langle \mathbf{z},\mathbf{\mathbf{P}_{:,1}} \rangle\right)\, \mathbf{\mathbf{P}_{:,1}}$$
and 
$$b_k = \left(-\sin^2\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle+ \sin\epsilon\cos\epsilon \,\langle \mathbf{z},\mathbf{P}_{:,1} \rangle\right)\, \mathbf{P}_{:,k} + \left(\sin\epsilon\cos\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle+ \sin^2\epsilon \,\langle \mathbf{z},\mathbf{P}_{:,1} \rangle\right)\,\mathbf{P}_{:,1}$$

using the identity $\cos^2\epsilon+\sin^2\epsilon=1$. Since $b_k=-a_k$, 

$$\bm{\Tilde{\Sigma}}_{(k)}^{-1} \mathbf{z} - \bm{\Sigma}^{-1} \mathbf{z} = \left(\frac{1}{\lambda_1}-\frac{1}{\lambda_k}\right)a_k.$$

Therefore, 
\begin{align*}
\delta_{(k)}(\epsilon, \mathbf{z}) &= \bigl\| \bm{\Tilde{\Sigma}}_{(k)}^{-1} \mathbf{z} - \bm{\Sigma}^{-1} \mathbf{z} \bigl\|^2=\left(\frac{1}{\lambda_1}-\frac{1}{\lambda_k}\right)^2 \bigl\|a_k\bigl\|^2 \\
&=\left(\frac{1}{\lambda_1}-\frac{1}{\lambda_k}\right)^2 \left[\left(\sin^2\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle - \sin\epsilon\cos\epsilon \,\langle \mathbf{z},\mathbf{\mathbf{P}_{:,1}} \rangle\right)^2+\left(\sin\epsilon\cos\epsilon\,\langle \mathbf{z},\mathbf{P}_{:,k} \rangle+ \sin^2\epsilon \,\langle \mathbf{z},\mathbf{P}_{:,1} \rangle\right)^2\right] \\
&=\left(\frac{1}{\lambda_1}-\frac{1}{\lambda_k}\right)^2\left[\sin^4\epsilon\left(\langle \mathbf{z},\mathbf{P}_{:,k}\rangle^2 + \langle \mathbf{z},\mathbf{P}_{:,1}\rangle^2\right)+\cos^2\epsilon\sin^2\epsilon\left(\langle \mathbf{z},\mathbf{P}_{:,k}\rangle^2 + \langle \mathbf{z},\mathbf{P}_{:,1}\rangle^2\right)\right] \\
&= \left(\frac{1}{\lambda_1}-\frac{1}{\lambda_k}\right)^2\sin^2\epsilon\left(\langle \mathbf{z},\mathbf{P}_{:,k}\rangle^2 + \langle \mathbf{z},\mathbf{P}_{:,1}\rangle^2\right).
\end{align*}

