	\title{Collective phenomena in chirally imbalanced medium}

	\author{Sourav Duari\orcidlink{0009-0006-0795-5186}$^{a,c}$}
	\email{s.duari@vecc.gov.in}
	%	\email{snigdha@ggdckharagpur2.ac.in}
