%Chiral imbalance means no of right-handed quarks and no of left-handed quarks are not equal. 
The Feynman diagrams contributing to the gluon self-energy are shown in Fig.~\ref{one-loop} of which the first three diagrams do not depend on the chiral chemical potential and their contributions are well-known. So in the gluon self energy chiral asymmetry enters only in Fig.~\ref{one-loop}(d) where only quarks are involved. In this paper, we will use real time formulation (RTF) of thermal field theory where all two-point correlation functions such as the propagator and self-energy become $2\times2$ matrices in the thermal space~\cite{Bellac:2011kqa,Mallik:2016anp}. Few key features of RTF are summarized in Appendix~\ref{App_RTF}. Here we calculate the 11-component of the gluon polarization tensor for Fig.~\ref{one-loop}(d) which is necessary to study collective properties of the chiral plasma~\cite{Weldon:1982aq}. It is given by
\begin{equation}\label{self energy}
	 \Pi_{11}^{\mu\n}=-ig^2\frac{N_f}{2}\int \frac{d^4K}{(2\pi)^4}\text{Tr}\tbr{\gm^\mu\Sll{P=K+Q}\gm^\n\Sll{K}}
\end{equation}
where $g$ is the strong coupling constant, $N_f$ is the number of quark flavours, $Q=(q^0,\vec q)$ is the external gluon momentum and $K=(k^0,\vec k)$ is the loop momentum. $\Sll{K}$ is the 11-component of the fermionic thermal propagator matrix~\cite{Ghosh:2022xbf} in presence of chiral imbalanced medium in RTF and is given by
\begin{equation}
	\Sll{K}=\msd(k^0+\mu,\mdvec{k}) \sum_{r\in \sbr{\pm}}\frac{1}{4\mdvec{k}r\mu_5}\tbr{\frac{-1}{\fbr{k^0+\mu}^2-(\wkr)^2+i\ep}-\eta(k^0+\mu)2\pi i\delta((k^0+\mu)^2-(\wkr)^2)}
\end{equation}
%\begin{equation}
%	\Sll{P=K+Q}=\msd(p^0+\mu,\mdvec{p}) \sum_{r\in \sbr{\pm}}\frac{1}{4\mdvec{p}r\mu_5}\tbr{\frac{-1}{\fbr{p^0+\mu}^2-(\wpr)^2+i\ep}-\eta(p^0+\mu)2\pi i\delta((p^0+\mu)^2-(\wpr)^2)}
%\end{equation}
Here $\eta(x)=\Theta(x)f_+(x)+\Theta(-x)f_-(-x)$, $f_\pm(x)=\frac{1}{e^{\frac{x\mp\mu}{T}}+1}$, $\wpr=\mdvec{p}+r\mu_5$, $\wkr=\mdvec{k}+r\mu_5$.  $\msd(k^0+\mu,\mdvec{k})$ and $\msd(p^0+\mu,\mdvec{p})$ contain the Dirac structure of the fermion propagators which are given by
\begin{equation}
	\msd(k^0+\mu,\mdvec{k})= \mcpp \tilkm^2 \tilskp+\mcpm \tilkp^2 \tilskm 
\end{equation}
%\begin{equation}
%	\msd(p^0+\mu,\mdvec{p})= \mcpp \tilpm^2 \tilspp+\mcpm \tilpp^2 \tilspm 
%\end{equation}
in which $\mathcal{P}_\pm = \frac{1}{2}(1\pm\gm^5)$, $\tilde{K}_\pm^\mu\equiv(k^0+\mu\pm\mu_5,\vec{k})$ and  $\tilde{P}_\pm^\mu\equiv(p^0+\mu\pm\mu_5,\vec{p})$.
Eq.~\eqref{self energy} can be written as
\begin{equation}
	\Pi^\munu_{11}=\fbr{\Pi^\munu_{11}}_{\rm vac}+\fbr{\Pi^\munu_{11}}_I+\fbr{\Pi^\munu_{11}}_{II},
\end{equation}
where $\fbr{\Pi^\munu_{11}}_{\rm vac}$ is the temperature independent part and $\fbr{\Pi^\munu_{11}}_I$, $\fbr{\Pi^\munu_{11}}_{II}$ are temperature dependent parts. These are given by 
\begin{eqnarray}\label{self_energy_vac}
	\fbr{\Pi^\munu_{11}}_{\rm vac}&=&-\frac{ig^2}{(2\pi)^4}\frac{N_f}{2}\int d^4K \frac{L^\munu}{16 kp\mu_5}\tbr{\frac{-1}{(k^0+\mu)^2-(\wkp)^2+i\epsilon}-\frac{-1}{(k^0+\mu)^2-(\wkm)^2+i\epsilon}}\nn\\
	&&\tbr{\frac{-1}{(p^0+\mu)^2-(\wpp)^2+i\epsilon}-\frac{-1}{(p^0+\mu)^2-(\wpm)^2+i\epsilon}}
\end{eqnarray}
\begin{eqnarray}\label{self_energy_I}
	\fbr{\Pi^\munu_{11}}_I&=&-\frac{ig^2}{(2\pi)^4}\frac{N_f}{2}\int d^4K\frac{L^\munu}{16kp\mu_5^2}\tbr{2\pi i \eta(p^0+\mu)\sbr{\frac{1}{(k^0+\mu)^2-(\wkp)^2+i\epsilon} -\frac{1}{(k^0+\mu)^2-(\wkm)^2+i\epsilon} }\right.\nn\\
	&&\sbr{\delta\fbr{(p^0+\mu)^2-(\wpp)^2}-\delta\fbr{(p^0+\mu)^2-(\wpm)^2}}
 +2\pi i \eta(k^0+\mu)\sbr{\frac{1}{(p^0+\mu)^2-(\wpp)^2+i\epsilon} -\frac{1}{(p^0+\mu)^2-(\wpm)^2+i\epsilon} }\nn\\
&&\left.\sbr{\delta\fbr{(k^0+\mu)^2-(\wpp)^2}-\delta\fbr{(k^0+\mu)^2-(\wpm)^2}}}
\end{eqnarray}
\begin{eqnarray}\label{self_energy_II}
	\fbr{\Pi^\munu_{11}}_{II}&=&-\frac{ig^2}{(2\pi)^4}\frac{N_f}{2}\int d^4K\frac{L^\munu}{16kp\mu_5^2}(2\pi i \eta(k^0+\mu))(2\pi i \eta(p^0+\mu))\sbr{\delta\fbr{(k^0+\mu)^2-(\wkp)^2}-\delta\fbr{(k^0+\mu)^2-(\wkm)^2}}\nn\\
	&&\sbr{\delta\fbr{(p^0+\mu)^2-(\wpp)^2}-\delta\fbr{(p^0+\mu)^2-(\wpm)^2}}~.
\end{eqnarray}
Here $k=\mdvec{k}$, $p=\mdvec{p}$ and
\begin{eqnarray}
 L^\munu&=&2\tilpm^2\tilkm^2\tbr{\tilkp^\mu\tilpp^\nu+\tilkp^\nu\tilpp^\mu-g^\munu\tilkp\cdot \tilpp}+2i\tilpm^2\tilkm^2 \epsilon^{\mu\nu\alpha\beta} (\tilpp)_\alpha (\tilkp)_\beta+\nn\\
 &&2\tilpp^2\tilkp^2\tbr{\tilkm^\mu\tilpm^\nu+\tilkm^\nu\tilpm^\mu-g^\munu\tilkm\cdot \tilpm}-2i\tilpp^2\tilkp^2 \epsilon^{\mu\nu\alpha\beta} (\tilpm)_\alpha (\tilkm)_\beta~.
\end{eqnarray}
