%	\text{Im}\Pi^\munu(K)=\text{sign}(k^0)\tanh(k^0/2T)\text{Im}\Pi_{11}^\munu(K)
%\end{equation}
Only the real part of the analytic in-medium self energy i.e. the diagonal component of $2\times 2$ matrix in the thermal space contributes to the dispersion relations~\cite{Weldon:1982aq}. This can be calculated from the 11-component of the self energy by using Eq.~\eqref{Eq_Re11_Re}. Note that, in the appendix we have distinguished the diagonal element from other components by denoting it via a \textit{`bar'}. However in the following discussion only the diagonal component is necessary to calculate different collective properties of the system and hence for clarity of presentation we will remove the \textit{`bar'} notation. Since Eq.~\eqref{self_energy_II} only contributes to the imaginary part,  integrating over $k^0$ in Eq.~\eqref{self_energy_I} we get
\begin{eqnarray}\label{Re-self energy}
	\text{Re}\Pi^\munu&=&\frac{g^2}{(2\pi)^3}\frac{N_f}{2}\int\frac{d^3k}{16kp\mu_5^2}\text{P}\left[\fppp \frac{L_5^\munu}{2\wpp}\left\{\frac{1}{2\wkp}\fbr{\frac{1}{-q^0-\wkp+\wpp}-\frac{1}{-q^0+\wkp+\wpp}}\right.\right.\nn\\
	&&\left.-\frac{1}{2\wkm}\fbr{\frac{1}{-q^0-\wkp+\wpp}-\frac{1}{-q^0+\wkp+\wpp}}\right\}-\fppm\frac{L_5^{\prime\munu}}{2\wpm}\left\{\frac{1}{2\wkp}\fbr{\frac{1}{-q^0-\wkp+\wpm}-\frac{1}{-q^0+\wkp+\wpm}}\right.\nn\\
	&&\left.-\frac{1}{2\wkm}\fbr{\frac{1}{-q^0-\wkm+\wpm}-\frac{1}{-q^0+\wkm+\wpm}}\right\}+\fmpp\frac{L_6^{\munu}}{2\wpp}\left\{\frac{1}{2\wkp}\fbr{\frac{1}{-q^0-\wkp-\wpp}-\frac{1}{-q^0+\wkp-\wpp}}\right.\nn\\
	&&\left.-\frac{1}{2\wkm}\fbr{\frac{1}{-q^0-\wkm-\wpp}-\frac{1}{-q^0+\wkm-\wpp}}\right\}-\fmpm\frac{L_6^{\prime\munu}}{2\wpm}\left\{\frac{1}{2\wkp}\fbr{\frac{1}{-q^0-\wkp-\wpm}-\frac{1}{-q^0+\wkp-\wpm}}\right.\nn\\
	&&\left.-\frac{1}{2\wkm}\fbr{\frac{1}{-q^0-\wkm-\wpm}-\frac{1}{-q^0+\wkm-\wpm}}\right\}+\fppm\frac{L_6^{\prime\munu}}{2\wpm}\left\{\frac{1}{2\wkp}\fbr{\frac{1}{-q^0-\wkp-\wpm}-\frac{1}{-q^0+\wkp-\wpm}}\right.\nn\\
	&&\left.-\frac{1}{2\wkm}\fbr{\frac{1}{-q^0-\wkm-\wpm}-\frac{1}{-q^0+\wkm-\wpm}}\right\}+\fpkp\frac{L_1^{\munu}}{2\wkp}\left\{\frac{1}{2\wpp}\fbr{\frac{1}{q^0+\wkp-\wpp}-\frac{1}{q^0+\wkp+\wpp}}\right.\nn\\
	&&\left.-\frac{1}{2\wpm}\fbr{\frac{1}{q^0+\wkp-\wpm}-\frac{1}{q^0+\wkp+\wpm}}\right\}-\fpkm\frac{L_1^{\prime\munu}}{2\wkm}\left\{\frac{1}{2\wpp}\fbr{\frac{1}{q^0+\wkm-\wpp}-\frac{1}{q^0+\wkm+\wpp}}\right.\nn\\
	&&\left.-\frac{1}{2\wpm}\fbr{\frac{1}{q^0+\wkm-\wpm}-\frac{1}{q^0+\wkm+\wpm}}\right\}+\fmkp\frac{L_2^{\munu}}{2\wkp}\left\{\frac{1}{2\wpp}\fbr{\frac{1}{q^0-\wkp-\wpp}-\frac{1}{q^0-\wkp+\wpp}}\right.\nn\\
	&&\left.-\frac{1}{2\wpm}\fbr{\frac{1}{q^0-\wkp-\wpm}-\frac{1}{q^0-\wkp+\wpm}}\right\}-\fmkm\frac{L_2^{\prime\munu}}{2\wkm}\left\{\frac{1}{2\wpp}\fbr{\frac{1}{q^0-\wkm-\wpp}-\frac{1}{q^0-\wkm+\wpp}}\right.\nn\\
	&&\left.\left.-\frac{1}{2\wpm}\fbr{\frac{1}{q^0-\wkm-\wpm}-\frac{1}{q^0-\wkm+\wpm}}\right\}\right]
\end{eqnarray}
