\section{ General structure of gluon self-energy and the effective propagator}
%\subsection{General structure of gluon self-energy at $\mu_5\neq0$}

The general structure of gluon self-energy in a chirally imbalanced medium is given by\cite{Nieves:1988qz}
\begin{equation}\label{Eq_Gen_SE}
	\Pi^\munu = \Pi_T R^\munu_T + \Pi_L Q^\munu_L   + \Pi_A P^\munu_A~,
\end{equation}
where  $Q^\munu_L$, $R_T^\munu$ and $P_A^\munu$ are orthogonal to each other and also orthogonal to $Q_\mu$ and $Q_\nu$ so that gauge invariance is preserved i.e $Q_\mu\Pi^\munu=Q_\nu\Pi^\munu=0$. $Q_L^\munu$, $R_T^\munu$ and $P_A^\munu$ are constructed from the known quantities i.e gluon momentum $q^\mu$ , metric tensor $g^\munu$ and thermal bath velocity $U^\mu$. Form of these tensors are as follows,
\begin{equation}
	Q^\munu_L=\frac{\util^\mu\util^\nu}{\util^2},\hspace{0.5cm}R_T^\munu=\gtil^\munu-Q^\munu_L,\hspace{0.5cm} P_A^\munu=\frac{i}{q}\ep^{\munu\alp\bt}Q_\alp U_\bt~,
\end{equation}
where 
\begin{equation}
	\util^\mu=\gtil^\munu U_\nu,\hspace{0.5cm}\gtil^\munu=g^\munu-\frac{Q^\mu Q^\nu}{Q^2},
\end{equation}
and $U^\mu=(1,0,0,0)$ in the local rest frame.
%So, $\Pi^\munu$ depends on the gluon 4-momentum($Q^\mu$) and velocity 4-vector($U^\mu$) of the thermal medium. 
$\Pi_L$ and $\Pi_T$ are longitudinal and transverse parts of gluon polarization tensor and $\Pi_A$ is the anomalous  contribution which appears due to the chiral asymmetry of the medium.
\begin{equation}\label{coefficient}
	\Pi_L=(Q_L)_\munu\Pi^\munu,\hspace{0.5cm}\Pi_T=\frac{1}{2}(R_T)_\munu\Pi^\munu,\hspace{0.5cm}\Pi_A=-\frac{1}{2}(P_A)_\munu\Pi^\munu,\hspace{0.5cm}
\end{equation}	


%==================================================================================	
%\subsection{Effective gluon Propagator at $\mu_5\neq0$}
%==================================================================================	
%\section{Effective gluon Propagator}

\begin{figure}[h]
	\centerline{\includegraphics[scale=.30]{./Plots/gluon_effective_propagator.png}}
	\caption{Effective gluon propagator}
	\label{dyson_fig}
\end{figure}
Using the Dyson-Schwinger equation (Fig.~\ref{dyson_fig}) we get
\begin{equation}
	(G^{-1})_\munu=(G^{-1}_0)_\munu+\Pi_\munu
\end{equation}  
where $(G^{-1}_0)_\munu$ is inverse of the free gluon propagator given by
\begin{equation}
	(G^{-1}_0)_\munu=Q^2g_\munu-\fbr{1-\frac{1}{\xi}}Q_\mu Q_\nu~.
\end{equation}
We now decompose $(G)_\munu$ as
\begin{equation}
	G_\munu=G_1 Q_\mu Q_\nu+G_2 A_\munu+ G_3 (Q_L)_\munu+G_4 B_\munu
\end{equation}
where $ A_\munu$, $ (Q_L)_\munu$ and $ B_\munu$ are the projection tensors defined as
\begin{equation}
	A_\munu=\frac{1}{2}\fbr{ (R_T)_\munu+ (P_A)_\munu},\hspace{0.5cm}  B_\munu=\frac{1}{2}\fbr{ (R_T)_\munu- (P_A)_\munu}~.
\end{equation}
%To evaluate G1,G2,G3,G4 we use the following equation
%\begin{equation}
%	G^\munu(G^{-1})_{\nu\rho}=\delta_\rho^\mu
%\end{equation}	
The effective propagator is finally given by
\begin{equation}\label{Eff_prop}
	G_\munu=\frac{\xi}{Q^2}\frac{Q_\mu Q_\nu}{Q^2}+\frac{A_\munu}{Q^2+\Pi_T+\Pi_A}+\frac{B_\munu}{Q^2+\Pi_T-\Pi_A}+\frac{(Q_L)_\munu}{Q^2+\Pi_L}~.
\end{equation}

\section{Evaluation of the structure functions $\Pi_L$, $\Pi_T$, $\Pi_A$ }
%-------------------------------------
\subsection{Calculation of $\Pi_L$}

Using the transversality condition i.e $q_\mu\Pi^\munu=0$ we can write 
\begin{equation}\label{eq_piL}
	\Pi_L=(Q_L)_\munu\Pi^\munu=\frac{U_\mu U_\nu}{\util^2}\Pi^\munu=\frac{\Pi^{00}}{\util^2}~.
\end{equation}
Now, in the HTL approximation the external soft momentum ($~gT$) can be ignored  with respect to the loop momentum which is of order $T$. This leads to the following approximate expressions
%Note that this approximation is valid for weak coupling constant i.e $g\ll 1$.Here we can write the following approximations.
	\begin{eqnarray}\label{approx}
		p\approx k+q\cos\theta~~~~~~~~~~~~~~~~~~~\nn\\
		\frac{1}{\pm q_0\pm(\wpp-\wkp)}\approx\frac{1}{\pm q_0\pm q\cos\theta}~~~~~~~~~~\nn\\
		\frac{1}{\pm q_0\pm(\wpm-\wkm)}\approx\frac{1}{\pm q_0\pm q\cos\theta}~~~~~~~~~~\nn\\	
		\frac{1}{\pm q_0\pm(\wpp-\wkm)}\approx \frac{1}{\pm 2\mu_5\pm q^0\pm q\cos\theta}~~~~~~~\nn\\
		%\frac{1}{\pm q_0\pm(\wpp-\wkm)}\approx\frac{1}{\pm q_0\pm 2\mu_5\pm q\cos\theta}\nn\\
		\frac{1}{\pm q_0\pm(\wpm-\wkp)}\approx\frac{1}{\mp 2\mu_5\pm q^0\pm q\cos\theta}~~~~~~~\nn\\
		%	\frac{1}{\pm q_0\pm(\wpm-\wkp)}\approx\frac{1}{\mp q_0\mp 2\mu_5\pm q\cos\theta}\nn\\
		\frac{1}{\pm q^0+\omega^\pm_p+\omega^\pm_k}\approx\frac{1}{2k\pm2\mu_5\pm q^0+q\cos\theta}~~~~~~\nn\\
		\frac{1}{\pm q^0+\omega^\pm_p+\omega^\mp_k}\approx\frac{1}{2k\pm q^0+q\cos\theta}~~~~~~~~\nn\\
		f_\pm^{p_\pm}\approx f_\pm^{k_\pm}+\frac{\partial f_\pm^{k_\pm}}{\partial k} q\cos\theta~~~~~~~~~~\nn\\
	\end{eqnarray}
	using which we can write
	\begin{equation}\label{piL-L1}
		L_1^{00}\approx L_2^{ 00}\approx L_5^{00} \approx L_6^{00} \approx 64\mu_5^2 k^2 (k+\mu_5)^2
	\end{equation}
	\begin{equation}\label{piL-L1p}
		L_1^{\prime 00}\approx L_2^{\prime 00}\approx L_5^{\prime00} \approx L_6^{\prime 00} \approx 64\mu_5^2 k^2 (k-\mu_5)^2~.
	\end{equation}
From Eqs.~\eqref{Re-self energy},~\eqref{eq_piL}-\eqref{piL-L1p} the
expression for $\Pi_L$ after some algebra becomes
\begin{eqnarray}
	\Pi_L&\approx&\frac{1}{\util^2}\frac{g^2}{(2\pi)^3}\frac{N_f}{2}\tbr{\int d^3k\fbr{\frac{\partial\fpkp}{\partial k}+\frac{\partial\fpkm}{\partial k}}\frac{q\cos\theta}{-q_0+q\cos\theta}+\int d^3k\fbr{\frac{\partial\fmkp}{\partial k}+\frac{\partial\fmkm}{\partial k}}\frac{q\cos\theta}{q_0+q\cos\theta}}\nn\\
	&=& g^2\frac{N_f}{2}\fbr{\frac{T^2}{3}+\frac{\mu^2+\mu_5^2}{\pi^2}}\frac{q_0^2-q^2}{q^2}\fbr{1-\frac{q_0}{2q}\logterm}~.
\end{eqnarray}
Now, the results of the loop diagrams in Fig.~\ref{one-loop}a-c are $\mu_5$ independent and exist in the literature~\cite{Bellac:2011kqa,Klimov:1982bv,Weldon:1982aq}. Considering all four loops of Fig.~\ref{one-loop} we can write $\Pi_L$ as
\begin{eqnarray}
	\Pi_L&=& \fbr{g^2\frac{T^2}{6}\fbr{N_f+2C_A}+\frac{N_fg^2}{2\pi^2}\fbr{\mu^2+\mu_5^2}} \frac{q_0^2-q^2}{q^2}\fbr{1-\frac{q_0}{2q}\logterm}\nn\\
	&=&\MD^2 \frac{q_0^2-q^2}{q^2}\fbr{1-\frac{q_0}{2q}\logterm}
\end{eqnarray}
where $\MD$ is the Debye mass given by
\begin{equation}
	\MD^2=g^2\frac{T^2}{6}\fbr{N_f+2C_A}+\frac{N_fg^2}{2\pi^2}\fbr{\mu^2+\mu_5^2}~.
\end{equation}

%-------------------------------------

%-------------------------------------
\subsection{Calculation of $\Pi_T$}

From Eq.~\eqref{coefficient} we can write
\begin{eqnarray}
	\Pi_T&=&\frac{1}{2}(R_T)_\munu\Pi^\munu=\frac{1}{2}\tbr{\gtil_\munu-(Q_L)_\munu}\Pi^\munu\nn\\
	&=&\frac{1}{2}\gtil_\munu\Pi^\munu-\frac{1}{2}\Pi_L~.
\end{eqnarray}
The transversality condition i.e $q_\mu\Pi^\munu=0$ gives
\begin{equation}\label{eq_piT}
	\Pi_T=\frac{1}{2}g_\munu\Pi^\munu-\frac{1}{2}\Pi_L~.
\end{equation}
Using  Eqs.~\eqref{approx} the relevant quantities can be written as
\begin{equation}\label{piT-L1}
	g_\munu L_1^{\munu}\approx -g_\munu L_5^{\munu}\approx -64 k\mu_5^2(k+\mu_5)^2(q_0-q\cos\theta)
\end{equation}
\begin{equation}\label{piT-L1p}
	g_\munu L_1^{\prime \munu}\approx -g_\munu L_5^{\prime \munu}\approx -64 k\mu_5^2(k-\mu_5)^2(q_0-q\cos\theta)
\end{equation}
\begin{equation}\label{piT-L2}
	g_\munu L_2^{\munu}\approx -g_\munu L_6^{\munu}\approx 64 k\mu_5^2(k+\mu_5)^2(q_0+q\cos\theta)
\end{equation}
\begin{equation}\label{piT-L2p}
	g_\munu L_2^{\prime \munu}\approx -g_\munu L_6^{\prime \munu}\approx 64 k\mu_5^2(k-\mu_5)^2(q_0+q\cos\theta)~.
\end{equation}
From Eqs.~\eqref{Re-self energy},\eqref{approx},\eqref{eq_piT}-\eqref{piT-L2p} we can write $\Pi_T$ as
\begin{eqnarray}
	\Pi_T&\approx&-\frac{g^2}{(2\pi)^3}\frac{N_f}{2}\int\frac{d^3k}{k}\tbr{\fpkp+\fmkm+\fmkp+\fpkm}-\frac{1}{2}\Pi_L\nn\\
	&=&-\frac{1}{2}g^2\frac{N_f}{2}\fbr{\frac{T^2}{3}+\frac{\mu^2+\mu_5^2}{\pi^2}}-\frac{1}{2}\Pi_L\nn\\
	&=&-\frac{1}{2}g^2\frac{N_f}{2}\fbr{\frac{T^2}{3}+\frac{\mu^2+\mu_5^2}{\pi^2}}\frac{q_0^2}{q^2}\fbr{1+\frac{1}{2}\fbr{\frac{q}{q_0}-\frac{q_0}{q}}\logterm}~.
\end{eqnarray}

Considering all four loops of Fig.~\ref{one-loop} the final expression for $\Pi_T$ is given by
\begin{eqnarray}
	\Pi_T &=& -\frac{1}{2}\fbr{g^2\frac{T^2}{6}\fbr{N_f+2C_A}+\frac{N_fg^2}{2\pi^2}\fbr{\mu^2+\mu_5^2}} \frac{q_0^2}{q^2}\fbr{1+\frac{1}{2}\fbr{\frac{q}{q_0}-\frac{q_0}{q}}\logterm}\nn\\
	&=&-\frac{1}{2}\MD^2 \frac{q_0^2}{q^2}\fbr{1+\frac{1}{2}\fbr{\frac{q}{q_0}-\frac{q_0}{q}}\logterm}~.
\end{eqnarray}

%-------------------------------------
\subsection{Calculation of $\Pi_A$}
To calculate $\Pi_A$ we need to evaluate $L^\munu (P_A)_\munu$ where
\begin{equation}
	L^\munu (P_A)_\munu=4\frac{\tilkp^2\tilpp^2}{q}\tbr{\tilkm\cdot Q \tilpm^0-\tilpm\cdot Q \tilkm^0}+4\frac{\tilkm^2\tilpm^2}{q}\tbr{\tilpp\cdot Q \tilkp^0-\tilkp\cdot Q \tilpp^0}~.
\end{equation}
%Now we consider that external momentum is soft with respect to internal momentum.
So the required quantities in the HTL approximation are given by
\begin{equation}\label{piP-L1}
	L_1^{\munu}(P_A)_\munu \approx L_5^{\munu}(P_A)_\munu \approx 64 k \mu_5^2(k+\mu_5)^2\frac{q_0}{q}\fbr{q_0-q\cos\theta-\frac{q_0^2-q^2}{q_0}}
\end{equation}
\begin{equation}\label{piP-L1p}
	L_1^{\prime\munu}(P_A)_\munu \approx L_5^{\prime\munu}(P_A)_\munu \approx -64 k \mu_5^2(k-\mu_5)^2\frac{q_0}{q}\fbr{q_0-q\cos\theta-\frac{q_0^2-q^2}{q_0}}
\end{equation}
\begin{equation}\label{piP-L2}
	L_2^{\munu}(P_A)_\munu \approx L_6^{\munu}(P_A)_\munu \approx 64 k \mu_5^2(k+\mu_5)^2\frac{q_0}{q}\fbr{q_0+q\cos\theta-\frac{q_0^2-q^2}{q_0}}
\end{equation}
\begin{equation}\label{piP-L2p}
	L_2^{\prime\munu}(P_A)_\munu \approx L_6^{\prime\munu}(P_A)_\munu \approx -64 k \mu_5^2(k-\mu_5)^2\frac{q_0}{q}\fbr{q_0+q\cos\theta-\frac{q_0^2-q^2}{q_0}}~.
\end{equation}
Using Eqs.~\eqref{Re-self energy},\eqref{approx},\eqref{piP-L1}-\eqref{piP-L2p} we can write $\Pi_A$ as
\begin{eqnarray}
	\Pi_A&\approx&\frac{g^2}{(2\pi)^2}\frac{N_f}{2}\frac{q_0^2-q^2}{q}\fbr{1-\frac{q_0}{2q}\logterm}\int dk k \tbr{\frac{\partial\fpkp}{\partial k}-\frac{\partial\fmkm}{\partial k}-\frac{\partial\fpkm}{\partial k}+\frac{\partial\fmkp}{\partial k}}\nn\\
	&=&-\frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 \frac{q_0^2-q^2}{q}\fbr{1-\frac{q_0}{2q}\logterm}~.
\end{eqnarray}






