\section{sum rules and residues}	

The longitudinal and transverse gluon propagators $\Delta_L$ and $\Delta_T^\pm$ are defined as
\begin{eqnarray}
	\Delta_L(q_0,q)&&=\frac{Q^2}{q^2}\frac{-1}{Q^2+\Pi_L}\nn\\
	&&=\frac{-1}{q^2+\MD^2\fbr{1-\frac{q_0}{2q}\ln\frac{q_0+q}{q_0-q}}}
\end{eqnarray}
and
\begin{eqnarray}
	\Delta_T^\pm(q_0,q)&&=\frac{-1}{Q^2+\Pi_T\mp\Pi_A}\nn\\
	&&=\frac{-1}{q_0^2-q^2-\frac{1}{2}\MD^2 \frac{q_0^2}{q^2}\fbr{1+\frac{1}{2}\fbr{\frac{q}{q_0}-\frac{q_0}{q}}\logterm}\pm\frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 \frac{q_0^2-q^2}{q}\fbr{1-\frac{q_0}{2q}\logterm}}~.	
\end{eqnarray}

\begin{figure}[h]
	\includegraphics[scale=0.34,angle=0]{./Plots/contour.png} 
	\caption{Integration contour for derivation of sum rules}\label{contour}
	\end{figure}
$\Delta_L$ and $\Delta_T^\pm$ are analytic in the complex $q_0$-plane cut from $-q$ to $q$ and they have poles at $q_0=\pm\omega_L$ and $\pm\omega_T^\pm$. So one can write for $\Delta=\Delta_L$ or $\Delta_T^\pm$ using Cauchy's theorem 
\begin{eqnarray}\label{cauchy}
	\Delta(q_0,q)&&=\oint_\Gamma \frac{dz}{2\pi i}\frac{\Delta(z,q)}{z-q_0}\nn\\
	&&=\int_{-\infty}^{\infty}\frac{dq_0^\prime}{2\pi i}\frac{\Delta(q_0^\prime+i\ep,q)-\Delta(q_0^\prime-i\ep,q)}{q_0^\prime-q_0}+\oint_{\Gamma^\prime} \frac{dz}{2\pi i}\frac{\Delta(z,q)}{z}~,
\end{eqnarray}
where $\Gamma$ is the contour shown in Fig.~\ref{contour} and $\Gamma^\prime$ is a circle whose radius tends to infinity. Eq.~\ref{cauchy} can be written in terms of spectral density $\rho(q_0,q)=2\text{Im}\Delta(q_0+i\ep,q)$ which contains both the discontinuities across the cuts and residues at poles~\cite{Bellac:2011kqa}. The  above equation can be written as
\begin{equation}\label{delq}
	\Delta(q_0,q)=\int_{-\infty}^{\infty}\frac{dq_0^\prime}{2\pi }\frac{\rho(q_0^\prime,q)}{q_0^\prime-q_0}+\oint_{\Gamma^\prime} \frac{dz}{2\pi i}\frac{\Delta(z,q)}{z}	
\end{equation}	
Now $\Delta_T^\pm(z,q)\sim\frac{1}{z^2}$. As $z\rightarrow\infty$, $\Delta_T^\pm(z,q)\rightarrow0$, there is no contribution from $\Gamma^\prime$. For $z\rightarrow\infty$, $\Delta_L(z,q)\rightarrow\frac{-1}{q^2}$ and this will contribute for contour $\Gamma^\prime$. Sum rules are obtained by setting $q_0=0$ in the Eq.~\ref{delq}~\cite{Bellac:2011kqa}.
Sum rule for $\Delta_L$ at small $q_0$ is given by
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi }\frac{\rho_L(q_0,q)}{q_0-q_0}=\frac{1}{q^2}+\Delta_L(0,q)=\frac{\MD^2}{q^2\fbr{q^2+\MD^2}}
\end{equation}
and the sum rule for $\Delta_T^\pm$ at small $q_0$ is
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi }\frac{\rho_T^\pm(q_0,q)}{q_0-q_0}=\Delta_T^\pm(0,q)=\frac{1}{q^2\pm\frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5}~.
\end{equation}

Other sum rules may be obtained by setting $q_0$ very large~\cite{Bellac:2011kqa}. This is given by
\begin{eqnarray}\label{delL}
	\Delta_L(q_0,q)&&=-\frac{1}{q^2}+\int_{-\infty}^{\infty}\frac{dq_0}{2\pi }\frac{\rho_L(q_0,q)}{q_0-q_0}\nn \\
	&&=-\frac{1}{q^2}-\frac{1}{q_0}\sum_{n=0}^{\infty}\int_{-\infty}^{\infty}\frac{dq_0^\prime}{2\pi}\fbr{\frac{q_0^\prime}{q_0}}^{2n+1}\rho_L(q_0^\prime,q)~.
\end{eqnarray}
Now expanding $\Delta_L(q_0,q)$ for large $q_0$ we obtain
\begin{equation}\label{delL1}
	\Delta_L(q_0,q)=-\frac{1}{q^2}-\frac{\MD^2}{3q^2q_0^2}-\frac{\frac{\MD^2}{5}+\frac{\MD^4}{9q^2}}{q_0^4}+\mathcal{O}[q_0^{-6}]~.
\end{equation}
Comparing the powers of $q_0^{-2}$ on the right hand sides of the Eqs.~\eqref{delL} and \eqref{delL1} we get
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi}q_0\rho_L(q_0,q)=\frac{\MD^2}{3q^2}=\frac{\omega_p^2}{q^2}~.
\end{equation}
Similarly comparison of the power of $q_0^{-4}$ on the right hand sides of the Eqs.~\eqref{delL} and \eqref{delL1} gives
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi}q_0^3\rho_L(q_0,q)=\frac{\MD^2}{5}+\frac{\MD^4}{9q^2}=\frac{3\omega_p^2}{5}+\frac{\omega_p^4}{q^2}~.
\end{equation}

Now we proceed to calculate the sum rules for $\Delta_T^\pm$ at large $q_0$ where
\begin{eqnarray}\label{delT}
	\Delta_T^\pm(q_0,q)&&=\int_{-\infty}^{\infty}\frac{dq_0}{2\pi }\frac{\rho_T^\pm(q_0,q)}{q_0-q_0}\nn \\
	&&=-\frac{1}{q_0}\sum_{n=0}^{\infty}\int_{-\infty}^{\infty}\frac{dq_0^\prime}{2\pi}\fbr{\frac{q_0^\prime}{q_0}}^{2n+1}\rho_T^\pm(q_0^\prime,q)
\end{eqnarray}
Now expanding $\Delta_T^\pm(q_0,q)$ for large $q_0$ we get
\begin{equation}\label{delT1}
	\Delta_T^\pm(q_0,q)=-\frac{1}{q_0^2}-\frac{1}{q_0^4}\tbr{\frac{\MD^2}{3}+q^2\pm\frac{g^2}{12\pi^2}\frac{N_f}{2}\mu_5q}+\mathcal{O}[q_0^{-6}]~.
\end{equation}

Comparing the powers of $q_0^{-2}$ on the right hand sides of the Eqs.~\eqref{delT} and \eqref{delT1} we get
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi}q_0\rho_T^\pm(q_0,q)=1
\end{equation}
and comparison of the power of $q_0^{-4}$ on the right hand sides of the Eqs.~\eqref{delT} and \eqref{delT1} gives
\begin{equation}
	\int_{-\infty}^{\infty}\frac{dq_0}{2\pi}q_0^3\rho_T^\pm(q_0,q)=\frac{\MD^2}{3}+q^2\pm\frac{g^2}{12\pi^2}\frac{N_f}{2}\mu_5q=\omega_p^2+q^2\pm\frac{g^2}{12\pi^2}\frac{N_f}{2}\mu_5q~.
\end{equation}

Now residues of $\Delta_L$ and $\Delta_L^\pm$ are evaluated at the poles.
Residue of the longitudinal excitations is given by
\begin{equation}
	Z_L(q)=-\fbr{\frac{\partial\Delta_L^{-1}(q_0,q)}{\partial q_0}\Big{\arrowvert}_{q_0=\omega_L(q)}}^{-1}=\frac{\omega_L\fbr{\omega_L^2-q^2}}{q^2\fbr{q^2+\MD^2-\omega_L^2}}
\end{equation}
and residues of the corresponding expressions for transverse modes are given by
\begin{equation}
	Z_T^\pm(q)=-\fbr{\frac{\partial(\Delta_T^\pm)^{-1}(q_0,q)}{\partial q_0}\Big{\arrowvert}_{q_0=\omega_T^\pm(q)}}^{-1}=\frac{\omega_T^\pm\fbr{(\omega_T^\pm)^2-q^2}}{(\omega_T^\pm)^2\MD^2-\tbr{(\omega_T^\pm)^2-q^2}^2\pm\frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 q \tbr{(\omega_T^\pm)^2-q^2}}~.
\end{equation}
So the complete expression of the spectral function for longitudinal excitations is given by
\begin{equation}
	(2\pi)^{-1}\rho_L(q_0,q)=Z_L(q)[\delta(q_0-\omega_L(q))-\delta(q_0+\omega_L(q))]+\beta_L(q_0,q)
\end{equation}
where $\beta_L(q_0,q)$ is
\begin{equation}
	\beta_L(q_0,q)=\frac{\frac{1}{2}\MD^2\frac{q_0}{q}\Theta\fbr{1-\frac{q_0}{q}}}{\tbr{q^2+\MD^2\fbr{1-\frac{q_0}{2q}\logterm}}^2+\frac{\MD^4\pi^2q_0^2}{4q^2}}
\end{equation}
and the complete expression of the spectral function of transverse excitations is given by
\begin{equation}
	(2\pi)^{-1}\rho_T^\pm(q_0,q)=Z_T^\pm(q)[\delta(q_0-\omega_T^\pm(q))-\delta(q_0+\omega_T^\pm(q))]+\beta_T^\pm(q_0,q)
\end{equation}
where $\beta_T^\pm(q_0,q)$ is given by
\begin{equation}
	\beta_T^\pm(q_0,q)=\frac{\frac{1}{2}\Theta\fbr{1-\frac{q_0^2}{q^2}}\frac{q_0q}{q_0^2-q^2}\fbr{-\frac{\MD^2}{2}\pm \frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 q }}{\tbr{q^2-\frac{1}{2}\frac{\MD^2q^2}{q_0^2-q^2}+\fbr{-\frac{\MD^2}{2}\pm \frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 q }\fbr{1-\frac{q_0}{2q}\logterm}}^2+\frac{\pi^2q_0^2}{4q^2}\fbr{-\frac{\MD^2}{2}\pm \frac{g^2}{2\pi^2}\frac{N_f}{2} \mu_5 q }^2}~.
\end{equation}	

