\section{Vaccination on Trees}\label{app:tree_vac}

In this section, we present a vaccination algorithm for trees that we prove to be optimal i.e., it reduces the spectral radius the most for a given vaccination budget $K$. The algorithm is based on the observation that following the removal (i.e., vaccination) of any vertex of a tree, the resulting tree has at least one new connected component. 

% This algorithm works by finding the smallest $\lambda$ such that there exists a set of $k$ vertices $R \subseteq V$ such that $\rho(G[V \setminus R]) \leq \lambda$. It does so by performing a binary search for $\lambda$ in $[0, \sqrt{n-1}]$, calling \Cref{alg:feasibility-check} for each $\lambda$. The optimality of \Cref{alg:feasibility-check} is proven in \Cref{app:vac_opt}.

\paragraph{Algorithm Overview.} Our algorithm, pseudocode given in \cref{alg:tree-vacc}, employs a binary search strategy to identify the smallest possible spectral radius $\lambda_\varepsilon$ achievable by removing at most $K$ vertices from a tree $\T$, up to a precision of $\varepsilon > 0$.

For each candidate value of $\lambda$ during the binary search, we invoke a feasibility check algorithm, pseudocode given in \Cref{alg:feasibility-check}, to determine whether there exists a set of at most $K$ vertices whose removal ensures that the spectral radius of the resulting forest (i.e., disjoint union of trees) does not exceed $\lambda$. \Cref{alg:feasibility-check} operates as follows:
\begin{enumerate}
    \item \textbf{Depth-First Traversal:} The algorithm picks an arbitrary root and recursively explores each subtree in post-order (i.e., children before parent).
    \item \textbf{Vertex Removal:} If a subtree's spectral radius exceeds $\lambda$, the root of that subtree is marked for removal (vaccination), effectively splitting the tree into smaller components.
    \item \textbf{Budget Verification:} After the traversal, if the total number of removed vertices does not exceed $K$, the current $\lambda$ is considered feasible.
\end{enumerate}

Using \Cref{alg:feasibility-check}, we can identify the smallest $\lambda_\varepsilon$ via a binary search procedure conducted within the interval $[0, \sqrt{n-1}]$, leveraging the fact that the spectral radius of a tree is bounded by $\sqrt{n-1}$ \cite{van_mieghem_spec_rad_2011}. The binary search iteratively narrows the range of possible $\lambda$ values by selecting a midpoint and using the feasibility check to determine if the current $\lambda$ is achievable within the vaccination budget. As the domain of $\lambda$ is continuous, we stop the binary search when the interval size is less than a predefined threshold $\varepsilon$.

\begin{algorithm}[t!]
    \caption{Optimal vaccination for a tree}
    \label{alg:tree-vacc}
    \begin{algorithmic}[1]
    \State \textbf{Input:} Tree $\T= (V, E)$, budget $K$, precision $\varepsilon > 0$
    \State \textbf{Output:} Set of vertices to vaccinate $R_\varepsilon$
    \State Initialize $L \gets 0$
    \State Initialize $high \gets \sqrt{|V| - 1}$
    \State Initialize $R_\varepsilon \gets \emptyset$
    \While{$high - low > \varepsilon$}
        \State $mid \gets \frac{low + high}{2}$
        \State (\text{feasible}, $R$) $\gets$ \Call{\cref{alg:feasibility-check}}{$\T$, $K$, $\lambda= mid$}
        \If{feasible}
            \State $high \gets mid$
            \State $R_\varepsilon \gets R$
        \Else
            \State $low \gets mid$
        \EndIf
    \EndWhile
    \State \textbf{Return} $R_\varepsilon$
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[t!]
    \caption{Feasibility checker for tree vaccination}
    \label{alg:feasibility-check}
    \begin{algorithmic}[1]
    \State \textbf{Input:} Tree $\T = (V, E)$, budget $K$, threshold $\lambda$
    \State \textbf{Output:} Feasibility and set of vertices to remove $R$
    \State Choose an arbitrary root vertex $r \in V$
    \State Initialize $R \gets \emptyset$
    \State \Call{DFS}{$\T$, $r$, \texttt{None}, $\lambda$, $R$}
    \If{$|R| \leq k$}
        \State \textbf{Return} True, $R$
    \Else
        \State \textbf{Return} False, $R$
    \EndIf
    \end{algorithmic}

    \hrulefill

    \begin{algorithmic}[1]
    \Function{DFS}{$\T$, $u$, parent, $\lambda$, $R$}
        \State $S \gets \emptyset$
        \For{$v \in \N(u)$}
            \If{$v \neq \text{parent}$}
                \State $S \gets S \cup \Call{DFS}{\T, v, u, \lambda, R}$
            \EndIf
        \EndFor \label{ln:dfs-loop-end}
        \If{$\rho(\T[S]) > \lambda$}
            \State $R \gets R \cup \{u\}$
            \State \textbf{return} $\emptyset$
        \Else
            \State \textbf{return} $S$
        \EndIf
    \EndFunction
    \end{algorithmic}
    \end{algorithm}


\paragraph{Optimality Guarantee.}
Below, we formally state and prove the optimality of \cref{alg:tree-vacc}.
\begin{theorem}
    Given a tree $\T$ and vaccination budget $K$, let $\lambda^* = \rho(\T[V \setminus R^*])$, where $R^*$ is the solution to the optimization problem given in \Cref{eq:opt_vac}, and let $\lambda_\varepsilon = \rho(\T[V \setminus R_\varepsilon])$, where $R_\varepsilon$ is the output of \cref{alg:tree-vacc} with precision parameter $\varepsilon$. Then, $\abs{\lambda^* - \lambda_\varepsilon} \leq \varepsilon$.
\end{theorem}

\begin{proof}
    Proof follows from the correctness and completeness of \cref{alg:feasibility-check}, as detailed in \cref{app:vac_opt}.
\end{proof}

\paragraph{Computational Complexity.}
The worst-case complexity of the algorithm is $\mathcal{O}\left(n^3 \log(\sqrt{n} / \varepsilon)\right)$. The complexity arises from (i) the binary search, which has a complexity of $\mathcal{O}(\log(\sqrt{n} / \varepsilon))$; (ii) the post-order traversal of the tree, which has a complexity of $\mathcal{O}(n)$; and (iii) the spectral radius computation, which has a complexity of $\mathcal{O}(n^2)$ using the Lanczos algorithm for sparse graphs with $\mathcal{O}(n)$ nonzero entries \cite{Lanczos_alg}.

\section{Tree Decomposition}\label{app:tree_decomp}
In this section, we provide a brief introduction to treewidth, tree decompositions, and nice tree decompositions. For more details, we refer the reader to \citet{param_algs}.

\paragraph{Tree decomposition.}
A tree decomposition of a graph $\G$ is a tree with bags of vertices as nodes that captures the connectivity and structure of the graph. Below, we provide a formal definition of a tree decomposition.

\begin{definition} (Tree Decomposition from \citet{param_algs}).
A tree decomposition of $\G$ is a pair $\Td = \left(\T,\left\{X_t\right\}_{t \in V(\T)}\right)$, where $\T$ is a tree whose every node $t$ is assigned a vertex subset $X_t \subseteq V(G)$, called a bag, such that the following three conditions hold:
\begin{itemize}
    \item $\bigcup_{t \in V(\T)} X_t=V(\G)$. In other words, every vertex of $\G$ is in at least one bag.
    \item For every $u,v \in E(\G)$, there exists a node $t$ of $\T$ such that bag $X_t$ contains both $u$ and $v$.
    \item For every $u \in V(\G)$, the set $\T_u=\left\{t \in V(\T): u \in X_t\right\}$, i.e., the set of nodes whose corresponding bags contain $u$, induces a connected subtree of $\T$.
\end{itemize}
\end{definition}

The width of tree decomposition $\Td$ equals $\max _{t \in V(\T)}\left|X_t\right|-1$, that is, the maximum size of its bag minus $1$. Notice that a trivial tree decomposition is formed by a single node with the entire vertex set of the graph as its bag, resulting in a width of $n -1$.

\paragraph{Treewidth.}
Then, the treewidth of an undirected graph $\G$, denoted by $\tw(\G)$, is the minimum width of any tree decomposition of $\G$. Intuitively, the treewidth of an undirected graph $\G$ is a measure of its tree-likeness (treewidth of a tree is $1$, hence the minus $1$ in the definition). It is a very important concept used in parametrized algorithms and complexity theory, where many NP-hard problems, such as the Hamiltonian path problem, Steiner tree problem, and many others \cite{treewidth_singl_exp}, become tractable on graphs of bounded treewidth.

For a general graph, an upper bound on the treewidth is the number of vertices. However, for many real-world graphs, the treewidth is much smaller than that, making it a useful parameter for designing efficient algorithms.

\paragraph{Nice tree decomposition.}
A nice tree decomposition is a tree decomposition that is easy to write dynamic programming algorithms on. It is formally defined below.

\begin{definition} (Nice tree decomposition from \citet{param_algs}).
    A rooted tree decomposition $\Td = \left(\T,\left\{X_t\right\}_{t \in V(\T)}\right)$ with root $r \in \T$ is \textit{nice} if $X_r=\emptyset$ and every node of $\T$ is of one of the following four types:
    % add leaf node as a node for the sake of consistency
    \begin{itemize}
    \item \textbf{Leaf node}: a node $t$ that has no children and has $X_{t}=\emptyset$.
        \item \textbf{Introduce node}: a node $t$ with exactly one child $t^{\prime}$ such that $X_t=$ $X_{t^{\prime}} \cup\{v\}$ for some vertex $v \notin X_{t^{\prime}}$; we say that $v$ is introduced at $t$.
        \item \textbf{Forget node}: a node $t$ with exactly one child $t^{\prime}$ such that $X_t=X_{t^{\prime}} \backslash\{w\}$ for some vertex $w \in X_{t^{\prime}}$; we say that $w$ is forgotten at $t$.
        \item \textbf{Join node}: a node $t$ with two children $t_1, t_2$ such that $X_t=X_{t_1}=X_{t_2}$.
    \end{itemize}
\end{definition}

Working with nice tree decompositions simplifies the design of dynamic programming algorithms, due to limited types of nodes. The following lemma shows that every tree decomposition can be converted to a nice tree decomposition without increasing the width and in polynomial time.

\begin{lemma} (Lemma 7.4 of \citet{param_algs}).
    \label{lem:nice_tree_decomp}
    If a graph $\G$ admits a tree decomposition of width at most $\omega$, then it also admits a nice tree decomposition of width at most $\omega$. Moreover, given a tree decomposition $\left(\T,\left\{X_t\right\}_{t \in V(\T)}\right)$ of $\G$ of width at most $\omega$, one can in time $\mathcal{O}\left(\omega^2 \cdot \max (|V(\T)|,|V(\G)|)\right)$ compute a nice tree decomposition of $\G$ of width at most $\omega$ that has at most $\mathcal{O}(\omega|V(\G)|)$ nodes.
\end{lemma}

\section{Additional Proofs}\label{app:proofs}
\subsection{Coupling between Processes $\{Y^{(t)}\}$ and $\{\Psi^{(t)}\}$} \label{app:coupling}
The transition probabilites of $\{Y^{(t)}\}_{t \in T_D}$ are governed by the infection and recovery probabilities as described in \Cref{sec:SIS_model}. If the chain is in the all zero state, it will remain in that state forever; i.e., $\mathbb{P}(Y^{(t)} = \underline{0} \mid Y^{(t-1)} = \underline{0}) = 1$.

For the modified SIS process $\{\Psi^{(t)}\}_{t \in T_D}$, we define the transition probabilities as follows:
\begin{equation*}
    \mathbb{P}(\Psi^{(t)} = \psi^{\prime \prime} \mid \Psi^{(t-1)} = \psi^\prime) = \begin{cases}
        \mathbb{P}(Y^{(t)} = \psi^{\prime \prime} \mid Y^{(t-1)} = \psi^\prime), & \text{if }  \psi^\prime \neq \underline{0}, \\
        (\initp)^{\norm{\psi^{\prime\prime}}}(1-\initp)^{n- \norm{\psi^{\prime\prime}}} & \text{otherwise,}
    \end{cases}
\end{equation*}

where $\norm{\psi} = \sum_{i=1}^{n} \psi_i$ denote the number of $1$-elements in a $n$-dimensional vector $\psi \in \{0,1\}^{n}$. 

Clearly, the processes $\{Y^{(t)}\}_{t \in T_D}$ and $\{\Psi^{(t)}\}_{t \in T_D}$ can be coupled until the first time $t_0$ when $Y^{(t_0)} =  \Psi^{(t_0)} = \underline{0}$, at which point process $Y$ goes extict and process $\Psi$ restarts.

\subsection{Concentration Inequality}
Here we state the concentration inequality for the modified SIS Markov chain $\{\Psi^{(t)}\}$ that we use to provide error bounds on the learning algorithm. 

\begin{lemma} \label{lm:replacement_CIneq}
    Let $\{\Psi^{(t)}\}_{t \in T_D}$ be observations from the SIS process, where $T_D$ is a set of (not necessarily consecutive) time indices and $\Psi^{(t)} \in \{0,1\}^V$. Under \Cref{as:stability_assumption}, for any subset $U \subseteq V$, any state $\psi_U \in \{0,1\}^{|U|}$, and any $\varepsilon, \delta > 0$, the following deviation bound holds for the unbiased estimator:
    $$
    \mathbb{P}\left(\left| \mathbb{P}(\Psi_U = \psi_U) - \hat{\mathbb{P}}(\Psi_U = \psi_U) \right| \geq \varepsilon \right) \leq \delta,
    $$
    whenever $|T_D| \geq \frac{2\log(2 / \delta)}{\varepsilon^2 (1-\theta)^2}$, where $0 < \theta < 1$ is a constant depending on the graph structure but independent of $T$. 

    Here, $\mathbb{P}(\Psi_U = \psi_U)$ denotes the true probability (e.g., under the stationary distribution), and $\hat{\mathbb{P}}(\Psi_U = \psi_U) = \varphi_U$ is the empirical estimate over $T = |T_D|$ samples.
\end{lemma}

\begin{proof}
Let $\mathcal{S} = \{0,1\}^V$ be the state space of Markov chain $\{\Psi^{(t)}\}$ with transition probability $p(\psi^{\prime\prime}|\psi^\prime)$ from state $\psi^\prime \in S$ to state $\psi^{\prime\prime} \in S$. Let $T = |T_D|$ be the number of observations and let $\mathcal{S}^T$ be the product state space of these $T$ observations. By definition, the process $\{\Psi^{(t)}\}_{t \in \mathbb{N}} $ has the Markov property in time, hence so does a sub-sequence $\{\Psi^{(t)}\}_{t \in T_D}$.
We further define $\varphi_U:\mathcal{S}^T \rightarrow \mathbb{R}$ as
\begin{equation*}
    \varphi_U(\Psi^{(1)}, \dots, \Psi^{(T)}) = \frac{1}{T} \sum_{t=1}^{T} \1 \{\Psi_U^{(t)} = \psi_U\}. 
\end{equation*}
Notice that the function above is $c$-Lipschitz with respect to the Hamming metric $d(U,W) = \sum_{t=1}^T \1 \{U^{(t)} \neq W^{(t)}\}$ on $\mathcal{S}^T$, with Lipschitz constant $c = 1/T$.

We are now ready to apply Theorem 1.2 from \citet{leonid_aryeh_kontorovich_concentration_2008} for Markov chains. The theorem states that for a $c$-Lipschitz function $\varphi$ on $\mathcal{S}^n$,
\begin{equation*}
    \mathbb{P}\{|\varphi-\E{\varphi}| \geq t\} \leq 2 \exp \left(-\frac{t^2}{2 n c^2 M_n^2}\right).
\end{equation*}
In our case, the sequence length is $T$ (replacing $n$ in the theorem) and $c=1/T$. The relevant $M_n$ term becomes $M_T$. The bound becomes
\begin{equation*}
    \mathbb{P}\{|\varphi_U-\E{\varphi_U}| \geq t\} \leq 2 \exp \left(-\frac{t^2}{2 T (1/T)^2 M_T^2}\right) = 2 \exp \left(-\frac{T t^2}{2 M_T^2}\right),
\end{equation*}

where $M_T = (1-\theta^T)/(1- \theta)$ and $\theta$ is the Markov contraction coefficient given by 
\begin{equation*}
    \theta = \sup_{\psi^{\prime}, \psi^{\prime \prime} \in \mathcal{S}} \left\|p\left(\cdot \mid \psi^{\prime}\right)-p\left(\cdot \mid \psi^{\prime \prime}\right)\right\|_{\mathrm{TV}}.
\end{equation*}

We have $\theta <1$ because every configuration $\psi$ can transfer into the all-zero configuration $\underline{0}$. Hence, for any two states $\psi^{\prime}, \psi^{\prime \prime} \in \mathcal{S}$ both $p(\underline{0}|\psi^{\prime})>0$ and $p(\underline{0}|\psi^{\prime \prime})>0$ and the support of $p(\cdot|\psi^{\prime})$ and $p(\cdot|\psi^{\prime \prime})$ is not disjoint, which implies $\theta <1$.

We write $M_T \leq 1/(1-\theta)$ and the probability bound becomes
\begin{equation*}
    \mathbb{P}\{|\varphi_U-\E{\varphi_U}| \geq t\} \leq 2 \exp\left(-\frac{T t^2 (1-\theta)^2}{2}\right).
\end{equation*}
To ensure this probability is at most $\delta$ for a deviation $t=\varepsilon$, we get
\begin{equation*}
    2 \exp\left(-\frac{T \varepsilon^2 (1-\theta)^2}{2}\right) \leq \delta
\end{equation*}
Finally, solving for $T$ yields the desired condition
\begin{equation*}
    T \geq \frac{2\log(2 / \delta)}{\varepsilon^2 (1-\theta)^2}.
\end{equation*}

\end{proof}


