\begin{proof}
        Consider an SIS process $\left(Y^{(t)}\right)_{t \in \mathbb{N}}$ at an arbitrary time $t$ with infection probability $\infp$ and let $i,j \in V$ be neighboring vertices. Let $\norm{y} = \sum_{i=1}^{|\mathcal{N}(j)|-1} y_i$ denote the number of $1$-elements in a $\left(|\mathcal{N}(j)|-1\right)$-dimensional vector $y \in \{0,1\}^{|\mathcal{N}(j)|-1}$. Then 
    \begin{align*}
        \mu_{j|i}\t &= \mathbb{P}\left(Y^{(t+1)}_j = 1 | Y_j^{(t)}=0, Y_i^{(t)}=1\right) \\
        &\stackrel{(a)}{=} \sum_{y \in \{0,1\}^{|\mathcal{N}(j)|-1}} \mathbb{P}\left(Y^{(t+1)}_j = 1 | Y_j^{(t)}=0, Y_i^{(t)}=1, Y_{\mathcal{N}(j) \setminus \{i\}}^{(t)} = y\right) \cdot \mathbb{P}\left(Y_{\mathcal{N}(j) \setminus \{i\}}^{(t)} = y| Y_j^{(t)}=0, Y_i^{(t)}=1\right) \\
        &\stackrel{(b)}{=} \sum_{y \in \{0,1\}^{\abs{\mathcal{N}(j)}-1}} \left(1 - (1- \infp)^{\norm{y}+1} \right) \cdot \mathbb{P}\left(Y_{\mathcal{N}(j) \setminus \{i\}}^{(t)} = y| Y_j^{(t)}=0, Y_i^{(t)}=1\right) \stackrel{(c)}{\geq} \infp
    \end{align*}
    where $(a)$ is obtained by the law of total probability and $(b)$ by the definition of the SIS process. If the whole neighborhood of $j$ and the state of $j$ is known at time $t$, the transition probability of $Y_j\t$ from state zero at time $t$ to state one at $t+1$, is given by $1 - (1- \infp)^{\norm{y}+1}$. That is, we know $Y_j\t=0$, $Y_i\t=1$ and $Y_{\mathcal{N}(j) \setminus \{i\}}\t=y$. Hence, the number of infected vertices $\norm{y}$ and $i$ contribute to the probability of vertex $j$ being infected in the next round. Finally, $(c)$ is obtained by lower bounding $1 - (1- \infp)^{\norm{y}+1} \geq \infp$ and by normalization:
    \begin{equation*}
         \sum_{y \in \{0,1\}^{\abs{\mathcal{N}(j)}-1}} \mathbb{P}\left(Y_{\mathcal{N}(j) \setminus \{i\}}^{(t)} = y| Y_j^{(t)}=0, Y_i^{(t)}=1\right) =1.
    \end{equation*}
\end{proof}


\CondInfMarkov*
\begin{proof}
    Consider an arbitrary time $t$, vertices $j,k \in V$, $j$ and $k$ non-neighbors, $S \subseteq V \setminus \{j,k\}$ such that $\mathcal{N}(j) \subseteq S$ and a vector $y_S \in \{0,1\}^{|S|}$. We note that $S$ separates $j$ and $k$, i.e., any path between $j$ and $k$ passes through set $S$. Then by the local Markov property of the model (the probability of a vertex $j$ transitioning from the zero state to the one state only depends on the state of $j$ and its neighbors in the previous round) the evolution of $j$ is conditionally independent of $k$ and we write explicitly:
    \begin{align}
    \nu_{j|k, y_S}^t &= \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0, Y_k^{(t)}=1, Y^{(t)}_S = y_S \right) - \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0, Y_k^{(t)}=0, Y^{(t)}_S=y_S\right) \nonumber\\
    &= \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0,  Y^{(t)}_{\mathcal{N}(j)}= y_{\mathcal{N}(j)}, Y_k^{(t)}=1,  Y^{(t)}_{S \setminus \mathcal{N}(j)} = y_{S \setminus \mathcal{N}(j)} \right) \nonumber\\
    &\ \ \ - \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0,  Y^{(t)}_{\mathcal{N}(j)}= y_{\mathcal{N}(j)}, Y_k^{(t)}=0, Y^{(t)}_{S \setminus \mathcal{N}(j)} = y_{S \setminus \mathcal{N}(j)} \right) \nonumber\\
    &= \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0,  Y^{(t)}_{\mathcal{N}(j)}= y_{\mathcal{N}(j)} \right) - \mathbb{P}\left(Y_j^{(t+1)}=1 | Y_j^{(t)}=0,  Y^{(t)}_{\mathcal{N}(j)}= y_{\mathcal{N}(j)} \right) \label{eq:lem_nu_markov}\\
    &=0, \nonumber
\end{align}
where $\eqref{eq:lem_nu_markov}$ follows from the aforementioned Markov property.
\end{proof}

