We will once again use \Cref{lm:replacement_CIneq}. Under \Cref{as:stability_assumption} let $i \neq j \in V$, $S \subseteq V \setminus \{i,j\}$, $\delta, \varepsilon >0$, $\psi_S \in \{0,1\}^{\abs{S}}$, $m^+ = I(\Psi_j=0, \Psi_i =1, \psi_S)$, $m^- = I(\Psi_j=0, \Psi_i =0, \psi_S)$, and $ \min \{m^+ ,m^- \} \geq \frac{2}{\varepsilon^2(1-\theta)^2}\log(2/\delta)$. We define 
\begin{align*}
    \varphi^+ := \Pp{\Psi^{(\cdot+1)}_j =1| \Psi_j^{(\cdot)}=0, \Psi_i^{(\cdot)}= 1, \Psi^{(\cdot)}_S = \psi_S}
    \quad \text{and} \quad
    \varphi^- := \Pp{\Psi^{(\cdot+1)}_j =1| \Psi_j^{(\cdot)}=0, \Psi_i^{(\cdot)}= 0, \Psi^{(\cdot)}_S = \psi_S}.
\end{align*}
Then, let $\hat\varphi^+$ and $\hat\varphi^-$ be their estimators, respectively. That is,
\begin{align*}
    \hat\varphi^+ &:= \Phat{\Psi^{(\cdot+1)}_j =1| \Psi_j^{(\cdot)}=0, \Psi_i^{(\cdot)}= 1, \Psi^{(\cdot)}_S = \psi_S}, \\
    \hat\varphi^- &:= \Phat{\Psi^{(\cdot+1)}_j =1| \Psi_j^{(\cdot)}=0, \Psi_i^{(\cdot)}= 0, \Psi^{(\cdot)}_S = \psi_S}.
\end{align*}

Then, define $S_m^+$ and $S_m^-$ as
\begin{align*}
        S_m^+ &= \sum_{r \in \mathcal{I}(\Psi_j=0, \Psi_i=1 , \psi_S)} \1 \{\Psi^{(r+1)}_j =1 \}, \\
        S_m^- &= \sum_{r \in \mathcal{I}(\Psi_j=0, \Psi_i=0 , \psi_S)} \1 \{\Psi^{(r+1)}_j =1 \}.
\end{align*}
The expectation of the estimators is given by:
\begin{align*}
        \E{S_m^+} = m^+\varphi^+ \quad \text{and} \quad \E{S_m^-} = m^-\varphi^-.
\end{align*}

By application of \Cref{lm:replacement_CIneq}:
\begin{equation}
    \Pp{\abs{\varphi^+ - \hat\varphi^+}\geq \varepsilon} \leq \delta. \label{eq:bdconf_phi+}
\end{equation}
Similarly,
\begin{equation}
    \Pp{\abs{\varphi^- - \hat\varphi^-}\geq \varepsilon } \leq \delta. \label{eq:bdconf_phi-}
\end{equation}

Now, writing $\nu_{j|i,\psi_S}$ and $\hat{\nu}_{j|i,\psi_S}$ using $\varphi^+$ and $\varphi^-$, the triangle inequality implies that
\begin{align*}
    \left| \nu_{j|i,\psi_S} - \hat{\nu}_{j|i,\psi_S}\right|
    &= \left| \varphi^+ - \varphi^- -( \hat{\varphi}^+ - \hat\varphi^-) \right| \\
    &\leq \left| \varphi^+ - \hat\varphi^+\right| + \left|\hat{\varphi}^- - \varphi^- \right|.
\end{align*}

Combining the above,
\begin{align}
    &\Pp{\left| \nu_{j|i,\psi_S} - \hat{\nu}_{j|i,\psi_S}\right| < 2\varepsilon} \nonumber\\
    &\geq \mathbb{P}\Bigl( \left| \varphi^+ - \hat\varphi^+\right|  + \left|\hat{\varphi}^- - \varphi^- \right| < 2\varepsilon \Bigr) \nonumber \\
    &\geq \mathbb{P}\Bigl( \{\left| \varphi^+ - \hat\varphi^+\right|< \varepsilon\} \cap \{\left|\hat{\varphi}^- - \varphi^- \right| < \varepsilon\}\Bigr) \label{eq:bdconf_int}\\
    &\geq 1 - \Pp{\{\left| \varphi^+ - \hat\varphi^+\right|\geq \varepsilon\}} - \Pp{\{\left|\hat\varphi^- - \varphi^-\right|\geq \varepsilon\}} \label{eq:bdconf_union}\\
    &\geq 1 - 2 \delta, \label{eq:bdconf_finalres}
\end{align}
where in \eqref{eq:bdconf_int} we have used the intersection of events property, in \eqref{eq:bdconf_union} we have used the union bound, and in \eqref{eq:bdconf_finalres} we have used \eqref{eq:bdconf_phi+} and \eqref{eq:bdconf_phi-}.

Finally, taking the complement, we get 
    $\Pp{\left| \nu_{j|i,\psi_S} - \hat{\nu}_{j|i,\psi_S}\right| \geq 2\varepsilon} \leq 2\delta$
as desired.
\end{proof}



Lemmas \ref{lm:error_bd_dir_inf} and \ref{lm:error_bd_cond_inf} establish concentration for individual estimators $\hat{\mu}_{j|i}$ and $\hat{\nu}_{j|i,\psi_S}$ (for a specific configuration $\psi_S$). For our learning algorithm \texttt{SISLearn} (\Cref{alg:learn_graph}) to succeed, we need these estimates to be accurate simultaneously across all relevant $i,j,S,$ and respective configurations $\psi^*_S$. We thus define the event $\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)$ that captures this joint accuracy:
\begin{align*}
    \mathcal{A}( \varepsilon_\nu, \varepsilon_\mu) = \Bigg\{ & \left( \forall i \neq j \in V: |\mu_{j|i} - \hat{\mu}_{j|i}| \leq\varepsilon_\mu \right) \text{ and } \\ 
    & \left( \forall i \neq j \in V, \forall S \subseteq V \setminus \{i,j\} \text{ s.t. for each respective } \psi_S^* : |\nu_{j|i,\psi^*_S} - \hat{\nu}_{j|i,\psi^*_S}| \leq \varepsilon_\nu \right) \Bigg\},
\end{align*}
where, as a reminder, $\psi^*_{S}(i,j)$, or $\psi_S^*$ when clear from context, is defined as
\begin{align*}
    \psi^*_{S}(i,j) \coloneq \argmax_{\psi \in \{0,1\}^{\abs{S} - 1}} \min \Big( I(\Psi_j^{(t)}=0, \Psi_i^{(t)}=1, \Psi_{S \setminus \{i\}}^{(t)}= \psi),
    I(\Psi_j^{(t)}=0, \Psi_i^{(t)}=0, \Psi_{S \setminus \{i\}}^{(t)}= \psi) \Big).
\end{align*}
The following lemma provides the sample complexity conditions under which this joint event $\mathcal{A}$ holds with given probability.

\begin{restatable}{lemma}{BdA} \label{lm:A_bd}
    Under \Cref{as:stability_assumption}, if for every $i \neq j \in V$, every $S \subseteq V \setminus \{i,j\}$, and every configuration $\psi_i, \psi_j \in \{0,1\}$, the number of observations $I(\Psi_i=\psi_i, \Psi_j=\psi_j, \Psi_S=\psi^*_S(i,j))$ is at least $m_{min}$, where 
    $$ m_{min} = \frac{2}{(1-\theta)^2(\min\{\varepsilon_\nu/2, \varepsilon_\mu\})^2} \log \left(\frac{2n^2(1 +2^{n-1})}{\zeta}\right),$$
    then $\mathbb{P}(\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)) \geq 1- \zeta$.
\end{restatable}

\begin{proof}
    Under \Cref{as:stability_assumption}, assume that for all $i \neq j \in V, S \subseteq V \setminus \{i,j\}$, $\psi_i, \psi_j \in \{0,1\}, \text{ and the respective } \psi^*_S(i,j)$, $I(\Psi_i=\psi_i, \Psi_j=\psi_j, \Psi_S=\psi^*_S(i,j))\geq \frac{2}{(1-\theta)^2(\min\{\frac{\varepsilon_\nu}{2}, \varepsilon_\mu\})^2} \log \left(\frac{2n^2(1 +2^{n-1})}{\zeta}\right)$.
Then, we write using a union bound
\begin{align*}
    &\Pp{\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)}  \\
    &= 1- \Pp{\exists \{i,j\} \subset V, S \subset V \setminus \{i,j\} \text{ such that for }  \psi^*_S,  |\nu_{j|i,\psi^*_S} - \hat{\nu}_{j|i,\psi^*_S}| > \varepsilon_\nu\text{ or } |\mu_{j|i} - \hat{\mu}_{j|i}| > \varepsilon_\mu} \\
    &\geq 1 - \Pp{ \bigcup_{\substack{i,j \in V \\ S \subseteq V \setminus \{i,j\}}}  \left\{|\nu_{j|i,\psi^*_S} - \hat{\nu}_{j|i,\psi^*_S}| > \varepsilon_\nu \right\} \cup \bigcup_{\substack{i,j \in V}}  \left\{|\mu_{j|i} - \hat{\mu}_{j|i}| > \varepsilon_\mu \right\}}\\
    &\geq 1 - \sum_{\substack{i,j \in V \\ S \subseteq V \setminus \{i,j\}}}  \Pp{|\nu_{j|i,\psi^*_S} - \hat{\nu}_{j|i,\psi^*_S}| > \varepsilon_\nu} - \sum_{\substack{i,j \in V}}  \Pp{|\mu_{j|i} - \hat{\mu}_{j|i}| > \varepsilon_\mu}.
\end{align*}

The number of pairs $(i,j)$ in $V$ can be upper bounded by $n^2$ while the number all conditioning sets $S \subseteq V \setminus \{i,j\}$ is equal to $\sum_{k=1}^{n-2} \binom{n-2}{k} \leq 2^{n -2}$. Let $m = \min_{i,j \in V, S \subseteq V \setminus \{i,j\}}\{I(\Psi_i=\psi_i, \Psi_j=\psi_j, \Psi_S=\psi^*_S)\}$.
We obtain therefore from \cref{lm:error_bd_dir_inf} and \cref{lm:error_bd_cond_inf} that for $m \geq 2\log(2/\delta)/((1-\theta)^2(\min\{\varepsilon_\nu/2, \varepsilon_\mu\})^2)$

\begin{align*}
    \Pp{\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)} \geq 1 - n^22^{n-2}(2\delta) - n^2\delta.
\end{align*}

Now, since we assumed $m$ satisfies $m \geq \frac{2}{(1-\theta)^2(\min\{\frac{\varepsilon_\nu}{2}, \varepsilon_\mu\})^2} \log \left(\frac{2n^2(1 +2^{n-1})}{\zeta}\right)$, we can substitute $\zeta = \delta n^2(1 + 2^{n-1})$, yielding $\Pp{\mathcal{A}( \varepsilon_\nu, \varepsilon_\mu)} \geq 1 - \zeta$.
\end{proof}

\LearnAlgoB*

\begin{proof} Assume that for all $i \neq j \in V, S \subseteq V \setminus \{i,j\}$, $\psi_i, \psi_j \in \{0,1\}, \text{ and each respective } \psi^*_S(i,j)$ and under \Cref{as:stability_assumption}, 
$$
I\bigl(\Psi_i = \psi_i,\; \Psi_j = \psi_j,\; \Psi_S = \psi^*_S\bigr)
\geq \frac{2}{(1- \theta)^2(\min \{\varepsilon_\nu/2,\varepsilon_\mu\})^2}
\log \left(\frac{2n^2(1 +2^{n-1})}{\zeta}\right)
$$
and $\varepsilon_\nu < \infp(1- \infp)^{\Delta -1}/2$.  
Then, by \Cref{lm:A_bd}, $\Pp{\mathcal{A}( \varepsilon_\nu, \varepsilon_\mu)} \geq 1 - \zeta$. For the remainder of the proof we will assume that $\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)$ holds.

We will show that the algorithm learns the neighborhoods of all vertices correctly one after the other. As the outer for-loop (Line \ref{ln:outer_for_start}–\ref{ln:outer_for_end}) iterates over all vertices in $V$, it suffices to show that the algorithm correctly learns the neighborhood of an arbitrary vertex $j \in V$. To do so, we will show that after the inclusion for-loop (Line \ref{ln:inc_for_start}–\ref{ln:inc_for_end}), $S$ is a superset of the neighborhood of $j$, and that in the exclusion for-loop (Line \ref{ln:exc_for_start}–\ref{ln:exc_for_end}), all neighbors remain in $S$ while all non-neighbors get removed.

\paragraph{Inclusion Loop.}
By \cref{lm:dir_inf_lw_bd}, if $i$ is a neighbor of $j$, then $\mu_{j|i} \geq \infp$. Hence, conditioned on $\mathcal{A}$ being true, $\abs{\hat{\mu}_{j|i}- {\mu}_{j|i}} \leq \varepsilon_\mu$, and $\hat{\mu}_{j|i} \geq \infp - \varepsilon_\mu$. Therefore, after the inclusion loop, the set $S$ contains at least all neighbors of $j$, i.e., $S \supseteq \mathcal{N}(j)$.

\paragraph{Exclusion Loop.}
We first establish that no neighboring vertex of $j$ can be removed from $S$ in the exclusion for-loop and next show that all non-neighboring vertices of $j$ are removed from $S$.

Suppose, for the sake of contradiction, that at least one neighboring vertex of $j$ is removed in the exclusion for-loop, say $i$. As shown earlier, $S \supseteq \mathcal{N}(j)$, hence the conditions for \cref{cor:Sepehr_corollary} are satisfied. As we have also conditioned on $\mathcal{A}( \varepsilon_\nu, \varepsilon_\mu)$, \cref{cor:Sepehr_corollary}, which holds for any $\psi_S$, yields
$$
\hat{\nu}_{j|i, \psi^*_{S \setminus \{i\}}}
\geq \infp(1- \infp)^{\Delta -1} - \varepsilon_\nu.
$$
This inequality contradicts the exclusion criterion in Line \ref{ln:exclusion_cond} and thus $i$ cannot be removed from $S$. Hence, no neighboring vertex can be removed by the exclusion loop.

Finally, we know by \Cref{lm:cond_inf_markov} and $\mathcal{A}(\varepsilon_\nu, \varepsilon_\mu)$ that if $i \notin \mathcal{N}(j)$, then
$$
\hat{\nu}_{j|i, \psi^*_{S \setminus \{i\}}} \leq \varepsilon_\nu.
$$
We have assumed that $\varepsilon_\nu < \infp(1- \infp)^{\Delta -1}/2$. Hence,
$$
\hat{\nu}_{j|i, \psi^*_{S \setminus \{i\}}}
\leq \infp(1- \infp)^{\Delta -1} - \varepsilon_\nu,
$$
and so any non-neighboring vertex gets removed.

Thus, after the exclusion for-loop, we have $S = \mathcal{N}(j)$ and the algorithm correctly learns the neighborhood of $j$. Since the outer for-loop iterates over all vertices in $V$, conditioned on $\mathcal{A}$, which occurs with probability at least $1 - \zeta$, the algorithm learns the neighborhood of every vertex in $V$ correctly.
\end{proof}

\subsection{Vaccination Results}
\subsubsection{Extinction Time of Discrete SIS Process}
\label{app:ext_time}
In this section, we state and prove results relating the extinction time of a discrete SIS process to the spectral radius of the underlying graph. This result was first empirically established by \citet{wang_epidemic_2003}, and formally stated and proven for the discrete-time SIS model as defined in \cref{sec:SIS_model} by \citet{sis_ub_2016}.

\begin{lemma}\label{lem:num_infected}
    Given a discrete SIS model with initial infection probability $p_\text{init}$, infection probability $\infp$, recovery probability $\healp$, and spreading on graph $\G$ with $n$ vertices and adjacency matrix $\mathbf{A}$, we have that the expected number of infected vertices at time $t$, denoted by $\mathbb{E}[Z^t]$, is upper bounded by $\initp \left(1 - \healp + \infp \rho(\mathbf{A})\right)^tn$.
\end{lemma}

\begin{proof}
    Denoting the infection probability of vertex $i$ at time $t+1$ by $p_i\tp \coloneqq \Pp{Y_i\tp = 1}$, we have
    \begin{align}
    p_i\tp = (1 - \healp) \cdot p_i\t + \mathbb{E}_{\{Y_j\}_{j \in \N(i)}}\left[1 - \prod_{j \in \N(i)}\left(1 - \infp \cdot Y_j\t\right)\right] \cdot \left(1 - p_i\t\right), \label{eq:marginal_exact}
    \end{align}
    where the first term of the sum is the probability of staying infected, and the second term is the probability of getting infected. We can then bound the product term by using the union bound to get
    \begin{align*}
        \E{1 - \prod_{j \in \N(i)}\left(1 - \infp \cdot Y_j\t\right)} &\leq \E{\sum_{j \in \N(i)} \infp \cdot Y_j\t} \\
        &= \sum_{j \in \N(i)} \infp \cdot \E{Y_j\t} \\
        &= \sum_{j \in \N(i)} \infp \cdot p_j\t.
    \end{align*}
    Substituting this into \Cref{eq:marginal_exact}, we get
    $$
    p_i\tp \leq (1 - \healp) \cdot p_i\t + \infp \cdot \sum_{j \in \N(i)} p_j\t \cdot (1 - p_i\t).
    $$
    Since $0 \leq (1 - p_i\t) \leq 1$, we further bound the expression by:
    $$
    p_i\tp \leq (1 - \healp) \cdot p_i\t + \infp \cdot \sum_{j \in \N(i)} p_j\t.
    $$
    Now, let $\mathbf{p}^t = [p_1^t, p_2^t, \ldots, p_n^t]^\top$ represent the vector of infection probabilities at time $t$. The above inequality can be written in matrix form as
    \begin{align*}
        \mathbf{p}^{t+1} &\leq (1 - \healp) \cdot \mathbf{p}^t + \infp \cdot \mathbf{A} \mathbf{p}^t \\
        &= \left[(1 - \healp) \mathbf{I} + \infp \mathbf{A}\right] \mathbf{p}^t \\
        &= \mathbf{M} \mathbf{p}^t,
    \end{align*}
    where $I$ is the $n \times n$ identity matrix and $\mathbf{M} = (1 - \healp) I + \infp \mathbf{A}$ is the transition matrix. Then, by recursively applying the inequality, we obtain
    $$
    \mathbf{p}^{t} \leq \mathbf{M}^{t} \mathbf{p}^0,
    $$
    where $\mathbf{p}^0$ is the initial infection probability vector, given by $\mathbf{p}^0 = [p_\text{init}, p_\text{init}, \ldots, p_\text{init}]^\top$.
    The spectral radius of matrix $\mathbf{M}$, denoted by $\rho(\mathbf{M})$, is given by:
    $$
    \rho(\mathbf{M}) = (1 - \healp) + \infp \rho(A),
    $$
    where $\rho(\mathbf{A})$ is the spectral radius of the adjacency matrix $\mathbf{A}$. Now, we can write the expected number of infected vertices at time $t$ as
    \begin{align*}
        \mathbb{E}[Z^t] &= \sum_{i=1}^n \mathbb{E}[Y_i^t]\\
        &= \sum_{i=1}^n p_i\t \\
        &= \| \mathbf{p}^t \|_1 \\
        &\leq \sqrt{n} \| \mathbf{p}^t \|_2,
    \end{align*}
    where the last inequality follows from the Cauchy-Schwarz inequality. Substituting the bound on $\mathbf{p}^t$ into the above expression, we obtain
    \begin{align*}
        \mathbb{E}[Z^t] &\leq \sqrt{n} \| \mathbf{M}^t \mathbf{p}^0 \|_2 \\
        &\leq \sqrt{n} \rho(\mathbf{M})^t \| \mathbf{p}^0 \|_2,
    \end{align*}
    where the last inequality follows from $M$ being a symmetric matrix. Simplifying further and substituting in the value of $\rho(\mathbf{M})$, we obtain $\mathbb{E}[Z^t] \leq \left(1 - \healp + \infp \rho(\mathbf{A})\right)^t n p_\text{init}$, as desired.
\end{proof}

\ThmSIS*

\begin{proof}
    We first define $t' \coloneqq \arginf_t \{\mathbb{E}[Z^{t}] \leq 1/n\}$ as the first round $t$ such that $\mathbb{E}[Z^{t}] \leq 1/n$. Then, using the upper bound from \Cref{lem:num_infected}, and assuming that $\rho(\mathbf{A}) < \healp / \infp$, we have that if $t' = \ceil{-\log(\initp n^2) / \log(\rho(\mathbf{M}))}$, then $\mathbb{E}[Z^{t'}] \leq \rho(\mathbf{M})^{t'} n p_\text{init} \leq 1/n$. Then, we can write the expected extinction time as
    \begin{align*}
        \mathbb{E}[\tau] &= \E{\sum_{t=1}^{\infty} \indic{Z^t \geq 1}} \\
        &= \sum_{t=1}^{\infty} \Pp {Z^t \geq 1} \\
        &= \sum_{t=1}^{t'} \Pp{Z^t \geq 1} + \sum_{t=t'+1}^{\infty} \Pp{Z^t \geq 1} \\
        &\leq t' + \sum_{t=t'+1}^{\infty} \Pp{Z^t \geq 1}.
    \end{align*}
    Now, we will show that the second term in the above expression goes to zero asymptotically and we will be done. To do so, we will apply Markov's inequality and \Cref{lem:num_infected} to obtain
    \begin{align*}
        \sum_{t=t'+1}^{\infty} \Pp{Z^t \geq 1} &\leq \sum_{t=t'+1}^{\infty} \mathbb{E}[Z^t] \\
        &\leq \sum_{t=t'+1}^{\infty} \initp \rho(\mathbf{M})^t n.
    \end{align*}
    Using the definition of $t'$, we have that
    \begin{align*}
        \sum_{t=t'+1}^{\infty} \Pp{Z^t \geq 1} &\leq \sum_{k=1}^{\infty} \initp \rho(\mathbf{M})^{t'+k} n\\
        &= \sum_{k=1}^{\infty} \left(\initp \rho(\mathbf{M})^{t'} n\right) \rho(\mathbf{M})^k\\
        &\leq \frac{1}{n} \sum_{k=1}^{\infty} \rho(\mathbf{M})^k \\
        &= \frac{1}{n} \frac{\rho(\mathbf{M})}{1 - \rho(\mathbf{M})},
    \end{align*}
    where in the last line we have used the fact that $\abs{\rho(\mathbf{M})} < 1$. Finally, we have that the expected extinction time is upper bounded by
    \begin{align*}
        \mathbb{E}[\tau] &\leq \ceil*{-\frac{\log(\initp n^2)} {\log(\rho(\mathbf{M}))}} + \frac{1}{n} \frac{\rho(\mathbf{M})}{1 - \rho(\mathbf{M})} \\
        &\backsim \mathcal{O}(\log n).
    \end{align*}
\end{proof}

\subsubsection{Optimality of \Cref{alg:dp_alg}}
\label{app:dp_opt_proof}
Here, we state and prove the optimality of \Cref{alg:dp_alg}.

\begin{theorem}
    Given a graph $\G$ and vaccination budget $K$, let $\lambda^* = \rho(\G[V \setminus R^*])$, where $R^*$ is the solution to the optimization problem given in \Cref{eq:opt_vac}, and let $\lambda_\varepsilon = \rho(\G[V \setminus R_\varepsilon])$, where $R_\varepsilon$ is the output of \cref{alg:dp_alg} with precision parameter $\varepsilon$. Then, $\abs{\lambda^* - \lambda_\varepsilon} \leq \varepsilon$.
\end{theorem}

\begin{proof}
    Proof follows from the correctness and completeness of \cref{alg:dp_feas_check}, stated and proven below.
\end{proof}

Throughout the rest of the subsection, let $\G$ be an undirected graph with nice tree decomposition $\Td~=~\left(\T,\left\{X_t\right\}_{t \in V(\T)}\right)$, $K \in \mathbb{Z}^+$ the vaccination budget, and $\lambda \in \mathbb{R}^+$ the desired spectral radius threshold. Assume that \Cref{alg:dp_feas_check} is run with input $\G$, $\Td$, $K$, and $\lambda$. 

\begin{claim}[Correctness of \Cref{alg:dp_feas_check}]
    If \Cref{alg:dp_feas_check} returns \texttt{True} and identifies a set $ R $ of vertices to vaccinate, then $\abs{R} \leq K$ and $\rho(\G[V \setminus R]) \leq \lambda$.
\end{claim}

\begin{proof}
    Assume that \Cref{alg:dp_feas_check} returns \texttt{True} with a set $R$. We will prove the correctness of the algorithm by proving the correctness of $\DP[t,S,c]$ for each node type using induction i.e., we will prove that if $\DP[t,S,c] \neq \emptyset$, then all $R \in \DP[t,S,c]$ satisfy simultaneously (i) $\abs{R} = c$, (ii) $S \cap R = \emptyset$ and (iii) $\rho(\G[V_t \setminus R]) \leq \lambda$. 

    For the base case, notice that $\DP[t,S,c] = \emptyset$ for all $t \in V(\T)$, $S \subseteq X_t$, and $0 \leq c \leq K$, so the hypothesis is trivially satisfied. Then, for the induction step, notice that the algorithm iterates through the tree's nodes in a post-order and visits children before the parent. Thus, for each node $t$, we assume the correctness of its children's $\DP$ values (induction hypothesis). We will now prove the correctness of the node $t$, based on its type.

    \paragraph{Leaf node.} For a leaf node $t$, note that $V_t = \emptyset$, and the algorithm sets the only $R$ in $\DP[t,\emptyset,0]$ as $\emptyset$, which trivially satisfies (i), (ii), and (iii).

    \paragraph{Introduce node.} For an introduce node $t$ with child node $t'$, we have $X_t = X_{t'} \cup \{v\}$ for some $v \in V(\G)$. For all $S \subseteq X_t$ and $0 \leq c \leq K$,
    \begin{itemize}
        \item If $v \not\in S$, then the algorithm sets $\DP[t, S, c] = \{R' \cup \{v\} \colon R' \in \DP[t', S, c-1]\}$. Thus, for any $R' \cup\{v\} = R \in \DP[t, S, c]$, we have $\abs{R} = \abs{R'} + 1 = c$ and $S \cap R = (S \cap R') \cup (S \cap \{v\}) = \emptyset$, so (i) and (ii) are satisfied. For (iii), notice that $V_t \setminus \{v\} = V_{t'}$, so $\rho(\G[V_t \setminus R]) = \rho(\G[V_{t'} \setminus R']) \leq \lambda$ by the induction hypothesis.

        \item  If $v \in S$, then the algorithm sets $\DP[t, S, c] = \{R' \in \DP[t',S \setminus \{v\}, c] \colon \rho(G[V_t \setminus R']) \leq \lambda\}$. Therefore, (iii) is satisfied by definition, and (i) and (ii) are satisfied by the induction hypothesis ($\abs{R'} = c$ and $S \cap R' = \emptyset$). 
    \end{itemize}

    \paragraph{Forget node.} For a forget node $t$ with child node $t'$, we have $X_t = X_{t'} \setminus \{w\}$ for some $w \in V(\G)$. Thus, $V_t = V_{t'}$. For all $S \subseteq X_t$ and $0 \leq c \leq K$, the algorithm sets $\DP[t,S,c] = \DP[t',S,c] \cup \DP[t', S \cup \{w\}, c]$. Let $R \in \DP[t,S,c]$.

    \begin{itemize}
        \item If $R \in \DP[t',S,c]$, then $\abs{R} = c$, $S \cap R = \emptyset$, and $\rho(\G[V_t \setminus R]) = \rho(\G[V_{t'} \setminus R]) \leq \lambda$ by the induction hypothesis.
        \item If $R \in \DP[t',S \cup \{w\},c]$, then $\abs{R} = c$ and $\rho(\G[V_t \setminus R]) \leq \lambda$ by the induction hypothesis, so (i) and (iii) are satisfied. For (ii), notice that $(S \cup \{w\}) \cap R = \emptyset$, by the induction hypothesis, implying $S \cap R = \emptyset$. 
    \end{itemize}

    \paragraph{Join node.} For a join node $t$ with child nodes $t_1$ and $t_2$, we have $X_t = X_{t_1} = X_{t_2}$. For all $S \subseteq X_t$ and $0 \leq c \leq K$, the algorithm sets
    \begin{align*}
        &\DP[t, S, c] = \\
        &\left\{ R_1 \cup R_2 \;\bigg|\;0 \leq c_1, c_2 \leq K,\ R_1 \in \DP[t_1, S, c_1],\ R_2 \in \DP[t_2, S, c_2],\ |R_1 \cup R_2| = c,\ \rho(G[V_t \setminus (R_1 \cup R_2)]) \leq \lambda \right\}.
    \end{align*}
    Conditions (i) and (iii) are satisfied by definition. Condition (ii) is also satisfied as $S \cap R_1 = S \cap R_2 = \emptyset$ by the induction hypothesis.

    We have shown that assuming the correctness a node $t$'s children's $\DP$ values, the correctness of $t$'s $\DP$ values follows. This, combined with the base case, establishes the correctness of the algorithm through induction.
\end{proof}

\begin{claim}[Completeness of \Cref{alg:dp_feas_check}]
    If there exists a set $ R' \subseteq V(\G) $ with $ |R'| \leq K $ such that $ \rho(\G[V(\G) \setminus R']) \leq \lambda $, then \Cref{alg:dp_feas_check} will return \texttt{True} along with a set $R \subseteq V$ with $\abs{R} \leq K$ such that $ \rho(\G[V(\G) \setminus R]) \leq \lambda $.
\end{claim}

\begin{proof}
    Let $R \subseteq V(\G)$ be any set of vertices with $\abs{R} \le K$ for which $\rho\bigl(\G[V(\G)\setminus R]\bigr) \le \lambda$. We show by (bottom-up) induction on the nodes of the tree decomposition $\Td$ that $R$ is recorded in the table $\DP[\cdot,\cdot,\cdot]$. In particular, we will prove that for every node $t \in V(\T)$, 
    \[
       R_t \;:=\; R \cap V_t 
       \quad\text{belongs to}\quad 
       \DP\bigl[t,\; X_t \cap (V(\G) \setminus R),\; \abs{R_t}\bigr].
    \]
    Since $X_t \cap R = \emptyset$ is equivalent to $X_t \cap (V(\G)\setminus R) = X_t$, we define the `preserved set' $S_t := X_t \setminus R$ so that $R_t$ never intersects $S_t$. As before, $V_t$ denotes the union of all bags in the subtree of $\T$ rooted at $t$.

    \paragraph{Base Case (Leaf node).}
    If $t$ is a leaf node, then $X_t = \emptyset$ and $V_t = \emptyset$. Thus $R_t = R \cap \emptyset = \emptyset$. The algorithm sets $\DP[t, \emptyset, 0] = \{\emptyset\}$ (and $\DP[t,S,c] = \emptyset$ otherwise). Clearly, $R_t=\emptyset$ is indeed recorded in $\DP[t, \emptyset, 0]$. 

    \paragraph{Induction Hypothesis.}
    Assume that for every child $t'$ of $t$, $R_{t'} \in \DP[t',\, S_{t'},\, \abs{R_{t'}}]$ where $S_{t'} = X_{t'}\setminus R$. We now prove that $R_t \in \DP[t,S_t,\abs{R_t}]$.

    \paragraph{Introduce node.}
    Suppose $t$ is an introduce node with child $t'$, and let $v$ be the vertex introduced at $t$, so $X_t = X_{t'} \cup \{v\}$. There are two cases:
    \begin{itemize}
        \item \textbf{Case 1:} $v \in R$. Then $R_t = R_{t'} \cup \{v\}$ and $S_t = S_{t'}$ (since $v \notin S_t$). By induction, we know $R_{t'} \in \DP[t',\, S_{t'},\, \abs{R_{t'}}]$. Because $v \in R_t$, the DP update rule places $R_t$ into $\DP[t,\, S_t,\, \abs{R_t}]$ as $R_{t'} \cup \{v\}$.
        \item \textbf{Case 2:} $v \notin R$. Then $R_t = R_{t'}$ and $S_t = S_{t'} \cup \{v\}$. By induction, $R_{t'} \in \DP[t',\, S_{t'} \cup \{v\},\, \abs{R_{t'} }]$. The DP update rule copies $R_{t'}$ directly into $\DP[t,\, S_t,\, \abs{R_t}]$ (and also checks $\rho(\G[V_t\setminus R_t]) \le \lambda$, which holds by assumption).
    \end{itemize}

    \paragraph{Forget node.}
    Suppose $t$ is a forget node with child $t'$, and let $w$ be the vertex forgotten at $t$, so $X_t = X_{t'} \setminus \{w\}$ and $V_t = V_{t'}$. We again have two cases:
    \begin{itemize}
        \item \textbf{Case 1:} $w \in R$. Then $R_t = R_{t'}$ and $S_{t} = S_{t'} \setminus \{w\}$. By induction, $R_{t'} \in \DP[t',\, S_{t'},\, \abs{R_{t'}}]$. The DP update rule ensures $R_{t'}$ appears in $\DP[t,\, S_t,\, \abs{R_t}]$.
        \item \textbf{Case 2:} $w \notin R$. Then $R_t = R_{t'}$ and $S_t = S_{t'}$. By induction, $R_{t'} \in \DP[t',\, S_{t'},\, \abs{R_{t'}}]$. Again, $R_{t'}$ is copied into $\DP[t,\, S_t,\, \abs{R_t}]$.
    \end{itemize}

    \paragraph{Join node.}
    Suppose $t$ is a join node with two children $t_1$ and $t_2$, where $X_t = X_{t_1} = X_{t_2}$. Observe that $R_{t} = R_{t_1} \cup R_{t_2}$ and $S_{t} = S_{t_1} = S_{t_2}$. By the induction hypothesis, 
    \[
       R_{t_1} \in \DP[t_1,\, S_{t_1},\, \abs{R_{t_1}}]
       \quad\text{and}\quad
       R_{t_2} \in \DP[t_2,\, S_{t_2},\, \abs{R_{t_2}}].
    \]
    The join node's DP rule unites these sets whenever they align on the same $S_{t}$ and total size $\abs{R_t} = \abs{R_{t_1}} + \abs{R_{t_2}} \le K$. By our feasibility assumption, $\rho(\G[V_t\setminus (R_{t_1}\cup R_{t_2})]) \le \lambda$, so $R_t$ is placed in $\DP[t,\, S_t,\, \abs{R_t}]$.

    We have shown that whenever the children of a node $t$ have valid DP entries, the node $t$ will also have a valid DP entry. Thus, by induction, the solution $R'$ is recorded in the root node's DP table, and the algorithm returns \texttt{True}. More specifically, at the root node $r$ we have $R \in \DP[r,\, \emptyset,\, c]$ for some $ 0\leq c \leq K$. Therefore, $\DP[r,\emptyset,c] \neq \emptyset$, which guarantees \Cref{alg:dp_feas_check} detects a feasible solution.
\end{proof}

\subsubsection{Time Complexity of \Cref{alg:dp_alg}}
\label{app:dp_time}

\DPTimeComplexity*

\begin{proof}
    The complexity arises from the binary search, building the DP table, node and spectral radius computation, each of which we analyze below.

    \paragraph{Binary search.} The binary search is done on $[0, \Delta]$ and runs until $\mathsf{high} - \mathsf{low} > \varepsilon$, thus taking $\mathcal{O}(\log(\Delta/\varepsilon))$ time.

    \paragraph{DP table.} The DP table is indexed by $t \in V(\T)$, $S \subseteq X_t$, and $c \in \{0,1,\ldots,K\}$. The number of nodes in the tree decomposition is upper bounded by $\O(\omega n)$ by \Cref{lem:nice_tree_decomp}. Then, as size of each bag $X_t$ is at most $\omega + 1$ by the definition of treewidth (see \Cref{app:tree_decomp}), we have that the total number of subsets is upper bounded by $\O(2^{\omega+1})$. Thus, the total number of entries in the DP table is $\O(\omega n 2^{\omega+1} K)$. 

    Note that although the DP table is described in \Cref{sec:vac_strat_dp} as storing all feasible solutions per $(t, S, c)$ triplet, this is not necessary. We only need to retain a representative solution for each state, and in particular only before a join node is reached in the post-order. In other words, once a join node has been processed, it suffices to only keep one solution per triplet. This is how we avoid a $\binom{n}{K}$ factor in the complexity. We still need to perform a search over $K^2$ many $c$ values at each node join node, but this only adds a $\O(K^2)$ factor to the complexity.

    \paragraph{Spectral radius.} The spectral radius computation complexity is at most $\mathcal{O}(n^2)$ using the Lanczos algorithm for sparse graphs with $\mathcal{O}(n)$ nonzero entries \cite{Lanczos_alg}.

    Combining the above, we have that the total time complexity is $\mathcal{O}\left(n^3 K^3 \omega 2^{\omega + 1} \log(\Delta / \varepsilon)\right)$.
\end{proof}

\subsubsection{Optimality of \Cref{alg:tree-vacc}}
\label{app:vac_opt}
Here, we prove the optimality of \Cref{alg:tree-vacc}, which follows directly from the correctness and completeness of \Cref{alg:feasibility-check}, proven below.

Throughout the rest of this subsection, let $\T = (V,E)$ be an undirected tree, $K \in \mathbb{Z}^+$ the vaccination budget, and $\lambda \in \mathbb{R}^+$ the desired spectral radius threshold. Assume that \Cref{alg:feasibility-check} is run with input $\T'$, $K$, and $\lambda$. Without loss of generality, order the vertices in the tree $\T$ by picking a random root and ordering the other vertices accordingly.

Lastly, define $\mathcal{C}(\T)$ as the set of connected components of $\T$, where $\T$ is a forest, and define a \textit{minimal offending subtree} as a connected subtree $S \subseteq V $ where $ \rho(\T[S]) > \lambda $ and for any proper connected subtree $ S' \subset S $, $ \rho(\T[S']) \leq \lambda $.

\begin{claim}[Correctness]
If \Cref{alg:feasibility-check} returns \texttt{True} and identifies a set $ R $ of vertices to remove, then $\abs{R} \leq k$ and after removing $ R $ from the tree $ \T $, $\rho(\T[V \setminus R]) \leq \lambda$.
\end{claim}

\begin{proof}
Assume that \Cref{alg:feasibility-check} returns \texttt{True} with a set $R$. First, observe that $\abs{R} \leq k$, due to the if clause in line 6. Then, notice that the algorithm performs a post-order depth-first traversal of the tree. At each vertex $ u $, it attempts to merge all child subtrees with $ u $. 

If the spectral radius $ \rho(\T[S]) \leq \lambda $, the subtree remains connected, and no cut is made. Otherwise, the algorithm adds $u$ to $R$, effectively removing $ u $ from its parent by not including $ u $ in the merged subtree, ensuring that the offending subtree rooted at $u$ does not propagate upwards.

Since the traversal is post-order, all descendants of any vertex $ u $ have been processed before $ u $ itself. Therefore, when an offending subtree is detected at $ u $, none of its descendants have subtrees with spectral radius larger than $\lambda$. Consequently, when the final vertex in the post-order is reached, all subtrees rooted at all other vertices satisfy the spectral radius threshold.

Thus, after \Cref{alg:feasibility-check} terminates, we have that for all connected components (i.e., subtrees) after removal of vertices in $R$, $S \in \mathcal{C}(\T[V \setminus R])$, $\rho(\T[S]) \leq \lambda$. Then, the desired claim follows from applying the equality relating the spectral radius of a graph to the maximum of the spectral radii of its connected components: $\rho(\T[V \setminus R]) = \max_{S \in \mathcal{C}(\T[V \setminus R])}\rho(\T[S])$ \cite{van_mieghem_spec_rad_2011}.
\end{proof}


\begin{claim}[Completeness]
If there exists a set $ R' \subseteq V $ with $ |R'| \leq K $ such that $ \rho(\T[V \setminus R']) \leq \lambda $, then \Cref{alg:feasibility-check} will return \texttt{True} along with a set $R \subseteq V$ with $\abs{R} \leq K$ such that $ \rho(\T[V \setminus R]) \leq \lambda $.
\end{claim}

\begin{proof}
Assume, for contradiction, that there exists a feasible solution $R' $ with $ |R'| \leq K $ such that $ \rho(\T[V \setminus R']) \leq \lambda $, but \Cref{alg:feasibility-check} returns \texttt{False}, implying $\abs{R} > K $, where $R$ is the set constructed by \Cref{alg:feasibility-check}.

When the algorithm processes the tree in post-order, it identifies and removes the root of each minimal offending subtree. Moreover, following each removal of a subtree root, that subtree is never visited again by the algorithm. Thus, each element of $R$ corresponds to removing exactly one vertex from a distinct minimal offending subtree.

Now if $ \abs{R} > K $, this implies that there are more than $K$ distinct minimal offending subtrees in $ \T $. However, since each such subtree requires at least one vertex removal and $ |R'| \leq K $, it is impossible to cover all offending subtrees with $ K $ removals. This is a contradiction and thus \Cref{alg:feasibility-check} must return \texttt{True}, establishing the optimality of the algorithm.
\end{proof}
