\underline{V}\ar[d]_{\alpha} \ar[r] & \underline{V}_0\ar[d]^{ \alpha_0}\ar[r]^{w_0}& \underline{V}_1\ar[d]^{\alpha_1}\ar[r]^{w_1} & \underline{V}_2\ar[r]\ar[d]^{\alpha_2} & \cdots  \\
\underline{Z}^{n+1}(\mathcal{U})\ar[r]         & \mathcal{U}^{n+1}\ar[r]_{d}&\mathcal{U}^{n+2}\ar[r]_d & \mathcal{U}^{n+3}_d \ar[r] &\cdots
}}
\caption{Diagram for elementary extension}
\label{fig:elementaryext}
