\begin{theorem}\cite [Theorem 3.11]{LS02}\label{thm:existance of minimal}
If $\sU$ is a system of $\DGA$s which is cohomologically $1-$connected, then there exists a minimal model of $\sU$, i.e., a minimal system $\sM$ and a quasi-isomorphism $\rho:\sM \to \sU$.
\end{theorem}


\begin{definition}\label{def:associ:vect}(Associated diagram of vector spaces)
Let $\cA$ be an injective cohomology diagram and $(\sM,\rho)$ be its minimal model. Let $\sM_n=\sM_{n-1}^{\gamma}(\underbar{V})$, be the $n$-th stage construction of $\sM$, which is obtained by taking elementary extension of $\sM_{n-1}$ with the injective resolution of $\underbar{V}$. We refer to $\underbar{V}$ as the  \emph{$n$-th stage associated diagram of vector spaces of $\cA$}. 
\end{definition}







In the non-equivariant setup, we define the following.
\begin{definition}[Retract]\label{defn: retract}
   Given a $\DGA$  $A$ and a sub-$\DGA$ $B$ of $A$, we say $B$ is a retract of $A$ if there is a $\DGA$-morphism $r: A\to B$ such that $r\circ i=id$. Here $i:B\to A$ is the inclusion morphism and the morphism $r$ is called the retraction. Equivalently, we define a map $r:A \to B$ is said to be a retraction if there is a $\DGA$ morphism $i:B\to A$ such that $r\circ i=id$. 
\end{definition}

In the corrected version of \cite{santhanam2023equivariant} the authors prove the following result. We provide the prove for the sake of completeness.
\begin{prop}\label{Z_P injimpliesminimal}
Let $G=C_p$, for $p$ prime. If the structure map in the cohomology diagram $\cA$  $\cA_{e,G}: \cA(G/e)\to \cA(G/G)$ is a retraction of $\DGA$s then the associated diagram of vector spaces is injective. In particular, the minimal model of the cohomology diagram is level-wise minimal.
\end{prop}
\begin{proof}


Since the structure map $\cA_{e,G}:\cA(G/e)\to \cA(G/G)$ is a retraction, there exists $i:\cA(G/G)\to \cA(G/e)$ such that $\cA_{e,G}\circ i=id$. This  implies $\cA_{e,G}$ is surjective, and it follows that $\cA$ is injective diagram  of graded algebras. Note that for any minimal system of $\DGA$s $\sN$, the $\DGA$ $\sN(G/G)$ is non-equivariantly minimal by construction. 
    Let $\rho:\sM\to \cA$ be the minimal model and let $\sM_{e,G}:\sM(G/e)\to \sM(G/G)$ be the corresponding structure map. We claim that there exists $j:\sM(G/G)\to \sM(G/e)$ an inclusion map of $\DGA$s. 
    Since $\cA(G/e)$ is a $\DGA$ with zero differential we have, $\rho(G/e):\sM(G/e)\to \cA(G/e)$ is surjective quasi-isomorphism, by Lifting Lemma (\cite[Lemma 12.4]{FHT}), there exists a lift $j:\sM(G/G)\to \sM(G/e)$ so that the \Cref{fig:levelwisemin} commutes  
        \begin{figure}[h]
        \centerline{
\xymatrix{
\sM(G/e)\ar[r]^{ \rho(G/e)}  & \cA^i(G/e) \\
\sM(G/G) \ar[r]_{\rho(G/G)}\ar[u]^{j}   & \cA^i(G/G)\ar[u]_{i}
}}
\caption{Horizontal arrows are quasi-isomorphisms, $i,j$ are inclusions }
\label{fig:levelwisemin}
\end{figure}
Therefore, 
\begin{equation}
    \cA_{e,G}\circ i \circ \rho(G/G)= \cA_{e,G} \circ \rho(G/e)\circ j\\
    \implies \rho(G/G)=\rho(G/G)\circ \sM_{e,G}\circ j
\end{equation}
Since $\rho(G/G)$ is a quasi-isomorphism , $\sM_{e,G}\circ j:\sM(G/G)\to \sM(G/G)$ is a quasi-isomorphism. It then follows that, $\sM_{e,G}\circ j$ is an isomorphism and therefore $j:\sM(G/G)\to \sM(G/e)$ is an inclusion and $\sM_{e,G}$ is a surjection. Also note that if we let $\sM_{e,G}\circ j=\phi$, where $\phi$ is isomorphism, then $\sM_{e,G}\circ j\circ \phi^{-1}=id$, making $\sM_{e,G}$ a retraction.



%Note that for any minimal system of $\DGA$s $\sN$, the $\DGA$ $\sN(G/G)$ is non-equivariantly minimal. Indeed, as $\sN$ is minimal it can be written as increasing union of elementary extensions $\sN_i =\mathbb{Q}(\oplus_{j=1}^{n_i} \underline{ V_j^i})$, where for each associated system of vector spaces $\underline{ V^i}$, we have the corresponding injective resolution $ \underline{ V_0^i}\to \underline{ V_1^i}\to\cdots\to  \underline{ V_{n_i}^i}$. For each $i$, $\underline{V_1^i}(G/G)=\underline{V}^i(G/G)$ from the definition of injective envelope. Therefore, the elementary extension's $G/G$-level is the same as that of the Hirsch extension (as in the non-equivariant case). 




Next, we show that all the associated systems of vector spaces are injective by induction on $n$ where $\sM=\cup \sM_m$. 
    Recall $\sM_n=\sM_{n-1}(\underline{V})$, where $\underline{V}$ is $H^{n+1}(\ker (\beta) \oplus \underline{\QQ})$ is the associated diagram of vector spaces at $n$-th stage. Any element of $\underbar{V}(G/G)$ looks like the product of the elements of $\sM_{n-1}(G/G)$, $\cA(G/G)$ and $\sum \cA(G/G)$. We study case by case to conclude that $\underbar{V}(\hat{e}_{e,G})$ is surjective. Let $[x]\in \underbar{V}(G/G)$.

    \begin{enumerate}
        \item 
        If $x\in \sM^{n+1}_{n-1}(G/G)$ i.e., $[x]\in \underline{V}(G/G)$. Then $j(x)\in \sM_{n-1}(G/e)$. 

        As $\beta=\rho$ on $\sM_{n-1}$, we have $i\circ \rho(G/G)(x)=\rho(G/e)\circ j(x)$, this implies $i\circ \beta(G/G)(x)=\beta(G/e)\circ j(x)$, which implies $j(x)\in \ker \beta(G/e)$. 
        As $j$ is a $\DGA$-map we get $dj(x)=jd(x)$, which gives $j(x)\in \underline{V}(G/e)$. 
        \item If $x\in \sum \cA(G/G)$ then by injectivity of $\cA$, one gets a pre-image in $\sum \cA(G/e)$. As the differential is zero for elements in $\sum \cA$. So we get a pre-image in $\underbar{V}(G/e)$. 

        \item Assume $x$ is the product of elements in $\sM_{n-1}$, $\cA$ and $\sum \cA$. In this case, note that the maps $i,j$ induces a $\DGA$-map $g: \sM(G/G)\otimes\QQ (\cA \oplus \sum \cA)(G/G)\to \sM(G/e)\otimes\QQ (\cA \oplus \sum \cA)(G/e)$. If $x=m.a.sb$ where $m\in \sM(G/G)$, $a\in \cA(G/G)$ and $sb\in \sum \cA(G/G)$, with $[x]\in \underline{V}(G/G)$, then we have $[g(m.a.sb)]\in \underline{V}(G/e)$. 


    \end{enumerate}

Hence, $\underbar{V}$ is injective and it follows that  the minimal model $\sM$ is level-wise minimal. 
\end{proof}


Surjective morphisms between non-equivariant minimal models exhibit useful structural properties. One such consequence is the following result.

\begin{lemma}\label{lemma: minimal surjective}
Let $\varphi \colon A \to B$ be a morphism of $\DGA$s, where both $A$ and $B$ are minimal Sullivan algebras (i.e., non-equivariantly minimal). 

For each $k \geq 1$, let $A_{\leq k}$ and $B_{\leq k}$ denote the subalgebras of $A$ and $B$ generated by elements of degree less than or equal to $k$. Then, by the structure of minimal Sullivan algebras (via Hirsch extensions), we can write:
\[
A_{\leq k} = A_{\leq k-1} \otimes \wedge V^k 
\quad \text{and} \quad
B_{\leq k} = B_{\leq k-1} \otimes \wedge W^k,
\]
where $V^k$ and $W^k$ are $\mathbb{Q}$-vector spaces concentrated in degree $k$.

If the map $\varphi \colon A \to B$ is surjective, then for each $k$, the induced map $A_{\leq k} \to B_{\leq k}$ is also surjective. In particular, the induced linear map $V^k \to W^k$ is surjective for each $k$.
\end{lemma}

\begin{proof}
Consider the projection $\pi_W : B \to W$ be the projection onto generators, using the decomposition as a direct sum $$B = W \oplus W^{\otimes 2}/S_2 \oplus \dots.$$
Let $\phi|_V$ be the restriction of $\phi$ to generators. Then $\pi_W \circ \phi|_V : V \to W$ is the linear part of $\phi$.

Since $B_{\leq k}$ is generated by elements of degree $\leq k$, it suffices to prove that $A_{\leq k} \to B_{\leq k}$ hits all of these elements. But if $y \in B_{\leq k}$ is of degree $\leq k$, since $\phi$ is surjective, there exists $x \in A$ with $\phi(x) = y$; and $\deg(x) = \deg(y) \leq k$ so $x \in A_{\leq k}$.

Moreover, the linear part of $f\phi$ is also surjective in every degree. Suppose $w \in W^k$ is a generator of degree $k \geq 2$. Since $\phi$ is surjective, there exists $a \in A$ such that $f(a) = w$. The element $a$ decomposes as $a = v + a'$, where $v \in V$ and $a' = b_1 c_1 + \dots + b_l c_l \in A$ is decomposable as a sum of nontrivial products of elements of positive degree. It follows that $w = f(a) = f(v) + \sum_i f(b_i) f(c_i)$ projects to $f(w)$ under $\pi_W$. But of course $\pi_W(w) = w$ so $\pi_W(f(v)) = w$.
\end{proof}


