\begin{definition}[Pullback] \label{defn:pullback}
Let $A, B, C$ be $\DGA$s over $\QQ$, and let $f: A \to C$ and $g: B \to C$ be morphisms of \DGA s. The \emph{pullback DGA}, $A \times_C B$ is defined as follows:

\begin{itemize}
  \item As a graded module,
  \[
  (A \times_C B)_n = \{ (a, b) \in A_n \times B_n \mid f(a) = g(b) \in C_n \}.
  \]

  \item The multiplication is defined componentwise:
  \[
  (a_1, b_1) \cdot (a_2, b_2) = (a_1 a_2, b_1 b_2).
  \]

  \item The differential is defined by:
  \[
  d(a, b) = (d_A a, d_B b).
  \]
\end{itemize}

This makes $A \times_C B$ into a $\DGA$, and it satisfies the universal property of the pullback in the category of $\DGA$s i.e., given $h:D\to A$ and $e:D\to C$ so that $fh=ge$ there exists $\tau:D\to A\times_C B$ so that the following diagram commutes (\Cref{Fig:4}). 

\begin{figure}[h] \centerline{%
 \xymatrix{
D\ar@{-->}[dr]^{\tau}\ar@/_2.0pc/@{->}@[black][ddr]_{h}\ar@/^2.0pc/@{->}@[black][rrd]^{e} & & \\
& A \times_C B\ar[r]^{\pi_2}\ar[d]_{\pi_1} & B\ar[d]^{g} \\
& A\ar[r]_{f} & C 
 }}
\caption{Pull-back diagram}\label{Fig:4}
\end{figure}


The map $\tau $ is given by $\tau(d)=(h(d),e(d))$ for any $d\in D$.
\end{definition}


\begin{remark}
Consider the diagram in \Cref{defn:pullback}. If $f,g$ are surjective then $\pi_i$ for $i=1,2$ are surjection. Additionally, if $\tau$ is surjection so are $h,e$. This can be seen in the following way.  
Let $a\in A$. As $g$ is surjection there exists $b\in B$ so that $f(a)=g(b)$ so that $(a,b)\in A\times _C B$. Hence $\pi_1$ is surjective. Using a similar argument, we conclude that $g$ is surjective. 
Additionally, if we assume $\tau$ is surjective it follows that $h,e$ are surjective.   
\end{remark}

Motivated from \cite[Example 2.47]{FOT2008} we define the following.

\begin{definition}(Wedge product of $\DGA$s)\label{defn:wedge of DGAs}
    Let \( A = (A^\ast, d_A) \) and \( B = (B^\ast, d_B) \) be $\DGA$s over \( \mathbb{Q} \), each with unit \(1_A\) and \(1_B\). The \emph{wedge sum} \( A \vee B \) is defined as the pushout in the category of DGAs over \( \mathbb{Q} \), i.e.,
\[
A \vee B := (A \oplus B) / \langle 1_A - 1_B \rangle,
\]
with the following structure:
\begin{itemize}
    \item The unit is \(1 := 1_A = 1_B\).
    \item The multiplication is given by:
    \[
    (a + b) \cdot (a' + b') = aa' + bb',
    \]
    with the additional condition that
    \[
    a \cdot b' = 0 = b \cdot a' \quad \text{for all } a, a' \in A, \; b, b' \in B.
    \]
    \item The differential is defined componentwise:
    \[
    d(a + b) = d_A(a) + d_B(b).
    \]
\end{itemize}

This DGA reflects the cohomology ring of a wedge sum of spaces, where cohomology classes from the two summands do not interact except through the common unit.
\end{definition}


Let $f: A \to A'$ and $g: B \to B'$ be morphisms of $\DGA$s, and assume that $A \vee B$ and $A' \vee B'$ are defined as in \Cref{defn:wedge of DGAs}.

Then the induced map
\[
f \vee g : A \vee B \longrightarrow A' \vee B'
\]
is defined on representatives by
\[
(f \vee g)([a + b]) := [f(a) + g(b)],
\]
for all $a \in A$, $b \in B$. This is well-defined because $f(1_A) = 1_{A'}$, $g(1_B) = 1_{B'}$, and $f(a)g(b) = 0$ in $A' \vee B'$ whenever $a \in \overline{A}$, $b \in \overline{B}$.

Moreover, since $f$ and $g$ are DGA maps, $f \vee g$ respects the differential:
\begin{align*}
d(f \vee g)([a + b]) 
&= d([f(a) + g(b)]) \\
&= [d(f(a)) + d(g(b))] \\
&= [f(da) + g(db)] \\
&= (f \vee g)([da + db]) \\
&= (f \vee g)(d[a + b]).
\end{align*}



\begin{lemma}
    Let $f:A\to A'$ and $g:B\to B'$ be retraction of $\DGA$s then the induced map $f\vee g:A\vee A'\to B\vee B'$ is also a retraction.
\end{lemma}
\begin{proof}
As $f,g$ are retractions there exist $i:A'\to A$ and $j:B'\to B$ such that $f\circ i=id_{A'}$ and $g\circ j=id_{B'}$.

As above we can define $i \vee j : A' \vee B' \to A \vee B$ by
\[
(i \vee j)([a' + b']) := [i(a') + j(b')]
\]
for $a \in A'$, $b \in B'$. 

Then we compute:
\[
(f \vee g) \circ (i \vee j)([a + b]) = (f \vee g)([i(a) + j(b)]) = [f(i(a)) + g(j(b))] = [a + b],
\]
using that $f \circ i = {id}_{A'}$ and $g \circ j = {id}_{B'}$.

Thus, $(f \vee g) \circ (i \vee j) = {id}_{A \vee B}$, and $f \vee g$ is a retraction.
\end{proof}



\begin{lemma}\label{lemma: zigzag weak}
Let $A \simeq A'$ and $B \simeq B'$ be DGAs, where the weak equivalences are given by zigzags of quasi-isomorphisms. Then the wedge (coproduct) $A \vee B$ is weakly equivalent to $A' \vee B'$, i.e.,
$$
A \vee B \simeq A' \vee B'.
$$
\end{lemma}

\begin{proof}
Suppose we have zigzags of quasi-isomorphisms connecting $A$ to $A'$ and $B$ to $B'$ as follows:
$$
A = A_0 \xleftrightarrow{\simeq} A_1 \xleftrightarrow{\simeq} \cdots \xleftrightarrow{\simeq} A_n = A', \quad
B = B_0 \xleftrightarrow{\simeq} B_1 \xleftrightarrow{\simeq} \cdots \xleftrightarrow{\simeq} B_m = B'.
$$
Assume without loss of generality that $n \leq m$. We can extend the shorter zigzag (say, the $A_i$'s) by repeating the terminal DGA $A_n$ as needed, defining $A_i = A_n$ for $i > n$, so that both sequences have the same length.

Then we define a zigzag of quasi-isomorphisms between the wedge products:
$$
A_0 \vee B_0 \xleftrightarrow{\simeq} A_1 \vee B_1 \xleftrightarrow{\simeq} \cdots \xleftrightarrow{\simeq} A_m \vee B_m,
$$
where each map is the wedge (coproduct) of quasi-isomorphisms between the respective terms. Since the wedge of quasi-isomorphisms between cofibrant DGAs is again a quasi-isomorphism, this sequence forms a zigzag of quasi-isomorphisms from $A \vee B$ to $A' \vee B'$.

Hence, $A \vee B \simeq A' \vee B'$.
\end{proof}



