\begin{prop}
    Let $G=C_{pq}$, where $p,q$ are distinct primes, and $X$ be a $G$ space with the cohomology diagram  $\cA$ being injective. Then, the cohomology diagram of $X^Q$ as a $P$-space (similarly, the cohomology diagram of $X^P$ as a $Q$-space) is also injective. Moreover, the cohomology diagram of $X$ as a $C_p$-space (respectively $C_q$) is also injective.
\end{prop}
\begin{proof}
    The $C_{pq}$ diagram for $\cA$ is given as follows (see \Cref{fig:new}). 
        \begin{figure}[h]
            \centerline{
    \xymatrix{
    \cA(G/e)\ar[d]_{\cA_{e,P}}\ar[r]^{\cA_{e,Q}} & \cA(G/Q)\ar[d]^{\cA_{Q,G}}\\
    \cA(G/P)\ar[r]_{\cA_{P,G}} & \cA(G/G)
    }}
            \caption{$\cA$ as a $C_{pq}$-diagram of $\DGA$s }
            \label{fig:new}
        \end{figure}




    Note that $\cA(G/e)=H^*(X;\QQ), \cA(G/P)=H^*(X^P;\QQ),\cA(G/Q)=H^*(X^Q;\QQ), \cA(G/G)=H^*(X^G;\QQ)$. 
As $\cA$ is injective it follows from \Cref{thm: injective C_pq} that the structure maps are surjective. Now, if $x\in X^Q$ it follows that $q.x=x$ for all $q\in Q$. Also $(X^Q)^P=\{x\in X^Q~|~p.x=x~\text{for all } p\in P\}$. Therefore, as $x\in (X^Q)^P$ for any $g\in P\cup Q$, we have $g.x=x$. In particular, $g.x=x$ for all $g\in G$. Hence it follows $(X^Q)^P=X^G$ and the cohomology diagram for $X^Q$ is given by $\cA_{Q,G}:\cA(G/Q)\to \cA(G/G)$ which is subjective. By \Cref{prop:inj C_p} the result follows.   


Next, consider $X$ as a $P=C_p$-space. The cohomology diagram is given by $\cA_{e,P}:H^*(X;\QQ)\to \H^*(X^P;\QQ)$, which is surjective. Hence the result follows. 
\end{proof}



\section{ Combination theorems}\label{section: combnation theorem}

In this section, we prove the combination theorems as promised in \Cref{section:intro}. We start with the following definitions.

\begin{definition}[Wedge product of $C_p$ and $C_q$ space]\label{defn: equiwedgespace}
Let $X$ (respectively $Y$) be $C_p$-space (resectively $C_q$-space). Let $X^{C_p}$ and $Y^{C_q}$ are corresponding fixed point spaces. We define the $C_{pq}$-space as follows 
\[
X\vee Y:=
\begin{cases}
    X\vee Y, & \text{at G/e}\\
    X^{C_p}\vee Y, & \text{at G/P}\\
    X\vee Y^{C_q}, & \text{at G/Q}\\

    X^{C_p}\vee Y^{C_q} 
    ,  & \text{ at G/G}.
\end{cases}
\] 

The structure maps are induced from the structure maps of $X,Y$ as $C_p$ and $C_q$-spaces. 


\end{definition}

Using \Cref{defn:wedge of DGAs} one can define the following.

\begin{definition}[Wedge product of diagram of $\DGA$s]\label{defn:wedgeequivar}

Let $\cU_1\in \sO_{C_p}[\DGA]$ and $\cU_2\in \sO_{C_q}[\DGA]$s. Then one can combine these diagrams to get a $C_{pq}$-diagram of $\DGA$s, $\cU_1\vee \cU_2$, defined as 

\[
\cU_1\vee \cU_2:=
\begin{cases}
    \cU_1(C_p/e)\vee \cU_2(C_q/e), & \text{at G/e}\\
    \cU_1(C_p/C_p)\vee \cU_2(C_q/e), & \text{at G/P}\\
    \cU_1(C_p/e)\vee \cU_2(C_q/C_q), & \text{at G/Q}\\

    \cU_1(C_p/C_p)\vee \cU_2(C_q/C_q) 
    ,  & \text{ at G/G}.
\end{cases}
\] 

where the wedge is defined as in \Cref{defn:wedge of DGAs} and the structure maps are induced from the structure maps of $\cU_1$ and $\cU_2$ see \Cref{fig:eqwedge1}.
