\end{tikzcd}
\caption{Diagram for $\sM$}
\label{fig:Mo}
\end{figure}

Inductively, assume that the associated systems of vector spaces are injective for degree $\leq n$.
%We use \Cref{thm: injective C_pq} and show that the associated diagram of vector spaces satisfies Property I.

We now prove the $n$th stage of induction.

Without loss assume that $\pi_V:V\to V'$ and $\pi_W:W\to W'$ are projections. These maps induce projections $\pi_V^n:V_n\to V'_n$ and $\pi_W^n:W_n\to W'_n$ for every $n$, where the vector space $V_n $ (respectively, $V'_n,W_n,W'_n$) consists of vectors homogeneous in degree $n$. As in \Cref{fig: justM} all the arrows are surjections using \Cref{lemma: minimal surjective} it follows that all the arrows in the following \Cref{fig:assoc} are also so, where $h,k,f,g$ are induced naturally from $\pi_V,\pi_W$.
We denote the pull-back vector space for the maps $f,g$ by $R_n$ where the vectors in $R_n$ are $$((v',w, x),(v,w',y))\in V'_n \oplus W_n\oplus (K_{V',W})_n\times  V_n \oplus W'_n\oplus (K_{V,W'})_n $$ such that $v=v',w=w'$ and $f(x)=g(y)=z\in (K_{V',W'})_n$. It follows that there are vectors $a\in V',b\in W'$ so that $d(f(x))=d(g(y))=ab=dz$. Now $V\to V', W\to W'$ are projections so $K_{V',W'}$ embeds inside $K_{V',W},K_{V,W'}\subset K_{V,W}$. 

\begin{figure}[h!]
    \centering
\begin{tikzcd}
    & {V_n \oplus W_n\oplus (K_{V,W})_n }\\
     {V'_n \oplus W_n\oplus (K_{V',W})_n} & R_n& {V_n \oplus W'_n\oplus (K_{V,W'})_n} \\
     & {V'_n \oplus W'_n\oplus (K_{V',W'})_n}\\
     &&&{}
     \arrow[from=2-2, to=2-1]
     \arrow[from=2-2, to=2-3]
     \arrow[dashed,"\gamma",from=1-2, to=2-2]
     \arrow["h"', from=1-2, to=2-1]
     \arrow["k",from=1-2, to=2-3]
     \arrow["f"',from=2-1, to=3-2]
     \arrow[" g",from=2-3, to=3-2]
\end{tikzcd}
\caption{The commutative square indicates the $n$th stage associated diagram of vector spaces for $\sM$, $R_n$ is the pull-back vector space with respect to $f,g$, $\gamma$ is induced by the universal property of pullback} \label{fig:assoc}
\end{figure}


Moreover, $K_{V',W}\cap K_{V,W'}=K_{V',W'}$ as a subspace of $K_{V,W}$. Indeed, as each vector in $K^1_{V',W}$ (respectively, $K^1_{V,W'}$) corresponds to a pair $(v,w')\in V \times W'$ (respectively $V'\times W$) so the vectors in the intersection corresponds to $V'\times W'$.
For the other iterated spaces, a similar thing happens.

Therefore, $x=z+t$ and $y=z+s$, where $t\in K_{V',W}/K_{V',W'}$ and $s\in K_{V,W'}/K_{V',W'}$. Also, by construction $f(t)=0$ it follows that $k(t)=0$, similarly, $g(s)=0=h(s)$. 

Now consider the element $(v',w',z+t+s)\in V_n\oplus W_n\oplus (K_{V,W})_n$. The induced map due to universal property $\gamma:V_n\oplus W_n\oplus (K_{V,W})_n\to R_n$ is given by

\begin{align*}
\gamma(v', w', z + t + s) 
&= \left(h(v', w', z + t + s),\; k(v', w', z + t + s)\right) \notag \\
&= \left((v', w', z + t),\; (v', w', z + s)\right) \notag \\
&= \left((v', w', x),\; (v', w', y)\right).
\end{align*}

This implies the diagram of associated system of vector spaces \Cref{fig:assoc} satisfies Property I and injective for each $n$. This implies $\sM$ is constructed inductively, by elementary extensions of injective diagram of vector spaces for each $n$. Hence $\sM$ is a minimal system. As $\sM \to \sM_1\vee \sM_2\to \cA_1\vee \cA_2$ is a quasi-isomorphism, it follows that $\sM$ is the minimal model of $\cA_1\vee \cA_2$. This completes the proof.

\end{proof}

Using \Cref{thm:combmain} and \Cref{defn: equiwedgespace}, we have the following reslut which gives us a class of $C_{pq}$-cohomology diagram with minimal model level-wise minimal. 
\begin{corollary}\label{cor:main}
    Let $X$ be a $C_p$-space and $Y$ be a $C_q$-space such that the structure maps corresponding to their cohomology diagrams are retracts. Then the cohomology diagram for the $C_{pq}$-space $X\vee Y$ is injective and the minimal model is level wise minimal.  
\end{corollary}

We end this article by proving the following result that gives us a class of examples of $C_{pq}$-formal spaces.

\begin{theorem}\label{thm:main2}
    Let $X,Y$ be equivariantly formal $C_p$ and $C_q$-spaces, $p,q$ distinct primes, then $X\vee Y$ as a $C_{pq}$-space is also formal.
\end{theorem}
\begin{proof}
Let $\cA_1,\cA_2$ denote the injective envelopes of the cohomology diagrams for $X,Y$ respectively with equivariant minimal models $\sM_{\cA_i}$ for $i=1,2$.


    Let $\sM_1$ and $\sM_2$ be the equivariant minimal models of $X$ and $Y$, respectively. As $X,Y$ are equivariantly formal, it follows that the minimal systems $\sM_i$ and $\sM_{\cA_i}$ are weakly equivalent, for $i=1,2$.

    Using a similar argument as \Cref{lemma: zigzag weak} and a similar approach used to show the commutativity of \Cref{fig: M1M2andA}, we note that the $C_{pq}$-diagrams of $\DGA$s, $\sM_1\vee \sM_2$ and $\cA_1\vee \cA_2$ are weakly equivalent as 
    $$\sM_1\vee \sM_2 \to (.)\leftarrow{}\sM_{\cA_1}\vee \sM_{\cA_2}\to \cA_1\vee \cA_2.$$ 



    As $\cA_1\vee \cA_2$ and $\sM_1\vee \sM_2$ are injective using \Cref{prop: combination injective}, and the fact that they are weakly equivalent, it follows that the minimal model of $\sM_1\vee \sM_2$ is weakly equivalent to the injective envelope of $\cA_1\vee \cA_2$, which is itself. Now the minimal model for $X\vee Y$ and the minimal model for $\sM_1\vee \sM_2$ are the same. Hence, the result follows. 

\end{proof}



\begin{exmp}\label{exmp: mainnnn}
Consider the following example as in \Cref{exmp:1}. Let $T= (S^3\times S^3 \times S^3) \vee (S^5 \times S^5)$ with a $C_6$ action given by as follows: 
Let $H=<t>,K=<s>$ be subgroups of $C_6$ order $3,2$ respectively. $H$ acts on $(S^3\times S^3 \times S^3)$ by $t(x,y,z)=(y,z,x)$ and on $S^5\times S^5$ component the action is trivial. $K$ acts trivially on $(S^3\times S^3 \times S^3)$ and on $(S^5\times S^5)$ by $s(a,b)=(b,a)$. 

Thus we get $X^e=X$, $X^H=S^3 \vee (S^5\times S^5)$, $X^K=(S^3\times S^3 \times S^3)\vee S^5$ and $X^G=S^3 \vee S^5$.

The cohomology diagram is given by 
\[
\cA=
\begin{cases}
     \wedge (x_1,x_2,x_3,y_1,y_2)/D , & \text{at G/e}\\
    \wedge(x,y_1,y_2)/A,  & \text{ at G/H}\\
    \wedge(x_1,x_2,x_3,y)/B, & \text{ at G/K}\\
    \wedge(x,y)/C, & \text{ at G/G},
\end{cases}
\]

where $D=\langle x_iy_j~|~i=1,2,3 \text{ and } j=1,2\rangle$, 
$A=\langle xy_i~|~i=1,2\rangle$, 
$B=\langle x_iy~|~i=1,2,3 \rangle$, $C=\langle xy \rangle$.

The $x_i, y_j$ correspond to each copy of $S^3,S^5$ in $X^e$ and $x,y$ correspond to the copies of $S^3,S^5$ in $X^G$ respectively. 


We denote the injective envelope for $\cA$ as 
$\sI(\cA)= \underline{\cI}_G^\ast \oplus \underline{\cI}_e^\ast \oplus \underline{\cI}_H^\ast \oplus \underline{\cI}_K^\ast$,

where $\underline{\cI}_X^{\ast}$ is the associated system corresponding to the vector space $I_X=\cap 
_{X\subset Y}\ker (H(\hat{e}_{X,Y}))$ (see \Cref{equation:24}). 
Thus we get

\[
I_X=\begin{cases}
    0, & \text{ X=e}\\
    \wedge(x_{12},x_{13}), & \text{ X=H}\\
    \wedge(y_{12}), & \text{X=K}\\
    \wedge(x,y), & \text{X=G}
\end{cases}
\]

Hence, the corresponding systems are
\[
\underline{\cI}_e^\ast=
\begin{cases}
    0, & \text{ at every subgroup level}
\end{cases}
\]

\[
\underline{\cI}_G^\ast=
\begin{cases}
    I_G=\wedge(x,y)/C, & \text{ at every subgroup level}.
\end{cases}
\] 
\[
\underline{\cI}_H^\ast=
\begin{cases}
     I_H=\wedge(x_{12},x_{13}), & \text{at G/H, G/e}\\
   0 , & \text{else}
\end{cases}
\] 
\[
\underline{\cI}_K^\ast=
\begin{cases}
     I_K=\wedge(y_{12}), & \text{at G/K, G/e}\\
   0 , & \text{else}
\end{cases}
\] 

Thus the injective envelope of the cohomology diagram is 
\[
\underline{\cI}(\cA)=
\begin{cases}
     \wedge(y_{12}) \oplus \wedge(x_{12},x_{13})\oplus \wedge(x,y), & \text{at  G/e}\\
     \wedge(y_{12}) \oplus \wedge(x,y), & \text{at G/H}\\
     \wedge(x_{12},x_{13}) \oplus \wedge(x,y), & \text{at G/K}\\
   \wedge(x,y) , & \text{else}
\end{cases}
\] 

Note that the envelope is isomorphic to $\cA$, hence we conclude that $\cA$ is injective using \Cref{sum inj}.

Next, we compute the minimal model for $\cA\cong \cI(\cA)$. 

\textbf{Computation of $\sM_3$:}
First, consider the diagram, 

 \[
\xymatrix{
&\sM_{2}\ar[rd]^{\rho}\ar[d]_{\alpha} \\
\ker (\beta)\ar[r] &\sM'_{2} \ar[r]_{\beta}       & \cA} 
\]

where 
\[
\sM'_2=\sM_2 \otimes (\otimes (I_H \oplus \sum I_H))=
\begin{cases}
     \QQ_0\oplus \QQ_3(x_{12},x_{13},x)\oplus \QQ_4(sx_{12},sx_{13},sx), & \text{at  G/e}\\
     \QQ_0\oplus \QQ_3(x) \oplus \QQ_4(sx), & \text{at G/H}\\
     \QQ_0 \oplus\QQ_3(x_{12},x_{13},x) \oplus \QQ_4(sx_{12},sx_{13},sx) & \text{at G/K}\\
   \QQ_0 \oplus \QQ_3(x) \oplus \QQ_4(sx) , & \text{at G/G.}
\end{cases}
\] 

Therefore, 

\[
(\ker \beta)^4= 
\begin{cases}
   \QQ_4(sx_{12},sx_{13},sx), & \text{at  G/e}\\ 
   \QQ_4(sx), & \text{at G/H}\\
   \QQ_4(sx_{12},sx_{13},sx), & \text{at G/K}\\
   \QQ_4(sx) , & \text{at G/G.}
\end{cases}
\]
Using \Cref{thm: injective C_pq} or \Cref{prop: combination injective}, we conclude that $(\ker \beta)^4$ is injective. So $\underline{V}=H^4(\ker\beta)=(\ker \beta)^4$.

Thus $\sM_3$ is given by 
\[
\sM_3=
\begin{cases}
\wedge(a,b,c), & \text{at G/e}\\
\wedge (c), & \text{at G/H}\\
\wedge(a,b,c), & \text{at G//K} \\
\wedge(c), & \text{at G/G}
\end{cases}
\]
where $|a|=|b|=|c|=3$ with zero differential. The map $\rho $ is the obvious one. 
While computing $\sM_4$ one can check there is no element of degree $5$ in the $\ker (\beta: \sM'_3 \to \cA)$. Hence, we get $\sM_4=\sM_3$.

Similarly, one can check that $\sM_5$ is level-wise minimal and it is given by 
\[
\sM_5=
\begin{cases}
  \wedge(a,b,c,d,e), & \text{at G/e}\\
\wedge (c,d,e), & \text{at G/H}\\
\wedge(a,b,c,e), & \text{at G//K} \\
\wedge(c,e), & \text{at G/G}
\end{cases}
\]

where $\rho$ takes $(a,b,c,d,e)=(x_{12},x_{13},x,y_{12},y)$. Inductively, one can continue this process and get the minimal model. By \Cref{thm:combmain}, we conclude that $\sA$ has the minimal model level-wise minimal. 

Also note that the $C_6$-space $T$ can be written as the equivariant wedge $T_1\vee T_2$, where $T_1=S^3\times S^3\times S^3$, which is a $C_3$-space and $T_2=S^5\vee S^5$, which is a $C_2$-space. From \cite[Example 6.1]{santhanam2023equivariant} it follows that $T_1$ (respectively $T_2$) is $C_3$-equivariantly formal (respectively $C_2$-equivariantly formal).Hence by using \Cref{thm:main2} we conclude that $X$ is $C_{pq}$-equivariantly formal.      
\end{exmp} 


