\textbf{Notation.} For $\cX:=\{1,\ldots,d\}$, the space $\R^\cX$ is identified with $\R^d$, and we interchangeably use the notation $a(x)=a_x$ to denote the $x$th coordinate of any $a\in\R^d$. The $(d-1)$-dimensional vector $a_{-x}$ is defined by deleting the $x$th entry from $a$. Further, if $\psi:A\times B\to C$ is a function, then $\psi(a):B\to C$ is defined by $\psi(a)(b):=\psi(a,b)$. For $p\in[0,\infty]$, the $p$-norm is denoted by $|\cdot|_p$. For $p=0$, we recall the definition of the $0$-norm: $|a|_0=|\{x:a_x\neq0\}|$. For a function $\psi:\R^k\to\R^{k'}$, we define its Lipschitz constant with respect to the $|\cdot|_1$-norm by $\Lip_1(\psi) := \sup_{\tilde \mu\neq\mu} |\psi(\tilde \mu)-\psi(\mu)|_1/|\tilde \mu-\mu|_1$. Finally, probability distributions/vectors are treated as row vectors.

\section{Problems and main results}

\subsection{The general finite-player problem}

We consider a dynamic stochastic game between $N+1$ players or agents indexed by $\{0,\ldots,N\}$ in discrete time over a finite time horizon $\bar \cT=\{0,h,2h, \ldots, Kh\}$. 
Here, $h>0$ is the time step and we denote the time horizon by $T=Kh$. We write $\cT = \bar \cT\setminus\{T\}$. Let us fix a player $0\leq i \leq N$. Player $i$'s state is described by a discrete-time stochastic process $(X^i_t)_{t\in\bar \cT}$ taking values in a finite set $\cX=\{1,\ldots,d\}$.\footnote{The specific choice of $\cX$ is irrelevant. In particular, we do not assume any ordering on $\cX$.} This player uses a feedback policy $ \alpha^i:\cT\times\cX^{N+1}\to\Sigma^{d-1}$ to control the transition probabilities of $X^i_t$. The feedback control $\alpha^i$ is allowed to depend on the current time and position of the $N+1$ players. Here, the set of probability measures on $\cX$ is identified with the $(d-1)$-dimensional probability simplex $\Sigma^{d-1}:=\{p\in[0,1]^d:\sum_x p_x= 1\}$.
Given feedback policies $\alpha=(\alpha^0,\ldots,\alpha^{(N)})$ and given players' states $(x^0,\ldots,x^N)$ at time $t$, the states of players at time $t+h$ are drawn independently of each other. More precisely, let $X=(X^0,\ldots,X^N)$ be the state process which tracks the positions of all players. Without loss of generality, we let $X$ be the canonical element in the space $\Omega=(\cX^{N+1})^{\bar\cT}$. Its $\P^\alpha$-transition probabilities are given by
$$
\P^\alpha[X_{t+h} = y \,|\, X_t=x] = \prod_{i=0}^N \alpha^i(t,x)(y^i),\quad t\in\cT,\ x,y\in\cX^{N+1}.
$$
Given the controls of the other players $\beta=(\beta^j)_{j\neq i}$, player $i$  minimizes the following expected cost, which is the discretization of the continuous-time problem that we discuss in Section \ref{ssec:literature} below. Inspired by the continuous-time setting, our main structural assumption on the cost functional is that we penalize the \emph{rate} of changing states.  Precisely, at time $t\in\bar\cT$ and position $x\in\cX^{N+1}$ of all players, player $i$ solves
\be\label{eq:N-player-general-value-function}
\begin{split}
v^i(t,x;\beta)&:=\inf_{\alpha^i}\ \cJ^i(t,x,\alpha^i;\beta),\quad \text{where}\\
\cJ^i(t,x,\alpha^i;\beta) &:= \E^{\alpha^i\otimes \beta}\Bigl[
\sum_{t\leq s<T} \ell^i(X_s,\alpha^i(t,X_s)/h)h+g^i(X_T)
\,|\,X_t=x\Bigr],
\end{split}
\ee
$\ell^i: \cX^{N+1}\times [0,\infty)^{d}\to [0,\infty)$ and $g^i:\cX^{N+1}\to [0,\infty)$ are running and terminal cost functions, respectively, and we use the notation,
$$
(\alpha^i\otimes \beta)^j:=
\begin{cases}
\alpha^i,&i=j,\\
\beta^j,&i\neq j,
\end{cases}
$$
for any $0\leq i,j\leq N$. $\cJ^i$ is the \emph{cost functional} while $v^i$ is the \emph{value function} of player $i$. 
For future use, for a given strategy profile of all players $\alpha=(\alpha^0,\ldots,\alpha^{(N)})$, we define the vector of strategies of players other than $i$ by $\alpha^{-i}:=(\alpha^j)_{j\neq i}$.

\begin{Def}[Markov perfect equilibrium]
A strategy profile $\alpha^* = (\alpha^{*,0},\ldots, \alpha^{*,N}):\cT\times\cX^{N+1}\to(\Sigma^{d-1})^{N+1}$ is called a \emph{Markov perfect (Nash) equilibrium (MPE)} if
$$
\cJ^i(t,x,\alpha^{*,i};\alpha^{*,-i})\leq \cJ^i(t,x, \alpha^i;\alpha^{*,-i})
$$
for any feedback control $\alpha^i:\cT\times\cX^{N+1}\to\Sigma^{d-1}$, any $(t,x)\in\cT\times\cX^{N+1}$ and any $0\leq i\leq N$. 
\end{Def}

We recall some facts about discrete dynamic programming equations in Appendix \ref{app:dynamic-progamming}. Finding MPEs amounts to solving a coupled system of dynamic programming equations. This set of equations is commonly referred to as the \emph{Nash system} and it reads, for $0\leq i\leq N$ and $x\in\cX^{N+1}$,
\be \tag{Nash system}\label{eq:Nash-System}
\left\{
\begin{split}
v^i(t,x) &= \underset{a^i\in\Sigma^{d-1}}{\inf}\ \sH^i(x,v^i(t+h),a^i;\alpha^{-i}(t,x)),\quad  0\leq t\leq T,\\
\alpha^i(t,x) &= \underset{a^i\in\Sigma^{d-1}}{\mathrm{arg\,min}} \ \sH^i(x,v^i(t+h),a^i;\alpha^{-i}(t,x)),\quad  0\leq t< T,\\
v^i(T,x) &= g^i(x).
\end{split}
\right.
\ee
Here, for $(x,\varphi,a)\in\cX^{N+1}\times \R^{d(N+1)}\times\Sigma^{d-1}$, we defined player $i$'s \emph{Hamiltonian} by
$$
\sH^i(x,\varphi,a;\alpha^{-i}(t,x))  := \ell^i(x,a/h)h + \sum_{y=(y^0,\ldots,y^N)\in\cX^{N+1}} \varphi(y) a(y^i)\prod_{j\neq i}\alpha^j(t,x)(y^j).
$$ 
In the next section, we consider a game where $(\ell^i,g^i)=(\ell,g)$ for all $0\leq i\leq N$, for some common cost functions $\ell,g$, and show how \eqref{eq:Nash-System} reduces to the Nash-Lasry-Lions equation. We note that the techniques introduced in the next section to prove existence and uniqueness of the Nash-Lasry-Lions equation can also be used to establish existence and uniqueness of the \eqref{eq:Nash-System}.

\subsection{The symmetric finite-player problem}

We now consider a game with symmetric players and derive the Nash-Lasry-Lions equation. The assumption of symmetry will allow us to obtain a \emph{mean-field game} in the limit $N\to\infty$.  More precisely, we assume that, for all $0\leq i\leq N$, the cost functions are of \emph{mean-field type},  
\be \label{eq:symmetry}
\ell^i(x,a) = \ell(x^i, \frac1N \sum_{j\neq i}\delta_{\{x^j\}} ,a),\quad g^i(x) = g(x^i,\frac1N \sum_{j\neq i}\delta_{\{x^j\}})
\ee
for some functions $\ell:\sX_N\times[0,\infty)^d\to[0,\infty)$, $g:\sX_N\to[0,\infty)$. Here we set
$$
\Sigma^{d-1}_N:=\{z\in\Sigma^{d-1} : z_x\in\{0,1/N,\ldots,1\}\ \forall x\in\cX\},\quad \sX_N := \cX\times\Sigma^{d-1}_N,
$$
and we identify the set of empirical probability measures on $\cX$ with $\Sigma^{d-1}_N$. The analysis simplifies in this symmetric case. We fix a player and call it the \emph{tagged player}, and we refer to the untagged players as \emph{other players}. The state process of the problem can be summarized by a Markov chain $(X_t,Z_t)$ taking values in $\sX_N$. $X_t$ now denotes the state of the tagged player at time $t$ while $Z_t$ refers to the distribution of other players across states at time $t$. Given a feedback control $\alpha(t,x,z)$ of the tagged player and a feedback control $\beta(t,x,z)$ that is used by every other player, the transition probabilities are given by
$$
\P^{\alpha\otimes\beta}[X_{t+h} = x',Z_{t+h}=z' \, |\, X_t =x, Z_t=z] = \alpha_{x'}(t,x,z)\,\gamma^\beta_{z'}(t,x,z),
$$
where $\gamma^\beta(t,x,z)\in\Sigma^{d-1}$ denotes the probability distribution of a random variable $Z'(x,z,\beta(t))$, constructed as follows. Here, with an abuse of notation we let $\alpha\otimes\beta$ denote the joint control in which the tagged player uses $\alpha$ and all other players use $\beta$.  Fix a time $t\in\cT$, a position of the tagged player $x\in\cX$ and an empirical distribution $z\in\Sigma^{d-1}_N$ of untagged players. At time $t$ there are $Nz_y$ many untagged players in a state $y\in\cX$. Given that the tagged player is in state $x$, each untagged player in state $y$ chooses a next state independently according to the probability law $\beta(t,y,z+\frac{1}{N}(e_x-e_y))$ where $e_x\in\{0,1\}^d$ denotes the $x$th unit vector. It is clear that the distribution of these agents is given by the random variable $Z'(x,y,z,\beta(t))$ with 
$$
NZ'(x,y,z,\beta(t)) \sim \mathrm{Multinomial} (Nz_y,\beta(t,y,z+e^N_{xy})),\quad \text{where} \quad  e_{xy}^N:=\frac1N(e_x-e_y).
$$
We obtain the distribution of untagged players at time $t+h$ by summing over all possible states $y$:
\be \label{eq:multinomial}
Z'(x,z,\beta(t))=\sum_{y\in\cX}Z'(x,y,z,\beta(t)),
\ee
recalling that $\{Z'(x,y,z,\beta(t))\}_{y\in\cX}$ are independent. 

In the following, we will allow for restrictions on the class of admissible transition probabilities. 

\begin{Def}[and assumption]\label{def:adm-controls-finite-player}
For each $x\in\cX$ and $h>0$, let $A(h,x)$ be a closed, convex and non-empty subset of $\Sigma^{d-1}$. 
\begin{itemize}
\item The set of all \emph{admissible feedback rules} $\sA_N=\sA_N(h)$ is the set of all maps $\alpha: \cT\times\sX_N \to \Sigma^{d-1}$ such that $\alpha(t,x,z)\in  A(h,x) $ for all $(t,x,z)\in\cT\times\sX_N$. 
\item For each $x\in\cX$, let $S(x)\subset\cX$ denote the support of $A(h,x)$, i.e., $S(x)$ consists of all $y\in\cX$ such that there exists a transition probability $a\in A(h,x)$ with $a(y)>0$. We assume that $S(x)$ is independent of $h>0$.
\item We set $m:=\max_{x\in\cX} |S(x)|$.
\end{itemize}
\end{Def}

Our setting accommodates models with a \emph{minimum transition probability $h\sigma^2>0$} by setting $ A(h,x) \equiv A(h)$ with $A(h)= \{a\in\Sigma^{d-1}\,:\,a(y)\geq h\sigma^2 \ \forall y\in\cX\}$. We note that the upper bound $m=m(d)$ on the allowed transitions may depend on $d$.

\begin{Ex}\label{ex:nearest-neighbor-I}
For a nearest-neighbor model on the one-dimensional torus $S^1\cong[0,2\pi)$ we can let
$$
\cX= \Bigl\{0,\frac{2\pi}{d}, \frac{4\pi}{d},\ldots,\frac{(d-1)2\pi}{d} \Bigr\},\quad A(h,x) \subset \{a\in\Sigma^{d-1} \, : \, a_y=0\ \ \text{if}\ \ |y-x|>2\pi/d\}.
$$
Here, addition is defined modulo $2\pi/d$ and we have 
$$
S(x) = \{x-2\pi/d,x,x+2\pi/d\},\quad m=m(d)=3.
$$ 
\end{Ex}

To unify the treatment with the mean-field case, we let running and terminal cost functions be given,
$$
\ell: \sX \times [0,\infty)^{d}\to [0,\infty),\quad g:\sX\to [0,\infty),\quad \text{where}\quad \sX:=\cX\times\Sigma^{d-1}.
$$

Now, given a control $\beta=\beta(t,x,z)$, the tagged player minimizes its \emph{cost functional}
\be\label{eq:cost-functional-tagged-player}
J^N(t,x,z,\alpha;\beta)  := \E^{\alpha\otimes\beta} \Bigl[\sum_{t\leq s<T} \ell(X_s,Z_s,\alpha(s,X_s,Z_s)/h)h + g(X_T,Z_T)\,|\,(X_t,Z_t)=(x,z)\Bigr]
\ee
over $\alpha\in\sA_N$. We define the \emph{value function} of the tagged player by
\be\label{eq:value-function-tagged-player}
v^\beta(t,x,z):=\inf_{\alpha\in\sA_N}\ J^N(t,x,z,\alpha;\beta),\quad (t,x,z)\in\bar\cT\times\sX_N.
\ee


\begin{Def}[Symmetric Markov perfect equilibrium]
A \emph{symmetric Markov perfect (Nash) equilibrium} for the $(N+1)$-player game is characterized by a single feedback rule $\alpha^*\in\sA_N$ such that $J^N(t,x,z,\alpha^*;\alpha^*)=\inf_{\alpha\in\sA_N}\, J^N(t,x,z,\alpha;\alpha^*)$ for all $(t,x,z)\in\cT\times\sX_N$.
\end{Def}

In the same way that the Nash system characterizes Markov perfect equilibria, there is a single equation, which we call the \emph{Nash-Lasry-Lions equation}, whose solution corresponds to symmetric Markov perfect equilibria. It reads, for $(t,x,z)\in\bar \cT\times\sX_N$,
\begin{equation}\tag{$N$-NLL}\label{eq:N-NLL}
\left\{
\begin{split}
v(t,x,z)&= \underset{a\in  A(h,x) }{\inf} \, H(x,z,E(x,z,v(t+h),\alpha(t)),a), \quad 0\leq t\leq T,\\
\alpha(t,x,z) &= \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \, H(x,z,E(x,z,v(t+h),\alpha(t)),a),\quad 0\leq t<T,\\
v(T,x,z)&=g(x,z),
\end{split} 
\right.
\end{equation}
where, for $(\beta,\varphi):\sX_N\to\Sigma^{d-1}\times\R$,
$$
E(x,z,\varphi,\beta) := \bigl(\E[\varphi(y,Z'(x,z,\beta))]\bigr)_{y\in\cX} \in \R^d,
$$
the expectation is taken with respect to $Z'(x,z,\beta)$ introduced in equation \eqref{eq:multinomial}, and for $(x,z,v,a)\in\sX_N\times\R^d\times\Sigma^{d-1}$, we defined another Hamiltonian by 
\be\label{eq:NLL-hamiltonian}
H(x,z,v,a) = \ell(x,z,a/h)h +  a\cdot v.
\ee
The unknowns of equation \eqref{eq:N-NLL} are $(v,\alpha)$, and we note that $\alpha(t)$ appears on both sides of the equation in the second line.

The following assumption underlies most of our results in this paper. Recall the notation $\sX=\cX\times\Sigma^{d-1}$.

\begin{Asm}\label{asm:basic}
\begin{enumerate}[(i)]
\item (Continuity). The costs $\ell,g$ are continuous.
\item (Unique minimizer). \label{asm:basic-(ii)}
The function $ A(h,x) \ni a\mapsto\ell(x,\mu,a/h)h+a\cdot v$ admits a unique minimizer for fixed $h>0$ and $(x,\mu,v)\in\sX\times\R^d$.
\item (Boundedness).\label{asm:basic-(iii)}  The terminal cost $g$ is bounded. Furthermore, for every $(x,\mu,h)\in\sX\times(0,\infty)$, there exists an $a^*(x,\mu,h) \in A(h,x)$ such that 
$$
\limsup_{h\downarrow0}\sup_{(x,\mu)\in\sX} |\ell(x,\mu,a^*(x,\mu,h)/h)| h <\infty.
$$
\end{enumerate}
\end{Asm}

We further observe that the boundedness assumption implies that, for any $\beta\in\sA_N$, the value function $v^\beta$ is uniformly bounded in $(t,x,\mu,h)\in\cT\times\sX\times(0,\bar h)$ for any finite $\bar h<\infty$. If $\ell(x,\mu,\cdot)$ is quadratic in $a_{-x}$ and transition probabilities of the form $\sigma^2h$, for some $\sigma^2\geq0$, are admissible, then $a^*_y(x,\mu,h)=\sigma^2h$ for $y\neq x$ satisfies the above assumption. 


\begin{Rmk}[Correspondence]\label{rmk:correspondence-finite-player}
Under Assumption \ref{asm:basic}, standard results on dynamic programming (see Lemma \ref{lem:bellman}) imply that a given control $\alpha^*\in\sA_N$ is a symmetric Markov perfect equilibrium if and only if there exists a solution $v:\bar\cT\times\sX_N\to[0,\infty)$ to the \eqref{eq:N-NLL} equation with $\alpha=\alpha^*$.
\end{Rmk}

For our uniqueness results, we need the following stronger version of Assumption \ref{asm:basic} \eqref{asm:basic-(ii)}.


\begin{Asm}[Strong convexity of the running cost]\label{asm:convex-cost}
There exists a $\gamma>0$ such that 
\be\label{eq:asm-convex-cost}
\ell(x,\mu, a') \geq \ell(x,\mu,a)+ \phi\cdot ( a'-a) + \gamma | a'-a|_1| a'-a|_\infty
\ee
for all $(x,\mu,a, a')\in\sX\times[0,\infty)^{2d}$ and $\phi\in\partial_a\ell(x,\mu,a)$ that satisfy $a_y= a'_y=0$ for all $y\notin S(x)$ and $\sum_{y\in\cX} a_y= \sum_{y\in\cX} a'_y$ .  Here, $\partial_a\ell(x,\mu,a)$ denotes the subgradient of $\ell(x,\mu,\cdot)$ at the point $a$.
\end{Asm}


\begin{Rmk}
{\rm 
Recall $m$ from Definition \ref{def:adm-controls-finite-player}. Note that we have 
$$
A(h,x) \subset \{a\in\Sigma^{d-1} \, :\, |a|_0\leq m\},\quad \forall x\in\cX.
$$
If $m<d$, then this restricts the number of possible transitions at each state. Let $\ell:\sX\times \R^d\to[0,\infty)$ be a mapping that instead of \eqref{eq:asm-convex-cost} satisfies a standard definition of strong convexity with respect to the $|\cdot|_2$-norm,
$$
\ell(x,\mu, a')\geq \ell(x,\mu,a) +y\cdot ( a'-a) + \gamma_0 |a'-a|_2^2.
$$
Then, $\ell$ satisfies Assumption \ref{asm:convex-cost} with $\gamma = \gamma_0/\sqrt{m}$}. This follows by noting that $|a|_1|a|_\infty\leq \sqrt{|a|_0}|a|_2^2$ holds for any $a\in\R^d$.
\end{Rmk}

\begin{Ex}\label{ex:nearest-neighbor-II}
In the setting of Example \ref{ex:nearest-neighbor-I}, define a quadratic cost function  $\ell(x,a) = \frac12 \sum_{y\in S(x) \setminus\{x\}}a_y^2.$
Then Assumption \ref{asm:convex-cost} holds with
\begin{align*}
\ell(x, a')-\ell(x,a) &= \frac12 \sum_{y\in S(x)\setminus\{x\}}((a'_y)^2-a_y^2) = \nabla_a\ell(x,a)\cdot (a '-a)+ \frac12 \sum_{y\in S(x)\setminus\{x\}} (a'_y-a_y)^2\\
&\geq\nabla_a\ell(x,a)\cdot (a'-a) + \frac{1}{6} |a'- a|_2^2\geq \nabla_a\ell(x,a)\cdot (a'-a) + \frac{1}{6\sqrt{3}}|a'-a|_1|a'-a|_\infty,    
\end{align*}
for all $(a,\tilde a)\in\R^{2d}$ that satisfy 
$a_y=\tilde a_y=0$ for any $y\notin S(x)$ and $\sum_y\tilde a_y=\sum_ya'_y$. Note that $\nabla_a\ell(x,a)$ is a $d$-dimensional vector whose $x$th coordinate is $0$.
\end{Ex}


\begin{Thm}\label{thm:symmetric-Nash-system-and-sMPE}
Under Assumption \ref{asm:basic}, the following hold.
\begin{enumerate}[(i)]
% \item \label{thm:symmetric-Nash-system-and-sMPE-(i)} \emph{Correspondence:} Symmetric Markov perfect equilibria are in one-to-one correspondence with solutions to \eqref{eq:N-NLL}.
\item \label{thm:symmetric-Nash-system-and-sMPE-(i)} \emph{Existence:} Symmetric Markov perfect equilibria exist.
\item \label{thm:symmetric-Nash-system-and-sMPE-(ii)} \emph{Uniqueness:} In addition, let Assumption \ref{asm:convex-cost} hold. Then there exists $h_*(N,T)>0$ such that, for every $h<h_*(N,T)$, the solution $v$ to the Nash-Lasry-Lions equation \eqref{eq:N-NLL} is unique. 
\end{enumerate}
\end{Thm}

\begin{Rmk}
\rm{
 The proof of Theorem \ref{thm:symmetric-Nash-system-and-sMPE} \eqref{thm:symmetric-Nash-system-and-sMPE-(ii)} reveals that one can equivalently express the smallness condition on $h$ in terms of the convexity $\gamma$ of the running cost in the control variable $a$ being sufficiently large.
}
\end{Rmk}


Theorem \ref{thm:symmetric-Nash-system-and-sMPE} implies the following corollary.

\begin{Cor}
For $N\geq1$ and $h>0$, let $T^*(N,h)\in h\Z_+\cup\{\infty\}$ denote the maximal time duration such that \eqref{eq:N-NLL} has a unique solution on $\cT=\{0,h,\ldots,T^*(N,h)\}$. Then $T^*(N,h)\to\infty$ as $h\downarrow0$.
\end{Cor}



\subsection{The mean-field problem}

In the mean-field problem, a \emph{typical player} faces a continuum of agents that generate a flow of probability distributions. The assumption is that no player by itself influences the population distribution. At time $t\in\cT$ and state $x\in\cX$, a typical agent takes a flow of probability distributions $\boldsymbol\mu=(\mu_t,\ldots,\mu_T)$ as given and solves
\be\label{eq:MF-value-function}
\begin{split}
v(t,x;\boldsymbol\mu)&:= \inf_{\alpha\in\sA} \ J^\infty(t,x,\alpha;\boldsymbol\mu),\quad \text{where} \\
J^\infty(t,x,\alpha;\boldsymbol\mu)&:= \E^\alpha \Bigl[\sum_{t\leq s <T} \ell(X_s,\mu_s,\alpha(s,X_s)/h)h + g(X_T,\mu_T) \, | \, X_t=x
\Bigr],
\end{split}
\ee
and $\sA$ is the set of all feedback rules $\alpha: \cT\times\cX \to \Sigma^{d-1}$ such that $\alpha(t,x)\in  A(h,x) $ for all $(t,x)\in\cT\times\cX$. In the following, we write 
$$
\cT(t,T) := \{t,t+h,\ldots,T\}.
$$


\begin{Def}
A \emph{mean-field game (Nash) equilibrium (MFG-NE)}, started from $\mu\in\Sigma^{d-1}$ at time $t\in\cT$, is a measure flow $\boldsymbol\mu^*=(\mu^*_t,\ldots,\mu^*_T)$ such that there exists a control $\alpha^*\in\sA$ satisfying the following.
\begin{enumerate}[(i)]
\item Optimality: $J^\infty(t,x,\alpha^*;\boldsymbol\mu^*)\leq J^\infty(t,x,\alpha;\boldsymbol\mu^*)$ for any $\alpha\in\sA$ and any $x\in\cX$;
\item Consistency: For all $t\leq s\leq T$, we have
$$
\mu^*_s(x) = \sum_{y\in\cX} \mu(y) \, \P^{\alpha^*}[X_s=x\,|\,X_{t}=y],\quad x\in\cX.
$$
\end{enumerate}
\end{Def}

\begin{Rmk}
Instead of the measure flow $\boldsymbol\mu^*$, it is equivalent to define a solution to the mean-field game starting from $(t,\mu)$ in terms of a feedback control $\alpha^*\in\sA$ such that $J^\infty(t,x,\alpha^*;\boldsymbol\mu^*)\leq J^\infty(t,x,\alpha;\boldsymbol\mu^*)$ for any  $\alpha\in\sA$ and $x\in\cX$, where $\mu^*_t=\mu$ and $\mu^*_s=\P^{\alpha^*}\circ X_s^{-1}$ for all $t\leq s\leq T$.
\end{Rmk}

Consistent with the finite-player setting, we define the Hamiltonian $H$ by
$$
H(x,\mu,v,a) = \ell(x,\mu,a/h)h +  a\cdot v,\quad (x,\mu,v,a)\in\sX\times\R^d\times\Sigma^{d-1}.
$$
It is well known, see Remark \ref{rmk:MFG-system-correspondence} below, that Nash equilibria correspond to solutions of the forward-backward \emph{mean-field game system} consisting of dynamic programming and Kolmogorov equations for $x\in\cX$,
\begin{equation}\tag{MFG system}\label{eq:MFG-system}
\left\{
\begin{split}
v(s,x)&= \underset{a\in  A(h,x) }{\inf} \, H(x,\mu_s,v(s+h),a), \quad t\leq s\leq T,\\
\alpha(s,x) &= \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \ H(x,\mu_s,v(s+h),a), \quad t\leq s < T,\\
\mu_{s+h}(x) &= \sum_{y\in\cX}\mu_s(y)  \alpha_x(s,y),\quad t\leq s<T,\\
\mu_t&=\mu,\ v(T,x)=g(x,\mu_T).
\end{split}
\right.
\end{equation}

\begin{Rmk}[Correspondence] \label{rmk:MFG-system-correspondence}
More precisely, 
under Assumption \ref{asm:basic} and given initial data $(t,\mu)\in\cT\times\Sigma^{d-1}$, a measure flow $\boldsymbol{\mu}\in(\Sigma^{d-1})^{\cT(t,T)}$ is a MFG-NE starting from initial distribution $\mu$ at time $t$ if and only if there exists a function $v:\cT(t,T)\times\cX\to[0,\infty)$ such that $(v,\boldsymbol{\mu})$ solve the \ref{eq:MFG-system} with initial data $(t,\mu)$.
\end{Rmk}

Finally, we introduce a solution concept that is the mean-field analogue of the finite-player Markov perfect equilibria. To this end, we let $\sA_\infty$ be the set of all feedback rules $\bar\alpha: \cT\times\sX \to \Sigma^{d-1}$ such that $\bar \alpha(t,x,\mu)\in  A(h,x) $ for all $(t,x,\mu)$.  Fix an initial condition $(t,x)\in\cT\times\cX$ of a typical player and a distribution of the population $\boldsymbol{\mu}=(\mu_s)_{t\leq s\leq T}$. Given a control $\bar \alpha\in\sA_\infty$, define the control $\alpha^{\bar \alpha, \boldsymbol\mu}(s,x) := \bar \alpha(s,x,\mu_s)$
and set 
$$
J^\infty(t,x,\bar \alpha;\boldsymbol\mu) := J^\infty(t,x,\alpha^{\bar \alpha, \boldsymbol\mu};\boldsymbol\mu).
$$



\begin{Def}
A \emph{Markov perfect (Nash) equilibrium for the mean-field game (MF-MPE)} is a feedback policy $\bar \alpha \in\sA_\infty$ such that, for any $(t,x,\mu)\in\cT\times\sX$ and any control $\alpha\in\sA$, we have
$$
J^\infty(t,x,\bar \alpha;\boldsymbol\mu^{t,\mu,\bar \alpha})\leq J^\infty(t,x,\alpha;\boldsymbol\mu^{t,\mu,\bar \alpha}),
$$
with $\boldsymbol\mu^{t,\mu,\bar \alpha}$ being the distribution of $X$ under $\P^{\bar\alpha}$, i.e., for $t\leq s < T$,
$$
\mu_{s+h}^{t,\mu,\bar \alpha}(x) = \sum_{y\in\cX} \mu_{s}^{t,\mu,\bar \alpha}(y) \bar \alpha_x(s,y,\mu_{s}^{t,\mu,\bar \alpha}),\quad \mu^{t,\mu,\bar \alpha}_t=\mu.
$$
\end{Def}

If $\bar \alpha\in\sA_\infty$ is a Markov perfect equilibrium for the mean-field game, then the value function $V(t,x,\mu) = J^\infty(t,x,\bar \alpha; \boldsymbol\mu^{t,\mu,\bar \alpha})$
is characterized by the \emph{mean-field Nash-Lasry-Lions equation} or \emph{master equation}:
\begin{equation}\tag{MF-NLL}\label{eq:MF-NLL}
\left\{
\begin{aligned}
V(t,x,\mu) &= \underset{a\in  A(h,x) }{\inf} \,  H(x,\mu,V(t+h,\mu\cdot \bar \alpha(t,\cdot,\mu)),a), \quad 0\leq t\leq T, \\
\bar \alpha(t,x,\mu) &= \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \,H(x,\mu,V(t+h,\mu \cdot\bar \alpha(t,\cdot,\mu)),a), \quad 0\leq t< T,\\
V(T,x,\mu)&=g(x,\mu).
\end{aligned}
\right.
\end{equation}
Here, $(V,\bar\alpha)$ are the unknowns. We interpret $\mu$ as a row vector and $\bar\alpha(t,\cdot,\mu)\in\R^{d\times d}$ as a transition matrix so that each $\bar\alpha(t,y,\mu)$ is a row vector. 
By including the distribution of the population as a state variable, the following remark follows by dynamic programming.

\begin{Rmk}[Correspondence]\label{rmk:correspondence-MF-NLL}
Let Assumptions \ref{asm:basic} hold and let $ \bar\alpha \in\sA_\infty$. Then $ \bar\alpha $ is a MF-MPE if and only if there exists a function $V:\bar\cT\times\sX\to [0,\infty)$ such that $(V, \bar\alpha )$ satisfies \eqref{eq:MF-NLL}.
\end{Rmk}

\begin{Prop}\label{prop:MFG-NE and MF-NLL}
Let Assumptions \ref{asm:basic} hold and fix an initial condition $(t,\mu)\in\cT\times\Sigma^{d-1}$.
\begin{enumerate}[(i)]
% \item \label{prop:MFG-NE and MF-NLL-(i)} Mean-field game equilibria correspond to solutions of the \ref{eq:MFG-system}.
\item \label{prop:MFG-NE and MF-NLL-(i)} There exist a solution to the mean-field game starting from $\mu$ at time $t$. 
\item \label{prop:MFG-NE and MF-NLL-(ii)} Let $(V,\bar\alpha)$ be a solution to \eqref{eq:MF-NLL}. Then, the flow $(\mu^*_s)_{t\leq s\leq T}$, defined by
$$
\mu^*_{t} := \mu,\quad \mu^*_{s+h}(x) := \sum_{y\in\cX} \mu^*_s(y)\bar\alpha_x(s,y,\mu^*_s),\quad v^*(s,x):=V(s,x,\mu^*_s),
$$
is a solution to the \ref{eq:MFG-system}.
\end{enumerate}
\end{Prop}


