\subsection{Short-time results}

We proceed to provide conditions under which there exists a unique mean-field MPE, or equivalently, a unique solution to the mean-field NLL equation.

\begin{Asm}[Lipschitzness] \label{asm:lipschitz-cost}
There exist $0\leq L_\ell,L_g,L_{\partial\ell}<\infty$ such that, for every $(x,a,\mu,\tilde\mu)\in\cX\times [0,\infty)^d\times \Sigma^{d-1}\times\Sigma^{d-1}$ and $w\in\partial_a\ell(x,\mu,a)$, $\tilde w\in\partial_a\ell(x,\tilde \mu, a)$, we have
\begin{align*}
|\ell(x,\tilde \mu, a)-\ell(x,\mu,a)| \leq L_\ell |\tilde \mu-\mu|_1,  \ \sum_{y\in S(x)}  \!\! |\tilde w(y)-w(y)| \leq L_{\partial\ell} |\tilde \mu-\mu|_1, \ |g(x,\tilde \mu)-g(x, \mu)| \leq L_g |\tilde \mu-\mu|_1.
\end{align*}
As before, $\partial_a\ell(x,\mu,a)$ refers to the subgradient of $\ell(x,\mu,\cdot)$ at the point $a$.
\end{Asm}

Under these assumptions, we have the following existence and uniqueness result in short time, for both the finite-player and mean-field problems.

\begin{Thm}\label{thm:well-posedness-MF-NLL}
Let Assumptions \ref{asm:basic}, \ref{asm:convex-cost} and \ref{asm:lipschitz-cost} hold. Then there exist constants $h_*,T_*>0$, depending on the data and $m=m(d)$ but not on the number of players $N+1$, such that, whenever $h<h_*$ and $Kh<T_*$, there exists a unique solution to \eqref{eq:MF-NLL} and \eqref{eq:N-NLL} on $\bar\cT=\{0,h,\ldots,Kh\}$, for any $N\geq1$.
\end{Thm}


\subsection{Mean-field convergence} \label{ssec:mean-field-convergence}

Fix the time horizon $T$ and step size $h$. For each $N$, any solution $(v^{(N)},\alpha^{(N)})$  to \eqref{eq:N-NLL} is extended from $\bar\cT\times\sX_N$ to $\bar \cT\times\sX$ by linear interpolation in the $z$-variable. 

\begin{Thm}\label{thm:N-convergence}
Let the assumptions of Theorem \ref{thm:well-posedness-MF-NLL} hold, and let $h_*,T_*$ be as in that theorem. Let $h<h_*$ and $Kh<T_*$ be given. Let $(v^{(N)},\alpha^{(N)})$ solve \eqref{eq:N-NLL} and let $(V,\alpha)$ be the solution to \eqref{eq:MF-NLL}. Set $\bar\cT=\{0,h,\ldots,Kh\}$. Then the following hold:
\begin{enumerate}[(i)]
\item (Convergence of values) As $N\to\infty$, $ v^{(N)}\to V$ on $\bar\cT\times\sX$ uniformly.
\item (Convergence of MPE) As $N\to\infty$, $ \alpha^{(N)}\to \alpha$ on $\cT\times\sX$ uniformly.
\end{enumerate}
\end{Thm}




\subsection{Continuous-time limit} \label{ssec:continuous-limit}

We now fix the time horizon $T$ and the number of players $N+1$, and we consider the continuous-time limit $h\downarrow 0$. We continue to briefly define the limiting problem and refer to \cite{GMS1} for a detailed discussion. In the continuous-time model, players' state processes follow a time-inhomogeneous continuous-time Markov chain, which, by an abuse of notation, we again denote by $(X_t,Z_t)$. For a given \emph{thermal noise} level $\sigma^2\geq0$, let $\beta\in\sA_{\mathrm{cts}}$ be an \emph{admissible feedback control}, that is, a Lipschitz continuous function $\beta:[0,T]\times\sX_N\to\R^d$ satisfying, for any $(t,x,z)\in[0,T]\times\sX_N$, 
$$
\beta_{x'}(t,x,z)\geq\sigma^2\quad  \text{for all} \  x'\in\cX\setminus\{x\} \    \text{and}\quad \beta_x(t,x,z)=-\sum_{y\neq x}\beta_y(t,x,z).
$$
Here, $\beta_{x'}(t,x,z)$ is the rate of changing from the current state $x\in\cX$ to a state $x'\neq x$ at time $t\in[0,T]$, given that the empirical distribution of other players is $z\in\Sigma^{d-1}_N$. Given a control $\alpha\in\sA_{\mathrm{cts}}$ of the tagged player and a control $\beta\in\sA_{\mathrm{cts}}$ used by all other players, for any $(t,x,z)\in[0,T]\times\sX_N$ and $y,w,x'\in\cX$, we have
$$
\P^{\alpha\otimes\beta}[X_{t+\Delta t} = x' \, |\, (X_t,Z_t)=(x,z)] = \alpha_{x'}(t,x,z) \, \Delta t + o(\Delta t),\quad \text{as} \ \Delta t \downarrow0,
$$
and
$$
\P^{\alpha\otimes\beta}[Z_{t+\Delta t} = z+ e^N_{wy} \, |\, (X_t,Z_t)=(x,z)] = Nz_y \beta_w(t,y,z+e^N_{xy}) \, \Delta t + o(\Delta t),\quad \text{as} \ \Delta t \downarrow0,
$$
where we recall the definition $e^N_{xy}=\frac1N(e_x-e_y)$ and $o(\Delta t)/\Delta t\to0$ as $\Delta t\downarrow0$. The tagged player solves
\begin{equation*}
\begin{split}
v^\beta_{\mathrm{cts}}(t,x,z)&:= \inf_{\alpha\in\sA_{\mathrm{cts}}}  \ \ J_{\mathrm{cts}}(t,x,z,\alpha;\beta),\quad \text{where} \\
J_{\mathrm{cts}}(t,x,z,\alpha;\beta) &:= \E^{\alpha\otimes\beta} 
\Bigl[
\int_t^T\ell(X_s,Z_s,\alpha(s,X_s,Z_s))\,\d s + g(X_T,Z_T) \, | \, (X_t,Z_t)=(x,z)
\Bigr].
\end{split}
\end{equation*}
In full analogy with the discrete-time definition, a control $\alpha^*\in\sA_{\mathrm{cts}}$ is called a \emph{Markov perfect (Nash) equilibrium (MPE)} if
$$
J_{\mathrm{cts}}(t,x,z,\alpha^*;\alpha^*) \leq J_{\mathrm{cts}}(t,x,z,\alpha;\alpha^*)\quad \forall \alpha\in\sA_{\mathrm{cts}} \ \forall (t,x,z)\in [0,T]\times \sX_N.
$$
To define the NLL equation, we make the following explicit assumption.
\begin{Asm}\label{asm:cost-2}
For every $(x,\mu,a)\in\sX\times[0,\infty)^d$, the running cost $\ell(x,\mu,a)$ is independent of $a_x$.
\end{Asm}

Given $\beta:\sX_N\to\R^d$, we define the generator $\sL^\beta$ of the process $Z_t$ by 
$$
(\sL^\beta\varphi)(x,z) := \sum_{w\neq y, \, w,y\in\cX} Nz_y \beta_w(y,z+e^N_{xy}) [\varphi(x,z+e^N_{wy})-\varphi(x,z)],\quad (x,z)\in\sX_N,
$$
for any $\varphi:\sX_N\to\R$, 
and we define the Hamiltonian $\cH$ by
$$
\cH(x,z,v,a) :=  \ell(x,z,a) + a\cdot v,\quad (x,z,v,a)\in\sX_N\times\R^{d-1}\times[0,\infty)^{d-1}.
$$
Finally, we denote the minimizer of the Hamiltonian by $\hat \alpha:\sX_N\times\R^{d-1}\to\R^d$, i.e.,
$$
(\hat\alpha_{y}(x,z,v))_{y\in\cX\setminus\{x\}} := \underset{a\in[\sigma^2,\infty)^{d-1}}{\mathrm{arg\,min}} \ \cH(x,z,v,a)\quad \text{and}\quad  \hat\alpha_x(x,z,v) := -\sum_{y\neq x} \hat\alpha_{y}(x,z,v).
$$
Gomes, Mohr and Souza \cite{GMS1} show that there is a unique MPE which corresponds to the unique classical solution $v_{\mathrm{cts}}:[0,T]\times\sX_N\to[0,\infty)$ of the following continuous-time finite-player NLL equation, 
\be\label{eq:cts-time-finite-player-NLL}
\left\{
\begin{split}
-\frac{\d}{\d t} v_{\mathrm{cts}}(t,x,z) &= \underset{a\in[\sigma^2,\infty)^{d-1}}{\inf}\cH(x,z,\Delta_x v_{\mathrm{cts}}(t,\cdot,z),a)+ \sL^{\alpha_{\mathrm{cts}}(t)} v(t) (x,z),\\
\alpha_{\mathrm{cts}}(t,x,z) &= \hat\alpha(x,z,\Delta_xv_{\mathrm{cts}}(t,\cdot,z)),\\
v_{\mathrm{cts}}(T,x,z)&=g(x,z).
\end{split}
\right.
\ee
Here, we used the notation
$$
\Delta_x\varphi := (\varphi(y)-\varphi(x))_{y\neq x}\in\R^{d-1}
$$
for any $\varphi:\cX\to\R$.
We continue to state our convergence result. For $K\geq1$, define $h=h^{(K)}:=T/K$ and $\bar\cT^{(K)}:=\{0,h,\ldots,(K-1)h,T\}$ and $A(h)=A(h,x)=\{a\in\Sigma^{d-1}:a_y\geq h\sigma^2\ \forall y\in\cX\}$. For sufficiently large $K$, let $(v^{(K)},\alpha^{(K)})$ be the unique solution to the \eqref{eq:N-NLL} equation on $\bar\cT^{(K)}$, with the aforementioned choice of $A(h)$, and extend $(v^{(K)},\alpha^{(K)})$ to $[0,T]\times\sX_N$ by linear interpolation in the time variable. Set $$
\mathfrak{a}^{(K)}(t,x,z):=\alpha^{(K)}(t,x,z)-e_x,\quad (t,x,z)\in[0,T]\times\sX_N,\ K\geq1.
$$

\begin{Thm}\label{thm:continuous-convergence}
Under Assumptions \ref{asm:basic}, \ref{asm:convex-cost}, \ref{asm:lipschitz-cost} and \ref{asm:cost-2}, we have the following.
\begin{enumerate}[(i)]
\item (Convergence of values) As $K\to\infty$, $v^{(K)}\to v_{\mathrm{cts}}$ uniformly on $[0,T]\times\sX_N$.
\item (Convergence of MPE) As $K\to\infty$, $\mathfrak{a}^{(K)}/h^{(K)}\to \alpha_{\mathrm{cts}}$ uniformly on $[0,T]\times\sX_N$.
\end{enumerate}
\end{Thm}


\subsection{Comparison with existing works} \label{ssec:literature}

We study stochastic finite-player and mean-field games in discrete time and space, where players control transition probabilities over a finite time horizon. Similar settings have been explored in the literature. For instance, Saldi, Ba\c{s}ar and Raginsky \cite{SBR} examine a mean-field game on a general state space with a discounted infinite-horizon cost functional. Doncel, Gast and Gaujal \cite{doncel2019discrete} consider both discrete and continuous-time problems, but with finite action spaces. Our setup is closest to Gomes, Mohr and Souza \cite{GMS2} who study the exponential convergence of a discrete-time mean-field game to its stationary solution.

In Remarks \ref{rmk:correspondence-finite-player} and \ref{rmk:correspondence-MF-NLL}, we first clarify the connection between symmetric Markov perfect equilibria and the Nash-Lasry-Lions equation, both in the finite-player and mean-field formulations. In the finite-player case, this relationship has been observed, for example by Gomes, Mohr and Souza \cite{GMS1} for a reference close to our setting. 

Next, we address the existence and uniqueness of MPE in our finite-player and mean-field problems, see Theorem \ref{thm:symmetric-Nash-system-and-sMPE}. Existence follows from well-known fixed-point arguments, see for example Gomes, Mohr and Souza \cite{GMS2}, while our uniqueness proof relies on a contraction argument and uses the smallness of the time step. This result sheds light on the relationship with the continuous-time problem, which in the finite-player case becomes uniquely solvable, see \cite{GMS1}. In the mean-field, we obtain short-time results in Theorem \ref{thm:well-posedness-MF-NLL}, which can be made global under monotonicity assumptions. In this regard, our work is related to the pasting of equilibria by Dianetti, Nendel, Tangpi and Wang \cite{dianetti2024pasting}, who utilize a discrete-time master equation approach under Lasry-Lions monotonicity, see Remark \ref{rmk:monotonicity} below.

Finally, we present convergence results of the finite-player game in Theorems \ref{thm:N-convergence} and \ref{thm:continuous-convergence}, both as the number of players $N+1$ goes to infinity and as the time discretization $h$ goes to zero.  The former parallels the results obtained in \cite{GMS1} in continuous-time while in the latter limit we recover the uniquely solvable finite-player NLL equation in \cite{GMS1}.


\vspace{1em}
\textbf{Structure.} The rest of the paper is structured as follows. In Section \ref{sec:sym-finite-player} we investigate the symmetric finite-player problem and establish Theorem \ref{thm:symmetric-Nash-system-and-sMPE}. Section \ref{sec:mean-field-problem} discusses the mean-field problem and proves Proposition \ref{prop:MFG-NE and MF-NLL}. The short-time results recorded in Theorem \ref{thm:well-posedness-MF-NLL} for both finite-player and mean-field games are obtained in Section \ref{sec:short-time}. The mean-field limit $N\to\infty$, see Theorem \ref{thm:N-convergence}, is presented in Section \ref{sec:mean-field-convergence}, and the continuous-time limit $h\downarrow0$, see Theorem \ref{thm:continuous-convergence}, is treated in Section \ref{sec:continuous-limit}. We recall some basic facts about dynamic programming in discrete time in Appendix \ref{app:dynamic-progamming} and prove a generalized conjugate correspondence theorem in Appendix \ref{app:conjugate-correspondence}.

\section{The symmetric finite-player problem}\label{sec:sym-finite-player}
This section proves Theorem \ref{thm:symmetric-Nash-system-and-sMPE}. While the proof of \eqref{thm:symmetric-Nash-system-and-sMPE-(i)} rely on results in dynamic programming and an application of Brouwer's fixed-point theorem, the analysis for part \eqref{thm:symmetric-Nash-system-and-sMPE-(ii)} makes crucial use of a Lipschitz property of the multinomial distribution presented in Lemmas \ref{lem:lipschitz-multinom-I}, \ref{lem:lipschitz-multinom-II}. 

\subsection{Existence}

We continue to establish the existence of symmetric MPE as claimed in Theorem \ref{thm:symmetric-Nash-system-and-sMPE} \eqref{thm:symmetric-Nash-system-and-sMPE-(i)} using a classical fixed-point argument.



\begin{proof}[Proof of Theorem \ref{thm:symmetric-Nash-system-and-sMPE} \eqref{thm:symmetric-Nash-system-and-sMPE-(i)}]
We define a map $\Phi:\sA_N\to\sA_N$ by the following procedure. For a given control $\beta\in\sA_N$ of the other players, let $\alpha=\alpha(\beta)\in\sA_N$ be the optimal unique feedback control of the tagged player. By Lemma \ref{lem:bellman}, $\alpha$ can be computed using the dynamic programming equation
$$
\begin{cases}
v^\beta(t,x,z)= \underset{a\in  A(h,x) }{\inf} \, H(x,z,E(x,z, v^\beta(t+h),\beta(t)),a), \quad 0\leq t\leq T,\\
\alpha(t,x,z) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \ H(x,z,E(x,z, v^\beta(t+h),\beta(t)),a),\quad 0\leq t<T,\\
v^\beta(T,x,z)=g(x,z),
\end{cases} 
$$
by backward recursion. Then set $\Phi(\beta):= \alpha$. Using Berge's maximum theorem, it is easy to see that $\Phi$ is a continuous mapping. Since $\sA_N$ is a convex compact set, Brouwer's fixed-point theorem guarantees the existence of a fixed point. By Remark \ref{rmk:correspondence-finite-player} any fixed point corresponds to a symmetric Markov perfect equilibrium.
\end{proof}


\subsection{Uniqueness}
By Remark \ref{rmk:correspondence-finite-player}, uniqueness of symmetric MPE is equivalent to uniqueness of solutions to \eqref{eq:N-NLL}. By (backward) induction, it is equivalent to uniqueness in one-step games. More precisely, it is sufficient to show that, for any $\varphi:\sX_N\to\R$, there exists a unique map $\hat \alpha:\sX_N\to\Sigma^{d-1}$ satisfying the fixed-point equation
$$
\hat \alpha(x,z) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \ H(x,z,E(x,z,\varphi,\hat \alpha),a),\quad (x,z)\in\sX_N.
$$
We prove this using Banach's fixed-point theorem in Proposition \ref{prop:finite-player-one-step} below. To this end, recall from \eqref{eq:multinomial} that $Z'(x,z,\alpha)$ is defined as the sum of $d$ independent random variables $Z'(x,1,z,\alpha),\ldots,Z'(x,d,z,\alpha)$ with
$$
NZ'(x,y,z,\alpha) \sim \mathrm{Multinomial} (Nz_y,\alpha(y,z+e^N_{xy})),\quad y\in\cX.
$$

We now provide two Lipschitz estimates involving $Z'(x,z,\alpha)$.

\begin{Lem}\label{lem:lipschitz-multinom-I}
For any maps $\alpha,\tilde\alpha:\sX_N\to\Sigma^{d-1}$, we have
$$
\max_{(x,z)\in\sX_N} \E|Z'(x,z,\alpha)-Z'(x,z,\tilde \alpha)|_1 \leq  \max_{(x,z)\in\sX_N} |\alpha(x,z)-\tilde\alpha(x,z)|_1.
$$
\end{Lem}

\begin{proof}
First note that if $\eta\sim\mathrm{Multinomial}(n,p)$ for some $n\geq1$, $p\in\Sigma^{d-1}$, then for every coordinate $j\in\cX$,
$$
\eta_j \overset{d}{=} \sum_{i=1}^n  \chi_{[0,p_j]}(\xi^i) \in \Z_+,
$$
where $\{\xi^i\}$ are independent $\mathrm{Uniform}(0,1)$ variables. Now fix $j\in\cX$ and $(x,z)\in\sX_N$, let $\{\xi^i_y\}$ be a collection of independent $\mathrm{Uniform}(0,1)$ random variables, and write
\begin{align*}
Z'_j(x,z,\alpha)-Z'_j(x,z,\tilde \alpha) &= \sum_{y\in\cX} (Z'_j(x,y,z,\alpha)-Z'_j(x,y,z,\tilde \alpha))\\
&\overset{d}{=} \frac1N \sum_{y\in\cX} \sum_{i=1}^{Nz_y}(\chi_{[0,\alpha_j(y,z+e^N_{xy})]} -  \chi_{[0,\tilde \alpha_j(y,z+e^N_{xy})]} 
)(\xi^i_y).
\end{align*}
Taking expectations,
\begin{align*}
\E|Z'(x,z,\alpha) -Z'(x,z,\tilde\alpha)|_1 &=\sum_{j\in\cX} \E|Z'_j(x,z,\alpha) -Z'_j(x,z,\tilde \alpha)|\\
&\leq\frac{1}{N} \sum_{j\in\cX}\sum_{y\in\cX}
 \sum_{i=1}^{Nz_y} \, \E|(\chi_{[0,\alpha_j(y,z+e^N_{xy})]} -  \chi_{[0,\tilde \alpha_j(y,z+e^N_{xy})]} 
)(\xi^i_y)|\\
&= \sum_{y\in\cX}  z_y|\alpha(y,z+e^N_{xy}) - \tilde \alpha(y,z+e^N_{xy})|_1\\
&\leq \Bigl(\sum_{y\in\cX} z_y \Bigr) \max_{(x,z)\in\sX_N} \, |\alpha(x,z)-\tilde\alpha(x,z)|_1 \\
&= \max_{(x,z)\in\sX_N} \, |\alpha(x,z)-\tilde\alpha(x,z)|_1.
\end{align*}
Taking the maximum over $(x,z)$ finishes the proof.
\end{proof}

\begin{Lem}\label{lem:lipschitz-multinom-II}
For any map $\alpha:\sX_N\to\Sigma^{d-1}$ and any $z,\tilde z\in\Sigma^{d-1}_N$, we have
$$
\max_{x\in\cX} \, \E|Z'(x, z,\alpha)-Z'(x,\tilde z,\alpha)|_1\leq  (1+\max_{x\in\cX} \, \Lip_1(\alpha(x,\cdot)) )\,|z-\tilde z|_1.
$$
\end{Lem}

\begin{proof}
Using the same notation as in the proof of the previous lemma, for any $x\in\cX$,
\begin{align*}
\E|Z'(x, z,\,\alpha)-Z'(x,\tilde z,\alpha)|_1&= \sum_{j\in\cX} \E|Z'_j(x,z,\alpha)-Z'_j(x,\tilde z, \alpha)|\\
&\leq\frac1N \sum_{j\in\cX} \sum_{y\in\cX}\sum_{i=1}^{N(z_y\land\tilde z_y)} \E|(\chi_{[0,\alpha_j(y,z+ e^N_{xy} )]} -  \chi_{[0, \alpha_j(y,\tilde z+ e^N_{xy} )]})(\xi^i_y)|\\
&+ \sum_{j\in\cX} \sum_{y\in\cX}\Bigl((z_y-\tilde z_y)^+ \,\alpha_j(y,z+ e^N_{xy} )+ ( z_y-\tilde z_y)^-\,\alpha_j(y,\tilde z+ e^N_{xy} )\Bigr)\\
&= \sum_{y\in\cX} (z_y\land \tilde z_y)  |\alpha(y,z+ e^N_{xy} )-\alpha(y,\tilde z+ e^N_{xy} )|_1+ |z-\tilde z|_1\\
&\leq \Bigl(1+ \sum_{y\in\cX} (z_y\land \tilde z_y) \Lip_1(\alpha(y,\cdot)) \Bigr)  |z-\tilde z|_1\\
&\leq  \, (1+\max_{y\in\cX} \Lip_1(\alpha(y,\cdot)) )\,|z-\tilde z|_1. \qedhere
\end{align*}
\end{proof}

We note the following version of the conjugate correspondence theorem, whose proof is given in Appendix \ref{app:conjugate-correspondence}.

\begin{Lem}[Variant of the conjugate correspondence theorem] \label{lem:convex-conjugates}
Let $f:\R^d\to (-\infty,\infty]$ be a proper, closed and convex function. Let $C\subset\dom(f)$ be a non-empty, closed and convex set. Fix $p,q\in[1,\infty]$ with $1/p+1/q=1$ and assume that there exists a $\gamma>0$ such that  
\be\label{eq:lem-convex-conjugate}
f(x')\geq f(x)+\phi \cdot (x'-x) + \gamma |x'-x|_p|x'-x|_q
\ee
for any $x,x'\in C$ and $\phi\in\partial f(x)$. Set
$$
\psi(y) = \underset{x\in C}{\mathrm{arg\,max}} \{y\cdot x-f(x)\} ,\quad y\in\R^d.
$$
Then, $\psi$ is single-valued and is Lipschitz continuous with constant $1/\gamma$, with respect to both $|\cdot|_p$ and $|\cdot|_q$.
\end{Lem}

We are now ready to prove existence and uniqueness for one-step games.  We recall the constant $\gamma$ from Assumption \ref{asm:convex-cost}, $S(x)$ and $m=m(d)$ from Definition \ref{def:adm-controls-finite-player}, and the constant $L_{\partial\ell}$ from Assumption \ref{asm:lipschitz-cost}.


\begin{Prop}\label{prop:finite-player-one-step}
Let Assumptions \ref{asm:basic}  and \ref{asm:convex-cost} hold. Then, for any $\varphi:\sX_N\to\R$, there exists a unique function $\hat\alpha:\sX_N\to\Sigma^{d-1}$ that satisfies
$$
\hat \alpha(x,z) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \, H(x,z,E(x,z,\varphi,\hat \alpha),a),\quad \forall (x,z)\in\sX_N,
$$
provided that $h<\gamma/L_\varphi$, where $L_\varphi:= m \max_{x\in\cX}\Lip_1(\varphi(x,\cdot))$.  In addition, let Assumption \ref{asm:lipschitz-cost} hold. Then,
$$
\max_{x\in\cX} \, \Lip_1(\hat\alpha(x,\cdot)) \leq \frac{h(L_{\partial\ell}+ L_\varphi)}{\gamma-h L_\varphi}.
$$
\end{Prop}

\begin{proof}
Define
$$
\cS:=\{\alpha:\sX_N\to \Sigma^{d-1}\,:\,\alpha_y(x,z)=0\ \forall y\notin S(x), \, \forall (x,z)\in\sX_N\},
$$
For $\alpha\in \cS$, set $|\alpha|_\cS=\max_{(x,z)\in\sX_N}|\alpha|_1$,
$$
\Phi_{x,z}(\alpha):=\underset{a\in  A(h,x) }{\mathrm{arg\,min}} \, H(x,z,E(x,z,\varphi,\alpha),a) \quad \text{and}\quad \Phi(\alpha):= (\Phi_{x,z}(\alpha))_{(x,z)\in\sX_N}.
$$
Now let $(x,z)\in\sX_N$ be given. Define a function $f:\R^d\to[0,\infty]$ by $f(a):=\ell(x,z,a/h)h$ for $a\in[0,\infty)^d$ and $+\infty$ otherwise. Set $C:=A(h,x)$. By Assumptions \ref{asm:basic} and \ref{asm:convex-cost}, $f$ is a proper, closed and convex function. Using Assumption \ref{asm:convex-cost} and the fact that any element $a\in C$ satisfies $\sum_{y\in\cX}a_y=1$ and $a_y=0$ for all $y\notin S(x)$, we see that  
\be\label{eq:finite-player-one-step-(i)}
f(a')\geq f(a) + \phi\cdot (a'-a) + \frac{\gamma}{h} | a'-a|_1| a'-a|_\infty,\quad \forall (a, a')\in C\times C,\, \forall \phi\in\partial f(a).
\ee
Hence $f$ satisfies the conditions of Lemma \ref{lem:convex-conjugates}. Let $\alpha,\tilde\alpha\in \cS$ be given.
Observe that
$$
\Phi_{x,z}( \alpha)  =  \underset{a\in  \R^d }{\mathrm{arg\,max}} \, \Bigl\{\sum_{y\in S(x)}\! a_y \, (-\E[\varphi(y,Z'(x,z,\alpha))]) -f(a) \Bigr\}.
$$
By \eqref{eq:finite-player-one-step-(i)} and Lemma \ref{lem:convex-conjugates},
$$
|\Phi_{x,z}( \alpha)-\Phi_{x,z}(\tilde \alpha)|_1\leq \frac{h}{\gamma}\sum_{y\in S(x)}\E|\varphi(y,Z'(x,z,\alpha))- \varphi(y,Z'(x,z,\tilde\alpha))|.
$$
Using Lemma \ref{lem:lipschitz-multinom-I},
\begin{align*}
\sum_{y\in S(x)} \E|\varphi(y,Z'(x,z,\alpha)) - \varphi(y,Z'(x,z,\tilde\alpha))| 
&\leq  \sum_{y\in S(x)} \Lip_1(\varphi(y,\cdot))\, \E|Z'(x,z,\alpha) - Z'(x,z,\tilde\alpha)|_1\\
&\leq m \, \max_{y\in\cX} \Lip_1(\varphi(y,\cdot)) \ \E|Z'(x,z,\alpha) - Z'(x,z,\tilde\alpha)|_1\\
&\leq  L_\varphi\, \max_{(x,z)\in\sX_N} |\alpha(x,z)-\tilde\alpha(x,z)|_1\\
&= L_\varphi\, \max_{(x,z)\in\sX_N} \sum_{y\in S(x)}|\alpha_y(x,z)-\tilde\alpha_y(x,z)|,
\end{align*}
with $L_\varphi= m \max_{y\in\cX}\Lip_1(\varphi(y,\cdot))$. We conclude that
$$
|\Phi(\alpha)-\Phi(\tilde\alpha)|_\cS \leq \frac{h}{\gamma} \max_{(x,z)\in\sX_N} \sum_{y\in S(x)}\E|\varphi(y,Z'(x,z,\alpha))-\varphi(y,Z'(x,z,\tilde\alpha))|\leq \frac{L_\varphi h}{\gamma}  |\alpha-\tilde\alpha|_\cS.
$$
Hence, $\Phi(\cdot)$ is a contraction if $h<\gamma/L_\varphi$, in which case Banach's fixed-point theorem guarantees  the uniqueness of a fixed point $\hat \alpha\in\cS$. 

We proceed to establish an upper bound of the Lipschitz constant of $\hat\alpha(x,\cdot)$. Fix $z,\tilde z\in\Sigma^{d-1}_N$. By Assumption \ref{asm:convex-cost}, for any $a,\tilde a\in A(h,x)$ and $\tilde w\in\partial_a\ell(x,\tilde z,a/h)\subset\R^d$,
$$
\ell(x,\tilde z,\tilde a/h)h \geq \ell(x,\tilde z,a/h)h+\tilde w\cdot (\tilde a-a) + \frac{\gamma}{h}|\tilde a -a|_1\,|\tilde a-a|_\infty,
$$
which leads to
\begin{align*}
H(x,\tilde z,&\,E(x,\tilde z,\varphi,\hat \alpha), \tilde a)=
\ell(x,\tilde z,\tilde a/h)h + \tilde a \cdot E(x, \tilde  z,\varphi,\hat\alpha) \\
&\geq \ell(x,\tilde z,a/h)h + a\cdot E(x,\tilde z,\varphi,\hat\alpha) +[\tilde w +E(x, \tilde  z,\varphi,\hat\alpha)]\cdot (\tilde a-a)+\frac{\gamma}{h}|\tilde a -a|_1\,|\tilde a-a|_\infty \\
&= H(x,\tilde z,E(x, \tilde z,\varphi,\hat\alpha),a) + [\tilde w +E(x, \tilde  z,\varphi,\hat\alpha)]\cdot (\tilde a-a) + \frac{\gamma}{h} |\tilde a -a|_1\,|\tilde a -a|_\infty.
\end{align*}
Now we apply this to  $a=\hat\alpha(x,z)$ and $\tilde a=\hat\alpha(x,\tilde z)$. By the definition of $\hat\alpha(x,\tilde z)$ as a minimizer of $H(x,\tilde z,E(x,\tilde  z,\varphi,\hat \alpha),\cdot\,;\hat \alpha)$,
\begin{align*}
H(x,\tilde z,E(x,\tilde  z,\varphi,\hat \alpha),\hat\alpha(x,z)) &\geq H(x,\tilde z,E(x,\tilde  z,\varphi,\hat \alpha),\hat\alpha(x,\tilde z))\\
&\geq H(x,\tilde z,E(x,\tilde z,\varphi,\hat \alpha),\hat\alpha(x,z))  \\
&\quad +[\tilde w+ E(x,\tilde z,\varphi,\hat\alpha)] \cdot (\hat\alpha(x,\tilde z) - \hat \alpha(x,z)) \\
&\quad + \frac{\gamma}{h}|\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_1\, |\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_\infty.
\end{align*}
As $\hat\alpha(x,z)$ minimizes $H(x, z,E(x,z,\varphi,\hat \alpha),\,\cdot\,)$, by \cite[Corollary 3.68]{FOMO} there exists a $w\in\partial_a\ell(x,z,\hat\alpha(x,z)/h)$ such that 
$$
(w+ E(x,z,\varphi,\hat\alpha)) \cdot (\hat\alpha(x,\tilde z)-\hat\alpha(x,z)) \geq0.
$$
Combining the last two inequalities,
\begin{align*}
0&\geq [\tilde w+ E(x,\tilde z,\varphi,\hat \alpha)] \cdot (\hat\alpha(x,\tilde z) - \hat \alpha(x,z)) + \frac{\gamma}{h} |\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_1\, |\hat\alpha(x,\tilde z) - \hat\alpha(x,z)|_\infty\\
&\geq [\tilde w  -w + E(x,\tilde z,\varphi,\hat\alpha) -   E(x, z,\varphi,\hat\alpha) ] \cdot (\hat\alpha(x,\tilde z) - \hat \alpha(x,z)) +\frac{\gamma}{h}|\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_1\, |\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_\infty.
\end{align*}
By Lemma \ref{lem:lipschitz-multinom-II},
\begin{align*}
\sum_{y\in S(x)}\E| \varphi(y,Z'(x,\tilde z,\hat\alpha))- \varphi(y,Z'(x,z,\hat\alpha))| &\leq L_\varphi\ \E|Z'(x,\tilde z,\hat\alpha)-Z'(x,z,\hat\alpha)|_1\\
&\leq L_\varphi\ (1+\max_{x\in\cX} \Lip_1(\hat \alpha(x,\cdot)) )\,|z-\tilde z|_1.
\end{align*}
By H\"{o}lder's inequality,
\begin{align*}
\frac{\gamma}{h}|\hat\alpha(x,\tilde z) - \hat \alpha(x,z)|_1  &\leq \sum_{y\in S(x)} \bigl(|\tilde w(y)-w(y)| +
\E|\varphi(y,Z(x,\tilde z,\hat\alpha))-\varphi(y,Z(x,z,\hat\alpha))| \bigr)\\
&\leq \bigl(L_{\partial\ell} +  L_\varphi (1+\max_{x\in\cX} \, \Lip_1(\hat \alpha(x,\cdot)) ) \bigr) \,|z-\tilde z|_1.
\end{align*}
This implies
$$
(\gamma/h- L_\varphi) \max_{x\in\cX} \, \Lip_1(\hat\alpha(x,\cdot)) \leq L_{\partial\ell}+L_\varphi.
$$
Note that $\gamma/h-L_\varphi>0$ by the first part of the proof.
\end{proof}


Using Assumption \ref{asm:basic} \eqref{asm:basic-(iii)}, we know that there exists a $b_*<\infty$ such that the value function \eqref{eq:value-function-tagged-player} of the tagged player is bounded by $b_*(1+T)$, uniformly in the step size $h\in(0,\bar h)$ for any $\bar h<\infty$. Now note that any function $\varphi:\Sigma^{d-1}_N\to\R$ trivially satisfies
$$
|\varphi(\tilde z)-\varphi(z)|\leq 2N\|\varphi\|_\infty |\tilde z- z|_\infty, 
$$ 
so $\Lip_\infty (\varphi) \leq 2N\|\varphi\|_\infty.$ Together with $\Lip_1 (\varphi) \leq \Lip_\infty (\varphi) $ and Proposition \ref{prop:finite-player-one-step}, this implies the following result.


\begin{Prop}\label{prop:finite-player-h(N,T)}
Let Assumptions \ref{asm:basic} and \ref{asm:convex-cost} hold. Let $h>0$ be a time step and $T\in h\Z_+$ an arbitrary time horizon. If
$$
h< h_*(N,T):= \frac{\gamma}{2m(d)Nb_*(1+T)},
$$
then there exists a unique solution $v:\bar\cT\times\sX_N\to [0,\infty)$ to \eqref{eq:N-NLL} on $\bar\cT=\{0,h,2h,\ldots,T\}$.
\end{Prop}

This establishes Theorem \ref{thm:symmetric-Nash-system-and-sMPE} \eqref{thm:symmetric-Nash-system-and-sMPE-(ii)}.  In Section \ref{sec:short-time} we will see that there are time steps uniform in $N$ that ensure uniqueness in short time. 

The following example of a two-player game illustrates the necessity of the small-$h$ condition to ensure existence and uniqueness of a MPE. We will revisit this example in Subsection \ref{ssec:MF-one-step-ex}.

\begin{Ex}\label{ex:N-one-step}
For a (sufficiently small) thermal noise level $\sigma^2\geq0$ set
$$
\cX=\{0,1\},\quad A(h,x)=\{(a_0,a_1)\in\Sigma^1:a_0,a_1\geq\sigma^2h\},\quad \ell(x,a) = \frac{1}{2h}a_{x+1}^2,\quad g(x^i,x^{-i})=  \chi_{x^i\neq x^{-i}},
$$
for $(x^0,x^1,a)\in\cX^2\times \Sigma^1$. Addition is understood modulo $2$, and we observe that the cost function $g$ encourages players to be in the same state at terminal time while $\ell$ penalizes changing one's current state. In this two-state game, it is equivalent to identify controls $\alpha:\cX\to\Sigma^1$ with the probability of changing, i.e., $\alpha(x)=\alpha_{x+1}(x)$. Then, admissible controls are given by vectors $(\alpha(0),\alpha(1))\in \tilde A(h)^2$ where $\tilde A(h):=[\sigma^2h,1-\sigma^2h]$. Given a control $\beta=(\beta(0),\beta(1))\in \tilde A(h)^2$ of the other player, the tagged player solves
$$
\inf_{\alpha:\,\cX\to \tilde A(h)} \alpha(x)^2/(2h)+\E^{\alpha\otimes\beta}[g(X^0_h,X^1_h)\,|\,X_0=x],
$$
for every $x\in\cX^2$. Here, $\P^\alpha[X^0_h=x^0+1\,|\,X^0_0=x^0]=\alpha(x^0)$, $x^0\in\cX$. A direct computation shows that the NLL equation characterizing symmetric MPE reduces to the following system of equations:
$$
\begin{cases}
\alpha(0,0) = h[2\alpha(0,0)-1]\lor(\sigma^2h)\land (1-\sigma^2h),\\
\alpha(0,1) = h[1-2\alpha(1,0)]\lor(\sigma^2h)\land (1-\sigma^2h),\\
\alpha(1,0) = h[1-2\alpha(0,1)]\lor(\sigma^2h)\land (1-\sigma^2h),
\end{cases}
$$
and $\alpha(1,1)=\alpha(0,0)$. One easily observes the necessity for small $h$ to ensure the unique solvability of this set of equations. Indeed, if $\sigma^2=0$, then the first equation possesses multiple solutions for $h\geq1$, two of them being $\alpha(0,0)=0,1$. If $\sigma^2>0$, another direct computation shows the existence of three solutions if $h\in(h_*,h^*)$ where $h_*:=(1+\sigma^2 -\sqrt{1-(6-\sigma^2) \sigma^2})/(4 \sigma^2)$ and $h^*:=(1+\sigma^2 +\sqrt{1-(6-\sigma^2) \sigma^2})/(4 \sigma^2)$. This assumes that $\sigma^2\leq 3-2\sqrt{2}$, so that the square root is well-defined.
\end{Ex}

\section{The mean-field problem} \label{sec:mean-field-problem}

\subsection{The mean-field game system}



We continue to establish the existence result in Proposition \ref{prop:MFG-NE and MF-NLL} \eqref{prop:MFG-NE and MF-NLL-(i)}.


\begin{proof}[Proof of Proposition \ref{prop:MFG-NE and MF-NLL} \eqref{prop:MFG-NE and MF-NLL-(i)}]
Set $\cS := (\Sigma^{d-1})^{\cT(t,T)}$ and define a map $\Phi:\cS\to \cS$ via the following procedure. For $\boldsymbol\mu\in \cS$, let $(v,\alpha)$ solve the dynamic programming equation
$$
\begin{cases}
v(s,x)= \underset{a\in A(h,x)}{\inf} \ H(x,\mu_s,v(s+h),a),\quad t\leq s\leq T,\\
\alpha(s,x) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \ H(x,\mu_s,v(s+h),a),\quad t\leq s<T,\\
v(T,x) = g(x,\mu_T).
\end{cases}
$$
Then, set
$$\Phi_{t}(\boldsymbol\mu):=\mu,\quad 
\Phi_{s+h}(\boldsymbol\mu) := \Bigl(\sum_{y\in\cX}\mu_s(y)\alpha_x(s,y) \Bigr)_{x\in\cX},\quad t\leq s<T.
$$
With this construction, it is clear that solutions to the \ref{eq:MFG-system} correspond to fixed points of the map $\Phi(\cdot)$, and hence by Remark \ref{rmk:MFG-system-correspondence}, correspond to mean-field game Nash equilibria.  But Berge's maximum theorem implies that $\Phi(\cdot)$ is a continuous map. The claim follows by Brouwer's fixed-point theorem.
\end{proof}




\subsection{The mean-field Nash-Lasry-Lions equation}


We now discuss the \eqref{eq:MF-NLL} equation and first recall that any solution to the \eqref{eq:MF-NLL} equation, regardless of its regularity in the $\mu$ variable, defines a solution to the \ref{eq:MFG-system} for any initial condition $(t,\mu) \in \cT\times\Sigma^{d-1}$, and hence gives rise to solutions to the mean-field game, see Proposition \ref{prop:MFG-NE and MF-NLL} \eqref{prop:MFG-NE and MF-NLL-(ii)}. 

In Section \ref{sec:short-time}, we show the existence and uniqueness of the solution of \eqref{eq:MF-NLL} in short time. To this end, we again turn to the one-step problems. 

\begin{Prop}\label{prop:MF-one-step}
Let Assumptions \ref{asm:basic} and \ref{asm:convex-cost} hold. Then, for any Lipschitz continuous function $\varphi:\sX\to\R$, there exists a unique map $\hat\alpha(x,\mu):\sX\to\Sigma^{d-1}$ that satisfies
$$
\hat \alpha(x,\mu) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \, H(x,\mu,\varphi(\cdot,\mu\cdot \hat \alpha(\cdot,\mu)),a),\quad \forall (x,\mu)\in\sX,
$$
provided that $h<\gamma/L_\varphi$, where $L_\varphi:=m\,\max_{x\in\cX}\Lip_1(\varphi(x,\cdot))$. In addition, let Assumption \ref{asm:lipschitz-cost} hold. Then, $\hat \alpha$ is Lipschitz continuous in $\mu$ with 
$$
\max_{x\in\cX} \, \Lip_1(\hat\alpha(x,\cdot)) \leq \frac{h(L_{\partial\ell}+L_\varphi)}{\gamma-hL_\varphi},
$$
where $\gamma$ and $L_{\partial\ell}$ are constants from Assumptions \ref{asm:convex-cost} and \ref{asm:lipschitz-cost}, respectively.
\end{Prop}

\begin{proof}
For any fixed $\mu\in\Sigma^{d-1}$, we consider the following finite-dimensional fixed-point problem. Define
$$
\cS:=\{\alpha:\cX\to \Sigma^{d-1}\,:\,\alpha_y(x)=0 \ \forall y\notin  S(x)\},\quad 
|\alpha|_\cS := \max_{x\in\cX} \sum_{y\in S(x)}|\alpha_y(x)|,\quad \alpha\in\cS.
$$
Next, define $\Phi:\cS\to \cS$ by
$$
\Phi_x(\alpha) := \underset{ a\in  A(h,x) }{\mathrm{arg\,min}} \,H(x,\mu,\varphi(\cdot,\mu\cdot \alpha),a) ,\quad \text{and}\quad  \Phi(\alpha) :=(\Phi_x(\alpha))_{x\in\cX}.
$$
We first note that, if $\mu\in\Sigma^{d-1}$ is a row vector and $A\in\R^{d\times d}$, then $|\mu\cdot A|_1\leq \max_{1\leq i \leq d}|A_{i,:}|_1$.
Together with Lemma \ref{lem:convex-conjugates},
$$
|\Phi_x(\alpha)-\Phi_x(\tilde \alpha)|_1 \leq \frac{h}{\gamma} \sum_{y\in S(x)}|\varphi(y ,\mu\cdot\alpha)-\varphi(y,\mu\cdot\tilde \alpha)| \leq \frac{hL_\varphi}{\gamma} \, |\mu\cdot(\alpha-\tilde \alpha)|_1 \leq \frac{hL_\varphi}{\gamma} \, \max_{x\in\cX}|\alpha(x)-\tilde \alpha(x)|_1,
$$
so that $\Phi(\cdot)$ is a contraction if $h<\gamma/L_\varphi$ where $L_\varphi =m \max_{x\in\cX}\Lip_1(\varphi(x,\cdot))$.
By Banach's fixed-point theorem, there exists a unique fixed point in $\cS$. Since $\mu\in\Sigma^{d-1}$ was arbitrary, this construction yields a unique fixed point $\hat\alpha(x,\mu)$. The Lipschitz constant of $\hat\alpha$ can be deduced similarly to the finite-player case, see the proof of Proposition \ref{prop:finite-player-one-step}.
\end{proof}


We proceed with an explicit example that illustrates the necessity for the smallness condition on the time step.

\begin{Rmk}\label{rmk:monotonicity}
Our paper does not assume any monotonicity conditions on the cost functions, and the next example shows that we cannot expect global well-posedness. Our existence and uniqueness result in Section \ref{sec:short-time} relies on the smallness of both the time step $h$ and the time horizon $T$. Global existence and uniqueness for \eqref{eq:MF-NLL} can for example be established under the Lasry-Lions monotonicity condition. This condition allows to construct a time-consistent family of Nash equilibria, which is related to the concept of pasting equilibria by Dianetti, Nendel, Tangpi and Wang \cite{dianetti2024pasting}. 
\end{Rmk}



\subsection{One-step example} \label{ssec:MF-one-step-ex}

This section presents an example of a mean-field game in which uniqueness is lost in one step when the time step $h$ exceeds a critical value.  For a (sufficiently small) thermal noise level $\sigma^2\geq0$, set  
$$
\cX=\{0,1\}, \quad \tilde A(h)=[\sigma^2h,1-\sigma^2h],\quad \ell(x,a) = \frac{1}{2h}a^2,\quad g(x,\mu)=\mu\,\chi_{x=0}+ (1-\mu)\,\chi_{x=1},
$$
for $(x,a,\mu)\in\cX\times \tilde A(h)\times[0,1]$. As in the two-player Example \ref{ex:N-one-step}, addition on $\cX$ is defined modulo $2$ and we identify controls $\alpha(x)=(\alpha_0(x),\alpha_1(x))$ with the probability $\alpha_{x+1}(x)\in \tilde A(h)$ of \emph{changing} the current state. Similarly, we only keep track of the fraction $\mu\in[0,1]$ of the population in state $1$. Given a flow $\mu=(\mu_0,\mu_h)\in[0,1]^2$ of probabilities representing the fractions of players in state $1$, a typical player solves
$$
\inf_{\alpha:\,\cX\to \tilde A(h)} \alpha(x)^2/(2h)+\E^{\alpha}[g(X_h,\mu_h)\,|\,X_0=x],
$$
for every $x\in\cX$. Here, $\P^\alpha[X_h=x+1\,|\,X_0=x]=\alpha(x)$, $x\in\cX$. The cost functional is chosen in a way that leads to synchronization with the population. Given the initial distribution $\mu_0$, mean-field game equilibria are characterized by the following system:
$$
\begin{cases}
\alpha(x) = \underset{a\in A(h)}{\mathrm{arg\,min}} \,\{a^2/(2h)+ (1-a) g(x,\mu_h)+a g(x+1,\mu_h)\},\\
\mu_h = \alpha(0)(1-\mu_0) + (1- \alpha(1))\mu_0.
\end{cases}
$$
Computing $\alpha$ in terms of $\mu_h$ leads to the following one-dimensional fixed-point problem for the distribution at time $t=h$:
$$
\mu_h = \alpha^{\mu_h}(0)(1-\mu_0)+(1-\alpha^{\mu_h}(1))\mu_0,
$$
with $\alpha^{\mu_h}(0):=[h(2\mu_h-1)]\lor(\sigma^2h)\land(1-\sigma^2h)$ and $\alpha^{\mu_h}(1):=[h(1-2\mu_h)]\lor(\sigma^2h)\land(1-\sigma^2h)$. This is a fixed-point equation for the Nash equilibrium distribution $\mu_h\in[0,1]$. If $\sigma^2=0$, then there are three equilibria starting from the uniform distribution become if $h\geq1$. If $\sigma^2>0$, we have the following result, which follows by inspection of the above fixed-point equation, see Figure \ref{fig:1-step-MFG-Kuramoto} for an illustration.

\begin{Lem}
Let $\mu_0=1/2$ and $0< \sigma^2< 3-2\sqrt{2}$. Define $h_*:=(1+\sigma^2 -\sqrt{1-(6-\sigma^2) \sigma^2})/(4 \sigma^2)$ and $h^*:=(1+\sigma^2 +\sqrt{1-(6-\sigma^2) \sigma^2})/(4 \sigma^2)$.  
\begin{enumerate}[(i)]
\item For any $h>0$, the uniform distribution $\mu_h=1/2$ is a Nash equilibrium.
\item If $h\in(0,h_*)\cup(h^*,1/(2\sigma^2))$, then the only NE is $\mu_h=1/2$.
\item If $h\in\{h_*,h^*\}$, then there are exactly three NE.
\item If $h\in(h_*,h^*)$, then there are exactly five NE.
\end{enumerate}
\end{Lem}


\begin{figure}[h]
    \begin{subfigure}{0.3\textwidth}
        \centering
        \includegraphics[width=.9\linewidth]{1-Step-MF-NLL-i.pdf}
        \caption{$h<h_*$}
        %\label{fig:}
    \end{subfigure}
    \hspace{5pt}
    \begin{subfigure}{0.3\textwidth}
        \centering
        \includegraphics[width=.9\linewidth]{1-Step-MF-NLL-ii.pdf}
        \caption{$h=h_*$}
        %\label{fig:}
    \end{subfigure}
    \hspace{5pt}
    \begin{subfigure}{0.3\textwidth}
        \centering
        \includegraphics[width=.9\linewidth]{1-Step-MF-NLL-iii.pdf}
        \caption{$h\in(h_*,h^*)$}
        %\label{fig:}
    \end{subfigure}
    \caption{Nash equilibria starting from $\mu_0=1/2$ when $\sigma^2>0$.}
    \label{fig:1-step-MFG-Kuramoto}
\end{figure}

Clearly, in any one-step mean-field game, solutions to the Nash-Lasry-Lions equation are in one-to-one correspondence with collections $(\mu_0,\mu_h^{\mu_0})_{\mu_0\in\Sigma^{d-1}}$ of Nash equilibria, parametrized by the initial condition $\mu_0$. This observation implies that, in the example above, for $h\in[h_*,h^*]$, uniqueness of solutions to  \eqref{eq:MF-NLL} is lost.

\section{Short-time results} \label{sec:short-time}

Theorem \ref{thm:symmetric-Nash-system-and-sMPE} establishes the existence and uniqueness of the solution to \eqref{eq:N-NLL} for a time step $h<h_*(N,T)$ that depends on both the number of players and the time horizon of the game. In fact, as stated in Theorem \ref{thm:well-posedness-MF-NLL}, there exist time steps that guarantee uniqueness for any finite-player game as well as for the mean-field limit. We proceed to establish this result.

\begin{Lem}
Let Assumptions \ref{asm:basic}, \ref{asm:convex-cost} and \ref{asm:lipschitz-cost} hold. 
\begin{enumerate}[(a)]
\item (Finite-player case). 
Let $\varphi:\sX_N\to\R$ be given. Let $\hat \alpha$ be as in Proposition \ref{prop:finite-player-one-step}, and define
$$
\psi(x,z) = H(x,z,E(x,z,\varphi,\hat \alpha),\hat\alpha(x,z)), \quad (x,z)\in\sX_N.
$$
\item (Mean-field case). 
Let $\varphi:\sX\to\R$ be given. Let $\hat \alpha$ be as in Proposition \ref{prop:MF-one-step}, and define 
$$
\psi(x,\mu)= H(x,\mu,\varphi(\cdot,\mu\cdot\hat\alpha(\cdot,\mu)),\hat\alpha(x,z)), \quad (x,\mu)\in\sX.
$$
\end{enumerate}
In both cases, we have 
\be\label{eq:Lipschitz-estimate-value-func}
L_{\psi} \leq hm\,L_\ell + L_{\varphi} \, \Bigl(1+ \frac{h(L_{\partial\ell}+L_{\varphi})}{\gamma - hL_\varphi}\Bigr),
\ee
where $L_{\psi}=m\,\max_{x\in\cX} \,\Lip_1(\psi(x,\cdot))$ and  $L_{\varphi}=m\,\max_{x\in\cX} \, \Lip_1(\varphi(x,\cdot))$.
\end{Lem}

\begin{proof}
(a) By Lemma \ref{lem:lipschitz-multinom-II}, for $x\in\cX$ and $z,\tilde z\in\Sigma^{d-1}_N$,
\begin{align*}
|\psi(x, z)-\psi(x, \tilde z)| &\leq \sup_{a\in  A(h,x) } |(\ell(x,z,a/h)-\ell(x, \tilde z,a/h))h +  a\cdot (E(x,z,\varphi,\hat \alpha)-E(x, \tilde z,\varphi,\hat \alpha))|\\
&\leq \bigl[h L_\ell+ L_{\varphi}/m  \, (1+ L_{\hat \alpha}) \bigr]\, |z-\tilde z|_1,
\end{align*}
where $L_{\hat \alpha} = \max_{x\in\cX}\,\Lip_1(\hat \alpha(x,\cdot))$. Using the Lipschitz estimate from Proposition \ref{prop:finite-player-one-step}, we obtain

\begin{align*}
L_{\psi}&\leq hm\, L_\ell+ L_{\varphi}  \, (1+L_{\hat\alpha}) \leq hm\, L_\ell+ L_{\varphi} \, \Bigl(1+ \frac{h(L_{\partial\ell}+ L_{\varphi})}{\gamma - h L_\varphi}\Bigr).
\end{align*}

(b) For $\mu,\tilde\mu\in\Sigma^{d-1}$,
\begin{align*}
|a\cdot(\varphi(\cdot,\mu \cdot\hat \alpha (\cdot,\mu))-\varphi(\cdot,\tilde \mu \cdot\hat \alpha (\cdot,\tilde\mu)))|&\leq L_{\varphi}/m\,|\mu \cdot\hat \alpha (\cdot,\mu)-\tilde \mu \cdot\hat \alpha (\cdot,\tilde\mu)|_1\\
&=L_{\varphi}/m\, |(\mu-\tilde\mu)\cdot \hat \alpha (\cdot,\mu) + \tilde\mu\cdot( \hat \alpha (\cdot,\mu)-\hat \alpha(\cdot,\tilde\mu))|_1\\
&\leq L_{\varphi}/m(1+L_{\hat \alpha }) |\mu-\tilde \mu|_1,
\end{align*}
where $L_{ \hat \alpha} =\max_{x\in\cX} \,\Lip_1( \hat \alpha (x,\cdot))$.
Therefore,
\begin{align*}
|\psi(x,\mu)-\psi(x,\tilde \mu)| &\leq \sup_{a\in  A(h,x) } |(\ell(x,\mu,a/h)-\ell(x,\tilde \mu,a/h))h +  a\cdot(\varphi(\cdot,\mu \cdot\hat \alpha (\cdot,\mu))-\varphi(\cdot,\tilde \mu \cdot\hat \alpha (\cdot,\tilde\mu)))|\\
&\leq \bigl[h L_\ell+ L_{\varphi}/m(1+L_{ \hat \alpha })\bigr]\, |\mu-\tilde \mu|_1,
\end{align*}
and we complete the proof using the Lipschitz estimate from Proposition \ref{prop:MF-one-step}, analogous to (a).
\end{proof}


The following proposition establishes Theorem \ref{thm:well-posedness-MF-NLL}.

\begin{Prop}\label{prop:short-time-well-posedness}
Let Assumptions \ref{asm:basic}, \ref{asm:convex-cost} and \ref{asm:lipschitz-cost} hold. 
There exist constants $h_*,T_*>0$ depending only on the cost functions $\ell,g$ and $m=m(d)$, such that, for all $h>0$ and $K\geq1$, the following holds: If $h<h_*$ and $Kh<T_*$, then there exists a unique solution $v^\infty$ to \eqref{eq:MF-NLL} and a unique solution $(v^{(N)},\alpha^{(N)})$ to \eqref{eq:N-NLL} on $\bar\cT=\{0,\ldots,Kh\}$ for every $N\geq1$. Furthermore, 
$$
\sup_{N\in\N\cup\{\infty\}}\max_{(t,x)\in\bar\cT\times\cX} \, [\Lip_1(v^{(N)}(t,x,\cdot))+\Lip_1(\alpha^{(N)}(t,x,\cdot))]<\infty.
$$
\end{Prop}


\begin{proof}
\emph{Step 1.} We iterate the estimate \eqref{eq:Lipschitz-estimate-value-func}, which is valid for both the finite-player and the mean-field case. We reverse time, set $L(0):= m\,L_g := m\, \max_{x\in\cX}\,\Lip_1(g(x,\cdot))$, and recursively define
$$
L(k) = L(k-1)+ h \Bigl(m L_\ell +  L(k-1) \frac{L_{\partial\ell}+L(k-1)}{\gamma-h L(k-1)}\Bigr),\quad k\geq 1.
$$
Fix $M>L(0)$, $h\leq\gamma/M$ and set $\tilde M := mL_\ell + M(L_{\partial\ell}+M)/(\gamma-hM)$. We claim that, for any $K\geq0$ that satisfies $
Kh\leq (M-L(0))/\tilde M$, we have $L(k)\leq M$ for all $k=0,\ldots,K$. Indeed, we may proceed by induction on $K$. For $K=0$, we have $L(0)\leq M$ by assumption. Let $K\geq1$. If $L(0),\ldots,L(K-1)\leq M$, then 
\begin{align*}
L(K)&=L(0)+\sum_{k=1}^K (L(k)-L(k-1)) \leq L(0)+ h \sum_{k=1}^K \Bigl(mL_\ell +  L(k-1) \frac{L_{\partial\ell}+L(k-1)}{\gamma-h L(k-1)}\Bigr)\leq L(0) + Kh\, \tilde M \leq M,
\end{align*}
where the first inequality follows from the induction hypothesis, the second from the choice of 
$h$ and $\tilde M$, and the third follows from the choice of the product $Kh$. \\

\emph{Step 2.} In light of the previous step, we may choose any $M>L(0)$ and define $h_*:=\gamma/M$ and $T_*:=(M-L(0))/\tilde M$. Note that, in particular, we have $h<\gamma/L(k)$ for all $k=0,\ldots,K$. By Propositions \ref{prop:finite-player-one-step} and \ref{prop:MF-one-step}, we can recursively solve the equations \eqref{eq:N-NLL} and \eqref{eq:MF-NLL} on $\{0,\ldots,Kh\}$. Finally, note that the Lipschitz constants are bounded by $M$.
\end{proof}

\begin{Rmk}
If the number of admissible transitions $m=m(d)$ is independent of $d$, then so are $h_*$ and $T_*$. This is, for instance, the case in Example \ref{ex:nearest-neighbor-I}.
\end{Rmk}


\section{Mean-field convergence} \label{sec:mean-field-convergence}

We proceed to establish Theorem \ref{thm:N-convergence}, which asserts the convergence of the solutions to \eqref{eq:N-NLL} to the solution of the mean-field equation \eqref{eq:MF-NLL} as $N\to\infty$ in short time. We start by recording the following consequence of the law of large numbers.

\begin{Lem}\label{lem:LLN}
Let $(\varphi^{(N)},\alpha^{(N)}):\sX\to\R\times\Sigma^{d-1}$, $N\geq1$, be a sequence of functions converging uniformly to some $(\varphi^{(\infty)},\alpha^{(\infty)}):\sX\to\R\times\Sigma^{d-1}$. Assume that $\sup_{n\geq1}\Lip(\varphi^{(N)}(x,\cdot))<\infty$ for all $x\in\cX$. Let $(z^{(N)})_{N\geq1}$ be a sequence with $z^{(N)}\in\Sigma^{d-1}_N$ converging to some $\mu\in\Sigma^{d-1}$. Then, for any $x\in\cX$,
$$
\E[\varphi^{(N)}(x,Z'(x,z^{(N)},\alpha^{(N)}))] \to \varphi^{(\infty)}(x,\sum_{y\in\cX} \mu(y)\alpha^{(\infty)}(y,\mu)),\quad \text{as} \quad N\to\infty.
$$
\end{Lem}
\begin{proof}
By the law of large numbers, as $N\to\infty$,
$$
Z'_j(x,z^{(N)},\alpha^{(N)}) = \sum_{y\in\cX} Z'_j(x,y,z^{(N)},\alpha^{(N)})\to\sum_{y\in\cX} \mu_y\, \alpha^{(\infty)}_j(y,\mu) =: Z^{(\infty)}_j,
$$
for each $1\leq j\leq d$ almost surely. By the triangle inequality,
\begin{align*}
|\E[\varphi^{(N)}(x,Z'(x,z^{(N)},\alpha^{(N)}))] - \varphi^{(\infty)}(x,Z^{(\infty)})| &\leq \E|\varphi^{(N)}(x,Z'(x,z^{(N)},\alpha^{(N)}))-\varphi^{(N)}(x,Z^{(\infty)})|\\
&\quad + |\varphi^{(N)}(x,Z^{(\infty)})-\varphi^{(\infty)}(x,Z^{(\infty)})|.
\end{align*}
The second term converges to zero by assumption. The first term can be estimated as follows:
\begin{align*}
\E|\varphi^{(N)}(x,Z'(x,z^{(N)},\alpha^{(N)}))-\varphi^{(N)}(x,Z^{(\infty)})|&\leq\Lip(\varphi^{(N)}(x,\cdot)) \,\E|Z'(x,z^{(N)},\alpha^{(N)})-Z^{(\infty)}| \to 0.\qedhere
\end{align*}
\end{proof}




\begin{proof}[Proof of Theorem \ref{thm:N-convergence}]
\emph{Step 1.} Let $h_*,T_*$ be as in Proposition \ref{prop:short-time-well-posedness}. Clearly, the solutions $(v^{(N)},\alpha^{(N)})_{N\geq1}$ of \eqref{eq:N-NLL} form a uniformly bounded equicontinuous sequence of continuous functions from $\Sigma^{d-1}$ to $[0,\infty)^{\bar\cT\times \cX} \times (\Sigma^{d-1})^{\cT\times\cX}$. Here, we linearly interpolated in the $z$-variable. Hence, by the Arzel\`{a}-Ascoli theorem, there exists a $(\tilde v^{(\infty)}, \tilde \alpha^{(\infty)})$ such that, along a subsequence, $(v^{(N)},\alpha^{(N)})\to (\tilde v^{(\infty)},\tilde\alpha^{(\infty)})$ uniformly as $N\to\infty$. We replace the original sequence by this subsequence.

\emph{Step 2.} We now claim that 
$$
\tilde \alpha^{(\infty)}(t,x,\mu) = \underset{a\in  A(h,x) }{\mathrm{arg\,min}} \, H(x,\mu,\tilde \varphi^{(\infty)}(\mu^T\tilde\alpha^{(\infty)}(\cdot,\mu)),a),\quad (t,x,\mu)\in\cT\times\sX.
$$
Indeed, for every $N\geq1$ and $(x,z,a)\in\sX_N \times  A(h,x)$, we have
$$
H(x,z,E(x,z,v^{(N)}(t+h),\alpha^{(N)}(t)),\alpha^{(N)}(t,x,z))\leq H(x,z,E(x,z,v^{(N)}(t+h),\alpha_N(t)),a).
$$
For a given $\mu\in\Sigma^{d-1}$, choose $z^{(N)}\in\sX_N$ such that $z^{(N)}\to\mu$ as $N\to\infty$. By Lemma \ref{lem:LLN}, 
$$
H(x,\mu,\tilde v^{(\infty)}(t+h,\mu\cdot\tilde\alpha^{(\infty)}(t,\cdot,\mu)),\tilde \alpha^{(\infty)}(t,x,\mu))\leq H(x,\mu,\tilde v^{(\infty)}(t+h,\mu\cdot\tilde\alpha^{(\infty)}(t,\cdot,\mu)),a)
$$
for $(t,x,\mu,a)\in\cT\times\sX\times A(h,x)$. Hence, $(\tilde v^{(\infty)},\tilde \alpha^{(\infty)})$ is a solution of \eqref{eq:MF-NLL} on $\bar\cT$, which has a unique solution $(V,\alpha)$. This argument shows that any subsequence of $(v^{(N)},\alpha^{(N)})_{N\geq1}$ has a further subsequence that converges to $(V,\alpha)$ uniformly, hence the entire sequence converges to $(V,\alpha)$ uniformly.
\end{proof}

\section{Continuous-time limit}\label{sec:continuous-limit}

This section proves Theorem \ref{thm:continuous-convergence}. Throughout this section we assume 
$$
A(h)=A(h,x)=\{a\in\Sigma^{d-1}:a_y\geq h\sigma^2\ \forall y\in\cX\},\quad \text{for some fixed}\ \ \sigma^2\geq0.
$$

\begin{Lem}\label{lem:cts-time-limit}
Let $(\alpha^{(K)},\alpha^{(\infty)}):\sX_N\to \Sigma^{d-1}\times\R^d$, $K\geq1$, be functions such that $\mathfrak{a}^{(K)}/h^{(K)}\to \alpha^{(\infty)}$ as $K\to\infty$ where $\mathfrak{a}^{(K)}(x,z):=\alpha^{(K)}(x,z)-e_x$ for $(x,z)\in[0,T]\times\sX_N$. Then, for all $(x,z,z')\in\sX_N\times\Sigma^{d-1}_N$,
$$
\lim_{K\to\infty}\frac{1}{h^{(K)}} \P[Z'(x,z,\alpha^{(K)})= z'] 
=
\begin{cases}
\infty,& z'=z,\\
Nz_y\, \alpha^{(\infty)}_w(y,z+e_{xy}),& \text{if} \ \exists w\neq y: z'=z+e_{wy}\\
0,&\text{otherwise},
\end{cases}
$$
and, more precisely, $\lim_{K\to\infty }\P[Z'(x,z,a^{(K)})= z]=1$.
\end{Lem}

\begin{proof}
Fix $(x,z)\in\sX_N$. For any state $y\in\cX$ and any empirical distribution $s\in\Sigma^{d-1}_{Nz_y}$ of untagged players in state $y$,
$$
\P[Z'(x,y,z,\alpha^{(K)})=s]
= \frac{(Nz_y)!}{(Ns_1)!\cdots (Ns_d)!}  \, [1+\mathfrak{a}_y^{(K)}(y,z+e_{xy})]^{Ns_y}\prod_{i\neq y}[\mathfrak{a}^{(K)}_i(y,z+e_{xy})]^{Ns_i} .
$$
By inspection of this formula we deduce
\begin{enumerate}[(1)]
\item if $s=z_ye_y$, i.e., all untagged players in state $y$ remain in $y$ after $h^{(K)}$ amount of time, then
$$
\P[Z'(x,y,z,\alpha^{(K)})=z_ye_y] = [1+\mathfrak{a}^{(K)}_y(y,z+e_{xy})]^{Nz_y} \to 1,\quad \text{as} \ K\to\infty,
$$
using $\mathfrak{a}^{(K)}_y(t,y,z+e_{xy})\to0$;
\item if there exists $w\in\cX\setminus\{y\}$ such that $s=z_ye_y+e_{wy}$, i.e., exactly one untagged player in state $y$ changes to a state $w$, then 
$$
\frac{1}{h^{(K)}} \P[Z'(x,y,z,\alpha^{(K)})=z_ye_y+e_{wy}]
= \frac{(Nz_y)!}{(Nz_y-1)!}   \, [1+\mathfrak{a}_y^{(K)}(y,z+e_{xy})]^{Nz_y-1}\frac{\mathfrak{a}^{(K)}_w(y,z+e_{xy})}{h^{(K)}},
$$
which converges to $Nz_y \,\alpha^{(\infty)}_w(t,y,z+e_{xy})$;
\item in all other cases, 
$$
\frac{1}{h^{(K)}}\P[Z'(x,y,z,\alpha^{(K)})=s]
= \frac{(Nz_y)!}{(Ns_1)!\cdots (Ns_d)!}  \, [1+\mathfrak{a}_y^{(K)}(y,z+e_{xy})]^{Ns_y}
\frac{1}{h^{(K)}}\prod_{i\neq y}[\mathfrak{a}^{(K)}_i(y,z+e_{xy})]^{Ns_i} 
$$
converges to zero as $\mathfrak{a}_i^{(K)}(t,y,z+e_{xy})/h^{(K)}$ stays bounded as $K\to\infty$ for all $i$ and there are at least two states $i\neq y$ present in the product.
\end{enumerate}
Next, let $z'\neq z$ in $\Sigma^{d-1}_N$ be given and write $z' = s(1)+\cdots+s(d)$ for some $s(y)\in\Sigma^{d-1}_{Nz_y}$, with $\Sigma^{d-1}_0:=\{0_{\R^d}\}$. We let $\Sigma(z')$ denote the set of all such $s(1),\ldots,s(d)$. Then, the claim follows from the previous observation, together with the explicit formula
\begin{align*}
\P[Z'(x,z,\alpha^{(K)})=z']  &=\P\Bigl[\sum_{y\in\cX} Z'(x,y,z,\alpha^{(K)})=z'\Bigr] =\sum_{s\in\Sigma(z')} \prod_{y\in\cX}\P[Z'(x,y,z,\alpha^{(K)})=s(y)].\qedhere
\end{align*}
\end{proof}

Now, for each $K\geq1$, set $h^{(K)}:=T/K$ and define the discretization $0=s_0^{(K)}<s_1^{(K)}<\cdots<s_k^{(K)}=T$ of the time interval $[0,T]$ by $s^{(K)}_k:=kT/K$. For each $K\geq1$, let $(v^{(K)},\alpha^{(K)})$ solve the \eqref{eq:N-NLL} equation, which is uniquely defined for sufficiently large $K$, say $K\geq K_0$. We extend these functions to $[0,T]\times\sX_N$ by linear interpolation in the time variable and set 
$$
\mathfrak{a}^{(K)}(t,x,z) := \alpha^{(K)}(t,x,z)-e_x,\quad (t,x,z)\in [0,T]\times\sX_N.
$$ 
In the continuous-time problem, let $v_{\mathrm{cts}}:[0,T]\times\sX_N\to[0,\infty)$ be the unique solution to \eqref{eq:cts-time-finite-player-NLL} and let $\alpha_{\mathrm{cts}}(t,x,z)=\hat\alpha(x,z,\Delta_x v_{\mathrm{cts}}(t,\cdot,z))$. The following proof establishes Theorem \ref{thm:continuous-convergence} and shows that $(v^{(K)},\mathfrak{a}^{(K)}/h^{(K)})\to (v_{\mathrm{cts}},\alpha_{\mathrm{cts}})$ uniformly on $[0,T]\times\sX_N$, as $K\to\infty$.

\begin{proof}[Proof of Theorem \ref{thm:continuous-convergence}]

\emph{Step 1.} We claim that $(v^{(K)},\mathfrak{a}^{(K)}/h^{(K)})_{K\geq K_0}$ is a uniformly bounded, equicontinuous family of continuous functions, seen as functions from $[0,T]$ to $[0,\infty)^{\sX_N}\times (\R^d)^{\sX_N}$.

\emph{Uniform boundedness.} By Assumption \ref{asm:basic}, $v^{(K)}$ are uniformly bounded, say by some $c_0<\infty$. We set 
$$
\tilde H(x,z,v,\tilde a):= \ell(x,z,a/h)h+\sum_{y\neq x} a(y)\Delta_xv(y) +v(x), \quad (x,z,v,a)\in\sX_N\times\R^{d}\times\R^{d-1},
$$
and note that $\tilde H(x,z,v, a_{-x})=H(x,z,v,a)$ for all $(x,z,v,a)\in\sX_N\times\R^{d-1}\times\Sigma^{d-1}$.
We note that $\alpha^{(K)}_{-x}(s^{(K)}_k,x,z)$ is given as the minimizer of the Hamiltonian 
$$
\tilde A(h^{(K)})\ni \tilde a_{-x}\mapsto \tilde H(x,z, E(x,z,v^{(K)}(s^{(K)}_{k+1}),\alpha^{(K)}(s^{(K)}_k)),\tilde a_{-x}),
$$
where $\tilde A(h^{(K)})$ is the set of subprobability  vectors $\tilde a_{-x}\in [0,1]^{d-1}$ satisfying $\sum_{y\neq x}\tilde a_x\leq 1$ and for which there exists $a\in A(h^{(K)})$ with $a_{-x}=\tilde a_{-x}$.   Let $\eta^{(K)}$ be defined as the minimizer of $\tilde A(h^{(K)})\ni \tilde a_{-x}\mapsto \tilde H(x,z,0,\tilde a_{-x})$. By Lemma \ref{lem:convex-conjugates}, 
$$
\frac{1}{h^{(K)}} |\alpha^{(K)}_{-x}(s^{(K)}_k,x,z)-\eta^{(K)}(x,z)|_1\leq \frac{1}{\gamma} \, \sum_{y\in S(x)\setminus\{x\}} \E|\Delta_x v^{(K)}(s^{(K)}_{k+1}, x, Z'(x,z,\alpha^{(K)}(s^{(K)}_k)))|\leq \frac{2(m-1)c_0}{\gamma}.
$$
By definition of $\eta^{(K)}$ as the minimizer of $\tilde H(x,z,0,\cdot)$ over $\tilde A(h^{(K)})$, 
$$
\ell(x,z,\frac{\eta^{(K)}(x,z)}{h^{(K)}}) \leq \ell (x,z,\sigma^2).
$$
Since $\ell(x,z,\cdot)$ is strongly convex, it is coercive, and hence $(|\eta^{(K)}(x,z)|_1/h^{(K)})_{K\geq1}$ is bounded by some $\tilde c_0<\infty$. Putting these two estimates together, we arrive at
$$
\sup_{K\geq K_0} \max_{0\leq k<K}\max_{(x,z)\in\sX_N}\frac{1}{h^{(K)}}|\alpha_{-x}^{(K)}(s^{(K)}_k,x,z)|_1 \leq \frac{2(m-1)c_0}{\gamma}+\tilde c_0 =: c_1<\infty.
$$
Using the relation
$$
|\mathfrak{a}^{(K)}(s^{(K)}_k,x,z)|_1 = 2|\alpha_{-x}^{(K)}(s^{(K)}_k,x,z)|_1,
$$
this implies the claim.
Note that $(|\alpha^{(K)}(t,x,z)|_1/h^{(K)})_{K\geq K_0}$ is not a bounded sequence since $\alpha^{(K)}_x(t,x,z)\to1$ as $K\to\infty$.

\emph{Equicontinuity.} Let us first observe that by the same reasoning as in Lemma \ref{lem:cts-time-limit}, the uniform boundedness of $(\mathfrak{a}^{(K)}/h^{(K)})_{K\geq K_0}$ implies that
\begin{align*}
&\max_{0\leq k<K} \, \frac{1}{h^{(K)}}\,\P^{\alpha^{(K)}\otimes\alpha^{(K)}}[(X_{s^{(K)}_{k+1}},Z_{s^{(K)}_{k+1}})=(x',z')\,|\,(X_{s^{(K)}_{k}},Z_{s^{(K)}_{k}})=(x,z)]\\
&\qquad =\max_{0\leq k<K} \,   \frac{1}{h^{(K)}}\, \alpha^{(K)}_{x'}(s^{(K)}_k,x,z) \,\P[Z'(x,z,\alpha^{(K)}(s^{(K)}_k))=z']
\end{align*}
is bounded, say by some $c_2<\infty$, whenever $(x',z')\neq (x,z)$. Hence, for $0\leq k<K$ and $(x,z)\in\sX_N$,
\begin{align*}
&|v(s^{(K)}_{k+1},x,z)-v(s^{(K)}_k,x,z)|\\
&\quad \leq |\E^{\alpha^{(K)}\otimes\alpha^{(K)}}[v(s^{(K)}_{k+1},X_{s^{(K)}_{k+1}},Z_{s^{(K)}_{k+1}})]-v(s^{(K)}_k,x,z)|  + |\E^{\alpha^{(K)}\otimes\alpha^{(K)}}[v(s^{(K)}_{k+1},X_{s^{(K)}_{k+1}},Z_{s^{(K)}_{k+1}})]-v(s^{(K)}_{k+1},x,z)| \\
&\quad= |\E^{\alpha^{(K)}\otimes\alpha^{(K)}}[v(s^{(K)}_{k+1},X_{s^{(K)}_{k+1}},Z_{s^{(K)}_{k+1}})]-v(s^{(K)}_k,x,z)| \\
&\quad+ \sum_{(x',z')\neq(x,z)} \P^{\alpha^{(K)}\otimes\alpha^{(K)}}[(X_{s^{(K)}_{k+1}},Z_{s^{(K)}_{k+1}})=(x',z')\,|\,(X_{s^{(K)}_{k}},Z_{s^{(K)}_{k}})=(x,z)] \, |v(s^{(K)}_{k+1},x',z')-v(s^{(K)}_{k+1},x,z)|\\
&\quad\leq |\ell(x,z,\alpha^{(K)}(s_k^{(K)},x,z)/h^{(K)})|h^{(K)} + 2c_0c_2\, h^{(K)} \leq (\sup_{[0,c_1]^{d-1}} |\ell(x,z,\cdot)|+2c_0c_2) \, h^{(K)} =: c_3 h^{(K)}.
\end{align*}
This implies equicontinuity of $(v^{(K)})_{K\geq K_0}$. We turn to  show the equicontinuity of $(\mathfrak{a}^{(K)})_{K\geq K_0}$. 
As in the proof in Proposition \ref{prop:finite-player-one-step}, by Lemma \ref{lem:convex-conjugates},
\begin{align*}
|\alpha^{(K)}_{-x}(s^{(K)}_k,x,z)&\,-\alpha^{(K)}_{-x}(s^{(K)}_{k+1},x,z)|_1\\
&\leq \frac{h^{(K)}}{\gamma}\sum_{y\in S(x)\setminus\{x\}}\E|\Delta_xv(s^{(K)}_{k+1},y,Z'(x,z,\alpha^{(K)}(s_k)))- \Delta_xv(s^{(K)}_{k+2},y,Z'(x,z,\alpha^{(K)}(s_{k+1})))|\\
&\leq \frac{4(m-1)L^{(K)}_kh^{(K)}}{\gamma} \max_{(x,z)\in\sX_N}  |\alpha^{(K)}_{-x}(s^{(K)}_k,x,z)-\alpha^{(K)}_{-x}(s^{(K)}_{k+1},x,z)|_1 + \frac{c_3(m-1)}{\gamma}(h^{(K)})^2,
\end{align*}
where $L^{(K)}_k:=\max_{x\in\cX}\,\Lip_1(v^{(K)}(s^{(K)}_k,x,\cdot))$.
Taking the maximum over $(x,z)\in\sX_N$, 
$$
\bigl(1- \frac{4(m-1)L^{(K)}_kh^{(K)}}{\gamma} \bigr)\max_{(x,z)\in\sX_N}  |\alpha^{(K)}_{-x}(s^{(K)}_k,x,z)-\alpha^{(K)}_{-x}(s^{(K)}_{k+1},x,z)|_1\leq  \frac{c_3(m-1)}{\gamma}(h^{(K)})^2
$$
 Since $L^{(K)}_k$ is bounded uniformly in $(k,K)$, we see that indeed $(\alpha^{(K)}/h^{(K)})_{K\geq K_0}$ is equicontinuous. By definition of $\mathfrak{a}^{(K)}$, this shows equicontinuity of  $(\mathfrak{a}^{(K)}/h^{(K)})_{K\geq K_0}$.\\

 \emph{Step 2.} By the Arzel\`{a}-Ascoli theorem, there exists continuous $(\tilde v^{(\infty)}, \tilde \alpha^{(\infty)})$ such that, along a subsequence, $(v^{(K)}, \mathfrak{a}^{(K)}/h_K)\to (\tilde v^{(\infty)}, \tilde \alpha^{(\infty)})$ uniformly on $[0,T]$ as $K\to\infty$. We replace the original sequence with this subsequence. \\

\emph{Step 3.} For $(x,z)\in\sX_N$ define 
\begin{align*}
\varphi^{(K)}_k(x,z)&:=\tilde H(x,z,E(x,z,v^{(K)}(s^{(K)}_{k+1}),\alpha^{(K)}(s^{(K)}_k)),\mathfrak{a}^{(K)}(s^{(K)}_k,x,z)) -v^{(K)}(s^{(K)}_{k+1},x,z),\quad 0\leq k<K\\
\varphi^{(\infty)}(s,x,z) &:=\cH(x,z,\Delta_x\tilde v^{(\infty)}(s,\cdot,z),\tilde \alpha^{(\infty)}(s,x,z))+\sL^{\tilde \alpha^{(\infty)}(s)}\tilde v^{(\infty)}(s,\cdot,\cdot)(x,z)),\quad s\in[0,T].
\end{align*}
We claim that
$$
\lim_{K\to\infty}\ \max_{0\leq k<K} \ \Bigl|\frac{1}{h^{(K)}}\varphi^{(K)}_k(x,z)-\varphi^{(\infty)}(s^{(K)}_k,x,z)\Bigr| =0.
$$
Indeed, write $\varphi^{(K)}_k := \ell(x,z,\mathfrak{a}^{(K)}(s^{(K)}_k,x,z)/h^{(K)})h^{(K)} + \mathrm{(I)}_k + \mathrm{(II)}_k$ where
\begin{align*}
\mathrm{(I)}_k &:=\sum_{y\in\cX\setminus\{x\}} \mathfrak{a}^{(K)}_y(s^{(K)}_k,x,z)\, \E[v^{(K)}(s^{(K)}_{k+1},y,Z'(x,z,\alpha^{(K)}(s^{(K)}_k)))-v^{(K)}(s^{(K)}_{k+1},x,Z'(x,z, \alpha^{(K)}(s^{(K)}_k)))], \\
\mathrm{(II)}_k &:= \E[v^{(K)}(s^{(K)}_{k+1},x,Z'(x,z,\alpha^{(K)}(s^{(K)}_k)))]-v^{(K)}(s^{(K)}_{k+1},x,z).
\end{align*}
Using the fact that $\lim_{K\to\infty}Z'(x,z,\alpha^{(K)}(s^{(K)}_k)) = z$ and the uniform convergence of $(v^{(K)},\mathfrak{a}^{(K)}/h^{(K)})$ to $(\tilde v^{(\infty)},\tilde \alpha^{(\infty)})$, 
$$
\lim_{K\to\infty} \ \max_{0\leq k< K} \ \Bigl|\frac{1}{h^{(K)}}\mathrm{(I)}_k -\sum_{y\in\cX\setminus\{x\}} \tilde \alpha^{(\infty)}_y(s^{(K)}_k,x,z)\, (\tilde v^{(\infty)}(s^{(K)}_k,y,z)-\tilde v^{(\infty)}(s^{(K)}_k,x,z)) \Bigr| = 0.
$$
For the second term, we write 
$$
\mathrm{(II)}_k = \sum_{z'\in\Sigma^{d-1}_N\setminus\{z\}} \P[Z'(x,z,\alpha^{(K)}(s^{(K)}_k))=z'] \, (v^{(K)}(s^{(K)}_{k+1},x,z')-v^{(K)}(s^{(K)}_{k+1},x,z)),
$$
and we use Lemma \ref{lem:cts-time-limit} and the uniform convergence of $(v^{(K)},\mathfrak{a}^{(K)}/h^{(K)})$ to $(\tilde v^{(\infty)},\tilde \alpha^{(\infty)})$ to see
$$
\lim_{K\to\infty}\ \max_{0\leq k<K}\ \Bigl|\frac{1}{h^{(K)}}\mathrm{(II)}_k -\sum_{w\neq y} Nz_y \,\tilde \alpha^{(\infty)}_w(s^{(K)}_k,y,z+e^N_{xy})\,(\tilde v^{(\infty)}(s^{(K)}_k,x,z+e^N_{wy})-\tilde v^{(\infty)}(s^{(K)}_k,x,z)) \Bigr| =0.
$$


\emph{Step 3.} Note that for every $0\leq k < K$ we have
\be\label{eq:proof-cts-time-limit}
-(v^{(K)}(s^{(K)}_{k+1},x,z)-v^{(K)}(s^{(K)}_k,x,z)) = \varphi^{(K)}_k(x,z),\quad (x,z)\in\sX_N.
\ee
Let $t\in(0,T)$, choose a sequence $t^{(K)}\in\{0,T/K,\ldots,T\}$ converging to $t$ and let $T^{(K)}=t^{(K)} K$. Summing over $0\leq k \leq T^{(K)}-1$ in \eqref{eq:proof-cts-time-limit}, we obtain $-(v^{(K)}(t^{(K)},x,z)-v^{(K)}(0,x,z))=\sum_{k=0}^{T^{(K)}-1} \varphi^{(K)}_k(x,z)$. Now 
\begin{align*}
\Bigl|\sum_{k=0}^{T^{(K)}-1} \varphi^{(K)}_k(x,z) - \int_0^t \varphi^{(\infty)}(s,x,z)\,\d s \Bigr| &\leq h^{(K)} \sum_{k=0}^{T^{(K)}-1} |\varphi^{(K)}_k(x,z)/h^{(K)}-\varphi^{(\infty)}(s^{(K)}_k,x,z)| \\
&+ \Bigl|\sum_{k=0}^{T^{(K)}-1} \varphi^{(\infty)}(s^{(K)}_k,x,z)h_K-\int_0^t \varphi^{(\infty)}(s,x,z)\,\d s \Bigr|
\end{align*}
The first term converges to zero by Step 2.\ while the second term converges to zero by classical arguments. This proves that $\tilde v^{(\infty)}(t,x,z)-\tilde v^{(\infty)}(0,x,z)=-\int_0^t\varphi^{(\infty)}(s,x,z)\,\d s$. Hence  $\tilde v^{(\infty)}(\cdot,x,z)$ is continuously differentiable on $[0,T]$ with derivative $-\varphi^{(\infty)}(\cdot,x,z)$. 

\emph{Step 4.} We claim that
$$
(\tilde \alpha^{(\infty)}(t,x,z))_{y\neq x}=\underset{a\in[\sigma^2,\infty)^{d-1}}{\mathrm{arg\,min}}\ \cH(x,z,\Delta_x\tilde v^{(\infty)}(t,\cdot,z),a),\quad (t,x,z)\in[0,T]\times\sX_N.
$$
Then, for every $0\leq k <K$ and $(x,z,a)\in\sX_N\times \tilde A(h^{(K)})$ we have,
$$
\tilde H(x,z,E(x,z,v^{(K)}(t^{(K)}+h),\alpha^{(K)}(t^{(K)})),\mathfrak{a}^{(K)}(t^{(K)},x,z))  \leq \tilde H(x,z,E(x,z,v^{(K)}(t^{(K)}+h),\alpha^{(K)}(t^{(K)})),a).
$$
Adding $\E[v(t^{(K)}+h,x,Z'(x,z,a^{(K)}(t^{(K)})))]$ to both sides, dividing by $h^{(K)}$ and taking the limit $K\to\infty$ yields
$$
\cH(x,z,\Delta_x\tilde v^{(\infty)}(t,\cdot,z),\tilde \alpha^{(\infty)}(t,x,z))  \leq \cH(x,z,\Delta_x\tilde v^{(\infty)}(t,\cdot,z), a)\quad (x,z,a)\in\sX_N\times [\sigma^2,\infty)^{d-1}.
$$

\emph{Step 5.} Steps 1.\ to 4.\ show that given any subsequence $(K_n)_{n\geq1}$, we can find a further subsequence $(K_{n_p})_{p\geq1}$ such that $\{v^{(K_{n_p})}(\cdot,x,z):(x,z)\in\sX_N\}$ and $\{\mathfrak{a}^{(K_{n_p})}_y(\cdot,x,z) / h^{(K_{n_p})}:(x,z)\in\sX_N\}$ converge uniformly to some continuous functions $\tilde v^{(\infty)}= \{\tilde v^{(\infty)}(\cdot,x,z):(x,z)\in\sX_N\}$ and $\tilde \alpha^{(\infty)}=\{\tilde \alpha^{(\infty)}(\cdot,x,z):(x,z)\in\sX_N\}$, respectively, such that $(\tilde v^{(\infty)},\tilde a^{(\infty)})$ satisfy the continuous-time NLL equation \eqref{eq:cts-time-finite-player-NLL}. Since the latter has a unique classical solution $(v_{\mathrm{cts}},\alpha_{\mathrm{cts}})$, this proves that the entire sequence $(v^{(K)},\mathfrak{a}^{(K)}/h^{(K)})$ converges uniformly to $(v_{\mathrm{cts}},\alpha_{\mathrm{cts}})$.
\end{proof}



