\subsection{Dynamic programming for Markov chains} \label{app:dynamic-progamming}

For $h>0$ and $K\geq1$ let $\bar \cT:=\{0,h,\ldots,Kh\}$ and $\cT:=\bar\cT\setminus\{Kh\}$.
Consider a state process $(X_t,Y_t)_{t\in\bar\cT}$ taking values in a discrete set $\cX\times\cY$ where $|\cX|=d_1<\infty$ and $|\cY|=d_2<\infty$. Fix a map $\beta:\cT\times\cX\times\cY\to\Sigma^{d_2-1}$. For any control $\alpha:\cT\times\cX\times\cY\to\Sigma^{d_1-1}$, let $\P^\alpha$ denote the probability measure under which $(X,Y)$ is a Markov chain with $\P^\alpha$-transition probabilities
$$
\P^\alpha[(X_{t+h},Y_{t+h})=(x',y')\,|\,(X_t,Y_t)=(x,y)] = \alpha(t,x,y)(x')\beta(t,x,y)(y').
$$
Let $\ell:\cT\times\cX\times\cY\times\Sigma^{d_1-1}\to\R$ and $g:\cX\times\cY\to\R$ be given (cost) functions. Introduce the value function
$$
v(t,x,y)=\inf_{\alpha:\,\cT\times\cX\times\cY\to\Sigma^{d_1-1}} \E^\alpha\Bigl[\sum_{t\leq s < T} \ell(s,X_s,Y_s,\alpha(s,X_s,Y_s))+g(X_s,Y_s)\,|\,(X_t,Y_t)=(x,y)\Bigr].
$$
Clearly, for the problem at time $t$, the values of $\alpha$ at previous times $s<t$ are irrelevant.

Define the Hamiltonian
$$
\sH(t,x,y,\varphi,a) = \ell(t,x,y,a)+\sum_{(x',y')\in\cX\times\cY}a(x')\beta(t,x,y)(y')\varphi(x',y').
$$
The following result is standard, see for example \cite{FS}.

\begin{Lem}\label{lem:bellman}
Let $w:\bar\cT\times\cX\times\cY\to\R$ be given and assume the cost functions $\ell,g$ are continuous. Then $w=v$ if and only if $w$ solves the following dynamic programming equation, for $(t,x,y)\in\bar\cT\times\cX\times\cY$,
$$
\begin{cases}
w(t,x,y) = \underset{a\in\Sigma^{d_1-1}}{\inf}\ \sH(t,x,y,w(t+h),a), \\
w(T,x,y) = g(x,y).
\end{cases}
$$
Moreover, a control $\alpha:\cT\times\cX\times\cY\to\Sigma^{d_1-1}$ is optimal for any initial data $(t,x,y)$ if and only if 
$$
\alpha(t,x,y)\in\underset{a\in\Sigma^{d_1-1}}{\mathrm{arg\,min}} \ \sH(t,x,y,v(t+h),a),
$$
for all $(t,x,y)\in\cT\times\cX\times\cY$. 
\end{Lem}

\begin{Rmk}
There are no issues with measurability since $\cT\times\cX\times\cY$ is a discrete set. When the dynamics of $Y$ are deterministic, we may allow $\cY$ to be any set without changing the validity of Lemma \ref{lem:bellman}.
\end{Rmk}


\subsection{Proof of Lemma \ref{lem:convex-conjugates}} \label{app:conjugate-correspondence}



We follow the notation of \cite{FOMO}. Given a function $f:\R^d\to(-\infty,\infty]$, the domain of $f$ and of its subdifferential $\partial f$ are defined by
$$
\dom( f) := \{x\in\R^d: f(x)<\infty\}\quad \text{and}\quad \dom(\partial f) := \{x\in\R^d:\partial f(x)\neq\emptyset\}.
$$
Further, the indicator function of a set $C\subset\R^d$ is defined by 
$$
\delta_C:\R^d\to[0,\infty],\quad \delta_C(x):=
\begin{cases}
0 &x\in C,\\
\infty, &x\notin C.
\end{cases}
$$
Finally, the normal cone of the set $C$ is denote by $N_C$:
$$
N_C(x) := 
\begin{cases}
\{n\in\R^d : n\cdot(c-x)\leq 0,\ \forall c\in C\}, &x\in C,\\
\emptyset, &x\notin C.
\end{cases}
$$

\begin{proof}
\emph{Step 1.} We first show that $\eta:=f+\delta_C$ is a  closed, proper and strongly convex function. Clearly, $\eta$ is proper. Closedness of $\eta$ is obvious by closedness of $f$, for example using closedness of the sublevel sets \cite[Theorem 2.6]{FOMO}. Next, using $\partial\delta_C=N_C$, see \cite[Example 3.5]{FOMO}, and the the sum rule of subdifferential calculus, see \cite[Theorem 3.40]{FOMO}, we have
$$
\partial \eta(x) = \partial f(x)+ N_C(x),\quad x\in\R^d,
$$ 
where the right side is understood in the sense of Minkowski. Hence $\dom(\partial\eta)=\dom(\partial f)\cap \dom(\partial\delta_C)=\dom(\partial f)\cap C$.
Strong convexity means that for $(x,x')\in\dom(\partial \eta)\times\dom(\eta)$ and $\phi\in\partial \eta(x)$,
\be\label{eq:app-convex-i}
\eta(x')\geq \eta(x)+\phi\cdot(x'-x)+\gamma |x'-x|_2^2,
\ee
see \cite[Theorem 5.24]{FOMO}. Let such $(x,x',\phi)$ be given. By the above observation, there exists $g\in\partial f(x)$ and $n\in N_C(x)$ with $\phi=g+n$. Since $x,x'\in C$, by
\eqref{eq:lem-convex-conjugate},
\begin{align*}
\eta(x')=f(x')&\geq f(x)+ g\cdot(x'-x)+\gamma |x'-x|_p|x'-x|_q\\
&\geq f(x)+ g\cdot(x'-x)+\gamma |x'-x|_2^2=\eta(x)+ g\cdot(x'-x)+\gamma |x'-x|_2^2
\end{align*}
by H\"{o}lder's inequality.  Using $n\in N_C(x)$ and $x'\in C$, we have $n\cdot(x'-x)\leq 0$. Hence,
$$
\eta(x')\geq  \eta(x)+g\cdot(x'-x)+\gamma |x'-x|_2^2 \geq \eta(x)+ \phi\cdot(x'-x)+\gamma |x'-x|_2^2 ,
$$
establishing \eqref{eq:app-convex-i}.

\emph{Step 2.} Let $y_1,y_2\in\R^d$ be given and set $v_i:=\psi(y_i)$ for $i=1,2$. We claim that there exist $g_i\in\partial f(v_i)$ and $n_i\in N_C(v_i)$ with  $y_i=g_i+n_i$ for $i=1,2$.
Indeed, note that we may write
$$
\psi(y)=\underset{x\in C}{\mathrm{arg\,max}} \{y\cdot x-f(x)\}=\underset{x\in \R^d}{\mathrm{arg\,max}} \{y\cdot x-\eta(x)\},\quad y\in\R^d.
$$
By Step 1, $\psi$ is well-defined as a single valued function, see \cite[Theorem 5.25 (a)]{FOMO}. By the conjugate subgradient theorem \cite[Theorem 4.20]{FOMO}, $v_i=\nabla \eta^*(y_i)$ for $i=1,2$.
Then, by \cite[Corollary 4.21]{FOMO} and the sum rule again,
$$
y_i\in\partial \eta(v_i) = \partial f(v_i)+ N_C(v_i),\quad i=1,2.
$$
The claim follows.

\emph{Step 3.} Let $r=p,q$ and let $r'$ be its conjugate.  We  claim that
\be \label{eq:app-convex-ii}
|v_1-v_2|_r\leq \frac{1}{\gamma}|y_1-y_2|_r.
\ee
If $v_1=v_2$, then the claim follows, so that we may assume $w:=v_2-v_1\neq0$.
By \eqref{eq:lem-convex-conjugate},
$$
f(v_2) \geq f(v_1)+ g_1\cdot w+ \gamma |w|_r |w|_{r'}\quad \text{and}\quad 
f(v_1) \geq f(v_2) - g_2\cdot w + \gamma |w|_r |w|_{r'}.
$$
Since $v_1,v_2\in C$, we have that 
$$
n_1\cdot w= n_1\cdot(v_2-v_1)\leq 0,\quad 
- n_2\cdot w = n_2\cdot(v_1-v_2)\leq 0.
$$
Hence, 
$$
f(v_2) \geq f(v_1)+ y_1\cdot w + \gamma |w|_r |w|_{r'}\quad \text{and}\quad 
f(v_1) \geq f(v_2) - y_2\cdot w + \gamma |w|_r |w|_{r'}.
$$
Adding these inequalities gives
$$
(y_2-y_1)\cdot w\geq \gamma |w|_r |w|_{r'}.
$$
By H\"{o}lder's inequality,
$$
\gamma |w|_r |w|_{r'}\leq |y_2-y_1|_r|w|_{r'},
$$
which, using $w\neq 0$, implies \eqref{eq:app-convex-ii}.
\end{proof}
